Object.assign(window.__LB,{"12500": ["兼症", "脉之数象稍平，说明前之火热渐退，故痰血未清而右胁痛止；然左胁依然，是肝络余邪未净。数象稍平为火势得减之征，故原方兼和肝胃，以清余热、调肝胃而善后。", ["数"]], "12501": ["病机", "脉见芤象，芤主失血伤阴，中空如按葱管。季春突然失血盈碗、血色鲜红，火犯阳经，血络受伤，阳旺阴亏，阴不和谐，故芤脉外浮中空，正示暴失血后阴血骤亏而阳热未清之病机。", ["芤"]], "12502": ["病机", "脉象细涩，推之不甚宁静。细为阴血亏少，涩为气滞血瘀，故失血多紫、胸臆两胁兼痛、饮食难下、心中懊𢙐。气郁操劳伤阴，水不养肝，肝不藏血，气失摄纳，载血上行，兼脾胃不振，土弱不能生金。", ["细", "涩"]], "12503": ["病机", "脉象滑数而软，左部微弦。滑数主火燥气冲、血热妄行，软为肝阴不敛，弦属肝木偏旺。肝阴不敛则火燥气冲，血不归经，逆而上犯，初起为火，久则成怯，故脉见滑数而软、左部微弦。", ["滑", "数", "软", "弦"]], "12504": ["病机", "脉沉弦且数且滑，原文自释：沉为郁为气，数为火为热，滑为痰湿水。素有遗精、入房易泄、火升耳鸣，是肾阴亏而肝阳强；痰湿闭塞、胸次汩汩有声、咽喉不利、饮食不思，乃痰饮内郁化热。故脉沉弦主气郁，数主火热，滑主痰湿，合示阴虚阳强、痰热郁阻之机，香燥腻补皆难投。", ["沉", "弦", "数", "滑"]], "12505": ["病机", "脉来弦滑无力，弦主肝郁气逆，滑主痰饮，无力则示脾肾虚衰。原文谓肾虚真阳不旺、脾虚健运失常，虚寒积饮、清浊混淆，故见贲音腹胀、懊𢙐嘈杂、口流清涎、臂肋疼痛、胸次寒凝。脉之无力正应虚寒，弦滑应积饮郁气，主脾肾阳虚、饮气横逆之病机。", ["弦", "滑"]], "12506": ["病机", "脉来沉弦而滑，沉主里、弦主肝郁、滑主痰饮。原文谓肝郁中伤、积饮吐酸、痰如蛋清，食不能入、入则痛甚、两胁作胀，是肝气犯胃、肺肾俱伤。沉弦示郁在里，滑示饮痰内积，故主肝郁犯胃、痰饮中阻之病机；又值春令肝旺，故言非所宜。", ["沉", "弦", "滑"]], "12507": ["病机", "右脉沉弦、左脉沉滑，沉主里，弦主肝郁，滑主痰饮。原文谓肝气内郁、内有痰饮，症见痛吐清水、手足发冷，是郁气与饮邪内阻、阳气不达四末。虽言肝肾虽虚，却从乎中治，说明脉象重点在肝郁痰饮之中焦实象，故主气郁饮停、中焦不和之病机。", ["沉", "弦", "滑"]], "12508": ["病机", "右脉滑疾，左脉细涩。滑主痰湿，疾主热盛，细涩主阴血亏少。原文谓肝肾内亏、酒湿伤中、积饮酿热，故食后饱胀、气结嘈杂、呕恶清水。右滑疾示中焦湿痰化热，左细涩示肝肾阴血不足，合为虚实夹杂、湿饮酿热之病机，久延非宜。", ["滑", "疾", "细", "涩"]], "12509": ["病机", "脉见弦滑，弦主肝郁气滞，滑主痰湿饮邪。原文谓肝脾气胀、胃气积饮、湿热为患，病延日久，脾肾亦虚，防其气逆上冲。弦滑并见，正示肝脾气郁与胃中饮湿相合，久则化热，故主肝胃不和、痰饮湿热内蕴之病机，并提示冲逆之虞。", ["弦", "滑"]], "12510": ["病机", "脉弦兼滑，弦主肝郁、亦主饮，滑主痰饮。原文谓中阳不健、胃寒停饮，嗳气吐酸、食后尤甚、胸闷膈上停痰，苓桂术甘及姜术皆不应，年在冲龄而病延已久。弦滑示饮寒内停、气机不利，中阳不振则饮不化，故主胃寒停饮、中阳不健之病机，治从温肾建中。", ["弦", "滑"]], "12511": ["病机", "左脉沉弦、右脉沉滑，沉主里，弦主肝郁，滑主痰饮。原文谓嗳逆吐酸、胸闷呕食，肾虚胃关不建、脾虚健运失常，积痰积饮、作酸作呕。左沉弦应肝郁，右沉滑应脾胃痰饮，合示脾肾虚而饮痰内停、胃关不建之病机，故有外饮治脾、内饮治肾之说。", ["沉", "弦", "滑"]], "12512": ["病机", "脉来细涩，细为血少，涩为气滞，反映肝气横逆犯胃，胃中受伤。胃不下降则积饮吐酸，厥逆之气自下而上，中宫之气疲惫。此脉象说明肝气犯胃、胃失和降、积饮内停的病机，主不饥不纳、吐酸、厥逆等症。", ["细", "涩"]], "12513": ["病机", "两脉俱弦且滑且疾，弦主肝病，滑主痰饮，疾主热。思虑伤脾，积劳伤中，中伤停饮，呕吐清水，气不开畅，发甚胀痛。病起于肝，损及于中，吐水多甜，脾湿生热。脉象反映肝郁脾虚、痰饮内停、湿郁化热的病机。", ["弦", "滑", "疾"]], "12514": ["预后", "六进前方后，气渐平顺，呕吐未发，亦未痛胀，脉之弦滑稍平。弦滑为肝郁痰饮之脉，今稍平说明药后肝气渐舒、痰饮渐化，病情向愈。仍崇土渗湿，佐以和肝，巩固疗效。此段以脉象变化判断预后。", ["弦", "滑"]], "12515": ["病机", "脉来弦滑，弦主肝郁，滑主痰饮。中阳不健，肝胃不和，积寒积饮，吐食吐酸，间有苦水，木郁中伤。曲直作酸，木郁达之。舌苔焦黄，胸中有热，先拟左金合二陈加味。脉象反映肝胃不和、寒饮内积、郁而化热的病机。", ["弦", "滑"]], "12516": ["病机", "脉伏，肢冷，呕吐痰涎，皆痰饮阻塞胸中，阳气不能宣通所致。肝邪横逆，木来侮土，饮食入胃，生津生液者少，为火为痰者多。所服六君、金匮、资生，反觉横逆痰饮之象。脉伏非高年久病所宜，说明痰饮内闭、阳气不通的病机。", ["伏"]], "12517": ["病机", "脉象弦滑而数，按之无力。弦主肝郁，滑主痰，数主热，按之无力为中虚。气痰呃逆，中虚胃不和，肺气不降，痰郁作呃。呃由暴起，肺胃不和。脉象反映中虚痰郁、肺胃气逆、郁而化热的病机，主气痰呃逆。", ["弦", "滑", "数"]], "12518": ["病机", "右脉弦大，左象涩小。右脉候脾胃，弦大为肝气犯胃、胃气不和；左脉候肝肾，涩小为阴血不足。中宫失运，胃不冲和，气痰阻食。年近七旬，肺胃液枯。脉象反映肝胃不和、气痰阻食、阴液亏虚的病机。", ["弦", "大", "涩", "小"]], "12519": ["病机", "脉散，为气耗散不收之象。生脉散、二陈汤加枇杷叶、红糖，雪羹汤煎。脉散说明正气耗散，肺胃气阴两伤，痰饮内停。治以生脉散益气敛阴，二陈汤化痰，枇杷叶降气。脉散反映气阴耗散、痰饮内阻的病机。", ["散"]], "12520": ["病机", "脉象沉弦，沉主里，弦主肝郁气滞。原文谓“气郁动肝，中伤气逆”，肝气郁结则脉弦，气逆于中则食入作痛、嗳气不止。沉弦并见，说明病在里而肝木犯土，中州失运，故曰“非佳候也”。", ["沉", "弦"]], "12521": ["病机", "脉来沉小，沉主里，小主不足，故为“心肝肾三阴不足”。左脉犯弦，弦为肝木之象，木制中胃则清气不展、浊阴上潜，清浊混淆而成否象。脉沉小兼弦，示阴亏而肝旺，胃气受制，故不可轻视。", ["沉", "小", "弦"]], "12522": ["病机", "脉来沉小而涩，沉小为肝肾阴亏，涩为气机不利、阴血不足。左脉仍弦，弦主肝木制中胃，气失冲和，故“天地不泰，否象生矣”。阴亏而肝旺，香燥破气皆非所宜，当养肝肾以纳气机。", ["沉", "小", "涩", "弦"]], "12523": ["病机", "脉象虚弦，虚为正气不足，弦为肝木偏旺。原文谓“先天薄弱，水不养肝，肝虚犯胃”，肝虚而亢则犯胃，胃不冲和，气不下逮反逆于上，故食不能下。虚弦之脉示本虚标实，不宜香燥，当以乙癸同源。", ["虚", "弦"]], "12524": ["病机", "两脉俱弦，弦主肝气。原文谓“肾虚胃关不健，气逆中宫”，水不养肝则肝气中胃，食入作阻。舌绛苔燥、痰多汗多，示阴阳不化，津液受伤。弦脉为木制中胃之象，香燥殊属不宜，故拟十味温胆加味。", ["弦"]], "12525": ["病机", "脉见双弦，弦为肝木之象。原文谓“中宫失运，气痰作阻，胃失冲和”，木制中胃则饮食难下。年逾六旬，大便结燥，肺胃干槁，弦脉示肝木偏旺而胃土受克，病势深沉，故虑难奏捷。", ["弦"]], "12526": ["病机", "右脉弦大不平，右关候胃，弦大主肝木犯中宫，胃失冲和。原文谓“肝为刚脏，非柔不和”，肾不吸胃则胃关不健。弦大为木旺土虚之象，故前用金匮肾气、十味温胆未效，拟补中益气加减以奠安中州。", ["弦", "大"]], "12527": ["病机", "脉来弦大而数，按之无力。弦大为肝阳偏强，数为有热，按之无力则肾阴亏虚。原文谓“肾之阴亏，肝之阳强，犯中扰胃”，故胸满头眩、梦多内热、痞块横硬。弦大数而无力，示本虚标实，香燥难投，法宜乙癸同源。", ["弦", "大", "数"]], "12528": ["病机", "左脉沉弦为肝郁中伤，右脉沉滑为气逆痰阻，中宫失运则胃不冲和。年逾六旬五液先亏，脉沉弦滑示肝郁痰阻、胃气不和，久则阴液亏耗，气机升降失常，故防成关格。", ["沉", "弦", "滑"]], "12529": ["病机", "脉象双弦，弦为肝郁之象，思虑伤脾、郁怒伤肝，肝胃不和，中宫不畅，懊𢙐作痛。弦脉主肝郁气滞，病已多年，肝郁达之，火郁发之，拟补中益气调中养胃，防三阳结病。", ["弦"]], "12530": ["病机", "脉来沉滑，沉主气滞，滑主痰阻，气痰作阻则胸次不开，噫逆不爽。沉滑之脉示痰气交阻于胸肺，气化不利，故慎防堵塞，治以舒肺胃展气化，不致病结则吉。", ["沉", "滑"]], "12531": ["治法", "此段为方药组成，非脉象描述。生脉散加半夏、诃子肉、阿胶、荸荠、白蜜、姜汁，生脉散益气养阴，加半夏化痰降逆，诃子敛肺，阿胶滋阴，荸荠白蜜润燥，姜汁和胃，属治法范畴。", []], "12532": ["病机", "左脉弦为肝郁，右脉结为气滞，情怀抑郁，气勃于中，五志过极皆从火化。弦结并见，示肝郁气滞、火郁于内，木郁达之，必得抑郁开怀，否则防其结痹。", ["弦", "结"]], "12533": ["预后", "原文述开上实下、轻舒肺气后胸次渐开，天地交泰，否象自除。从心脾进步，候脉无结象再为易方。结脉主气滞，脉无结象示气机渐畅，故为预后转佳之征。", ["结"]], "12534": ["病机", "脉来沉小，沉主气滞，小主正虚，气胀拱痛、汩汩有声、二便不通，乃阴阳偏胜、气机壅塞所致。前哲以溲便不利为关、饮食不下为格，沉小之脉示正气不足而气结于内，病之逆从也。", ["沉", "小"]], "12535": ["病机", "两脉俱弦，弦为肝木之象，年逾六旬操劳烦心，中胃不和，食入痛阻，机关不利。木犯中胃，肝气横逆，胃失和降，故脉弦而症见食入痛阻，殊属不宜。", ["弦"]], "12536": ["治法", "脉散为气耗不收、肺气耗散之象，故用生脉散敛肺益气以固散越之气；二陈汤加竹二青、枇杷叶化痰降逆，针对痰浊内阻、肺失肃降。脉散提示正气耗散为本，痰浊为标，治当敛散固本兼化痰，标本兼顾。", ["散"]], "12537": ["治法", "脉散主肺气耗散不收，故仍以生脉散敛肺固气为底；加枳实炭、杏仁、枇杷叶，是痰气交阻、肺失宣降之象明显，需理气化痰、降逆止咳。脉散示本虚，痰阻示标实，故补敛与疏降并行，标本同治。", ["散"]], "12538": ["病机", "原文谓「六脉往来调达」，脉象平和无病，然「气分虚而肝脾不足」，病机在思虑伤神、中焦失运、肝气横逆、木来侮土；又兼胃中无火、命门火虚，釜底无薪。脉虽调达而症见虚损，属脉症合参、以症推机，故主肝脾两虚、命火不足之病机。", []], "12539": ["治法", "脉数大为热盛之象，热邪内炽故于方中加大古勇（乌犀角类）以清热凉血解毒。脉数主热，脉大主邪盛，提示热毒壅盛、血分受灼，故用犀角清心凉血，随脉数大而加，属据脉增药之治法。", ["数", "大"]], "12540": ["病机", "脉来沉数，沉主里、数主热，为肾水不足、不能上济心火，心阳上亢，心肾不交，子午不交故寤不成寐。脉沉数正合水亏火旺、心肾失交之机，故拟六味地黄丸加味滋肾填阴，以交心肾。", ["沉", "数"]], "12541": ["病机", "脉来动滑，按之则弦，动主惊、滑主痰、弦主郁，合参「不知喜怒，多疑多虑，心胆自怯」，是郁损心阴、胆虚痰扰之象。胆为中正之官，肝虚胆虚则胆冷无眠，惊伤心、恐伤肾，故脉动滑弦主心胆虚怯、痰郁不寐之病机。", ["动", "滑", "弦"]], "12542": ["病机", "原文未出脉名，以「胃不和则卧不安」立论，引《难经》二十七经络与𫏋络之说，谓厥气客于脏腑、卫气独留于阳，阳𫏋盛而不入于阴，故卧不安。所论在阴阳𫏋脉失交、卫气行阳不入阴之病机，非以脉断。", []], "12543": ["预后", "大渴引饮、舌裂唇焦，火灼金伤、津液枯涸，能食而脉软，属上消（膈消）。脉软为气液耗伤、脉道不充之象，与燥热伤津相应；能食示胃火尚存，然津枯脉软，正虚已露，故谨防发背，示预后当慎。", ["软"]], "12544": ["病机", "脉细数无力，细为阴血亏少，数为虚火内扰，无力则正气已衰。原文谓消渴止而痰嗽未平、胸腹仍胀，乃木火余威、火灼金伤；又经闭二月非胎候，大产后八脉有亏，故脉不任按。细数无力正合虚劳阴亏、虚火未敛之机，故断为虚劳之虑，宜静补真阴。", ["细", "数", "虚"]], "12545": ["病机", "脉来软数无力，软为阴液不充、脉道失养，数为五志化火内燔，无力则非实火。原文言五志过极俱从火化，火消万物故饥嘈善食，食不能多则三消未著。此脉正示阴亏火旺而正气已馁，故先荡涤积热、继补真阴，服泻心后火势已杀，宜补真阴以复其液。", ["软", "数", "虚"]], "12546": ["病机", "脉洪而数，洪为阳明胃火燔盛、气血涌溢，数为热邪急迫。原文谓胃火上炎，头中震痛如动脉之状、时作时止，正是火性冲动、随脉鼓击之象。洪数应胃热，动状言痛势搏动如脉动，故以寒以取之，直折阳明实火，火降则震痛自止。", ["洪", "数", "动"]], "12547": ["病机", "脉来细数，细为阳虚阴寒内盛、脉道不充，数为虚阳浮动之象。原文称素本阳虚、不时巅痛、容色萧然，乃阴翳上滞精明之府。细数非实热，是阳衰不能镇阴、虚阳上扰，故巅痛而色悴。法当益火之源，温补下焦以消阴翳，阴霾散则精明之府自清。", ["细", "数"]], "12548": ["病机", "脉来软数，软为阴亏脉道失刚，数为虚阳鼓动。原文谓宿疾阴亏、巅顶时痛、面色戴阳，戴阳乃虚阳浮越于上之征。软数并见，非实火燔灼，而是阴不恋阳、浮阳上扰清空。故暂以壮水之主，滋填真阴以摄浮阳，水足则阳自归宅，巅痛戴阳可减。", ["软", "数"]], "12549": ["病机", "脉来沉滑，沉主里主水饮内停，滑主痰湿壅盛。原文述头痛如破、痛甚作呕、食入则吐、胸满胁胀，正是湿痰盘踞中州、清气无由上达清虚之所，名曰痰厥头痛。沉滑应痰饮在里，故主以温中消饮，佐风药引清阳上行，痰去则痛呕胸满俱解。", ["沉", "滑"]], "12550": ["病机", "原文未识脉名，纯以症候立论。怒损肝阴，木郁化火，下耗肾水、上熏巅顶；妊三月奇脉受戕，少阴虚不能引巨阳腑气则巅痛，阳维为病苦寒热。此段重在析木火耗阴、奇经受累之病机，故拟逍遥散加味条达肝邪，治寒热巅痛之本，非凭脉断证。", []], "12551": ["病机", "脉滑而弦，滑主湿浊痰食内壅，弦主气机郁滞、木来克土。原文谓胃脘当心而痛、痛则水泻、舌有黄苔、不思谷食、胸闷不宽，明言积湿化热兼之停食，食聚中胃作楚。滑弦正应湿食交阻、肝胃不和之机，故痛而水泻、苔黄胸闷，治当化湿消食、疏达肝胃。", ["滑", "弦"]], "12552": ["病机", "脉沉弦而滑，沉主里，弦主痛主饮，滑主痰饮。胃病九载，痛则呕吐酸水，乃中阳不建，胃寒积饮，饮邪内停，气机不畅，故脉见沉弦而滑。此脉象反映寒饮内伏、胃气上逆之病机，与呕吐酸水、胃痛相应。", ["沉", "弦", "滑"]], "12553": ["预后", "脉来细数无力，细为阴血不足，数为虚热，无力为气虚。形神日羸，饮食日增，腹中汩汩有声，乃中虚积饮伏于肺经，虚劳之渐。细数无力示正气亏虚，虚热内扰，久病迁延，殊堪虑也，故属预后不良之象。", ["细", "数", "虚"]], "12554": ["病机", "原文未识脉名，然述脘痛按之则缓，可按为虚，证本木旺中虚，土不生金，风邪伏肺，气机不展。痛则不通，不可拘痛无补法之说，通者宣和也，补亦可通。此段论病机为肝木乘土、脾虚肺伏风邪，治以益水生木、培土生金。", []], "12555": ["预后", "原文未识脉名，但言细数之脉未起，脾肾双亏，伏风未尽。肾病当愈于冬，不愈者以冬水反涸，少生生之气。水冷金寒，肺有伏风，外风易感，同气相求。此段论病机为脾肾亏虚、伏风未净，预后欠佳，暂从温散。", []], "12556": ["兼症", "温散伏风后痰嗽竞止，但脉仍细数，脘痛依然。细数脉示阴血不足、虚热未清，虽痰嗽暂平，而中虚肝郁之本未复，故脘痛持续。此段以脉症并见，说明伏风虽减而正虚未复，兼症仍存，需续以丸方调治。", ["细", "数"]], "12557": ["病机", "脉仍细数，素本阴亏，木不条达，克制中胃，中伤络损，气失冲和。肝郁则痛，胃伤则呕。五六日更衣一次，阴液不濡，肠胃燥涩。细数脉主阴亏虚热，此段阐明病机为肝阴不足、胃燥气逆，治以润燥生阴、佐和中胃。", ["细", "数"]], "12558": ["病机", "脉之细数如初，饮食略进，形神渐振，痛吐渐稀。证本肝阴不敛，克制中胃，胃不冲和，传化失职，津凝为饮，液结成痰，中虚清气不展，阴霾上翳。细数脉示阴亏未复，病机为肝胃不和、痰饮内聚，故以甘缓为治。", ["细", "数"]], "12559": ["病机", "原文脉体和而又否者，指脉虽和缓而时有歇止，示病势苦深而少静定之力。肝阴不敛，肾阴不滋，健运失常，中伤饮聚，痛呕并见。肾损伤肺，肝病传脾。此段论病机为肝肾阴亏、脾肺两伤，治以补肾生阴、清金益肺。", []], "12560": ["治法", "原文仅列生脉散加白蜂蜜一方，脉散为前案所载脉象。散脉主气耗阴伤、肺气不收，故用生脉散敛肺生津，加白蜂蜜甘润缓急、补中润燥。此段以方测证，示脉散当以益气敛阴为治，非攻伐所宜。", ["散"]], "12561": ["病机", "脉散示正气耗散，体气素壮而病三月，脾胃已困，肝木独旺。原文言肝郁化火、火灼阴液为痰、痰凝气结、幻生实象，非食积可下。脉散正是气阴耗散之征，故弃攻下而用生脉散加金匮大半夏汤，柔肝和胃、益气养阴。", ["散"]], "12562": ["治法", "此段承前案，脉散为气阴耗散之象。生脉散加金匮大半夏汤，一以敛肺生津固其散，一以和胃降逆止呕。脉散而痛呕不食，示胃气已困、肝木乘之，故治法取益气养阴、柔肝和胃，不用攻下。", ["散"]], "12563": ["病机", "原文未识脉名，然言水不涵木、火灼液耗、两阳合明之气未能合洽，故上不入下不出、中脘痛呕。病机在肝肾阴虚、肝胃不和，故以壮水清金、两和肝胃为法，用生脉散合参蜜半夏汤、甘麦大枣汤，不治痛而痛自止。", []], "12564": ["治法", "脉散主气阴耗散，故用生脉散敛阴益气；参蜜半夏汤和胃降逆，甘麦大枣汤缓肝急、养心脾，加黄粟米、甘澜水益胃和中。全方紧扣脉散所主之气阴两伤、肝胃不和，以缓治取效，非峻补峻攻。", ["散"]], "12565": ["治法", "脉散为气阴耗散之征，生脉散益气敛阴以固其散，合六味地黄丸滋补肾阴、壮水涵木。脉散而用此，示病本在肾阴亏虚、气不收摄，故肺肾同治，使阴充气敛，散脉可复。", ["散"]], "12566": ["病机", "脉来软数已历多年，软为正气亏弱，数为郁热内扰。原文言木乘土位、升降失司、否而不泰，脘痛如刺、呕吐痰涎、不思饮食，正虚与郁热并见，故曰正气已亏、殊难奏捷，拟调气法中辅以扶正之品。", ["软", "数"]], "12567": ["预后", "原文未识脉名，然言服药呕平而饮食难进、脉尚未起，虑其来复。病延四载，阴虚于下、肾不养肝、木乘土位，痛呕几致汗脱，正气大伤。脉未起示胃气未复，故以丸代煎徐徐培养，属预后调治之论。", []], "12568": ["病机", "原文述脘痛怯寒、肢尖面目畏风，属气闭不能敷荣四末、上走清空，非真寒。服理气佐山栀后“数脉亦缓”，说明木乘土位、气郁化火之数脉因气畅火清而转缓，缓为胃气渐和之象，主病机由郁火伤阴转向中焦气机调畅，与呕平食纳相应。", ["缓"]], "12569": ["预后", "肝郁乘脾，中伤气痛，食少时吐，脉来细数无神。细为阴血不足，数为郁火内扰，无神则胃气衰败。木郁化火伤阴，脾土受克，久延有虚劳之虑，故以脉之细数无神示预后不良，非仅主病，强调戒怒以达木郁。", ["细", "数"]], "12570": ["病机", "胁痛属肝胆二经循胁肋。素忧劳，忧伤肺志、劳动心阳，心肺伤而肝胆郁。原文未出脉象，以病因推病机：心肺气虚致肝胆气郁，法当宣补，不可作东方气实宜疏论治，说明病机为虚郁夹杂，非单纯肝实。", []], "12571": ["主病", "暴怒伤肝，木火载血妄行清窍，胁肋胀痛，烦热脉洪。洪为火盛阳亢之象，肝火暴张，迫血上溢，故脉洪主东方实热。宜先泻肝实，兼助中央脾土，以杜木传脾之患，脉洪与烦热、胀痛相应。", ["洪"]], "12572": ["病机", "肝胆之脉循胁肋，忧思过度损心脾，气血不能流贯，厥少二经不利。心脉亦循胸出胁，脾伤故木不安，胁肋隐痛。原文未出脉象，以忧思伤脾、气血不贯释病机，主培补心脾以治本，非疏肝泻实。", []], "12573": ["病机", "腰为肾府，腰间空痛、按之稍缓、能直不能曲，病在督脉。原文未出脉象，以痛处空、按缓、活动受限辨为督脉空虚、肾精不充，非实邪阻滞。空痛属虚，按缓为虚象，主病在督脉，与肾虚腰痛相关。", []], "12574": ["病机", "腰为肾府，痛属肾虚。太阳脉夹脊抵腰，督带冲任要会于此。素耽酒色，肾阴本亏，潜伤四脉，痛屡发不瘳，行立不支、卧息稍缓。原文未出脉象，以“暴痛为实，久痛为虚”辨病机为肾虚久痛，在经属府、在脏属肾，拟方缓治。", []], "12575": ["病机", "脉象沉弦，气郁动肝，肝冲气胀已历多年。沉为气郁于里，弦为肝气横逆，故大腹小腹胀痛。形容憔悴、血不荣色，心脾营损，肝气横逆。沉弦脉主肝郁气滞、木横克土，与胀痛、憔悴相应，治养心脾以合肝胃。", ["沉", "弦"]], "12576": ["预后", "原文未识出具体脉名，仅言“脉神形色俱起”，即脉之神气、形色皆见起色，与“腹痛已痊，饮食已香，夜来寐安”相应，说明邪退正复、胃气渐振，故预后向安；然“不宜烦劳动怒”，提示脉虽起而正气未固，烦劳则伤气、怒则伤肝，须防复损。", []], "12577": ["病机", "原文未出脉名，以“遍身发冷，出汗不止”及“硬积跳动不消”述症。病机重在肾水亏、肝阳强、阴液不充，气积凝而成块；《素问》云“阳在外为阴之使，阴在内为阳之守”，气行血流如风行水动，阴亏则气积不化，故主养正消积、固气和阴，非攻伐可一时取效。", []], "12578": ["病机", "脉反浮洪，与“肾虚于下，木失敷荣，木乘土位，脾困于中，蕴生湿热，化生蛔虫”相应。浮洪为湿热虫积鼓动于外之象，非表实之浮洪；痛甚颊青唇赤为虫之验，故脉反浮洪主虫积湿热内郁、脏气虚而虫生之病机。", ["浮", "洪"]], "12579": ["其他", "原文未出脉象，仅言“但不知脉象如何耳”，以“呕吐泄泻，并有青黑砖瓦色”推测虫蛊化而未尽，或夹暑湿积食。虫化下行为顺、上行为逆，逆则脾阴大伤、正虚积不能化，故险；因脉未诊，不能悬揣，姑拟固正下积，静以待动。", []], "12580": ["病机", "脉来沉滑而疾，沉主里、滑主痰、疾主热，合为湿痰内郁化热生风之象。原文“脚面麻木，引延两手，右手食指跳动，井肩环跳俱痒，入暮潮热”，正是湿热生风、走窜经络之症，故当理太阴阳明，化湿热以杜风患。", ["沉", "滑", "疾"]], "12581": ["病机", "脉来滑疾，滑主湿、疾主热，为风湿郁于阳明、湿热郁结气化为火之征。原文“两腿两手脊筋作痛，寐来更甚，两耳作响”，乃湿热流注筋骨、上扰清窍所致，兼肝肾不足，故脉滑疾主湿热郁结、化火生风之病机。", ["滑", "疾"]], "12582": ["治法", "原文未出脉象，以“服药已效”为据，将木通减三分，加车前子、党参，并嘱每早服二妙丸。此属据效调方之法：减木通防渗利太过，加车前子助清利，党参扶正，二妙丸清湿热，示湿热未清而正须顾，故归治法。", []], "12583": ["病机", "脉来虚数而弦，虚主精血亏、数主热、弦主肝急，合为三阴内亏、湿热郁而不化、肝不荣筋之象。原文“腿瘦，胫弯，痛无宁息”“左腿形如鹤膝”，乃精血大亏、筋骨失养、湿热流注所致，故脉虚数而弦主下痿已成之病机。", ["虚", "数", "弦"]], "12584": ["病机", "脉来虚数，虚为肝肾两亏、气血不足，数为酒色内伤、阴不制阳而虚热内生。腰痛肋胀乃肝肾亏虚、筋脉失养；两腿麻木、步履无力为精血不能充养筋骨；口干便结、少腹作坠是阴亏液耗、中气下陷之象。脉症合参，病机为肝肾两亏、虚热内扰，谨防下痿。", ["虚", "数"]], "12585": ["病机", "原文未出脉名，以任脉为病立论。思虑烦劳损伤中气，亏及冲任，任虚失担任之职，冲虚血少不能荣筋。肝主筋与肾同源，前阴为宗筋之会，故睪丸下坠、不知痛痒而成𤻊疝。病机重在冲任亏虚、中气不足、筋脉失荣，故治法暂从中治。", []], "12586": ["病机", "脉来虚数少神，虚为脾肾双亏、八脉有损，数为阴不济火、虚阳浮动。任脉不足则睪丸下坠偏左，责之肝；肾气通耳，水不济火则耳鸣；火炽阴消则精滞。脉虚数少神正合脾肾两虚、虚火内扰之机，故以脾肾双补为主。", ["虚", "数"]], "12587": ["病机", "原文未出脉名，以神思过用、摇动相火立论。相火载血上行，下为遗泻；虚阳上越则眩晕戴阳；肝肾不足则不能久立久坐、眼花耳啸；二气不能流贯则胸背隐痛如裂；木乘土位则呕吐黄绿水。病机为心脾劳伤、相火妄动、肝肾亏虚、木乘土位。", []], "12588": ["病机", "脉左弦右软，左弦为肝阳强、郁怒所伤，气失调达；右软为气虚阴亏。心火湿热下注，火掩精关，故疼痛淋浊；湿伤气、热伤阴。脉象与症合参，病机为气虚阴亏、肝阳偏亢、湿热下注，治以补阴益气为先。", ["弦", "软"]], "12589": ["病机", "脉来数象，数为有热。湿热伤阴，溺管疼痛，血淋之后阴阳未复，水部有火，湿热有余，故热沥不尽。数脉主热，此热由湿热蕴结下焦、阴分受伤而来，非单纯虚热，故病机为湿热伤阴、余热未清。", ["数"]], "12590": ["病机", "脉来虚小，虚为精血不足，小为脉道不充。进补养肝肾与化湿热后溺管痛舒、血淋亦止，但四五日间仍有疼痛，脉虚小示肝肾精血未复、余气未尽。病机为肝肾亏虚、余湿未清，故以丸缓图、清养为妙。", ["虚", "小"]], "12591": ["病机", "脉来左大，左候肝肾，大为阴虚阳浮、虚火不敛。五进补阴益气后淋浊已止、阳举不痛、皮外不痒，但晨舌作干，脉左大，乃阴虚不能上潮、乙癸同源而水不涵木。病机为肝肾阴虚、虚阳偏亢，余症虽减而阴精未复。", ["大"]], "12592": ["病机", "脉来弦大，两尺不静，弦主肝郁，大主热盛，尺部不静为相火妄动。原文谓“湿热伤阴，心相不静，欲火凝结，湿郁不化”，说明湿热下注、灼伤阴液，心火与相火交煽，欲火凝结下焦，致五淋之疾。脉象反映湿热与虚火交织，故治当清心绝欲，分利湿热。", ["弦", "大"]], "12593": ["病机", "原文未识脉名，但言“脉不应指”，提示脉象模糊难寻，主里气空虚。膀胱气化无权，小便淋漓不畅，少腹胀满，舌绛口干，乃湿热伤阴、精不化气所致。年逾六旬，肾气已衰，肝失疏泄，肾失闭藏，州都无约，水泉无束，故补中兼开，慎用通利。", []], "12594": ["病机", "两脉俱弦，按之无力，弦为肝郁，无力为虚。年逾花甲，真阳虚衰，真阴亦伤，脾胃困顿，湿热内伤，脏不行腑，气化无权，致小溲不通。脉弦无力反映本虚标实，气化不及州都，故治当温补命肾、健运脾胃，以复气化。", ["弦"]], "12595": ["预后", "前案双弦脉，今“脉之双弦已和”，弦象渐退，说明肝郁得舒，气机调和。原文载“腑气已调，小溲畅行，脏已安适，面色已开，精神渐起”，脉症相符，示补命肾、健脾胃、升清降浊之法已效，故以丸剂徐徐调养，预后安吉。", ["弦"]], "12596": ["病机", "脉来软数无神，尺部尤甚。软为气虚，数为有热，无神为阴亏。原文谓“阴亏水不制火，火灼金伤”，肾液涸竭，州都失藏，膀胱津液不蓄，故小溲多而大便结。肺与大肠相表里，肺失治节，清浊太分，传送失职，寒热如疟，皆由阴亏火旺、金伤水涸所致。", ["软", "数"]], "12597": ["病机", "六脉细软，按之少神。细为阴血不足，软为气虚不运。原文谓“肝肾不充，气虚不健”，肾开窍于二阴，阴不足则气反虚而不运，故小溲勤而短，大便反结。脉象反映气阴两虚、肝肾亏乏，法宜益气以清阴，使气运复常。", ["细", "软"]], "12598": ["病机", "脉数且滑，数为热盛，滑为湿聚。原文直断“湿热伤阴，肠风便血”，湿热蕴结大肠，灼伤阴络，血渗肠间，故便血。数滑之脉正合湿热内盛之机，热迫血行，湿性黏滞，故病肠风。治当清利湿热、凉血止血。", ["数", "滑"]], "12599": ["病机", "脉来滑数，按之无力。滑主湿，数主热，无力为虚。便血多年，先紫后红，有血块，腹中隐痛，乃三阴内亏，湿热不化，阴络受伤。肝不藏血，脾不统血，气不摄血，渗入大肠而下。脉象示湿热标实而三阴本虚，故治当兼顾。", ["滑", "数"]], "12600": ["病机", "脉左紧右缓，紧主寒主痛，缓主脾弱。左紧为寒湿暴起、水气作泻之征，右缓为脾运不健之候。绕脐作痛、气虚作坠、痛则作泻，乃寒湿郁久化热，脾虚气陷，湿郁化热之象。脉象与腹痛、泄泻症候相应，故以温熨及香连归芍汤加减调治。", ["紧", "缓"]], "12601": ["病机", "六脉沉紧而涩，沉主里，紧主寒主痛，涩主气滞血瘀。面浮肢肿、腹胀胸闷、便溏尿少，乃风湿抑郁、食填太阴、脏寒生满，浊气逆上为䐜胀，清气下为泄泻。脉沉紧涩正合寒湿内郁、气机不畅之病机，久延则脾阴伤而及肾。", ["沉", "紧", "涩"]], "12602": ["病机", "脉来滑疾，滑主痰湿，疾主热盛。鼻涕稠浓腥味、鼻息不利、息肉脑空，乃痰热壅阻清窍。年甫十九而病延七载，脉滑疾示痰热内蕴、上实下虚，故拟清上实下主治，与鼻渊息肉之症相应。", ["滑", "疾"]], "12603": ["病机", "脉来软数而空，软为阴虚，数为火旺，空为精血不足。白睛赤缕、泪出眵凝，乃肾水下亏、木燥生火、风火相搏、肺金受制。脉软数空正合水亏火旺、阴液耗伤之机，故有赤脉贯瞳子之虑，治宜壮水生木、升阳散火。", ["软", "数", "空"]], "12604": ["病机", "原文未识脉名，以症测机。黑睛暗淡、瞳子无光、色兼蓝碧，为内障。少年嗜欲太过，水亏火升，木燥生风，风火交并，阴液潜消。脾虚则精气失司，肝虚血不归原，肾虚水不济火，故目暗无光。治宜壮水济火、补阴潜阳。", []], "12605": ["病机", "原文未识脉名，以症推机。耳内常鸣，因肾虚水不升、心火不降，壮火食气，清空失养；阴液下亏，脉络干涸，气血不畅。素多抑郁，水虚木燥，肝传脾，土不生金，肺病及肾，五内互克，展转沉疴。治宜静养舒怀，平补正心。", []], "12606": ["病机", "原文未识脉名，以症析机。齿痛上引太阳，眩晕左肢麻痹，因金水二脏素虚，金虚不平木，水虚不制火，肝阳内扰，阴火上升；兼酒酪肥甘，湿热蓄于肠胃，上壅经络。齿痛属阳明有余，眩晕麻痹属太少不足，故从阳明有余、少阴不足论治。", []], "12607": ["病机", "脉来软数无神，软为水亏，数为火旺，无神为五志乖违、精气耗伤。肾水不足，心火有余，水不济火，火性炎上，舌为之糜。脉象正合水亏火旺、心神不宁之机，故上病下取，壮水之主以制阳光，滋苗灌根。", ["软", "数"]], "12608": ["病机", "脉来软数无力，软为水亏不涵，数为火燥生风，无力则气不充脉。原文谓肾水不足、肝木失荣，木燥生火，火甚生风，风火交并上冒清空，故见声哑舌强、视听不聪。此脉正示水火不济、风火内扰之机，治宜益气壮水调中，冀水火既济。", ["软", "数", "虚"]], "12609": ["病机", "脉来滑数而空，滑主痰火，数主火盛，空则阴精亏耗、脉道不实。原文言诵读太过损脏气，五志过极从火化，火盛刑金则金溶不鸣，火旺水亏则舌机失用，故声哑语言难出。滑数而空正合火盛水亏、本伤机失之病机，故以铁笛加减。", ["滑", "数", "空"]], "12610": ["病机", "原文未出脉名，然述小便有血、带下五色、溲痛、夜寐不安、饮食不甘，明言心移热于小肠，湿热、肝火内郁。病延半载，极难奏效，是湿热肝火交郁、心热下移之机，虽无脉象可凭，症候已示郁火湿热内蕴、缠绵难解之势。", []], "12611": ["病机", "原文未识脉名，述带下频频、便艰溲黄不畅、腹有硬块、腰膝酸痛，断为阴亏阳不敛、虚寒之质、液络精气枯涸。此属肾阴亏耗、虚寒内结、气不收纳之机，故东垣谓连桂同功能交心肾、纳气归原，立方须切脉验证。", []], "12612": ["病机", "脉来弦动，弦为肝木偏旺，动则气郁不宁。原文谓汛闭年余、饮食日少、形体日羸，乃郁损心脾、木乘土位所致。心境不畅则肝不条达，脾失斡旋则气阻血滞，五志化火灼阴，血海渐涸，故月汛不以时下，必致血枯经闭，弦动正示郁损木乘之机。", ["弦", "动"]], "12613": ["病机", "左脉弦出寸口，弦主志意不伸、肝郁偏亢；脉络为之枯涩，涩主血少不荣。原文谓隐曲不伸、抑郁损心阴，阴虚血少，血不荣脾，脾伤不能为胃行津液，精血日衰，故经闭半载、腹中虚胀作痛、荣色憔悴。弦涩并见，正合郁损阴血、脉络枯涩之病机。", ["弦", "涩"]], "12614": ["预后", "脉来滑数而长，滑数主痰火壅盛，长主邪气有余、壅滞不散。原文谓经秘五载而饮食起居如故，无骨蒸痰嗽，乃任脉经坠滞塞，非血枯可比；手指肿紫、鼻衄、遍体疮痒，营气不从逆于肉里。滑数而长示邪实壅滞，故断有痈疽肿满之患，拟玉烛散。", ["滑", "数", "长"]], "12615": ["病机", "脉来沉细，沉主里、主阳虚，细主气血双亏。原文谓汛愆、胸腹相引而痛、手足逆冷、食生冷即发、腹中雷鸣，显是命火中阳不足以煦和五内、敷荣四末，由产后气血双亏、虚寒为祟。沉细正合火衰寒凝、气血不充之机，治宜益火之源以消阴翳。", ["沉", "细"]], "12616": ["病机", "脉来滑数，滑主湿郁痰滞，数主热。患者素月经不调，现晡热、巅疼、胫肿，经居三月，乃肝脾不和、胃不开畅、湿郁不行所致。湿郁化热，故脉滑数；热扰冲任，经闭不行；湿泛肌腠，胫肿；湿热上蒸，巅疼。治当理脾胃以观动静。", ["滑", "数"]], "12617": ["病机", "六脉沉涩，左部尤甚。沉主里，涩主血少气滞。素痛经，阴液本虚，今腹痛作泻、寒热呕吐胀闷，感邪夹湿，胃脘久伤，阳明阻塞，清浊升降失常，脾湿生痰，肝木侮土。脉沉涩示气血郁滞、湿阻血瘀，值经期防内外交病，恐生厥搐呃逆肢冷之险。", ["沉", "涩"]], "12618": ["病机", "左脉尚缓，右脉尚大。缓为胃气尚存，大为气血俱病之象。气郁填胸，气血俱病，五损之病，宜从中治。脉缓大而不弦细，说明脾胃未至大衰，故调饮食、适寒温、畅肝和脾，使脾胃健运，气血得复，方能有济。", ["缓", "大"]], "12619": ["病机", "脉见双弦无力，弦主肝病，无力为虚。经先期、少腹胀痛、呕哕，乃肝病善痛，肝传脾则胀，脾传胃则呕。饮食不甘，肝脾胃俱病。双弦无力示肝郁脾虚，木不疏土，故以丸缓治，调和肝脾。", ["弦", "无力"]], "12620": ["病机", "原文未识脉名。齿为骨之余，手足阳明脉循齿，冲脉为血海并阳明而行。阴虚无以配阳，水弱不能济火，经事先期，不时齿痛。此属阳明有余、少阴不足，虚火上炎，故齿痛；冲任失调，故经先期。当从阳明少阴论治。", []], "12621": ["病机", "原文未识脉名。气不卫外则寒，血失中营则热，经无约束则愆期。二气素虚，奇经复损，督任冲脉失养。任督如天之子午，冲脉从中直上。法当静补真阴，以充八脉，使气血调和，寒热自平，经期得准。", []], "12622": ["治法", "脉散，主气血耗散、真阴亏虚。生脉散加熟地黄、鱼鳔、山芋肉、山药、归身、左牡蛎、白莲花熬膏，乃补气敛阴、固摄奇经之法。脉散示元气不敛，故用生脉散敛肺气，加熟地、鱼鳔等填精补血，牡蛎潜阳，白莲花清敛，共奏静补真阴之功。", ["散"]], "12623": ["病机", "脉尚软数无神，软为阴亏，数为火盛，无神示胃气衰。崩漏虽止，巅顶犹痛，腹中䐃䐜胀。厥阴脉上巅络少腹，水不涵木，阴不敛阳，故巅痛腹胀。阴虚阳搏谓之崩，今脉软数无神，仍以壮水潜阳为主，冀血气各守其乡。", ["软", "数"]], "12624": ["治法", "原文以“脉散加生地”点明脉象为散，散脉主气血耗散、根本不同。方用乌贼骨丸合生脉散加生地、知母、玉竹、枣仁、牡蛎、归身、白芍，蜜丸缓图，是取生脉散敛散固脱、生地知母玉竹滋阴清热、枣仁牡蛎潜镇、归芍养血和营，针对脉散所主的气阴两伤、虚阳浮越之机，以敛散固本为治。", ["散"]], "12625": ["病机", "原文未出脉名，以“冲为血海，下司肝肾，上隶阳明”立论，指出经行饮冷致寒凝胞中、瘕聚十余年，症见经来脐下硬痛连腰，断为“任脉亦病”。其病机为寒饮内伤冲任，气血瘀结，病深及奇经，故曰“病深难于痊愈”，属积久入络、虚实夹杂之候。", []], "12626": ["病机", "原文未出脉名，述腹中血症大如复杯、脉络阻碍，致经血循环失度、经不及期而经前作痛。又因气郁伤肝、木乘土位而食减，悲哀伤肺、治节不行而胸次不畅、腰如束带，带脉亦伤。总属癥积阻络、肝郁脾弱、肺失治节、带脉受伤，年逾三旬未妊，必待经候平调方能孕育。", []], "12627": ["病机", "左脉涩、右脉弦，涩主血少瘀滞，弦主肝郁气结。原文谓“肝郁中伤，气血凝结，经不通行”，故见气胀腹痛、饮食不思。又引“二阳之病发心脾，有不得隐曲，女子不月”，说明心脾郁结、血源不充而经闭，其传为风消、息贲则属不治，点明病机由郁致损的转归。", ["涩", "弦"]], "12628": ["病机", "脉来滑数而空，滑数似为胎象，然“空”且“无坚硬之处”，故断“似有胎而不果腹，非停瘀可比”。素经事不调、日晡热、头痛时作时止，是阴亏血少、虚热内生；病在肝脾，木不调达而土运郁壅。故以崇土培木、宣补中州为法，从肝脾虚损、阴血不足立论。", ["滑", "数", "空"]], "12629": ["病机", "脉左涩右弦，左涩为肝血虚而凝，右弦为肝气郁而乘胃。原文谓“肝虚气血凝结”，经居四月似胎而不固，心悸脘痛、漏淋不已、气聚为瘕，是血虚气结、漏下成瘕之候。断“肝为起病之原，胃为传病之所”，故治以养心脾兼和肝胃，紧扣左涩右弦之虚郁并见。", ["涩", "弦"]], "12630": ["病机", "六脉细数而弦，细为血少，数为热，弦属肝胆。原文谓胎堕总在二三月，腹有硬块，缘“肝胆血热伤及心脾，太少二阴受恙”，气不充血而积块频频不化。故治法养正消积合养阴滋降，补天一之水、泻地二之火，以益母胜金丹加减，正对细数弦所主之阴虚血热、肝郁积结。", ["细", "数", "弦"]], "12631": ["预后", "原文未出脉名，仅言“脉不应指”，即脉象沉伏难寻、不应指下，为气血衰少、胎元失养之征，故断“胎元不长”。虽服回春丹安住，仍须胎长方为妙，并“防流滑”，说明脉不应指提示胎萎难长、有滑堕之虞，属预后判断，非一般病机叙述。", []], "12632": ["预后", "原文未识脉名，仅言“脉闭”，指脉气闭塞不通，与“肢冷烦躁、苔黄”并见，为霍乱转筋、阴阳乖隔、寒暑交争之危候。脉闭提示邪气内陷、气血不能外达，故断为“内陷之症”，预后不良，故曰“恐难挽回”。", []], "12633": ["病机", "原文未出脉名，以“经脉横解”言脉道松弛失常。素善饮致湿甚中虚，肠澼延绵、虚气下坠、升降失常，滞下多而胀不痛，属虚。气血交亏、湿郁化热，脉道失约故横解，主脾虚湿滞之肠澼。", []], "12634": ["预后", "呕吐清水、痛则欲绝，脉象细软而涩。细软为气血不足、中阳式微，涩则脉道不利、气滞血少。痛剧而脉反细软涩，正虚无力抗邪，脉症相失，故原文断“大非所宜”，属预后不良之象。", ["细", "软", "涩"]], "12635": ["病机", "脉来细软而滑，细软主正虚，滑主痰湿内蕴。原文谓肝郁夹湿、木旺土亏，胸闷作呕、气逆痰不升、间有寒热，乃肝虚湿患而非客感。脉细软应其正虚，滑应其湿痰，故治宜固正和中、调脾渗湿。", ["细", "软", "滑"]], "12636": ["病机", "脉细数无力，细为阴血不足，数为虚热，无力为正气亏虚。酒湿伤阴，心脾肾三阴不足，故手足振掉、巅眩目中生花。阴虚不能涵木、虚风内动，脉细数无力正合三阴亏虚之机，原文虑其有阴痱之患。", ["细", "数", "虚"]], "12637": ["病机", "脉软数无神，软主中虚湿胜，数主湿热化火，无神为正气衰惫。湿热蕴于中州，脾主四肢，故战栗动摇、两手动无宁息，火之象也。脉软数无神说明中虚而湿热化火、阴分受伤，故治宜培补心脾兼甘温壮水。", ["软", "数"]], "12638": ["预后", "六脉稍觉和缓，缓为胃气渐复、阴阳调和之象。原文谓服调气畅中后木荣土渐旺，故脉转和缓。扶阳固气、气和胃调，脉象由病转和，说明药证相合、正气渐复，照前煎方主治可望向愈。", ["缓"]], "12639": ["治法", "生脉散以人参、麦冬、五味组成，方名取“脉散”可敛之意。脉散为气阴耗散、脉气不敛之象，故用五味酸收、人参补气、麦冬养阴，使散越之脉气收敛复常。此处脉散点明制方之旨，属治法范畴。", ["散"]], "12640": ["治法", "此段为复脉汤（炙甘草汤）方药组成，未载脉象，故脉象要素为空。原文以炙甘草、桂枝、人参、麻仁、生地、阿胶、麦冬、姜枣组方，功在益气滋阴、通阳复脉，属治法类条文，非论脉主病，故不涉具体病机与症候对应。", []], "12641": ["病机", "原文「左脉弦数，右脉迟细」，左弦数主气滞寒停、寒热时作，兼感温邪则数；右迟细主中阳不足、寒湿内停。中脘痛连少腹，气滞寒停为本，温邪外袭为标，故脉左右异象，提示寒热错杂、气机不畅，治宜疏散畅中。", ["弦", "数", "迟", "细"]], "12642": ["病机", "原文「脉来弦大，按之微数」，弦主邪郁少阳，大示邪势盛，微数则化热之征。温邪三日，头重骨疼、苔厚腻尖红，为少阴阳明合病，邪郁肌表兼里热，故脉弦大而数，主病机为表里同病、邪热内蕴，治以柴葛解肌加白虎汤。", ["弦", "大", "数"]], "12643": ["预后", "原文「舌白脉伏，有内陷之虑」，脉伏为邪气内闭、正气不能外达之象。时感九朝而胸闷寒热、口渴腹痛，舌白示邪未化热，脉伏则正虚邪陷，故断为有内陷之虑，属预后判断，提示邪闭正馁、病势转危。", ["伏"]], "12644": ["病机", "原文「脉伏邪闭，肺胃皆病」，脉伏主邪气壅闭、气血不能外达。斑疹隐隐未透、喉疼、手足麻、头身痛而喘，皆邪闭肺胃、气机不通所致，故防呃喘之患。脉伏在此说明邪闭于内、正不能伸，属病机与预后并见之候。", ["伏"]], "12645": ["病机", "原文「脉息沉数，有化热之势」，沉主邪入于里，数主热。时邪八日，白㾦发、苔厚黄润、口干不渴，为热在血分、邪郁营分，故脉沉数而不浮，说明病机由表入里、化热入血，热灼营阴而口不渴。", ["沉", "数"]], "12646": ["预后", "原文「脉数少力」，数主热，少力示正气不足。更衣汗出而热未尽、舌强渐干，为邪热未清而津气已伤，脉数无力正是正虚邪恋之象，故云「邪势难解，仍防陷变」，属预后判断，提示正不胜邪、有内陷之虞。", ["数"]], "12647": ["病机", "原文「脉来浮数」，浮主邪在表，数主热。时疫四朝，壮热无汗、胸闷舌白、身痛腹泻呕恶，斑尚未透，脉浮数说明邪郁肌表、热势鸱张而未能外透；兼妊娠两月，故须顾及胎元，主病机为表邪郁热、透达不畅。", ["浮", "数"]], "12648": ["病机", "脉数主热，舌绛为热入营血之征。妊娠足月感邪，邪郁阳明，壮热口渴、身疼烦躁，皆阳明热盛之象。热甚则伤胎，故脉数舌绛提示热势鸱张，有内陷生变之虞，当谨防气急谵语等热扰神明之候。", ["数"]], "12649": ["病机", "原文仅言“脉亦较和”，属纯描述，故脉象要素为空。此段述复诊时内热稍缓、苔化、脉和，但脘痞格拒、腑气不通、日晡热甚，说明阳明之滞未下，火邪劫烁阴津，虑阴津消亡而发陷症，故议甘寒泄热、和中润下。", []], "12650": ["病机", "脉来细数，细主阴亏，数主热，合而示脏阴、营液俱亏。恙势虽退、滞气已出胃腑为佳兆，但脉仍细数，说明阴液未复，虚热内扰。若腑气宣通、阴气来复，则脉象可望转和，方保无虞，故此为病机之论。", ["细", "数"]], "12651": ["病机", "脉浮洪，浮主邪在表，洪主热盛，合见发热面红、口甜痰黏、神迷不语、牙关紧闭，显系痰热蒙闭心窍、邪扰神明之候。始因惊恐，复感秋邪，痰热内闭，故先用至宝丹等清心开窍，脉浮洪正应痰热壅盛之病机。", ["浮", "洪"]], "12652": ["病机", "脉数而濡，数主热，濡主虚、主湿，合示阴虚夹痰、腠理空疏。病后复劳感邪，寒去热蒸，舌苔白厚，有汗热不清，溺赤似痛，乃虚邪蕴于脾肺两经，阴虚痰恋于络。脉数濡正应虚热夹痰之机，故议养阴化痰。", ["数", "濡"]], "12653": ["病机", "脉象弦滑，弦主郁、主饮，滑主痰、主热，合示伏邪化热、痰热内郁。疫邪两候阴分已虚，热糊不清，口渴多饮，舌黑底绛，谵语不宁，痰咯不爽，皆正虚邪实、热郁伤阴之象。脉弦滑正应痰热郁伏之病机，故暂拟养阴化痰。", ["弦", "滑"]], "12654": ["病机", "脉来弦滑且不宁静，弦主少阳郁滞，滑主痰热内蕴，示伏邪未化，少阳阳明皆不清楚。时感十朝，寒热虽止而胸胃不开、精神萎顿、五更作呕、溲黄内热，皆邪恋未解之征。脉不宁静说明邪势未衰，未可言愈，故以不生风波为吉。", ["弦", "滑"]], "12655": ["病机", "脉来沉弦而数，沉者郁也，弦主肝郁，数主化火，右脉滑疾则主湿热生痰。肝郁不畅，气化为火，少阳不宁，厥阴之气鼓动火炎于上，上盛则下耗，故见心肾两亏。此脉象紧扣“郁”“火”“痰”三端，示上盛下虚之病机，治当养心肾以和厥阴。", ["沉", "弦", "数", "滑"]], "12656": ["病机", "原文未明脉象，仅言“脉尚未静”，指脉未和缓，示湿热久郁伤阴，余邪未清。少壮湿热壅郁，溃脓虽愈而阴分已伤，故脉不静；治以补不足、泻有余，即扶正祛邪并行，使湿热去而阴复，脉乃静。", []], "12657": ["病机", "原文谓“脉不安静”，未言具体脉形，示气血失和。精不化气则阳运不健，气不生阴则阴亏，故脉躁动不静；阴中之阳不运，阳腑之气不调，舌裂为气分热、阴中湿之征。治以猪胆丸清降，轻可去实。", []], "12658": ["病机", "脉沉而滑，沉主里、滑主痰湿，知湿热郁于肺，肺气受伤，肾气不纳，湿热上冲而喘咳不止。沉滑为湿热内郁之象，非表邪；肺肾同病，故清火化痰以平冲逆，防气冲厥逆。", ["沉", "滑"]], "12659": ["病机", "脉来滑数无神，滑主湿、数主热，无神为胃气衰。脾为湿热薰蒸，中央土色外越而发黄；火盛灼金，迫血妄行，血去阴伤，宗气上浮而虚里穴动。滑数无神示湿热蓄血、中土久亏，故从蓄血发黄论治。", ["滑", "数"]], "12660": ["预后", "原文“脉渺如丝”即微细欲绝之象，主正气衰败。胎前水肿，气化无权，腹大如箕，腰围倍昔，喘鸣肩息，脉微细如丝，示脾肾阳衰、水湿泛滥而正气不支，攻水则堤防不固，故曰“生气残矣”，预后不良。", ["微", "细"]], "12661": ["预后", "脉来沉数无神，沉主里、数主热，无神为胃气将败。脾虚不能制水，肾虚不能纳水，肺虚不能行水，水泛皮肤则肿、流注脏腑则胀。沉数无神示本虚标实、正气已衰，故症势危如朝露，勉拟肾气丸塞因塞用。", ["沉", "数"]], "12662": ["病机", "脉见两弦，弦为肝木之象，两弦则肝脾俱病。疟邪留肝成痞，气郁伤中，肝脾两伤，胸腹痞胀、腿肿、二便不畅，皆木来乘土、清浊混淆所致。弦脉主木旺克土，势成中满，故用升清降浊、小温中丸，防其成中满。", ["弦"]], "12663": ["病机", "脉来弦数无神，弦为木乘土位，数为郁热，无神为胃气受伤。健运失常，清阳不展，阴霾上翳，故食入反吐、肿胀频仍。弦数无神示肝郁化热而脾土已虚，久延有三阳结病之虑，故治先实脾，归脾、六君加减。", ["弦", "数"]], "12664": ["病机", "脉滑数，滑主痰湿，数主热，提示脾虚生湿、湿渍于肺、化热之机。原文谓“脾虚生湿，渍之于肺，有喘满之虑”，正合滑数之象。年高肺脾肾三经皆病，湿不运行，清浊混淆，气化无权，故见肿、胀、二便不利，滑数脉反映湿郁化热，暂以苏杏轻通化湿化热。", ["滑", "数"]], "12665": ["预后", "脉静肢和，指脉象由躁转静、四肢温和，为邪退正复之佳兆。原文述前有“脉躁指黑，鼻生烟煤”之危象，经四君子加附子粳米汤后“呕未尽止，稍能纳谷，脉静肢和，黑气已退”，说明虚气上逆、浊饮上升之势已减，预后转好，但胸膺痹窒，仍属虚气未全平。", ["静"]], "12666": ["病机", "本段未识脉名，以症析机。外强中干，气火并于上；素善茶成茶饮，咳嗽痰多、呕吐清水；服肾气而口鼻出血，服半夏饮而耳鸣不寐；操劳郁闷，相火素旺，木火易兴，心肾不交，阴不敛阳，气有升无降，故耳闭不聪。总属气火升逆、痰饮内伏、心肾不交之病机。", []], "12667": ["病机", "脉弦兼滑，弦主饮、主肝，滑主痰，合之提示痰饮内停、肝脾失调。原文谓“水停心下为饮”，风寒伤外、七情伤内，茶饮伤气耗阴，思虑伤肝脾，惊恐伤心肾，故咳嗽痰饮举发。脉弦滑正应饮邪与气郁，治宜先标后本，先解感冒，再治饮兼解七情。", ["弦", "滑"]], "12668": ["病机", "左脉弦涩，右来濡滑，按不应指。弦涩主肝郁寒凝，濡滑主湿饮内停。原文谓“寒能生湿，湿能生饮”，肾病带动肝胃，胸乡气满胀痛、扬扬有声，清浊混淆，脏病带动六腑。脉象反映寒湿生饮、肝脾肾同病、气机壅滞之病机，故内饮治肾、外饮治脾。", ["弦", "涩", "濡", "滑"]], "12669": ["病机", "脉来滑疾，两尺不静。滑主痰湿，疾主热、主急，尺部不静提示下焦肾气不纳。原文谓哮喘十载，郁湿、郁热、郁痰、伏风为患，肺为娇脏不耐邪侵，痰湿郁热伏风交阻，故脉滑疾而尺不静，极难脱体，反映痰热伏风内蕴、肺肾同病之机。", ["滑", "疾"]], "12670": ["病机", "本段未识脉名，以症论机。咳甚哮复萌，痰多气阻，额上有汗。原文谓“肺气不降，肾气不纳，中气不能树定中枢，肺虚不能主扬诸气”，指出肺肾不交、中气失枢之病机。治以调中养肾、纳气归窟、子母相生，正针对肺虚不能降、肾虚不能纳之气逆痰阻。", []], "12671": ["病机", "脉弦兼滑，弦主风、主饮，滑主痰，合之提示伏风痰饮内蕴。原文谓“肺有伏风，为外风所引，液败为痰，痰成窠臼”，故髫年宿哮，秋冬举发，发则气促痰鸣不得卧。脉弦滑正应风痰胶结、肺失宣降之病机，虑难脱体，先以小青龙加减外解内化。", ["弦", "滑"]], "12672": ["病机", "脉软提示正气不足，外强中干。患者形丰却脉软，说明脾肺气虚，土不生金，而风痰蟠踞清空，每遇秋冬即发哮喘。补则风痰愈结，散则正气不支，邪正不两立，攻补两难，故脉软反映本虚标实、正虚邪恋之病机。", ["软"]], "12673": ["病机", "脉滑而数，滑主痰，数主热，说明肺蕴风痰郁热，清肃不行。痰热内郁则哮喘痰鸣，舌燥唇干溲混，巅疼食减。此脉象直接对应痰热壅肺之病机，故宜先清燥救肺，但苦寒未宜常服，恐戕生发之气。", ["滑", "数"]], "12674": ["病机", "原文未识脉名，但述肺为至娇之脏，寒客肺俞，因循怠治，致邪郁肺络，变生哮喘，发则不能安卧。此段强调外邪失治入络，肺气壅郁，病机由表入里，久延成终身之累，非脉象所主。", []], "12675": ["病机", "脉来沉滑而疾，沉主里，滑主痰，疾主热，说明风伏肺络，郁而化热，正气肾气俱亏，不能化邪外达。童年哮喘延廿余载，久病及肾，本虚标实，故取效一时之品非常服，当和养肺胃，兼顾太阴湿土。", ["沉", "滑", "疾"]], "12676": ["病机", "脉沉喘咳浮肿，沉主里主水，说明秋风化燥伤肺，气壅不降，水谷汤饮之湿痹阻经隧，化为痰涎。鼻黑唇舌赤、渴饮、少腹胀急、大便不爽，皆湿壅三焦、肺气不降之候，故法宜开太阳之里，若补以温燥则三焦闭塞危矣。", ["沉"]], "12677": ["病机", "原文未识脉名，述肾水下亏，子窃母气，致肺虚于下，风邪易袭，肺中津液不归正化，凝结为痰。喉间作痒，金水枯燥，发时宣风豁痰治标，平复后温养真阴治本，病机为肾虚肺弱、标风本虚。", []], "12678": ["预后", "脉来细数兼弦，细主阴亏，数主虚热，弦主气逆，说明肾虚气不归根，肺损气无所附，孤阳浮泛。喘鸣肩息，动劳益甚，脉证相符，诚为剥极之候，预后不良，故列于预后。", ["细", "数", "弦"]], "12679": ["病机", "脉洪而滑，洪主热盛，滑主痰，说明痰火内郁，脏腑受伤，气逆喘促。洪滑之脉直接反映痰火壅盛于内，上焦清肃失司，故法当清肃上焦，以解痰火之郁。", ["洪", "滑"]], "12680": ["病机", "脉象六阴按之虚数不静，两尺尤甚，虚为阴亏，数为阳浮，尺甚则肾虚不纳。原文谓“水不配火，肾不纳气，气不归原”，虚数不静正是肾阴亏虚、虚阳上浮之象，故见走泄、精神不振，主心肾两亏、水火不济之病机。", ["虚", "数"]], "12681": ["病机", "脉洪豁，按之不鼓，洪为火象，不鼓则虚，乃水亏于下、火越于上之格阳证。原文谓“格阳形证已著”，久咳音哑喉痛、口干不欲饮冷，皆虚火上浮之候，故脉洪豁不鼓主格阳病机，非实火可泻。", ["洪"]], "12682": ["病机", "脉双弦，弦主饮主痛，双弦则饮邪偏盛。原文谓“中虚积饮，土败金伤，水湿浸淫”，久咳痰涎盈碗、食减神羸、苔白厚，皆脾虚水湿不化、饮邪渍肺之候，故双弦脉主中虚积饮、三焦不治之病机。", ["弦"]], "12683": ["病机", "脉来细数兼弦，细为阴亏，数为虚热，弦为木旺。原文谓“脏阴营液俱亏，木击金鸣，下损于上”，精血不归正化悉变为痰，故咳嗽痰多、喉痛音哑、寒热汗泄，脉象正合阴亏木旺、虚损已成之病机。", ["细", "数", "弦"]], "12684": ["预后", "脉来细数无神，细为阴损，数为虚热，无神则胃气衰败。原文谓“肾损于下，肺损于上，上下交损”，痰嗽失血、内热便泻、形神日羸，脉证相合，虚损之势已著，故主预后不良，谨防喉痛音哑、吐食大汗之变。", ["细", "数"]], "12685": ["预后", "脉数形羸，数为虚火内炽，形羸为肌肉消脱。原文谓“肺肾两亏，三焦俱伤”，鸡鸣咳嗽、痰多食少、吐血气促，脉数而形羸，正虚劳阴亏火旺之候，故脉数形羸主虚劳已著，预后堪虑。", ["数"]], "12686": ["兼症", "前诊弦数之脉已缓，缓为胃气渐和、火势渐平之象。原文谓结喉肿痛全消，而每朝咳嗽痰多、声音不振、午后心烦，总属阴亏水不济火，脉缓示标热已减，兼症未除，故主阴亏未复、虚火渐敛之兼症。", ["缓"]], "12687": ["病机", "脉仍微数，微为虚，数为热，示余热未清。原文谓喉肿痛全消、逆气已平、饮食进、夜寐安，惟平明痰嗽犹存，脉仍微数，乃肺胃伤而未复、阴亏未充之象，故主肺胃虚热未清之病机，仍顾其本。", ["数"]], "12688": ["病机", "原文先言「脉滑而数，风伤肺」，又言「痰郁肺胃，夏令脉洪数」，复诊「脉沉滑而数」。滑主痰，数主火，沉主郁，洪应夏令气化。四脉合参，知邪伏化热生痰，郁于肺胃，故以苏杏甘桔开提、蒌夏理肺胃，不治咳而咳自解，不治痰而痰自出，正合脉象所示痰火郁结之机。", ["滑", "数", "洪", "沉"]], "12689": ["预后", "原文「脉细如丝，按之如无」，细为阴血亏少、脉道不充，按之如无则正气衰微，故断为「中伤肺损」。肺损不能言语，语则喘咳不宁，足肿身热，乃肺病及脾肾、水气不化之候。脉微至此，谨防大汗而阴阳脱离，是示预后险恶，非泛言虚损。", ["细"]], "12690": ["病机", "「脉来沉滑而疾」，沉主里、主郁，滑主痰，疾主热盛。合之「湿痰蕴结肺胃之间」，痰嗽气促、胸次不爽，皆痰阻气机之症。面色戴阳为肾亏虚阳上浮，子盗母气言肾不纳而累及肺。脉沉滑而疾，正痰湿郁热内蕴、本虚标实之象，故暂以茯苓饮加减。", ["沉", "滑", "疾"]], "12691": ["病机", "「脉来沉涩，推之则移」，沉主里、主郁，涩主血少、主痰滞。原文断为「痰郁阴亏，肺气不展」，久嗽不已则三焦俱伤。推之则移，言脉虽沉涩而非牢结不移，示郁滞中尚有流动之机。火令司权，火旺刑金，故慎防音哑，治以舒肺胃展气机。", ["沉", "涩"]], "12692": ["病机", "「脉来滑数」，滑主痰，数主热，故曰「肺有郁痰」。痰郁化热，肺失清肃，则喘咳不安；热耗气阴，则口干神倦；痰湿困脾，则食减。恙久体虚而不受补，是虚实夹杂、攻补两难之局，脉滑数正是痰热未清之据，故原文叹极难奏效。", ["滑", "数"]], "12693": ["病机", "「脉象濡弱」，濡主湿、主气虚，弱主不足。咳嗽痰多而见濡弱，知非实痰，乃「气虚痰郁，脾受湿侵」。脾虚不能运化水湿，湿渍于肺，肺失宣降而咳痰。脉濡弱正脾肺气虚、湿浊内停之征，病本在脾，故原文以脾受湿侵、渍之于肺立论。", ["濡", "弱"]], "12694": ["病机", "「脉来弦数」，弦主肝、主阴虚阳亢，数主火。久咳痰多、喉肿痛痒、耳鸣头眩、寤而不寐，皆阴亏火旺之症。原文断为「阴亏已极，水不上升，心火刑金，清肃不降」，弦数正是水亏火炎、肝心之火上刑肺金之象，故虑难奏捷。", ["弦", "数"]], "12695": ["病机", "服地黄汤六剂后诸恙安，而头目不清、寐易醒、喉痛止痒存、微咳食少，「脉沉弦数」。沉主里，弦主肝郁阴亏，数主火。前诊阴亏火旺，今脉仍沉弦数，知阴未全复、虚火未清，故喉痒微咳、夜寐易醒；食少则脾运未健，是余热未靖、本虚未复之候。", ["沉", "弦", "数"]], "12696": ["病机", "脉沉而小，按之颇不流利，沉主里、小主虚，不流利为痰湿内阻之象。原文言外寒内热，久嗽不已，喉间淫淫作痒即咳，夜来少寐，胸满食减，正合沉小不流利之脉：外寒束表、内热郁肺，痰湿阻滞气机，故胸满食减；久嗽伤及肺阴，故夜寐不安。脉证相参，病机为寒热错杂、痰阻肺络。", ["沉", "小"]], "12697": ["病机", "本段未出脉象，专论肺咳传变之理。原文言肺合皮毛主咳，皮毛受邪从其合而客于肺，又饮食入胃从脾脉上至于肺则肺寒，内外合邪则为肺咳。乘春则肝先受之，肺咳不已传于他脏，际发陈之令必先传肝，故治法以和解中佐肃降。所论为外邪内寒合而客肺、循经传脏的病机演变。", []], "12698": ["病机", "本段未出脉象，以脏腑气血立论。原文言肝藏诸经之血、肺司百脉之气，水弱肝虚则火载血上；肺虚不能下荫于肾，肾虚子窃母气，下损于上而痰嗽带血。相火内寄于肝，君火动则相火随之，心有所思则梦遗。指出精血易损、草木难应，宜屏除尘绊、恬淡虚无，使水升火降。病机为肝肾阴虚、君相火动、气火上逆。", []], "12699": ["预后", "脉来细数无神，细为阴亏、数为火动，无神则胃气已衰。原文言金水亏残、龙雷震荡，载血妄行上溢清窍，木扣金鸣为咳，肾虚水泛为痰，营卫乖违而往来寒热。数载屡发不已，虚劳之势已著，故脉细数无神主阴损及阳、虚劳难复。勉拟甘温壮水以制阳光，不可过服沉寒戕生气，示预后堪虑。", ["细", "数"]], "12700": ["病机", "脉来滑数，滑主痰、数主热，为痰热内蕴之象。原文言幼年失血，今春举发，血止而痰嗽不已、平明尤甚，痰多食少，阴伤子盗母气。滑数之脉正应痰热壅肺、阴虚火动：痰多故滑，火动故数，平明咳甚乃阴虚阳动之时。溽暑流行，谨防狂吐，示痰热与暑邪相合易致再血。", ["滑", "数"]], "12701": ["病机", "脉来弦数，弦为肝旺、数为火盛。原文言失血多年，早暮咳呛、交节尤甚，三四日一发而血涌，胸次作胀、食少运迟，巅疼身热。弦数之脉主阴虚火旺、肝火上炎：火载血上则狂吐，木击金鸣则咳呛，肝阳上扰则巅疼身热。故戒思虑劳心，当静则生阴，以制肝火。", ["弦", "数"]], "12702": ["病机", "脉来弦数，弦主肝郁、数主火郁。原文引《经》大怒则形气绝而血菀于上，郁结化火、火载血上，狂吐后咳嗽不已，十余日必遗泄。弦数为水不养肝、肝火偏亢之征：木击金鸣则咳，肝虚侮胃则纳差，火扰精室则遗泄。病机为肝郁化火、阴虚火动、木火刑金。", ["弦", "数"]], "12703": ["预后", "脉来停止，即结代之类，主脏气衰败、气血不能接续。原文言年逾六旬、二气就衰，冬客风冷咳嗽绵延，今春痰带红紫、夜不能寐、身痛气急、动劳尤甚、饮食少思、足跗浮肿蔓延于上，阴分大亏兼有湿热。脉停止而土败金残，生气大损，故虑难奏捷，拟补肾开胃，胃开则吉，属危候预后。", ["停", "止"]], "12704": ["病机", "脉来弦洪且大且数，弦为肝旺，洪大为气火升腾，数为热。失血后脉宜缓静，今反洪大，是血不养肝、肝不藏血，气冲血逆而妄行。痰嗽带血、痰少血多，正合木火刑金、血随气上之机。时令肝木用事，气火上腾，故慎防喘汗血脱、金残肺痿。", ["弦", "洪", "大", "数"]], "12705": ["病机", "脉软为正虚之象。素有失血，心营肺卫俱伤，又复感寒邪，表散未解，身热憎寒、短气自汗、痰嗽带血、声嘶，皆正虚邪实之候。脉软说明气血不足而邪仍留恋，虚体挟邪，攻补两难，故称棘手。", ["软"]], "12706": ["病机", "脉软主虚。阴虚咳血，龙雷内炽，五液交枯，虚热往来、渴不欲饮、自汗不收、痰嗽带血、面色戴阳、声嘶，皆阴亏阳浮之象。脉软示胃气尚存，然虚火内炽，复感寒邪则变生难治，故用药滋金水之源以迎夏至一阴来复。", ["软"]], "12707": ["病机", "脉来细数无神，细为阴亏，数为虚热，无神则胃气衰败。水亏不能生木，木燥生火，载血上行，木击金鸣为咳，肾水上泛为痰。舌绛咽干、蒸热夜甚，皆阴虚阳乘之候。脉证相合，虚劳已著，木火上升之令慎防狂吐。", ["细", "数"]], "12708": ["病机", "脉强而硬、弦而软、弦细而急、缓则平、急则甚，反映心脾受病、水虚木燥、木火载血上行。木击金鸣为咳，木乘土位津凝成痰，营卫失守则寒热。脉急则病进，缓则稍安，说明脏气盛衰决定痰血转化，病魔辗转沉痼。", ["强", "硬", "弦", "软"]], "12709": ["病机", "脉来浮数兼弦，浮为邪在肺络，数为火灼，弦为木旺。久咳肺络受伤，血随咳上，鲜瘀不一。症本阴亏，水不济火，火灼金伤，木击金鸣，清气不降，络有停瘀。脉示虚中夹实，故未宜骤补，当先荡尽停瘀再议培养。", ["浮", "数", "弦"]], "12710": ["病机", "脉来虚数，虚为气阴不足，数为虚热。伤风致损，必是肾虚，咳嗽痰多、微带鲜血、耳鸣盗汗、脱肛不收，皆下损于上、肺肾两亏之候。虚数之脉说明真阴亏耗而虚阳浮动，故宜远房帏、独居静养，待真阴来复方能有济。", ["虚", "数"]], "12711": ["预后", "脉带数象，数为火旺阴伤。吐血甚多鲜红，痰嗽益甚，夜不能寐，身痛肢木，血不荣筋，面色带黄，皆阳盛水不济火、肾虚窃气于金、精损移枯于肺之候。阴亏火旺而脉数，尤非所宜，示预后不良，故列于所宜之外。", ["数"]], "12712": ["病机", "脉来虚弦，虚为三阴不足、酒湿内伤，弦为肝木失养、火载血上。下有漏疡耗阴，痰嗽食少便溏示脾土亦弱，舌绛有槽、左胁动气乃阴虚火动、肝气不宁之征。虚弦并见，正合阴亏而肝阳偏亢、本虚标实之机，故法宜清补，仍防狂吐。", ["虚", "弦"]], "12713": ["病机", "暴怒伤阴，肝阳化火，火载血上行而咳喘带红。脉来弦劲，弦为肝脉，劲则火盛气逆、毫无柔和之象，正是肝阳化火、气血上冲之征。此脉主肝火迫血、肺失清降之病机，与咳喘带红相应，故法当清以降之，折其上炎之势。", ["弦", "劲"]], "12714": ["预后", "失血后咳不止、气微促、食减，脉细数。细为阴血亏少，数为火动，由盛怒伤肾、水不济火、火载血上、木击金鸣，肾不纳肺不降故气促。原文谓前贤以诸端为危证殊属不宜，是辨此脉此症虽重而未必尽危，故列预后，拟方多酌高明。", ["细", "数"]], "12715": ["病机", "右脉弦而洪，左脉弦大而芤。弦为肝逆，洪大为气火亢盛，芤则阴血内亏、血不归络。水不养肝、肝不藏血，气逆血上冲犯阳明，致有狂吐。原文以逆流之水喻逆行之血，脉不安静、波涛不定，正示气逆血涌、防其壅逆之机。", ["弦", "洪", "大", "芤"]], "12716": ["误治", "左关右尺洪而有力，余部细数。洪为龙雷鼓动、阳火独狂，细数为阴分素亏。本属阴虚火动之咳血，误视头风以辛温升散，致阳火独狂、冲破血脉，咳吐两昼夜不止。犀角地黄未能制及龙雷，故主大剂育阴兼苦降，使龙藏泽中、雷潜海底。", ["洪", "细", "数"]], "12717": ["病机", "本段未识脉名，纯论病机。女子以肝为先天，情怀不遂则气动于中，气旺阴伤，络血不注冲脉而月事稀少；肝无血养则化气化火，血络不安而胁胀胁痛，离经之血由肺胃出为咯呕夹红。汗为心液，液耗阴伤故精神萎顿、肢面虚浮、下体气坠，木旺土衰、清阳下陷所致。", []], "12718": ["预后", "长夏失血，肺肾两伤，金水交亏，龙雷震荡，故神情恍惚、语言错乱、云门卒痛、竟夕无眠。脉象虚弦，虚为阴液耗损、神魄失守，弦为肝阳不潜、龙雷上僭。虚弦见于失血阴亏之体，正示本虚阳浮、殊难奏捷，故主壮水制阳，且谓火令司权远涉非宜。", ["虚", "弦"]], "12719": ["预后", "暮春风温上受，发热后吐血鲜红，四月血又涌来不止，胸胁引痛，系肝胃不和。胃为多血之腑，肝为藏血之脏，肝阴少藏则胃血上涌。脉来洪滑，洪为火盛气腾，滑为血热痰壅，见于失血涌吐之际，火势方张而血未宁，故原文谓非其所宜，示其堪虑。", ["洪", "滑"]], "12720": ["病机", "原文未出脉名，以“督脉少运”言病机。真武汤温阳利水后血上痛除，惟夹脊膂筋酸楚、左手大拇指乍寒乍热，是督脉阳气运行不畅、血行未复之象；仍防血逆上涌，说明阳虚水泛虽减而血随气逆之势未全平，故以脉象缺如而重病机转归。", []], "12721": ["预后", "原文未出脉，以“肺绝胃败之候”定预后。足阳明脉环唇挟口，鼻准属脾、鼻孔属肺而胃统之；产后口鼻起黑色而衄，乃瘀血入肺、肺绝胃败，属危候。急拟二味参苏加附子，是回阳救逆、益气摄血之法，示病机为瘀血上逆、肺胃气败。", []], "12722": ["病机", "脉来细弱无神，细为阴血不足，弱为气衰，无神则真阴亏耗、根本已虚。操劳过度、素耽酒色致真阴不足，水不制火，冲任血动上溢于鼻为外衄。此脉不任苦寒，故曰未可作火热论治，法当培补真阴，脉症合参以虚为本。", ["细", "弱"]], "12723": ["病机", "脉来软数无神，软为阴精不充、脉道不实，数为虚阳鼓动，无神则根本衰惫。素阴精不足，疟后阴液大伤，阴亏阳亢，水不济火，逼血妄行出于肺窍。火性炎上、血随气行，故有喘促痉厥之虑；治宜壮水之主，与六淫在经邪热壅盛者不同。", ["软", "数"]], "12724": ["病机", "脉来浮滑，浮为阳浮于上，滑为痰火内盛，合阴虚火动之齿衄消渴。神倦气怯、大便坚、小便数，是阳明有余、少阴不足之象；火动于胃则齿衄，消烁津液则便坚溺数。故从阳明有余、少阴不足论治，清胃火兼滋肾阴。", ["浮", "滑"]], "12725": ["病机", "原文未出脉，明言“并无火证火脉可据”，以齿衄动摇辨为肾阴不固、虚火上升。齿为骨之所络，肾主骨，阴不固则虚火上炎而齿动血溢；既无实火脉证，故宜壮水以制之，不可妄投苦寒，示脉证合参、以虚为本之旨。", []], "12726": ["病机", "原文未出脉，专论血之生成与出血归属。中焦受气取汁变化而赤为血，主于心，散脉内者随冲任行经络，散脉外者充肌腠。吐血衄血、牙龈齿缝出血皆经络之血涌而上决；牙宣属胃热炽甚，牙不宣而出血者乃阴竭于下、阳亢于上，龙雷之火冲激胃络，即钱氏骨漏。", []], "12727": ["预后", "气口脉浮大，上引结喉之人迎，浮为阳浮不敛，大为邪盛正衰。饮食不入为格、二便不出为关，阴阳偏乘、尺寸复溢；吐逆不食、便旬日不解、小便癃闭，是阳明胃液就枯、化火金伤、治节不行，幽门失启闭、气化不及州都，乃三阳将结之危疴。", ["浮", "大"]], "12728": ["治法", "原文仅言“生脉散加生地山药萸肉牛乳”，脉象写作“脉散”，指脉气耗散不收。散脉主气阴两伤、元气不敛，故用生脉散敛气生津，加生地、山药、萸肉、牛乳以滋阴填精。此段以方测证，示脉散为气阴耗散之象，治当敛补。", ["散"]], "12729": ["病机", "原文言“气痰作阻，食不能下，关津不利，便不能解”，脉散为气阴耗散、中州失运之象。高年气阴两亏，升降失司，痰气交阻，故食不得下、便不得解。散脉主正气涣散，与“中州失运，升降失司”相应，乃高年逆候。", ["散"]], "12730": ["病机", "原文未识脉名，但言“人迎脉盛，病在阳明”，人迎候阳明。酒入于胃，肝浮胆横，木乘土位，火灼金伤，致州都气化失常、传道失职，大便结如羊粪、小便不利如淋。诸逆冲上皆属于火，体战心惊亦火象。人迎脉盛示阳明腑火上炎，少阴脏水耗竭，三阳转结而成隔。", []], "12731": ["预后", "原文言“弦数之脉亦缓”，此前弦数主火郁土困、痰凝气阻，服药十三剂后食入阻碍平、呕吐止、胸痛减，脉转缓，示中阳渐复、郁火渐平。然云门穴痛未除，乃营液欲竭，终属不宜，故缓脉虽为向愈之兆，预后仍当警惕营阴耗竭。", ["缓"]], "12732": ["主病", "脉来洪数，洪主气分热盛，数主火郁。原文言“气郁填胸，汨汨有声，隐隐作痛，食不能入，二便俱阻”，此气郁化火，火逆冲上，阴阳偏胜而成关格。洪数为实热之象，与食入不入、小便不出之关格相应，故虑难奏捷。", ["洪", "数"]], "12733": ["病机", "脉弦主肝郁，左关沉涩主肝血瘀滞。原文言“郁怒伤肝，忧思伤脾，肝脾荣损，气亘于中，贲门不利，食入作梗，痰多，干物难下”，此肝郁脾伤、气滞血瘀、痰阻贲门，故脉弦而左关沉涩，为中枯之症，治拟养胃和中兼柔肝木。", ["弦", "涩"]], "12734": ["病机", "左脉结涩主气血瘀滞、心气不续，右脉弦小主肝郁脾弱。原文论噎膈为神思之病，七情所致，五脏空虚、气无所主，食不能进。结涩示气血结滞，弦小示肝郁土衰，与“利锁名缰”“酒沉色困”致五脏空虚、气无所主相应，故当内观静养。", ["结", "涩", "弦", "小"]], "12735": ["病机", "脉沉弦而滑，沉主气郁于里，弦主肝郁，滑主痰阻。原文言“怒则气上，思则气结”，肝郁中伤，胃失冲和，气血作阻，机关不利，故呃逆不容饮食，三阳结也。沉弦滑正合肝郁气结、痰气血交阻之机，治当怡情开怀。", ["沉", "弦", "滑"]], "12736": ["病机", "脉来两关弦细，弦为肝旺，细为阴伤，两关候肝脾，弦细并见，是肝气横逆而犯胃土。肝气犯胃，气机壅滞，故胸咽梗痛有如刀割；久则胃气不降，膈间不通，势成隔疾。此脉象揭示肝强脾弱、气结阴亏之病机，主噎膈之病。", ["弦", "细"]], "12737": ["病机", "脉象虚数，虚为正气不足，数为阴分有热。原文言肥气日久脾土亏虚，脾为生化之源，源竭则肝木愈旺，上刑肺金而咳呛咯血，热移于脑则鼻流浊涕。此虚数脉正是脾胃之阴伤、气血不运而成虚转实之象，故宜养脾胃之阴、调营分，不可用气药破积。", ["虚", "数"]], "12738": ["病机", "左部细弦，右部兼滑。细弦为肝阴不足、肝阳偏亢，滑为痰浊内结。原文述疟后肝邪未尽，邪与痰滞互结络中，渐觉硬大，土衰木旺，肝积散大硬及腹右。左脉细弦应肝积，右滑应痰滞，每遇烦劳气逆耳鸣，乃肝阳上僭、心肾荣亏之候，法当扶土抑木、和荣泄浊。", ["细", "弦", "滑"]], "12739": ["病机", "脉来沉涩软弱，沉为气陷，涩为营亏血滞，软弱为正气已伤。原文言郁怒伤肝，肝营亏虚，气从中逆，浊痰上升，胸胁痛胀走窜，继则脐下关元气海梗痛，二便不爽，清不升浊不降，常似喘促。此脉示肝木横逆、正气已伤，故拟养血柔肝、和中化浊。", ["沉", "涩", "软", "弱"]], "12740": ["病机", "左脉沉弦不静，右脉滑数。沉弦不静为肝郁不畅、气不条达，滑数为痰热内蕴。原文言气聚为瘕，任脉为病，肝脉为患，肝脾皆伤，月事不调，常多白带。左脉应肝，沉弦示郁结；右脉应脾，滑数示痰热。此脉象说明肝郁气滞、痰热互结、肝脾两伤之病机。", ["沉", "弦", "滑", "数"]], "12741": ["病机", "脉来细数，细为阳气衰微，数为阴寒内结、虚阳外浮之象。原文言胃阳衰微，阴寒凝结，嗳噫吞酸，胸痞不饥不食，明言非食停中脘，乃阳气不升作滞，是阴翳也。此细数脉非实热，乃阳衰阴凝、升降失司之病机，故议理中主治，温中阳以散阴翳。", ["细", "数"]], "12742": ["病机", "脉体弦多胃少，弦为肝木之象，胃少谓缺乏和缓胃气。原文言思虑伤脾，脾虚不运，痞塞不开，不饥不食。脾虚则肝木乘之，故脉弦多而胃气不足。此脉象说明脾虚肝乘、中焦升降不利之病机，主痞塞之病，法当补肾温脾，用塞因塞用之法。", ["弦"]], "12743": ["病机", "脉形缓弱，缓为脾土本脉，弱为正气不足。原文言饮食起居均失其宜，脾胃伤而不运，一月以来不饥不食，胸次痞满，升降失司，否而不泰。缓弱脉正是脾胃虚弱、中气不足之象，说明脾肾两虚、清阳不展之病机，故法当补脾肾、运中州、展清阳。", ["缓", "弱"]], "12744": ["病机", "脉来小𫘝于迟，小为阳微，𫘝为郁热，迟则主寒，合而观之乃寒滞中焦、脾阳不运之象。寒邪壅遏，阳气不得宣通，故脉虽小而兼𫘝，似数非数，正合嗳腐吞酸、胸痞不食之候。法当温暖中土，即针对此寒滞阳郁之机。", ["小", "𫘝", "迟"]], "12745": ["病机", "脉来缓弱，缓为胃气不足，弱为阳气衰微，合之则中阳不健、气痞于中。原文明言胸脘无胀痛邪滞等证，但不饥不食而自疑若满，容色萧然，正是虚痞而非实滞。缓弱之脉印证中阳不振，故非消导所宜，而用塞因塞用法。", ["缓", "弱"]], "12746": ["病机", "脉来胃少弦多，胃少则中土之气不足，弦多则肝木偏旺。原文谓火素不足、中州不振，胃虚卫外不护则寒，脾虚营失内守则热，此非外感。弦多正是木旺乘土之征，故先培土崇木，治中汤加附子以益火生土。", ["弦"]], "12747": ["预后", "脉来细数，细为阴血不足，数为虚阳浮动。胸次痞塞按之有形如伏梁，饮食减少，素来木不条达，中虚清气不展，离光不振而阴霾上翳。高年见此细数之脉，正虚邪结，故原文断为非佳兆，属预后不良之候。", ["细", "数"]], "12748": ["病机", "脉来细数兼弦，细为元阴不足，数为郁热，弦为木旺。原文谓先天元阴不足，水不涵木，木乘土位，健运失常，积瘀壅塞膀胱，州都气化失常而小便如淋。细数弦正合水不涵木、木乘土位之病机，非单纯淋证可比。", ["细", "数", "弦"]], "12749": ["病机", "脉来胃少弦多，胃少示胃阳未复，弦多示肝木尚旺。复诊饮食较进、呕吐亦退，然饥不欲食、食入即胀，得后与气则快然如衰，正是胃阳未复、脾阴亦亏而木气乘之。弦多胃少印证土虚木亢，故以归脾汤加减培土柔肝。", ["弦"]], "12750": ["病机", "脉来沉弦涩兼，沉为病在里，弦为肝木偏旺，涩为精血不足、气血滞涩。原文谓先天精亏、产育过多，水枯木燥，肝木取汲于脾胃，久则反为木克。沉弦涩正合水不涵木、扶土柔肝之治，强调胃气无损则诸病不生。", ["沉", "弦", "涩"]], "12751": ["病机", "脉左寸关数，左寸关候心肝，数为有热。原文谓抑郁不舒，土衰木团，食入即呕，乃肝木乘土、郁而化热之象。左寸关数正应肝木乘土之急，故急宜清降，以折肝木怒盛之气，使土不受克而呕止。", ["数"]], "12752": ["病机", "六部脉皆弦劲，弦为肝木太过，劲则胃气受戕、中土失和。肝木横逆犯胃，胃气上逆不降，故朝食暮吐；脾失健运、腐熟无权，故完谷不化。此脉示木旺克土、胃虚气逆之机，主反胃呕吐之病。", ["弦", "劲"]], "12753": ["病机", "脉弦主肝郁，数主热。原文言劳郁多怒伤肝、思虑伤脾，脾损胃亏，饮食少进，湿蒸热郁而生虫。弦为木旺，数为郁热，故脉来弦数，主蛔厥作痛、呕泻俱出，为肝脾失调、湿热生虫之病机。", ["弦", "数"]], "12754": ["病机", "脉弦细少神，细为血少，少神为气衰，弦则木郁乘土。原文谓气血已衰、脾胃两败，故食少而胸腹作痛、有时呕涎。弦细少神正合气血两亏、肝木犯脾之机，主脾胃虚败、营血不足之证。", ["弦", "细"]], "12755": ["病机", "原文谓虫生于脏气虚，肾虚于下、木乘土位、湿蕴生热化虫。脉反浮洪，浮为虚阳外越，洪为热象，与肾虚于下之本不符，故曰反。痛甚颜青唇赤为虫验。此脉示本虚标热、虚阳上浮之机，主虫痛之病。", ["浮", "洪"]], "12756": ["病机", "脉沉细，沉主里、细主虚，是中虚气滞、形神皆衰之象。原文述胃虚肝乘、纳食则呕、脘中板硬如拳，兼半产早劳、平素多郁伤脾。沉细正合中气亏虚、肝木横逆之机，主胃虚气滞、棘手重症。", ["沉", "细"]], "12757": ["病机", "脉沉弦，沉为气郁于里，弦为肝木受伤。原文谓气郁肝伤、土为木侮，肝病善痛已历多年，形容憔悴、血不华色，乃心脾营损。沉弦示肝郁乘脾、营血亏耗之机，主久痛虚损之证，治当养心脾以和肝胃。", ["沉", "弦"]], "12758": ["预后", "原文未识脉名，仅言脉形神色俱起。腹痛已平、饮食已进、夜来安寐，皆邪退正复之征；脉形神色俱起，示胃气渐复、气血渐和，故为向愈之候。惟嘱不宜烦劳动怒，防肝木再扰、旧病复作，属预后顺境。", []], "12759": ["预后", "脉细数无神，细为阴血亏少，数为虚热内扰，无神则胃气衰败。原文谓肝郁乘脾、中伤气痛、食入则吐，久延有虚劳之虑。细数无神正合木郁土伤、气血日耗之机，故预后堪忧，戒悲怒方能济。", ["细", "数"]], "12760": ["预后", "原文述脘痛甚则发寒、肢尖面目畏风，属气闭不能营敷四末、上走清空，非真虚。服理气佐山栀清火后，呕吐平、饮食进，脉由数转缓。数主郁火，缓为胃气和调之象，故脉数亦缓示木乘土位、化火伤阴之势已退，中气渐复，为病势向愈之凭。", ["数", "缓"]], "12761": ["病机", "原文未出脉名，以脘痛按之则缓辨为虚，引《经》脾络布胸中、肺脉环循胃口，断为木旺中虚、土不生金、风伏于肺、气机不展。痛则不通，故主张宣和展气、益水生木、培土生金，补亦可通，不拘肝无补法之说。", []], "12762": ["病机", "原文言细数之脉未起，脘痛时作时止、痰嗽增减，断为肺胃双亏、伏风未尽。细为阴血不足，数为虚热，脉未起即正气未复。冬水反涸、水冷金寒，肺有伏风则外风易感，故暂从温散，必使里气融和方济。", ["细", "数"]], "12763": ["病机", "脉仍细数，素本阴亏，木不条达而克制中胃，中伤络损、气失冲和，肝郁则痛、胃伤则呕。五六日一更衣，阴液不濡、肠胃燥结可知。细数主阴亏液少，香燥开胃非所宜，当润燥生阴、佐和中胃。", ["细", "数"]], "12764": ["病机", "诊脉细数如初，虽饮食略进、形神渐振、痛呕举发渐稀，而脉象未改，知阴亏不敛、克制中胃之本未除。胃不冲和则传化失职，津凝为饮、液结成痰，中虚清阳不展、阴霾上翳，故以甘缓为妥协，仍用丸方缓调。", ["细", "数"]], "12765": ["病机", "原文言脉体和而又否者，谓脉虽略见和缓而仍有痞隔不畅之意，故断病势深而少静定之力。肝阴不敛、肾阴不滋，健运失常、中伤饮聚，痛呕屡发。阴无骤补之法，故拟补肾生阴为主、清金益肺辅之，取虚则补母、金水相生之义。", []], "12766": ["病机", "脉散主气液耗散。原文谓气虚不能传送、液耗不能濡润，气主煦之、血主濡之，肾司二阴、胃司九窍，肝阳木旺而中伤转输失职，血燥液干，故大便不解、痛呕不舒、通夕不寐。拟生脉散行肺金治节、滋肾水源流，冀清肃令行而肝胃自治。", ["散"]], "12767": ["治法", "承上段脉散，于生脉散中加白蜜。脉散为气液耗散之象，白蜜甘润，助濡润血燥液干、补中而缓肝，使肺金治节得行、肾水源头得滋。此属因脉施治之加减法，非另立新证，故归治法。", ["散"]], "12768": ["病机", "脉散示正气耗散，脾胃已困，肝阳独旺。肝郁化火，火灼阴液为痰，痰凝气结，幻生实象，非食积可下。痛呕不食、便闭，皆由肝胃不和、气逆液耗所致，故以生脉散合大半夏汤柔肝和胃。", ["散"]], "12769": ["病机", "脉散主水不济火，火灼液耗，两阳合明之气未和。上不入、下不出、中脘呕逆，皆由肝胃失和、津液亏耗。治宜壮水清金、两和肝胃，使肝和胃开，纳谷便解，痛呕自止。", ["散"]], "12770": ["治法", "脉散为精气耗散之象，故用六味合生脉散加黑枣、黄粟米、蜜甘澜水煎，以滋水养阴、收敛散气。此段重在示治法，以甘润补益之品复其耗散之正气。", ["散"]], "12771": ["治法", "脉散主正气耗散，故以六味合生脉散加牛膝，既滋肾敛散，又引血下行。此段示治法，针对散脉所主之精血亏耗、气不收敛，以补益固摄为要。", ["散"]], "12772": ["病机", "冲任并损，脾肾两亏，精血不足养心脾，肝虚不能为胃行津液，凝滞成痰，随气流行，乘虚犯心脾之络，故胃脘当心而痛、攻冲背膂、膨胀有声。气血少则凝涩不通，痛无急暴之势，惟连绵不已，虚病可知。", []], "12773": ["病机", "营血渐生则宿痰渐化，脉络通调则痛止。近又复作，因精血未充满，痰饮犹存，蔽障经中，气为之阻。痛时小溲如淋，乃痰隔中州、升降失司之据，故养阴宣络以治其本。", []], "12774": ["病机", "脉滑而弦，滑主痰饮内停，弦主气机郁滞。胃脘当心而痛、痛则水泻、舌有黄苔、胸次不舒、不思饮食，皆积食停饮阻隔，阴阳升降失司所致。故以和气平胃、展清阳主治。", ["滑", "弦"]], "12775": ["病机", "脉来弦数，弦为肝郁，数为火旺。五志不伸，肝火犯中，土为木侮，故大痛不止、胸次气郁如焚、贯膈冲咽、痰塞咽喉、午后尤甚。治以苦泄辛开，先泻心法调之。", ["弦", "数"]], "12776": ["病机", "脉象沉潜无力，沉主里、无力为虚，反映中阳不健、胃寒积饮。胃痛八载、呕吐吞酸，乃寒饮内停、胃气上逆所致。脉沉无力正合中阳不足、水饮内停之病机，故拟苓桂术甘汤温阳化饮。", ["沉", "虚"]], "12777": ["病机", "脉滑数，滑主痰湿积滞，数主热。小腹痛如针刺、大便坚、溲混赤，为火郁下焦、灼伤血络、腑气不通之象。脉滑数正合火郁下焦、痰热内结之病机，法宜清利。", ["滑", "数"]], "12778": ["病机", "脉滑数，滑主痰，数主热。脘痛横连胁肋、昼轻夜重，为痰郁化热、阻滞气机。经日不食、气馁于中，故不胜涌吐，暂以失笑散加味。脉滑数正合痰郁化热之病机。", ["滑", "数"]], "12779": ["病机", "脉来洪数而弦，洪数主火热亢盛，弦主痛、主厥阴。少腹痛连胸背、呕吐、溲赤便黄，乃二阳之火蕴结不开，值经血适来，热搏血结，厥阴脉络壅滞。诸逆冲上皆属于火，故食不得入。脉洪数弦正合火热搏血之病机。", ["洪", "数", "弦"]], "12780": ["病机", "原文未识脉名。昨药后症减，惟少腹胀痛、夜寐不安，乃水不制火、阳跷脉盛、阴不上承、心阳独旺，血为热搏结不行，经水适来，热入血室。病机为阴虚火旺、热入血室，故议壮水补阴为急，行血逐瘀为缓。", []], "12781": ["病机", "脉来软数，软主正气亏虚，数主虚热。木乘土位、升降失司，脘痛如刺、呕吐痰涎、不思食，已历多年，正气已亏。脉软数正合正虚邪恋、气阴两伤之病机，故殊难奏效，拟补气法加补正品。", ["软", "数"]], "12782": ["预后", "原文未识脉名，但言「脉仍未起」，示脉气未复。阴虚于下、肾不养肝、木乘土位，痛呕不食，延绵四十余日，几致汗脱。药后痛呕虽平而脉未起，虑其来复，故以丸代煎徐徐培养，属预后判断。", []], "12783": ["治法", "原文未识脉名。胁痛属肝胆二经所循，素本忧劳，忧伤肺、劳伤心，心肺伤而肝郁。法当宣补，未可因东方气实而用疏散。此段重在确立治法，故归治法类。", []], "12784": ["病机", "脉洪为木火亢盛之象。暴怒伤肝，肝火挟血妄行清窍，胁肋胀痛、烦热，皆肝经实火循经上扰、横逆所致。洪脉主实热，故宜先泻东方之实，兼助中央之土，以杜传脾之患，体现肝病实热、木火刑金、防其传变之病机。", ["洪"]], "12785": ["病机", "原文未出脉名，以忧思过度伤心脾立论。心脾两伤，气血不能流贯，致厥、少二经不利，胁肋隐痛。脾伤则木不安，为心脾两虚、肝木乘土之病机。治先培补心脾，治其致病之源，属虚证胁痛，与脉象无直接关联。", []], "12786": ["病机", "原文未出脉名，以腰为肾府、痛属肾虚立论。素沉酒色，肾阴本亏，僭伤血脉，痛起于渐，屡发不瘳，行立不支，卧息稍缓，属久病肾虚之腰痛。暴病为实，久病为虚，在经属腑，在脏属肾，强调肾虚为本，非外邪实痛。", []], "12787": ["病机", "原文未出脉名，以任脉为病、内结七疝立论。思虑烦劳损伤中气，亏及奇经，任虚失担任之职，冲虚血少不能营筋，肝主筋与肾同归一体，前阴为宗筋之会，故睪丸下坠、不知痛痒，名曰𤻊疝。属奇经虚损、肝筋失养之病机。", []], "12788": ["病机", "脉来虚数少神，为脾肾双亏、虚火内扰之象。二天不振，八脉有亏，任脉不足则睪丸下坠；肾气通耳，水不济火则耳鸣；火炽阴削则精泄。虚数少神示正气不足而虚热内生，故以脾肾双培为主，属虚损病机。", ["虚", "数"]], "12789": ["病机", "脉弦兼滑，弦主肝郁、滑主痰湿。疝气三载，任脉为病，内结七疝，大如鸡卵，囊大如瓜，满腹攻痛，劳则胀大作坠，乃肝肾不足、中气亦虚，痰湿下注、肝气郁结所致。弦滑示虚实夹杂，故以劳者温之、损者益之立法。", ["弦", "滑"]], "12790": ["病机", "脉弱形癯，为肺气虚弱、津液不布之象。久嗽不已，肺热叶焦，则生痿躄；肺司气化主皮毛，雨露不施则万物不生，故两足环跳穴按痛、不能步履。脉弱示肺金虚馁，下病治上，宜滋养肺金，属肺虚致痿病机。", ["弱"]], "12791": ["病机", "脉弦细微数，弦主肝郁，细主阴亏，微主气虚，数主虚热。壮年三阴不足，阴寒湿邪乘虚陷入下焦，两足胫骨肿胀、腿膝酸疼、大肉渐瘦，神疲食少、面目痿黄，气血俱亏。弦细微数示正虚湿恋、虚中夹实，虑成残废，宜平补三阴兼利湿舒络。", ["弦", "细", "微", "数"]], "12792": ["病机", "脉弦细，细为阴亏，弦为血少，肝肾血液不足，莫能流贯络中，故腿足酸痛乏力，虚则善变。此脉象主阴血亏虚，络脉失养，病机在肝肾不足，与腿足酸痛乏力相应。", ["弦", "细"]], "12793": ["病机", "原文未明言脉象，但述筋脉扎起、屈伸则痛、酸楚乏力，筋无血养，络湿不清，显属虚寒。病机为血虚寒湿痹阻，筋脉失养，与腿痛乏力相应，法当温养。", []], "12794": ["主病", "大渴引饮，舌裂唇焦，火灼金伤，津液枯涸，能食脉软，此属上消，亦名膈消。脉软为津液枯涸、气阴两伤之象，火灼金伤故能食而渴，谨防发背，白虎加人参汤主之。", ["软"]], "12795": ["预后", "消渴已止，眠食俱安，痰嗽未平，胸腹仍胀，乃木火余威，木击金鸣，火灼金伤。经闭二月余，脉象细数无力，非胎候也，有虚劳之虑。细数无力为阴血亏虚、虚火内扰，故非妊娠，宜静补其阴。", ["细", "数"]], "12796": ["病机", "脉来软数无力，症本阴液有亏，五志过极，俱从火化，万物遇火则消。软数无力为阴亏火旺、气耗之象，必先荡涤积热，然后补阴，否则得补而愈炽。服泻心汤火势已杀，宜补真阴。", ["软", "数"]], "12797": ["病机", "原文未明言脉象，述神思过用，摇动相火，载血上行，下为遗泄，虚阳上越眩晕，面色戴阳，不能久立久坐，眼花耳鸣，胸背隐痛如裂，呕吐黄绿水，乃木乘土位，心脾不足，肝肾亏虚，二气无能流贯。", []], "12798": ["病机", "吟诵不倦，深霄不寐，寐则梦遗，形神日羸，饮食少思，脉来细数，此属血耗心虚，神不摄精，水不济火，肾不交心。细数为阴血耗损、虚火内动，心肾不交，非郁思不遂者可比，当从厥阴胞络论治。", ["细", "数"]], "12799": ["病机", "年甫廿四，两天皆虚，纳谷不丰，劳感咳嗽愈后频频走泄，心悸体倦食少，劳心耗肾，心肾两亏，脉不宁静，心相火旺。阴虚精遗于下，阳虚热冒于上，心肾不交，水不济火，暂宜变化地黄汤。", []], "12800": ["病机", "脉象虚数，虚为不足，数为有热，揭示“两天不足”即肺肾阴亏。水亏于下则火炎于上，故午后渴饮、肺胃阴伤；阴液不濡则大便结，肾虚不固则小便频、梦泄。能食不能充养形骸，乃水不济火、壮火食气。脉虚数正合阴亏火旺之机，谨防消渴而变三阳结病。", ["虚", "数"]], "12801": ["病机", "脉来软数无力，软为气衰，数为虚热，无力为精气不充。原文谓“肺肾俱亏，精气不相营运”，精不化气则气不归精，故无故精滑自不能禁。肺司百脉之气，肾纳五内之精，二者俱亏则精关不固。脉软数无力正是精气两亏、虚热内扰之象，法当温固三阴。", ["软", "数", "虚"]], "12802": ["病机", "脉来软数无神，软为脏阴亏虚，数为虚火，无神为根本衰败。原文谓“脏阴有亏”，阴中之水亏或火亏，致肾失封藏，水不生木则肝病传脾，土不生金则脾伤及肺。中气不足则溲便变，肾虚水反为湿，小水如膏如淋；宗气无根则虚里穴动。脉软数无神正示脾肾水火交亏、中虚不能交通心肾。", ["软", "数"]], "12803": ["病机", "脉来涩象，涩主气滞血少、脉络不通。原文谓劳心耗肾，肝不藏血，血不化精，精不化气，湿热伤阴，心火下注。溺血不痛为血去，有痛乃赤淋；癃闭亦能溺血，因三焦气化无权。脉涩正是气化不利、火掩精窍、血阻溺窍之征，故见溺血、淋闭等症。", ["涩"]], "12804": ["病机", "脉来虚数，虚为气虚阴亏，数为心火内动。原文谓“水泉不止者，膀胱不藏也”，小便频数由心火下注、气结阑门，由癃变淋，火掩精窍。已服多方先效后不效，乃气虚阴亏、二便齐下、约束无权。脉虚数正合心火下注而气阴两伤之机，故宜清心保肾。", ["虚", "数"]], "12805": ["预后", "脉来弦象，弦为肝旺，亦主阴亏。原文谓血淋载余、溺管疼痛，始因苦寒伤胃，继又温补，致咳嗽有痰、形神日羸、饮食日少、皮肤发热，下损于上而及中。脉弦示肾之阴亏、肝之阳强，三焦俱伤。弦脉见于虚损日久，正合“殊属可虑”之预后判断。", ["弦"]], "12806": ["病机", "脉虚，主气血不足。原文谓阳明多气多血，气不摄血则渗入大肠而下；血不养肝则肝不藏血，血海空虚故不能受孕；生产之后血不归经、气不归窟。形丰脉虚乃“外强中干”，脉虚正揭示中气不摄、肝脾失统之便血与不孕病机，故养心脾以和肝胃。", ["虚"]], "12807": ["病机", "脉来虚软，虚软为气血阴阳并损；右关弦滑，弦主肝气病痛，滑主中虚痰湿。原文谓络伤便血十余年，精神不振，心虚气短，阳事痿顿，年甫四二未老先衰。脉虚软示中虚肾肝胃气皆虚，弦滑见于右关更证中焦气机不利。此脉正合“阴阳并损”“外强中干”之机，故从心脾进步。", ["虚", "软", "弦", "滑"]], "12808": ["病机", "脉来软数，软为虚，数为热，此虚热之象。结合便后远血、血色鲜红、肛脱、头眩神倦，乃肾水不足，肝阴少藏，脾少统司，气无摄纳。软数脉反映气阴两虚，虚热内扰，脾不统血，故议归脾举元，从乎中治。", ["软", "数"]], "12809": ["病机", "脉滑数，滑主湿，数主热，为湿热内蕴之象。酒湿伤阴，湿热下注，灼伤肠络，故见肠风便血。滑数脉直接反映湿热壅盛，迫血妄行，与酒湿伤阴之病机相应。", ["滑", "数"]], "12810": ["病机", "脉来滑数，按之无力，滑数主湿热，无力为虚。便血数年，红紫相间，腹中隐痛，乃三阴内亏，湿热不化，阴络受伤，脾不统血，气不摄血。滑数示湿热，无力示正虚，虚实夹杂，渗入大肠而下。", ["滑", "数"]], "12811": ["预后", "脉来细数，细为阴伤，数为阳亢，然注泄色如赭，化机衰惫，此阳败于阴，真元几脱之象。细数脉在此非单纯阴虚，而是阴阳离决之危候，故拟回阳之法，多酌明哲，预后不良。", ["细", "数"]], "12812": ["预后", "脉沉潜无力，沉潜为虚，无力为弱，绝不思食，肤胀腹大，耳闭绝无闻，乃脾肾两亏，生阳不布，水溢气凝，肾气欲脱不能上承心。脉沉潜无力正合脾肾阳衰，勉拟一方，以尽人力，预后堪忧。", ["沉", "潜", "无", "力"]], "12813": ["病机", "脉来浮数而空，尺部独减，浮数为虚热，空为血脱。症本心脾气馁，脾肾阴虚，血失统司，水不制火，血注后阴，鲜瘀不定，便前便后俱有。浮数而空示阴亏火旺，血滑气脱，脉络不能摄固，殊为棘手。", ["浮", "数", "空"]], "12814": ["病机", "脉来软数无神，尺部尤甚，软数为阴亏虚热，无神为胃气衰败。症本阴亏，水不制火，火灼阴伤，寒热如疟。软数无神反映阴亏火旺而正气已衰，清浊相混，溲多便结，与脾肾阴虚、相傅失职相关。", ["软", "数", "无", "神"]], "12815": ["病机", "原文未识脉名，但述清气在下则飧泄，浊气在上则䐜胀，肝实胁胀，脾虚腹满，木乘土位，食少运迟，营卫不和，寒热往来。此乃肝脾不和、升降失常之病机，补中益气佐涩固胃关，以复中焦升降。", []], "12816": ["病机", "原文未出脉名，以“相火不振”“中土困于阴湿”立论。相火亏不能生土，土虚无以生金，致脾失斡旋、肺失治节，湿甚则濡泄，故见大便溏薄、小水频数。此段重在阐发阳气根于命门、长养于中土，火衰土湿则诸经失敷布，虚症蜂起，非以脉象为凭。", []], "12817": ["主病", "脉来细弱无神，细为血少，弱为气虚，无神则脾肾双亏之候。曾经洞泄又值大产，脾虚清气不升，肾虚胃关不固，故洞泄日增、完谷不化。脉细弱无神应血枯经闭之虑，正合“益火之源，以消阴翳”之法，火虚不能生土，土虚不能运化精微。", ["细", "弱"]], "12818": ["病机", "原文未出脉名，以“脾肾双亏”为纲。三次血崩、七胎半产，中土受亏，化机失职，清不升浊不降，故呕吐吞酸、肠鸣飧泄；乘肾之虚，戊邪传癸，遂成肠澼，五色相兼、呕哕大汗、绝食神迷，皆脾肾衰败、湿邪内壅之危候，非脉象所主。", []], "12819": ["主病", "脉来虚数无神，虚为气不归宗，数为虚阳浮动。肾乃胃之关，胃关不固则泄泻数年不痊；宗气上浮，虚里穴动，故怔忡屡发。虚数无神示久延有二阳之病发心脾、传为风消息贲之虑，正合“气不归宗”之机，当以丸剂缓图。", ["虚", "数"]], "12820": ["主病", "脉来细数无神，细为少阴血虚，数为湿郁化热。阴湿袭虚，病起于下，两足蒸蒸而热、肿痛至膝、蠕蠕而动、酸软无力，病名脚气。少阴血虚、阳明气馁，湿邪乘之，脉细数无神故有拘挛痿躄之虑，法当除湿通经，辅以宣补少阴阳明。", ["细", "数"]], "12821": ["妇人", "原文未出脉名，以“怒损肝阴，木邪化火”立论。下耗肾水，上蒸巅顶，值妊三月奇脉受戕，少阴虚不能引巨阳府气则巅疼，阳维为病苦寒热。此段属妇人妊娠兼肝郁化火之证，治以逍遥散加川芎、香附条达肝邪，非凭脉断病。", []], "12822": ["主病", "脉洪而数，洪为阳明胃火燔盛，数为热邪急迫。胃火上炎，头中震痛如动脉之状，时作时止，正是火性主动、随脉搏击之象。洪数之脉主阳明实热，故以“寒以取之”直折火势，与头中震痛相应。", ["洪", "数"]], "12823": ["病机", "脉来细数，细为阳虚阴弱，数为虚阳上浮。素本阳虚，阴翳上滞精明之府，故不时巅痛、容色萧然。细数非实热，乃火不归原、阴寒内盛而虚阳外越之象，法当益火之源以消阴翳，使阳复阴化，巅痛自止。", ["细", "数"]], "12824": ["病机", "脉来软数，软为阴亏不能敛阳，数为虚阳浮越之象。原文谓“宿疾阴亏，巅顶时痛，面色戴阳”，乃阴不制阳，浮阳上扰清空，故脉软数。此脉主阴亏阳浮之病机，与巅顶痛、面赤戴阳相应，治以壮水之主。", ["软", "数"]], "12825": ["病机", "脉象沉滑，沉主里，滑主痰湿。原文谓“湿痰盘踞中州，清气无由上达清灵之所”，痰湿内阻，清阳不升，故头痛如破、痛甚作呕、胸满肋胀，名曰痰厥头痛。此脉主湿痰中阻之病机，治以温中佐风药。", ["沉", "滑"]], "12826": ["病机", "左脉虚弦，右脉滑疾。虚弦为心肝肾阴不足、肝虚生风；滑疾为中虚湿痰不运、脾虚生湿。原文谓“两耳失聪，如风雨声，间或蝉鸣”，乃阴亏于下、痰湿阻于上，清窍失聪。此脉主阴亏痰湿之病机。", ["虚", "弦", "滑", "疾"]], "12827": ["病机", "右脉滑疾无力，左脉虚弦。滑疾无力为气虚有痰，虚弦为肝虚生风。原文谓“气虚有痰，肝虚生风，脾虚生湿”，故右耳闭、昼夜常鸣、目见小黑点。此脉主气虚痰湿、肝风内动之病机，治以养气助脾。", ["滑", "疾", "虚", "弦"]], "12828": ["病机", "脉来滑数，滑主湿热，数主火。原文谓“湿热阻于气分，少阳不和”，又“心火肝阳不宁”，故耳轰不聪。此脉主湿热内蕴、厥少不和之病机，防其失聪，治当清心相以化湿热。", ["滑", "数"]], "12829": ["病机", "左脉虚数，右脉虚细。虚数为阴亏有热，虚细为气分不足。原文谓“先天固属不足，气分有湿，阻蔽清窍，升降失常，湿蒸热腾，少阳不和”，故耳蔽不聪。此脉主气阴两虚、湿热阻窍之病机。", ["虚", "数", "细"]], "12830": ["病机", "脉弦右滑，按之大疾。弦主肝郁，滑主痰湿，疾为湿热内盛。原文谓“气分有湿有痰，耳闭不聪”，乃痰湿阻于气分，清窍不利。此脉主痰湿内盛之病机，治以清心相化湿热，午后服资生丸。", ["弦", "滑", "疾"]], "12831": ["病机", "原文未识脉名，以经络理论阐发耳闭病机。谓“肾虚则水不能上升，心火无由下降”，阴液下亏，脉络干涸，气血不畅，故耳内常鸣。又因抑郁，五志不伸，水虚不能生木，肝燥生脾，土虚不能生金，肺病及肾，二气不平，五内互克，辗转沉痼。此段主病机，治以平补镇心丹加减。", []], "12832": ["病机", "脉来虚数而空，虚为三阴内亏、精血不足，数为阴虚生内热，空则脉道不充、阴精耗损之甚。原文谓肾虚不能养肝、肝虚生风、肾虚生热、脾虚生湿，三阴俱亏故见此脉。耳内蝉鸣、睛红生眵、太阳胀痛乃虚热上浮、肝风上扰之症，手足无汗示阴液不足。脉虚数而空正合上盛下虚、防脱之机。", ["虚", "数", "空"]], "12833": ["病机", "六脉俱沉，按之细数，原文自释沉者郁也气也，弦者肝也，细者肝阴不足。沉主气郁于内，细数为肝阴亏虚而生内热，弦为肝木之象。气火掩闭神光，故左目失明。脉沉细数弦并见，说明肝阴不足、气火内郁上攻目窍，属虚中夹实之病机，故治以明目地黄合扶桑法养阴清肝以保右目。", ["沉", "细", "数", "弦"]], "12834": ["病机", "脉来弦数，弦属肝木，数主热，合而示肝肺伏热化风。原文谓目疾六载不时举发、迎风流泪、惧日羞明、交午尤甚，目内红丝起自童年，皆肝开窍于目、伏热化风上扰之象。弦数之脉正应肝肺郁热生风之机，故治以清心凉肝兼清肺热，使伏热得清则风自息、目疾可缓。", ["弦", "数"]], "12835": ["病机", "脉来软数，软为阴精不足、脉道不充，数主热。原文谓肾水下亏不能涵木，木燥生火，火甚生风，风火相搏，肺金受制，白睛属肺故赤缕浮红、泪出眵多。软数之脉正合水亏木燥、风火内炽之机，且有赤脉贯瞳之虑。治宜壮水生木、升阳散火，不可泛服去风涤热之剂，取上病下取之意。", ["软", "数"]], "12836": ["病机", "本段未识脉名，纯论病机。原文谓水亏于下、火升于上，水不制火、阴不胜阳，缘少年嗜欲太过，水失所养不能生木，木燥生风，风火交并于上、阴液消耗于下，致瞳睛暗淡无光、色兼蓝碧而为内障。又言肾虚则脾亦虚，脏腑之精失所司不能归明于目。治宜壮水济火、补阴潜阳，冀水升火降。", []], "12837": ["病机", "脉体虚弦无力，虚为阴精亏乏，弦属肝木而无力则示肝阴不足、木失柔养。原文谓视物不甚分明，素多带下，奇经有亏，水火不济，神光不敛。带下日久耗损奇经阴血，水火不能既济，故脉虚弦无力而目视不明。此脉正合纯虚无实之机，故治宜纯补真阴，不可妄投清利。", ["虚", "弦", "无力"]], "12838": ["病机", "本段未识脉名，以症论机。原文谓金水二脏素亏，金虚不能平木，水虚不能制火，肝阳内扰、阴水不升，故眩晕、左肢麻痹；又酒体肥甘过度，湿热蓄于肠胃上壅于经，故齿痛上引太阳。齿痛属阳明有余，眩晕麻痹属太少不足，久延病深，故从阳明有余、少阴不足论治，用清胃、玉女煎加鹿衔草。", []], "12839": ["病机", "本段未识脉名，专论病机。原文谓齿乃骨之所终，手足阳明之脉上循于齿，天癸主于冲脉，冲为血海并足阳明经而行。阴虚无以配阳，水虚不能济火，故经事先期、不时齿痛。此属阳明有余、少阴不足之候，虚火循经上攻齿龈，故治当从阳明有余、少阴不足论治，清胃火而滋肾水。", []], "12840": ["病机", "形丰而脉软，是外似有余、内实不足之象。原文以舌边带黑为肾色上僭心部，断为脾肾必虚：脾统血、肾藏精，精血不守其乡，故肾水不升、心火不降，火炎物焦。脉软正应内虚，非实邪之候，故治取滋苗灌根、培补其阳，从本缓图。", ["软"]], "12841": ["病机", "脉来软数无神，软为不足、数为有热、无神则正气亏，合于肾水不足、心火有余之机。水不济火，火性炎上，故舌糜；五志乖逆，化火伤阴，脉失神气。上病下取，壮水之主以制阳光，正针对此虚火之本，而非苦寒直折。", ["软", "数"]], "12842": ["病机", "脉来软数无力，软而无力主正虚，数主火。原文谓肾水不足、肝木失荣，木燥生火，火盛生风，风火相并上冒清空，故声哑舌强、视听不聪。脉软数无力正是水亏火浮、风火内动而正气不支之象，故治以益气壮水，求水火既济。", ["软", "数"]], "12843": ["病机", "脉来滑数而空，滑数主火盛痰动，空则阴精已亏。原文归因诵读太过、五志化火，火盛刑金，金溶不鸣，火旺水亏，故声哑语难。滑数为火，空为水亏本伤，恰合火炎于上、根本先损之机，故以铁笛丸加减清润并施。", ["滑", "数", "空"]], "12844": ["病机", "脉来细数，细主阴血亏少，数主虚热。原文谓液化为痰、精不化气、金水交伤，脏阴津液俱耗，阴耗阳竭，故喉疼音哑、咳嗽痰多，肾水不升、肺阴不降。细数正应阴津耗损而阳气不敛、阴气不收之候，生气伤残，病机在虚损。", ["细", "数"]], "12845": ["病机", "脉来虚数，虚主正气不足，数主热。原文断为心、肝、肾三阴皆亏，厥阴循咽、少阴浇喉，湿热痰火郁而不达，故喉痛不能食盐、不耐烦劳。虚数之脉正合三阴虚亏而兼郁热之象，故拟清上实下，标本兼顾，久防喉痛。", ["虚", "数"]], "12846": ["预后", "脉来大小不均，是脉体乍大乍小、气血乖乱之象。原文述类中于右、神烦言蹇、肢搐口歪、气冲呃逆，外风勾动内风，湿痰上攻清窍，脉之大小不均正应风痰扰窜、气血失序。年近古稀而见此，故断风烛堪虑，属预后不良之候。", ["大", "小"]], "12847": ["病机", "脉象弦滑，弦主肝风内动，滑主痰。原文谓曲运神机、心劳肾耗，水不涵木，肝阳内扰，内风化火，火动痰升，上冲多汗、精神昏愦、语言错乱，已成类中之象。弦滑正合风火痰浊上扰清窍之机，故惟宜静养，不可妄攻。", ["弦", "滑"]], "12848": ["病机", "原文未出脉名，以经络脏腑立论。心脉系舌本，脾脉络舌本，少阴循喉咙挟舌本，故心脾郁湿生风生痰，循经上扰，致舌破流涎，状类中风。病机在湿郁化痰生风，非外风真中，乃内风夹痰之轻证。", []], "12849": ["病机", "卒然晕倒、手足厥逆而六脉皆伏，气口犹是，知非脱绝，乃饮食填塞胸中，胃气不行，阴阳阻隔，升降不通，脉道被遏而伏。此食厥类中风，非真中风，故先以盐汤探吐，通其壅塞。", ["伏"]], "12850": ["病机", "右半偏枯，左部细弦为肝肾阴亏、风阳内动，右部气口虚濡、关部沉滑为气虚痰湿留络。三阳病发于右，右属痰与气虚，络中痰湿未尽，故当气血两培兼化痰利节。", ["细", "弦", "虚", "濡"]], "12851": ["病机", "左部弦数，风阳鼓动、心火随之；右部兼滑，湿痰内蕴。肾水不足不能养肝，风阳不降夹痰上扰，故心胸不安、头眩肢麻、肤腠刺痛、腹肋气喘作胀，延防类中。法当滋水柔肝兼化痰湿。", ["弦", "数", "滑"]], "12852": ["病机", "脉来软数兼弦，软为水亏，数为火炎，弦为木燥风动。水亏于下、火炎于上，壮火食气则上虚眩冒，精不化气则咽干梦泄。值春令阳升，木燥生火煎熬津液变痰，故防痉厥，法宜壮水。", ["软", "数", "弦"]], "12853": ["病机", "脉来软数无神，软为脾肾不足，数为郁火，无神为元气虚馁。气郁化火、土郁生痰，上扰精明之府，故颠眩如驾风云、卒然愦乱倏尔神清，非类中之比。痰伏中州，清浊升降失司，姑以治痰为主。", ["软", "数"]], "12854": ["病机", "脉弦细按之稍滑，弦细为营卫两亏、血虚风动，滑为痰气结中。中脘板闷、嗳气不舒、内热食少、肢抽肉𥆧，皆血虚肝风扰络、痰气中阻之象，延久须防晕厥，故进化痰镇逆。", ["弦", "细", "滑"]], "12855": ["预后", "脉来细数无神，细为阴血亏耗，数为虚火内灼，无神为元气衰败。忧思郁怒损肝脾，气郁化火灼阴耗血，筋失荣养而结于项侧，溃久脓清不敛，正虚难托，故预后堪虑，法当壮水生木、益气养营。", ["细", "数"]], "12856": ["主病", "脉见双弦，弦为肝木之象，双弦则肝郁偏旺。忧思抑郁损伤心脾，神不安舍而惊悸少寐，肢战食减，容色萧然，皆由肝郁乘脾、心脾两虚所致。弦脉主郁主痛，双弦更显郁结之深，故殊为可虑，提示病势缠绵。", ["弦"]], "12857": ["病机", "脉来弦数无神，弦为肝木横乘脾胃，数为火郁痰凝。情怀屈抑，肝木乘脾，脾虚生痰，上注于肺，痰塞喉间，胸次不舒，饮食减少。痰随气行，经过胞络，神形外驰，悲泣不能自主。弦数无神示痰火郁结而正气已伤，有三阳结病之虑，法当宁中州为主。", ["弦", "数"]], "12858": ["预后", "前议镇木清金、泻南补北后诸症悉退，脉亦调平。调平之脉为胃气渐复、阴阳趋和之象，说明火盛灼金、痰蔽神明之病机已得缓解。然火起于妄，变幻不定，脉平仅示当前向愈，仍需济补真阴、清痰之本，调和智意，防其复扰心君。", ["平"]], "12859": ["病机", "脉来搏疾，疾为阳盛火动之象。思则气结，谋深木屈，木郁生火，土郁生痰，痰火扰乱神魂，故动作不经、语言无次。阴不胜阳，阳主动搏，故脉来搏疾。此脉揭示痰火内扰、阴不制阳之病机，法当寻火寻痰，加以清镇之品。", ["疾"]], "12860": ["病机", "脉空，空为气血亏虚、脉道不充之象。思则气结，忧则气耗，悲哀动中，形神错乱，肝胆自怯，心肾不交，多寤寡寐。神不安舍，舍空则痰火居之。阳𫏋脉空，心神不敛，肝阳不宁，有狂乱之患。空脉正示正气虚而痰火乘虚内居之病机。", ["空"]], "12861": ["病机", "脉来沉，沉者郁也。胎产之后恶露不行，败血上冲，扰乱心胞，瘀凝作胀，人事不省，如醉如疯。气血不得和畅，气化风火，败血随之，癫狂见矣。沉脉主郁主里，示瘀血内结、气机郁滞之病机，仍宜化瘀为治。", ["沉"]], "12862": ["病机", "脉来滑数，滑主痰，数主火。心火肝火上亢，神不安舍，舍空痰火居之。月事不调而带症，头常作痛，遍身骨节俱疼，肌肤作痒，两目呆瞪，项颈气胀，牙缝出血，语言错乱。滑数之脉正合肝风痰火不宁、扰乱心胞之病机。", ["滑", "数"]], "12863": ["病机", "原文未识脉名，以症测机。水亏于下，木失敷荣，土为木侮，中枢少运，水谷精微凝结成痰，蔽障中土，络脉间断。痰伏于中，气血周流失常，故卒然仆地、神魂如醉、痰涎上溢、四肢瘛疭，良久方醒，间断来发，病名曰痫。症本虚中之实，法当补泻兼施。", []], "12864": ["病机", "脉来弦大，弦为肝风，大为阳盛，故主心火肝阳上升化风，夹痰上达心胞。原文谓“积劳、积郁、积痰为患”，症见卒然跌仆、流涎时醒，乃风痰蒙蔽心包之癫痫；忽寒热昏冒为尸厥，亦由火升风动、痰随气逆所致。脉症合参，病机在肝阳化风、痰火内闭。", ["弦", "大"]], "12865": ["病机", "脉来软数，软为水亏不济，数为火旺血热。原文谓“水不济火，血热化风”，故身战、口噤、背张，至夏火令则发，逾时而已，病名风痉。软数之脉正示阴亏火炽、血燥生风之机，法宜养肝息风、壮水制火，脉象与治法相应。", ["软", "数"]], "12866": ["病机", "原文未出脉名，然述咽疼舌短、卒然口噤背张、手足掉摇、气从少腹冲逆，显系阴亏水不涵木、冲虚血不荣筋、中虚湿痰生热、血燥化风、风扰阳明、龙雷上僭之病机。诸症从厥阴、阳明主治，归芍异功加减，正合柔肝健脾、息风化痰之法。", []], "12867": ["病机", "脉虚弦而数，虚为阴血不足，弦为风动，数为热化。原文谓“湿痰化热，血燥生风，风扰阳明，九窍不和”，故瘛疭虽缓而虚烦、口干、心悸、腹中气升、舌难伸、项背强、牙关紧、六日不更衣。脉象示正虚风热内扰，都从胃治，原方加减。", ["虚", "弦", "数"]], "12868": ["病机", "脉数无力，数似火而无力为虚，故原文谓“症势颇类无根之火”，非相火衰微，乃忧思抑郁、火不宣扬、不能生土，脾湿郁而生痰，流注诸经。症见脐下卒然震动、惊惕莫能自主、上攻臂痿厥不收、面色戴阳，皆虚阳上浮、痰湿变幻之候。", ["数", "无", "力"]], "12869": ["病机", "原文谓“冲脉动，则诸脉皆动”，冲脉起于肾下、挟脐上行至胸而散。气从少腹蠕动逆冲，心慌意乱，虚里穴跳如跃梭，乃肾不养肝、气失摄纳、根蒂亏虚之病机。脉动应冲气上逆，故主虚损，宜恬淡寡欲以固根本。", ["动"]], "12870": ["病机", "年甫廿三，脉来软数，软为不足，数为虚热。原文谓“二天不振，心肾交亏”，瘰疬虽痊而二气伤未复，虚里穴动，中虚作呕。软数之脉示心肾亏虚、中气不振，故先养心脾、兼滋肝肾，脉症治法相贯。", ["软", "数"]], "12871": ["病机", "脉数无神，数为虚阳浮动，无神为真阴亏竭、根本已衰。原文谓“真阴不足，心肾不交，宗气上浮，虚里穴动，心烦意乱，莫能自主”，脉数无神正示阴不恋阳、宗气失守之机，故当培其下以固肾填阴。", ["数", "无", "神"]], "12872": ["预后", "原文“脉体渐平，症势渐减”指出脉象由病态渐趋平和，反映水火渐有相济之机，是久恙阴亏阳亢、心肾不交向愈的征兆。脉平则症减，说明阴阳渐和，故预后向好，宜服养心之剂以巩固。", []], "12873": ["病机", "脉来软数无神，软为虚，数为热，无神为正气不足。原文谓水虚无以上升，心火无由下降，水火不济，心肾不交，故见心烦意乱、宗气上浮、虚里穴动，脉软数无神正是虚火内扰、心气浮越之象，主惊悸健忘之虑。", ["软", "数"]], "12874": ["病机", "脉来弦数而软，弦为木旺，数为火炽，软为阴亏。原文谓真阴下亏，虚阳上越，水不济火，五志化火，水不涵木则曲直作酸，阴不敛阳则竟夜无寐。此脉反映阴虚火旺、心肾乖违、肝木偏亢之病机。", ["弦", "数", "软"]], "12875": ["病机", "脉来动数，按之则弦。动主惊，数主热，弦主肝胆。原文谓心胆自怯，怯则气乱伤乎心，恐则精怯伤乎肾，胆汁不满则胆冷无眠。此脉示心胆气虚、痰热内扰、神魂不安之病机，故见疑虑惊恐、默默不知喜怒。", ["动", "数", "弦"]], "12876": ["病机", "脉来两关弦强搏指，两关候肝胃，弦强搏指为痰饮气阻、胆胃不和之象。原文谓惊气伤胆，恐气伤肾，五志不伸，聚饮气阻，胆寒肝热，热升于胃，故心胸懊𢙐、悸在胃脘心下。脉症合参，病机在胆胃痰热内扰。", ["弦", "强"]], "12877": ["预后", "原文“脉来形色未起，殊非佳兆”，虽未识脉名，但言脉形与色未起，说明正气未复，形色未充，故非佳兆。现感风寒，暂以二陈汤加减，是急则治标，兼顾正气未复之预后判断。", []], "12878": ["病机", "脉来细涩，细为阴血不足，涩为营液亏耗。原文谓脏阴营液俱耗，肾虚则胃关不健，肾不吸胃，食入即吐，小便红赤，夜不能寐，心神不交，酒色伤阴耗气。此脉主阴亏液涸、胃肾失和之病机，防其涣散。", ["细", "涩"]], "12879": ["病机", "左脉涩，右脉弦滑。左涩为肝肾阴亏，右弦滑为脾积痰饮。原文谓肝肾两亏，肾虚则胃关不健，脾积则饮食作酸，胃不冲和，运纳失常，脉犯五行之克。此脉示肝肾亏虚、脾积痰阻、木克土之病机，少年更属不宜。", ["涩", "弦", "滑"]], "12880": ["病机", "脉象软数无神，软为阴亏，数为火旺，无神示正气不足。原文谓“症属阴亏，水不济火，阴不敛阳”，故腠理疏开而汗出不止，心液外泄。汗血同源，经来甚涌，近汗不收，面色戴阳，虚里穴动，皆阴不敛阳、心液外泄之候。脉软数无神正合阴亏火旺、气不敛液之机。", ["软", "数"]], "12881": ["其他", "原文仅存“经脉”二字，无脉象描述及病机论述，无法据以分析所主病机。脉象写法未识别，故脉象要素为空。此段内容过简，不能推断具体病机与主病，仅能视为残缺条文。", []], "12882": ["病机", "脉来弦劲，弦为肝郁，劲为木亢。原文谓“郁损心脾，木乘土位”，心境不畅则肝不条达，脾失斡旋，气阻血滞，故经闭年余、饮食日少、形体日羸。弦劲之脉正示肝木偏亢、乘克脾土，五志化火烁阴，血海渐涸，必至血枯经闭。", ["弦", "劲"]], "12883": ["病机", "左脉弦出寸口，志意隐曲不伸，郁损心阴；脉络枯涩，血少不养脾。原文谓“阴虚血少，血不养脾，脾伤不能为胃行其津液”，精血日衰，故经闭半载、腹中虚胀作痛、容色憔悴。弦出寸口主郁，涩主血少，合示心脾郁损、精血枯竭之机。", ["弦", "涩"]], "12884": ["病机", "原文未出脉象，以“腹中素有血症，大如复杯，脉络阻碍”言病机。经血循环失其常度，故经不及期、经前作痛；气郁伤肝，木乘土位则饮食减少；悲哀伤肺，治节不行则胸次不畅、腰如束带。总属癥瘕阻络、肝脾肺俱伤，冲任带脉受损，故年逾三旬尚未妊子。", []], "12885": ["病机", "脉来滑数而长，滑主痰湿壅滞，数主热，长主邪实有余。原文谓“任脉经隧滞塞，非血枯可比”，经闭五载而饮食起居如故，手指肿胀色紫、鼻衄、遍身疮疡，皆营气不从、逆于肉里，郁而化热之候。滑数而长示实热壅盛，故有痈疽肿满之虑。", ["滑", "数", "长"]], "12886": ["病机", "脉软数无神，软为阴亏，数为火盛，无神为正气虚。原文谓“阴亏则火盛，火盛则逼血妄行”，阴亏阳搏谓之崩。崩漏虽止，巅顶犹疼、腹中䐜胀，乃水不涵木、阴不敛阳，厥阴脉上额会巅、下络少腹，故见巅疼腹胀。脉软数无神正合阴亏火旺、气血失守之机。", ["软", "数"]], "12887": ["病机", "原文未出脉象，以“二气素虚，奇经复梗”论病机。气不外卫则寒，血失中营则热，经无约束则愆期。督行一身之阳，任行一身之阴，任督犹天之子午，冲脉从中直上。二气素虚而奇经梗阻，故寒热不调、经期愆度。法当静补真阴以充八脉，属虚损奇经失养之候。", []], "12888": ["病机", "脉来滑数，无神而空，似有胎而不果，腹无坚硬之处，非停瘀可比。滑数本主痰热，然无神而空，乃阴亏血少，肝脾不调，木不条达，土运郁抑，故月事不调，晡热巅疼，时作时止。脉症合参，病在肝脾，非胎非瘀，治当崇土培木，宣补中州。", ["滑", "数"]], "12889": ["病机", "脉来沉细，显是命火中伤，不足以煦和五内而敷四末。沉细主里虚寒，故经候愆期，胸腹相引而痛，痛时手足厥冷，过食生冷即发，腹中雷鸣。皆由产后气血双亏，虚寒为祟。治宜益水之源，以消阴翳。", ["沉", "细"]], "12890": ["病机", "脉象双弦无力，少腹主于肝，肝病善痛；肝传脾，脾病善胀；脾及胃，胃病善呕，饮食不甘。双弦无力乃肝郁脾虚之象，故经本失期，少腹胀痛，不时呕哕。肝、脾、胃并病，有妨孕育。", ["弦", "无力"]], "12891": ["病机", "脉象空弦，虚劳已著。空弦乃肝郁气滞、血结成症，下离天枢寸许，正当冲脉之道，跳跃如梭，攻痛如咬，按有头足。肝乘土位食减，木击金鸣为咳，中虚营卫不和，寒热如疟，脾伤血不化赤，白带淋漓。情志郁结，必得心境开舒。", ["空", "弦"]], "12892": ["病机", "年逾四旬，产育过多，气血双亏，形丰脉软。软脉主虚，故饮食不甘，精神慵倦，夜来少寐，清晨坐起必呕，胃有留饮。经失期色紫，腹右有症，由气郁伤肝，怒哀动中所致，有血崩之虑。先以解郁舒肝，以畅心脾主治。", ["软"]], "12893": ["病机", "带下赤白如漏卮，脉虚弦，舌绛中有红巢，大便坚结难解，小腹左角作痛，遍体关节酸痛，咳嗽震动，按摩其痛不止，呼吸往来俱觉牵引痛处。此皆血液脂膏耗损，不能荣养一身，经隧滞涩，络脉乖分，二气无能流贯连络交经之处。久漏久崩，非堵塞可止，升提可愈。", ["虚", "弦"]], "12894": ["病机", "服后带下较减，痛楚渐舒，大便仍结，舌心无苔，一条红滑，乃真阴亏损之征也。脉来弦数无神，弦数本主热，然无神，乃真阴亏损，虚热内扰。带下日久，液道虚滑，卒然堵塞，其势必溃。故以宣通之品为之向导，同气相求也。", ["弦", "数"]], "12895": ["病机", "连进通以济塞，带下十减二三，小腹关节酸痛俱缓，大便燥结未润，弦数之脉未静，舌心红滑如故。症本血液脂膏耗损，复延奇经，八脉俱亏，百骸俱损，岂铢两之丸散所能窥其藩牖乎。爰以一通一塞，大封大固之品，共煎浓汁，如膏如饴，每以二两，开水和服。", ["弦", "数"]], "12896": ["病机", "原文未出脉名，以“带下不止，所有皆淡黄色，腹痛筋如抽掣”述症，断为“精血内枯，脂液尽涸，冲任交病”，非肝木乘脾。精血枯涸则冲任失养，带脉不约而带下不止；筋失濡润故抽掣。病本在奇经虚损，故从奇经八脉主治。", []], "12897": ["病机", "原文未出脉名，述“经漏成带，医疗无功”，归脾等剂“未尝齿及奇经”，断为冲、任、督、带交病。漏久成带，奇经失约，非独脾不统血。议通阳补阴从奇经主治，示病机在奇经虚损、阴阳不交，故常法无功。", []], "12898": ["病机", "原文未出脉名，言“奇经之脉，隶于肝肾”，冲任不足则血虚寒，故经来色淡且少、带下腰痛、骨节酸痛。乙癸同源，肝肾精血亏虚则奇经失养，寒从内生。主旨在明奇经病根于肝肾，故当乙癸同源主治。", []], "12899": ["病机", "脉象虚弦无力，虚为肝血不足，弦为肝气郁结，无力则非实邪。原文谓“肝木郁结可知”，因阴性偏执、沉默寡言，生发之气不振，脏腑失和，故难受胎。脉虚弦无力正合肝郁血虚之机，拟逍遥、归脾、八珍加减以畅肝木。", ["虚", "弦"]], "12900": ["预后", "服壮水潜阳之剂后“胎元竟过离宫”，半载“阴平阳秘，脉象和调”，为药后阴复阳潜、胎元得固之象。然形神拘倦甚于畴昔，仍缘火甚阴亏，故脉和调示当前阴阳暂平，非病本尽除，仍以壮水潜阳为主，属预后判断。", ["和"]], "12901": ["病机", "脉来滑数无神，滑数主火，无神则阴液耗虚。原文谓胎三月而坠“正属离火暴甚，阴液耗虚，木失滋营”，譬久旱泉涸木槁。火亢灼阴，胎失所养故坠。滑数无神正示火盛阴亏、胎元不固之病机，非平脉之滑数有神。", ["滑", "数"]], "12902": ["病机", "产后百脉空虚，气血俱伤，冲任不振，故脉虚；脉来弦数无神，弦为冲任失调、木失柔养，数为虚热外浮。原文谓“奇经大损，营卫乃伤”，任虚不卫、冲虚无营，致寒热如感、乳房作痛、头旋、五心燔热，诸虚叠见，皆虚弦数无神所主。", ["虚", "弦", "数"]], "12903": ["病机", "大产后阴伤未复，脉象虚弦。虚为阴血不足，弦为水不涵木、肝阳偏亢。原文谓“水不涵木，火灼金伤，清肃不降”，故内热目涩羞明、形神慵倦、咳吐痰腥，有肺痈之虑。虚弦之脉正合阴虚木亢、金受火刑之病机，故清上实下主之。", ["虚", "弦"]], "12904": ["病机", "原文未识脉名，然述妊七月而坠，因肺脉司胎，壮火食气伤肺，金水同源，肾阴亏而大肠坚结，阴亏火盛，胎失所养而坠。病机在肺肾阴亏火旺，主妊妇胎坠，兼大便难、气火偏亢之候。", []], "12905": ["病机", "脉来弦数无神，弦为肝郁，数为火动，无神则中气不足。半产后亡血，肝失敷荣，脾虚营卫不守，故寒热；肝脾俱困则经候愆期，宗气上浮而虚里穴动。此脉主肝郁脾虚、阴亏火浮之病机，与寒热、经乱、心悸相应。", ["弦", "数"]], "12906": ["病机", "脉沉涩数，沉主里，涩为阴亏血少，数为虚火。喉痛悬壅、咯痰艰涩、夜足微浮、形瘦面黧，皆肾阴不上承、肺气不肃降所致。此脉示水竭金枯、虚火上炎之病机，主喉痹、虚劳，与梦惚、浮肿相应。", ["沉", "涩", "数"]], "12907": ["病机", "脉弦为肝胆气横之象，木旺克土，阻遏胃降，故食入即呕、吐苦气逆；呕剧震破咽头胃络，血与食并出而咽痛。此脉主肝胃不和、气逆火升之病机，治当疏肝降胃，切莫见血投凉，正合弦脉主气郁。", ["弦"]], "12908": ["病机", "二诊呕平而脉仍弦，知肝阻胃降之本未除；头脑眩、体疲乏力，向有脑漏偏左，乃胆热上移清窍。弦脉主肝胆气逆，此段示肝胃虽降而胆热未清，脑漏鼻渊亦胆热上移之病机，与眩晕、鼻渊相应。", ["弦"]], "12909": ["病机", "原文未识脉名，述阳升太过，清窍空，脉络之血难下趋而走清道，鼻衄如涌，络血由裂伤而出如走熟径。病机为阳升太过、督脉不宁、阳络妄行，主鼻衄涌甚，治当引阳入阴、安宁督脉。", []], "12910": ["病机", "原文未识脉名，述肺气为病、心血不清，痧疹留邪不达，气化有阻，致面目肢体颈项尽肿、呼吸深则胸胁痛、小溲短少。病机为肺气不化、水道不通、留邪内陷，主痧疹后肿满，若蔓延则肺胀喘闭。", []], "12911": ["病机", "脉弦涩，弦为肝气不舒，涩为荣血亏少。产育多胎，脉内损而胞脉失固，故恶露红黄杂见、烦劳即下，殊防崩漏；头眩目少神、背胀胸闷、掌跖夜热，皆血亏气滞、气有余便是火之象。此脉主肝郁血亏、胞脉不固之病机。", ["弦", "涩"]], "12912": ["病机", "脉弦为肝气不舒，气机郁滞；涩为荣络失和，血行不畅。右腰肋内牵引而痛，咳嗽行动转侧拘急，正是肝气横逆、络脉瘀阻之象。弦涩并见，说明气滞与血瘀并存，故治以舒气机、调荣脉，气行则血行，络和则痛止。", ["弦", "涩"]], "12913": ["病机", "脉弦主经隧不通、气机郁滞，涩主胞络恒闭、血行瘀阻。少腹两旁有癖，腿肢腰胯酸胀而痛，筋掣微麻，舌后难过，皆因胞脉属心、心主血脉而络于舌，血瘀络阻则诸症丛生。弦涩并见，明示气滞血瘀、络脉不通之病机，故仍以通络行血为治。", ["弦", "涩"]], "12914": ["病机", "脉不浮数，排除外感风热；弦滞乃气血郁滞、筋脉不利之征。右肩髃疼痛，筋骨拘急，臂难上举，仲景所谓“但臂不遂者为痹”，结合经事失调，显系血行不畅、筋脉失养。弦滞脉象紧扣行血舒筋、以利机关之治法，说明病机在血瘀气滞而非表邪。", ["弦", "滞"]], "12915": ["预后", "脉濡弦，濡为真元已伤、气血不足，弦为胞脉已闭、气机郁滞。腹痛肠鸣便泻，食难运化，形瘦色夭，月事不来，舌光绛如豚肝，寒热咳嗽，皆真元大伤、肠胃脂肪剥蚀殆尽之候。脉证合参，病势已深，生气索然，外将浮肿，故断为难治。", ["濡", "弦"]], "12916": ["病机", "脉浮数，浮主风邪外袭，数主火热内郁。火为风搏，郁而不宣，故喉痛咽肿，悬壅下垂，嗓音窒咽不扬；肢清形寒，是热郁于内而阳不达外；稍有咳嗽，为风火犯肺。浮数脉象正合风火相搏、郁而不宣之病机，故治以清宣利咽。", ["浮", "数"]], "12917": ["病机", "脉弦涩，弦主气机郁滞，涩主血瘀在络。左背胛酸楚，起及肘腋胠胁，既则右背部胸膺亦然，内著于骨，按之痛少止，卧则痛甚，胸臆气闷，呼吸不快，皆血瘀络阻、脉痹之属。心主一身血脉，络病难治，渐痹渐痼则尤难，弦涩脉象正示血瘀络痹之病机。", ["弦", "涩"]], "12918": ["预后", "脉濡弦而涩，濡为肝肾精血内亏，弦为精气无力上注，涩为血行不畅、目失所养。绿水泛入瞳人，瞳人散大，色如珠母，由右及左，听觉欠聪，皆肾脏精气衰败之征。尺部稍藏，说明根本尚存一线，但药饵补精益气功效甚微，预后不佳。", ["濡", "弦", "涩"]], "12919": ["病机", "脉弦滑左搏，弦主气逆，滑主痰涎，左搏为少阳胆火震动。饮食入胃，传肺而肺苦气逆，水谷精液酿痰不生血，故咳嗽痰沫多，咳剧震肺络则痰红杂出；足肢浮肿，周行气化有阻；苔黄口苦，胆汁暗泄。弦滑左搏正合痰热阻肺、少阳火郁之病机。", ["弦", "滑"]], "12920": ["病机", "脉弦左搏，弦为肝旺，左搏示肝气偏亢。足肿消而咳呛剧、痰多带红、口苦苔黄、呕恶，乃肺失宣降、胃逆不降、胆汁上逆之象。肝木犯肺胃，气逆痰滞，故脉弦而左搏，主病在肺胃肝胆，属气逆痰热之机。", ["弦"]], "12921": ["病机", "脉濡弦，濡为肾气有伤、摄纳无力，弦为肺苦气逆、咳嗽喘急。腰酸形瘦、寐觉汗泄，皆肾虚不纳、肺气上逆之征。肺为气出入之道，其本在肾，脉濡弦正合肺肾同病、本虚标实之机，故以纳下宣上为治。", ["濡", "弦"]], "12922": ["病机", "脉弦涩而数，弦主肝郁，涩为血瘀，数示热迫。产后胞脉损伤，恶露缠绵，近忽崩中喷涌有瘀块，头眩心悸足膝酸软，乃瘀热内扰、冲任不固、肝不藏血之机。弦涩数并见，主瘀血夹热、崩漏之病。", ["弦", "涩", "数"]], "12923": ["病机", "脉滑主痰湿内盛。咳嗽喘闭、喉间有声、卧难安枕、唾皆白沫，转黄浓则少瘥，显系寒痰壅肺、气逆不降。滑脉为痰浊内蕴之征，故以温药和之，温化痰湿，使肺气宣降复常。", ["滑"]], "12924": ["病机", "脉弦主痛、主气滞。湿滞相搏肠府，腹痛下利红白、里急、肛胀痛则汗泄，舌苔灰白而腻，乃湿浊积滞壅阻肠腑、气机不畅之机。弦脉应肝，肝气犯肠，故治以导滞通腑，去其壅滞。", ["弦"]], "12925": ["病机", "脉弦数，弦为肝气盛强，数为少火化壮火。胆不清静、胃不下降，致胸脘痞塞、烦闷喜太息、呕恶酸苦、苔黄口苦、夜寐惊惕，即「胃不和则卧不安」。弦数主肝胆火旺、胃气上逆，故拟温胆汤泄木安胃。", ["弦", "数"]], "12926": ["病机", "脉来弦涩，弦主肝郁气滞，涩为血少精伤。肾脏精气内夺，脑筋不赡，手麻足酸、耳失聪胀、声音咽涩、唇喁，皆精亏络瘀之象。湿热不攘为诱因，弦涩示本虚标实、肾亏脑弱兼络脉不畅之机。", ["弦", "涩"]], "12927": ["病机", "脉弦滞，弦为肝气亢害，滞示气机郁滞不畅。肝血失荣，腹胀时胀时愈，气上冲胸，发厥搐搦，心悸呃逆，乃肝阳化风、气血瘀滞之机。弦滞主肝亢血瘀、风动痰阻，故势恐成痫难愈。", ["弦", "滞"]], "12928": ["预后", "脉濡缓为湿邪渐化、脾胃气和之象。前诊肝亢厥搐、心悸呃逆等症俱平，今脉转濡缓而不弦急，说明肝阳已潜、营卫调和，故曰「完好无恙」。濡主湿去，缓主胃气复常，此脉与诸症向愈相应，故仅需舒筋调荣以善后。", ["濡", "缓"]], "12929": ["病机", "脉濡滑而弦，濡滑为痰湿内蕴，弦为肝阳扰动。患者精神痛苦、心血脑力交瘁，阳动少藏，故见头眩畏烦、夜眠不安、肉𥆧筋惕；濡滑主痰湿阻滞，弦主肝风，左肢及偏左头面酸木浮肿，正是厥中萌动之兆，与「精神衰弱」及风痰内动病机相合。", ["濡", "滑", "弦"]], "12930": ["兼症", "脉濡弦，濡主湿浊，弦主气滞。经行涩少愆期、头胀体酸神疲，为营血不充、气机不畅；右耳后缺盆结肿、痰多咳不爽，乃经隧血脉为病，痰湿凝结。濡弦之脉正合湿痰阻络、血气不调之兼症，故曰「标本兼治」，既调经隧又化痰湿。", ["濡", "弦"]], "12931": ["病机", "脉弦涩，弦主肝风内动，涩主精血亏少。年老精气衰，肾脉不荣舌络，故言语忽蹇、呃逆；头眩筋掣而痛、善恐、带下频，皆肾虚肝旺之象。弦涩并见，示精血不足而风阳上扰，几经倾跌乃厥中先兆，与肾虚风动病机紧扣。", ["弦", "涩"]], "12932": ["病机", "脉弦主气机郁滞、水湿不化。清阳失旋，阳难化气，致腹胀身尽肿、皮肤厚、面黄暗晦、头脑胀痛不清，大便溏而小溲赤，此水气太过、湿郁化热之肤胀。弦脉应肝，主气郁水停，与「温化」治法相应，然脉弦而症重，故曰不易治。", ["弦"]], "12933": ["预后", "脉静息平，即脉不数不弦、气息平和，为肺络虽伤而脏气未败之象。咯血盈碗盈盘，肺叶久坏，痰浊秽恶，症情危重；若脉见洪数弦急则火逆血涌，预后不良。今脉静息平，说明血虽多而气未上逆，故曰「不然殆已」，脉静为可治之凭。", ["静"]], "12934": ["病机", "脉濡弦，濡主湿留，弦主风动。寒热之后留邪不清，内居营卫，精气暗夺，故偏身颤振如战栗，面部筋脉掣动可见。濡弦之脉示营卫不和、风痰内扰，神疲、舌黄积而苔露绛点，为湿郁化热伤阴之征，与养心脾、调营卫治法相应。", ["濡", "弦"]], "12935": ["病机", "脉弦而涩，弦主气滞，涩主血瘀湿阻。湿热内阻气分并注血中，故肌肤发瘰、搔痒流水、皮蜕；头眩腹胀闷、尿烫，为湿热郁蒸；大便泻利则适，示湿有去路。弦涩之脉正合气滞血瘀、湿热胶结之病机，故治以利气清血、渗泄湿热。", ["弦", "涩"]], "12936": ["病机", "脉弦为肝气偏旺，涩为血少不畅。原文称“奇脉既伤，血质贫乏，而肝气又盛”，正合弦涩并见：血虚则脉道不充而涩，肝旺则脉气劲急而弦。故见肌肤痿黄无津泽、腰酸头眩耳鸣、带下频仍、乍寒乍热，皆血亏肝旺、奇经失养之候，且虑崩漏。", ["弦", "涩"]], "12937": ["病机", "脉弱微主气血虚少，弦主肝旺，数主虚火。原文谓“血质淡薄”“产后又失调养”“血虚火又盛”，故脉弱弦微数并见。血虚失荣则面白、经迟白多、带下频；虚火上炎则偏头痛、耳后筋掣、口腔生疮、咳嗽，皆本虚标热之象。", ["弱", "弦", "微", "数"]], "12938": ["病机", "脉濡为体虚湿滞，弦为肝气不柔，涩为血行不畅。原文言“流产胞脉暗伤，体质虚弱”“宗脉失养，累及脑海”，故脉见濡弦涩。冲任损伤、奇恒为病，则头眩耳鸣腰疼、体疲带下、胸背交痛、胸膈气闷、呼吸不舒，症虽复杂而源在奇脉虚滞。", ["濡", "弦", "涩"]], "12939": ["病机", "脉弦主气逆，涩主血枯肠燥。原文“肠胃交通滞塞，食入翻出，呕恶酸苦痰涎，大便十余日不下”，是肠枯失润、胃气上逆，故脉弦涩。形瘦容悴为久病耗伤，气滞血瘀、升降失常，故断为“肠枯胃逆，格症是虑”。", ["弦", "涩"]], "12940": ["病机", "脉细为阴血亏少，弦为肝气偏急，数为虚热内蒸。原文“经停半载”“晡热骨蒸，咳呛气急”“形瘦纳减”，正是血枯劳瘵之候。阴亏则脉细，木旺则脉弦，虚火内灼则数，故断“劳瘵血枯，难以图治”，兼面暗跗浮、便溏不爽，示脾肾亦败。", ["细", "弦", "数"]], "12941": ["病机", "本段未识脉名，纯论病机。原文以冲脉起于关元、女子系胞为命门立论，谓“六七而天癸就竭，不当竭而竭，是谓不及”，命门精气日衰，排泄不力，湿热流布脉络，故见足肢流火、肌肤风瘣、面赤汗泄；纳食寡味、胀难化、五更晨泄，皆元气日消之征。", []], "12942": ["病机", "脉濡主精气虚乏、湿滞不运，弦主肾伤而肝失柔和。原文以肾“有翕有辟，亦静亦动”立论，谓“肾脏有伤，精气滑泄，有辟无翕，有动无静”，故精气虚而荣卫循行失度，见肢清恶寒、身热发无定时、小溲昼少夜频，脉濡弦正是体虚而气机不藏之象。", ["濡", "弦"]], "12943": ["病机", "脉弦主气滞，涩主血瘀。原文“脘痛，休止半晌又痛，鸣则少瘥，午后较剧，或彻于背，则如锥刺”，痛有定处如锥刺，正是瘀血阻络之征。气滞血瘀，痛深及络，故脉弦涩，治以蠲痛通络，弦涩并见恰合气结血凝之病机。", ["弦", "涩"]], "12944": ["病机", "脉濡细弦数，濡细为阴伤液燥、肺阴亏虚，弦数乃阴虚火旺、虚热内扰。原文述‘阴伤液燥，太阴不收，肺气焦满’，咳呛痰稠、掌中热、鼻衄，皆肺燥阴伤、虚火迫血之象。脉症合参，主肺痨叶焦之病机，故曰‘诚恐肺痨叶焦’。", ["濡", "细", "弦", "数"]], "12945": ["病机", "脉濡弦，濡为精气衰、痰湿内蕴，弦主肝风内动。原文谓‘气机失舒，痰阻于络，内风即乘隙而动’，故见心摇善恐、四肢瘛、口㖞、语言忽蹇。胸中气闷、咯痰灰黑、苔腻，皆痰阻气郁之征。脉弦应内风，濡应痰湿精衰，合示荣络熄风豁痰之治。", ["濡", "弦"]], "12946": ["病机", "脉细弦涩，细为阴血枯槁，弦主气结，涩乃瘀滞不通。原文述‘肠胃幽门之间淤塞不通’，食入即吐、便秘枯结、肌肉消瘦、肤起鳞屑、少腹结肠如垒块，皆胃脘枯槁、瘀血内结之候。脉细弦涩正合瘀结阴伤之病机，年逾六旬，胃气已衰，故难图治。", ["细", "弦", "涩"]], "12947": ["病机", "脉细濡缓，细为阳气不足，濡缓主卫气空疏、阳微阴盛。原文谓‘清阳不振，卫气空疏’，故头胀形寒畏风、鼻多清涕、动辄汗泄、耳轮畏风、食入欲便，皆阳无力升举之征。腹胀乃‘阳微阴盛之过’。脉症相应，主卫阳不振、阴寒内盛之病机。", ["细", "濡", "缓"]], "12948": ["妇人", "原文未识脉名，纯述症候。‘生未足月婴时即泻，后天脾胃不振’，致任脉通、太冲脉盛之年而干瘪不长、无发育气概，牙宣便溏。此先天后天俱损，脾胃衰败，冲任无以充养，故发育迟缓、药饵难治。属妇人发育不足之候，脉象缺如，病机在脾胃虚衰、冲任失养。", []], "12949": ["兼症", "脉弦主肝气郁结。外感已解，咳痰霍然，而经水涩少不畅、左胁闪烁而痛、缺盆结核未消，皆肝郁气滞、络脉不和之兼症。原文‘再以疏肝舒气’，明示弦脉应肝，此段重在疏肝解郁以调经、消结核，非主新病，乃余邪兼症之治。", ["弦"]], "12950": ["病机", "脉弦涩，弦主肝郁火旺，涩主血行瘀滞。原文谓‘肝胆火热下移任脉’，带频色黄、少腹胀、两旁作酸，皆肝火挟瘀下注任脉之象。引《内经》‘任脉为病，女子带下瘕聚’，脉弦涩示久恐聚而为瘕，故宜先事消弭，主肝火瘀结、任脉受损之病机。", ["弦", "涩"]], "12951": ["预后", "脉细弦数，细为阴精亏耗，弦数乃虚火内炽。原文述‘血后肺燥，阴不上承’，咳嗽不休、痰带血星血筋、骨蒸盗汗、声音嘶败，皆肺阴枯竭、虚火灼金之候。脉症合参，断为‘水竭金枯之虑’，阴精不复则喉痛声嘶难瘥，故属预后不良之判。", ["细", "弦", "数"]], "12952": ["病机", "脉弦右搏，弦主饮主痛，右搏提示湿浊偏盛于中焦。原文谓嗜曲糵致内湿自盛，外湿相感，未尝宣泄分消，湿酿而荣卫自衰，故寒热延缠、头眩体酸、盗汗、肌肉渐瘦。脉弦右搏正是水谷酿湿、荣卫循行失常之象，先和荣卫止寒热，徐图理湿。", ["弦"]], "12953": ["预后", "脉濡弦，濡为肺气不足、湿邪内滞，弦为邪入益深、气机郁滞。原文谓风邪由肺俞内舍于肺，失治邪深，肺气益伤，咳嗽气逆喘急、左胠内痛、身热痰腥、稍有浮肿，皆肺叶败坏之候。濡弦并见，正虚邪实，故断为肺叶行将败坏、颇难治。", ["濡", "弦"]], "12954": ["病机", "脉濡弦，濡示荣卫虚衰、气血不足，弦示虚中夹有郁滞。原文谓损者非一日而损，虚极岂能骤复，寒热、寝汗、咳嗽较前稍减而脉仍濡弦，说明荣卫未复、虚损未填。故再以养荣固卫，脉象反映的是久损难复、荣卫俱虚之病机。", ["濡", "弦"]], "12955": ["病机", "脉弦滑，弦主肾虚气逆、运化无力，滑主痰湿内蕴。原文谓肾脏精气之虚由来已久，摄纳不固则小溲夜频，运化无力则生痰酿湿。寒热已辍而脉仍弦滑，说明脾肾两虚、痰湿未化，故拟强肾运脾，脉象紧扣肾虚痰湿之机。", ["弦", "滑"]], "12956": ["平脉", "脉来濡静柔和，濡为胃气薄弱，静为神气安定，柔和为无亢无躁之象。原文谓年届六旬，见证属肝旺胃薄，纳食欲嗳为胃虚作嗳，而脉却濡静柔和，说明虽有肝旺胃薄之症，脉气尚和，故主张怡悦颐养，草木汤液不宜多服，脉象示胃气未败。", ["濡", "静", "和"]], "12957": ["病机", "脉弦主气机郁滞、肝木失疏。原文谓性躁而量窄，有难言之隐，膈气不舒，清阳失旋，发为厥心痛，痛发倏忽面颊呈青色、肢清背胀，皆气郁阳遏之候。脉弦正应膈气不舒、清阳失旋之病机，故从厥心痛治，以疏肝理气为要。", ["弦"]], "12958": ["病机", "脉弦涩，弦主气滞，涩主血行不畅、瘀阻。原文谓经事将至未至，少腹绷胀而痛，经净后带下有红黄恶物，腹中气忽上忽下不舒，夜卧足肢平放则难过，皆气血郁滞、冲任不畅之象。脉弦涩正示气滞血瘀，故谓隐疾之征兆已见，宜慎毋忽。", ["弦", "涩"]], "12959": ["预后", "脉弦主湿蕴气中、清浊混乱、气机郁滞。原文谓腹膨胀痛、肠中鸣、大便泻、小溲少、食难运化、面色苍黄、苔黄腻，湿浊内盛而脾运受困。延缠两月久泻，脉弦示土虚木乘，故防脾败。脉象反映湿困气滞、脾土将败之机。", ["弦"]], "12960": ["病机", "脉濡缓而弦，濡缓为脾虚湿困、运化无力之象，弦则气机郁滞不舒。原文谓思虑太过、脾元大伤，脾神委顿则气机不为灵转，故腹膨胀、面浮跗肿、肌肤痿黄。濡缓示脾运困惫，弦示土虚木乘、气滞胀满，脉症相合，胀势乃成。", ["濡", "缓", "弦"]], "12961": ["病机", "脉弦搏，形色脉候均无虚象，说明禀赋丰厚、痰湿素盛而胃气苦浊。弦搏为实象，非虚损之比，与晨起口苦、腻而不清、乘热饮食腹痛溏泄相应；神劳事烦、脑力多动少静，清空之血下趋滞涩，故脑常胀痛。脉实证实，治当泄胃浊、清脑络。", ["弦"]], "12962": ["病机", "脉弦涩，弦为肝气郁滞，涩为血行不畅，合之即肝脏气滞血瘀。原文两胁属肝，胁内痛牵及季胁后、转侧维艰、难卧下，右臂肩髃作酸、小溲赤涩难解，皆气血瘀阻之征。脉弦涩与痛有定处、溺涩相应，故防酿肝痈，示瘀滞日久有腐溃之虞。", ["弦", "涩"]], "12963": ["预后", "原文未识脉名，仅言脉搏已调，是脉象由病时之弦劲渐归和平。风阳就和、脑力安静、瘛疭痉厥向瘳、胸宇已舒、面容清爽、舌苔亦薄，皆邪退正复之象；惟偏左头筋时仍扛起、或作噫嗳，余风未净。脉搏已调示大势向安，故仍以清络柔肝安脑善后。", []], "12964": ["病机", "脉沉细而弦，沉细为阳虚水停、气血不足，弦为水气不化、气机郁滞。原文嗜饮成癖、曾患水肿、病根未除，故心悸荡漾、脘中气结若痞、肢清足肿。沉细示元阳不振，弦示水气太过，脉症合参属阳虚水泛、气滞饮停，故以温药和之。", ["沉", "细", "弦"]], "12965": ["病机", "脉弦为肝病之主脉，原文肝著、气滞血瘀，右胁内痛牵及季胁后、淋溲便难、卧下转侧维艰，皆肝经气血瘀阻之征；日昨食物有伤、痛则欲呕，是木郁犯胃。脉弦与胁痛、溺难相应，病势已深，故言治疗甚难，不自慎则难图。", ["弦"]], "12966": ["病机", "脉濡滑按之无力，濡为湿盛、滑为痰聚，无力则元阳不振。原文痰湿俱盛、元阳不振，故腹胀尿急、宗筋不举、头眩、记忆善忘、交睫善寐而多梦。濡滑示痰湿内壅，无力示阳衰不能化气，脉症相合，治宜扶元阳以祛痰湿。", ["濡", "滑"]], "12967": ["病机", "原文未识脉名，从经事四月余不转、胞脉为闭立论。经隧之血将化为水，故足肢浮肿、至晚而甚，是血瘀水停、输化不行之病机。延久则水气上逆碍肺，势必生喘闭之患。虽无脉象可凭，然胞脉闭阻、血化为水之机已明，故当以通泄为治。", []], "12968": ["主病", "脉弦数而左搏于右，弦为肝木气盛，数为热炽之象。咳嗽八年，痰多胸胁引痛，左胸骨高肿、重吸咳痛、按热殊炽，是肝火循经灼肺，病在肺体著骨之处，热毒壅聚，故防成疽患。脉数应热，弦应痛应肝，左搏于右示病势偏盛，与局部高肿炽热相应。", ["弦", "数"]], "12969": ["病机", "脉弦而涩，弦为肝肾阴亏阳浮，涩为精血耗损、脉道不利。精败为浊、小溲频数无力，精耗于下则骨少髓养；阴中之火浮泛于上，故齿髓痛、目赤、背胀、咳痰带红；左跗肿、右髀麻亦精亏络涩之征。诸症皆出一源，故从肝肾治，脉弦涩正合精亏火浮之机。", ["弦", "涩"]], "12970": ["病机", "脉弦主肝木失和、气机郁滞。外感秽湿与内伤食滞相搏，胃气失降，胆汁壅遏，故脘痞胀闷、头脑不清、面目肌肤小溲俱黄而黄暗不深。弦脉应肝，示胆气不利、湿浊阻遏中焦，故以通降腑气为治，脉弦与痞胀发黄之症相应。", ["弦"]], "12971": ["病机", "脉弦主中焦气机被湿浊壅遏、清阳不展。湿踞于中，清阳不振，故清气在下则泻、浊气在上则胀；阳不胜阴，故肢清且麻、腹鸣濯濯；头眩由清阳不升，少寐由胃气不和。脉弦苔黄腻，正合湿浊内阻、肝脾不调之机，故治以升清阳祛浊阴。", ["弦"]], "12972": ["病机", "脉沉弦，沉主病在里、病根深久，弦主肝失疏泄、气机郁滞。前患黄疸，肝疏泄失职，脾运不灵，胆汁瘀滞结成窠囊，故腹右膨胀闷塞、欲嗳弗畅，面目肌肤小溲俱黄。沉弦示病位深而气郁，与积块胀满相应，故疏达肝脾，仅冀少瘥。", ["沉", "弦"]], "12973": ["预后", "脉弦而搏，弦为肝木乘脾、搏为邪正相争、脉气劲急。腹胀痛绷急、食难运化、肌瘦便溏，是脾土受克；咳嗽少寐多汗、时有寒热，则肺劳肠劳萃于一身。脉弦搏示正气虽虚而邪势犹张，故曰岂易治耶，戒女劳、节饮食，寓预后不良之意。", ["弦", "搏"]], "12974": ["病机", "脉濡滑而弦，濡滑主痰湿内蕴，弦主肺肾气逆。肾气微弱，水谷精微酿为痰，痰壅于上则咳嗽气急；气候寒冷较甚即发，因肺恶寒而肾命气怯无力御寒。脉象与痰壅气逆之症相应，故从肺肾一炁论治，以纳肾为主，防喘促于未然。", ["濡", "滑", "弦"]], "12975": ["预后", "脉来弦搏刚劲，左寸滑而濡，右尤粗大，弦搏刚劲为心肺之伤日久、真气失守而邪气劲急，滑濡主痰湿。心悸不得卧、咳出非血非痰有如肺体，是心肺败坏；气逆、少腹痛、面黄暗、舌黄白腻，肠胃连带为病。脉象劲大而症见脏损，故难以图治。", ["弦", "搏", "滑", "濡"]], "12976": ["病机", "脉濡弦，濡主湿、主虚，弦主肝郁。产后失调，肝脾疏运委顿，脾虚湿盛则面黄而浮、足跗浮肿、大便溏泄；肝郁气滞则纳食胀闷难化；神疲呵欠、肢酸乏力、声音失扬皆脾虚气弱之征。脉象与症候相合，示肝郁脾虚、湿滞内蕴，病势已成蓐痨。", ["濡", "弦"]], "12977": ["病机", "脉沉弱无力，沉主里，弱主虚。病经四十余日，躯壳久病由经隧牵动内脏，心脏舒缩乍疏乍数或有歇止，心肺循环既乱，呼吸亦逆；天庭耳轮黄暗、目珠微黄、小溲赤、唇吻黝黑、舌灰口苦，皆肝胆为病、胆汁暗泄。脉沉弱无力正合久病正虚、邪留内脏之机。", ["沉", "弱"]], "12978": ["病机", "原文未识脉名，以呼吸定息论血脉循环，谓肺苦气逆、心脏舒缩太急，致心悸亢进其动振衣、乍疏乍数或动，中心吸气吃力；面目肌肤黄暗不泽、爪甲枯淡、唇吻黝黑、舌苔灰糙，心脏少血、胆汁暗泄。此因病累久致虚，与劳损之虚有别，故拟镇摄使肺气和平、心脏镇静。", []], "12979": ["病机", "脉弦涩，弦主肝病、气滞，涩主血瘀。腹痛呕恶数月，肝脾积伤，蓄血暴动，上呕积瘀如豚肝，下则黑衃如漆滓，面容肌肤萎黄，舌本白而灰糙厚腻。脉弦涩正合瘀血内蓄、气机壅滞之机，故曰非虚非火，当推陈致新，若投凉与补恐成盅胀。", ["弦", "涩"]], "12980": ["病机", "脉濡弦，濡主虚、主湿，弦主肝郁。思虑忧郁，精神未能痛快，气机不获展舒，胸宇既闷，咽间如有物阻，咯不出咽不下，悗闷时肢清厥，志乐气爽则无恙。此肝郁气滞、气机不畅之象，脉濡弦与症相应，故以愉快精神为主，参以宣气解郁。", ["濡", "弦"]], "12981": ["病机", "脉濡缓而弦，濡缓主脾虚湿困，弦主肝郁。清阳单薄，健运无力，四肢清厥，啜粥为安、啖饭欠适，脘中不舒难鸣，久坐起立头脑旋运、闭目少选即瘥。头为诸阳之会，四肢为诸阳之末，清阳不升故眩运厥冷。脉症合参，示脾虚阳弱、肝郁不达，故以健脾和阳为治。", ["濡", "缓", "弦"]], "12982": ["预后", "脉尚平静，面亦清亮。肺叶久坏，裂痕已深如烂疮漏管，痰浊秽恶虽弭而咯血历久不瘥，或盈口而出，或与痰相杂，高卧较安、平卧较甚。脉平静、面清亮，与肺坏咯血之重候似不相符，故曰不然殆已久矣，正以脉症相失判断预后险恶。", ["平"]], "12983": ["预后", "脉空弦而涩，空主脉道空虚、胃气衰败，弦主肝木乘土，涩主血少枯滞。胃脘枯槁至于结肠，势难挽救，大便虽通下燥粪甚伙，尚仍呕吐，形瘦见骨，色萎不泽。膈症至此，脉空弦涩与形瘦色萎相应，示胃气将绝、血枯津竭，故曰徒唤奈何，属预后不良之候。", ["空", "弦", "涩"]], "12984": ["病机", "脉缓微弦，缓为脾土本象，微弦则肝木乘之。原文谓「肝脾疏运失司」，弦主肝郁，缓中带弦示土虚木贼，故见心胸作嘈、腹隐痛、便带黏积、口甘溺赤、面黄暗不泽，皆肝脾不调、血质衃败之渐，非寻常伤湿可比。", ["缓", "弦"]], "12985": ["病机", "脉濡弦，濡主湿滞、气虚，弦主气机郁结。原文言「精神虚弱……气机之运用、肠胃之传导变化均乖乱失常」，脘腹否闷、嗳气、便溏不爽、咽间梗塞，皆气郁湿阻、腑脏失和之象，舌后光截花剥且糙腻，示虚实夹杂，故以和调腑脏、安宁精神为治。", ["濡", "弦"]], "12986": ["病机", "脉弦搏，弦为肝木亢盛，搏则劲急有力，示邪实正伤。原文「环脐少腹绷急而痛，酸坠不舒，便溏日有数起」，形瘦食难运化、欲呕咳嗽少寐多汗，乃肺劳肠劳并病，肝木乘脾、肺肠两伤，脉弦搏正应其邪势鸱张而正气已损，故谓殊不易调。", ["弦", "搏"]], "12987": ["病机", "脉弦，主痛、主瘀滞。原文左睪丸偏坠肿痛牵及鼠蹊、胯内色赤焮热，热已减退而脉仍弦，说明「精浊瘀滞未输」，邪未尽去，弦脉示气机郁滞、瘀浊内阻，故仍以通泄为治，并防囊肿日久外溃难敛。", ["弦"]], "12988": ["预后", "脉来缓和，缓为胃气渐复、和则阴阳相济之象。原文「败精腐瘀已渐输出」，睪丸焮赤渐退、肿痛渐消、囊皮已蜕，脉由弦转缓和，示邪去正安、「病机向瘳」，故仍守原意而小其制，此段以脉象判断预后转归。", ["缓", "和"]], "12989": ["病机", "脉弦，主肝病。原文「肝者，中之将也。病失疏泄，血亦瘀滞」，肝气亢害侮胃累脑，卒然发厥如痧胀之状，愈发愈剧。弦脉应肝，示疏泄失职、气血瘀阻、肝气上逆，故治以疏达调通，使肝气条达则厥可平。", ["弦"]], "12990": ["病机", "脉弦滑，弦主肝阳上亢、滑主痰湿内蕴。年届六旬肝肾内亏，头眩耳鸣目花、举步浮荡、神疲语蹇，原文谓「根蒂有亏之证，为厥中根萌」，弦滑示下虚上实、痰阳上扰，风火痰交织，有卒中先兆，故议河间法清降。", ["弦", "滑"]], "12991": ["病机", "原文未识脉名，故脉象要素为空。所述「年前产难，胞脉内伤」，胞脉属心主血，汗为心液，烦劳即背胀多汗、夜寝觉后汗泄，乃心脏之虚受胞脉影响，属产后荣血亏虚、心气不固之病机，故拟养心调荣为治。", []], "12992": ["病机", "原文未明言脉象，但述“心脏舒缩较前稍缓，亦不歇止，惟乍疏乍数之象未改”，此脉象反映心气不匀、肝脾疏运失司。啖芋艿致滞气生痰，胃气翳滞不行，故脘腹绷胀而痛、按之坚硬；足肢以上俱肿、环脐少腹按之不坚，为气分肤胀之征。经事之后黄浊恶物，胞脉属心，与心脏病相关，故病机为气滞痰阻、心脾失调。", []], "12993": ["病机", "原文未直接描述脉象，但陆君诊后断为“病虽在气，患已及血”，并谓“气分之病，臌胀浮肿，皆不见痛”，而患者左胁有块作痛，故知病在血分。积食日久，由气及血，血瘀络阻，故痛有定处。方用当归、川芎、白芍、香附、柴胡等养血行气，一剂知，说明病机为血分瘀滞兼气机不畅。", []], "12994": ["病机", "脉沉而涩滞，模糊不分至数，为湿邪内阻、气机窒塞之象。沉主里，涩主滞，模糊不分至数乃邪阻脉道、气血运行不畅。肢凉畏冷、涎沫上涌、二便涩少、神气不爽，皆因感风湿之邪失于解散，从热化后误用温补，致气机愈塞，邪热无出路，烁液成痰，逆行而上。故治以舒展气机，痰行热降。", ["沉", "涩"]], "12995": ["病机", "脉微而细，舌亮无苔，为气血两伤之候。微主阳气虚，细主阴血少。夏间患感，过服表散，汗出过分，汗为心液，气随汗泄，故气血两伤，肢骸失其营养，以致不能起坐、类乎瘫痪。此非真瘫，乃虚损使然。治以大剂参、耆、归、术等气血双补，补血药重于补气，以汗为血液，阴分偏伤也。", ["微", "细"]], "12996": ["病机", "脉来涩数上溢，涩为津液已伤，数为热邪内炽，上溢乃气逆不降。冬温初治温散，津伤热炽；继以滋填，热邪愈锢；再施温补，气机更窒；升、柴、耆、术反助其逆，巴霜、轻粉尽劫其阴。故见呃忒、口腻、水难下膈、频吐涎沫、便秘溺赤、潮热往来、少腹如烙。病机为热邪内蕴、津液耗伤、气机逆乱。", ["涩", "数"]], "12997": ["病机", "脉细数而促，细为阴亏，数为热炽，促为热盛阴伤、脉道急促。仲夏患感，温散伤阴，邪热内陷，故神昏谵妄、肢搐耳聋、舌黑唇焦、囊缩溺滴、胸口微斑。此阴亏热炽、液将涸竭之危候。治以西洋参、元参、生地、二冬等甘凉濡润，大剂投之，以救阴液。", ["细", "数", "促"]], "12998": ["病机", "脉虚弦而小数，虚为气阴不足，弦为肝风内动，数为热。体素虚，患感时过投温散，阴津阳气皆伤；进补滋腻妨中运，刚烈动内风。故头痛偏左后、子夜热躁、肢冷欲呕、口干不欲饮、不饥不欲食、舌蹇言涩、溺黄而频。病机为气阴两伤、内风扰动、中运不健。", ["虚", "弦", "数"]], "12999": ["病机", "脉右寸关滑数上溢，左手弦数。滑数主痰热，上溢示热邪壅肺、气逆不降；弦数为肝胆热盛。暑热始终在肺，不传经，故耳聋口苦、热甚于夜、胸次迷闷、频吐黏沫、啜饮咽喉阻塞、便溏溺赤、间有谵语。此暑热壅肺、痰热内阻之病机，一剂白虎汤可愈。", ["滑", "数", "弦"]], "13000": ["病机", "脉来弦滑而实，为邪热内传阳明腑实之征。弦主热郁气结，滑主痰热内壅，实主邪气盛而正未虚。前医升散后热退复热，邪已归府，故脉见弦滑而实，主可下之证，与腹不坚满但热结在里相应，径用承气汤下之，下后热显于经，转用竹叶石膏汤清解。", ["弦", "滑", "实"]], "13001": ["病机", "右部沉滑，沉主里，滑主痰热。症见恶寒头痛似伤寒，而心下疼胀、苔黄、溲如苏木汁，为痰热内蕴、表邪未解。脉沉滑说明邪已入里，痰热结于心下，故先解表后清里，吐胶痰而纳复，动则喘佐滋下，皆痰热去而气阴未复之象。", ["沉", "滑"]], "13002": ["病机", "脉至滑数，滑主痰热，数主热盛。症见耳聋不语、昏不识人、舌不能伸、苔黄腻、遗溺便秘、目不交睫、胸腹按之不柔，皆痰热蒙蔽心包、腑气不通之候。滑数脉说明热痰内炽，故用白虎汤加犀角、菖蒲等清心化痰，下证已备而先清透。", ["滑", "数"]], "13003": ["病机", "脉洪滑且数，洪为热盛，滑为痰血互结，数为热炽。症见壮热狂烦、目赤谵语、脘闷腹胀拒按、畏明口渴、气逆痰多，为热入血室、瘀热互结之重证。脉洪滑数说明热势鸱张，故用桃仁承气汤加犀角、石膏等大破其血、大清其热，后脉滑苔黄而腹胀，更用小承气汤下之。", ["洪", "滑", "数"]], "13004": ["病机", "脉虚促欲绝，虚为正气大伤，促为热盛阴伤、脉道不利。症见舌卷痉厥、腰以下不能动，为热陷营血、阴液耗竭、虚风内动之危候。脉虚促欲绝说明正虚邪陷，故先灌紫雪、犀角地黄汤清营凉血，厥止而苔黑目赤，仍用前汤，后呃忒频作，营热解而气道未肃。", ["虚", "促"]], "13005": ["病机", "左部数，右手俨若鱼翔，鱼翔脉为真元将竭、脉气散乱之危象，数主热盛阴伤。症见痰嗽气促、自汗瘛疭、苔灰厚、渴无一息之停，为热盛阴涸、虚风内动、元气欲脱之候。脉数而鱼翔说明邪热未去而正气已溃，故用竹叶石膏汤加减，后脉皆和缓，为转机。", ["数", "鱼翔"]], "13006": ["病机", "脉至细数，细为阴伤，数为热盛。症见发热而腰腿痛如刀割、苔黑燥、溺赤便黑，为热伤少阴、真阴内损之候。细数脉说明热邪深入少阴，阴液耗伤，故用西洋参、麦冬、生地、犀角等大剂甘凉濡润，热退痛已，后舌绛倍加、真阴涸竭，药难奏绩。", ["细", "数"]], "13007": ["病机", "脉弦滑而微数，弦主热郁，滑主痰热，数主热盛。症见昏痉谵语、六昼夜不交睫、旬日不沾米饮、舌缩苔垢，为热痰内闭、误治酿成之危证。脉弦滑微数说明痰热尚盛而正未大虚，故当竭力援之，勿再犯悖药，尚有一线生机。", ["弦", "滑", "数"]], "13008": ["病机", "初诊脉滑而洪，为阳明热盛，气分燔灼，故苔黄大渴、鼻衄数升，白虎汤清泄而安。复发壮热脘闷，乃食复。后左尺细数而芤，细数属阴亏，芤为精血耗伤，右尺洪大则虚阳浮动，合为女劳复之候，阴精亏而相火妄动，故舌绛溺涩、昏沉欲寐。", ["滑", "洪", "细", "数"]], "13009": ["病机", "右手洪大滑数，洪大为阳明热盛，滑数主痰热内壅。症见呃忒、苔腻、便秘、痰多、心下拒按，显系痰热结于胸脘，腑气不通，热势鸱张。故用小陷胸加清化痰热、宽胸降逆之品，使痰热得蠲，腑气通而愈。", ["洪", "大", "滑", "数"]], "13010": ["病机", "脉弦而软数，弦为肝阳上亢，软为阴亏不敛，数为热。患者阴亏肝盛，前医表散温补，致升逆无制，痰饮𫐖轕，风阳肆横，故目瞪神呆、气喘、舌绛不语、肢搐而厥。此脉示阴亏于下、风阳痰热扰于上，故以息风镇逆、清热蠲痰取效。", ["弦", "软", "数"]], "13011": ["病机", "脉弦数软滑，弦数主肝热风动，软滑为痰热内蕴。秋感服温散而日重，苔黑肢瘛，乃温散助热，引动肝风，痰热蒙扰，有厥逆之势。故急予清凉涤痰、息风开窍，服后脉较和，示热势渐退，一路清凉而向愈。", ["弦", "数", "软", "滑"]], "13012": ["病机", "脉伏而弦滑，伏为邪热内闭、阳郁不达，弦滑主痰热内盛。连服温散，热邪愈炽，痰热闭阻心包，故倏然昏厥、不省人事。此脉示热闭痰蒙之机，非虚寒之伏，故用大剂清心凉营、涤痰开窍，调至宝丹灌下即安。", ["伏", "弦", "滑"]], "13013": ["病机", "脉至弦洪豁大，右手尤甚，弦为肝风，洪大为阳热亢盛，豁大示阴不敛阳。症见大渴大汗、能食妄言、面赤足冷、彻夜不瞑，乃真阴素亏，心阳外越，内风鸱张。此脉非实热壅盛，而是阴亏阳浮之象，故以潜阳镇摄、滋阴息风为治。", ["弦", "洪", "豁", "大"]], "13014": ["病机", "脉皆细数，细为阴血亏少，数为虚热内扰。前医进桂、朴、姜、柴温燥，劫烁营液，故痰血频咯、神瞀耳聋、谵语便溏、苔黑溲少。此脉示真阴素亏、营液受烁，虽便溏不食亦不可畏滋腻，故以甘凉濡润、养阴清热获效，脉渐和而痊。", ["细", "数"]], "13015": ["病机", "左弦洪而数，右滑而溢，弦洪数主肝阳上浮、热盛于内，滑溢为痰热壅盛、肺气不降。症见面赤不眠、烦躁谵语、口甘渴腻、胸次痞结、大解未行，显系肝阳上浮、肺气不降、痰热阻痹，邪乃逗留。故以开结涤痰、通腑泄热而愈。", ["弦", "洪", "数", "滑"]], "13016": ["病机", "脉迟涩为血热内蕴、营行不畅之象，非寒凝；后转弦滑，示热与痰搏。原文“喉舌皆赤”为血热之征，故虽畏寒能食而脉不浮紧，知非外感寒邪。此脉主热伏营分，与筋掣不眠相应，故用清营而瘥。", ["迟", "涩", "弦", "滑"]], "13017": ["病机", "脉弦细为阴亏木旺，左寸右尺甚数、右寸关急搏不调，乃心肾火炽、肺胃痰热交争。原文“平昔善饮，三十年来期在必醉”，积热久锢，温补杂投，致风火痰浊互煽，故见耳鸣腰痛、火升梦戈、凛寒善怒，非虚寒可补。", ["弦", "细", "数", "急"]], "13018": ["病机", "脉形虚大为上焦热恋、下部阴亏，气逆不饥、呃忒自汗乃热壅气逆；脉至虚弦、按之涩弱，为营血不足、肝木失柔，故耳鸣不寐、脘痛头摇。两脉皆主虚中夹实，非纯补可投，故以养营调气、和胃柔肝取效。", ["虚", "大", "弦", "涩"]], "13019": ["病机", "左关弦、寸滑如珠、尺细而干，乃真阴亏而风阳内炽，搏液成痰。原文“体丰色白，平昔多痰”，痰火扰心则谋虑操持、肺金受烁。脉弦滑为痰热，细数为阴伤，故忌温燥，宜轻清。", ["弦", "滑", "细", "数"]], "13020": ["病机", "脉弦软不调为痰热结于上焦，尺中虚细为房劳伤于下部。原文“苔腻垢黄，脘闷便溏”，痰热有形之结未开，久耗之阴未复，故神气日消。弦软主痰热未清，虚细主下元亏虚，治当清上滋下。", ["弦", "软", "虚", "细"]], "13021": ["病机", "脉形涩数不调，为卫分邪恋、枢机不利。原文“补中益气，实卫锢邪”“承气通腑，但能下肠胃有形之物，不能散卫分无形之邪”，故热不退而不食不便。涩数主邪滞营卫，非纯虚纯实，故攻补皆难。", ["涩", "数"]], "13022": ["病机", "脉来细数为神虚液夺、余暑未清。原文“唇红面白，肌瘦汗频”，阴液已伤而热未净，故不眠妄语、口渴耳聋。细主阴亏，数主热扰，治以清暑益气、养阴安神，则神气遂安。", ["细", "数"]], "13023": ["小儿", "小儿凛寒身热、筋瘛谵妄，脉弦细为食滞化热、肝风内动，缓滑为痰食内蕴。原文“苔色黄腻，口渴唇红”，乃停食感冒，胃不和则卧不安，阳明实则谵妄，非惊风。脉证合参，故以消食导滞、清热化痰取效。", ["弦", "细", "缓", "滑"]], "13024": ["病机", "本案未录脉象，孟英据“素用力”致络脉久伤，发热恶寒、肢振自汗为卫虚风袭，少腹气上冲胸、头疼口渴为肝风内动、津液亏耗。卫虚则藩篱不固，肝风挟冲气上逆，故见冲胸头疼；汗出耗津故口渴。治以建中去饴加龙牡石英等，正是固卫潜阳、柔肝息风之法，与脉象无直接关联。", []], "13025": ["病机", "左弦疾而促、右滑数而溢，弦主肝阳，疾促为热盛鼓动，滑数为痰热内壅。冬温挟痰阻肺，治节不伸，肝阳鼓舞直升，故痰嗽气逆、额汗颧红、胸痞躁扰。脉之弦疾促滑正合痰火类孤阳之候，非虚寒可比，故以陷胸加薤白旋覆赭石等清降痰火而瘥。", ["弦", "疾", "促", "滑"]], "13026": ["预后", "左关尺忽见浮弦而空，浮为阳越，弦为肝逆，空则根蒂不固、阴亏无守。高年下虚，肾水泛溢成痰，浮阳冲逆为嗽，似伤风而实非伤风。脉见浮弦而空，正示根本空虚、阳气外浮，故孟英私嘱可虑；后误散误清，痰升气逆，果验其言，此脉主预后不良。", ["浮", "弦", "空"]], "13027": ["病机", "脉数且涩，数为温邪热盛，涩为阴血亏少、脉道不利。患者阴虚有素，值忧劳哀痛之余，五志内燔，温邪外迫，不必由卫及气，自气而营，故初起即舌赤而渴。数涩并见，示邪热炽而真阴竭，非善证也，故急与清营凉血，然病来颇恶，势必转重。", ["数", "涩"]], "13028": ["病机", "脉象既形弦滑以数，弦主肝风，滑主痰，数主热。风温之邪顺传胃府，痰热内壅，肝风鸱张，故目闭鼻塞、耳聋肢搐、不言语不饮食，外候似神昏而实非神昏。弦滑数正合痰热风动之机，苔白滑、大解未行又示腑实未通，故治从胃府，证可无恐。", ["弦", "滑", "数"]], "13029": ["病机", "体瘦脉细数，尺中更乱。细为阴亏，数为热炽，尺乱则下焦真液溃乱不守。发热前一日陡然带下如崩，真液早经漏泄，阴气先伤，阳气独发，故气逆无寐、咳痰舌绛、耳聋谵语。细数而乱，正示阴虚阳越、液枯热炽，有痉厥之变，故以壮水潜阳为治。", ["细", "数", "乱"]], "13030": ["预后", "右寸脉促数不调，促为数中一止、脉来不匀，数为热盛。右寸主肺，风温误用温散，邪热壅肺，治节不行，故脉促数不调。孟英断其恐有骤变，越二日即见鼾睡，促数尤甚，终至语言难出而逝。此脉主风温误汗、热壅肺气之危候，预后不良。", ["促", "数"]], "13031": ["病机", "脉见芤数，芤为中空、阴血亏竭，数为热邪炽盛。患者烟瘾甚大，津液素亏，又值劳瘁悲哀，吸受温邪，故初发即胁痛筋掣、热壮神昏、茎缩自汗、舌绛无津。芤数并见，正合阴虚阳越、热炽液枯之险，根蒂不坚可知，故以壮水息风、潜阳镇逆、益气充津并治而愈。", ["芤", "数"]], "13032": ["病机", "脉犹弦滑，弦主痰饮、肝风，滑主痰热内盛。患者素患喘嗽，本元久亏，春温新邪引动旧疾，温补误投致痉厥神昏、耳聋谵语、面青舌绛、痰喘不眠，皆痰热内闭、风火相煽之象。脉弦滑示痰热未至耗散，生机尚存，故孟英以清热息风、潜阳镇逆获效。", ["弦", "滑"]], "13033": ["病机", "脉弦数右滑溢，弦主风动，数主热盛，右滑溢为痰热壅肺之征。患者年近古稀，肢厥头肿、谵语遗溺，前医误作虚风温补，势益剧。此乃痰热内阻、风温外侵，热郁于肺则右脉滑溢，风热上扰则弦数。孟英以清化痰热、疏风透邪而瘳。", ["弦", "数", "滑"]], "13034": ["病机", "右寸脉洪大，洪主热盛，大主邪实，右寸候肺，为春温初犯、邪尚在肺之象。发热面赤、渴而微汗，皆热邪内炽、迫津外泄之症。脉洪大示邪热壅盛于肺，尚未入营，故孟英因势利导，令邪从腑出，投清肺泄热之品，便泻热水后脉静身凉而愈。", ["洪", "大"]], "13035": ["病机", "两脉甚数，数主热盛，温邪初起即神气躁乱、惊惧不眠，是热邪直入营分、内扰心神之征。脉数而不浮，示邪已离表入里，非汗解所能及。孟英谓温邪直入营分，用神犀丹佐紫雪清营凉血、开窍透热，两剂而瘥，强调病无定体、药贵得宜。", ["数"]], "13036": ["病机", "脉弦大而缓滑，弦主肝风，大主邪盛，缓滑主痰湿内蕴。患者春温谵语发狂，连服清解大剂后反昏沉不语、肢冷如冰、遗溺不饮，似虚寒而实为痰热内闭、阳气不达。黄腻苔满布、秽气直喷，合脉弦大缓滑，知痰热胶结胃肠，故孟英投承气汤下胶黑矢而愈。", ["弦", "大", "缓", "滑"]], "13037": ["病机", "脉数而弦，数主热，弦主气郁痰结。患者发热独炽于头，发散后汗出不解，胸痞便滞溺艰，舌绛口干，饮不下膈，不眠头痛，皆热郁于肺、痰结于胸之象。脉数弦示热未清而气机郁滞，非风寒表实，故孟英戒羌防柴葛温散，以轻清展气化而愈。", ["数", "弦"]], "13038": ["病机", "脉来弦软而寸数，弦软主气郁痰滞，寸数主热壅于上。舌绛苔黑、神昏谵渴溺红、胸腹拒按，是温邪双传——既入阳明胃腑，又陷心营。脉弦软示正气尚耐攻，寸数示热势鸱张，故孟英谓双传当双解，以凉膈散加犀角、菖蒲、元参下之而愈。", ["弦", "软", "数"]], "13039": ["病机", "脉甚细软，细主阴亏，软主气弱，然身热头疼、凛寒胸闷、气冲不寐、口渴嗽痰、干呕便闭，显系温邪留恋、气郁痰滞。前医咸以为虚欲补，孟英谓阴分虽亏而邪不可补，脉细软乃邪郁气机、阴分受灼之象，非纯虚证，故以轻展清宣、化痰透邪获效。", ["细", "软"]], "13040": ["病机", "脉滑数而右歇左促，肝部雀啄、气口解索，是湿热误补、充斥三焦、气机壅闭之象。滑数主湿热，歇促为气机阻塞不流行，雀啄、解索乃胃气将败、真脏脉见，故见心下坚硬拒按、便溺涩滞、烦躁懊𢙐等症，邪正混淆，病势危重。", ["滑", "数", "促", "雀啄"]], "13041": ["病机", "脉软汗多，热不甚壮，原文自注“热为湿所持故脉软”，是湿温之邪蕴遏，湿重于热，阳气为湿所困，故脉象软弱不扬。苔厚腻、呕恶烦躁、痰多腿酸，皆湿温内蕴、气机不宣之候，不可从表治，更勿畏虚率补。", ["软"]], "13042": ["病机", "脉甚数，溲赤苔黄，口干燥呛，是暑湿之邪从热化，体极阴亏，热势鸱张之象。数脉主热，暑湿内蕴而化热伤津，故见溲赤、苔黄、口干呛；虽便泄而不可温燥，宜轻清肃解、甘凉撤热，误治即败。", ["数"]], "13043": ["病机", "脉软数，发热身黄，是湿温重证。软为湿邪困阻，数为热邪内蒸，湿热交蒸故初起即黄。湿热下行则便溏溲赤，热减；若辍药复热，谵语昏聋、抽痉遗溺，则湿热之邪扰营，宜泄卫清营。", ["软", "数"]], "13044": ["病机", "原文未识脉名，仅言“按其脉肤甚热”，是湿热时邪郁蒸肌肤之象。睾丸肿痛偏右，非疝也，乃湿热下注，误用茴香、芦巴等温燥则痛不可忍。脉肤热为湿热外达之征，治当清解湿热，设以疝治必成痈。", []], "13045": ["病机", "脉左寸数疾，余皆软大，舌尖独黑，苔腻黄，是平昔曲运心机、离火内亢、坎水不制之象。左寸数疾主心火炽盛，软大为湿温之邪弥漫，火亢水亏兼感湿温，势必自焚，故虽证原不重而预后凶险。", ["数", "疾", "软", "大"]], "13046": ["病机", "脉形歇代，而弦搏有根，是得乎天者厚，虽高年犹为实象。歇代为脉气不续，然弦搏有根则非真脏败脉；病深声哕、二便窒涩、苔腻而灰，乃痰湿热阻其气化流行之道，府气未宣，清宣展布尚可图治。", ["歇", "代", "弦"]], "13047": ["病机", "脉软神疲，是内湿素盛、兼吸客邪，湿困阳气之象；其子脉数而弦，寒微热甚，为疟邪内蕴、痰热交争之候。软主湿盛，数弦主热与疟邪，故见身热头重、腹胀便溏、口流涎沫，及耳聋舌绛、溺赤痰多等症。", ["软", "数", "弦"]], "13048": ["病机", "脉虚软微带弦滑而不甚鼓指，非阳气不足之虚寒，乃痰阻清阳、气壅脉道所致。原文谓“脉证太觉悬殊”，正因痰浊内阻，脉气不伸，故虽见壮热神昏、溲赤便秘等实象，脉反无力。治以小陷胸合雪羹加涤痰之品，痰吐后脉较起，可证脉虚软为痰阻而非真虚。", ["虚", "软", "弦", "滑"]], "13049": ["病机", "脉伏胸痞由滋腻阻塞气机、痰饮闭滞隧络所致，非脱象也。原文明言“清阳不司旋运”“非脱象也，补药不可进”，故脉伏为邪闭气机、清阳不展之征，与呃忒自汗、渴饮不食并见。投通降涤痰后“呃止脉出”，反证脉伏属闭阻而非虚脱。", ["伏"]], "13050": ["病机", "脉形空软促数，乃冬温失于清解、误服辛热致营血暴脱于下。空软为血脱脉失充盈，促数为热邪未清而营阴骤伤，故苔黑舌绛、足冷息微。原文辨此非热入血室，乃“营血暴脱”，脉空软正是血去脉虚之象，与崩血一阵相应。", ["空", "软", "促", "数"]], "13051": ["病机", "脉滑且数，主温邪挟宿饮上逆。滑为痰饮内蕴，数为温邪炽盛，故见头疼发热、渴饮不饥、谵语神昏、面赤痰喘。原文谓“温邪挟宿饮上逆，法当清解”，脉滑数正合痰热交阻之机，非虚寒所宜附桂，故以清解涤痰取效。", ["滑", "数"]], "13052": ["病机", "形瘦脉数，舌色乾红，为阴虚热胀。数脉主热，然此热由阴亏而生，非实热可攻。原文谓温补“阴愈耗，络愈痹，胀虽不加，而肌愈削，脉愈数”，指出误补后脉数愈甚，正是阴液日耗、虚热愈炽之征，终致干呛气急而不起。", ["数"]], "13053": ["病机", "左数右滑皆极虚软，乃积劳久虚之体，肝阳内动，烁液成痰，逆升而厥。数主热，滑主痰，虚软为正气不足，故虽感冬温而邪尚轻微，却现昏沉如寐、俨似温邪内陷。原文谓“肝阳内动，烁液成痰”，脉虚软数滑正合虚体痰热内动之机。", ["数", "滑", "虚", "软"]], "13054": ["病机", "脉弦缓，非娠非损，乃血虚痰滞而感冬温。弦为痰滞气机，缓为血虚脉道不充，故产后经未行而腹不胀，反见呕吐发热、眩晕心嘈、溏泄溲痛。原文以脉弦缓断其非孕非损，正是凭脉辨血虚痰滞之据，故以清解化痰调之而愈。", ["弦", "缓"]], "13055": ["病机", "原文未识脉名，然述冬温挟痰、误提而气不肃降，致目瞪不语、面赤气逆、昼夜抱坐。其病机在痰热壅阻、肺气不降，故以旋赭杏贝等肃肺涤痰降逆，三帖大便行而能卧。虽无脉象可录，然症候与治法已明示痰热上逆、气机不降之机。", []], "13056": ["病机", "脉细数而弦，细为阴伤，数为热炽，弦主肝郁。本案冬温伏邪，前医误认中虚寒湿，投参术附桂温补，致舌黑神昏、舌缩底绛，显系温邪化火、阴液耗伤。脉细数而弦正是热盛阴亏、肝阳偏亢之象，与‘阳盛之象’‘火证偏多’相合，故非虚寒，乃温病误治之坏证。", ["细", "数", "弦"]], "13057": ["病机", "脉滑数而洪，滑主痰，数主热，洪为阳盛。本案冬温，面赤音低、大渴溺赤，显系肺胃热炽；苔白不燥、便泻如水，乃伏痰内蕴、肺热下迫大肠。脉滑数而洪正合痰热壅盛、邪势鸱张之机，故以犀角、元参、旋覆等清解肺卫、化痰泄热而愈。", ["滑", "数", "洪"]], "13058": ["病机", "脉虚数而弦，虚为真阴素亏，数为燥热内伏，弦主痰气郁结。本案年逾花甲，冬温伏邪，初服温散致苔黑，继投白虎而胸胁大疼、面赤不眠，乃枢机窒滞、气道未舒。脉虚数而弦正示阴液耗伤、痰多气郁，非白虎汤仅能涤热者所宜，故以展气开痰、潜阳镇逆取效。", ["虚", "数", "弦"]], "13059": ["病机", "脉数而虚，继则脉尚数、脉数渐退、脉甚细软，数主热，虚细软主营阴亏耗。本案冬温，营分素亏，肝阳烁液，痰阻枢机，故脉数而虚；经变法治之，热退而脉数渐退，终现细软，乃邪退正虚、阴血未复之象，故渐参养血而安。", ["数", "虚", "细", "软"]], "13060": ["病机", "脉数而弦，数主温邪内炽，弦主肝旺血虚；继则弦数而涩，涩为血少气滞；终至弦细而缓，细为阴伤，缓为胃气渐和。本案冬令伏邪发为温病，血虚肝旺，故脉数弦；庶祖母年高，脉弦数而涩，乃血虚气郁、邪阻枢机之候，与脘闷便秘、少腹瘕痛相应。", ["数", "弦", "涩", "细"]], "13061": ["病机", "脉极沉重，按至骨则弦滑隐然，沉主里，弦主饮，滑主痰。本案阳痿多年，频吐白沫，体怯面青，显系阳虚痰饮内伏；沉取弦滑，乃痰饮深踞、阳气不布之象。虽见恶寒头痛，非外感表证，故温散不效，当从痰饮虚寒论治。", ["沉", "弦", "滑"]], "13062": ["病机", "脉细而滑数，细为阴伤，滑主湿，数主热。本案年近古稀，囊肿溲赤，寒热如疟，乃久蕴湿热下流、气机未宣。脉细滑数正合阴虚湿热内蕴之机，故以五苓合滋肾加楝实、栀子、木通清利湿热，两剂后囊出黄水、小溲渐行而愈。", ["细", "滑", "数"]], "13063": ["预后", "原文未识脉名，仅言‘及诊其脉，许以可生’。本案痰嗽夜热、自汗不寐、左胁痛如针刺、肌削，病来虽恶，但未经误药，脉象当有胃气，故断为可生。孟英以固本加龟板、鳖甲、苁蓉等大剂育阴潜阳、化痰止咳，连服四五十帖而痊，示脉证相参、未误药者预后尚佳。", []], "13064": ["病机", "脉滑数，滑主痰湿，数主热，合示湿热下注、灼伤血络。患者溺后出血水甚痛，虽溲长激似非火证，然脉滑数明示火邪内蕴，故孟英用元参、生地、犀角、栀、楝等清热凉血利湿之品，旬日而痊。脉象与溺血涩痛相应，证实热迫血妄行之病机。", ["滑", "数"]], "13065": ["病机", "脉弦数，弦主肝郁气滞，数主热，合示肝经郁热、湿热蕴结。赤痢延至暮春，苔黄渴饮、腹胀而坠、五热夜甚，皆热郁营血之象。孟英用白头翁汤合金铃子散加芩、芍、栀、斛，清肝凉血、行气止痛，浃旬而愈。脉弦数正合肝热下迫大肠之病机。", ["弦", "数"]], "13066": ["病机", "脉伏恶寒、四肢厥逆，俨似阴厥，然渴饮溲赤，真情已露，脉伏乃热邪深遏、阳郁不达所致，非虚寒也。迨后脉显滑数，滑数主热，证实热内蕴。孟英径投凉解，热邪下行泻出红水，终以白头翁汤加味清解而愈。脉伏之证须参渴饮溲赤，方不泥于寒厥。", ["伏", "滑", "数"]], "13067": ["病机", "右关尺弦大而滑，弦主痰、大主热、滑主痰湿，合示痰热内蕴、伏暑在里。腹中绞痛、泻血如注、面色油红、喘逆不寐，皆痰热壅盛、迫血下行之象。孟英用苇茎汤合金铃子散加银花、侧柏、芩、连，清化痰热、凉血止血，二帖面红退血止。脉弦大滑正合痰热内盛之病机。", ["弦", "大", "滑"]], "13068": ["病机", "脉洪大，洪主热盛，大主邪实，合示热邪壅肺、气分热盛。陈叟久患痰嗽气逆，夏初恶寒，误服理中汤温补，遂痰中带血、气喘而厥、二便不通、冷汗腹胀，皆热结在肺、腑气不通之危候。孟英察脉洪大、按腹如烙，用苇茎汤加栀、楝、旋、贝等清肺化痰，外贴脐下通溺而平。脉洪大正合肺热壅盛之病机。", ["洪", "大"]], "13069": ["病机", "脉虚细，虚主气血不足，细主阴血亏少，合示阴虚血少、筋脉失养。两膝后筋络酸痛而不红肿，卧则痛不可当，苔黄腻、咽燥溺赤，乃阴虚于下、火炎于上。孟英用知、斛、栀、楝等煎剂治其上，送虎潜丸培其下，旬日而瘳。脉虚细正合阴血亏虚、虚火内扰之病机。", ["虚", "细"]], "13070": ["病机", "脉滑实，滑主湿浊，实主邪盛，合示湿热壅结、腑气不通。发热清解后腿肿异常、身面渐黄、腹胀口干，皆湿热郁蒸发黄、腑实内结之象。孟英用茵陈大黄汤，两剂便行而各恙霍然。脉滑实正合湿热内结、阳明腑实之病机，故以通腑泻热取效。", ["滑", "实"]], "13071": ["病机", "脉弦劲，弦主肝郁，劲主肝阳亢逆，合示肝阳化风、风火上扰。左目胞起瘰，痛及眉棱、额角、巅顶，脑后筋掣难忍，舌绛不饥，皆肝阳上亢、风火循经上攻之象。医投风剂反剧，孟英用固本合二至、桑、菊、犀、羚、牡蛎、鳖甲等育阴潜阳、凉肝息风，匝月始愈。脉弦劲正合肝阳亢逆之病机。", ["弦", "劲"]], "13072": ["病机", "原文「按其脉，沉取滑数，是从前之积热，深伏于内」。沉取始得滑数，说明热邪深伏于里而非表热；滑主痰热内蕴，数主热盛。久服姜食积热于内，虽凉药暂瘥而火升不愈，故见身不衣绵、头面汗出，服芩连反烦渴，皆积热深伏、苦寒化燥之征。", ["沉", "滑", "数"]], "13073": ["病机", "原文「切脉，洪实滑数，舌绛大渴，腹微张」。洪为热盛气分，实为邪实壅盛，滑数主痰热内炽。目赤渐至满面红肿、壮热神昏，是热毒充斥阳明、上扰神明之候；腹微张示腑实内结。故以酒洗大黄、犀角等两下而愈，脉证相合。", ["洪", "实", "滑", "数"]], "13074": ["病机", "原文先言「脉弦而滑，舌绛口干」，后察「弦数倍常」。弦主肝旺，滑主痰，数主热，合示阳旺气血有余、伏热内蕴。久患淋漏风斑、崩后广服温补酿病，皆肝经郁热、血分有火之征；寒热如疟、苦渴易饥，亦痰热内扰、肝阳偏亢之象。", ["弦", "滑", "数"]], "13075": ["病机", "原文「脉之，沉弦而缓，作痰热内伏」。沉主病在里，弦主痰饮郁结，缓非虚寒之缓，乃痰热内伏、气机壅滞之象。外寒覆衾而内热渴饮、便溺皆行，投温散即咽痛，正合痰热伏于内、误温则火上炎之机，故以犀羚清透而瘳。", ["沉", "弦", "缓"]], "13076": ["病机", "原文「诊脉，弦劲而数，乃热伏厥阴，误治而肺亦壅塞也」。弦劲为肝经热盛、气火亢逆之象，数主热。汛愆寒热误投温补，致腹胀带淋溲涩，是热伏厥阴、下迫州都；肺亦壅塞则气化不行。故以清肃开上合当归龙荟丸泻肝而安。", ["弦", "劲", "数"]], "13077": ["预后", "原文「脉洪数无伦，右尺更甚」，后「三日后，脉证渐和」。洪数为热盛，无伦示热邪充斥、脉失常度，右尺甚则热在下焦。气逆神昏、汗多舌缩乃燥补误治、热陷心营之危候；服药后脉证渐和，是邪退正复之兆，故本段重在凭脉判预后转归。", ["洪", "数"]], "13078": ["病机", "原文「脉甚滑数，曰：此热毒逗留阳明之络，陷入冲脉」。滑主痰热，数主火，合示热毒久蕴。五心热、黑苔不退、口苦而渴、经来色黑，皆热毒入冲脉、隶于阳明之征；月事时下为宣泄之路，故久蕴未为大患，汤剂难搜隧络之热。", ["滑", "数"]], "13079": ["病机", "原文「循其脉，虚软微数，左兼弦细」。虚软为营分素亏、正气不足，微数主伏热内扰，左弦细应肝阴亏而络脉郁滞。孀居年高、汛至如崩，本营亏之体；少腹块痛、发热谵语、呕渴，乃伏热阻于隧络。故重药碍投，取轻清通络、养营泄热。", ["虚", "软", "微", "数"]], "13080": ["病机", "脉软涩而不鼓指，右手尤甚，似虚寒而实非。软涩为气血郁滞、热伏于内之象，故虽肢厥便溏似寒，却见舌紫苔黄腻、口苦、眼鼻出火，乃真阴素亏而伏热内蕴。热郁气机则脉不鼓指，非阳虚也。孟英断为伏热，用栀连桑菊等清透而愈，脉亦较和，正合热退气机渐畅之机。", ["软", "涩"]], "13081": ["病机", "脉缓大而滑，苔黄腻，脘下拒按，乃痰热内壅之候。体丰多痰，暑湿挟痰阻于中焦，气机失降，故茎缩溲闭、气喘大汗、眩晕不支，皆痰热上逆、气机闭塞所致。脉缓大而滑正是痰涎壅盛之征，非虚也。予菖枳旋蒌等涌吐痰涎，一剂喘汗平，二剂溲畅，脉证相合。", ["缓", "大", "滑"]], "13082": ["病机", "脉弦数而驶，按胸下坚且痛，舌绛根苔黄滞，乃汗下伤阴而府实犹存之候。弦数主热，驶为热盛急迫，牢涩示坚积内结。前医误补误滋，致热锢府实，身难转侧。孟英以善药通之，下坚黑矢夹瘀血而热缓，证明脉弦数驶与府实坚痛相应，非纯虚可补。", ["弦", "数", "驶", "牢"]], "13083": ["病机", "脉则右大，热甚于颈面，形瘦口干，时犹作嗽，乃肺热不清之候。右脉主肺，右大者肺中热壅气浮也。前医误作劳损，久服养阴滋腻，反锢其热。孟英断为肺热，以芩栀地骨桑叶等清降，热汗递减，解酱矢赤溲而愈，可见右大之脉主肺热壅盛，非虚劳之象。", ["大"]], "13084": ["病机", "脉来甚涩，四肢发热，食减便溏，汗多形瘦，孟英断为热厥，且谓前此必误服补药。涩脉主气机郁滞、血行不畅，热邪内郁，阳气不达四末则四肢发热；误补则壅塞愈甚，故脉涩。以芩栀连柏等清透郁热，十余剂而瘥，证明涩脉在此主热郁，非虚寒也。", ["涩"]], "13085": ["病机", "脉来浮弦软数，尺中甚弱，舌绛无液，稍有黄苔，乃真阴素亏、暑热化疟未清、扰及中州之候。浮弦软数主暑热挟虚，尺弱示真阴不足。吐泻交作、肢冷自汗、谵语，皆伏热内扰、津液受劫之象，非元虚寒证。孟英力辨香燥温补之误，正合脉数舌绛、泻色酱热如火之伏热据。", ["浮", "弦", "软", "数"]], "13086": ["病机", "脉甚虚软，舌紫滑泽无苔，溲频浓赤不禁，阴茎已缩，两手紫黯，乃心阳过扰、热伏厥阴之象。虚软似虚寒，然溲赤、阴缩、手紫皆热郁之征，不可因恶寒而认作真伤寒。孟英以葱豉茹芩轻解其外，继以养阴清热，下坚矢而舌干谵语，正见热伏阴伤之机，脉虚软为热扰而气不充，非阳虚也。", ["虚", "软"]], "13087": ["病机", "脉软滑而微长，苔淡黄不渴，仅能仰卧，反侧不能，乃热伏阳明之候。软滑主痰热内蕴，微长示气机尚存、非虚劳之脉。前医频服滋填无效，因热伏阳明，机关不利，筋骨不束，故见暮热鼻衄、羞明溲浑。衄血溲浊为热气宣泄之路，故人不甚枯削。以槐蕊知柏芩栀清透阳明而渐愈，脉证相符。", ["软", "滑", "长"]], "13088": ["预后", "脉极弦细而促，弦为肝郁，细为阴伤，促为热盛而数中一止，是邪热深入营分、阴液耗损之象；更兼舌绛大渴、小溲赤少、饮而不食，证实脉虚，正不胜邪，故孟英坚辞不治，属预后不良之候。", ["弦", "细", "促", "虚"]], "13089": ["病机", "脉沉滑而数，沉主里，滑主痰湿积滞，数主热，合之痢下五色、少腹结块攻痛、大渴无溺，显系温补误投，邪浊蟠踞下焦，气滞血瘀，湿热壅遏之病机，非初起停滞可比。", ["沉", "滑", "数"]], "13090": ["病机", "脉甚弦，重按则滑，弦为厥阴肝经气郁，滑为暑热内伏，故断为热暑伏厥阴；头痛三日一发、发则恶寒，乃暑热郁遏、肝阳上扰所致，温补则助热，故以左金、龙荟丸清肝泻热而愈。", ["弦", "滑"]], "13091": ["妇人", "脉形滑数，滑为孕脉，数主热，舌黑神昏、大渴便泄、臭痰频吐，似属危候，然脉滑数而气息调和，是伏暑内热未伤胎元，故断胎尚未坏，重用气血两清，暑热解则胎安。", ["滑", "数"]], "13092": ["病机", "脉滑数，舌绛苔黄，渴饮溲赤，动则喘逆，痰多畏冷，是膏粱酿痰、温补助热，又吸暑邪，痰热互结，肺胃气壅之病机；滑主痰，数主热，故以清化痰热为治。", ["滑", "数"]], "13093": ["病机", "左脉弦劲而数，右滑大不调，弦劲为肝胆风阳上僭，数为热，滑大为痰热有余；症见面浮跗肿、喘嗽易嗔，显系肺胃痰热与肝胆风阳交炽，非虚候，故畏虚率补必误。", ["弦", "劲", "数", "滑"]], "13094": ["病机", "脉数溺少，神昏谵语，舌绛耳聋，频吐白沫，渴饮不饥，热微汗出，是暑邪传营，气分未廓，敷布无权，故水不下行而为溺少，旁溢为汗，上行为沫；数脉主热，示邪热内陷营分。", ["数"]], "13095": ["病机", "脉洪弦而兼滑数，洪为暑热炽盛，弦为肝郁，滑数为痰热；症见肢瘛腹痛、卧则昏谵、膈间痞闷、舌紫肿苔厚腻黄，是暑湿内蕴，肝气素郁，肺胃多痰，升降失常，邪气壅塞之病机。", ["洪", "弦", "滑", "数"]], "13096": ["病机", "脉形滑数，滑主痰热，数主热盛。患者年高患感，热退后误用滋养，致热复壮神昏，舌心已黑，溲赤干呕，粥饮不入，显系痰热内蕴，蒙蔽心包。滑数脉正是痰热交阻之征，故治以清热化痰开窍，数帖霍然。", ["滑", "数"]], "13097": ["预后", "脉微细欲绝，而呼吸甚促，按心下坚且痛，乃阴液下脱，阳气欲绝之候。初治失于开泄，胸中痞结，津液不能敷布，尽从下脱，攻补皆难措手。微细欲绝为气血衰微之死脉，故曰疾不可为，翼日果殒。", ["微", "细"]], "13098": ["病机", "初脉形涩滞，乃伏暑晚发而本元极亏，涩主气滞血少。药后脉来软而且涩，软为虚，涩为滞，示邪未尽而正已伤。三服后脉转弦数，弦主热郁，数主热盛，故见谵语不休、夜间热炽、肢凉头晕，浊热上熏。脉象演变反映伏暑化热、浊邪上攻之病机。", ["涩", "软", "弦", "数"]], "13099": ["病机", "脉形滑数，滑主痰湿，数主热盛。劳力人发热，左胁疼，咳嗽碍眠，痰出甚臭，苔黄舌绛，渴饮谵语，便秘溲赤，乃伏暑证。询其嗜饮醉卧，湿热酿痰久积于左，非内痈。滑数脉正合痰热内蕴之机，故以苇茎汤加减清化痰热而瘳。", ["滑", "数"]], "13100": ["病机", "初脉细数而涩，细为阴伤，数为热，涩为气郁，乃暑湿内伏，气郁不宣。药后脉转弦细而数，弦主热郁，细主阴伤，数主热盛，口转发渴，示郁热渐透。终至脉和溲畅，乃邪退正复之象。脉象由细涩转弦数再转和，反映暑湿郁热渐解之过程。", ["细", "数", "涩", "弦"]], "13101": ["病机", "脉数而弦，数主热盛，弦主气机郁滞。朱氏妇赤痢匝月，痢止后胸头痞胀，米饮不沾，口渴苔黄，溲热而痛，凛寒身热，夜不成眠，神惫形消。乃伏暑未清，营津已劫，气机窒塞。数弦脉正合热郁气滞之机，故首议清泄，终用清养而痊。", ["数", "弦"]], "13102": ["病机", "脉滑右甚，滑主痰湿，右甚则病在气分。钱君寒热时作，自服柴桂病益甚，狂躁欲啖西瓜，苔色腻黄，便秘溲短，胸痞不沾粒米。乃暑湿夹痰阻于气分，非白虎汤证。滑脉为痰湿内阻之征，故治宜开泄，用蒌薤枳朴等，二便畅而胸次豁然。", ["滑"]], "13103": ["病机", "脉滑而洪，滑主痰食，洪主热盛。患者寒热时作，汗多不解，便溏不畅，溲赤妄言，面黑如煤，苔黑大渴，烦躁气逆，按心胸坚硬而痛。乃暑湿夹痰食也。群医误进寒凉，不知气分尚结。滑洪脉正是痰食热结之征，故以小陷胸加味开泄而愈。", ["滑", "洪"]], "13104": ["病机", "原文未直接描述脉象，但孟英切脉后指出“高年之体，元气随泻而泄，固当补者。第余暑未清”，说明病机为高年元气随吐泻而泄，兼有余暑未清。前医误作寒证，孟英以脉辨其非寒，强调暑邪未净，不可纯补，当兼顾余暑。", []], "13105": ["病机", "脉微弱如无，伴耳聋目陷、汗出肢冷、音哑肌削，乃吐泻甚而津液伤，误服苦寒致微阳欲绝。脉微弱如无主阳气衰微、津液耗夺，故见危象毕呈。孟英以参附回阳、顾护津液，后述“气分偏虚，那堪吐泻之泄夺”，正合此脉。", ["微", "弱"]], "13106": ["病机", "脉伏无溺，伴目陷神消、肢冷音飒、口渴汗多、腹痛苔黄，乃伏暑内闭，热深厥深，气机不通所致。脉伏非阳虚，而是暑热胶锢、阳气不能外达。孟英取西瓜汁、白虎加芩连柏等，清透伏暑，复杯即安，证明脉伏主热闭而非寒脱。", ["伏"]], "13107": ["病机", "脉极弦驶，为肝阳内炽、暑热外侵之象。弦主肝阳，驶数主热盛，故见头疼如劈、溺血如注、自汗息微。孟英断为肝阳内炽，暑热外侵，用犀角、龙荟丸清肝泻火。后案脉弦数、苔黄口苦，亦属肝火湿热，脉弦数主肝胆热盛。", ["弦", "数", "驶"]], "13108": ["病机", "脉右甚滑数，右脉主气分，滑主宿食痰浊，数主热。患者食冷鱼后发病，脐贴回阳膏不效，胸下坚硬而痛，口渴苔黄，说明宿食恋膈、郁而化热，非寒证。脉滑数正是宿食内停、热邪壅滞之征，故以消食清热取效。", ["滑", "数"]], "13109": ["病机", "脉数而芤，数主热盛，芤主阴血亏伤。患者受暑，裸卧昏狂、舌黑大渴、溺赤便秘，暑热深入血分，耗伤阴血，故脉数而芤。孟英用犀角地黄汤加减凉血解毒，神识转清。后虽目张睛瞪、齿露唇焦而亡，然脉数芤确主暑热伤血之病机。", ["数", "芤"]], "13110": ["病机", "脉伏自汗，四肢渐冷过肘膝，二便不行，乃酷热啜冷，冰伏胸中，大气不能转旋，阳气不达四末所致。脉伏非阳虚，而是暑热为冷饮所遏，气机闭塞。孟英用六一散、紫雪丹辛香通闭，次日脉见胸舒肢热，证明脉伏主冰伏气闭之病机。", ["伏"]], "13111": ["误治", "原文未直接描述脉象，但孟英指出“阴虚之质，暑热胶锢，殆误投补药矣”，病机为暑热内锢，前医不察外来之疾，误投熟地等滋腻温补，致邪气胶结难解。孟英强调暑热证必邪到血分始可议用生地，初病即进熟地，如油入面，终致不救。", []], "13112": ["病机", "原文未录脉象，然述暑伏脾胃而误投温补，致津气灼烁殆尽、脂液奔迫妄行、治节无权、阳明涸竭。温补阴柔腻滞挟制暑邪，使不能遽变而深伏，终成不饥不食、二便不行、肌肉尽削、带下如溺之候，故以白虎加参清透暑热为主治。", []], "13113": ["误治", "原文未载脉，述五龄儿暑邪发热，医以柴葛解肌风药发之，热得风而焰烈，津受烁以风腾，风药引起肝风，致肢搐而厥、目张不语。此风药误治引动肝风、耗烁津液之变，故用犀角地黄加羚羊、石膏等凉肝息风、清热生津而痊。", []], "13114": ["病机", "脉涩兼沉弦以数，涩主血滞，沉弦主郁，数主伏热。抑郁致气机不宣，暑邪内伏，误投归芎血药引邪深入，血为邪踞而不流行，故左胁下少腹梗塞不舒。病虽在血而治宜清气为先，气得宣布则热象露、瘀滞行，故连投清气而热渐壮、谵妄不眠。", ["涩", "沉", "弦", "数"]], "13115": ["主病", "脉滑实而数，滑主湿痰，实主邪盛，数主热。淫雨湿甚，医但知湿不知化热，投平胃散而壮热昏狂，湿郁化热成湿温暑疫之候。大渴溲赤、稀水旁流，皆湿热内盛之征，故以石膏、大黄下之而愈，并推甘露消毒丹、神犀丹分治气营。", ["滑", "实", "数"]], "13116": ["病机", "脉甚滑数，苔色腻黄，滑主痰，数主暑热，乃平素多痰兼吸暑热之候。化疟后脉较平，而暑脉颇类乎虚，痰阻于肺呼吸不调又与气虚短促相似，故辨其非虚。热能伤气，清暑热即所以顾元气，故坚持不可用参，连投白虎加减而愈。", ["滑", "数"]], "13117": ["病机", "原文未录脉象，据晨泄有年、春间尤甚、泻后腹中反觉舒畅、服四神附桂泻必加，断为肝强脾弱、木土相凌，非温升补涩之证。泻后畅、不泻则胀闷减食，正是肝木乘脾、气机郁滞之征，故用白术苡仁扶脾、黄连楝实蒺藜抑肝，制方灵动。", []], "13118": ["病机", "体丰脉不甚显而隐隐然弦且滑，弦主肝强，滑主痰盛，故断为肝强痰盛而非虚寒。久泻脘痛齿痛、汛事不调、极其畏热，肌肉不瘦、冬不知寒，皆非阴阳虚损之象。痰之为病最顽，病根深锢不可妄补，故力排众议，主张攻其痰病。", ["弦", "滑"]], "13119": ["主病", "脉数大渴，汗多苔黄，数主热盛，渴汗苔黄皆阳明热炽之征。发热泄泻十七日，骨瘦如柴、音嘶气逆，乃热盛耗津、肺热移于大肠之候。故以竹叶石膏汤加减清泄气分邪热，十余剂向愈，继以滋养而康。", ["数"]], "13120": ["病机", "脉沉数，沉主里，数主热，此伏邪内蕴之象。原文言“病起泄泻，何必为寒？正是伏邪自寻出路”，误投温补则“固留之”，致邪“内陷厥阴”，发热昏痉、咽喉黑腐。脉沉数正是热伏于里、不得外达之征，与泄泻、发热、昏痉相应，说明温补致邪闭厥阴之病机。", ["沉", "数"]], "13121": ["病机", "脉迟缓而浮取甚微，迟非寒，乃暑湿内伏、燥矢在胃，气机不利使然。原文谓“暑湿内伏，而有燥矢在胃，机关为之不利”，故脉见迟缓微弱，症见便溏、静卧、不食、语懒音低。此湿胜于热之暑证，脉不显热象，最足眩人，断为暑湿，足征卓识。", ["迟", "缓", "微"]], "13122": ["兼症", "脉细而弦，细为阴血不足，弦为肝木偏旺。患者素患肝厥，仲夏患感，大便泄泻，渴饮痰多，不饥不寐。原文自注“泄泻乃湿温应有之证”，脉细弦示肝风内动、阴液受灼，故以白头翁汤加三甲、石斛等清肝潜阳、养阴安神而安。", ["细", "弦"]], "13123": ["病机", "暑脉微弱，非虚也，兼数象则属暑热内蕴。原文云“暑脉微弱，不可谓之虚也。且兼数象，参不可投”，高年阴亏，暑热挟痰，故见泄泻、发热、神思不清、自汗呕恶。后案脉弦滑而数，面赤不瞑，苔黄腻，胸下拒按，为痰热肝火为患，脉象与症候相合。", ["微", "弱", "弦", "滑"]], "13124": ["病机", "脉至弦硬，舌赤无津，乃风阳内炽、津液耗伤之候。原文谓“香燥忌投，法宜濡润，否将阴涸”，故以甘凉濡润之剂。后“脉硬虽和，极其弦细”，是阴液未复、木火失涵，弦细为阴亏木旺之象，与舌不能伸、心摇语蹇、不眠头晕相应。", ["弦", "硬", "细"]], "13125": ["预后", "脉虚弦而空软，虚为正气亏，弦为木旺，空软则阴血枯竭、胃气将败。患者久患羸弱，腹痛便泻，恶谷形消，脉证相合，故断“不可为矣”，又虞“明年春令”木旺之时。虽以参、鳖甲、乌梅丸等扶正柔肝，暂得便坚食进，终属危候。", ["虚", "弦", "空", "软"]], "13126": ["病机", "脉微弱，中气固虚；左手及右尺沉取弦数，为风阳内扰、湿热蕴结之象。原文谓“中气固虚，理应投补，但不可佐滋腻以滞中枢……又不宜杂燥热以煽风阳”，故以补运兼施、宣清升降之法。脉证合参，眩晕形消、舌深紫、腹胀溲赤、泻必肠鸣，皆虚中挟实之候。", ["微", "弱", "弦", "数"]], "13127": ["病机", "脉弦数，弦为肝旺，数为热，乃土受木乘、温补益广病机之候。原文谓“非菜之罪也”，头痛带多、脘疼食少、吐酸痰嗽、五热不眠，无非八脉无权、风阳偏盛。后案脉甚滑数，面赤口干、足冷溲热、耳鸣无寐，为湿热内蕴、药病相争，幸能安谷，故可清热坚阴。", ["弦", "数", "滑"]], "13128": ["病机", "脉软而弦，软为气虚，弦为木旺，此脾虚肝乘之象，故久泻带血；其季郎脉弦数，乃阴亏水不涵木，心火内炽，肺金受戕，兼客邪胃浊不降，故见上溢气冲、血腥喘汗、睛红面黧足冷等症。", ["软", "弦", "数"]], "13129": ["病机", "脉弦数而尺滑，弦数主肝热，尺滑为湿浊下注，此肝热风行于胃，液走阴亏，故带盛口干、腰酸咽痛、溲热善噫、肢冷畏烦，乃热郁湿滞、阴血日损之候。", ["弦", "数", "滑"]], "13130": ["病机", "脉软微弦，软为气衰，微弦为木侮，此中虚木侮、生化无权，气久虚而血将涸，故便泻肠鸣、不饥不渴、形消色瘁、经事渐稀，治当砥柱中流、镇风轮。", ["软", "弦"]], "13131": ["病机", "脉数而左寸关兼弦大，数主热，弦大为心肝阳扰，此过扰心阳、兼伤谋虑，阴亏火旺，复吸暑邪，故发热纳阻、溲短便溏、气逆嗽痰、咽疼肿，药误滋填则病增。", ["数", "弦", "大", "细"]], "13132": ["病机", "脉洪大滑数，洪大为阳明热盛，滑数为暑湿内蕴，此暑热为患，阳明暑疟，与伤寒三阳合病同符，故汗出昏厥、妄语遗溺，治宜清热益气。", ["洪", "大", "滑", "数"]], "13133": ["病机", "脉沉而滑数，沉主里，滑数为痰热内蕴，此暑湿失解，温补助邪，酿成痰饮盘踞三焦，气机阻塞，故恶寒日甚、胸腹痞闷、喜热熨而冷气上冲、吐黏痰，苔黄腻不渴。", ["沉", "滑", "数"]], "13134": ["病机", "脉芤而稍有歇止，芤为暑伤气阴，歇止为痰湿阻气机之流行，此暑湿挟痰盘踞，气血受扰，故疟发而便血，治宜清解蠲痰，攻去其痰使邪无依附。", ["芤", "歇止"]], "13135": ["病机", "脉弦而细，尺中甚数，弦细为阴亏，尺数主少阴热，此足少阴热疟，阴液受灼，故寒少热多、间日而作、形消口干嗜饮，治当滋阴清热。", ["弦", "细", "数"]], "13136": ["病机", "脉伏口渴，乃暑热内炽，热邪深伏，气血壅滞，脉道不利，故脉伏；热盛伤津，故口渴。此非寒证，乃暑热内闭，热深厥深之象，故主暑疟热炽神昏、胸高气逆、溺赤便闭等症。", ["伏"]], "13137": ["病机", "脉伏因痰阻气道，气血不得宣通；痰去后脉见弦滑而数，弦主疟，滑主痰，数主热，示暑热痰湿内蕴。故先以礞石滚痰丸开导，痰出脉显，继清暑热。", ["伏", "弦", "滑", "数"]], "13138": ["病机", "脉洪滑无伦，洪为暑热燔灼，滑为痰湿内盛，无伦形容脉来洪滑过甚，主暑热挟痰湿内扰，故见疟剧、目赤狂言、汗如雨下，舌深黄厚燥，为阳明热盛之候。", ["洪", "滑"]], "13139": ["病机", "脉沉细而数，尺为甚，沉细主阴伤，数主热，尺甚示暑热深入足少阴肾经，劫烁肾阴，故口渴、目不欲张、腰收痛如锥刺、心慌，乃暑入少阴之证。", ["沉", "细", "数"]], "13140": ["预后", "脉细硬如弦，毫无胃气，细硬为阴伤津涸，弦为疟邪未透，无胃气则生机已竭；右尺洪数，为肾阴亏而热炽。此温补劫津，邪炽阴亡，故预后不良，逾日果殁。", ["细", "硬", "弦", "洪"]], "13141": ["病机", "脉软为湿邪内蕴，正气未伤，苔腻亦湿象，故断为伏邪所化，非正疟。软脉主湿，湿阻气机，故治以化湿清热，忌风寒温燥，姜枣亦不可啜。", ["软"]], "13142": ["妇人", "右脉洪滑，为暑热内盛，胎气未损；脉形细数，示热伤阴分。此妊妇患疟，伏暑为病，育阴滋腻，小柴胡辛温，均非所宜，故以竹叶石膏汤清暑保胎。", ["洪", "滑", "细", "数"]], "13143": ["病机", "脉微无神，为精气神三者交虚，阳气衰微，故倦卧奄奄、便秘溺赤、痰多口甘、苔黑腻蒙茸，乃牝疟日久，正虚邪恋，非伏暑实邪，故用温补大剂。", ["微"]], "13144": ["病机", "脉滑主痰湿内蕴。患者牝疟月余，腹胀便秘、嗳多不饥、口淡，显系湿浊困阻中焦，气机不畅，痰湿内聚，故脉见滑象。孟英以连、朴、橘、贝等化湿痰、理气机而瘳，正合滑脉主痰湿之机。", ["滑"]], "13145": ["病机", "脉数无伦，乃温散补燥诸药助邪烁液，热邪亢盛，扰乱心神，故狂乱如故、汗渴不已。暑疟本宜白虎清热，反以桂枝助热耗津，致脉数失序，此数脉主热盛阴伤，非外感初起之数。", ["数"]], "13146": ["病机", "脉滑实而数，滑主痰湿，实主邪盛，数主热。患者素嗜肥甘，膏粱厚味酿湿生热，挟暑湿为患，故面目黄、苔腻、腹胀溺赤、大渴。此脉示湿热痰浊壅盛之实证，孟英以承气加减通腑泄热化浊，二十余剂始愈。", ["滑", "实", "数"]], "13147": ["病机", "脉弦滑而数，弦主邪郁少阳，滑主痰盛，数主热。患者脘闷便秘、口渴不饥、合目汗出，乃温邪挟素盛之痰化热，壅阻气机。此脉示痰热内蕴、邪郁少阳之机，故孟英力排补药，以清热化痰、和解枢机为治。", ["弦", "滑", "数"]], "13148": ["病机", "脉滑而弦，滑主痰热内盛，弦主少阳枢机不利。患者间疟寒少热多、不饥大渴、善呕无汗，乃痰热阻于少阳，胃气上逆。孟英投白虎汤加花粉、柴胡，清阳明之热兼和解少阳，正合滑弦之脉所主痰热郁遏之机。", ["滑", "弦"]], "13149": ["病机", "脉形细数，细主阴伤，数主热盛。患者面赤舌绛、溲涩便溏、渴饮汗多，乃暑热内炽，耗伤阴液，误用参、桂温补，致狂躁妄言。此细数脉示暑热伤阴、阴虚内热之机，孟英以元参、银花、知母等清热养阴而愈。", ["细", "数"]], "13150": ["病机", "脉滑而长，滑主痰热，长主阳热亢盛。患者疟寒微热甚，旬余不愈，乃阳明热盛挟痰。孟英疏大剂白虎汤，重用石膏去米加花粉、竹茹，清阳明独盛之热。此滑长脉正示热盛痰壅、邪在阳明气分之机。", ["滑", "长"]], "13151": ["病机", "脉至弦数，重按少神，弦主邪郁，数主热，少神示阴虚阳越。患者年高，疟发寒微热甚而昏痉，颧赤目垂、鼻冷额汗、苔黄腻舌根红，乃伏暑挟痰、阴虚阳越之候。此弦数少神之脉，示邪热内郁而真阴不足，故孟英先以苁蓉、鳖甲育阴潜阳，佐化痰清热。", ["弦", "数"]], "13152": ["病机", "脉弦滑右甚，弦主痰饮、滑主痰热，右甚提示痰热偏盛于中焦。患者胸中痞结如柈、苔黄苦渴、溲如热汤，皆痰热内结之象；带下如注为湿热下注。前医温散温补反助痰热，故脉象反映痰热壅结之病机，主痰热结胸证。", ["弦", "滑"]], "13153": ["病机", "脉弦数，弦主厥阴、数主热，为厥阴暑热内盛之象。症见搐搦、泛泛欲呕、口苦、溲热如火，皆暑热引动肝风、内扰厥阴之候。脉象揭示暑热炽盛于厥阴，主厥阴暑疟，与搐搦、呕苦、溲热等症相应。", ["弦", "数"]], "13154": ["病机", "脉滑数，滑主痰湿、数主热，为伏暑痰热内蕴之象。畏冷不饥、苔黄溲赤、脘闷善呕，皆暑湿痰热阻滞中焦所致。脉象说明伏暑内伏、痰热交阻之病机，主伏暑疟，与苔黄溲赤、脘闷善呕等症相应。", ["滑", "数"]], "13155": ["病机", "脉皆滑，滑主痰；继诊脉弦而数，弦主风、数主热，为伏暑挟内风痰热鸱张之象。壮热耳聋、谵语昏狂、见人欲咬，皆痰热蒙蔽心包、引动肝风之候；头疼如劈、口苦耳聋，为风热上扰。脉象揭示伏暑挟痰热内风之病机。", ["滑", "弦", "数"]], "13156": ["病机", "脉弦滑，弦主痰饮、滑主痰结，为痰气交阻之象。疟久不痊、形消不食，前医误补反增自汗，皆因痰结中脘、气机不畅。脘下聚气为痰气凝聚之征。脉象说明痰结气滞之病机，主疟久痰结证，与脘下聚气、不食等症相应。", ["弦", "滑"]], "13157": ["病机", "脉来洪滑且数，洪主热盛、滑主痰湿、数主热，为暑热痰湿内盛之象。妊身八月患间疟，热炽昏沉、腰疼欲堕，苔黄腻垢浊，皆暑热痰湿内扰、伤及胎元之候。脉象揭示温疟暑热痰湿壅盛之病机，主温疟，与热炽、苔黄腻等症相应。", ["洪", "滑", "数"]], "13158": ["病机", "脉弦滑，弦主痰饮、滑主痰热，为痰热内蕴之象。年逾七旬患间疟，脘闷苔黄，皆痰热阻滞中焦所致。脉象说明痰热内结之病机，主痰热疟证，与脘闷苔黄等症相应，故投清热涤痰药而愈。", ["弦", "滑"]], "13159": ["病机", "脉缓滑而上溢，缓主湿、滑主痰，上溢提示痰湿阻痹、气机升逆。形瘦体弱患间疟，寒少热多、脘膈闷极、苔腻不渴，皆痰湿阻痹之候。脉象说明痰湿内阻、枢机不利之病机，主痰湿疟证，与脘闷苔腻等症相应。", ["缓", "滑"]], "13160": ["病机", "脉弦数而促，弦主痰饮，数主热，促为热盛而气机壅滞，故断为“素有热痰，暑邪内伏”。后复感风邪，脉兼浮，浮为风邪在表，然热得风而更炽，故见痰嗽头疼、口渴无溺。脉象紧扣暑热痰伏之病机，非单纯外感。", ["弦", "数", "促", "浮"]], "13161": ["病机", "脉弦缓，弦为气机郁滞，缓主湿痰内阻，非虚寒之缓。结合苔黄腻，知为“阻气凝痰，窒碍枢机”，非元气虚脱。前医误作虚脱用参附，脉象实为痰凝气阻之征，故以宣豁痰气取效。", ["弦", "缓"]], "13162": ["病机", "脉数舌绛，数主热盛，舌绛为暑热内燔之象。症见寒少热多、呕渴痞闷，显系“暑湿之疟”，暑热偏盛。脉数反映暑湿化热、内蕴气分之病机，故治当清暑化湿，非风疟柴胡姜东所宜。", ["数"]], "13163": ["病机", "脉细数而芤，细为阴亏，数为热盛，芤主失血伤阴。合之壮热汗多、舌绛神烦，知“阴分久亏，暑邪深入”。芤脉揭示阴液耗伤之本质，故用白虎加滋阴清透，非见疟治疟。", ["细", "数", "芤"]], "13164": ["病机", "脉数而右更滑大搏指，数为热，滑大为痰热壅盛，右脉候气分，故知暑湿痰热结于气分，胸闷溲赤苔垢。误服温散后脉渐伏，伏为邪热内闭、气机不通之兆，非虚脱，故用凉膈散合雪羹清下痰热。", ["数", "滑", "大", "伏"]], "13165": ["病机", "两尺空数，空为真阴亏虚，数为热；左关弦寸溢，弦为气逆，溢为升提太过；右寸关滑驶，滑为痰热。合参知“真阴素亏，腹有聚气，吸受暑热”，最忌升提。脉象示阴亏于下、暑热痰气壅于上之病机。", ["空", "数", "弦", "滑"]], "13166": ["病机", "脉洪数而芤，洪数为暑热炽盛，芤为阴伤液耗，故见苔黑面红、谵妄耳聋。经清下后脉来柔缓，柔缓为邪退胃和之象；若脉微则示正气衰微。脉象动态反映暑热伤阴、邪正消长之病机。", ["洪", "数", "芤", "缓"]], "13167": ["病机", "脉弦细而数，按之不鼓，弦为气郁，细为阴亏，数为虚热，不鼓示中气不足。合之腹中聚气上冲、汗多眩晕、骨瘦如柴，知久疟耗伤气阴，虚风内动，非实疟可截。脉象揭示正虚邪恋、气阴两伤之病机。", ["弦", "细", "数"]], "13168": ["病机", "脉洪数而滑，洪为阳盛，数为热炽，滑主痰湿。患者年高患疟，寒少热多，自汗，舌绛口干，显系暑热内蕴，蒸腾气血，故脉洪数；暑多挟湿，湿聚为痰，故兼滑。此脉主暑病，非虚脱之候，故孟英以清解法取效。", ["洪", "数", "滑"]], "13169": ["病机", "脉见滑数，滑主痰湿，数主热。患者痰嗽气逆，后疟痢并作，口渴苔黄，溺似沸汤，皆暑热挟痰为患。暑伏肺经，失于清解，气逆上奔，温纳妄投，胃枢塞滞，郁遏成疟，热迫大肠则痢。脉滑数正合暑痰内盛之机，故治暑则源清流洁。", ["滑", "数"]], "13170": ["病机", "脉虚数而弦，虚为营阴不足，数为有热，弦主少阳邪客。患者娩后月余患间疟，头疼腹痛，苔薄，乳少善呕，乃营虚而邪客少阳。疟邪踞少阳，故脉弦；营虚生内热，故虚数。此脉示正虚邪客，故以和解兼养营为治。", ["虚", "数", "弦"]], "13171": ["病机", "脉虚软微数，虚软为营阴亏虚，微数为暑热内扰。患者季夏患疟，寒微热炽，舌红不渴，思啖瓜果，汗多神惫，显系暑疟而邪不甚重，惟营阴久亏。脉虚软微数正合营虚暑扰之机，故治宜清暑养阴，不须重剂诛罚。", ["虚", "软", "微", "数"]], "13172": ["病机", "脉至滑数，右寸关更甚，滑主痰，数主热。患者疟寒少热多，前医误投凉营养阴，致呕恶烦躁，舌淡白光滑如膜，实为痰阻清阳。脉滑数右寸关甚，示痰热壅于肺胃，阴虚吸暑，痰阻清阳，故以轻清开上、化痰泄热为治。", ["滑", "数"]], "13173": ["病机", "脉缓涩不调，缓为气机弛纵，涩为痰滞血瘀，不调示郁结。患者阴虚患疟，久补不愈，杳不知饥，欲噫不畅，便溺艰涩，胸次坚而不柔，舌布干黄薄苔，显系气机郁结，痰滞未行。脉缓涩不调正合郁结痰滞之机，故先予开泄，后调养。", ["缓", "涩"]], "13174": ["病机", "脉软滑而数，软为湿，滑为痰，数为热。患者盛暑患疟，热势如长，抚之烙手，无汗，神瞀，大渴苔黄，脘闷欲呕，便秘溺赤，身面肤赤，乃暑湿挟痰交阻中焦，气机痹塞。脉软滑数正合暑湿痰热之机，故以清宣化痰为治。", ["软", "滑", "数"]], "13175": ["病机", "脉至滑数，滑主痰，数主热；甚则弦疾，左尤坚搏，弦主气郁，疾主热盛，坚搏示邪结。患者平素饮食不节，气滞多痰，患疟溺赤苔黄，脘闷不饥，乃痰热内蕴。误服温补，狂热尤甚，脉转弦疾坚搏，示邪热鸱张，气机壅塞，故病势日进。", ["滑", "数", "弦", "疾"]], "13176": ["病机", "脉不浮而弦滑且数，按之愈甚，说明暑热挟痰内蕴，非表邪。弦主痰饮，滑主痰湿，数主热，按之愈甚为邪实内结。苔黄腻、大渴喜冷、溲赤茎痛、便秘，皆暑热痰浊壅阻之征。前医温补杂投，致疟日甚、口日渴，反证此脉非虚寒，乃实热痰火内伏。", ["弦", "滑", "数"]], "13177": ["病机", "脉细而数，细为阴血亏虚，数为热盛，合之舌绛龈疼、齿缝血流，显系温邪深入营血，阴分受灼。壮热神疲、汗出不解、二便闭涩，为热结阴伤、下厥上竭之势。脉细数而禀赋极弱，故宜轻剂清肃肺气，不可攻散滋培过重。", ["细", "数"]], "13178": ["病机", "脉软脘胀，软为湿困气弱，脘胀为湿浊阻遏气机。手紫面黄、便秘溺红、苔腻而渴，皆暑湿挟秽浊阻于募原之象。脉软非虚寒，乃湿邪困阻、气机不畅所致，故用菖、朴、橘、半等芳化宣透，湿去则脉复。", ["软"]], "13179": ["病机", "脉微弱而弦，微弱为阳气虚衰，弦为寒湿内侵、气机不和。跗肿便溏、痰多食少、时欲呕吐、不渴无苔、小溲不赤，皆中虚寒湿为患之征。脉微弱说明中阳不足，弦则寒湿阻于中焦，故以六君加桂枝、吴萸温中化湿。", ["微", "弱", "弦"]], "13180": ["病机", "脉洪且数，洪为热盛气分，数为热邪亢盛。舌绛无苔、大渴多汗、寒微热甚、咳嗽兼呕，为伏暑化疟、阴分素亏而热炽。后脉来涩滞，涩为热灼津伤、血行不畅。洪数之脉主暑热内伏，非表寒，故温散致眩悗，宜清暑养阴。", ["洪", "数", "涩"]], "13181": ["病机", "脉洪滑右甚，左手兼弦，洪滑为痰热壅盛，右甚主痰热在肺胃，弦为肝风内动。昏谵瘈疭、目不识人、舌绛无液、苔黄燥、便秘，皆痰热深蟠、内风煽动之候。脉洪滑非虚，乃实痰热邪，故以知母、花粉、蒌仁清化痰热。", ["洪", "滑", "弦", "数"]], "13182": ["病机", "脉来弦数，弦为肝郁气滞，数为热邪内蕴。脘闷欲呕、汗多头重、苔腻黄，为余邪逗留兼挟肝郁，气机不畅。弦数说明邪热未清而肝气郁结，故用枳、朴、芩、半加苏叶、黄连，疏肝清热化湿，吐后邪越而脉证相应。", ["弦", "数"]], "13183": ["妇人", "脉欲离经，为临月将娩之征，非病脉。怀娠临月患疟，忧劳交加，伏暑化疟，腰疼腹坠，脉欲离经示气血将动、胎元欲产。产后血去火炎，狂言不寐、面红口渴，乃阴血骤虚、虚火上扬，故以童溲、琥珀、菖蒲清心豁痰。", []], "13184": ["病机", "脉滑数而右大，按之皆虚，两尺尤甚，滑数为痰热，右大属上焦邪实，按虚尺甚则下元虚损。原文谓\"精脱之征\"，耳聋由下元虚损、精不上承，非热入血室；胸下拒按、苔白腻为气郁痰凝。脉象揭示上实下虚、本虚标实之病机，故先开痰行气，补且缓商。", ["滑", "数", "大", "细"]], "13185": ["病机", "脉滑而弦，滑主痰湿，弦主疟邪郁于少阳。原文\"湿热蕴隆，失于宣解\"，苔腻无汗、食少痰多，面肿目黄、溲赤腹胀，皆湿热内蕴、气机不畅之象。脉滑弦正合湿热痰浊壅遏、疟邪未透之病机，故以清化方宣解湿热，戒甜腻以免助湿。", ["滑", "弦"]], "13186": ["病机", "指下虚弦而涩，虚为八脉久亏，弦为肝郁，涩为积劳血少。原文\"八脉久亏，积劳多郁\"，故寒热时形、虚火易升、少眠善悸。此虚弦涩之脉示本虚郁滞之体，疟证属虚，非寒湿饮邪实证，故劫剂虽暂效必遗后患，果复作较甚。", ["虚", "弦", "涩"]], "13187": ["病机", "脉数而面白唇红、舌绛而渴、寒微热盛、溲短便艰、汛事先期、不眠，原文断为\"暑邪侵营\"。数脉主热，暑热入营则舌绛口渴、夜不安眠；营热下迫则汛先期。脉数与症相符，故用清营透暑之品，误投温补则疟复作。", ["数"]], "13188": ["病机", "脉滑而弦，原文谓\"痰气内滞，风暑外侵\"。滑主痰，弦主气滞与疟邪，怀孕四月而患间疟腹痛、便溏汗多呕闷，正痰气内阻、风暑外袭、气机不利之象。脉滑弦紧扣痰气与疟邪相搏之病机，故以理气化痰、和解透邪之剂三服而瘳。", ["滑", "弦"]], "13189": ["病机", "脉洪数，洪为暑热炽盛，数为热象。原文\"暑热为疟\"，症见微寒热炽、发于夜、口渴便闭、目眩多汗、米饮不沾，皆暑热伤津、内热壅盛之候；汛不当期而至为热迫血分。洪数之脉与暑疟热盛病机相合，故用清热生津之剂。", ["洪", "数"]], "13190": ["病机", "脉软以涩，原文断为\"肝郁于内，暑侵其外\"。软为气虚，涩为郁滞血少，故疟日轻夜重、少腹块上冲、呕嗽并作、杳不进谷，皆肝郁气逆、暑邪外侵之象。软涩之脉示正虚郁滞，非纯实可攻，故用和解疏肝、清暑之剂。", ["软", "涩"]], "13191": ["病机", "脉软滑而尺带虚弦，软滑主痰湿，尺虚弦示真阴素亏、水不涵木。原文\"真阴素亏，水不涵木，风阳内炽，耗血伤津\"，故大渴、头疼、肿胀、肌肤甲错、苔光无液、胎动不安。软滑为痰湿之标，虚弦为阴虚阳亢之本，脉象揭示本虚标实、险恶之候。", ["软", "滑", "虚", "弦"]], "13192": ["主病", "脉弦滑，弦主气滞，滑主痰热。患者滞下昼夜数十行，苔黄满布，显为湿热积滞肠腑，气血壅阻。脉证相参，知非虚寒，故孟英重用芩、连清热，佐楂、朴行气导滞，送服青麟丸通腑泄热，投匕而痊。此脉象说明病机为湿热滞下，属实热证。", ["弦", "滑"]], "13193": ["病机", "脉弱眩晕，弱为气血不足，眩晕为清阳不升。前医误用通因通用，致痛泄无度、呕恶不纳、汗出息微，元气将脱。脉弱正合虚脱之候，非伏暑痢疾之实。孟英断为元将脱矣，急投大剂温补，脉候渐安。此脉说明病机为元气虚脱，主虚寒滑泄。", ["弱"]], "13194": ["病机", "脉沉而滑数梗梗，沉主里，滑数主湿热，梗梗为邪阻气机。患者年逾花甲，白痢误投温补，致腹胀痛、不食不溺、哕逆发热。脉证相参，知暑热未清，补药早投，邪热胶结。孟英用芩、连等清暑热，行气导滞。此脉说明病机为暑热内蕴，气机壅塞。", ["沉", "滑", "数"]], "13195": ["病机", "脉弦细，沉取甚数，弦主热郁，细为阴伤，数为热盛。患者痢疾误服温补燥热，致发热无溺、口渴不饥、舌绛无津、肌肉尽削。脉证合参，显为暑热胶锢，阴气受烁。孟英以滋阴清热为治，痢出反热，正是热邪外达之象。此脉说明病机为暑热伤阴，阴液亏耗。", ["弦", "细", "数"]], "13196": ["病机", "脉滑数而沉，滑主湿热，数主热盛，沉主里实。患者赤痢，面赤苔黄，手足冷过肘膝，当脐硬痛，小溲涩少，显为伏热内闭，热深厥深。孟英断为伏热为病，用大剂清热利湿之品，两服手足渐温，正是热透之征。此脉说明病机为伏热内蕴，湿热壅滞。", ["滑", "数", "沉"]], "13197": ["病机", "脉细涩，细为阴亏，涩为液少。患者高年阴亏，伏暑伤液，又误投枳、朴、槟、楂等燥热之药，致肢冷自汗、杳不进谷、舌绛无津。脉证相参，显为阴液亏耗，胃汁不充。孟英用滋阴养液兼调肝气，数剂后汗止肢温。此脉说明病机为阴液亏虚，津液耗伤。", ["细", "涩"]], "13198": ["主病", "脉迟微，迟为阳虚，微为阳衰。患者痢下色白不黏，不饥不渴，腹微痛而不胀，显为脾肾阳虚，寒湿内盛。脉证相合，故孟英进大剂真武汤加参，温阳散寒而愈。此脉说明病机为阳虚寒湿，主虚寒痢疾。", ["迟", "微"]], "13199": ["病机", "脉细数，细为阴伤，数为热盛。患者五色痢，神昏肢搐，大渴茎肿，腹痛夜热，危险异常。前医误用升提温补，致液脱肛坠。脉证相参，显为热毒炽盛，阴液耗伤。孟英用白头翁汤加犀角、生地等清热解毒、滋阴凉血，三帖后热退神清。此脉说明病机为热毒内陷，阴伤液耗。", ["细", "数"]], "13200": ["病机", "脉象六阴，按之如无，示高年阴液亏虚，脉道不充。阴亏则舌绛无津，音嘶痰嗽；阴虚肠燥，转为滞下色酱，脐旁坚硬，按之趯趯，为肠热府实。脉虚证实，故用甘凉清润，不可温燥。", ["沉", "虚"]], "13201": ["病机", "脉细弱而口干，为久痢伤阴，阴血亏虚，脉道不充。腰膝酸疼，乃肾虚失养。细弱主虚，故用鹿角霜、苁蓉、枸杞等温养肾阴，佐以熟地、石脂固涩，使阴复痢止。", ["细", "弱"]], "13202": ["病机", "右脉弦细芤迟，弦主暑邪内郁，细芤迟为阴血亏虚。年高久病，误补致邪盛正虚，口渴溲涩、面赤自汗，乃暑邪内迫。脉虚证实，故用白头翁汤加参、术扶正，芩、芍清热。", ["弦", "细", "芤", "迟"]], "13203": ["病机", "右脉滑数上溢，滑主痰，数主热，上溢示肺胃之气窒塞不能下行。因升散温燥烁阴，致咽疼口糜、呃忒噤口。脉证参之，非阳虚欲脱，实为阴液亏耗、痰热壅盛，故用大剂肃清。", ["滑", "数"]], "13204": ["病机", "脉至洪数不清，洪为热盛，数为邪急，不清示暑湿浊邪弥漫。疟痢并作，寒少热多，面垢苔黄，干呕口渴，痛胀溺赤，汗出神疲，皆暑湿热毒内蕴之象，故用大剂芩、连、石膏清解。", ["洪", "数"]], "13205": ["病机", "脉数而弦，数主热，弦主肝阳，形瘦口渴音微溺涩，乃阴分极虚，肝阳炽盛，伏暑为痢。腹痛异常，为肝木乘脾。故用白头翁汤加知母、花粉、丹皮、金铃等，清暑热而潜肝阳。", ["数", "弦"]], "13206": ["病机", "脉颇平和，无暑湿痢之数急弦滑，反见不饥不渴、欲呕腹痛上及心胸，乃寒湿内滞，阳气不运。脉平和不主热，故断为寒湿，投姜、桂、萸、朴温通，数服霍然。", ["和平"]], "13207": ["病机", "脉见细弱之形，肌无华泽，汛不行而早断，舌紫黯无津，是素质阴亏，情怀悒郁，二阳默炽，五液潜消。虽吸暑邪，脉不数实，故不可套用苦寒，予白头翁汤加雪羹、银花等清养兼施。", ["细", "弱"]], "13208": ["病机", "右脉弦细而数，弦主木旺，细为阴伤，数为热，滑为痰，合之右脉弦滑而空，空为气液耗竭。原文谓“气液两竭，热毒逗留”，脉弦细数示阴虚热毒未清，弦滑而空示痰热内蕴而正气已虚，故见滞下五色、腿肿裂血、溲涩口干、自汗等症，皆热毒伤阴、气液将竭之象。", ["弦", "细", "数", "滑"]], "13209": ["病机", "脉来弦数而滑，弦为木旺，数为热，滑为痰，合之腹坠腰疼、面红烦躁、知饥能食，显系阴虚木旺，风阳煽动，营液旁溢。原文谓“阴虚木旺，营液因而旁溢”，冲任隶于阳明，血从大肠而出，故滞下赤白而无粪色，月事愆期，脉象正是木火挟痰、营液失守之征。", ["弦", "数", "滑"]], "13210": ["病机", "脉亦弦软，弦为木旺，软为湿滞，合之滞下五色、噤口不食、满面红光、鼻赤尤甚，显系暑热深受，肺热素炽，暑火烁金。原文谓“暑热之深受”“肺热素炽，暑火烁金”，脉弦软示暑湿内蕴、木火刑金，故见滞下危重、面赤鼻赤等症，为暑热挟湿、肺金受灼之候。", ["弦", "软"]], "13211": ["病机", "脉虚弦而软，虚为气弱，弦为木旺，软为湿滞，合之滞下赤白、腹不甚痛而奔迫异常、能食溺长，显系中气不足、木邪犯土、湿滞下迫。原文谓“不可以常痢视也”，脉虚弦软示正气已虚而木邪未靖，故奔迫异常而腹不甚痛，以三奇散加归芍送香连丸，正是扶正祛邪、调气和血之法。", ["虚", "弦", "软"]], "13212": ["病机", "初起脉微弱为暑之本象，今按之尚数，乃阴液已伤。原文谓“脉微弱，为暑之本象”“今按之尚数，乃阴液已伤”，弱微示暑湿伤气，数示热邪未清而阴液耗损，故见痛痢不减、谷食不思、口干舌绛、气短汗多等症，为厥阴证而胃液已伤，幸脉未空数浮弦，尚可养阴清热。", ["弱", "微", "数"]], "13213": ["病机", "左手弦洪涩数而上溢，软滑而大，按之无神。弦洪为木火亢盛，涩数为阴伤血滞，上溢示肝阳上僭，软滑大而无神为正气溃败。原文谓“七情郁结，木土相乘”，高年滞下，温补酿成危证，脉象示木火挟痰上逆、阴液耗竭、胃气将绝，故粒米不纳、唇舌皆紫、痰中带血，药不可为。", ["弦", "洪", "涩", "数"]], "13214": ["病机", "脉细不饥，细为阴血亏少，不饥为胃气衰败。原文谓“病因暑热不夹湿邪，温燥过投，阴液有立涸之虞”，脉细示暑热伤阴、阴液将竭，故见口干舌绛、形消色瘁、不寐溺无，皆阴亏液涸之象，治以西洋参、生地、麦冬等养阴清热，正是救阴之意。", ["细"]], "13215": ["病机", "脉显滑数而洪，滑为痰，数为热，洪为热盛，合之黑斑苔秽、脉浑气粗面垢，显系痰热炽盛、邪毒内蕴。原文谓“痰热尚炽也”，滑数洪示痰火壅盛，故投凉膈散得大解后斑皆透绽，脉转滑数而洪，仍与大剂凉润清肃，直至痰热渐化，眠食渐安，脉象始终反映痰热壅盛之病机。", ["滑", "数", "洪"]], "13216": ["病机", "脉细数而体瘦，细为阴亏，数为热盛。患者平昔阴亏，热邪藉风药而披猖，营液得温燥而干涸，故脉细数。斑色绀、昏狂遗溺、大渴，皆阴亏热炽、营血受灼之象，脉象紧扣‘阴亏热邪’之病机。", ["细", "数"]], "13217": ["病机", "脉弦而数，弦主风阳，数主热。稚质阴亏，风阳上越，助以温散，厥少陡升，肃降无权，因而吐逆。夜不成眠、目赤、苔黄口苦，皆风阳化火、肝胃气逆之候，脉弦数正合此病机。", ["弦", "数"]], "13218": ["病机", "脉弦滑而数，弦主肝胆气逆，滑主痰凝，数主火。气郁而痰凝，痰阻而气痹，肺胃无以肃降，肝胆并力上升，浊不下行，风自火出。胸闷、便秘、溺热、惊悸烦躁，皆痰火气郁之症，脉象与之相应。", ["弦", "滑", "数"]], "13219": ["病机", "左细数，右弦滑。细数为阴亏伏火，弦滑为痰热壅盛。阴亏之体，伏火之病，失于清降，扰及于营，故见烂喉、肌热、龈糜、汛妄行。脉象分候左右，正合阴亏于下、痰火壅于上之病机。", ["细", "数", "弦", "滑"]], "13220": ["病机", "脉滑且数，为痰热内盛；脉弦细数，为阴亏风动。前者口大渴，属痰热壅盛；后者头偏左痛、心悸欲呕、壮热烦躁，乃阴亏风动、肝阳上扰。两脉并见，示痰热与阴亏风动并存之病机。", ["滑", "数", "弦", "细"]], "13221": ["病机", "脉甚弦洪滑数，弦主肝风，洪主热盛，滑主痰，数主火。痘后清凉药未辍，忽发壮热、肢瘈面赤、呕吐苔黄、渴而溺清、昏厥，乃新感温邪，痰热内闭，肝风动。脉象洪滑数，正合温邪痰热炽盛之机。", ["弦", "洪", "滑", "数"]], "13222": ["病机", "脉涩，为气血涩滞，阴伤液涸。咽痛误用升散，延及龈肿、牙关不开、舌不出齿、自汗、绝谷，乃升散耗阴，热毒壅结，气血不能流通。脉涩正示阴液亏耗、血行不畅之病机，故宜降而反升，病增剧。", ["涩"]], "13223": ["病机", "舌绛脉数，数主热盛，绛示热入营血。头疼恶冷、呕吐肢冷，似寒而实热，乃火势甚炽，斑疹将出。脉数紧扣‘火势甚炽’之病机，故治宜清凉透发，不可温升攻托。", ["数"]], "13224": ["病机", "脉滑而数，滑主痰热内盛，数主火邪炽烈。原文谓“发散太过，火盛风炽，气血两燔”，故脉见滑数，与舌绛大渴、面赤失音、不食便泻相应，示气营两燔、热毒壅盛之病机，非虚脱之候。", ["滑", "数"]], "13225": ["病机", "右脉大，右候肺，大主热盛。原文谓“伏热在肺”，因瘄后余热未净，误投滋补，热伏于肺，故脉右大，与口渴苔黄、夜热痰嗽、小溲过多相应，示伏热壅肺、清肃失司之病机。", ["大"]], "13226": ["病机", "脉甚数，数主热盛。原文陡发寒热、咽痛大渴、脘闷舌绛，显系温邪内炽，热毒燔灼，故脉甚数，与遍身发赤疹而热退相应，示热毒郁于气营、外透疹毒之病机。", ["数"]], "13227": ["误治", "本段未识脉名，纯述瘄疹误治。陆某见瘄点不绽，连进柽柳温散，致壮热无汗、面赤静卧、二便不行，复加麻黄而气喘痰升、喘汗濒危，示温散助热、耗津闭肺之误治，终以白虎清解而愈。", []], "13228": ["病机", "右脉洪滑，洪主热盛，滑主痰壅。原文谓“暑邪薄肺，挟其素有之痰而阻其治节”，故脉右洪滑，与口渴、苔白滑、痰嗽气喘、小溲不赤相应，示暑热挟痰壅肺、气机不行、疹不能达之病机。", ["洪", "滑"]], "13229": ["病机", "脉甚滑数，滑主痰盛，数主热炽。原文谓体厚痰多，扬掷谵妄，舌绛面赤，渴饮便涩，显系痰热内闭、腑气不通，故脉滑数，与下胶漆样便后脉证渐和相应，示痰热壅盛、大实之病机。", ["滑", "数"]], "13230": ["病机", "脉洪滑弦数，洪滑主热盛痰壅，弦数主热迫营血。原文谓“瘄因温邪而发”，误投温散、小柴胡升提，致狂妄莫制，与目赤苔黄、大渴不寐、时时大汗相应，示温邪燎原、气血两燔之病机。", ["洪", "滑", "弦", "数"]], "13231": ["病机", "脉弦缓而滑，弦主气滞，缓主湿，滑主痰。原文见舌黑难伸、太息便秘、胸次拒按，显系痰热内结、腑气壅滞，故脉弦缓而滑，与投凉膈散后苔退黄、下黑矢而愈相应，示痰热结聚、腑实之病机。", ["弦", "缓", "滑"]], "13232": ["病机", "脉见弦细而软，为阴虚劳倦之象；更因湿温毒重，故脉虽弦细而软，非纯虚也。后脉更细弱，乃阴液益亏，湿热未清，神昏溲涩，正不胜邪。弦为肝旺，细软为阴伤，细弱则气阴俱损，故主阴虚湿温，治当清解存阴。", ["弦", "细", "软", "弱"]], "13233": ["病机", "原文未识脉名，但孟英切脉断为非伤风，结合用药多滋阴润燥，可知其脉当非浮紧之表脉，而是虚细或细数之象，反映阴虚肺燥之质。久患痰嗽，非外感，乃内伤阴虚，肺失濡润，故以滋阴获效，继则受孕，亦阴血得养之征。", []], "13234": ["病机", "脉形弦滑有力，为痰热内壅之象。痰嗽气喘、囊缩便秘、心摇不宁，皆痰热阻遏气机，非虚脱也。孟英断为根蒂欲脱，实因痰热闭阻，气机不降，故以八味去丹泽合生脉加镇纳，待大解行而诸恙减，证明脉弦滑有力主痰热内实。", ["弦", "滑", "有", "力"]], "13235": ["病机", "脉滑苔厚，溺赤痰浓，显系痰热内蕴。哮发于冬，医作虚寒治反剧，孟英以滑脉为凭，断为痰热阻肺，故用知母、花粉、滑石、栀子等清化痰热而安。滑主痰饮，苔厚为湿浊，溺赤痰浓为热象，脉症合参，病机在痰热壅肺。", ["滑"]], "13236": ["预后", "六脉皆数，见于冬令水旺之时，数为阴虚火旺之象。久患痰嗽，阴亏兼郁，误投温补，咳嗽复作，咽痛渐至，阴液愈耗。冬见数脉，阳不潜藏，至春木旺火升，阴竭难支，故断其不能春。此以脉数测预后，非主病也。", ["数"]], "13237": ["病机", "脉虽不甚有力，右部微有弦滑，苔黄腻，为痰热内蕴之征。前医作肾虚水泛治，反致咽喉阻塞、便溏溲频，皆因补涩助邪。孟英凭右部弦滑，断非虚证，以苇茎汤合雪羹清热化痰获效。弦滑主痰热，右部候肺，故病在肺胃痰热。", ["弦", "滑"]], "13238": ["病机", "脉弦滑右甚，为痰热壅肺之实象，故参汤切勿沾唇，以蒌薤旋覆等开降获效。石媪脉虚弦细滑，则为本虚标实，痰热中兼阴亏，故重加熟地而瘳。同一喘嗽，脉弦滑右甚主痰实，虚弦细滑主虚中夹痰，凭脉权衡，病机各异。", ["弦", "滑", "虚", "细"]], "13239": ["病机", "脉沉而涩，体冷自汗，似虚脱，然二便不通、脘闷苔腻，实为痰热为补药所遏，气机窒痹不行。沉主里，涩主气滞血瘀，痰热内闭，阳气不达，故体冷自汗。孟英以开降之剂复杯即减，证明脉沉涩主痰热壅遏、气机痹阻。", ["沉", "涩"]], "13240": ["病机", "左脉弦细而虚，右尺寸皆数，为阴亏气不潜纳之候。弦细而虚示阴血亏虚、肝失柔养，虚而无力；数脉主热，右寸关数乃气不潜纳、虚阳上浮。前医误用耆、术助气，二陈、故纸、附、桂劫阴，致愈补愈剧。此脉象说明病本在阴亏，非气虚，故补气反悖。", ["弦", "细", "虚", "数"]], "13241": ["病机", "初诊脉弦滑，乃肝经郁怒火升，弦主肝郁，滑主痰火，故投当归龙荟丸而瘥。后病屡发，脉甚弦涩，口苦苔黄，舌色紫黯，汛虽不愆而内有瘀滞。弦为气郁，涩为血瘀，弦涩并见示气滞血瘀、郁火内伏，故以雪羹加金铃、旋覆、桃仁等行瘀泄热而愈。", ["弦", "滑", "涩"]], "13242": ["病机", "脉仍虚弦，略加软数。虚弦为根蒂虚而兼怫郁，软数示暑热内侵。患者年逾七旬，遭惨痛而嗽，气逆痰咸，夜多漩溺，口苦不饥，本属阴亏气郁；夏间吸暑患痢，脉虚弦加软数，说明正虚未复又感暑邪，故于滋阴方中增滑石、香连丸以解暑治痢。", ["虚", "弦", "软", "数"]], "13243": ["病机", "右寸软滑，软为肺虚，滑为痰贮。卧难偏左，乃痰阻肺络、气机不利。右寸主肺，脉软滑示肺气虚弱而痰浊内贮于络，非实邪壅盛。故以苇茎、丝瓜络、蛤粉、贝母等清肺化痰通络，投之果愈。", ["软", "滑"]], "13244": ["病机", "脉无常候，虚促虽形，未必即为虚谛。患者年甫三旬，平时善饭，病起于暴，苔腻痰浓，纵有足冷面红、不饥、不寐、自汗等证，无非痰阻枢机，有升无降。脉无常候示痰壅气机、脉道不利，非真虚之象，故以石膏、黄芩、旋覆、赭石等清化痰热而安。", []], "13245": ["病机", "脉虚洪豁大，舌色干绛，溲赤点滴，证属阴亏。虚洪豁大乃阴亏阳浮、气不潜纳之象，非实热洪大。年越古稀，痰嗽气喘，躁汗时形，欲卧不能著枕，皆阴亏不能摄纳所致。故忌投刚燥，以西洋参、熟地、苁蓉、枸杞等大剂滋阴潜阳，果获愈。", ["虚", "洪", "大"]], "13246": ["病机", "脉缓而滑，岂为虚象？缓为气机迟滞，滑为痰凝久伏。患者久坐不劳，行气迟滞，痰凝久伏，故行数十武即喘。脉缓滑示痰湿内蕴、气机不畅，非虚证，故频补不应。以雪羹合小陷胸加竹茹、旋覆等化痰行气，果吐多痰而愈。", ["缓", "滑"]], "13247": ["病机", "脉弦缓而大，畏冷异常，动即气逆，时欲出汗，暮热从骨髓中出，痰色绿而且臭，便坚溺赤。弦缓而大示痰火内郁、气机壅滞，非劳怯虚象。痰火为患，误投补药，故久而不愈。以苇茎汤合雪羹加白薇、花粉、旋覆、蛤壳清化痰火，服二十剂而体健。", ["弦", "缓", "大"]], "13248": ["病机", "脉迟弱为阳气不足、脾胃虚寒之象，结合苔黄垢不渴、指冷腰酸，显系中虚痰湿内盛。迟主阳微，弱主气馁，故痰湿不化而喘逆。虽苔黄垢似热，但不渴、指冷，正是虚寒本质。脉症合参，病机为中虚痰湿上逆，故用参术补中、苍枳旋半化痰降逆而效。", ["迟", "弱"]], "13249": ["病机", "脉来虚弦软滑，尺中小数，虚弦为下元根蒂不固，软滑为痰热内阻。颧红微汗、吸气不能至腹、小便短数，皆肾虚不纳之征；胸痞、舌红黄苔、渴不多饮，乃痰热阻上。故断为根蒂虚于下、痰热阻于上，非单纯实喘或虚喘，温补清化皆非所宜。", ["虚", "弦", "软", "滑"]], "13250": ["病机", "脉数而洪，为热盛之象。盛夏患恶阻，前医误用旋覆、姜、桂温燥，致壮热神昏、腰疼欲坠、二便秘涩、呕吐不休，显系热邪内炽、胎气不安。数主热，洪主阳明气分热盛，故以栀芩连楝等清热安胎，佐苏叶少许以顺气，热清则呕止胎安。", ["数", "洪"]], "13251": ["病机", "脉弦软而数，弦主厥阴，软为热蒸，数主热盛。发热呕吐、茎缩腹痛，苔色腻黄，皆热伏厥阴、肝经郁热之候。茎缩为厥阴脉络拘急，腹痛为肝气不舒。故断为热伏厥阴，以楝实、通草、栀、莲等清肝泄热通络，热去则诸症自愈。", ["弦", "软", "数"]], "13252": ["病机", "脉弦劲而数，弦劲为肝火亢盛，数为热象。口苦而渴、便不畅、溲如沸，皆热盛之征。冷气时冲、渴喜饮沸、吐沫极酸，乃热极似寒、饮邪内踞、曲直所化，非真寒也。病在络，故吐之不易。以清肝泄热、通络降逆之剂，佐当归龙荟丸泻火，热清络通则愈。", ["弦", "劲", "数"]], "13253": ["病机", "脉弦滑为痰阻络脉、气不得宣，故噫气不已、腿痛。其媳脉虽弦数以滑，弦数为风阳内动，滑为痰聚，乃痰挟风阳而为厥，非娠也。前医误补，致汛愆。两案皆以弦滑为痰之征，弦数为热之象，故治以蠲痰息风、舒郁清营，痰去则气宣厥止。", ["弦", "滑", "数"]], "13254": ["病机", "脉形软数，软为胃气未绝，数为热邪内蕴。霍乱后目闭呃忒，医疑脱陷欲用桂附回阳，然溺赤口干、药香扑鼻，显系热邪未清、肺胃气逆。软数之脉非虚寒，故断为热证，不可温补。以肃肺清胃之剂，热清胃降则呃止神安。", ["软", "数"]], "13255": ["病机", "脉弦细而有力，弦主肝郁，细为阴伤，有力则非虚寒。截疟后浮肿，前医误认体虚脉细而用温补，致呃忒不休、气冲碍卧。实则弦细有力乃肝郁气滞、痰阻胸膈，温补更助其壅。故以栝蒌薤白合小陷胸等宽胸化痰、降逆和胃，四剂而瘳。", ["弦", "细", "有力"]], "13256": ["病机", "左脉弦涩不调，弦主肝郁，涩示气机不畅；右兼软滑，软为气虚，滑为痰阻。症见呃忒欲呃不爽、喷嚏久不作，乃肝气郁而欲升不能，痰阻肺而欲降不能，气机升降失司。故以柴胡、枳壳等疏肝理气、化痰降逆，复杯而减。", ["弦", "涩", "软", "滑"]], "13257": ["病机", "左脉弦软，右虚大而滑。弦软为肝郁阴伤，虚大为气分不足，滑为伏痰内盛。症见神昏瘈疭、呃逆、心下拒按、苔黄燥，乃温邪虽陷而气分未清，里气虽虚而伏痰内盛。故先以人参、牡蛎扶正，犀角、元参清营，竹茹、贝母化痰。", ["弦", "软", "虚", "滑"]], "13258": ["预后", "脉促歇止，满舌黄苔秽腻，体丰肉颤。促为阳盛热结，歇止为气血瘀滞、脏气衰败。醉饱后胀闷便闭，复饮火酒洋烟，热毒壅盛，下之不及，故脉见促止。虽起居如常，实为危候，果至胸腹额上胀裂而死，示脉促歇止主病深重、预后不良。", ["促", "结", "代"]], "13259": ["病机", "脉弦细，苔黄腻。弦主肝郁气滞，细为阴伤血少。腹痛不饥，误投参、术、姜、附温补，致疼胀日加、水饮不沾、沉沉如寐，乃肝郁化热、气机壅滞。故以枳、朴、萸、连、栀、楝等疏肝清热、行气导滞，二剂便行脉起而愈。", ["弦", "细"]], "13260": ["病机", "脉弦细而数。弦为肝气郁滞，细为阴血不足，数为营分有热。腹胀减餐、牙宣腿痛、肌肉渐消，乃肝郁日久、阴虚营热，非辛通温运所宜。故以乌梅、黄连、楝、芍、栀子等酸苦泄热、柔肝养阴，服之果愈，继以甘润滋填而脉和。", ["弦", "细", "数"]], "13261": ["病机", "脉洪而数，渴饮苔黄。洪为热盛气分，数为热象。年近五旬天癸已绝，腹胀误投肾气汤、建中法温补，致寒热渐作、病剧而崩。此吸受暑邪，得温补而血下漏，热迫血妄行。故以犀角、元参、茅根、柏叶等清热凉血止血，数剂始安。", ["洪", "数"]], "13262": ["病机", "脉弦细数。弦主肝郁，细为阴亏，数为内热。腹胀善呕，误吸鸦片温运、蒜罨水炙，致骨蒸减餐、胀加经断，复进温补而便泻不饥、骨立形消。乃肝郁化热、阴液耗损、虚劳已成之候，脉弦细数正合阴虚内热、肝郁气滞之机。", ["弦", "细", "数"]], "13263": ["病机", "脉弦滑而体甚丰。弦主气郁，滑主痰盛。诞子后汛不行，频年温补无效，乃气郁生热，热烁津液以成痰，痰阻气道，不能化血以流行，致行度愆期、腹形胀痛、肢背不舒、渴不欲饮、苔黄口苦。皆风阳浮动、治节横斜之故，故以化痰清热、调气行血之剂而效。", ["弦", "滑"]], "13264": ["病机", "脉微而弱，虚象显然。肿起肾囊、气逆便溏，溺清且长，乃土虚不制水，水湿泛滥。前服五苓、八正通利无功，滋阴亦谬，正因脉微弱示中阳不足，非实邪停水，故宜大剂参术补土胜湿，土旺则水有所制而肿消。", ["微", "弱"]], "13265": ["预后", "脉甚细数，舌绛无津，谵语，乃真阴欲匮、阴竭阳亢之候。细为阴亏，数为阳亢，阴液枯涸不能濡养，故虽囊肿暂消而脉象依然，孟英坚辞不肯承手。原文明言脉至细数则阴竭阳亢，不拘何病均忌此脉，虚劳尤甚，寻果不起。", ["细", "数"]], "13266": ["病机", "左洪数、右弦滑，洪数为肺胃痰热内盛，弦滑主痰饮壅滞。龈疼日久渐至身面浮肿、气逆不饥，乃阴分虽虚而痰热壅肺，肺失肃降，水津不布。故先清肺胃痰热，投白虎加味，肿消后再佐滋阴而龈疼止。", ["洪", "数", "弦", "滑"]], "13267": ["病机", "脉弦细，沉之带数，舌绛口干，肿处赤痛，溺少而热，乃阴虚肝热、郁火无从宣泄。弦为肝旺，细为阴亏，数为火郁。便溏脉细易误作寒湿，然兼证赤痛溲热，实属郁火，火郁则气胀津枯，故温燥愈剧，投白头翁汤清肝泄火而愈。", ["弦", "细", "数"]], "13268": ["病机", "脉弦滑而数，弦为肝火，滑为伏痰，数为热盛。两腿疼肿、便溏不渴、溺极热如沸，非寒湿乃肝火为患。便泻是土受木乘，不渴因内有伏痰。前医投苍术、独活等温燥，反助火势，故以栀柏芩连清肝泻火、化痰通络而一剂知。", ["弦", "滑", "数"]], "13269": ["病机", "脉浮无汗，尺静经行，既非根蒂之虚，亦非邪留误补。浮脉主表，无汗示风邪外束，肺气阻痹，水津失布，故渐形浮肿、咳逆溲涩，所谓皮水证也。前用消导滋填皆误，宜香薷、杏仁、紫苏等宣肺疏风、通调水道，复杯而愈。", ["浮"]], "13270": ["病机", "脉象弦滑而数，弦为肝阳易动，滑为烁液成痰，数为火盛。手足肿疼、便坚溲赤、舌绛、准头瘰磊，皆阴虚火盛、风自火出、痰窜经络之征。温补率投遂成锢疾，幸病在经络，停补尚可延年，必用清通宣泄，清凉正合病机。", ["弦", "滑", "数"]], "13271": ["病机", "左极弦细，右弱如无，舌赤无津，呻吟呕沫，不眠不食。弦细为肝旺阴亏，右弱如无乃中土受伤、运化无权，气液两竭。素患跗肿，疟痢后腹疼胀、面浮身肿，系肝旺乘土、气液耗竭之候，故以参须、石斛等益气生津、清肝和胃，勉尽人谋。", ["弦", "细", "弱"]], "13272": ["病机", "脉沉弦而软滑，沉主里，弦主肝郁，软滑为痰湿内凝。原文谓“肝郁气结，郁则生热，补则凝痰”，温补误投致痰热互结，故腹胀如痞、冲逆吐酸、苔黄腻、溲浑短。脉象反映肝郁化热、痰凝气滞之病机，非虚寒可知。", ["沉", "弦", "软", "滑"]], "13273": ["病机", "脉弦无胃、不柔和，为肝阳亢逆、胃气衰败之象。原文谓“风阳内煽，水自沸腾”，久病郁怒，温补劫阴，津液涸竭，故攻痛呕吐、哕逆空呕。脉失柔和示胃气将绝，病机属肝风内动、阴液耗伤，非寒证可温。", ["弦"]], "13274": ["病机", "脉甚弦软，弦为肝郁，软为营阴不足。初患目赤发热，温散致泄厥，补剂反使宿瘕攻痛。脉象示肝郁化热、营阴亏虚，故舌绛而渴。治以柔肝养营、清热散结，方用苁蓉、龟板、当归等，正合弦软所主之郁热伤阴病机。", ["弦", "软"]], "13275": ["病机", "脉数舌绛，面赤睛红，溺如沸汤，为热郁于内；脉伏唇紫，乃热深厥深、气机闭阻。原文谓“下部虚寒”误进温补，愈服愈剧，实属郁热内炽、阳郁不达。脉数伏并见，示热邪内闭、气血壅滞，故日厥数十次，少腹拒按。", ["数", "伏"]], "13276": ["病机", "脉弦软且滑，弦主肝郁，软为气弱，滑为痰凝。疟后左胁聚气窜痛，非疟母之癥积，乃肝郁痰滞、气机不畅。原文断“非疟母也”，以脉象示痰气交阻而非瘀血成块，故用旋覆、海石、竹茹等化痰行气而根除。", ["弦", "软", "滑"]], "13277": ["病机", "左脉弦数上溢，尺中滑大按之细弱，右脉软滑，示肝阳上亢、阴血亏虚，兼痰热内蕴。原文谓“脉证虽觉渐和”，然痢久经断、聚块上窜、舌绛无津，病机属阴虚阳亢、痰热互结、气血俱损，故见晕厥、暮热、溺短等症。", ["弦", "数", "滑", "细"]], "13278": ["病机", "脉弦涩，弦主肝郁，涩主气滞血瘀。少腹坚胀、左胁聚气，面黄非暑湿，乃肝郁气结、血行不畅。原文断“非外因也，肝郁耳”，脉涩示气滞日久入血，故用旋覆花汤合金铃子散、当归龙荟丸，行气活血而愈。", ["弦", "涩"]], "13279": ["病机", "左脉弦数而洪，右脉滑数而溢，弦洪为肝阳亢盛，滑数为痰热内蕴。素体阴虚肝旺，腹有聚瘕，疟后苔黑口干，脉象示阴虚阳亢、痰热交阻。故初用栀豉合金铃子散清肝化痰，后见汛行腰痛，转以养营化痰，脉证相应。", ["弦", "数", "洪", "滑"]], "13280": ["病机", "脉虚细而弦，虚细为营阴亏耗、脉道不充，弦为肝郁气滞、瘕聚内结。少腹瘕聚上冲昏厥、足冷面红、夜不成寐、口干无液，皆阴血亏虚、肝气横逆、虚阳上浮之象。脉证合参，非实积可攻，乃阴虚气郁，故用一贯煎滋阴柔肝而愈。", ["虚", "细", "弦"]], "13281": ["病机", "脉来弦滑，弦主肝郁气滞，滑主痰热内蕴。少腹聚瘕攻痛、羞明心悸、汛速带频，苔黄苦渴、溺热便难，显系肝经郁热夹痰，误用胶艾参茸峻补，反助痰热上逆致晕厥。弦滑为痰热实证之凭，故以清肝豁痰潜降取效。", ["弦", "滑"]], "13282": ["病机", "脉弦滑，弦为肝气郁滞，滑为痰浊内盛。少腹聚气上冲脘痛、下坠腿肿、带多汛速、腹胀胸闷、口腻不渴、便溏欲解不行，皆肝热痰滞、气机升降失司。前医误作脾虚率进补剂，病日以甚。弦滑示痰热实滞，故清肝豁痰而滞气下行。", ["弦", "滑"]], "13283": ["病机", "脉来虚弦而软，虚软为营津久耗、正气本虚，弦为气郁不舒。身热耳聋、泻不食、胸痞痰韧、口腻欲呕、神情惫甚、苔黄腻无津，乃本实欲拨、挟客邪而过投清散所致。脉虚软示本虚，弦示气郁，故以扶正调气化痰为治，三贴泻止痰稀。", ["虚", "弦", "软"]], "13284": ["死脉", "原文未识脉名，然「脉仅若蛛丝过指」为垂危之候。久患胸痞多痰，清阳不司旋运，正气久亏；及痰药痧药风药遍灌，脉细如蛛丝，乃元气将绝、胃气已败之死脉。孟英坚不与方，须臾而卒，示脉微欲绝者不可妄药。", []], "13285": ["病机", "脉弦滑而大，弦主气逆，滑主痰盛，大为邪实壅盛。年逾花甲卒仆于地，牙关紧闭，乃痰、气、食相并逆于上，壅塞清窍。脉弦滑而大正是实邪内闭之征，故先探吐痰食开其壅塞，太息一声而苏，继以调气和中而愈。", ["弦", "滑", "大"]], "13286": ["病机", "脉缓滑，缓为气机弛缓，滑为痰浊凝滞。汛愆而饮食渐减，前医误投通经血药反恶谷。孟英断为痰气凝滞、经隧不宣，由安坐不劳所致。缓滑非血虚经闭之脉，故法以豁痰流气，果吐痰而经自通，示辨证当求脉因。", ["缓", "滑"]], "13287": ["病机", "脉滑痰多，滑为痰浊内盛之确征。形虽羸瘦而右腰痛胀欲捶，苔黄舌绛，乃体虚病实、痰热胶结络脉。脉滑示痰实可攻，不可徒以温补因循，故先以雪羹加味送控涎丹攻下胶痰，三进而病若失，嗣后调补获痊。", ["滑"]], "13288": ["病机", "脉弦软，弦主饮邪内动，软为湿浊壅遏。患者脘痛呕吐、二便秘涩，乃茶饮酿湿，饮邪上逆，胃失和降，下阻肠腑，故见关格之象。孟英断为饮证，非阴枯阳结，正合脉弦软而不劲急之象。", ["弦", "软"]], "13289": ["病机", "原文未出脉名，然述证延二十余年，肝升太过，胃降无权，痰饮踞为窠囊，气阻血瘀。此由生冷伤胃阳，肝木乘虚，积温成热，反助风阳，消烁胃津，渐形瘦削。病机在肝胃升降失司，痰瘀互结。", []], "13290": ["兼症", "左脉缓滑，缓主湿，滑主痰，乃痰湿内蕴之象。方用沙参、竹茹、旋覆、半夏等清降痰热，椒红、乌梅、吴萸炒黄连辛开苦降，苁蓉温润，龟板、海䖳咸寒软坚，藕、凫茈通利，赭石镇降，皆针对痰饮气逆、升降失司而设。", ["缓", "滑"]], "13291": ["病机", "左脉如昨兼弦，右寸转缓滑，弦为风阳浮动，缓滑为痰湿未化。中脘气渐下降而二便欲解不行，乃升降愆常，枢机窒涩，肺失肃清，一身气滞。故去海石，加栝蒌、枳实以廓上游、通腑气。", ["弦", "缓", "滑"]], "13292": ["预后", "脉来较静，小溲渐行，虽未更衣已能安谷，是浊得下降之征。前用清通，今脉静溲行，示痰热渐化，气机渐通。仍导以清通，去贝、楝，加归尾、桃仁活血润肠，送导水丸以通地道，冀其腑气畅达。", ["静"]], "13293": ["预后", "脉稍和缓，叠授清宣后更衣色黑，噫气罢、酸水不呕、纳谷增，是痰瘀渐下、胃气渐和之象。然腿凉便滞、颧红胁热，火犹上僭，络聚痰瘀未净。脉缓为胃气渐复，故法仍缓导，去枳实、归尾，减导水丸，防其过下。", ["缓"]], "13294": ["预后", "脉渐柔和，各恙皆减，眠食渐安，是邪退正复之佳兆。然火犹易升，头疼面赤，颊酸结核，胁热未蠲，余热痰瘀未尽。脉柔和示胃气渐和，故参清养，去白前、青黛、紫菀、黄连之苦寒，加银花、贝母、黄菊、丹参等清透余热。", ["柔", "和"]], "13295": ["病机", "脉沉弦而软滑带数，沉主里，弦主饮，软滑为痰湿，数为郁热。素患痰饮，误服温补，附桂刚猛辟易痰邪，地黄厚浊反阻枢机，致治节不伸，二便涩少，痰无出路，卒然壅塞清阳升降之路，故发冷喘汗欲厥。此与少阴虚喘迥异，病在肺气不展。", ["沉", "弦", "软", "滑"]], "13296": ["病机", "脉来右寸溢，关尺滑而微数，左手弦而带滑。右寸溢主气逆，关尺滑数主痰热内阻，左弦滑为肝郁痰凝。冲为血海隶于阳明，阳明经气为痰所阻，不能流通输布，致经断乳少，痰血胶结而为络病。面赤足冷、汗出、食减无眠、气逆口渴、溲短热，皆痰热内蕴、气机不降之象。", ["滑", "数", "弦"]], "13297": ["病机", "脉甚弦滑，弦主肝风，滑主痰浊。厥前必先作胀，更衣得泻始舒，巅顶时疼，饮食不减，乃肝风挟痰为患。痰在络中，故不见吐痰，补之则锢之愈深。胎前病痰证居半，产时痰涎不下，诸病丛生，此脉弦滑正示风痰内伏、络脉壅滞之机。", ["弦", "滑"]], "13298": ["病机", "脉软滑而数，苔色腻滞。软为湿，滑为痰，数为热。平昔善饮，湿热内蕴，奔走过劳，邪乃下注，膀胱气阻，溲涩不通。既非真火无权，亦非清阳下陷，故补中益气、肾气丸皆非所宜。此脉示湿热下注、气化不利之病机，与肛翻患痔、小溲不行相应。", ["软", "滑", "数"]], "13299": ["病机", "脉缓大，苔色微黄，乃劳力火升，内兼湿热。缓大非虚，软数而长亦非虚，皆湿热火升之象。腿酸寝汗、溺赤脘疼、食减口干，或疑为损，实为劳力火升、湿热内蕴。脉软数而长，带下诸药罔瘳，亦属湿火下注，宜猪肚丸清其湿火。", ["缓", "大", "软", "数"]], "13300": ["预后", "脉既数且乱，沉取极细。数乱为阴亏阳浮、精气欲脱之象，沉取极细则阴分素亏，根本已竭。服药后汗出昏狂，精流欲脱，此证颇危，生机仅存一线。脉数乱而细，示阴亏于下、阳扰于上，非附、桂之罪，乃阴分素亏不能敛阳，故预后险恶。", ["数", "乱", "细"]], "13301": ["病机", "脉微无神，自汗不收，肢背极冷，奄奄一息。微为阳衰，无神为元气欲脱。禀赋素亏，阳气欲脱，此必误认表证，以柴、葛、香薷散之，更以枳、朴、槟榔泻之，致阳气愈伤。脉微无神正示阳脱之机，与自汗、肢冷、息微相应，故用救逆汤加参、耆以回阳固脱。", ["微"]], "13302": ["病机", "脉微弱如无，四肢麻木，头晕汗淋，不能言，目垂遗溺，浑身肤冷。微弱如无为阳气衰微欲绝之象。乃虚风内动，阳浮欲脱也。阳虚不能温煦则肤冷，虚风上扰则头晕，阳浮不敛则汗淋，神失所养则不能言。脉微弱如无正示阳脱之机，故急以参、耆、附、桂回阳，龙、牡潜镇。", ["微", "弱"]], "13303": ["病机", "脉微欲脱，语难出声，舌光无苔，筋惕肉𥆧。微为阳衰，欲脱为元气将绝。寒热时形，身振多汗，医从疟治，数日而危，乃误治伤阳。脉微欲脱示阳气衰微、不能固摄，故身振多汗；舌光无苔为阴液亦亏；筋惕肉𥆧为虚风内动。亟宜救逆，合建中汤灌之，复杯即愈。", ["微"]], "13304": ["病机", "脉甚数主阴亏火旺。患者素禀不坚，频服温补，更伤阴液，阴虚不能制阳，故脉数。此数脉非热实，乃虚火内扰，与头眩脑鸣、畏冷（假寒）相应。灸火更伤阴，致寒少热多如疟，皆阴亏之变。", ["数"]], "13305": ["病机", "脉细数而兼弦滑，细数主阴亏火盛，弦滑为痰饮内蕴。阴亏火盛，津液受灼成痰，故痰多。此非虚寒，六君子汤温燥反助火。后咽痛、喉腐，乃阴虚于下、阳浮于上，火迫津液结痰，酿烟毒熏喉。", ["细", "数", "弦", "滑"]], "13306": ["病机", "脉弦硬无情，为真阴耗竭、胃津灼烁之象。前因寒药戕阳，后以温补竭阴，热药灼津为痰，五脏失养，故血溢、便泄、喘逆、足不能屈伸。水源欲绝则溲少色绿，木火内焚现东方之色，皆阴竭阳亢之危候。", ["弦", "硬"]], "13307": ["病机", "脉弦细以数，舌绛大渴，为真阴大虚之证。热药温补耗竭真阴，阴虚火旺故脉细数，筋脉失养则弦。阴亏液燥，津不易生，故便不行。咳痰红绿、腹中绞痛，皆阴虚火炽、痰热内扰之候，非肠痈实热。", ["弦", "细", "数"]], "13308": ["病机", "脉虚细中兼有弦滑，虚细为阴虚，弦滑为痰饮内停。舌绛而渴，阴虚挟痰之征。温补药助热耗阴，致喘汗欲脱。阴虚为本，痰饮为标，故滋阴调肝、祛饮利痰并用，使阴复痰消而安。", ["虚", "细", "弦", "滑"]], "13309": ["病机", "脉细主阴虚，痰咸为肾虚水泛之征。久患痰嗽碍卧，素不投补，然脉细痰咸，显系阴虚水泛，非温补所宜。大剂熟地滋肾填阴，阴复则水有所主，痰嗽自平。前服增病者，因杂参、术助气，非熟地之过。", ["细"]], "13310": ["病机", "脉芤而弦数，芤主阴血亏虚，弦数为肝火内动。真阴大亏，筋骨失濡，故筋掣、龈痛、指麻、腰酸。带下太甚，阴液漏泄，为病之本。脚气药温燥更伤阴，故无效。治当滋阴潜阳，澄源洁流。", ["芤", "弦", "数"]], "13311": ["病机", "左脉弦而微数，右脉软滑兼弦。左弦数主肝木过升、阴亏火动；右软滑主脾虚湿浊内蟠。久投滋腻，湿浊碍中，升降不调，故纳减、呕腐吞酸。水常泛滥，土失堤防，肝升肺降失职，左强右弱，治当调中运、平升降。", ["弦", "数", "软", "滑"]], "13312": ["病机", "脉至弦缓，并不洪数，说明非热邪内陷。弦主肝风内动，缓主正气不足。真阴素亏，半产劳瘁，阴虚阳亢，内风陡升，故头疼筋掣、不语、二便不行。脉不洪数，排除实热，乃阴虚痰滞机缄，本虚标实，宜清宣，勿投寒腻。", ["弦", "缓"]], "13313": ["病机", "脉软且弦，软为正气虚，弦为肝风痰阻。本虚标实，风升头痛羞明，痰凝气阻咽膈不舒。不可峻攻，法先开泄，以疏风化痰、宣畅气机，兼顾本虚。", ["软", "弦"]], "13314": ["病机", "脉至虚弦，右兼微弱，虚弦为阴血亏虚、肝风内动，微弱为气阳不足。本虚标实，难授峻攻。开养兼参，以扶正为主，兼化痰通络，庶无他变。", ["虚", "弦", "微", "弱"]], "13315": ["病机", "脉软以迟，软为气虚，迟为阳衰。舌淡红、苔灰腻、不作渴，非热可知。不食不便，宜参温煦，以豁凝痰。此阳虚痰凝，治当温阳化痰。", ["软", "迟"]], "13316": ["病机", "脉仍弦软，弦为肝火未平，软为正气已虚。苔化舌出、语稍吐、略思粥食，胃气渐动，但头痛未蠲、久不更衣。法主温通，徐为疏瀹，以温通肠腑、平肝息风。", ["弦", "软"]], "13317": ["病机", "左脉微迟，微为血虚，迟为阳弱。连投温养，神气渐清，语亦有声，但头犹左痛、大解不行。法当补血，血充风息，腑气自行。此血虚风动，肠燥便秘。", ["微", "迟"]], "13318": ["病机", "脉已渐起，说明正气渐复，但尚未更衣，浊未下行，语犹错乱，时或头痛，寐则梦多。此浊阴未降，神明被扰。濡导下行，且为先授，以润肠通腑、降浊安神。", []], "13319": ["病机", "脉软而迟，软为气虚，迟为阳衰。虽已知饥，未得大解，肝无宣泄，时欲上冲。阴分久亏，岂容妄下。素伤思虑，肝郁神虚，语言错乱。法当养正，通镇相参，以扶正安神、通腑降逆。", ["软", "迟"]], "13320": ["病机", "脉弱口干，面无华色，乃积虚未复，气血不足之象。脉弱主虚，口干因津亏，面华色失荣，故治以平补，前方去桂心等温燥，加龟板、麦冬、蒲桃干滋阴养液，使虚渐复而汛至体康。", ["弱"]], "13321": ["病机", "脉弦细软滑，弦细为阴亏于下，软滑为痰热阻上。患者耳鸣、食减痰多、苔灰黄厚腻，乃阴亏真于下，痰热阻于上。故以西洋参、麦冬等养阴，竹茹、黄连等清痰热，使痰少餐加，苔退病愈。", ["弦", "细", "软", "滑"]], "13322": ["病机", "两尺虚软，左寸关弦数，右兼浮滑，乃阴虚火炎，下焦阴虚无以制火，痰火实于上焦。故见五心如烙、面浮咳逆、痰壅碍眠。治当于虚处求实，用沙参、竹茹等清上焦痰火，兼养下焦之阴。", ["虚", "软", "弦", "数"]], "13323": ["病机", "脉细而数，口干舌绛，乃营阴大亏，无以营养筋骨。因用力拔针而痛遍一身，非外伤实邪，乃内伤虚损。细数脉主阴虚内热，故不可妄投燥烈，宜集灵膏加减滋养营阴，使筋骨得养而愈。", ["细", "数"]], "13324": ["病机", "脉似虚细而沉分略形弦滑，虚细为少阴不足，弦滑为阳明有余。症见肌肤消瘦、两腓发热、面色青黄隐黑气，乃土燥水涸，无形之热内伤。故以甘寒诸品清阳明、滋少阴，使黑气退而肌充经调。", ["虚", "细", "弦", "滑"]], "13325": ["病机", "左手弦而数，右部涩且弱，弦数因悒郁化火，涩弱因思虑伤脾。症见晡寒夜热、寝汗咽干、咳嗽胁疼、减餐经少，乃病发心脾，藏燥之候。故以甘麦大枣汤加藕，益气养血、润燥缓急，使脉证大减。", ["弦", "数", "涩", "弱"]], "13326": ["病机", "脉微弱，呕吐自汗，肢冷神疲，乃内伤虚寒，中阳不足。前医误投凉解，更伤阳气，故非伏暑。微弱脉主气血俱虚，治以黄耆建中汤去饴，加龙骨、生姜、茯苓、橘皮，温中固表，投剂即安。", ["微", "弱"]], "13327": ["预后", "脉细数，舌光绛，娩后乳多善饭而形遽瘦，乃急劳也。乳为血化，乳溢过中，如草木将枯精华外发，阴血耗竭。细数脉主阴虚火旺，舌光绛为阴液涸竭，故断乳服药亦不及，至秋而逝，示预后不良。", ["细", "数"]], "13328": ["病机", "原文述“按之豁然”，指脉象豁然空虚，为气血亏虚之象。半产后发热，前医广服滋阴之药不愈，孟英以当归补血汤、小建中汤温补获效，说明病机为血虚阳浮，非阴虚发热。脉豁然提示血虚气弱，故用阳和之品补血建中而热退。", []], "13329": ["预后", "原文未直接描述脉象，但言“心脾之脉尚有根，犹可望也”，以脉有根判断预后。患者体弱、汛多、便溏、冷汗气逆，屡进参耆而病危，孟英诊得心脾脉有根，说明胃气未绝，故可救。用重镇潜阳、滋填下元之剂而转机，体现脉有根者生。", []], "13330": ["病机", "脉虚弦软数，虚为阴血不足，弦为肝阳上亢，软为气弱，数为虚热。结合舌光赤无苔、头疼口燥、寝汗减餐，乃真阴亏虚、阳升无液、冲气上逆之候。孟英断为冲气上逆之嗽，非外感，故用潜阳镇逆、滋养肝肾而愈。", ["虚", "弦", "软", "数"]], "13331": ["病机", "两脉上溢，左兼弦细，上溢为阳气上逆，弦细为阴血亏虚、肝阳不潜。患者干嗽无停、目不交睫、口渴无苔，乃真阴久虚、风阳上潜、冲嗽不已，有厥脱之虞。孟英用潜阳镇逆之方，若作郁治而开泄，必致危殆。", ["弦", "细"]], "13332": ["病机", "脉甚弦软，弦为肝木偏旺，软为中气虚弱。患者久虚患嗽，误进肾气汤滋腻附桂，致呕恶便溏、不饥无溺，苔腻舌红。孟英断为中虚健运失职，滋腻滞枢机，附桂增肝横，故以培中泄木、行水蠲痰而愈。", ["弦", "软"]], "13333": ["病机", "脉虚弦缓大，虚为气血不足，弦为肝木乘脾，缓大为中气虚弱、虚阳外浮。患者嗽久废寝忘餐、凛寒乍热、经停形瘦、心悸耳鸣，滋补填阴反便泄，孟英谓固虚而非滋阴所宜，予参耆龙牡等大剂温补，旬日而安。", ["虚", "弦", "缓", "大"]], "13334": ["病机", "脉弦细而弱，弦为肝阳不潜，细弱为营血大亏、气不足息。患者晡热、心悸头痛、腰酸腿软、暮则目盲、腹胀自汗带多，舌赤无苔，孟英断为营血大亏，不可作暑治，授人参熟地等滋养奇经、潜阳固摄，数十剂而康复。", ["弦", "细", "弱"]], "13335": ["病机", "脉弦软而微数，弦为肝木失调，软为营阴不足，微数为虚热内扰。患者食蒸饼后腹中攻痛、寒热间作，似疟而非疟。孟英谓营素亏，阳维为病亦能作寒热，八脉隶于肝肾，故以温肾凉肝、濡养奇经之剂而愈。", ["弦", "软", "数"]], "13336": ["病机", "右寸关滑主郁痰，别部虚弦软数示营阴久耗、风阳独炽，指下无情为胃气衰败之兆。痰因火动，故心跳跳跃如舂；阴液将枯，故气逆不眠、面红易汗。脉证合参，属郁痰化火、阴亏风动之危候。", ["滑", "虚", "弦", "软"]], "13337": ["预后", "左脉细软而数、寸尤甚，右尺洪数、寸关不耐寻按，示燥邪薄肺、阴分素亏，源流两涸。细软为阴伤，数为燥热，洪数为胃气败而虚阳外浮。脉证相符，故断其难过惊蛰。", ["细", "软", "数", "洪"]], "13338": ["病机", "脉弦细而滑，弦主肝郁，细为阴伤，滑乃痰聚。七情怫郁，五火烁痰，痰火互结，气机窒塞，升降失常，故坐卧不安、饥不能食、食则滞膈、善恐畏烦。面赤痰黄，皆郁火炼液之征。", ["弦", "细", "滑"]], "13339": ["病机", "脉弦细软涩、重按如无，弦为怒木直升，细软为阴血不足，涩主痰阻脉道。情志郁结，痰随气升，堵塞华盖，治节不行，故目张泪流、口开舌强、胸膈板闷、二便艰涩。脉道不利，非虚脱也。", ["弦", "细", "软", "涩"]], "13340": ["病机", "原文未录脉象，然述心肾不交之人多不能仰卧，仰则肾气不能上承而心气愈浮，故惊窜不寐。又论痰饮阻清阳之旋运，气分偏虚，胸膈满闷发痫。病机在气分偏虚、痰饮阻遏、心肾失交。", []], "13341": ["病机", "原文未出脉象，然述少腹酸坠、溲频数疼，通利升提温补皆不效，反致不食不寐、大解不行、口渴不敢饮、闻声惊悸。孟英断为厥阳为病，不可徒治太阳，先咸苦泄热，续甘润滋阴，不犯通渗而愈。", []], "13342": ["病机", "脉沉弦，沉主气郁于里，弦主肝木失疏。因猝惊而气机逆乱，痰随气升，蒙蔽清窍，故不言不食、不寐不便。别无他苦，知非外感，乃惊则气乱、痰郁神蒙之证。化服苏合香丸以开窍，二帖便通能言。", ["沉", "弦"]], "13343": ["预后", "脉至细数无伦，细为阴亏，数为热炽，无伦者脉律散乱，阴将竭也。两手拘挛如角弓反张，肝无血养；痰升自汗、渴饮苔黄、面赤，皆热极风动、痰火蒙窍之危象。药后脉较和，示阴渐复、热渐退，为转机之兆。", ["细", "数"]], "13344": ["病机", "脉弦伏而滑，弦主气逆，伏为气机郁闭，滑主痰浊。惊则气乱，挟痰逆升，故脉见弦伏而滑；痰气交阻，升降失常，故不知饥、眩晕便秘，甚则昏厥。此非虚证，乃“诸厥应下者”，当降其痰与气。", ["弦", "伏", "滑"]], "13345": ["病机", "脉沉弦而细，沉主里，弦主肝风，细为阴血不足。禀属阴亏，卒闻惊吓，风阳陡动，气逆肢冷，自汗息微，身面青绿，皆阴虚阳越、肝风内动之象。治以镇逆养阴，正合病机。", ["沉", "弦", "细"]], "13346": ["病机", "脉涩而弦，按之甚软。涩主气滞血涩，弦主气结，软为气结而非实邪。因惊恐气结不行，胁痛偏右、便秘神瞀、身面发黄，皆气机壅滞所致。医误作湿热，治之罔效，正因未识气结之机。", ["涩", "弦", "软"]], "13347": ["病机", "脉浮弦而数，浮为阳越，弦主肝风，数为火炽。陡患心悸、肢冷如冰，舌尖赤无苔，乃阴虚阳越，煎厥根萌。阴亏于下，阳浮于上，故脉浮弦而数，治以滋阴潜阳而愈。", ["浮", "弦", "数"]], "13348": ["病机", "脉劲搏指，劲为阳气偏盛、火炎于内，搏指为邪实有余。年越古稀而病狂惑，面赤不言，口涎自流，力大无制，皆禀赋过强、阳气偏盛之征。群医误作神志不足，广投热补，愈服愈剧，正因未察此脉劲搏指之实。", ["劲", "搏"]], "13349": ["病机", "脉大而数，重按虚散。大数为阳热亢盛，虚散为阴不敛阳、根本已亏。两目发赤、牙龈肿痛、狂妄奔走，似实热而脉重按虚散，乃阴虚阳浮、虚火上炎之候。故用参、地、桂、磁等温补镇摄，投匕即安。", ["大", "数", "虚", "散"]], "13350": ["病机", "脉弦滑而微数，弦主肝风，滑主痰，数为火。目偏左视、扬手妄言，苔黄脘闷，乃劳则火升，挟素有之痰上扰清窍。时虽春暮而天气酷热，外热引动内火，痰火交炽，故脉弦滑而微数。治以清火化痰，痰下神清。", ["弦", "滑", "数"]], "13351": ["病机", "左脉弦细而数，右软滑。左弦细数为阴虚火旺、肝风内动，右软滑为痰盛于中。烦躁不眠，误温致狂妄瘛疭，乃阴虚之体，心火炽，肝气动，痰盛于中。脉证合参，先息风清火化痰，后潜阳养阴而康复。", ["弦", "细", "数", "滑"]], "13352": ["主病", "右脉洪滑，洪为阳盛，滑主痰热，故见神呆目瞪、言语失伦、善饥善怒骂詈如狂，此痰火壅盛之狂证。其大父脉弦而缓，弦主肝郁，缓主湿滞，非虚也，乃络脉痹阻，故四肢冷颤，久服温补不痊，治以通络化痰。", ["洪", "滑", "弦", "缓"]], "13353": ["病机", "脉弦而数，弦主肝郁，数主热，结合病起汛后、白带多、昼明了夜妄言，酷似热入血室。能食便行、气上冲、腹时痛胀，为瘀热互结，故径从瘀血治，两服瘀行神爽。", ["弦", "数"]], "13354": ["病机", "脉弦数，弦为肝阳亢逆，数为热，证见头痛睛红、发狂，身不发热，胸腹舒，乃阴虚肝阳陡动，非实热瘀血。温补则狂莫能制，故以三甲、二至滋阴潜阳，佐清肝之品而愈。", ["弦", "数"]], "13355": ["病机", "脉弦软而虚滑，弦软为肝郁气滞，虚滑主痰凝，气逆面青、牙关不开、遗溺便秘、胸次坚硬如柈，皆痰气壅塞之象。冬温尚在气分，非热入血室，故以陷胸合蠲饮化痰，痰涌而厥醒。", ["弦", "软", "虚", "滑"]], "13356": ["病机", "脉弦细若伏，肢冷如冰，苔白如砂，涎沫频吐，头疼而晕，重裘不知温，似寒而实热深厥深。误投热药，饮邪内盛，热邪隐伏，故脉伏肢冷。小溲赤为热据，导痰合雪羹加苦寒，复杯而愈。", []], "13357": ["病机", "脉甚滑数，滑主痰，数主热，证见多疑善恐、寡言善笑、遗精，皆痰热扰心之候。脉与证合，故以清痰火、凉心肝之剂，送当归龙荟丸，四帖而能出署观剧。", ["滑", "数"]], "13358": ["病机", "脉弦滑洪数，不为指挠，弦主肝，滑主痰，洪数为痰火壅盛，证见坐卧不安、如畏人捕、神躁妄闻，痰火猖狂之势。下其痰火，脉证渐平，继清包络肝胆有余以调神志。", ["弦", "滑", "洪", "数"]], "13359": ["病机", "脉虚软以数，虚软为阴分素亏，数为心火外浮，证见时时出汗、不饥溺少、舌绛口干、神情恍惚，乃心阳过扰、火动神浮之虚证，非热邪内陷心包之实证，法宜坚之使凝。", ["虚", "软", "数"]], "13360": ["病机", "左脉弦数，右手沉滑，弦主肝郁，数主热，沉滑主痰。患者因疑惧而广服补剂，致郁痰内结，气机不畅，故见不饥不寐、气升面赤、二便闭涩、痰多易汗、胸次如舂、咽有炙脔等症。此郁痰证误补致剧，脉象反映肝郁化热、痰阻气机之病机。", ["弦", "数", "沉", "滑"]], "13361": ["病机", "脉弦滑而数，弦主肝胆，滑主痰，数主热。患者因惊吓起疑，胆热内蕴，故善疑善虑；热传于胃，胃热蕴隆，发为青腿牙疳。脉象示胆热痰扰，非神志不足，愈补则热愈炽，故先治新病。", ["弦", "滑", "数"]], "13362": ["病机", "脉弦滑而数，弦为肝阳，滑为痰，数为热。患者高年体丰，肝阳内炽，痰阻枢机，液不上承，故舌绛而燥、神悗耳聋、不饮不食、呃忒面红。此非津涸，乃痰热内闭，故以陷胸汤加味清化痰热，一饮而夜得微汗，身热即退。", ["弦", "滑", "数"]], "13363": ["病机", "脉状细软，细为阴亏，软为气弱。患者孀居操劳，肝肾素亏，心阳内亢，故面赤耳聋、舌赤无液、便溏溲赤、痰咸咳逆、腹胀气冲、龈肿巅疼、音低自汗、口中甚辣、心下如焚、两足不温。脉象示气营耗伤、阴火潜燃之病机，治宜镇息。", ["细", "软"]], "13364": ["病机", "右脉软滑而虚，左脉浮弦且数。右脉软滑而虚，示肺伤于燥、治节不行，体质阴亏；左脉浮弦且数，因温以辛甘，致风阳内煽。患者痰嗽、左胁跃动、胸次痒如虫行、痰清便溏，乃上下交虚、风阳烁津之病机，非肺痿。", ["软", "滑", "虚", "浮"]], "13365": ["病机", "脉伏耳，左寸如无。劳心而兼痰火之郁，痰火内闭，气机不畅，故脉伏不见，非心散也。火升面赤、不寐胁鸣，乃惊骇激动肝胆之阳勃然升越，非本病。脉伏反映痰火郁闭之病机，故以人参、黄连、菖蒲等清心化痰开郁。", ["伏"]], "13366": ["病机", "脉虚弦小数，虚为阴亏，弦为肝阳，小数为虚热。赋质阴亏，将交春令，虚阳浮动，故多言不寐、面赤火升、汗出心摇、仓皇欲死。脉象示阴亏阳浮之病机，治以人参、龙齿、牡蛎等潜阳育阴，引以鸡子黄。", ["虚", "弦", "小", "数"]], "13367": ["病机", "脉弦而滑，弦主风阳，滑主痰。病起产后，久卧成瘫，广服补剂无效。面赤苔黄腻、胸闷气升、溲热易汗、耳鸣头晕、腿软痰多，乃风阳内炽、搏液成痰之证。脉象示痰热内蕴，病不在血分，根株非产后，故当从痰火论治。", ["弦", "滑"]], "13368": ["病机", "脉尚弦数，说明肝阳内炽未平。弦主肝，数主热，火虽降而余热未清，肝阳仍亢，故需滋潜善后。此脉与齿痛、肉颤等症相应，属肝阳化火之病机。", ["弦", "数"]], "13369": ["病机", "脉微弦，面红音低神惫，乃本元素薄，心火上炎，内风上僭。微为虚，弦为肝风，虚风内动故肢麻昏晕。不可误作痧闭而投香燥，当以滋潜熄风为治。", ["弦", "微"]], "13370": ["病机", "原文未识脉名，但述左寸关弦大而数，右稍和兼滑。弦大数主心肝阳亢，滑主痰饮。忧思扰动心肝之阳，中挟痰饮，火郁不宣。温补助风阳，滋腻增痰滞，故遍治无功。", []], "13371": ["预后", "左寸细数无伦，尺中微细如丝。细数主心阳过扰，微细主肾阴素伤，真水下竭，真火将施。此脉示阴阳离决，纵有神丹不能接续，故为败证，预后不良。", ["细", "数", "微"]], "13372": ["病机", "脉弦数而滑，弦主肝胆，数主热，滑主痰。面白唇红，目光炯炯，苔黄羞明，乃惊恐致痰涎阻窍，心肝胆胃热扰。非虚非祟，当清心肝胆胃以化痰热。", ["弦", "数", "滑"]], "13373": ["病机", "脉浮弦洪滑，浮主表，弦主肝风，洪主热盛，滑主痰。吸受热邪，适服参汤助热，痰热内闭，故昏瞀妄言、汗多面赤。治以清热熄风化痰，使邪从下利而解。", ["浮", "弦", "洪", "滑"]], "13374": ["病机", "脉沉弦而数，沉主里，弦主肝，数主热。周身麻木、瘫痪、口苦渴、溺热如火，乃肝经郁热，痰火内扰，气逆欲呕。虽饮姜汤暂适，实热深伏，故以苦寒泻火。", ["沉", "弦", "数"]], "13375": ["预后", "初脉甚迟缓，苔黄腻便秘，痰热内滞而脉道不利。后脉形滑驶如蛇，滑主痰，驶如蛇为真脏脉见，胃气已绝，故断其不起。此脉象由迟缓转滑驶，示病进危候。", ["缓", "滑"]], "13376": ["病机", "脉弦缓而滑，弦主肝风，缓主湿，滑主痰，合之则为风痰内伏。患者年近古稀，左半不遂，颧赤苔黄，音微舌蹇，便涩无痰，显系痰热内蕴，伏而未化，阻滞经络。孟英断为“痰中也”，故以清热涤痰、通络开窍之剂取效。", ["弦", "缓", "滑"]], "13377": ["预后", "六脉弦强无胃，弦为肝木亢盛，强为邪实，无胃气则失柔和之象，主胃气已败。症见热逾半月，胸腹胀痛拒按，便秘溺赤，舌黑口干，自汗烦躁，似结胸而实为温热逆传，邪盘胃府。脉无胃气，故断为不治，越二日而殁。", ["弦", "强"]], "13378": ["病机", "脉来弦涩而数，右寸关弦软以滑。弦主气郁，涩主血滞，数主热，滑主痰。患者胁痛畏风，周身络胀，食少便难，日晡寒热，乃升降之令久窒，痰邪袭于隧络，关格之势将成。孟英以脉证合参，断为痰邪阻络，故用清化痰热、疏利气机之品。", ["弦", "涩", "数", "滑"]], "13379": ["病机", "脉沉弦且滑，沉主里，弦主郁，滑主痰，数主热。患者心悸眩晕，汗出肢冷，气逆欲脱，似虚而实为痰热内蕴，误补则气机壅塞。舌绛苔黄腻，口苦溲热，汛事仍行，皆痰热之征。孟英以清热涤痰获效，后脉极滑数，仍主痰热未净。", ["沉", "弦", "滑", "数"]], "13380": ["预后", "脉甚弦滑，弦主肝旺，滑主痰盛，舌色光绛为热灼阴伤。患者体厚蹒跚，眩悸发肿不饥，本属痰热，医误作虚而久服温补，致痰热愈壅。再诊脉数七至，数而急疾，主热极阴竭，胃气已败，眠食尽废，故断为不可救药，果及秋而殁。", ["弦", "滑", "数"]], "13381": ["病机", "初诊脉滑，滑主痰，故作痰治。误补后脉极细数，细为阴伤，数为热，阴已伤矣。症见目赤便秘，胸下痞塞如柈，闻声惊惕，寒颤自汗，肢冷如冰，似虚而实为痰饮内伏，郁而化热。孟英力辨其非虚，投清化痰热之剂而安。", ["滑", "细", "数"]], "13382": ["病机", "脉弦滑，弦主肝郁，滑主痰。患者眩晕脘痛，筋掣吐酸，渴饮不饥，咽中如有炙脔，皆肝郁化火、痰热内阻之象。前医与温胃药，病日剧，盖温燥助热。孟英以和肝开郁、清痰降火之剂，十余剂而愈。", ["弦", "滑"]], "13383": ["病机", "脉弦细而涩，弦主肝胆火炎，细主阴亏，涩主血少。患者年未冠而体弱，夜梦如魇如惊，肢摇目眩，醒后纳食如常，月一二发，乃真阴不足，肝胆火炎，神魂不宁所致。孟英以滋阴降火、安神之剂，竟刈其根。", ["弦", "细", "涩"]], "13384": ["病机", "前案脉浮弦以滑，浮为风阳上扰，弦主肝风，滑为痰壅，故用顺气蠲痰、息风降火而痊。后案脉微弱而弦，微弱为气阴两虚，弦为肝风内动，属虚风上扰，故以镇补摄纳获效。两案脉象不同，病机虚实迥异，辨证关键在脉之有力无力。", ["浮", "弦", "滑", "微"]], "13385": ["病机", "脉沉而有弦滑且数之象，沉主里，弦主肝风，滑主痰，数主热。过投温补，引动肝风，煽津为痰，痰乘风上而晕厥；余波奔流经络则抽搐，阳气逆上则鼻塞面浮，浊气不降则便滞不饥。脉象揭示肝风痰热内蕴之病机。", ["沉", "弦", "滑", "数"]], "13386": ["病机", "脉象弦驶，弦主肝阳，驶为急疾，示肝阳浮越、气逆上奔。夜坐阳升，饮酒益浮肝阳，惊则气更上逆，故心跳欲吐、气逆如喘、肢麻手握、语言难出。此痰闭气结之候，苏合香丸辛香通气而愈。", ["弦", "驶"]], "13387": ["病机", "脉来弦缓，弦主肝气，缓主湿滞。饱食后大吐而厥，腹痛异常，口苦渴，二便不行，乃痰滞而热伏厥阴，肝气无从疏泄。脉弦缓正合痰滞热伏、肝失疏泄之机，故投雪羹、栀、楝等清疏而愈。", ["弦", "缓"]], "13388": ["预后", "未识脉名，仅言「按其脉尚不绝」，示生机未绝。虽面色灰黯、戴眼口开、一息奄奄，脉尚不绝则元气未散，故可救。与菖蒲、胆星、竹茹、旋覆等涤痰开窍，和童溺、牛黄至宝丹灌之，复杯而起。脉不绝为预后可治之关键。", []], "13389": ["病机", "脉虚大，虚为气阴不足，大为阴不敛阳、虚阳外浮。患吐血，肌肤枯涩，口渴，乃气分之阴亏，非阳虚温补所宜，亦非纯滋填可谬。脉虚大正示气阴亏虚、虚火上炎之机，故以参、耆、二冬、知母等益气养阴而愈。", ["虚", "大"]], "13390": ["病机", "右关洪滑，洪为阳明热盛，滑为痰热内壅。吐血盈碗，自汗口渴，稍动血即上溢，皆胃热迫血妄行之候。脉洪滑有力，证实非虚脱，故用白虎汤加西洋参、大黄炭清胃泻热、凉血止血，一剂霍然。", ["洪", "滑"]], "13391": ["死脉", "左寸如钩，为心之真脏脉；瞥瞥如羹上肥，为真气散漫之象。前案邪壅脉怪而搏指不挠，证实脉亦实，可攻可通；此案真气散漫，脉来瞥瞥如羹上肥而左寸如钩，是神病刀圭莫济，故断不能复。脉象揭示真脏见、胃气竭之死候。", ["实"]], "13392": ["病机", "六脉缓滑，缓为胃气冲和之象，滑主血盛。患者久患齿衄，乃血热上溢，今脉见缓滑，非病进之征，而是天癸将至、阴血充盈之候。血海将满，冲任流通，故脉滑而缓。孟英断为天癸将至，治以活血通经，使血循常道，一剂知，数日愈，寻即起汛，略无他患，正合脉证。", ["缓", "滑"]], "13393": ["病机", "脉形豁大，非实热之洪大，乃阴亏阳浮、虚火上炎之象。面有红光、足冷，正是火不归原、上热下寒之征。前医连进归脾汤温补升提，反助虚火，故吐益甚。孟英以六味地黄汤送肉桂心引火归原，使浮阳下潜，复杯而愈。脉形豁大在此主虚阳外越，非邪盛也。", ["洪", "大"]], "13394": ["病机", "脉弦而数，弦主肝阳，数主热盛。冬暖失藏，雷声大振，人身应之，肝阳乃动，血随气上溢而为鼻衄如注。体肥头汗，似虚而实非虚脱，乃肝阳化火迫血妄行。孟英断不可温补，投凉肝降逆、清热止血之剂，一剂知，二剂已。脉弦数正是肝阳动、血热上溢之病机。", ["弦", "数"]], "13395": ["病机", "脉数舌绛，数主热，绛主阴伤。便血本属湿热下注，医投温补，血虽暂止而湿热未清，反伤阴液，致泄泻浮肿。脉数舌绛正是湿热内蕴、阴液被灼之征。孟英以芩、连、栀、芍清热利湿，桑叶、丹皮、银花、石斛养阴凉血，使湿热去而阴液复，旬余而愈。", ["数"]], "13396": ["病机", "脉弦涩，弦主肝郁，涩主血瘀。陡吐狂血而肢冷自汗，血紫黯，乃肝郁气滞、瘀血内凝，血不循经而妄溢。证虽可愈，然瘀根未除，复发难瘳。孟英以丹参、丹皮、茺蔚、旋覆等活血化瘀、疏肝降逆，复杯果愈。后不能惩忿，逾二年复吐竟不起，正合弦涩主瘀、情志致郁之机。", ["弦", "涩"]], "13397": ["病机", "左手如无，右弦软按之数。左脉如无，阴血大亏；右弦软而数，肝阳陡动、热在气分。高年阴分久亏，肝血大去，风阳上扰，故汗出神昏、肢冷搐溺、躁乱妄言。由忿怒及久服姜枣汤、烧酒助热所致。孟英急止参汤，恐补气助火，以西洋参、犀角、生地等凉血熄风、养阴清热。", ["弦", "软", "数"]], "13398": ["病机", "脉弦洪而芤，弦主肝阳，洪主热盛，芤主阴血亏虚。年逾花甲，冬间广服助阳药，热亢阴虚，迫血上溢而为鼻衄不止。面黑黯而有红光，乃阴虚火旺、虚阳上浮之象。孟英以大剂犀角、元参、茅根等清热凉血、滋阴降火，投匕而安，续予滋阴填补而康。脉弦洪芤正合热亢阴虚之机。", ["弦", "洪", "芤"]], "13399": ["病机", "脉弦滑上溢，弦主肝郁，滑主血盛，上溢示血随气逆。齿衄五日不止，去血已多，诸方不应。孟英断为经血逆行，询之经事果愆期。肝郁化火，血热上溢，冲任之气上逆，故脉弦滑上溢。投犀角、泽兰、元参、旋覆等凉血降逆、活血通经，使血循常道而安，继用滋阴清热渐康复。", ["弦", "滑"]], "13400": ["病机", "脉弦滑而搏指，右手较甚，弦主肝郁气滞，滑主痰热内蕴，搏指为邪实亢盛之象。患者久患吐血，前医误用滋阴，致痰热胶结，肺胃热盛，故渴喜冷饮、米谷碍于下咽、小溲如沸、夜不成眠。此脉说明痰热壅肺、肝火犯胃之病机，非虚证可温补。", ["弦", "滑"]], "13401": ["病机", "脉弦数，弦主肝郁，数主热盛，结合舌苔黄、溺短赤，说明肝经湿热下注大肠，灼伤血络，故便血三十余年。前医误作虚寒温补，反助湿热。此脉证实为痔血，非一般便血，治当清肝凉血、肃肺祛痰，故用苇茎合白头翁汤加减。", ["弦", "数"]], "13402": ["病机", "右脉洪数，洪为阳明热盛，数为热邪亢盛，右脉候肺胃。患者怀妊患嗽，嗽则鼻衄如喷，憎寒乍热，口渴头疼，此肺胃热盛、外寒束表、伏热蕴隆之病机。虽时值隆冬，脉证如是，当用白虎汤清解里热，合葱豉以透表，即麻杏甘膏之变法。", ["洪", "数"]], "13403": ["病机", "脉弦洪而数，弦主肝火，洪主阳明热盛，数主热邪亢盛。患者素善饮，积热于内，暑火外侵，又误服香窜燥烈之痧药，致火益热，血涌如泉。此脉说明阴虚而热邪炽盛，非单纯阴虚，亟当清解客热，俟热退血止再为滋养。", ["弦", "洪", "数"]], "13404": ["预后", "左脉虚弦而数，右软大，虚弦为肝阴亏虚、肝阳偏亢，数为虚热内扰，软大为气散不敛。症见气逆自汗、足冷面红、夜不成眠、音低神惫，此心境不怡、肝多怫郁，致气散血竭之虞。其妻脉至弦细，亦水亏木旺。脉候如斯，预后堪忧，故有气散血竭之虞。", ["虚", "弦", "数", "细"]], "13405": ["病机", "脉滑而数，滑主痰湿或郁热，数主热盛。患者久患内热，鼻衄龈宣，溺赤便艰，睛红口渴，热象毕露，前医误作阳虚温补，致热愈炽。此脉说明郁热内蕴、湿热下注，阳萎乃因热而萎，非阳虚。服清解之剂后郁热泄而阳事通，梦遗即郁热外泄之征。", ["滑", "数"]], "13406": ["病机", "脉沉弱而弦，沉主里，弱主胃气久伤，弦主肝气横逆。患者久患脘痛，按之漉漉有声，便闭溲赤，口渴苔黄，绝粒五日，诸药下咽倾吐无余，此肝气挟停饮上逆之病机。素嗜瓜果，胃阳久伤，故于平肝涤饮之中加参以扶胃气，用海䖳、荸荠等取效。", ["沉", "弱", "弦"]], "13407": ["病机", "脉沉而弦，沉主里、主气滞，弦主肝郁、主痛。患者右胁痛，医与温运药病益甚，致音瘖不能出声，仰卧不能反侧，坐起则气逆如奔，便溺不行，汤饮不进，此肝气郁结、痰浊内阻、气机升降失常之病机。治以旋覆、赭石等降逆化痰、疏肝通络，一剂知，数剂愈。", ["沉", "弦"]], "13408": ["病机", "脉沉弦，沉主里，弦主肝主痛。患者腰腿串痛、闻声筋掣，乃肝血不足、筋脉失养，又因温补致积痰蕴热，胶固不开。脉沉弦正合肝郁痰滞、内热胶结之病机，故治以清痰泻热，兼养肝血。", ["沉", "弦"]], "13409": ["病机", "脉弦软而数，弦为肝火，数为热盛，软为久病正伤。患者素患脘痛，误服温补，致肝火炽盛，形瘦浮肿、胁背刺痛、心辣如焚，皆肝经伏热、诸经郁火之象。脉象与症相符，故治以清肝泻火、养阴泄热。", ["弦", "软", "数"]], "13410": ["病机", "脉虽沉伏难寻，然痛脉多沉，且苔黄腻、口干溺赤，显系湿热内蕴、气机壅滞，非元虚欲脱。沉伏之脉主邪闭于里，气血不畅，故腹痛自汗、肢冷息微，当从证辨为实热内结，治以清化湿热、行气止痛。", ["沉", "伏"]], "13411": ["病机", "脉细数，细为阴血不足，数为热象。患者小溲涩痛，医误渗利，反发热头疼、不饥口渴、夜不成眠，乃阴虚肝郁化热生风，津液已烁。脉细数正合阴虚内热之机，故不可再利，治以滋阴清热、疏肝熄风。", ["细", "数"]], "13412": ["病机", "脉细而弦滑，弦主肝风，滑主痰，细为阴伤。崩后脘痛发厥、自汗肢冷，乃素体多痰、风阳内鼓，病不在血。后脉弦滑而数，为风痰化热、扰及心神，故发狂笑骂。脉象揭示风痰内动、热扰神明之病机。", ["弦", "滑", "数"]], "13413": ["病机", "脉弦细软数，弦为肝郁，细软为阴亏，数为内热。患者素属阴亏，情志抑郁，咳逆胁痛、苔腻痰黏、便难溲少，乃肾不纳气、肝不舒、肺不清、胃不降。脉象反映阴虚肝郁、痰热内阻、气机升降失常之病机。", ["弦", "细", "软", "数"]], "13414": ["病机", "脉弦数，弦主痛主肝，数主热。患者腹痛因食羊肉面条，医误消导、燥热，致痛甚而渴、得饮大吐、二便不行，苔干微黄。脉弦数示肝经郁热、肠胃燥结，非寒非食滞，故治以清热通降、柔肝止痛。", ["弦", "数"]], "13415": ["病机", "脉弦软微滑，弦为肝郁，软为阴虚，滑为痰滞。患者环跳穴痛、转筋上冲、肢冷自汗，畏热知饥、溲赤便坚、舌红不渴，乃阴虚而痰气滞于厥阴。脉象揭示阴亏痰滞、肝经气机不畅之病机，故治以养阴化痰、疏肝通络。", ["弦", "软", "滑"]], "13416": ["病机", "脉弦滑且数，弦主肝逆，滑主痰盛，数主热。原文谓“伏痰内盛，肝逆上升，而兼吸受暑热”，故脉见弦滑数。痰热内伏，肝气上逆，则气冲欲厥、脘痛莫当；暑热内扰，则呕吐发热、渴喜冷饮、便秘溲热。此脉象明确提示痰、肝逆、暑热三者交炽之病机。", ["弦", "滑", "数"]], "13417": ["病机", "脉弦滑而软，弦滑为饮邪内停，软为正气不足。原文断为“中虚停饮”，中气素虚则运化失职，饮停于中，故脘痛吐水；吐后能食而不能吃饭，乃饮停气阻。脉软正合中虚，弦滑应饮。此脉主中虚饮停之病机，与脘痛、吐水、委顿等症相应。", ["弦", "滑", "软"]], "13418": ["病机", "左关尺弦数无伦，弦为肝阳亢盛，数为热炽，关尺应肝肾。原文谓“肾阴大亏，肝阳极炽，营液耗夺，八脉交虚”，阴亏不能涵木，肝阳化火，故脉弦数无伦。症见形消舌赤、彻夜无眠、腰腹左痛、带下如注，皆阴亏阳炽、八脉交虚之候。", ["弦", "数"]], "13419": ["病机", "脉弦细以软，弦主肝郁，细主阴亏，软主气弱。原文谓“暑湿内伏而肝郁不舒，且阴分素亏，复伤劳倦”，肝郁则脉弦，阴亏则脉细，劳倦伤气则脉软。症见喉偏左痛、神疲欲卧、动即凛寒、痰多且韧，正合暑湿内伏、肝郁阴亏之机。", ["弦", "细", "软"]], "13420": ["预后", "两脉弦数，弦为肝阳亢盛，数为热炽，舌绛无津、汛断半年、破䐃脱肉，显系阴液枯涸、肝阳独亢。原文引《经》言“九候虽调，犹属不治”，又谓“危殆若此，不能过”，故两脉弦数在此段主预后不良，示阴竭阳亢、化源告绝之危候。", ["弦", "数"]], "13421": ["病机", "脉弦软，弦主饮停气阻，软主正气不足。原文断为“停饮”，饮停则液不能上，故口渴而不欲饮；水凌火则心掣惊寤；遏其流则得食痛加。舌上脱液虽属阴虚，亦由饮隔。脉弦软正合停饮内阻、气化不利之病机，与脘下疼胀、涌水苦辣、溲少神疲相应。", ["弦", "软"]], "13422": ["病机", "左脉弦数，右脉虚软。弦数为肝经郁热，虚软为气阴不足。原文以梦遗久治不愈为主症，兼耳出脓水、目泪难开、肩胁胸背酸疼、微有寒热、食减神疲，显系肝热下扰精室、气阴两虚之候。左弦数应肝热，右虚软应脾肺气弱，脉症相合。", ["弦", "数", "虚", "软"]], "13423": ["病机", "脉大微弦，大为劳倦内伤、气血亏虚，微弦为虚中夹肝脾不和。原文载久患寒热、精遗自汗、能食神疲、肌肉渐瘦，显系中气亏虚、阴阳营卫失调。脉大而微弦，正合虚劳建中之证，故予黄耆建中加参、归、龙、牡而瘥。此脉主虚劳病机，与寒热、自汗、遗精、消瘦相应。", ["大", "弦"]], "13424": ["主病", "耄年脉实，非虚衰之象，乃天禀独厚、阳热内结之征。腹胀便秘属阳结，实脉应之，说明邪热壅盛、腑气不通，故法宜清火通下。若误认老年气弱火衰而投温补，则实实之戒，必致腹如抱瓮、不可救药，原文正以脉实为辨证眼目。", ["实"]], "13425": ["主病", "脉滑实，滑主痰盛，实主邪结。患者气逆躁烦、便秘面赤、舌绛痰多，显系痰热内结、腑气不通之实证。滑实脉与痰多便秘相应，故以承气汤下之霍然。若因年高而迟疑，则邪无出路，原文以脉断证，正见实脉不可妄补。", ["滑", "实"]], "13426": ["病机", "右寸沉滑，主痰邪壅肺；左手细数而弦，主阴亏而肝阳偏亢。高年阴亏，温邪在肺未经清化，反为补药所锢，故涕泪全无、耳闭不饥、二便涩滞、干嗽无痰。沉滑示邪闭于上，细数弦示正虚于下，故宜开痹通胃，清化而不峻补。", ["沉", "滑", "细", "数"]], "13427": ["主病", "脉坚体厚，坚为邪实内结之象，体厚示形气不衰。溺秘欲死、口渴苔黄，显系湿热火毒蕴结下焦，膀胱气化不行。坚脉与实热闭结相应，故用知、柏、栀、楝清火，犀、菀、蒌、茹通利，送当归龙荟丸直折其火，竟不复发。", ["坚"]], "13428": ["病机", "脉弦数左溢，弦主肝郁，数主热，左溢示肝阳勃升于左。患者体弱而腹痛欲厥，医误作虚寒镇逆通补，势日甚。原文点明因忿怒而肝阳勃升，便秘不饥、口苦而渴皆肝火内炽之症，故以清肝降火、下左金丸而愈，弦数左溢正是辨证关键。", ["弦", "数"]], "13429": ["病机", "右寸关弦滑而浮，主痰实于上兼客热；左关尺细软无神，主阴虚于下。高年痰嗽喘逆、便秘不眠、微热不饥，正是上实下虚之候。弦滑浮示痰热壅肺，细软无神示肾阴亏虚，故攻补难偏任，用清上滋下、浊药轻投之法，一举两全。", ["弦", "滑", "浮", "细"]], "13430": ["预后", "脉弦细而涩，弦主邪郁，细主阴伤，涩主血少气滞。证交十四日，骨瘦如柴、舌光紫布白糜、少腹拒按、势将喘逆，虽属下证而形脉如此，正虚邪实，法难直授。原文以弦细涩断其不可峻下，先外治通阳，再以滋阴润下缓图，脉象示预后险重。", ["弦", "细", "涩"]], "13431": ["主病", "脉滑数，滑主痰湿，数主热毒。妇人服外洋丸药后便秘两月，面赤龈胀、银针拔出如煤黑，显系药毒蕴结、阳明热盛。滑数脉与热毒内壅相应，故用犀角、石膏、硝、黄解毒通下，佐升麻、蜣螂透毒，服后登圊而病减半。", ["滑", "数"]], "13432": ["病机", "脉虚软而涩，虚软为根蒂素亏、气血不足之象，涩则血少而气机痹塞。经停乳少、泛泛欲呕，是血虚肝乘于胃；率投滋腻致脘闷不饥、气逆嗽痰、二便秘涩，乃窒滞不行、略受风邪无从解散，九窍不和。脉症合参，病本在阴血亏虚，标在气机痹塞，故先开上、次宣中、继滋下。", ["虚", "软", "涩"]], "13433": ["病机", "脉迟软，迟为阳气不运、健运迂迟，软为气分不足。患者久患痹证，坐卧不安，中气馁弱，脾运迂迟，故粪黑而坚如弹丸、旬余一更衣；舌润不渴、小溲甚多，皆非燥热内结，乃气虚液不濡布。所谓中气足则便溺如常，故用大剂参、术补气，旋转中枢，非凉润所能治。", ["迟", "软"]], "13434": ["病机", "脉虚弦而弱，虚弱为正虚，弦为肝风内动。年逾古稀，阴血已亏，肝木失养而生虚风，风耗津液，肠道失润，故便秘不舒、时欲挐挣、汗出头晕。前医误作肝气素滞，投麻仁丸峻下，其势孔亟。此属虚风秘结，治当益气养血、柔肝息风，非攻下所宜。", ["虚", "弦", "弱"]], "13435": ["病机", "脉软而微，软为阴虚，微为阳气衰微、气化无权。溺秘不行，腰腹皆胀拒按、胸高腿肿、舌绛无津、渴喜沸饮，是阴液枯涸而气化不行，水湿内停。前医温、凉、利、涩杂投不效，反增胀满。故以养阴之中加附子、桂心温阳化气，煎成冷服，使溺出便行，乃阴虚气化无权之的证。", ["软", "微"]], "13436": ["妇人", "本段未载具体脉象，主旨论妊娠脉之难切。孟英诊黄履吉室人，断为妊，而是月天癸犹来，次月仍转但不多，孟英谓汛不断者乃荫胎之血有余，逾月经更少，四月后经停娠显，娩如期。说明妊娠脉有时可凭、有时不足凭，真学问人不恃虚言眩世，故列妇人门。", []], "13437": ["妇人", "本段未载脉象细节，仅言孟英切脉即断怀麟。患者偶有小忿，经事涩少、腰腹微胀，自以为怒气所滞，孟英凭脉断为妊娠，初疑后信，卯春果弄璋。说明经少腹胀有因孕而致者，不可概作气滞血瘀论治，切脉辨娠自有其神妙，故归妇人门。", []], "13438": ["妇人", "本段未载具体脉象，论娠孕之脉最为难凭：有初娠即现于脉者，有三四月始现者，有始终不现者。孟英治石诵义室，脘痛甫愈、汛逾期即断为娠，果日形著。可见凭脉断证有时可凭、有时不足凭，同一至理，真学问人必不恃虚言以眩世，故列妇人门。", []], "13439": ["病机", "两尺皆浮，左寸关弦。尺脉当沉而反浮，是肾失闭藏之职；左寸关弦，是肝木太过、独行疏泄之权。半产后营分不摄、淋漓数月，正由肝疏泄太过、肾闭藏失职。填补肾阴以涵养肝木，加黄柏苦坚、螵蛸涩固，故收效倍捷；仲秋脉断受孕，然涵养无权，仲冬果堕胎。", ["浮", "弦"]], "13440": ["妇人", "脉甚滑疾为妊娠之象，滑主血盛，疾主胎气鼓动；后诊魏子恒室脉虚微软数，虚微为气血不足，数亦主胎，故虽诸医作虚损治，孟英仍断为妊。原文以脉滑疾辨娠，又脉虚微软数亦主孕，说明妊娠脉象非一，总以滑数为主，虚微者因体弱而兼见。", ["滑", "疾", "虚", "微"]], "13441": ["妇人", "脉弦滑左甚，弦主肝郁，滑主痰湿与胎孕。患者素阴虚肝滞，痛胀少餐，暮热形消，咽疼喉癣，不孕育者九年，旧恙弥增，经三月未转，似虚损难延；然脉不细而弦滑左甚，左关候肝，滑为血盛，故断为熊罴入梦，果得子。说明脉象不细、肤犹淖泽，虽病久仍可带病延年，且能受孕。", ["弦", "滑"]], "13442": ["病机", "脉来沉实而数，沉主里，实主邪实，数主热。堕胎后恶露虽行，而寒热头疼、自汗、冷自心中出，医误作类疟与温化，病日甚；舌色紫黯，脉沉实数，乃瘀血为患，瘀阻化热，故予桃仁、泽兰、红花等活血化瘀之剂，服后腹大痛，瘀下而愈。", ["沉", "实", "数"]], "13443": ["妇人", "脉甚滑，按之不绝，滑主血盛，为孕也；询经果愆两度。娩后脉洪大，按之虚软，洪大为热盛，虚软为气阴不足，故见气逆碍眠、嗽则汗出、便溏遗溺、口渴不饥，乃产后气阴两虚、虚热上浮之候，治以沙参、黄耆、牡蛎等益气养阴而愈。", ["滑", "洪", "大", "虚"]], "13444": ["妇人", "脉滑而弦，滑主血盛，弦主气滞，虽产后三月汛未行，诸症似蓐损，然脉滑弦，故以孕断。患者气自少腹上冲，似有聚瘕，呕恶腹痛，面黄形瘦，溲热便溏，口渴带多，面浮咳逆，皆孕后气滞痰阻、肝胃不和之象，与沙参、苏叶、黄芩、枳壳等调气清热而安，后产一女。", ["滑", "弦"]], "13445": ["误治", "原文未识脉名，仅言切脉时壮热烙指，汗出如雨，汗珠落于脉枕微有粉红色。患者素禀怯弱，汛不行，胁腹聚气如瘕，减餐肌削，屡服温通，至秋微寒壮热，医仍作经闭治，势濒于危。孟英断虚损为本，暑热炽盛为标，先治客邪，用白虎汤加味，此急则治标之法，而何医拘于血虚胃弱禁用石膏，反致危殆。", []], "13446": ["病机", "左弦而数，右滑以驶，弦主肝郁，数主热，滑驶主痰热内壅。患者脘痛过投香燥，渐增头疼眩晕、气逆呕吐、痰多不寐、便溏不食、经事不行，诸医误补，病日以进。孟英曰病药耳，脉证相参，知为药误致痰热内扰，故用清淡对证之剂，旬余可瘳。", ["弦", "数", "滑", "驶"]], "13447": ["病机", "脉弦滑而数，弦主肝郁，滑主痰湿，数主热。患者经行腹痛十年，医进胶艾汤温燥腻补，痛日盛而加呕吐，经至益频，痛势剧，满床乱滚；脉弦滑数，故知巅痛口渴、带多腰痛、汛色紫黑，皆肝经郁热、痰火内扰之候，治以芩、连、栀、胆等清肝泻火化痰，半年而蠲。", ["弦", "滑", "数"]], "13448": ["病机", "脉弦巅痛，乃营虚肝郁，微挟客邪。产后营血亏虚，肝失濡养，气机郁滞，故脉弦；巅顶作痛，为肝经郁滞、清阳不升之象。前医误投升散，更伤营阴，致腹膨气逆、肢痉欲厥。此脉弦主肝郁营虚，非外感实邪，故以清解轻宣而愈。", ["弦"]], "13449": ["病机", "脉弦软而细，是营阴素亏、气机多郁、郁久生热之候。弦为肝郁，软细为阴血不足，脉道不充。症见面赤足冷、口糜而渴、得饮即吐、五内如焚，皆郁热内扰、气机升降失司所致。辛燥忌投，故以清宣养阴获效。汛停由血不足，非血瘀阻隔。", ["弦", "软", "细"]], "13450": ["病机", "脉至软滑虚弦，乃阴亏水不涵木、风阳内炽、气郁痰凝之象。软虚为阴血亏虚，滑为痰凝，弦为风阳内动。症见头痛神疲、形瘦内烦、渴喜热饮、纳食滞膈、络胀少眠，皆风阳痰热扰于内。故以宣养清潜互用，佐外敷赤块。", ["软", "滑", "虚", "弦"]], "13451": ["病机", "脉弦滑而数，非虚劳之候。弦为肝阳内盛，滑为搏液成痰，数为热象。痰热阻塞气机，故凛寒乍热、咳逆、眩晕、形消面赤。前医误补，致盗汗带频。法宜清展，以清化痰热、展布气机为治，二十剂而健。", ["弦", "滑", "数"]], "13452": ["病机", "脉弦而数，乃肝郁化火、血热妄行之病机。半产之后，阴血亏虚，肝失条达，郁而化热，故汛事先期、淋漓不断；龈衄、苦渴苔黄，皆热伤血络、津液受灼之征。频服补剂而久不瘳，以补反助郁热。治以清肝凉血、柔养调经而愈。", ["弦", "数"]], "13453": ["病机", "脉弦数，舌绛无苔，乃肝郁深沉、木火内烁、耗津阻气之候。弦为肝郁，数为火炽。木火刑金则胸闷气逆，耗津则便秘呕渴，扰及心神则不眠，下迫则带下如注。此非小柴胡、逍遥散所能解，故以小陷胸加清降之品，使气机出入有权而愈。", ["弦", "数"]], "13454": ["平脉", "脉六部皆缓滑而长，左寸关带弦数。缓滑而长为气血充盛、脾胃健运之象，故年五十而天癸不衰、肌肤似三十许人。左寸关弦数，乃肝郁化热之微兆，与其多产、微带相关。此段以脉测体质，属平脉范畴，非病脉。", ["缓", "滑", "长", "弦"]], "13455": ["病机", "脉来细数，乃阴血亏虚、虚热内扰之病机。崩后淋带，阴血耗伤，脉道不充故细；虚热内生故数。五内如焚、溲热口干、头晕耳鸣、夜不能寐，皆阴亏阳浮、虚火扰神之症。滋补杂投不效，以气机未展，先清展后潜阳养血而痊。", ["细", "数"]], "13456": ["病机", "脉滑数有力，滑主痰湿，数主热，有力为实，故断为气实血热。血热妄行则漏血、吐血；气实上逆则纳食即吐。前医误补，反助病势，愈补愈漏。胎无血荫而不长，因气分坚实故不堕。此脉象揭示病机为实热而非虚，故用清营药取效。", ["滑", "数", "实"]], "13457": ["病机", "右寸脉滑大搏指，右寸候肺，滑主痰，大主热盛，搏指为邪气壅实。肺气壅塞则咳逆，震动胞系致半产。此非元气虚弱，乃病气侵扰，故治当清肺治病以保胎。若误投温补保胎，则肺气愈壅，咳逆愈盛，胎必堕矣。脉象明确指向邪实病机。", ["滑", "大"]], "13458": ["病机", "脉弦洪而数，弦主肝旺，洪主热盛，数主热，合为血热肝旺之象。血因热而崩，胎因崩而堕。前医误认产后宜温，用温药致虚象日著、汗出昏晕。孟英指出热未化寒，仍当清热凉血。脉象始终提示热盛，故治法不变。", ["弦", "洪", "数"]], "13459": ["病机", "脉洪数，洪主热盛，数主热，舌绛燥，为热毒炽盛、营阴耗伤之征。热毒上攻则咽糜，下迫则痢，水饮碍下。温补误治助热，胎已朽。脉洪数明确提示热毒内盛，故用犀角、元参等清热凉血解毒，咽腹之疾随愈。", ["洪", "数"]], "13460": ["病机", "脉甚滑数，滑主痰湿，数主热，为痰热壅盛之象。因温补峻投，肺胃下行之令被挽以逆升，致胸次堵塞而疼、喘嗽不能卧、溲闭不饥、浊气壅至清窍而目瞽。脉象揭示痰热壅阻、气机逆乱之病机，故用清化痰热、降气通降之剂。", ["滑", "数"]], "13461": ["病机", "脉涩口干，涩主营阴亏少、血行不畅，口干为热灼津伤。结合昏谵不眠、善呕便秘、汗出不解，断为营阴素亏、邪热内炽。热扰心神则昏谵，热灼津液则便秘口干。脉涩提示阴亏，故用清热养阴之剂，数帖而愈。", ["涩"]], "13462": ["病机", "脉滑数而溢，滑主痰，数主热，溢为脉气浮盛有余，示痰热壅盛、气机逆乱。温散误治后气冲不寐、欲痉厥、脘闷呻吟、渴难受饮，皆痰热内扰、肝风欲动之象。脉象揭示痰热壅实，故用小陷胸加清热化痰降逆之品，大剂投之旬日而愈。", ["滑", "数"]], "13463": ["病机", "脉虚弦软数，虚软主阴虚不足，弦主肝郁，数主虚热。姅后血夺，八脉交虚，阳维为病苦寒热，阴维为病苦心痛。前医误作外感解散，致神疲自汗、不食不眠、泛泛欲呕、时时欲晕、肢麻且软、气欲上冲。脉象揭示阴虚劳瘁、八脉空虚之病机，故用龟板、鹿角霜等补益奇经。", ["虚", "弦", "软", "数"]], "13464": ["病机", "脉软而弦，软为阴液大耗、脉道不充，弦为木土相乘、肝气横逆。怀妊八月，脘痛便溏、跗肿腰疼、频吐绿水，皆肝木犯脾土之象；舌绛无液、口干少寐、形瘦神疲，则阴液耗伤已甚。故脉软而弦主木土相乘、阴液大耗之病机，温补燥烈更劫其阴，治宜培养阴液、柔肝和脾。", ["软", "弦"]], "13465": ["病机", "脉至滑数，滑主痰热内结，数主热邪亢盛。坐草二日未产，小便不通，睛赤口干，显系热结膀胱、气化不达。然原文又言「脉必有虚微之象」，提示滑数之中兼见虚微，乃因胞压膀胱、脾气虚弱不能胜胞所致。故本段脉象主热结气滞兼脾虚不运之病机，通溺催生互用，正合其治。", ["滑", "数"]], "13466": ["病机", "脉虚微欲绝，虚为正气亏乏，微为阳气衰微。新产数日，泄泻自汗、呕吐不纳，气血暴脱，阳气欲绝，故脉道鼓动无力而虚微欲绝。此非三禁可拘，证极可虞，急宜参耆大补以固脱。脉虚微欲绝正是产后气血两脱、阳气衰微之危候，迟补则不及矣。", ["虚", "微"]], "13467": ["病机", "脉弦滑而数，弦主肝热，滑主痰蕴，数主热炽。娩后发热，误服生化汤助其温燥，致面赤热躁、胸闷善悲、肢肿而疼、白泡丛生、便结旬日，皆胎前伏暑蕴毒为温药所激而发。脉弦滑数正合暑热蕴毒、痰热内盛之病机，故犀角地黄清解犹恐不胜，须加清热解毒、化痰透邪之品。", ["弦", "滑", "数"]], "13468": ["病机", "脉软滑微数，软为阴亏，滑为痰饮内盛，微数为阴虚内热。素体阴亏，新产血去，热自内生，故娩后发热；谵妄昏瞀、渴喜热饮，貌似虚寒而实非。前医误认风寒、瘀血，迭进炮姜、桃、桂，阴愈受劫。脉软滑微数正是阴亏痰盛、虚热内扰之病机，故治以蠲饮六神汤加养阴清热。", ["软", "滑", "数"]], "13469": ["病机", "脉数而洪，数为热盛，洪为阳亢阴伤、脉道宽大。产后四肢串痛，误服生化汤、沙糖、酒等温燥，营血耗伤，内风欲动，热势鸱张，故脉数而洪。舌绛大渴，亦为营血耗伤、内热炽盛之征。此非风湿，乃温补酿热、阴亏风动之病机，治宜大剂凉润壮水以息风。", ["数", "洪"]], "13470": ["病机", "脉至梗涩，涩主血瘀气滞、脉道不利。产后腹胀泄泻、面浮足肿，医与渗湿温补月余不效，似气虚而实非；舌色如常、小溲通畅，更非单纯气虚水停。脉梗涩毫无微弱之形，说明瘀血内阻、水气不化，故以行瘀利水之法取效。脉涩正是瘀阻水停之病机关键。", ["涩"]], "13471": ["病机", "脉弦数而滑，弦主肝阳偏亢，数主热，滑主痰。产后经旬，阴血亏虚，肝失血养而阳独盛，肝阳侮胃，故脘痛、寒热气逆、自汗不寐、口渴善呕。前医误投温补涩滞，气机全不下降，诸证蜂起。脉弦数而滑正合阴亏肝旺、痰热中阻之病机，治以肃肺和肝胃，复杯即安。", ["弦", "数", "滑"]], "13472": ["病机", "脉弦滑，弦主木火内动，滑主痰湿内盛。新产血虚，伏暑乘虚而发，痰热内扰，故见发热痉厥、谵语昏狂；恶露仍行，知非瘀血为患。脉象反映伏暑痰热之病机，与胎前伏暑、产后血虚痰滞相应。", ["弦", "滑"]], "13473": ["病机", "脉洪数七至，洪为热盛，数为邪急，且七至示热炽阴伤。温邪内迫，误用温燥，壮热神昏、汗出不止、洞泻如火、小溲不行，皆热邪充斥三焦之候。脉象主暑热内盛，与温邪内陷、津液耗伤相应。", ["洪", "数"]], "13474": ["病机", "脉虚弦豁大，虚为营阴亏耗，弦为肝阳上亢，豁大为阳浮不敛。产后恶露日久，复因悲恸，阴血亏虚，风阳上冒，故干嗽吐血、头痛偏左、不饥不食不眠。脉象主阴虚阳浮，与营阴亏虚、肝风内动相应。", ["虚", "弦", "大"]], "13475": ["病机", "脉弦细虚数，弦为风阳，细为阴亏，虚为营弱，数为热扰。产后营阴素亏，酷暑外烁，风阳浮动，故发热汗多、苔黄眩悸，痉厥之萌。脉象主营阴亏虚、风阳内动，与阴虚阳浮、暑热外袭相应。", ["弦", "细", "虚", "数"]], "13476": ["病机", "左脉弦急，右脉洪滑数，弦急为木火上浮，洪滑数为暑热挟痰。阴虚之体，血去过多，酷暑外烁，津液大耗，伏痰内蕴，故壮热谵语、嗽痰口渴。脉象主阴虚火旺、痰热内盛，与暑热伤津、木火刑金相应。", ["弦", "急", "洪", "滑"]], "13477": ["病机", "脉虚弦豁大，虚为营液大脱，弦为风阳上冒，豁大为阴不敛阳。新产晕汗、目不能开、心若悬旌、毫无恶露，乃阴虚阳浮之候，非瘀血内阻。脉象主阴虚阳越，与营血暴脱、风阳上扰相应。", ["虚", "弦", "大"]], "13478": ["病机", "脉弦滑右甚，弦为风温外袭，滑为痰食内滞，右甚主病在气分。胎前吸受风温，兼挟痰食，虽新产血去阴伤，而证见壮热大渴、腹痛拒按、苔黄燥，病不在营。脉象主风温痰食内蕴，与气分热盛、痰食交阻相应。", ["弦", "滑"]], "13479": ["病机", "脉来洪大滑数，洪大为暑热充斥，滑数为痰热内盛。新娩后微寒壮热、小溲全无、便痢、大渴不眠，皆暑热挟痰湿内阻之候，非疟痢交作。脉象主暑热痰湿内盛，与暑邪弥漫三焦、营阴耗伤相应。", ["洪", "大", "滑", "数"]], "13480": ["病机", "左弦而数，右大不空，弦主肝郁，数主热，大示邪实。泻如漏水、恶露不行、口苦苔黄无溺，显系产后热毒内蕴，肝火下迫，非虚脱之证。故参汤断不可沾唇，予白头翁汤清肝解毒，伏龙肝汤丸止泻，一剂知，三剂愈。", ["弦", "数", "大"]], "13481": ["预后", "右寸关空大，有静中一跃之形，空大主气血大伤，静中一跃为胃气衰败之兆。虽神气安静、苔黄腻、胃略知饥，然脉象不佳，恐有骤变。前医误为脉和，继则寒热复作、腹大痛，更服回生丹而亡，正合空大之脉主元气涣散、预后不良。", ["空", "大"]], "13482": ["病机", "脉滑而数，滑主痰，数主热，结合面赤能餐、汗多畏热、呕渴苔黄，显系燥火伏于肺胃。虽在产后，然恶露流通，血分无病，故法宜清肃上焦，不可拘泥产后禁凉润之说。剂以沙参、知、斛等清润，旬日而痊。", ["滑", "数"]], "13483": ["病机", "脉至虚弦细弱，虚细弱主阴血亏虚，弦为阳不能潜、肝风内动。新产血去之后，八脉皆空，阳失所潜，游行于上，故见咳嗽寒热、齿衄、善怒不眠、四肢牵掣。见证错杂，治当清息风阳，表散攻瘀毫不可犯。", ["虚", "弦", "细", "弱"]], "13484": ["病机", "脉滑数，滑主痰，数主热，合身热痰嗽、白㾦头疼、口渴苔微黄，显系胎前感受冬温，热邪蕴于肺胃。虽产后便溏，然便溏为肺热之去路，故主清解法，清肺热而便溏自止，连服多剂向安。", ["滑", "数"]], "13485": ["病机", "寸关弦滑右大，弦主肝，滑主痰，大示邪实。恶露流通、二便无阻，下焦无病，病与产后无涉。胎已早殒失于早下，浊气薰蒸肺胃，故痰嗽、口糜口臭、气逆自汗。治当肃清肺胃，源澄流洁，不可拘产后宜温之说。", ["弦", "滑", "大"]], "13486": ["病机", "原文未载脉象，然述娩后嗽血，继则两目无光、四肢軃不能动，断为肺热欲成痿躄。肺热叶焦，津液不布，筋脉失养，故致痿躄。治以清肺润燥，用西洋参、桑皮、百合、知母等，服六帖病去大半，加葳蕤养阴而愈。", []], "13487": ["病机", "脉数而弦，数主热，弦主肝，合堕胎后恶露淋漓、臀疮肤痒，显系肝经郁热、血分伏火。多药罔效，为产后宜温谬说所误。治以西洋参、银花、生地、龟板等清肝凉血、养阴解毒，不十帖而愈。", ["数", "弦"]], "13488": ["病机", "脉弦滑，弦主肝郁气滞，滑主痰热内蕴。患者久服温补之透土长寿丹，积热酿痰，故见齿痛目赤诸恙蜂起。孟英察脉弦滑，断为湿热痰火内盛，与多剂石膏药清泄阳明，兼当归龙荟丸泻肝火，新疾既瘳而腿亦渐温，正合弦滑主痰热实邪之机。", ["弦", "滑"]], "13489": ["病机", "切脉虚细已极，虚为气夺，细为阴亏，合之则阴分太亏、气血俱损。前证疮毒虽去，而逾年伤寒，正虚不能鼓邪外出，故孟英曰不可徒攻其病，以阴分太亏耳。与景岳法用熟地、当归、酒炒白芍等滋填阴分，一剂而瘳，正合虚细主阴亏之机。", ["虚", "细"]], "13490": ["病机", "脉形空数，空为血虚不充脉道，数为虚火浮动。舌色红润而痛碍饮食，内治外敷不效，孟英断为血虚火浮，以产后发热例施之。用熟地、当归、酒炒白芍、炙甘草、茯苓、炮姜温养阴血，其病如失，正合空数主血虚火浮之机。", ["空", "数"]], "13491": ["病机", "脉弦细以数，弦主肝郁，细主阴亏，数主虚热。腰疽愈而复发五年，诸疡医治之不效，孟英断为内损证，非外科所能知。与大剂甘润滋填之药，匝月而痊，正合弦细数主阴亏内损、虚热内扰之机，故曰子之幸也。", ["弦", "细", "数"]], "13492": ["预后", "左尺坚搏，坚为脉体劲急，搏为应指有力，左尺候肾，坚搏则真阴已伤、肾水不能涵木。孟英偶诊其脉，谓李证有可愈之机，脉难久享其年，后果卒于京。此段以左尺坚搏断真阴耗损、预后不良，正合坚搏主肾阴亏竭之机。", ["坚", "搏"]], "13493": ["病机", "脉滑数，滑主痰湿内蕴，数主热邪亢盛。酷热之秋浑身生疖如疔，小溲或秘或频，大便努挣不下，舌紫苔黄而渴，皆湿热壅盛之象。孟英诊脉滑数，断为实热，与白虎加花粉、竹叶、栀子等清泄湿热，十余剂而痊，正合滑数主湿热实火之机。", ["滑", "数"]], "13494": ["病机", "脉弦数而滑，弦主肝郁，数主热，滑主痰。目疾久治不瘳，渐至腹中痞胀、痛不可当、食不能下、便秘形消，孟英断为肝郁痰滞而误补以致殆。与金铃子散合雪羹，吞当归龙荟丸暨礞石滚痰丸，三投即效，正合弦数滑主肝郁痰热之机。", ["弦", "数", "滑"]], "13495": ["病机", "脉至洪滑，洪为阳明热盛、脉道宽阔，滑为热盛痰壅。两目肿痛不能略张，医投风药反致昏痉欲厥，大渴便秘，皆阳明实热之象。孟英诊脉洪滑，与白虎汤二剂霍然，正合洪滑主阳明热盛、热壅气分之机。", ["洪", "滑"]], "13496": ["病机", "脉弦而滑，弦主肝郁气滞，滑主痰湿内盛。溲涩苔黄为湿热下注之征，脱肛虽属高年，然脉不虚而弦滑，说明非中气下陷之虚证，乃湿热壅滞、气机不畅所致。湿热下迫肛门，故脱肛；气机郁滞，故溲涩。孟英断为\"非虚证\"，清其湿热而痊，正合脉证。", ["弦", "滑"]], "13497": ["病机", "脉滑数，舌绛便难，口臭溲少，显系湿热痰火蕴结。疡医溃后温补收功，致平时湿热痰火一齐关住，不得外泄。滑主痰湿，数主热，湿热痰火交蒸，故寒热时作、咽糜龈腐、睛赤音嘶。病犹自寻出路，说明邪有外透之势，然温补助虐，蕴隆虫虫，病势愈剧。", ["滑", "数"]], "13498": ["病机", "脉弦缓而涩，弦主气机郁滞，缓主湿，涩主血行不畅。苔黄溺赤、饮食不思，为湿热不清之象。疡科温补乱投，气机郁滞，湿热入血，故大便下血、腰背疼胀。医者不治其病徒涩其血，气机愈窒，营卫不通，寒热不饥。此药病也，非土败阴亏，故孟英以海䖳、芦菔汤清化湿热、疏通气机。", ["弦", "缓", "涩"]], "13499": ["病机", "脉弦洪疾驶，重按细软。弦洪疾驶为郁火内燔之象，重按细软则高年气血两亏。头面赤肿磊痒、烦躁不眠，火郁于上；饮食日减，气血亏于中。此高年气血两亏、郁火内燔之证，不可从疡科治。孟英以益气养血、清透郁火为方，十余剂而瘳，正合脉证。", ["弦", "洪", "疾", "细"]], "13500": ["病机", "脉甚弦滑，痰火之疴。弦主肝火，滑主痰，痰火交阻络脉，故目障耳聋、巅肿而疼、时咳白沫。温补如胶似漆，锢疾成废。后诊脉沉滑而数，体厚苔黄，沉主里，滑数主痰热内蕴，亟宜化痰清热。两案互参，皆以弦滑数脉断为痰火为患，温补误治。", ["弦", "滑", "沉", "数"]], "13501": ["病机", "脉象弦细无神，弦主肝郁，细主阴亏，无神为营阴大亏之征。疮色黑陷、食减神疲、寒热时形，皆营阴亏虚、肝郁不达之象。初起无寒热、患处不红肿、不流脓，其非火毒可知。攻散劫津、温托壅气，妄施敷割，好肉剜成疮。病在下焦，素患肝郁，耆茸芎归益令阳浮，两腿不温非真冷，乃阳浮于上。", ["弦", "细"]], "13502": ["病机", "脉弦洪而数，弦主肝，洪主热盛，数主火。疥遍身、左臂酸疼，为肝经暑热之邪外发。妊妇案脉甚洪数，舌绛无苔，四肢拘挛，溲热如火，肤赤神昏，阴户疼肿，乃暑火证为毒烈燥热之药助虐。洪数为暑火炽盛之脉，故以大剂清热涤暑、凉血解毒之品取效。", ["弦", "洪", "数"]], "13503": ["病机", "脉滑而数，滑主痰湿，数主热，为肺胃热炽之征。乳裂乳痒、搔即水出、气冲痰嗽、口渴肤糙，津液从外患而耗。后脉弦涩不调，弦主气郁，涩主血滞，热炽日久，气机不畅，血行受阻。初为肺胃热炽，继则气滞血涩，故孟英先清肺胃之热，继则调气和血。", ["滑", "数", "弦", "涩"]], "13504": ["其他", "本段讨论医案源流与价值，未涉及具体脉象。原文言“临证医案，非古也”，强调医案记事非临证，但“对病书方，因题立义，相对斯须，人之性命系焉”，说明医案关乎性命得失，虽非根柢之学，却有参考意义。", []], "13505": ["病机", "脉数混混而不清，为湿温过候，湿蕴化热，热渐化燥之象。热邪内扰则脉数，湿浊未清则混混不清。症见斑疹并见、心胸烦懊、神识模糊、舌心苔干而不腻，皆湿蕴化热、阴精下亏、风阳上亢之候，虑其内陷昏痉。", ["数"]], "13506": ["病机", "脉沉小而数疾，为湿温邪在太阴、阳明，湿胜于热，邪郁不达之象。沉小主湿郁于里，数疾主热，邪郁不达故脉沉小；日晡烦躁、口虽渴苔仍白腻、神识时糊，皆湿蕴化热、余湿犹滞、蒙蔽清窍所致。", ["沉", "小", "数", "疾"]], "13507": ["病机", "脉数较大于昨，热势较盛于前，所谓“数则烦心，大为病进”，非阴转为阳、自内达外之象。舌苔白厚上罩微灰、面红目赤为阳盛之征；头昏耳聋为阴虚之象；小溲窒塞为气化不及。当生津彻热、利窍化湿。", ["数", "大"]], "13508": ["病机", "脉时躁时静，为湿热郁蒸，如烟如雾，邪内陷之象。静则神倦若寐，躁则起坐如狂，乃邪陷心营、神识沉迷之候。虽便不通而腹鸣不满，肠胃不实，其粪必溏，未可骤攻下。尖苔白上罩微霉，邪在营气之交，治宜透热转气、芳香宣窍。", []], "13509": ["病机", "下后舌黑稍退而脉反洪大，神识仍昏，为阳明火旺之象。洪大主阳明燔灼之火，火盛故脉洪大；神识仍昏乃火旺扰神。治宜清阳明燔灼之火，救少阴涸竭之阴，用景岳玉女煎。", ["洪", "大"]], "13510": ["病机", "右脉洪大数疾，左亦弦数，为湿温挟肝胃病之象。洪大数疾主阳明热盛，弦数主肝郁化火。症见舌灰唇焦、齿板口渴、便坚黑，为肠胃实热燥屎；脘痛、经事适来，为木乘土、气郁而痛。渴喜热饮乃湿与热合，非阴寒假热。", ["洪", "大", "数", "疾"]], "13511": ["预后", "汗出而脉躁疾者，为一忌，属预后不良之象。病本湿温挟食，战汗而解，少顷复热已为一忌；汗出脉躁疾，示邪热未衰而正气已伤，恐热邪陷入血室，从此滋变，故为又一忌。治以宣泄表里、通血中气滞，兼杜热入血室。", ["躁", "疾"]], "13512": ["预后", "原文述服药后便下黑栗溏粪、脘痛减、舌霉唇焦退，为邪减之征；然脉由数大转为虚小无力，且心中觉空，数大本主邪热，今骤变虚小无力，是邪热虽减而正气亦虚，故断为邪减正虚之象，防神糊痉厥等变，以正虚易致风动神浮。", ["数", "大", "虚", "小"]], "13513": ["病机", "温邪十二日斑疹遍透、神识仍糊、便屡行、齿垢未脱，舌尖红中心焦为阴津灼伤；左脉大右脉小，左主血右主气，右小为元气弱，故曰元气弱也。脉神委顿，当从元气推求，虑液涸动风致痉厥、胃虚气逆致呃忒。", ["大", "小"]], "13514": ["病机", "原文未识脉名，然述脾肾阳气素虚，阳邪一化阴湿即来，且言在脉神委顿时早防之，是脉神委顿即阳气虚衰之征。阳邪化而阴湿乘虚内起，故变证速至，古方大豆卷治筋挛湿痹与此症总不相宜，示湿痹非外邪可汗解。", []], "13515": ["病机", "温邪甫退而少腹板硬过脐如盘、按之不痛、小便不畅，脉沉小、舌白腻、身无热口不渴，沉小主里阳虚，故断为上热方除中寒复起。膀胱气化赖肾阳蒸腾，肾阳不足则水气凝而为瘕，须防犯胃冲心呃厥，急温肾通阳泄水。", ["沉", "小"]], "13516": ["主病", "温症交十二日，目赤耳聋、舌白烦渴、脉洪大而汗出，洪大为气分热盛之脉，热邪充斥气分故脉形洪大，热迫津泄故汗出。治当辛凉彻气分热邪、甘凉救肺胃津液，脉症合参确为气分热盛津伤之候。", ["洪", "大"]], "13517": ["病机", "目张不语而神慧、与汤则咽、身能转侧，舌苔灰白、脉形洪滑，洪滑主痰火壅盛，非邪闭心包之神昏，乃肝阳夹痰火阻塞清明之府，故神慧而目张不语。勿再芳香开达，开则引邪内陷，慎之。", ["洪", "滑"]], "13518": ["病机", "目张不语、多汗脉大，大为阳盛之脉，汗多则阴液外泄，阳盛而阴不能制，故断为阳盛阴虚。阳浮于外、阴竭于内，防其厥脱，急当救阴以恋阳，希图万一，脉大在此非实热乃虚阳外越之象。", ["大"]], "13519": ["预后", "目已能合、口已能言、汗多稍收、脉大稍敛，是大为阳盛，今稍敛则阳有渐潜之势，故似有一线生机；然舌蹇言涩、两臂动强，为阴液未复、虚风内动之兆，恐其发痉，拟存阴熄风法以善其后。", ["大"]], "13520": ["病机", "脉伏如无，非阳气虚衰，乃邪热内闭、阴津外泄之象。原文见神识模糊、斑色红紫、脘腹拒按、舌红干燥、目赤唇焦，热结旁流，又肤冷汗出，脉伏如无，是热邪深伏，气机不通，阴津外泄，故有内闭外脱之虑。", ["伏"]], "13521": ["病机", "肤冷、汗出、脉伏，非虚象，乃闭象也。从斑色红紫上看出，热邪内闭，气血壅滞，脉道不通，故脉伏；热闭于内，阳气不达四末，故肤冷；热迫津泄，故汗出。参须可斟酌，示不可妄补。", ["伏"]], "13522": ["病机", "久病元气未复，又感湿温，已愈旬日，解表、疏中、通下皆已服过，现脉仍数，舌白腻，头汗多，身热不解，咳嗽不扬，小溲不爽。脉数主热，湿温余邪未清，三焦气机不利，故以分泄三焦为治。", ["数"]], "13523": ["预后", "温邪挟积化燥，昨服药后战汗不透，大热虽减，里热仍炽，舌霉边白，脉形不显。脉形不显，非无脉，乃邪热内郁，气机不宣，脉道不利；高年正虚，恐其内陷，故为预后警示。", []], "13524": ["病机", "两手寸关脉细滑数，两尺少神，舌边乾红，心苔黄腻。细为阴伤，滑数为痰热，湿蕴生痰，热蒸灼液，郁于心胸，故烦躁、恶心、错语。脉象示将燥未燥、将陷未陷，治以生津化浊、和胃清心。", ["细", "滑", "数"]], "13525": ["病机", "口臭喷人，胃火极盛，斑疹虽见，透而未足，目赤神糊，脉洪口渴。脉洪为阳明胃火亢盛，热蒸津伤，故口渴；热毒外透不足，故斑疹未透。急急化斑，以白虎为主，参以犀地清营解毒存阴。", ["洪"]], "13526": ["病机", "黑苔剥落，舌质深红，阴津大伤，燥火未退，左脉细小，右脉洪大。左脉细小主少阴阴伤，右脉洪大主阳明火旺，故曰少阴不足，阳明有余。治以玉女煎存阴泻火，守过三候，其阴当复。", ["细", "洪"]], "13527": ["病机", "右脉洪大，阳明热结夹滞显然。洪为阳明热盛之脉，右脉候气，右洪大则热结于阳明，夹滞内阻，气机壅实。此条承前文阴伤火旺而来，点明右脉洪大主阳明热结夹滞之病机。", ["洪"]], "13528": ["病机", "原文述“耳聋无闻，舌干难掉”，断为“阴津大伤”，虽未出脉名，然复脉法所复者即阴津所养之脉。阴津大伤则脉道失充，当见细数或虚涩之象，故以复脉法救其阴液。此段主旨不在脉象本身，而在由症推机，示阴亏津涸之病机。", []], "13529": ["病机", "脉象软而小数，软为湿邪未化、正气受困，小为邪郁气营之交、脉道不畅，数为温邪内蒸。合之苔白腻边红、疹点不透、寐则谵语，知温邪挟湿逗留气营，非纯陷营分。脉软数正是湿热氤氲、正未大虚之象，故周先生清营泄卫、理气化浊恰如其分。", ["软", "小", "数"]], "13530": ["病机", "脉软数，软主湿浊弥漫、气机不宣，数主热处湿中、热为湿遏。原文明言“非邪陷膻中，乃湿热深漫于上焦，肺气失宣布”，故神蒙嗜卧而呼之则清、语言了了。脉软数恰应湿热蒙上、肺气不宣之机，呃尚未除，亦胃浊未化之征，故从肺胃立法。", ["软", "数"]], "13531": ["预后", "昨日脉弦硬，现诊小而涩数。弦硬为温邪化火、气逆痰涌之象；小而涩数则阴津暗伤、元气渐馁，脉道失充且行涩。由弦硬转小涩数，是邪未解而正已伤，故原文断“颇有喘汗厥脱之虑”。脉变示正虚邪陷，预后堪忧，治宜清肃肺胃、化痰降气。", ["弦", "硬", "小", "涩"]], "13532": ["预后", "脉象细数，细为津枯液燥、正气内亏，数为无形邪热薰蒸膻中。合之舌绛齿燥、痰气喘粗，知有形痰浊阻塞肺胃而阴津已耗。细数之脉见于痰喘，是正虚邪实并见，故原文虑“厥脱之变”。治拟化痰涤热治标、扶正生津救本，必痰喘平、神气清方可图。", ["细", "数"]], "13533": ["病机", "脉形洪大，洪为阳明邪火有余、火载气逆，大为热盛鼓动脉道。合之头汗淋沥、痰喘不止、面青舌红，原文断为“少阴阴津不足，阳明邪火有余”，火逆肺失降而为喘。洪大之脉主阳明实火，然面青、汗淋已露阴伤阳浮之危，故深虑厥脱，治救少阴之津、清阳明之火。", ["洪", "大"]], "13534": ["病机", "渊按脉形洪大，合之头汗面青，断为“上实下虚大著”。洪大为阳明邪火有余、气火上逆之实，头汗面青则下元不纳、虚阳上浮。故于补下纳气中清热救津，人参、石膏、粳米救肺清热亦所以救肾。此段以脉洪大发明上实下虚之病机，非单纯实火。", ["洪", "大"]], "13535": ["预后", "脉大稍软，较大之前洪大已减，软为邪火渐退、脉象稍和之兆。然气仍急促、心中烦躁、舌红干涸，是津液未回、虚阳未息、上逆之气未降。原文谓“虽逾险岭，未涉坦途”，脉大稍软示病势稍缓而根本未复，仍拟救少阴、清阳明，再望转机。", ["大", "软"]], "13536": ["病机", "脉形洪大中空，即洪而中空之象，为津枯液燥、气化不行之候。温邪两候不解，邪热耗伤津液，气分热盛故脉洪，津液大伤故中空。原文谓'津枯而液燥'，神昏如醉、舌淡红无苔、呓语呢喃，皆津亏燥热、神明失养之症，故主以甘寒润燥生津为治。", ["洪", "空"]], "13537": ["预后", "战而得汗后脉静身凉，为邪从战汗外解之佳兆。脉静者，正复而邪退，身凉者，热随汗解。然舌黄未去，示胃中余浊未清，故虽邪已解而尚需和化。此段以脉静身凉断邪解，以舌黄未去辨余浊，属预后判断兼及善后治法。", []], "13538": ["预后", "此段承前战汗后脉静身凉而言，脉静身凉为邪解之征，故用方大法不外乎此。脉静者，邪退正安，脉不复躁动；身凉者，表里之热已撤。原文以'脉静身凉'四字定邪解之局，示战汗后调治当循此机转，属预后与治法总则之论。", []], "13539": ["病机", "脉数而洪，数主热，洪主阳明气分火盛。营阴素亏之体感温邪，交七日而脉数洪，舌燥齿干、荡气促，是阳明之火方炽、少阴之阴已涸。腹硬痛、大便三日不通，积聚于中，气火尽浮于上。脉数洪正合'阳明之火方炽'，阴涸津亏则脉虽洪而根不固，故治先养津。", ["数", "洪"]], "13540": ["兼症", "此段论温邪上受、化火上炎之咽喉症，辨实火属肺胃阳盛、虚火关肝肾阴亏。原文'今观脉色，已觉神清爽朗'，脉色转佳为邪火渐退之象。斑痧后喉痛色赤、吐红痰，皆气火熏蒸所致。怀麟之妇，胎不动即是安，大便才通为转机，属兼症与转归之论。", []], "13541": ["病机", "此段论温邪燔亢后余热未净、肺胃阴津受戕，养阴在津与汗。孕妇七八月，肺与大肠司养，肺受火淫，燥热移于大肠，大肠移热胞络。胞脉络肾系胞胎，热上迫肺故音哑、咳嗽、喉痛。引《内经》重身九月而暗，明指胎中阴火所致，属病机推阐。", []], "13542": ["病机", "渊按辨伏温由内达外、由里传表，从少阴出太阴，故退而复来、轻而再重，不尽由胎热。疹属肺、斑属胃，温邪每从两经而达。胞络乃胞门子户之胞，非心包络，胞络系肾，少阴脉贯肾上入喉，热邪由少阴上干喉中故音哑，甚则喉痛，属病机辨析。", []], "13543": ["预后", "阴虚之体感温邪反复，交九日神识时迷、舌满碎腐，脉象渐沉。沉为邪陷阴分、正气内溃之象，阴虚之体不耐邪灼，脉由浮转沉示邪深入里、正不胜邪，故防其昏厥。原文以'脉象渐沉'与神识时迷并见，断其有内陷昏厥之虞，属预后判断。", ["沉"]], "13544": ["预后", "原文述“汗虽未出而疹点已化，热虽未退而脉象稍和，是佳兆也”。脉象稍和说明津液虽夺而胃气渐复，邪有外达之机，故为佳兆。脉和则营卫渐通，与疹化热退相应，预后向好。", ["和"]], "13545": ["病机", "脉小数疾，乃阴血虚于下而邪火伏于内。久患便血，阴气先伤，温邪挟积，肺胃阻窒，上喘下泄，发热口渴，舌绛如朱，额汗不止，皆阴不守阳越之象，故曰厥脱险象。", ["小", "数", "疾"]], "13546": ["病机", "原文“脉小数疾，阴血虚而邪火伏”。阴血耗于下，脾气伤于中，温邪感而喘泄并作，头汗为阴不守阳越，无汗为阴液虚气不化，舌绛如朱为胃阴亏心火炽，故脉小数疾主阴阳两虚、中气不守之危。", ["小", "数", "疾"]], "13547": ["病机", "原文“脉象不达”指脉气不能外达，因暑邪内闭，肺气闭塞，故恶寒发热而脉不显，口不能言，先有咳嗽。脉不达与肺气闭塞相应，拟开而达之，使闭开则脉自达。", []], "13548": ["病机", "脉数细而沉，数主热，细主阴伤，沉主邪闭。暑邪归心，神昏舌干黄，唇齿燥，耳聋便泄，津枯三焦皆病，故脉数细沉为邪闷心包、阴津枯涸之危候。", ["数", "细", "沉"]], "13549": ["病机", "脉弦带数，弦主疟邪内郁，数主热。暑湿伏内，凉风外袭，湿遏热伏，疟发先寒后热，心胸烦躁，中脘痞塞，呕吐泄泻。今疟退而脉仍弦数，舌苔白腻，小溲不爽，病机偏重于里，故从里治。", ["弦", "数"]], "13550": ["病机", "脉沉神昧，沉主邪陷于里，神昧为正气虚馁。年过花甲，伏邪挟积，正虚邪陷，故身热不扬，手足寒冷，气短作呃，便泄溏臭，舌强白中心焦，深虑厥脱。脉沉与正虚邪陷之象相应。", ["沉"]], "13551": ["预后", "两脉促疾，促为阳盛而阴不能和，疾为邪火急迫。伏暑化燥，劫津动风，舌黑唇焦，鼻煤齿燥，神昏手掣，阴津消涸，邪火燎原，虽便通病减，脉仍促疾，故属险象，恐其复剧。", ["促", "疾"]], "13552": ["病机", "脉沉不起，为阳症阴脉，热盛而脉反沉，示湿遏热炽，阳气内郁，不能外达。原文谓“湿遏热炽，将燥未燥，将陷未陷”，脉沉即邪热内陷、阳气不伸之象，故可虞。与发热神糊、两目上视、舌乾红等症相应，主湿热内闭、有厥脱之险。", ["沉"]], "13553": ["病机", "脉形弦数，弦主邪郁少阳、湿阻气机，数主热。原文谓“伏暑为病，湿热居多，阴虚之体，邪不易达”，脉弦数示湿热内蕴、邪正交争，尚未化燥深入。与耳鸣眩悸、口渴胸痞、微寒微热相应，主湿热郁阻、阴虚不甚之病机。", ["弦", "数"]], "13554": ["病机", "脉大而虚，大为邪气有余，虚为中气不足，正虚邪恋之象。原文谓“中虚浊恋，液涸痰蒙”，脉大而虚正合中气亏虚、浊痰内蒙之机。与神糊呃逆、手肢微痉、痰多舌白、音低、周身干燥而痒相应，主中虚浊恋、液涸痰蒙之危候。", ["大", "虚"]], "13555": ["病机", "脉濡主湿，为暑湿伏于太阴、中焦阳气不化之象。原文谓“中宫有浊，阳不舒化”，脉濡示湿浊内阻、阳气不舒。与神蒙若寐、身热不扬、肢冷、手指牵引、舌根牵强、口泛甜味相应，主湿浊阻络、阳不舒化之病机。", ["濡"]], "13556": ["病机", "脉小数而虚，数为热，小与虚为元气亏、津液不足。原文谓“高年元气素亏”“新邪乘虚而袭，引动伏邪晚发”“津枯邪恋”，脉虚数示正虚邪恋、津枯化燥之机。与干咳欲呕、舌边光红、根苔白掯、热甚无汗相应，虑其化燥神昏。", ["小", "数", "虚"]], "13557": ["病机", "脉象软细，软主湿，细主气机不达、湿阻脉道。原文谓“伏邪湿热内蕴，三焦气机不达”，脉软细正合湿邪内蕴、气机不畅之机。与午后发热、胸闷头胀、尿少无汗、舌苔白腻相应，主湿热内蕴、三焦气机不达之病机。", ["软", "细"]], "13558": ["病机", "脉沉实，沉主里，实主邪积。原文谓“伏邪挟积，阻塞中宫”“食积蒸痰，邪热化火，痰火上蒙包络”“邪积聚于阳明”，脉沉实示邪积阳明、痰火内结。与疟发日轻日重、神糊烦躁、起卧如狂、舌苔黄相应，主邪积阳明、痰火上蒙之病机。", ["沉", "实"]], "13559": ["病机", "脉细主虚，为少阴疟邪内陷厥阴、下乘脾土之象。原文谓“病机偏在太阴，法当辛温通阳，转运中气”，脉细示太阴中阳不足、邪陷于里。与手足寒冷、腹中气撑、上塞咽喉、几乎发厥、腹胀舌白相应，主太阴中阳不振、邪陷厥阴之病机。", ["细"]], "13560": ["病机", "脉缓大，缓为脾阳渐通之象，大为邪气未净之征。原文谓“脾脏阳气虽通，寒热痰涎未化”，故脉虽见缓而仍大，说明阳气虽通而痰湿未化，病机重点在脾阳不足、痰湿内蕴，主腹胀、痰多黏腻等症。", ["缓", "大"]], "13561": ["病机", "脉弦，原文谓“肝胃尤甚”，弦为肝木偏旺之象。木胜克土，胃土受伐，故见恶谷厌纳、痰多呕恶；肝胃不和，痰扰心神则心跳少寐。此脉弦主肝木乘胃、胃气虚弱之病机，与三疟后脾胃虚弱、痰湿内阻诸症相应。", ["弦"]], "13562": ["治法", "原文未出脉象，仅述“运脾气，补脾阴，和营卫，温督脉”为虚疟、久疟治法。此段主旨为治法，非论脉，故脉象要素为空。病机为久疟正虚，脾营督脉俱损，治当培补。", []], "13563": ["病机", "脉濡小，濡主湿邪留恋，小为元气渐伤。原文谓“其湿仍恋，而元气渐伤”，说明湿热浸淫未清而正气已损，故脉见濡小。此脉主湿恋正伤之病机，与三疟缠绵、虑加腹满等症相应。", ["濡", "小"]], "13564": ["病机", "左脉细弦，细为阴血不足，弦为肝失柔和，故主肝肾亏虚；右脉软弱，软为气虚，弱为脾弱，故主脾胃虚弱。原文谓“三疟之后，气血两亏”，此脉象主气血两亏、肝肾脾胃俱虚之病机，与疟后虚损诸症相应。", ["细", "弦", "软", "弱"]], "13565": ["预后", "脉自弦为疟病本脉，弦大者为阳，原文谓“其邪易达”，说明邪有外达之机。今疟来热势稍轻而短，脉弦大，为邪有退机之预后，故仍从前法治疗。此段主旨为判断疟疾向愈之预后。", ["弦", "大"]], "13566": ["病机", "脉空虚，为营卫两伤、下焦八脉空虚之象。原文谓“三疟久延，营卫两伤，复因产后，下焦八脉空虚”，疟邪阻于血络，聚于肝募而成疟母。此脉主正虚邪恋、络阻成积之病机，与腹中结块、疟久不止等症相应。", ["空虚"]], "13567": ["预后", "脉细，为正气不足之象。高年下痢百余次，舌苔白掯，身热恶心，饮食不纳，痢下五色，皆属忌款。脉细说明正气已虚，不能托邪，故原文谓“皆为忌款”，预后不良。此段主旨为判断痢疾之预后。", ["细"]], "13568": ["病机", "左脉沉小示湿温邪陷厥阴，下痢色紫后重为营血郁滞；右脉弦大主阳明积热内恋，木来乘土。舌黄、晡热印证阳明热盛。高年体虚神怯，脉沉小弦大并见，正虚邪实，防厥脱之变。", ["沉", "小", "弦", "大"]], "13569": ["病机", "红痢日久，脾气虚、营气耗，脉迟缓而涩，迟主阳微，涩主血少，舌薄白底绛、渴不贪饮、口恶甜味，皆脾阳失运、湿动于中之征。误服红曲、滑石致痢复剧，更伤中阳，故脉象如此。", ["迟", "缓", "涩"]], "13570": ["病机", "渊按从脉象迟涩看出理中汤温运中阳、驻车丸分导湿热之效。迟涩为脾阳不足、营血滞涩之象，故温运分导为合；红曲、滑石寒滑伤中，适与脉证相反，故致痢剧。", ["迟", "涩"]], "13571": ["病机", "久吃洋烟，脉沉而细，沉主里、细主虚，阳气不足。病方三日，微寒微热、头略胀痛，昼不痢、痢在夜，属寒邪伤营，故色赤。当和营散寒、温通阳气，勿与常痢同治。", ["沉", "细"]], "13572": ["病机", "脉细肢寒，细为阳气衰少，肢寒为阳不达四末；昼不痢、痢在夜，乃脾阳不能统摄营阴，夜间阴盛阳微，故痢作于夜。此脾阳虚弱、统摄失职之病机。", ["细"]], "13573": ["病机", "右脉细弦为木侮土，左脉细弱为肾水亏。病由肝气而起，水不涵木，木胜土衰，湿热不化，故下痢赤白。华先生补中升阳参育阴，从本求治；再参温化，兼顾脾肾阳气。", ["细", "弦", "弱"]], "13574": ["病机", "两脉虚濡，脾胃元气大弱。虚濡为气弱湿滞之象，似宜扶正；然下痢古称滞下，多起湿热，早补早敛往往受累，故河间苦辛宣通腑滞为必采之法。补阴阳、治脾胃，多为久痢而设。", ["虚", "濡"]], "13575": ["病机", "下痢而得促脉，促为阳盛而阴不能相续，今见之脾胃之阳微特著。形衰畏冷、小便清长，皆阳微之征。痢赤属血分，腹痛为有积，故立方寻其罅而通补兼施。", ["促"]], "13576": ["病机", "脉弦硬为厥阴肝木偏旺、伏暑湿热蕴结之象。原文谓\"伏暑湿热蕴于肠胃及厥阴\"，厥阴之表为少阳，故先热痢后兼疟，为厥阴少阳表里同病；弦硬示木邪未平，昼无小便、交子后便痢，乃阴亏渗少、清阳不举，故治以清厥阴、举清阳、益肾阴、运脾湿。", ["弦", "硬"]], "13577": ["病机", "脉弦主肝木郁滞，值经来而见寒热，是血虚木郁、肝胃未和之候。原文\"痢减腹仍痛\"示邪未尽而肝胃不和，弦脉应肝，血虚则木失濡养而郁，郁则寒热，故拟养血疏肝，使肝木条达、胃气和降。", ["弦"]], "13578": ["病机", "脉弦紧而数，弦紧主寒积内结、气机壅滞，数虽似热，然面色青而不渴，知非真热。原文辨肠痈寒热二端，此症\"属寒积\"，少腹偏右板窒、便痢白腻如水晶鱼脑，皆寒湿凝滞之征，故宜温通，非大黄牡丹汤所宜。", ["弦", "紧", "数"]], "13579": ["病机", "脉弦迟，弦主积、迟主寒，合苔灰白，为虚而有寒积之象。休息痢近五年，腹中块垒时痛、痢兼干粪，是痼冷盘踞肠胃、积滞未去，故引《本事方》\"痼冷在肠胃\"之说，主张先取去积，然后调理，不可畏虚养病。", ["弦", "迟"]], "13580": ["病机", "脉沉细主里虚有寒，沉为在里，细为阳气不足、气血衰少。原文\"泄痢白腻，腹不痛\"，白腻属寒湿，腹不痛则非实积壅滞，故直断\"此寒也\"，治宜温之，以振中阳、化寒湿。", ["沉", "细"]], "13581": ["病机", "脉紧主寒，肢寒不发热、苔白不渴，皆阴寒之征。原文腹不甚痛但肛酸且胀，兼素有寒疝，是寒凝下焦、气机不畅。景岳论痢属寒者不少，此症寒象为多，故宗景岳温散寒邪之法，与河间主热之说相辨。", ["紧"]], "13582": ["病机", "脉细主气血不足，肢寒示阳气不达。红痢匝月、腹痛后重，先曾发热三次，为中虚表邪传里；脉细肢寒则太阴阳气已弱，小便艰难则膀胱气化又钝。故拟开中焦、化湿热、升阳解表，表里双解，兼顾虚实。", ["细"]], "13583": ["死脉", "脉弦急大者死，弦急为肝木劲张、邪势鸱张，大为正气外浮欲散。原文论痢疾湿热壅结肠胃，若噤口不纳则湿热伤胃、邪势捍格，中气无根柢者难治；弦急大正示邪盛正溃、胃气将绝之死候，故列于预后判断之中。", ["弦", "急", "大"]], "13584": ["预后", "脉形乍大乍小，是阴阳相争、气机紊乱之象，非正常脉度。原文合参面色暗晦不泽、似有阴气阻遏于中，苔黄湿、腹满足肿、小便黄赤，判为湿遏热伏、女劳黑疸。疸而腹满，脾肾已伤，邪无出路，故言在法难医，脉之大小无常正提示正气散乱、病势深重。", ["大", "小"]], "13585": ["预后", "疟止复作、腹满平而又发，说明邪伏未净、反复伤正。今目黄脉细，细为气血不足、湿郁正虚；面黑溺少，黑为肾色外露、溺少为湿无下泄，故防延黑疸。原文引疸而腹满者难治，脉细正示正虚不能化湿，故仅姑与分消，预后堪忧。", ["细"]], "13586": ["病机", "脉沉而细，沉主里、细主虚，合面色黎黑、腹满足肿，说明脾肾之阳不化，水湿阻止于中。阳虚不能蒸化，水湿内停，故腹满肿胀；肾色上泛则面黑。原文断为证势甚重，治以通阳燥湿，脉沉细正是阳气衰微、湿阻于里的直接反映。", ["沉", "细"]], "13587": ["病机", "原文以脉大口渴属阳黄，湿热壅遏、证多实，故脉大；脉细皮寒、口不渴属阴黄，脾肾阳气素虚、不能升化其邪，故脉细。同是湿热，脉之大小与寒热渴否相应，揭示阳黄、阴黄病机虚实寒热之别，脉象是辨证关键。", ["大", "细"]], "13588": ["病机", "两关脉见一粒厥厥动摇，关候脾胃，动摇为内风动跃之象。原文断为脾虚木盛，土虚不能培木，肝风内动，故左半肢体麻木不仁、头眩面麻，属偏枯之候，虑延仆中。动摇之脉正反映风阳躁动、脾虚失运的病机。", ["动"]], "13589": ["预后", "复诊两关厥厥动摇之象大减，说明内风有暗熄之机，是向愈之兆。左手屈伸稍安而左足麻木未愈，风邪未尽、经络未通。原文拟补肾生肝为治本之计，脉象动摇减轻与症状改善相应，提示病势转缓，当从本图治。", ["动"]], "13590": ["病机", "左手脉沉弦而涩数不调，沉弦为肝郁，涩数为血虚而风动，故断血虚肝风暗动；右关独缓滑，缓滑主湿痰，故胃有湿痰；尺寸俱弱，金水两虚。合耳聋、肩膊酸难举、痰多、口中干腻，正与血虚风动、湿痰内蕴、肺肾不足之病机相应。", ["沉", "弦", "涩", "数"]], "13591": ["病机", "脉左弱为血虚，右弱为气虚，气血两虚则清阳不升，故上为头眩；血虚不能荣养筋脉，气虚不能运达四末，故半身以下麻木而成瘫痪；甚则心乱神昏，是肝风挟痰上扰。原文以左右脉弱分判气血虚，指出病本在虚、标在风痰。", ["弱"]], "13592": ["病机", "原文未出脉名，以“周身筋脉跳跃，甚则发厥”点明肝风内动之象。谢久患肝风眩晕，阴血暗耗，复感秋风成疟，疟愈而血虚未复，肝木失涵，虚风走络，故筋脉跳跃、发厥；痰涎凝聚亦由血虚络空、津液不布所致。治以养血熄风、化痰通络，正合“血虚不能涵木”之病机。", []], "13593": ["病机", "右关候脾胃，脉独滑动如豆，滑主痰、动主搏击，是痰浊壅聚中焦之征。中脘皮肉觉厚，乃痰湿阻滞、气机不运；手足筋脉时或动惕，为痰走经络、扰动筋脉之象。原文直断“此有痰浊在中焦也”，故以攻补兼施，化痰与扶正并行。", ["滑", "动"]], "13594": ["病机", "脉虚弦滑，虚为土弱金虚，弦为肝木偏旺，滑为风痰有余。素患痰饮咳嗽，土弱不能生金化痰，金虚不能制木，木旺侮土，风痰走络，故似风痰瘫痪、足软难行、口流涎沫；舌左无苔、口不渴、便坚燥，皆金土水不足之征。原文谓“金土水不足而风痰有余”，脉症相符。", ["虚", "弦", "滑"]], "13595": ["病机", "原文未出脉名，以“筋脉牵掣，昼日则安，暮夜则发，不能安卧”明病在阴经。血不养筋，筋脉失濡则牵掣；暮夜阴气用事，血虚阴亏之象愈显，故发而不得安卧。治宜养血以和经脉，正针对血虚筋急之病机，非外邪所致。", []], "13596": ["病机", "脉浮小弱，浮为风邪未净，小弱为正气不足、心气不充。上年痰火迷心，神呆语乱，愈后复发，现语言错乱、哭笑不常，舌心红而苔白，是风入心经、蕴热蒸痰所致。原文凭脉断为“心风”，以独活汤祛风清心，脉之浮小弱正示风邪留恋而正虚。", ["浮", "小", "弱"]], "13597": ["病机", "脉弦大而滑，弦主肝风，大为中气已虚、精血不足，滑主痰湿。少腹块平、小便反不禁，是气不固摄；右手麻木、痰多气升，为内风走络、脾湿生痰。素有肝风脾泄，近增麻木，脉症合参，显系中虚精亏、风痰内扰，故法当兼顾。", ["弦", "大", "滑"]], "13598": ["病机", "脉空，按之豁然而空，主精血枯竭、络脉空虚。年老精血日衰，肝络失养，肝气乘虚入络，胁肋少腹作痛；湿热又因虚为患。原文“精血枯而络脉空”正释脉空之由，故治以补养精血、疏肝通络，兼化湿热，标本兼顾。", ["空"]], "13599": ["治法", "原文未出脉名，承前诊而述药后变化：胁肋之痛稍减，是补养精血、疏通脉络已见小效；惟小溲短少、夜半后脘腹胀，乃浊气不化、阳气不运。故于前方加通阳泄浊之品，属随证调整治法，非另立新脉，重在示人守方加减之法。", []], "13600": ["病机", "久病正虚，阴阳两弱，坎离不交，本已夜不成寐、不耐劳烦；舟行热闷鼓动风阳，扰乱神明，故神糊不语、两手不定、烦躁不安。脉促乱者，促为阳为热，乱为气血失序、神明失主，正合风阳卒动、神志将变之机，非单纯虚候，故以熄风和阳、安神定志为急。", ["促", "乱"]], "13601": ["病机", "左关候肝胆，脉独弦滑，弦主风阳，滑主痰涎，是风阳挟痰上扰之象。痰火随风上攻阳明经络，故头额偏左连及腮齿皆痛。脉象与症相应，非外感表邪，故治法拟熄风阳兼清痰火，紧扣弦滑所主之风痰火。", ["弦", "滑"]], "13602": ["病机", "脉细数，细为精血不足，数为火动，合懒言倦卧，知精气神三者皆虚。然舌苔白腻，有痰有饮；静则气怠若虚，动则气上自乱，是虚中挟痰火，火伏则痰不升而静，火动则痰升而躁。脉细数正示虚为本、痰火为标，故治以十味温胆加减。", ["细", "数"]], "13603": ["病机", "原文未识脉名，但言脉不显、稍起，是阴遏于外、阳伏于内之象。阴如迷雾，阳若日光，阳为阴遏则沉沉默默而蒙昧，脉亦不显；阳光偶见则神清脉起，阴霾四合则昏昏如寐。前投清滋重镇，阴胜于阳，愈增蒙蔽，故欲开阴雾法必通阳，用苓桂术甘汤。", []], "13604": ["病机", "病已两月，外皮不热而脉微数急，微为阳虚，数急为里有热，是里热属阴虚，非关表邪，故无头痛恶寒。愈散其邪则愈虚其表，反增咳嗽。又无胸痞恶心，非湿热中焦。脉微数急示阴虚内热而正气已弱，故以和中为主，兼理脾肺。", ["微", "数", "急"]], "13605": ["病机", "和补相投后诸恙俱减，惟脉数未静，数主热、主虚，此热非实火，乃元气真阴亏损、虚热未敛之征。前补在肺脾，未及根本，故脉数不静。再参肾药兼养其阴，使阴复则虚热自退、脉数渐静，是据脉定治本之策。", ["数"]], "13606": ["病机", "便泄半载，脾肾两亏；脉沉细涩，沉为在里，细为阴血不足，涩为阳衰血滞，故曰阴阳并弱。阳弱则阳萎不举、足跗浮肿，阳虚湿注于下；气虚已极则面白无华；胃虚气逆则纳食嗳气。脉证合参，治宜脾肾双补、阴阳并顾，补土中兼顾肾脏。", ["沉", "细", "涩"]], "13607": ["病机", "脾肾双补略见小效，今腹中鸣响、气向下坠，属脾虚气陷；舌心光红、脉沉细数，沉细为阴伤，数为虚热，是肾脏阴伤之征。脾陷当升，肾阴当养，故用补中升阳法，既举下陷之气，又顾已伤之阴，脉沉细数正是阴亏于下、气陷于中之据。", ["沉", "细", "数"]], "13608": ["病机", "脉缓无力，缓为脾土本脉，无力则示脾气虚弱，运化失职。脾虚不能升清，故便溏；不能运化水湿，故足肿；心脾两虚，故心悸腹胀。此脉主脾虚湿困之病机，与“脾气虚弱”相应，治当补脾，进归脾加减。", ["缓", "虚"]], "13609": ["病机", "脉虚形弱，虚为营阴不足，弱为气血两亏。心脾营阴内亏，则内热；肝胆风火上逆，则头眩、项间结核。此脉示正虚而邪逆，病由内生，故养营之外难求速效。脉虚形弱主气血亏虚、风火上逆之病机。", ["虚", "弱"]], "13610": ["病机", "脉细数弱，细为阴血不足，数为虚热，弱为气衰。先天元气不足，夏秋寒热不已，气血两亏。身疼、口沃清水，乃胃气虚寒。此脉主气血两亏、胃虚寒之病机，故当商温补，仿东垣法。", ["细", "数", "弱"]], "13611": ["病机", "脉弦数者，弦为肝胆气郁，数为郁热内炽。热势交寅卯而盛，乃少阳旺时，肝胆郁热戕伐生生之气，肺金失清肃，脾胃失转输，相火炽而阴津涸。此脉主肝胆郁热之候，与咳嗽发热、食增而热盛相应，治拟酸苦益阴和阳，清彻郁热。", ["弦", "数"]], "13612": ["预后", "脉形软数，软为气衰，数为虚热。肺脾两虚，心营亏损，故咳嗽气塞、骨蒸夜热、面白无华。软数之脉示正虚而虚热内扰，劳损根深，夏至火旺防剧。此脉主虚劳内热之病机，并提示预后当慎。", ["软", "数"]], "13613": ["病机", "脉软数为气虚，软主气弱，数主虚热。骨蒸心跳为血虚，咳嗽头眩、面色萎黄，乃脾肺两虚之候。此脉示气血两亏、脾肺虚弱之病机，与骨蒸、心跳、咳嗽、头眩等症相应。", ["软", "数"]], "13614": ["病机", "左脉数疾，数为热，疾为阳亢。左脉候心肝，数疾乃心肝阳亢之象。肝火戕胃，故谷食反减；心火烁金，故夜热增重。胃阴失降，虚阳外浮。此脉主心肝阳亢、肝火戕胃、心火烁金之病机，夏令防剧。", ["数", "疾"]], "13615": ["预后", "脉之细数不退，细为阴血不足，数为虚热内扰。咳嗽内热虽减，而脉象未复，示阴血未充、虚热未清，故仍为可虑。此脉主虚损内热之病机，并提示预后当慎，不可因症减而忽视脉象。", ["细", "数"]], "13616": ["病机", "脉数内热，乃脾胃不足、肝木亢逆，攻消克伐致元气愈伤，津液日枯，虚火内炽，戕及肺胃。火升颧赤、咳呛口干、便艰溲涩，皆虚火内热之象，脉数正是内热之征，久则成劳损。", ["数"]], "13617": ["病机", "脉数内热，咳嗽脘胁痛，乃阴虚肝郁成热，肺失清肃。数脉主热，阴虚生内热，肝郁化火刑金，故咳而胁痛，热伤血络则防吐血。", ["数"]], "13618": ["病机", "两脉弦硬不柔，此谓牢脉，症属阴虚。脾虚气陷，疡溃久泻，下部畏冷，而脉反弦硬不柔，乃阴亏不能涵阳，虚阳外露之象，非实寒也，故以温中扶土、升阳化湿为法。", ["弦", "牢"]], "13619": ["病机", "脉沉搏数，口燥渴饮，骨蒸鼻血，营阴大亏，虚火内亢。沉主里，数主热，搏为火亢，阴亏于内而火浮于外，劳损根深，入夏火旺防剧，故滋少阴、清阳明。", ["沉", "数"]], "13620": ["病机", "左脉空大，肾水亏也；倦怠无力，脾气弱也。空大为阴亏不敛，虚阳浮越之象，食少则阴虚生内热，症属内伤，非外感实邪。", ["空", "大"]], "13621": ["病机", "脉细数，形容消瘦，行动气升，咳血后干咳发热。细为阴亏，数为虚热，肾气先亏于下，劳碌感邪延绵，阴损及阳，虑成劳损，静养为佳。", ["细", "数"]], "13622": ["预后", "脉数音哑，久咳血痰，肛门结疡，肺遗热于大肠。数脉主火，火旺金衰，时当夏令，颇有气逆血沸之虑，劳损之根已深，预后堪忧。", ["数"]], "13623": ["病机", "脉沉取数，其阴内亏，其热在里，劳损之候。沉主里，数主热，阴亏于内故热在里。咳吐白痰、心腹时痛、得矢气则宽，病兼肝郁，从痰饮气郁例治。", ["沉", "数"]], "13624": ["病机", "脉沉数而手足冷、胸闷食少，沉为脾胃阳气不振，数非实热，乃中土衰弱、运化无力所致。大便干燥是肠中津液枯涸，非热结。故法当温中土以复运化，润大肠以滋津枯，仿菟丝子丸加减，紧扣“脾胃衰弱”与“津液枯”之机。", ["沉", "数"]], "13625": ["预后", "左脉细数，右脉软弱，久咳痰稠、上午发热、面色青黄，细数为阴亏火动，软弱为脾肺气馁，病属上损。幸大便不溏，未过中及下，故曰“加谨调养，交夏至节无变再议”，以时令阴阳交替为转机，示预后须慎。", ["细", "数", "软", "弱"]], "13626": ["病机", "咳嗽脉细数，由上午发热延至下午亦热，是阴气渐伤、虚火内扰。大便间或带血，为脾气虚不能统摄。细数脉主阴亏，故从景岳理阴煎例，扶过夏至一阴来复，冀其无增变，紧扣“阴气渐伤”与“脾气虚”之机。", ["细", "数"]], "13627": ["治法", "脉散为气阴耗散之象，故用四君子汤合生脉散补脾益气、敛阴生脉，加生地、山药、白芍、扁豆、川贝、阿胶、红枣，兼顾养阴润肺、和营止血。全方以补气敛散为主，佐以滋阴，针对脉散所主之气阴两伤、肺脾不足。", ["散"]], "13628": ["预后", "漏疡日久阴津暗渗，加咳嗽气耗、劳神，致咳甚气升、便溏内热、音哑喉痛，脉象细数，已成劳损。细数主阴亏火旺，精、气、神三宝皆虚，故曰“敢谢不敏”，示病深难治，预后堪忧，紧扣“劳损”与“三者皆虚”。", ["细", "数"]], "13629": ["病机", "引《金匮》“男子平人脉大为劳，极虚亦为劳”，大脉非实，乃劳倦伤中、谷气不盛、热气蕴于胸中不得发越所致。中气衰少，肺经治节不行，故内热。治以劳者温之，桂枝龙牡、小建中、黄耆建中等，紧扣“劳伤其中”之机。", ["大"]], "13630": ["病机", "血止咳不已，脉沉带数，沉为气逆于里，数为火郁未清，故曰“其根犹未去”。气犹风，血犹水，咳则气逆血亦逆，经络不和而血不宁静。必降其气而后血不复升，充其阴而后火乃退，紧扣“气逆”“火未退”之病机。", ["沉", "数"]], "13631": ["病机", "脉数血涌而胃气大虚，胸中痞塞、大便带溏，是痞为虚痞、数为虚数。咳血三月忽冲溢，唇白面青，断非实火。实火宜清降，虚火宜补和，故引“血久不止，宜胃药收功”，紧扣“胃气大虚”与“虚火”之机。", ["数"]], "13632": ["病机", "脉数退，血少止，而反恶寒汗出，此血脱气无所依，卫虚不固之象。数脉退为热减，然恶寒汗出显系阳气外泄，气属阳主外，血脱则气失所附，故卫虚不固。最怕喘呃暴脱，乃气随血脱之危候。胸痞已宽，稍能容纳，示胃气尚存，故仿血脱益气例，取阳生阴长之义。", ["数"]], "13633": ["病机", "脉细促，细为阴血亏少，促为虚火炎炎莫御。先天不足之体，虚痰溃敛，春阳升发，喉痒咳嗽，大吐血鲜红，心嘈若饥，一团虚火迫血妄行。细促并见，示真阴已伤而火势未熄，用药清降之余，当预顾真阴，否则恐血脱阴伤而晕。", ["细", "促"]], "13634": ["预后", "脉数无神，数为阴虚内热，无神则胃气已衰。咳嗽痰红，渐延劳损，此虚火灼肺、阴损及阳之兆。数而无神，非实热之数，乃真阴亏耗、虚阳浮越之数，故断为劳损之渐，预后堪忧。", ["数"]], "13635": ["治法", "脉形细弱，精气内亏，咳嗽失血音哑，津液枯槁，劳损已成。细弱为气血两虚、脾肾不足之脉，故《内经》调以甘药，《金匮》立黄耆建中汤，急建中气，俾饮食增、津气旺，阳生阴长而复真阴之虚。此脉此证，舍建中别无良法。", ["细", "弱"]], "13636": ["病机", "脉弦形瘦，弦为饮邪未去，瘦为阴血已亏。寒饮咳嗽化火动血，血证屡发，咳嗽不已，安静咳甚属阴，劳动气升属阳，阴虚痰饮四字显然。弦脉主饮主痛，亦主木旺，此处示饮邪留伏、阴血亏耗并存，故拟金水六君同都气丸法，补肾纳气、化胃蠲饮。", ["弦"]], "13637": ["病机", "脉虚数，两尺愈虚，虚为气阴不足，数为火亢，尺虚独甚示肾阴亏乏。心肝火亢，肺胃受戕，痰由湿生，血随气逆，咳嗽黄痰带血，掌中觉热。虚数之脉，本于肾虚而标于火亢，故法宜养肾之阴以清心肝之火，而肃肺胃之气。", ["虚", "数"]], "13638": ["病机", "脉数左寸独锐，左寸候心，锐为火炎之象。心经有火，迫血妄行，故吐血不止。数脉主热，独锐于左寸，定位在心，火性急迫，故血不止。法宜清养，清心火而养阴血，使火降血宁。", ["数"]], "13639": ["预后", "脉沉细涩，沉为里，细为阴亏，涩为血少气滞。真阴大亏，虚阳上亢，肺金受烁，脾胃伤戕，津液耗而元气损，咳嗽吐血，寒热，头汗，口腻而干，虚极成劳。沉细涩之脉，示精气内竭，难为力矣，姑拟生脉六君子汤保肺清金、调元益气，扶过夏令再议。", ["沉", "细", "涩"]], "13640": ["治法", "此段论生脉散保肺清金及六君子加减，以“土旺自能生金”为法，强调久病“以胃气为本”“有胃则生”。脉象原文未及，故脉素取空。所主病机为肺金不足而脾阴亦弱，故不用养阴退热之药，恐滋腻碍肠、寒凉妨胃，治法重在培土生金、护养胃气。", []], "13641": ["病机", "原文“食少，身热，脉数，其阴已虚”，脉数为阴虚火动之象，兼阳明火炽、少阴不运，血有间断而腹有瘀血。数脉在此不主实热，而主阴亏火旺、虚热内扰，故拟养阴化瘀、清胃和中，既清阳明炽火，又顾少阴已虚之阴。", ["数"]], "13642": ["病机", "原文“脉不数，舌苔白”，说明失血之后并无阴虚火旺之数脉，病机偏于痰饮久咳、肺络受伤而气机不顺。脉不数则不宜过清，故但顺气化痰，气顺则血归经、痰化则咳止，突出凭脉辨虚实寒热、勿见血即投凉。", ["不数"]], "13643": ["病机", "原文“脉不数，身不热，口不渴”，吐血虽多而脉不数，说明非阴虚火盛迫血，乃内伤经络、中气不足失于统摄。故“切勿见血投凉”，法当益胃，拟理中加味温运中阳，使胃气复而血自归经，体现脉症合参以辨寒热虚实。", ["不数"]], "13644": ["病机", "原文未识脉名，脉素取空。所论为阴虚有火于内、寒邪深袭于外，失血咳嗽兼三疟数月，疟来心口酸痛、胸腹空豁，引“阳维为病苦寒热，阴维为病苦心痛”，断为阴阳营卫偏虚。故拟黄耆建中调营卫，合生脉保肺阴、复脉保肾阴，通盘合局。", []], "13645": ["病机", "原文“诊脉虚弱，形容清瘦，年方十七，精未充而早泄，阴失守而火升”，脉虚弱主精气未充、阴不守而虚火上升，故血症屡发。虚脉示不足，弱脉示无力，合形瘦早泄，断为阴亏火动，治宜滋水降火，并须自保养，恐成难名之疾。", ["虚", "弱"]], "13646": ["预后", "原文“肿胀已退，脉象较前稍大，汗出至膝而止”，脉由病时转大，非病进，乃“阳气有流通之象，阴湿有消化之机”。大而见于肿退之后，示阳气渐复、湿浊渐化，故以温理中州善后，使决渎流通、寒转为温，然须调养百日以防反复，属预后判断。", ["大"]], "13647": ["病机", "原文“面黧腹肿，脉沉而细”，沉主里、细主虚，合面黧腹肿，断为“脾肾之阳不化，水湿阻滞于中”。阳虚不能化水，水湿内停故肿，脉沉细正是阳气不振、湿阻于里之应，故症防加剧，姑且渗湿通阳以治其标。", ["沉", "细"]], "13648": ["病机", "脉浮为风湿之邪在表，风与湿相搏，肺气不宣，通调失职，故一身悉肿、咽痛发热、咳而脉浮。浮脉主表，说明病位在肺卫肌表，风湿郁遏，肺失宣降，水气不行。拟越脾法即越婢汤，宣肺清热利水，从表解之。", ["浮"]], "13649": ["病机", "脉沉主里，水湿内停，三焦气化不利，故小便不利、面目肢体大腹阴囊悉肿，病属里水。沉脉说明水气在里，非表证。鼻中流血、喉间略痛为肺家有郁热，热郁于肺，水湿不化，拟越婢汤宣肺清热以利水。", ["沉"]], "13650": ["预后", "痢后阳虚，水湿不化，腹满面浮足肿，色青黄，脉来虚细。虚细为阳气亏虚、气血不足之象，脾阳不振则水湿泛滥。脉证相参，正虚水盛，虑延臌胀重症，说明预后不良，脾肾阳虚日甚，水湿壅聚难消。", ["虚", "细"]], "13651": ["病机", "脉细如丝，重按至骨乃见弦象，是肝木乘脾。细为气血不足，弦为肝旺，久疟结痞，水饮痰涎与气相搏，癖散成臌。口干、小便短少为湿热不运，腹日加大，肝木乘脾，脾失健运，水湿壅聚，故急宜疏通水道、泄木和中。", ["细", "弦"]], "13652": ["病机", "脉沉滑数，是积之征也。沉主里，滑主痰积，数主热，暑湿伏邪挟积阻滞肠胃，中州不运，故大腹骤满、腹中时痛、便黏色红如痢、小水短少。脉沉滑数说明积滞内阻、湿热蕴结，拟大橘皮汤送木香槟榔丸行气导滞。", ["沉", "滑", "数"]], "13653": ["病机", "脉沉主里，气与水相搏，大腹骤满，小便不利，大便欲泄不泄。沉脉说明水气内结在里，气机壅滞，三焦水道不通，故法以疏气逐水，行气以化水，水行则胀消。此段以脉沉点明病位在里、病机为气水互结。", ["沉"]], "13654": ["病机", "木旺乘脾，腹胀如鼓，形瘦脉细，症属瘅胀。脉细为脾虚气血不足，形瘦而腹胀如鼓，是肝木克脾、脾失健运、水湿壅聚之象。木旺乘脾，脾气日衰，故法当温通，温运脾阳以化水湿，通利气机以消胀满。", ["细"]], "13655": ["预后", "脾虚胀满，面浮足肿，小便不利，脉形细数，元气大亏。细为气血不足，数为虚热或元气外浮，脾虚不能运化水湿，故浮肿尿少。脉细数而元气大亏，正虚水盛，虑其喘急之变，说明病势危重，水气上凌心肺可致喘急。", ["细", "数"]], "13656": ["病机", "两尺脉滑，尺部候下焦，滑主湿浊壅盛。原文谓“湿热积滞在于下焦”，湿热蕴结下焦，气化不利则小便不利；下焦不通，中焦气机亦因之窒塞，故大腹胀满。脉滑与湿热积滞之病机相合，症见小便不利、腹胀，皆由下焦湿热阻滞、气机不通所致。", ["滑"]], "13657": ["病机", "原文未出脉名，仅言“水寒血气凝聚冲脉之分”，指出病机为水寒之邪与血气相凝，结聚于冲脉。冲脉为血海，起于胞中，水寒凝滞则血气不行，结聚成实。渊按认为“果是实证，此方必效”，强调辨证属实证者，温通攻散之方方能取效，脉象虽未明言，然病机重在寒凝血瘀之实证。", []], "13658": ["病机", "脉沉弦小，沉主里，弦主肝、主痛，小为气机收引之象。原文言“奔豚气之挟肝邪者也”，气从少腹上冲咽嗌，致心中跳、胁中痛，初起寒热而呕，皆肝邪挟冲气上逆之候。半月来寒热虽止而气仍上逆，脉沉弦小正示病根在里，肝气郁逆未平，故宜宗《金匮》奔豚法以平冲降逆。", ["沉", "弦", "小"]], "13659": ["病机", "脉沉紧而细，沉主里，紧主寒主痛，细主积。原文谓“板痛者聚而成块，偏于右部，是脾之积也”，休息痢日久，脾阳受损，寒湿凝滞，聚而成积，气攻胸脘板痛，上下不通，几至发厥，大便匝月仅通三次。脉沉紧细正合寒凝积滞之病机，故当与温通，以散寒消积。", ["沉", "紧", "细"]], "13660": ["病机", "脉沉细涩，沉主里，细主虚，涩主血行不畅。经停十月，腹微满，脐上心下块长数寸，病属伏梁，因七情恚怒气郁痰凝所致。气郁则血滞，痰凝则脉涩，沉细为里虚不足之象。原文引“大积大聚，其可犯也，衰其大半而止”，又取洁古“养正积自除”之意，故治以理气行血、和脾化痰，寓消于补。", ["沉", "细", "涩"]], "13661": ["病机", "原文未出脉名，仅述“少腹有块，痛则经来如注，气升如喘”，断为“冲脉久伤，肝木肆横”。冲脉起于胞中，为血海，久伤则血海不宁，肝木失于藏血，横逆上冲，故气升如喘；经来如注乃冲脉不固、肝不藏血之候。病机重在冲脉损伤、肝气横逆，脉象虽未言，而症候已明。", []], "13662": ["病机", "脉微细，原文直断为“阴之象也”。少腹有块上攻及脘，自脘至嗌气塞，大痛欲厥，头汗如雨，皆阴寒凝结、浊阴上逆之候。然舌有黄腻浊苔、便泄臭秽，又兼湿热；块痛得按稍减，中气又虚。脉微细主阳衰阴盛，故治宜温通为主，而湿热与正虚夹杂，方法难周。", ["微", "细"]], "13663": ["预后", "脉仍微细，昨用温通病势稍减而脉象未复，泄仍臭秽，恶谷厌纳，中气大亏，阴气凝结，当脐硬痛。原文虑“恐属脏结，攻之不可，补之亦难，诚为棘手”。微细为阳气衰微、阴寒内盛之脉，温通后脉不复，示正气难支，脏结之预后堪忧，故列于预后判断。", ["微", "细"]], "13664": ["病机", "脉迟细，迟主寒，细主虚，为脾胃虚寒之象。脘中有块、纳食撑胀、腹中漉漉作声、嗳腐吞酸，皆寒积内停、脾胃运化失职所致；大便坚结乃寒凝气滞、传导无力。故断为脾胃有寒积，当以温药下之，仿温脾法。", ["迟", "细"]], "13665": ["病机", "脉沉弦细，细而沉为虚为寒，沉而弦为气为郁。年逾六旬，元气下虚，中气已弱，肝气肆横，腹渐胀满，结癖累累，久踞腹中。病关情志，非湿热积滞可比，攻消克伐难施，故拟商通补，补虚通氣。", ["沉", "弦", "细"]], "13666": ["病机", "右关滑动，舌苔黄白而腻，是痰积在中焦；左关弦搏，肝木气旺，故左肋斜至脐下有梗一条，按之觉硬，乃肝气入络所结；尺寸脉俱微缓，泄痢一载，气血两亏。病根在痰积、湿热、肝气，须借元气以运行，故择性味不猛而能通能化者用之。", ["滑", "动", "弦", "微"]], "13667": ["病机", "血虚木横，两胁气撑痛，腹中有块，心荡而寒热。病根日久，损及奇经。冲脉为病，逆气里急；任脉为病，男疝女瘕；阳维为病苦寒热；阴维为病苦心痛。合而参之，谓非奇经之病乎？调之不易。", []], "13668": ["病机", "脉沉弦而紧，沉主里，弦主痛，紧主寒。素有肝胃气痛，兼挟寒积，脘腹胀满，痛及于腰，咳不可忍，舌苔白腻，渴不欲饮，大便似利不利，乃寒积内结、阳气不通之象。恐属脏结，颇为险候，非温不能通其阳，非下不能破其结。", ["沉", "弦", "紧"]], "13669": ["预后", "两投温下，大便仍然不通，胸腹高突，汤水下咽辄吐，肢渐冷，脉渐细，鼻煽额汗，乃太阴脾脏受戕，清阳失于转运，阳气衰微，厥脱可忧。脉渐细为正气渐衰之征，故预后险恶，急宜挽回。", ["细"]], "13670": ["病机", "脉沉弦，沉主里，弦主痛。腹痛，下午则胀，此属虚寒挟积。前用温下，痛势稍减，今以温中化积，乃针对虚寒挟积之病机而设。", ["沉", "弦"]], "13671": ["病机", "脉小弦滑，必有宿积；脉浮小而沉大，按之有力，此为阴中伏阳。腹痛三年，时作时止，寒在中焦，当与温化；每交午月其痛倍甚，则兼湿热。故当利少阴之枢，温厥阴之气，运太阴之滞，更参滑以去著法。", ["小", "弦", "滑", "浮"]], "13672": ["病机", "原文指出“脉浮小沉大，乃积伏下焦”，浮小为积未全实于上，沉大则主积伏下焦、气聚于下。痛则气聚，故脉见沉大，说明宿积内停、气机壅聚下焦，非久虚之候。此脉象与腹痛宿积相应，提示病机为积滞内伏、气聚不行。", ["浮", "小", "沉", "大"]], "13673": ["病机", "原文云“腹痛，左脉弦，木克土也”，又引仲景“腹痛脉弦者，小建中汤主之”。弦为肝木之脉，左脉候肝，弦见于左，是肝邪横逆、克伐脾土，故腹痛。痛时得食稍安，兼漉漉有声，又属中虚水饮。此脉主肝木乘土、中虚饮停之病机。", ["弦"]], "13674": ["病机", "原文述“痛势上攻及胃脘，连于心下，左脉独弦滑，是肝邪乘胃也”。左脉候肝，弦主肝郁，滑主痰饮，弦滑独见于左，说明肝邪挟痰饮上逆乘胃，故痛势上攻脘连心下。此脉象主肝邪犯胃、痰饮内阻之病机。", ["弦", "滑"]], "13675": ["病机", "原文云“脉迟，喜食甜味，痛在当脐，后连及腰，身常懔懔恶寒”，断为“中虚阳弱，寒积内停”。迟脉主寒主阳虚，阳弱不能温运，寒积内停，故痛在当脐、恶寒喜甘。此脉迟为阳虚寒积之征，主中虚阳弱、寒凝内停之病机。", ["迟"]], "13676": ["病机", "原文述“脘间窒痛，得食则安，不能嗳气，亦不易转矢气，脉迟弦”，断为“肝胃不和，阳虚寒聚于中”。迟主阳虚寒凝，弦主肝木郁滞，迟弦并见，说明肝胃不和、阳虚寒聚，气机窒塞，故脘痛而嗳气矢气俱难。此脉主阳虚寒聚、肝胃不和之病机。", ["迟", "弦"]], "13677": ["病机", "原文云“钱脉微细，阴之象也”，少腹有块上攻作痛，甚则欲厥、头汗如雨，用方大法温通无疑。微细为阴盛阳微之脉，主阴寒凝结、块痛上攻；然舌黄腻浊苔、便泄臭秽，又兼湿热，块痛得按稍减则属虚象。此脉主阴寒内结、阳气衰微之病机。", ["微", "细"]], "13678": ["预后", "原文述水饮痰涎与下焦浊阴盘踞于中，中脘腹胁有块攻撑作痛，痛甚发厥。昨用温通痛势稍减，但“脉仍微细，泄仍臭秽，谷食厌纳，中气大虚，阴气凝结，当脐硬痛，恐属脏结”。微细脉示阳气衰微、阴寒凝结，攻补两难，故断为棘手，主预后不良。", ["微", "细"]], "13679": ["病机", "原文虽言“脉证细辨焉”，实以脘痛属胃、腹痛属脾立论，述吞酸呕苦由生冷忧思伤脾胃阳和，肝胆失升达之机，郁而横逆侮土，气机与痰饮凝滞中脘作痛。脾寒不化，水饮停积，木乘其胜，化酸化苦，久则积饮成囊、生癖块。此段主肝木乘土、痰饮凝滞之病机。", []], "13680": ["预后", "脉形弦硬，春令见之即「但弦无胃」，失冲和胃气。弦为肝木之象，硬则木火亢逆、胃汁肠液干枯，故纳食哽痛、大便坚燥。此脉此症示木火灼津、胃阴耗竭，治之不易，属预后不良之候。", ["弦", "硬"]], "13681": ["病机", "左脉沉数不利，为肝气郁结、血少不泽；右关及寸滑搏，为痰火壅盛，肺胃失降、肝木上逆，水谷津液蒸酿为痰，阻塞气道，故咽喉胸膈阻碍、纳食呕噎。五志化火、阳亢阴不上承，哭泣无泪、目涩昏花，皆本此病机。", ["沉", "数", "滑", "搏"]], "13682": ["病机", "脉细如丝，为阴气凝聚、阳气汩没之象。气郁于胸则膈，气滞于腹则臌，饮食不纳而形肉顿瘦，正因阳气衰微不能运化、阴寒内结。脉细主阳微阴盛，故治以培土、通阳、化气，扶阳以散阴凝。", ["细"]], "13683": ["病机", "胃脉浮按则紧、沉按则弦。弦为木侮土，肝气犯胃；紧为寒在中，寒凝气滞。食下饱胀、作酸呕吐，病属反胃，正由木克土、中寒不运所致。浮紧沉弦并见，示寒与木郁交阻于胃。", ["浮", "紧", "沉", "弦"]], "13684": ["病机", "右脉沉滑，主痰浊内阻；左脉细弱，主血虚不足。吐血后瘀血挟痰浊阻于肺胃之络，下焦冲脉相火上逆，鼓动其痰，气自少腹上冲而呃逆。舌白腻亦痰湿之征，脉症合参，病机为瘀痰阻络、冲气上逆。", ["沉", "滑", "细", "弱"]], "13685": ["病机", "脉滑大为痰火壅盛之象。食入哽噎不下、舌腻，属痰膈；大肠燥火凝结，则痰火交阻、气机不通。滑主痰，大主火，脉症相应，故拟清痰火、佐宣通，以开痰火之结。", ["滑", "大"]], "13686": ["预后", "脉细肢寒，为阳微已甚之候。先曾呕血，胃中空虚，寒饮停留，阳气不通，水谷不化，故食入呕吐酸水、谷食随之而出，证成翻胃。脉细主阳衰，肢寒为阳不达外，虑延脾败，属难治之预后。", ["细"]], "13687": ["病机", "脉沉细数而涩，为血虚气郁之象。沉细主血少，数主郁火，涩主气滞血瘀，故经事不来。五志郁极从火化，饥而善食、小溲如脓，为三消之渐；胸痛吐酸水，则肝郁无疑。脉症合参，病机为血虚气郁、郁火内炽。", ["沉", "细", "数", "涩"]], "13688": ["病机", "脉仍数涩，数主郁热内盛，涩主阴血亏少。原文言\"郁热日盛，脏阴日消\"，正合数涩并见之理：热灼阴津则脉道不充而涩，热势不退则脉数。舌红而碎、口渴消饮为阴亏火炽之征，头眩目花、带下乃阴虚阳亢所致，故当寓清泄于补正之中。", ["数", "涩"]], "13689": ["主病", "左寸关搏数，左寸候心、左关候肝，搏数并见说明心肝之火极炽。原文直言\"心肝之火极炽\"，火盛则脉数而搏指有力。口干、小溲频数浑浊为下消之症，久有脚气则湿热蕴于下焦，故拟清心肝之火而化肾与膀胱之湿，脉象与症候相合。", ["数", "搏"]], "13690": ["病机", "脉数主内热，原文谓\"内热脉数，阴津亦亏\"。患者肛漏阴津先损于下，嗜酒湿热盛于中，劳碌感寒与痰湿相合而成痰饮，咳嗽呕吐清水。饮烧酒祛寒反致血溢，是热伤血络。温则劫阴、清则加咳，故治宜和胃降气，脉数正是阴虚内热之据。", ["数"]], "13691": ["病机", "脉细数，细主阴血不足，数主内热，原文称\"内热，阴虚之候\"。咳呕清水为痰饮之病，治饮宜温而治阴虚宜滋，药适相背。故取肝肾子母补母益子、胃土为肺金之母而和胃化痰，滋燥兼行，正因细数之脉示阴虚内热，不可纯用温燥。", ["细", "数"]], "13692": ["病机", "脉弦迟，迟则为寒，弦主饮。原文引《脉经》\"迟则为寒\"、仲景\"口不渴而脉双弦者，饮也\"，脐以上连胃脘胀痛正是寒饮内停、阳气不运之象。双弦并见更确指饮邪为患，寒饮阻遏气机故胀痛，口不渴亦为寒饮之佐证。", ["弦", "迟"]], "13693": ["病机", "脉弦大而迟，迟主寒，弦主饮，大示阳气不足而虚。原文断为\"胃中阳气不足，而有寒饮也\"。当脐腹痛、痛则气塞胸中、气嗳不得语，皆寒饮阻遏、胃阳不振、气机不通所致，故当以温药通之，温通则寒饮散而阳气复。", ["弦", "大", "迟"]], "13694": ["病机", "脉沉弦者，沉主里、弦主饮，原文径言\"脉沉弦者，饮也\"。头眩心悸为饮邪上凌，呕吐酸水、满背气攻作痛、得嗳则松，是浊阴之气上攻阳位、气机暂得宣通之象。饮属阴邪，故当以温药和之，温阳化饮则诸症可解。", ["沉", "弦"]], "13695": ["病机", "脉象弦滑，原文自释\"滑主痰饮\"，弦亦主饮主气逆。中气不足则湿化为痰，气逆不降故喘息不安；痰饮属阴，阴邪旺于阴分，故病甚于夜。弦滑并见正合痰饮内停、气逆不降之机，故拟降气化痰兼扶中气，标本兼顾。", ["弦", "滑"]], "13696": ["病机", "春脉本当弦，今反微，是肝气不足、升发无力之象。肝虚则魂不藏，故夜不得寐；胃虚则阳气失明，故昼日反寐。原文以“肝虚魂不藏”“胃虚则阳气失明”点明病机，脉微正是阳气虚衰、肝胃俱弱之应，故治以补肝藏魂、益胃补气。", ["弦", "微"]], "13697": ["误治", "痰饮久留，脾肾两亏，水泛为溢饮，腹满足肿面浮。脉细为阳气衰微之征，原文言“脉细阳衰，便难液涸，肾气久虚”，故不可更投小青龙发泄耗阴伤阳，而拟附子都气丸裁去熟地，以痰多痞塞故也。此段重在凭脉细阳衰以戒发散之误。", ["细"]], "13698": ["病机", "风邪久恋肺中，寒饮停留胃脘，积饮生痰，胃阳失布。肺伤则肾亦亏，胃虚则脾亦弱，脾弱故便泄，肾亏故左尺脉弦而大。左尺候肾，弦大为肾虚饮泛之象，原文以“肾亏故左尺脉弦而大”明其病机，咳将一载而时呕清水，确为寒饮无疑。", ["弦", "大"]], "13699": ["预后", "嗜酒多湿，湿蕴生痰，体质阴虚，烦劳伤气，咳嗽带血，行动气升。诊脉虚小，为气阴两虚、正气不足之象。原文言“恐加喘急”，是虑虚小之脉提示金水两亏、肾不纳气，病势有转喘之虞，故以金水六君煎加味，兼顾肺肾气阴。", ["虚", "小"]], "13700": ["病机", "心痛呕吐得食则安，系中虚痰饮伏留心下。病延一载，咳频不已，诊脉双弦，形肉瘦削，口不干渴，身不发热，头眩心悸。双弦为饮邪内踞、肝脾失调之象，原文谓“肝肾之阴已虚，脾胃之气亦弱，痰饮恋而未化”，故从肺脾肾三经立法。", ["弦"]], "13701": ["预后", "脘胁之痛虽除，而脾胃之气大惫，面浮足肿，土衰水泛。脉细少神，为阳气衰微、胃气将败之征。原文虑其腹满，急宜温补中阳以消水湿，是知细而少神之脉提示中阳不振、水湿难化，预后堪忧，故当自知节爱。", ["细"]], "13702": ["病机", "此段总论痰饮名义与五饮所生，谓总由肺脾阳虚，水饮入胃不能布化通调，停蓄胃肠之间。原文虽言“脉多弦”，实以饮邪内停、阳气不布为病机根本，弦脉应饮，故痰饮、悬饮、溢饮诸证多见此脉，不必尽有咳嗽。", ["弦"]], "13703": ["治法", "脉散为气阴耗散、肺肾两虚之象，故用六味地黄合生脉散加青铅。六味滋肾填阴，生脉散敛肺益气生脉，青铅镇摄纳气，合而治脉散所主之气阴离散、虚喘欲脱。原文仅列方药，然脉散与治法相印，示以敛散固脱为要。", ["散"]], "13704": ["病机", "脉涩主湿滞血少，数主热。伏暑挟湿，湿郁生热，湿热痰浊恋于肺胃，气血运行不畅故涩，热邪内蒸故数。吐血虽止而咳仍作，舌灰白而渴，便溏食少，皆湿热困阻、脾胃不醒之象，脉涩数正合痰浊湿热交阻之机。", ["涩", "数"]], "13705": ["病机", "左脉细微，左候肝肾，微为阳虚，细为阴弱，故曰肝肾之虚大著。咳喘本在肺胃，久则深入肝肾，摄纳无权，气出多纳少。虽舌苔黄浊似实，然额汗冷、胃泛不纳，脉细微已露虚脱之兆，故当以摄纳为要。", ["微", "细"]], "13706": ["预后", "此段以药后反应判吉凶。额汗收敛、左脉稍起，则阳气渐回、肝肾有根，故犹有生机可理；若服之不应，脉不能起，则元气难复，故曰难为力矣。脉之起与不起，为预后转归之关键，非泛论病机。", []], "13707": ["病机", "脉形细数，细为阴虚，数为火动。下焦阴虚则脉数，中焦痰盛则喘哮频发，上焦肺弱故身常恶寒。三焦同病，虚实夹杂，故曰病有三层、治有三法，须层层护卫、法法兼到，非一法可尽。", ["细", "数"]], "13708": ["病机", "脉迟者为寒，舌白者为痰。喘之标在肺、本在肾，肾阳不足则水泛为痰，寒痰上逆迫肺而喘。脉迟正示下焦虚寒、痰饮内停之机，故以金水六君煎温肾化痰、标本兼顾。", ["迟"]], "13709": ["病机", "脉形细数，细主阴津亏少，数主火旺。汗多未敛、掌心热、食减，皆阴津大亏之征；炎暑水衰火旺，金受其灼，故气喘交午愈甚、咳痰黄。脉细数与阴虚火旺、肺金受灼之机相应，渐有延成损症之势。", ["细", "数"]], "13710": ["病机", "实者风寒痰火壅于肺胃，脉数浮滑不空，数主热、浮滑主痰热壅盛于外；若脉浮而紧，则风寒闭其肺络、元府不宣。虚者肺肾内虚、脾胃气弱，痰饮留于肺系胃络。此段以脉之浮紧滑数与空豁虚弦分虚实两途，脉象为辨证之纲。", ["数", "浮", "滑", "紧"]], "13711": ["病机", "脉虚细数，虚为气弱，细为阴亏，数为火动。三疟后盗汗伤津，去秋咳血，今行动气喘、内热多汗、食少无力，皆阴津大伤、虚火内扰之象。脉虚细数与劳损根深、气阴两亏之机相合，故曰劳损根深。", ["虚", "细", "数"]], "13712": ["病机", "脉细为精气两虚之象。盗汗气喘咳嗽，乃肺肾两亏，精气耗损，脉道不充故细。景岳云大虚之症微补尚难见效，强调虚损之重，治当补摄肺肾，非寻常补益可及。", ["细"]], "13713": ["预后", "脉数未退，示阴虚未复，虚热内扰。咳嗽不止则肺气日虚，夏暑将临，火令助热，病尚未稳，故宜小心安养。脉数不退为阴不复之征，预后须防暑热加重虚损。", ["数"]], "13714": ["病机", "脉形坚搏，外似有余而里实不足，乃高年娇脏暗伤、风温劫津灼肺之候。舌苔薄白底有裂纹，饮食略减，示胃津受劫。坚搏之脉非实热，乃阴伤脉失柔润，故不可再投辛散，当甘润生津。", ["坚", "搏"]], "13715": ["病机", "右脉弦滑，左弦小数，弦主肝郁，滑主痰，数小为郁热。肝经郁勃之热，肺家胶黏之痰，痰火郁蒸故浓痰腥臭，非肺痈可比。治当平肝开郁，参清金化痰，紧扣脉象所示肝肺同病。", ["弦", "滑", "数", "小"]], "13716": ["预后", "咳嗽面白为金伤，脉数而洪属虚火，是脉克色而火胜金也。夏至一阴生，正属火令，为剥极则复之际。若剥而不复，则火灼金销，预后堪虑。脉数洪与面白相悖，故曰脉克色。", ["数", "洪"]], "13717": ["治法", "此段为治法方药，以生脉散合六君子汤加紫菀，益气养阴、健脾化痰止咳。文中并考六君子汤之组成变异，属方剂加减讨论，非脉象主病之文，故脉象要素为空。", []], "13718": ["病机", "暑风从背俞内薄于肺，湿热从胃脉上注于肺，外内合邪，气并于胸中不得通，因而上逆作咳。舌苔薄白、口腻不渴，治属饮家。此段论邪气传变与咳逆病机，未出脉象，故脉象要素为空。", []], "13719": ["病机", "脉虚数为气血亏虚、虚热内扰之象。产后血舍空虚，八脉先伤于下，悲哀伤肺，咳嗽震动，冲脉之气上逆，故背寒内热、气逆痰多、大便溏。频进疏风清热更伤脾胃，成蓐劳之候，治当通补奇经、扶脾理肺。", ["虚", "数"]], "13720": ["病机", "脉形空大，为肺气虽虚而留邪未尽之象。肺为娇脏，感寒受热则咳，邪恋日久，肺虚不敛故脉空，邪郁气逆故脉大。得汗身轻，更证表邪未净。此非纯虚，亦非纯实，乃虚中夹邪，故降气化痰涤饮少效，当补虚兼化邪。", ["空", "大"]], "13721": ["病机", "脉虚软而似数，为内伤虚弱之征。虚处受邪，其病则实，咳嗽虽由外感，实因气虚。虚软似数非真热，乃气弱不敛。既不可作风寒峻散，亦不可作虚损纯补，故以玉竹饮子主之，养阴益气兼化留邪。", ["虚", "软", "数"]], "13722": ["病机", "此段无脉象，专论咳嗽病机。外感之咳从感寒饮寒而起，邪由皮毛内合于肺，当从肺治，或散或温或凉；内伤之咳则五脏十二经皆有，致咳不在肺，断不可专治肺。久咳必先顾胃气，胃不顺则咳不愈。强调辨病因脏腑，非独肺也。", []], "13723": ["病机", "此段无脉象，论疝病机。古人谓七疝隶于肝，以少腹前阴皆厥阴部位。然病标在肝，病本在脾肾。水寒土湿，木失其荣，藏舍空而经络虚，寒湿热湿乘虚袭入，邪郁不化，木不条达，横塞本位经脉而作疝。冲心则死，因心阳大虚，寒邪直犯君主。", []], "13724": ["病机", "此段无脉象，论精浊连年兼血块淋漓之病机。肝肾大虚，八脉无以固摄，湿热混乱不清，舌苔白腻。虚不摄精则精浊不断，湿热伤络则血块淋漓。法当脾肾双补，固摄下焦，兼清湿热，非单纯补涩可愈。", []], "13725": ["病机", "脉之虚，指肝肾八脉之虚。由湿浊混淆，精血频下，虚象虽著，然湿热相火未清。若不先清湿热以宁相火，徒事补肾固精，是谓不清其源而欲塞其流。此脉虚主本虚，而病机关键在湿热标实，故治当先清后补。", ["虚"]], "13726": ["病机", "诊脉细肢寒，为肾阳与胃阳不布。水窍为败精瘀浊阻塞，湿热不泄，下焦浊气上攻及胃，故时时嗳气、腹中不和、二便不爽。脉细主阳微，肢寒为阳不达末。法宜通阳渗湿，益肾化浊，使浊气下行，阳气得布。", ["细"]], "13727": ["病机", "左尺极细，寸关微而似数，右三部俱弦滑。尺细为肾阴下亏，寸关微数乃虚火浮动，右弦滑主湿热相火。下有遗精暗疾、肛门痒而出水，上则头眩耳鸣、舌苔粉白，皆湿热相火下淫上混，清窍蒙闭。法当补肾阴、清相火，清金和胃，分利膀胱以化湿热。", ["细", "微", "数", "弦"]], "13728": ["病机", "脉细固属阴虚，若下垂尺泽，是相火下淫，故精血下流，小溲便数，溺窍疼痛，大便干结。细脉主阴血不足，尺部尤显则相火妄动，下扰精室膀胱，故见精血下流、溺数而痛；火灼津液则便结。补养肾阴兼清相火为法。", ["细"]], "13729": ["病机", "脉左小右大，左小为肾水亏虚不能上承，右大为心阳内亢反下趋肾，即坎离不交。水亏火亢则下为淋浊尿血、宗筋绊痛，上为眩晕咳嗽、心中震跃。形逸心劳，内伤虚症无疑，治拟和平补益。", ["小", "大"]], "13730": ["病机", "右脉空大，两尺皆虚，是心阴耗损，君不制相，相火妄动。空大为阴血亏虚不能充盈脉道，尺虚为肾气不固。相火扰精则强阳常举、精浊时流；火灼肺金则干嗽无痰；脾失温煦则便溏气坠。法宜补心阴制相火，益肾气固元精。", ["空", "大", "虚"]], "13731": ["病机", "疡脓后气血必虚，奔走烈日汗出招风，风热毒舍于皮肤脉络。秋凉外束，热郁皮中，遍体瘙痒。面黑而浮、少腹满，唇舌麻是外风引动内风。经云面肿曰风，风行必燥，木胜克土，现为风癞，久防腹满。", []], "13732": ["病机", "脉软无力属气虚，便溏食少属脾虚，干咳无痰属肺虚，时觉口苦属心热移脾。软脉主气弱不运，脾虚失健则便溏食少；肺气虚则干咳无痰；心热移脾故口苦。宜十补一清，补虚为主兼清心热。", ["软"]], "13733": ["预后", "年近六旬天癸反频来，是脱营，元气极虚不能固摄，血从外脱，故腰痛如折。下竭必上厥，面赤火升发热。阴虚阳亢则脉弦硬无情，脉愈数则阴愈虚。夏令阳亢无制，恐水涸龙飞，难为力矣，属危候。", ["弦", "硬", "数"]], "13734": ["病机", "经来半月不止，紫血块，少腹疼痛，气坠阴门，脉沉涩，下午恶寒。沉涩为阳陷入阴、营虚失守，血行不畅故有紫块；气虚下陷则气坠阴门。法以升阳收摄其阴。", ["沉", "涩"]], "13735": ["病机", "营分有热则经至淋漓，卫分有寒则脉小而迟缓。小迟缓为卫阳不足、寒凝脉道。脾为营之本，胃为卫之源，胃阳虚无力化浊，故经至舌苔反布而胸无痞闷。拟醒胃阳以摄脾阴。", ["小", "迟", "缓"]], "13736": ["病机", "脉细迟缓，细为血少阴亏，迟为阳运不及，缓主中气虚弱。原文以“脉细迟缓，中气不足也”点明主旨，与“舌白多痰，胃有浊”“咽干色红，阴虚而火浮”并见，说明经行过多后血气两衰、肝肾失固，中焦脾胃气虚不运，故脉来细而迟缓，主虚损不足之候。", ["细", "迟", "缓"]], "13737": ["病机", "右脉更觉细微，右候脾肺，细微为气血虚衰之象。原文谓“脾气虚衰不振”，又见“心跳食少，心脾不足可知”，经漏不止、腹中微痛，乃气虚且滞、冲任不固。左脉稍有力为归、地滋养之功，右脉细微则脾虚未复，故取补肾不如补脾之义，主心脾不足、气不摄血之病机。", ["细", "微"]], "13738": ["病机", "脉小迟缓，小为气血不足，迟为阳衰，缓为虚软无力。原文据此断“其漏未必属热，或脾肾阳虚，不能固摄其血”，反对见血即以为热。脉小迟缓正合虚寒之象，主脾肾阳虚、固摄无权之崩漏，故须固而兼温，非清热凉血所宜。", ["小", "迟", "缓"]], "13739": ["病机", "原文言“通络脉之凝涩”，脉之凝涩即血行不畅、络脉瘀阻之象。症见经后少腹痛连腰股、肛门气坠、大便不通、小便赤涩热痛，乃肝经郁热与络脉凝涩并见，涩脉主气滞血瘀、络道不通，故拟宣肝经郁热、通络脉之凝涩，属瘀热互结之病机。", ["涩"]], "13740": ["病机", "本段未识脉名，纯论病机。原文谓“经未尽而行房过度所致，乃经血乘虚入络，冲任入脉受伤也”，指出经期未净而房劳伤损，血室正开，经血乘虚内陷络脉，冲任受损，属瘀血内留、冲任不固之候，与脉象描述无直接对应，故脉象要素从缺。", []], "13741": ["病机", "脉促数，促为阳盛而数中一止，数为热盛行速。原文列“寒热无序”“下有淋带”“上则心跳”“少腹痛、大便坚、面色萎黄”，断为“血瘀之候”，虑延劳损。促数之脉反映瘀热内郁、气血壅滞，热与瘀搏故脉数而促，主血瘀化热、虚实夹杂之病机。", ["促", "数"]], "13742": ["病机", "脉象细数，细主阴血亏少，数主有热。原文谓崩止而淋滞不断、少腹板痛、身发寒热、脾胃大虚，断为“血瘀未尽，复兼肝气夹寒”。细数之脉示阴血耗伤而瘀热未清，脾胃已虚，故法当通补兼施，主瘀血未尽、肝寒气滞、脾胃虚弱之病机。", ["细", "数"]], "13743": ["病机", "本段未识脉名，专论经水生成与调经之本。原文以“经乃心血与肾液相合而成”立论，强调“其质虽阴，其用则阳”，引叶天士“妇女以心脾为立命之本”，批评世医动曰冲任八脉而言末忘本。全段阐发经水盛衰通塞根于心脾阳气，属病机理论之辨，无具体脉象可录。", []], "13744": ["病机", "脉细为阳气不足、寒凝血脉之象，肢寒更印证下焦寒凝。原文言\"寒气客于下焦，瘀凝停于小腹\"，膀胱阳气失化而癃闭，脉细肢寒正是寒瘀阻塞、阳不温煦之征，故主温通下焦、化瘀利水，并防气逆发厥。", ["细"]], "13745": ["病机", "左脉细数，原文明言\"营阴亏也\"，阴亏则脉细，虚热则数；右脉细软，\"脾气虚也\"，软为气弱不充。产后劳碌，气血不复，故身常内热、心荡若嘈，脉象与营亏脾虚之症相应，久延虑成劳损，治以人参养营汤加减。", ["细", "数", "软"]], "13746": ["病机", "脉弦搏，原文谓\"肝阳有上亢之象\"。小产后恶露即止，血凝成块，胞络上系心包，血凝动火、火炽生风，故心神妄乱、言语如癫。弦为肝脉，搏为阳亢有力，故防加吐血，治以化瘀为先、清火化痰为佐。", ["弦", "搏"]], "13747": ["预后", "脉洪而荒，洪为虚阳外越之象，荒则脉形散乱无伦。原文言\"肝风炽张，营虚气耗，虚阳外越\"，故面赤身温、痉厥不醒、恶露稀少、汤水不入。脉证相悖，恐厥而不返，属危重预后之候，姑拟一方希冀万一。", ["洪"]], "13748": ["其他", "此段为渊按评语，辨\"脉荒\"之义，谓荒即乱也，并讥其说属杜撰。原文未出具体脉名，故脉象要素为空。所论重在虚风挟痰上逆之病机，主张化痰降火、冲入童便，属对前案脉象说法的辨析与治法补充。", []], "13749": ["病机", "脉大稍软，较前洪荒略缓，恶露稍多、面赤稍退，是虚阳稍敛之兆。然厥仍不醒、舌灰黄、时沃涎沫、饮食不进，原文断为\"营虚气滞，胃虚浊泛\"。脉大而软示气耗未复，浊阴上泛，故须温通化浊以冀阳回厥醒。", ["大", "软"]], "13750": ["兼症", "脉沉，主邪入于里。产后淋雨，水寒之气从毛窍入骨节，内舍于肾，外达太阳、阳明，故腰疼、头痛、遍体机关不利。脉沉而兼寒热，寐少恐惧、纳少恶心，原文谓\"邪气留连于胃肾\"，头痛甚则汗出为太阳表虚，脉沉与里邪相应。", ["沉"]], "13751": ["病机", "脉虽虚，原文借此论产后治法：新产百脉虽虚，然感邪则实，不可泥于大补。虚为产后本象，若兼外感内阻瘀滞，当见证治证，急去其邪即所以养正。此段以脉虚为纲，辨虚实缓急，强调补有方、攻宜慎，非单纯主病之脉。", ["虚"]], "13752": ["小儿", "原文指出幼儿脉难凭，仅得浮沉迟数大略，故称哑科。强调四诊只得其二，需察声望色、询乳母。批判挑惊陋习，不问外感内伤概以惊风呼之，妄用开药。此段主论小儿诊法之难与世风之弊，非论特定脉象主病。", []], "13753": ["预后", "右脉软弱，胃气残惫。脑疽高年，头顶平塌，根脚散蔓，脓少木肿，此气虚不能引血化腐托毒。脉软弱示元气亏虚，卫外、冲和、升降之气不足，故深恐阳变为阴，脓腐不克依期，预后堪虑。", ["软", "弱"]], "13754": ["主病", "怒则肝气逆，血苑于上，章门结块硬痛，寒热脉数，小便短少。脉数主热，肝气郁逆化火，血瘀热结，症属肝痈。防其内溃咳吐脓血而剧，脉数与寒热、结块硬痛相应，示热毒壅盛。", ["数"]], "13755": ["病机", "脉附骨极细而锐，细主正虚，锐示瘀伤。脾家有湿热瘀伤，症属脾痈。痛处略肿、食少便溏、面浮足肿、腰脊酸痛，皆脾虚湿盛、瘀热内结之象。日久正虚胃弱，脉细锐应之，恐不克支持。", ["细", "锐"]], "13756": ["治法", "肠内痈脓将足，脉细食少。脉细为气血不足，食少为胃气弱。脓将成而正虚，故治以托里，冀其外溃。脉细食少示托毒无力，需扶正托邪，使脓外透为妙。", ["细"]], "13757": ["病机", "肾俞漫肿色白，脉虚微热，此肾俞发也。脉虚主三阴亏损，气血不足；微热为湿热入络，气血凝滞。色白漫肿示阴证，属虚中夹实，最为淹缠，姑与消散法。", ["虚"]], "13758": ["预后", "胃脘生痈，脉虚形瘦，初起寒热，延今四十余日，晨必泄泻无度。脉虚形瘦示中气大虚，不胜攻消。泄泻无度更伤中气，故与内托法。倘仍作泻，则脾败难治，预后不良。", ["虚"]], "13759": ["病机", "肝胆郁火，凝结成痰，腮颊硬肿，牙关不开，此骨槽痰也。脉象郁涩，涩主气滞血瘀，郁示火郁痰凝。气失利畅，痰火胶结，故药力不易见效。脉涩与硬肿、牙关不开相应。", ["涩"]], "13760": ["病机", "脉息太细，系素禀六阴，真阳不足。细脉主虚，此因体质阴盛阳微，故虽喉痹火逆，清药亦宜酌用，恐阴未足而阳先伤。", ["细"]], "13761": ["预后", "脉数而虚，其阴已伤。数主热，虚主不足，咳吐臭痰三月，面白无华，饮食渐减，肺失所恃，防成肺痿。", ["数", "虚"]], "13762": ["预后", "脉数而虚，咳痰腥臭，面色青晦，纳谷大减。此木火乘金，金伤及土，脏气克贼，恐延不治。", ["数", "虚"]], "13763": ["病机", "体肥湿胜，卫虚冷营盛热，疡发背脊，内脓已结外腐未透。营火炽卫弱失敷布，不能引血化腐载毒外出，渐显内陷之机。", []], "13764": ["病机", "切脉虚细已极，此不可徒攻其病者，以阴分太亏耳。虚细主阴血亏虚，故用景岳法滋阴养血，一剂而瘳。", ["虚", "细"]], "13765": ["病机", "脉洪大滑数，阳明暑疟也，与伤寒三阳合病同符。洪大滑数主暑热炽盛，故用竹叶石膏汤清热兼益气。", ["洪", "大", "滑", "数"]], "13766": ["病机", "切脉微而弱，虚象显然。溺清且长，此土虚不制水也。通利无功，滋阴亦谬，法宜补土胜湿，与大剂参、术。", ["微", "弱"]], "13767": ["妇人", "孟英诊妊娠之脉，曰妊也。是月天癸犹来，次月仍转但不多，汛不断者荫胎之血有余。四月后经停娠显，娩如期。", []], "13768": ["预后", "原文未明言脉象，但述“脉仅若蛛丝过指”，此喻脉微细欲绝，主正气衰脱。前案胸痞多痰因清阳不司旋运，以参耆苓术而愈，后汗脱而亡；此案气从溺脱，脉微欲绝，本应参附回阳，却误灌痰药、痧药、风药，故孟英断为不治。脉若蛛丝过指，示元气将绝，胃气已败，故须臾而卒。", []], "13769": ["病机", "脉“既数且乱，沉取极细”，数主热，乱为至数不齐、脉形散乱，细为阴伤。此因阴分素亏，误服附、桂温燥，致汗出昏狂、精流欲脱。数乱为虚阳外越、热扰心神，沉细为阴精内竭。故孟英谓“生机仅存一线”，以元参、知、柏等救阴清热，非附桂之罪，乃阴亏之体不耐温补。", ["数", "乱", "细"]], "13770": ["病机", "脉“沉而涩滞，模糊不分至数”，沉主里，涩滞主气机窒塞、湿阻血行。此因感风湿失解，从热化，又加温补，致邪热无出路，烁液成痰，上涌而肢凉、二便涩少。脉模糊不分至数，为痰热壅遏、气机闭阻之象。故治以舒展气机、清热化痰，使痰行热降而愈。", ["沉", "涩"]], "13771": ["病机", "脉“微而细”，微主阳气衰，细主阴血少，合为气血两伤。此因多服表散，汗出过分，津血耗伤，肢骸失养，故不能起坐、类乎瘫痪。舌亮无苔亦阴血亏乏之征。脉微细与气血双补法相应，以汗为心液，阴分偏伤，故补血药重于补气，数十帖而起。", ["微", "细"]], "13772": ["病机", "脉“似虚细，而沉分略形弦滑”，虚细为少阴不足、阴血亏虚；沉分弦滑为阳明有余、土燥水涸，无形之热内蕴。故见肌肤消瘦、两腓发热、面色青黄隐黑气。此内伤不足兼有余之热，非外感可直泻，宜甘寒养阴清热，使黑气退、肌渐充、经亦调。", ["虚", "细", "弦", "滑"]], "13773": ["病机", "脉“空数”，空为血虚脉道不充，数主虚火浮动。舌色红润而患舌疮痛碍饮食，内治外敷不效，正是血虚火浮、虚火上炎之候。孟英以产后发热例施之，用熟地、当归、酒炒白芍等养血，炮姜引火归元，炙甘草、茯苓和中，使血充火降而病如失。", ["空", "数"]], "13774": ["误治", "脉“软数”，软为气分不足或湿阻，数主热。霍乱后目闭呃忒，医谓脱陷欲用桂附回阳，然询知溺赤口干，脉软数，显系肺胃余热未清、气机不降，非虚寒脱陷。若误服肉桂辛热，必助热伤阴而死。孟英令倾泼其药，与肃肺清胃之剂，热清胃降，呃止目开而渐安。", ["软", "数"]], "13775": ["病机", "脉“弦滑而大”，弦主气逆，滑主痰食，大为邪实壅盛。年逾花甲卒仆于地，乃痰、气、食相并逆于上，蒙蔽清窍。脉弦滑大示邪实有余，非虚脱之候。故先以乌梅擦牙、竹箸启口，灌淡盐姜汤探吐，吐出痰食，太息一声而苏，继以调气和中而愈。", ["弦", "滑", "大"]], "13776": ["主病", "脉虚微欲绝，乃新产气血大伤，气随血脱之候。泄泻自汗、呕吐不纳，中阳衰败，阴液外泄，故脉道空虚，鼓动无力。虚微欲绝主正气将绝，急宜大补，迟则不及。", ["虚", "微"]], "13777": ["病机", "脉缓滑，缓主气机弛纵，滑主痰湿内蕴。汛愆而饮食渐减，非血枯经闭，乃痰气凝滞、经隧不宣。痰阻气机，故脉见缓滑；治以豁痰流气，勿投血药，经自流通。", ["缓", "滑"]], "13778": ["病机", "脉来涩数上溢，涩为津液已伤，数为热邪内炽。冬温误表散则津伤热炽，继滋填则热邪愈锢，温补则气机更窒。热邪上逆，故脉上溢；阴伤液涸，故脉涩。主津伤热结之坏证。", ["涩", "数"]], "13779": ["主病", "脉弦细以数，弦主内损，细为阴亏，数则虚热。腰疽反复五年，非外疡实邪，乃内损肾阴，虚火内动。弦细数脉示真阴不足、虚热内扰，故以大剂甘润滋填取效。", ["弦", "细", "数"]], "13780": ["病机", "前案脉浮弦以滑，浮弦为风阳上扰，滑为痰浊内盛，故顺气蠲痰、息风降火。后案脉微弱而弦，微弱为气阴两虚，弦为虚风内动，故镇补摄纳。二案脉异，示虚实之辨。", ["浮", "弦", "滑", "微"]], "13781": ["病机", "脉极沉重，按至骨则弦滑隐然。沉主里，弦滑为痰饮内伏。怯寒面青、吐沫阳痿，乃阳虚痰凝，深伏于里，故脉沉取始见弦滑。非表寒，乃内损痰饮之候。", ["沉", "弦", "滑"]], "13782": ["病机", "脉沉而滑数，沉主里，滑数为痰热内蕴。疟后温补，暑湿失解，酿成痰饮盘踞三焦，气机阻塞，故外显寒象而脉见滑数。喜热熨而气冲如冰，乃痰热内郁、阳不外达之假寒。", ["沉", "滑", "数"]], "13783": ["主病", "原文未识脉名，但述壮热烙指、汗出如雨、汗珠微有粉红色。此虚损之体，暑热炽盛，迫津外泄，热灼血分，故汗带粉色。本虚标实，急则治标，先清客邪，主暑热伤营之候。", []], "13784": ["病机", "脉沉为里，弦滑且数乃肝风煽痰之象。过投温补，引动肝风，煽津液为痰，痰乘风上逆，故见昏厥、抽搐；阳气尽逆于上则鼻塞面浮，浊气不降则便滞不饥。脉象与晕厥、肢搐、面浮等症相应，揭示风痰上扰、气逆不降之病机。", ["沉", "弦", "滑", "数"]], "13785": ["病机", "脉细而滑数，细为阴伤，滑数为湿热内蕴。患者年近古稀，囊肿溲赤短，寒热如疟，乃久蕴湿热下流，气机未宣。脉象与湿热下注、气化不利之证相应，故用五苓合滋肾加楝实、栀子、木通以清利湿热，两剂后囊间出腥黏黄水，小溲渐行。", ["细", "滑", "数"]], "13786": ["病机", "脉甚数，数为热，此非实热乃阴亏内热。患者素禀不坚，头眩脑鸣，频服温补反觉畏冷，是阴亏不能涵阳。孟英断为阴亏，温补非宜，改滋水培元有效。后误灸伤阴，寒少热多如疟，脉滑数倍加，更证实艾火大伤阴液，脉数主阴亏热炽之机。", ["数"]], "13787": ["病机", "脉细数而促，细为阴亏，数为热炽，促为热盛阴伤、脉道急迫。患者神昏谵妄、肢搐耳聋、舌黑唇焦、囊缩溺滴、胸现微斑，皆阴亏热炽、液将涸竭之候。脉象与危重证候相应，故孟英断为阴亏热炽，液将涸矣，用大剂甘凉濡润以救阴清热。", ["细", "数", "促"]], "13788": ["病机", "脉虚弦而小数，虚为素体不足，弦为内风动，小数为阴伤有热。患者头痛偏左、子夜热躁、肢冷欲呕、口干不欲饮、舌蹇言涩，乃过投温散，阴津阳气皆伤，滋腻妨中，刚烈动风。脉象与虚风内动、阴阳两伤之证相应，故用扶正熄风、滋阴和阳之剂。", ["虚", "弦", "小", "数"]], "13789": ["病机", "脉滑而数，滑主痰热，数主火盛。瘄疹甫出而汛至，医者发散太过，火盛风炽，气血两燔，故舌绛大渴、面赤失音、不食便泻。脉象与气营两燔之证相应，气分之邪由泻略泄，营分之热由汛稍解，孟英以清解气血、凉营透热为治，三日而愈。", ["滑", "数"]], "13790": ["病机", "右寸关滑数上溢，左手弦数，滑数为暑热壅肺，弦数为热郁肝胆。患者耳聋口苦、热甚于夜、胸次迷闷、频吐黏沫、啜饮咽喉阻塞、便溏溺赤、间有谵语，皆暑热在肺、并不传经之候。脉象与肺经暑热、气分壅盛相应，故孟英谓一剂白虎汤可愈。", ["滑", "数", "弦"]], "13791": ["病机", "脉数而芤，数为热盛，芤为阴血亏耗、脉道中空。患者裸卧昏狂、舌黑大渴、溺赤便秘，乃暑热深入营血，耗伤阴液。脉象与暑热伤营、阴血亏虚之证相应，故用犀角地黄汤加减凉血解毒、养阴清热，服后神识已清，略能进粥。", ["数", "芤"]], "13792": ["其他", "原文未载具体脉象，仅言“及诊其脉，许以可生”，强调病虽恶而未经误药，脉象当有胃气可凭。案中痰嗽夜热、自汗不寐、左胁刺痛、肌削不饥，属阴虚痰热内恋，故孟英以固本加龟板、鳖甲、苁蓉、知、柏等育阴清痰而效。脉象虽未明言，然从“可生”之断，可知脉未至败绝，胃气尚存。", []], "13793": ["病机", "原文未出脉名，但孟英“按其脉”而断为“肝强脾弱，木土相凌”。晨泄有年、泻后腹反舒畅、服四神附桂泻必加，正是肝木乘脾、脾虚湿滞之机。脉当见弦而兼濡弱，故以白术、苡仁、黄连、楝实、桂枝、茯苓、木瓜、芍药等扶脾抑肝，数帖即安。", []], "13794": ["病机", "原文未载脉象，孟英“脉之曰：气分偏虚，痰饮阻其清阳之旋运”。患者痰多胸满、连年发痫，乃气虚痰阻、清阳不升。脉当见虚滑或弦滑，故用六君去甘草加黄耆、桂枝、薤白、蒌仁，法天之健以运大气，使痰饮化而清阳展。", []], "13795": ["误治", "原文未出脉象，然戚媪霍乱转筋后倦卧气少，朱某误认寒证欲投附子理中，孟英至而切脉，断为“高年之体，元气随泻而泄，固当补者，第余暑未清”。脉当见虚软或濡弱，故先以蚕矢汤清暑，继以参、术、附、桂等补元气，非纯寒可温。", []], "13796": ["病机", "脉微弱如无，伴耳聋目陷、汗出肢冷、音哑肌削，乃霍乱吐泻后气阴两脱、微阳欲绝之危候。误服苦寒更伤中阳，故脉微欲绝。孟英先浓煎高丽参汤接续元气，继以参、术、附、桂、干姜等回阳救逆，一剂证减，正是脉证相合。", ["微", "弱"]], "13797": ["病机", "脉芤而稍有歇止，孟英断为“芤者，暑也；歇止者，痰湿阻气机之流行也”。芤主暑热伤津，歇止主痰湿壅遏、气血流行不畅。体丰年迈患疟，暑湿夹痰盘踞，故大忌温补。后以桃仁承气汤加西洋参等攻去其痰，使邪无依附而病自去。", ["芤", "结"]], "13798": ["病机", "脉虚大，伴吐血、肌肤枯涩、口渴，孟英断为“气分之阴亏也”。虚大之脉主气阴两虚、虚阳外浮，非实热可攻，亦非温补所宜。故以参、耆、二冬、知母、百合、萎蕤、石斛等益气养阴，使阴复气充而血自止，投之而愈。", ["虚", "大"]], "13799": ["病机", "脉弦而细、尺中甚数，疟作于子夜、口干嗜饮、两发形消，孟英断为“足少阴热疟”。弦细为阴亏脉道不充，尺数主少阴伏热，故以元参、生地、知母、丹皮、天冬、龟板等滋阴清热，一剂疟止。若误温补提表，则阴愈伤而热愈炽。", ["弦", "细", "数"]], "13800": ["病机", "原文述误进首乌、鳖甲等滋腻药后\"脉伏胸痞\"，伏为邪闭气机、清阳不司旋运之象，非阳气外脱；\"脉散以塞责\"指包某疏生脉散敷衍，散非真散脉，乃气机闭滞、痰饮阻隧络所致。故孟英断为\"非脱象也，补药不可进\"，主痰饮闭滞、清阳不运之病机，与胸痞、呃忒、自汗、颧赤、便泄并见。", ["伏", "散"]], "13801": ["病机", "左脉细数，细为阴亏、数为伏火内扰；右脉弦滑，弦主肝火、滑主痰热壅盛。合观骨瘦肌热、韧痰阻咽、红肿白腐、龈舌皆糜、汛事非期而至，正合\"阴亏之体，伏火之病，失于清降，扰及于营\"，故以犀角地黄清营调血，白虎加洋参泻燎原之火。", ["细", "数", "弦", "滑"]], "13802": ["病机", "屡经柴葛香薷散之、枳朴槟榔泻之，致自汗不收、肢背极冷、奄奄一息，而\"脉微无神\"。微为阳气衰微、无神则根本欲败，故孟英断为\"禀赋素亏，阳气欲脱，此必误认表证使然\"，主阳脱之病机，与自汗、肢冷、息微相应，治以救逆汤加参耆回阳固脱。", ["微"]], "13803": ["其他", "原文仅言\"孟英切其脉曰：非伤风也\"，未出具体脉名，故脉象要素从缺。久患痰嗽而诸药勿瘳，孟英断非外感，从眉批\"其人必阴虚肺燥之质\"及所用北沙参、熟地、百合、麦冬等甘润之品推之，其脉当非浮紧表象，主旨在于辨非伤风、明阴虚肺燥之体质，故归其他。", []], "13804": ["病机", "先清解升浮之热，俟\"邪归于府，脉来弦滑而实\"，弦主邪实、滑主热痰、实为府实可攻之凭，故径用承气下之，下黑矢后大热大汗大渴，乃\"府垢行而经热始显\"。此脉为邪已入府、燥实内结之病机，与腹证虽不坚满而脉实相应，孟英坚主攻下。", ["弦", "滑", "实"]], "13805": ["病机", "前案王叟痰嗽气喘、囊缩便秘、心摇摇不能把握，孟英断为\"根蒂欲脱\"；后案邵可亭面浮微喘、茎囊渐肿、痰黄带血，\"脉形弦滑\"。弦主饮邪、滑主痰热，与口涎自流、腿肿至踵、喘逆欲死并见，示痰饮挟热壅肺、水气太过之病机，非下部虚寒，故温补纳气反剧。", ["弦", "滑"]], "13806": ["病机", "娩后发热，误服生化汤热益炽而发赤疹，\"脉弦滑而数\"，面赤热燥、胸闷善悲、肢肿而疼、白泡丛生、便闭旬日。弦滑主痰热壅盛、数主热毒炽烈，合为胎前伏暑蕴毒、产后误温助虐之病机，故犀角地黄犹恐不胜，加洋参、滑石、银花等清解蕴毒。", ["弦", "滑", "数"]], "13807": ["病机", "吐血盈碗而\"右关洪滑\"，右关属脾胃，洪为阳明热盛、滑为热壅血溢，合自汗口渴、稍动即血上溢，正是胃火燔灼、迫血妄行之病机，非虚脱之候。故孟英力任\"如脱惟我是问\"，用白虎汤加洋参、大黄炭清胃泻火，一剂霍然。", ["洪", "滑"]], "13808": ["病机", "脉滑数而右歇左促，肝部间有雀啄、气口兼解索，是湿热误补、充斥三焦、气机阻塞之象。滑数主湿热痰火，歇促为气机壅滞、脉道不利；雀啄、解索乃胃气将败之危兆。面如薰黄、头汗、呼吸粗促、便溺浑赤极臭、心下坚硬拒按，皆湿热痰饮壅闭、邪正混淆之候，故脉不主虚而主壅闭。", ["滑", "数", "促", "雀啄"]], "13809": ["病机", "原文未识脉名，孟英径断为厥阴为病，不可徒治太阳。少腹酸坠、溲频数而疼，似太阳膀胱之症，然通利升提温补备试无效，反致不食不寐、大解不行、口渴不敢饮、闻声惊悸，显系厥阴郁热、肝火扰心。故先咸苦泄热、续甘润滋阴，不犯通渗而愈，示脉症合参当求病本。", []], "13810": ["其他", "此段无脉象描述，乃泛论审证用药之要。指出小病脏气自有抗病之力，疑难危症若寒热虚实认错、广延多医遇药即投，必致气绝人亡。归咎于后人学识未精、审证不确，主张博览医案、参察脉理、一思百虑。故非论某脉主某病，而是强调脉理参悟在临证中的关键作用。", []], "13811": ["病机", "脉弦滑右甚，弦主肝胆气郁，滑主痰食内滞，右甚则病在气分脾胃。新产三朝浑身麻冷、壮热大渴、汗出不解、舌绛无津、苔燥黄、腹痛拒按、恶露仍行，是胎前吸受风温兼挟痰食内滞。虽血去阴伤，而病不在营，故脉不虚细而弦滑，亟宜撤热安营，不可破血养阴。", ["弦", "滑"]], "13812": ["病机", "脉弦细而涩，弦为肝胆火炎，细为真阴不足，涩为血少气滞、脉道不利。患者年未冠体弱，夜梦如魔如惊、肢摇目眩、醒后纳食如常而月一二发，正是真阴亏虚、肝胆火炎、神魂不宁之候。脉弦细涩与阴虚火炎相应，故服神犀丹清火，继以滋阴潜阳竟刈其根。", ["弦", "细", "涩"]], "13813": ["病机", "右寸溢、关尺滑而微数，左弦带滑，是痰阻阳明、经气不能流通输布之象。娩后自乳而月事仍行，血本有余；痰阻络痹则乳少汛愆、右胁筋绊作疼、嗽痰带血。滑数主痰热，弦主络痹，寸溢为气逆不降。面赤足冷、汗出、舌赤、溲短热，皆痰热内阻、营卫不通之候，非虚损也。", ["溢", "滑", "数", "弦"]], "13814": ["病机", "脉弦缓而涩，弦主气机郁滞，缓为湿热未清，涩则病渐入血、营卫不通。足疮愈后便血、腰背疼胀，医投温补致寒热不食，皆补药乱投、湿热不清、气机愈窒所致。脉不虚而弦缓涩，正合气郁湿滞入血之机，故断为药病，治当疏通气机、清化湿热，非脾肾两补所宜。", ["弦", "缓", "涩"]], "13815": ["病机", "脉大微弦，大为劳倦气虚、虚阳外浮，微弦为土虚木乘、中气不足。久患寒热、精遗自汗、能食神疲、肌肉渐瘦，是劳损中虚、阴阳不调、卫外不固之候。脉大而非实大，故予黄耆建中加参归龙牡，补中益气、调和营卫、收敛固涩而瘥，示大脉当辨虚实。", ["大", "弦"]], "13816": ["病机", "脉至滑数，滑主痰湿，数主热，结合睛赤口干，为热结膀胱、气不化达之候。然原文未及虚微之象，故病机以实热为主，与小便不通相应。", ["滑", "数"]], "13817": ["病机", "脉甚滑数，滑主痰湿，数主热，结合五心热、黑苔不退、口苦而渴，为热毒逗留阳明之络，陷入冲脉。冲隶阳明，故脉滑数应之。", ["滑", "数"]], "13818": ["病机", "脉数舌绛，数主热，舌绛为热入营血之征。疟疾寒少热多、呕渴痞闷，乃暑湿之疟，暑热内盛故脉数舌绛。", ["数"]], "13819": ["病机", "脉细数而芤，细主阴亏，数主热，芤主血虚。壮热汗多大渴，暑邪深入而阴分久亏，故脉细数而芤，为热盛伤阴之象。", ["细", "数", "芤"]], "13820": ["病机", "脉数而右更滑大搏指，数主热，滑主痰湿，大主邪盛。胸闷溲赤渴、苔垢腻，为暑湿痰热壅阻气分，右脉滑大搏指尤显邪实。", ["数", "滑", "大"]], "13821": ["病机", "脉来洪大滑数，洪大主热盛，滑数主痰热。新娩后微寒壮热、小溲全无、神烦大渴，为暑热内炽，故脉洪大滑数。", ["洪", "大", "滑", "数"]], "13822": ["病机", "脉数舌绛，面赤睛红，溺如沸汤，渴同奔骥，少腹拒按，为热毒内蕴，气机壅滞。数脉主热，舌绛为热入营血之征。", ["数"]], "13823": ["病机", "两尺空数，左关弦寸溢，右寸关滑驶，数主热，弦主气滞，滑主痰湿。真阴素亏，腹有聚气，吸受暑热，故脉数弦滑，忌升提。", ["数", "弦", "滑"]], "13824": ["病机", "脉洪数而芤，为暑热炽盛、气分热壅而阴津已伤之象。洪数主热，芤主阴血不足，故见苔黑面红、胸间拒按、便如胶漆、谵妄耳聋等热陷营血、阴液耗损之症。经清解后脉转柔缓，是邪退正复、胃气渐和之征，故以甘凉养液收功。", ["洪", "数", "芤", "缓"]], "13825": ["病机", "脉虚弦软数，为营阴素亏、八脉交虚之候。虚软主阴血不足，弦数主虚阳内扰，故见神疲自汗、不食不眠、泛泛欲呕、时时欲晕、肢麻且软、气欲上冲等症。此非外感寒热，乃阳维阴维为病，故不可作疟治，当以龟板、鹿角霜等填补八脉、壮水和肝。", ["虚", "弦", "软", "数"]], "13826": ["病机", "脉伏无溺，为伏暑内闭、热深厥深之象。暑热内伏，气机闭塞，故脉伏不见；热灼津伤，故无溺而口渴汗多；热郁于内，故腹痛苔黄、肢冷音飒。此非寒证，乃热邪深伏、阳气不能外达，故取西瓜汁及白虎加芩连等清透伏暑，复杯即安。", ["伏"]], "13827": ["病机", "脉极弦驶，为肝阳内炽、暑热外侵之象。弦主肝阳，驶数主热盛，故见头疼如劈、自汗息微、溺血如注等症。肝阳化风上扰，暑热迫血妄行，故以犀角、龙荟丸清肝泻火、凉血止血，继以清肺胃风阳而愈。", ["弦", "数", "驶"]], "13828": ["病机", "脉右甚滑数，为宿食恋膈、痰热内蕴之象。滑主痰食，数主热，右脉甚则病在气分中焦，故见口渴苔黄、胸下坚硬而痛。吐泻虽多，然宿食未去，非寒证也，故揭去回阳膏，以菖蒲、枳实、黄连等消食化痰清热，一剂霍然。", ["滑", "数"]], "13829": ["病机", "脉弦细以数，按之不鼓，为阴血亏虚、肝阳上扰之象。弦细主阴血不足，数主虚热，按之不鼓则非实邪，故见腹中聚气上冲、气促心摇、汗多眩晕、左胁震跃、渴饮无眠、骨瘦如豺。此久疟伤阴，肝阳化风，非疟邪未透，故不可再截疟，当养阴柔肝。", ["弦", "细", "数"]], "13830": ["病机", "脉来弦数而滑，为阴虚木旺、风阳煽动、营液旁溢之象。弦数主肝阳有余，滑主营液偏渗，故见腹坠腰疼、溲少口干、面红烦躁、滞下赤白而无粪色。此非肠中痢疾，乃冲任血液为风阳所煽而从大肠而出，故通补温凉皆不应，当从奇经论治。", ["弦", "数", "滑"]], "13831": ["病机", "脉虚软以数，为心火外浮、阴分素亏之象。虚软主正气不足，数主虚火浮动，故见时时出汗、不饥溺少、舌绛口干、神情恍惚、懒语音低。此非热邪内陷心包之实证，乃心阳过扰、火动神浮之虚证，法宜坚之使凝，不可与温暑逆传混淆施治。", ["虚", "软", "数"]], "13832": ["病机", "脉弦细沉数，舌绛口干，溺少而热，肿处赤痛，显系阴虚肝热，郁火无从宣泄。火郁则气胀，气胀则津枯，故便溏腹胀、肠鸣时痛、饮食日减。前医误作寒湿，投温燥则如火益热。脉细非寒湿之细，乃津枯之细；弦为肝郁，数为郁热，合而断为郁火伤津之候。", ["弦", "细", "数"]], "13833": ["病机", "左弦而数，右大不空，口苦不饥，苔黄无溺，此非虚脱之证。弦数主肝热，右大不空为邪实，故曰非虚。胎前患泻，产后泻如漏水，恶露不行，乃热邪内迫，非脾肾虚寒。参汤沾唇则助热，故以白头翁合伏龙肝汤丸清解热邪而愈。", ["弦", "数", "大"]], "13834": ["病机", "脉弦细以软，苔薄白，口不渴，痰多且韧，溺赤不饥，喉偏左痛下及乳旁，神疲欲卧，动即凛寒。弦细软为肝郁阴亏，暑湿内伏，非寒湿也。阴素亏复伤劳倦，故脉软细；肝郁不舒则弦。清暑益气、藿香正气皆温燥，误投则助暑湿，故以轻清之品透解。", ["弦", "细", "软"]], "13835": ["病机", "脉弦软不调，尺中虚细，苔腻垢黄，脘闷便溏，溺短不饥不眠，气短音低。弦软不调为痰热结于上焦，尺虚细为房劳伤于下焦。痰热有形之结未开，阴液久耗，故旷日相持，神气消索。治以小陷胸加清化痰热、滋养肝肾，结粪下而胸舒。", ["弦", "软", "虚", "细"]], "13836": ["病机", "脉弦滑而软，脘痛吐水数缶，吐后能食面肉而不能吃饭，此中虚停饮也。弦为饮，滑为痰，软为中虚。饮停中脘，故吐水；吐后饮减，故能食。治以六君去甘草加桂枝、厚朴、牵牛，积饮下而痛休吐止。中气素虚者不可专用香散，故后以附子、白芍、薏仁温补而愈。", ["弦", "滑", "软"]], "13837": ["病机", "左关尺弦数无伦，形消舌赤，彻夜无眠，腰腹左痛时作，带下如注。弦数为肝阳极炽，关尺独甚，肾阴大亏，营液耗夺，八脉交虚。前医误作真火无权，频投附、桂，如火益热，痛无停晷。治以龟板、乌鲗、苁蓉、枸杞等滋填肝肾，一剂知，数剂已。", ["弦", "数"]], "13838": ["病机", "左弦涩不调，右兼软滑，呃时有微甚而欲呃不爽，喷嚏久不作。弦涩为肝气郁结，欲升不能升；软滑为痰阻于肺，欲降不能降。气郁痰阻，升降失司，故呃忒不休。补摄之品反增窒塞，故以柴胡、枳壳、薤白、蒌仁等升降气机、化痰开郁，复杯而减。", ["弦", "涩", "软", "滑"]], "13839": ["病机", "脉形涩数不调，神呆静卧，倦于语言，溺少苔黄，时时面赤，不食不便不渴不眠。涩数不调为卫分无形之邪失于清解，补中益气实卫锢邪，承气仅下肠胃有形之物，养阴又增窒滞，枢机日钝，故神识如呆。此坏证非攻补难施，乃卫气未清，当先透解。", ["涩", "数"]], "13840": ["病机", "脉至弦缓而不洪数，说明内风虽升而热象不著。真阴素亏、半产劳瘁致阴虚，阴虚则生痰，痰滞机缄，风痰上扰故头疼、筋掣、不语；二便不行、不食唇焦、苔黑边白皆阴虚痰滞之征。弦主风、主肝，缓主湿滞，弦缓并见正是风痰内阻而非热邪内陷，故宜清宣，勿投寒腻。", ["弦", "缓"]], "13841": ["病机", "脉软且弦，软为虚、弦为肝风，正合「本虚标实」之论。舌稍出齿、苔转黄、小溲较畅为痰滞渐化，而羞明头痛显属风升，咽膈不舒乃痰凝气阻。脉软示正气不足，弦示风痰未平，虚而兼实，故不可峻攻，法先开泄以疏风豁痰。", ["软", "弦"]], "13842": ["病机", "脉至虚弦，右兼微弱，虚弦为阴亏风动，微弱为气血不足，与「本虚标实」相应。神识稍清、小溲渐行、头疼似减是标实渐退，而语未出声、苔犹灰滞示本虚未复。正虚为主，故难授峻攻，宜开养兼参，扶正与疏化并行。", ["虚", "弦", "微", "弱"]], "13843": ["病机", "脉软以迟，软为虚、迟为寒，且毫不作渴，明非热证。舌淡红、苔灰腻、不食不便，皆阳虚痰凝、温运无力之象。前诊风升痰阻，今脉转软迟，示病机由风动转为虚寒痰滞，故宜参温煦以豁凝痰，温通阳气则痰自化。", ["软", "迟"]], "13844": ["病机", "脉仍弦软，弦为肝火未平，软为正气尚虚。苔渐化、舌渐出、略思粥食示胃气渐动、痰浊渐退；而头痛未蠲、久不更衣，乃肝郁气滞、府气不通。虚中夹滞，不耐峻下，故徐为疏瀹，法主温通，以温运助传导。", ["弦", "软"]], "13845": ["病机", "左脉微迟，微为阳虚、迟为血少，左脉候血，故知血虚。连投温养后神清语出、苔退，是阳气渐复；头犹左痛、大解不行，乃血虚风未息、肠府失润。法当补血，血充则风自息，府气亦自行，体现治本之意。", ["微", "迟"]], "13846": ["病机", "原文未识脉名，仅言「脉已渐起」，示正气渐复之象。然浊未下行、尚未更衣、语犹错乱、时或头痛、寐则梦多，说明痰浊内阻、肝郁未清、神明未安。脉起而症未除，故以濡导下行先通府气，使浊降而神清。", []], "13847": ["病机", "脉软而迟，软为虚、迟为寒，合「阴分久亏」「肝郁神虚」之论。虽已知饥，然未得大解、时欲上冲，乃肝无宣泄、阴亏不能濡润。素伤思虑致肝郁神虚，虚寒之体岂容妄下，故法当养正，通镇相参，扶正兼镇肝降逆。", ["软", "迟"]], "13848": ["病机", "脉弱口干，面无华色，乃积虚未复之象。脉弱主气血不足，口干因津液未充，面乏华色为营血不荣。神气渐振、安谷耳鸣，示胃气渐苏而肾虚未复。此虚象明显，故治以平补，不可峻补。", ["弱"]], "13849": ["病机", "脉弦洪疾驶，重按细软，乃高年气血两亏，郁火内燔之候。弦洪疾驶为郁火亢盛之象，重按细软则示根本虚衰。火郁于上则头面赤肿磊痒，扰及心神则烦燥不眠。不可从疡科治，当养血清火。", ["弦", "洪", "疾", "软"]], "13850": ["病机", "脉虚洪豁大而舌色干绛，溲赤点滴，证属阴亏。虚洪豁大乃阴亏阳浮之象，舌干绛为津液枯涸。阴亏于下，痰嗽气喘，便难溲赤，忌投刚燥，当滋阴潜阳。", ["虚", "洪", "豁", "大"]], "13851": ["病机", "左关尺忽见浮弦而空，乃根蒂空虚，肾水泛溢成痰，浮阳冲逆为嗽之兆。浮弦而空示下元虚衰，阳不潜藏。此似伤风而实非伤风，误作外感解散则危。", ["浮", "弦", "空"]], "13852": ["预后", "右寸关空大，有静中一跃之形，乃元气大伤之候。空大为虚，静中一跃为胃气欲绝之兆。虽神气安静，苔黄腻，胃略知饥，然脉象不佳，恐有骤变，果越日而亡。", ["空", "大"]], "13853": ["预后", "左寸细数无伦，尺中微细如丝，乃肾阴素伤，心阳过扰，真水下竭，真火将灺。细数无伦为心阳浮越，微细如丝为肾阴枯竭。纵有神丹，不能接续，故曰不治。", ["细", "数", "微"]], "13854": ["病机", "右寸关虽滑，而别部虚弦软数，指下无情，乃郁痰证，谋虑伤肝，营阴久耗，风阳独炽，烁液成痰。滑为痰，虚弦软数为阴亏阳亢。养液开痰，暂作缓兵之计。", ["滑", "虚", "弦", "软"]], "13855": ["病机", "脉甚弦滑，厥前必先作胀，更衣得泻始舒，巅顶时疼，乃肝风挟痰为患。弦主肝风，滑主痰，痰在络中，故不见吐。胎前病痰证居半，徒知产后为虚，则锢痰愈深。", ["弦", "滑"]], "13856": ["病机", "脉来虚弦软滑，虚为根蒂不足，弦主痰饮内停，软滑示痰热胶阻。尺中小数，为下元虚而虚热不潜。合颧红微汗、吸气不能至腹、溺短便艰，正是「根蒂虚于下，痰热阻于上」。前医温补反助痰热，故喘逆濒危。此脉不主纯实亦不主纯虚，乃上实下虚之候。", ["虚", "弦", "软", "滑"]], "13857": ["病机", "脉至虚弦细弱，虚细弱为阴血亏乏，弦为阳不能潜、肝风内动。原文谓「八脉皆空，阳不能潜，游行于上」，故见嗽、衄、善怒不眠、肢掣汗出等错杂之症。此非外感表邪，亦非瘀血实滞，乃产后血去、奇经空虚、风阳浮越之病机，故表散攻瘀毫不可犯。", ["虚", "弦", "细", "弱"]], "13858": ["病机", "脉弦软而微数，弦为肝木不柔，软为营阴素亏，微数示虚热内扰。原文断为「营素亏」「阳维为病亦能作寒热」，非疟邪往来。八脉隶于肝肾，营亏则奇经失养，寒热间作、腹中攻痛皆由此起。故治法温肾凉肝、濡养奇经，而非截疟发表。", ["弦", "软", "数"]], "13859": ["病机", "左部弦数，右手沉滑。弦数为肝郁化火，沉滑为痰浊内壅。原文断「郁痰证误补致剧」，因广服补剂，痰火胶结，故不饥不寐、气升面赤、痰多易汗、胸次如舂、咽有炙脔。此脉不主虚损，乃郁痰误补、气火痰交阻之实候，与蓐损大虚迥别。", ["弦", "数", "沉", "滑"]], "13860": ["病机", "脉弦软且滑，弦主肝气不舒，软滑主痰浊凝聚。原文辨为「非疟母也」，乃疟后痰气留滞左胁，聚气窜痛。疟母多属瘀血结聚，脉当沉涩；此脉软滑，是痰而非瘀，故用旋覆、海石、蛤壳、海䖳等消痰软坚之品，十余剂而根除。", ["弦", "软", "滑"]], "13861": ["病机", "脉来弦软而寸数，弦软为温邪挟痰、气机不畅，寸数主热壅上焦。合舌绛苔黑、神昏谵渴、胸腹拒按，原文断为「双传证」，即顺传阳明与逆传心营并见。脉数在寸，示邪热上扰神明；弦软示痰热互结。故当双解，凉膈散加犀角、菖蒲、元参下之。", ["弦", "软", "数"]], "13862": ["病机", "脉弦细数，弦为肝郁气滞，细为阴血亏耗，数为虚热内蒸。原文述腹胀善呕、经断、骨立形消，诸医误作劳损温补，病乃日甚。此脉示气郁化火、阴液被灼，非纯虚可补。弦细数并见，是郁热伤阴之候，温补反助其胀，故日甚。", ["弦", "细", "数"]], "13863": ["病机", "脉弦缓而大，弦主痰火内郁，缓为湿浊留滞，大为邪实壅盛，非虚劳之脉。原文断「痰火为患耳，误投补药矣」。形消肌削、暮热从骨髓出、痰绿臭、便坚溺赤，皆痰火熏灼之象；畏冷异常、动即气逆，是痰阻气机、阳不外达，非真寒。故以苇茎汤合雪羹清化痰火。", ["弦", "缓", "大"]], "13864": ["病机", "脉缓而滑，缓非虚缓，乃久坐气行迟滞之象；滑主痰凝久伏。患者跛疾久坐，气机不畅，痰浊内伏，故动则喘促。脉缓而滑正是痰凝气滞之征，非虚象，故频补不应。吐痰后愈，印证痰伏为病本。", ["缓", "滑"]], "13865": ["病机", "左寸脉伏如无，非心散，乃劳心兼痰火郁遏，阳气不达所致。火升面赤、不寐胁鸣，为惊骇激动肝胆之阳勃然升越，非本病。脉伏耳点明痰火郁闭、脉道不利之病机，故以清心化痰降火取效。", ["伏"]], "13866": ["主病", "脉洪数而滑，舌绛口干，疟寒少热多，时时自汗，显系暑热内炽、气分热盛之象。洪为热盛，数为热急，滑主暑湿痰热。年高虑脱，然脉不虚，故不可进补，当以清解法逐暑热，暑去则疟自止。", ["洪", "数", "滑"]], "13867": ["病机", "脉弦细而弱，气短不足以息，舌赤无苔，营血大亏之候。弦为肝阴不足，细弱为血虚气衰。晡热、心悸、目盲、腰酸腿软，皆精血亏虚、不能荣养之症。此非暑治，当以滋补营血为要，故用参、地、龟板等填补。", ["弦", "细", "弱"]], "13868": ["病机", "脉数而洪，壮热神昏，二便秘涩，呕吐不休，乃暑热炽盛、内扰神明、下灼津液之病机。前医误用姜、桂温燥，助热伤胎，故腰疼欲堕。脉数洪为实热之征，故以栀、芩、连、楝等清解暑热，佐苏叶以安胎。", ["数", "洪"]], "13869": ["病机", "脉亦弦软，按之甚软，乃惊恐气结不行所致。弦为气郁，软为气结而脉道不利。胁痛偏右、便秘神瞀、身面发黄，皆气机壅滞、升降失司之症。此非湿热，故前治罔效。以宣通气机、清化痰热为法，气行则诸症自解。", ["弦", "软"]], "13870": ["病机", "脉迟软，舌润不渴，小溲甚多，便秘而粪黑坚如弹丸，乃久患痹证、坐卧不行、健运迂迟所致。迟软为气虚推动无力，非热结阴亏。中气不足，则便溺失常。法宜补气，俾液濡布，故用大剂参、术，佐旋覆、鸡膍胵以旋转中枢、宣通大肠。", ["迟", "软"]], "13871": ["病机", "脉迟软而舌润不渴、小溲多，显非燥热内结。迟为阳气不运，软为气馁无力，合之痹证久坐、健运迂迟，知便秘由中气不足、液不濡布所致，非凉润可通。故以参术补气、旋覆旋转中枢，气足则便溺如常。", ["迟", "软"]], "13872": ["病机", "脉数溺少，乃暑热内传营分，气分未廓，敷布无权。热灼营阴则神昏谵语、舌绛耳聋；气不化津则渴饮不饥、频吐白沫；水不下行则溺少，旁溢为汗。初起误表散风寒，传营又未营卫两解，徒走膻中，故牛黄紫雪无功。脉数主热，溺少示气化失司，病机在暑热内陷、气营两燔。", ["数"]], "13873": ["病机", "脉软神疲，内湿素盛，兼吸客邪，湿困中焦则腹胀便溏、脘闷不饥、口流涎沫；湿注下焦则腿酸溺少。脉软主湿，神疲为湿困。其子疟发脉数而弦，数主热，弦主疟，寒微热甚，耳聋舌绛溺赤痰多，乃暑热夹痰，少阳阳明同病。两案脉象虽异，皆不离湿与热之病机。", ["软", "数", "弦"]], "13874": ["病机", "脉微弱如无，乃虚风内动，阳浮欲脱。四肢麻木、头晕汗淋、不能言、目垂遗溺、浑身肤冷，皆阳气式微、虚风上扰、卫外不固之候。脉微为阳衰，弱为气弱，如无则阳气欲脱。故急以参、芪、附、桂回阳固脱，龙、牡潜镇浮阳，木瓜舒筋，茯苓宁心，恐缓则药不能追。", ["微", "弱"]], "13875": ["病机", "脉虚弦而软，滞下赤白，腹不甚痛而奔迫异常，能食溺长，此非寻常湿热痢。虚弦为肝脾不和，软为气弱，乃中气不足、肝木乘脾，传导失职。故不可按常痢清利，以三奇散加归、芎调气和血，送香连丸清余热，标本兼顾而愈。", ["虚", "弦", "软"]], "13876": ["病机", "脉虚弦而弱，年高便秘，时欲弩挣，汗出头晕，是虚风秘结。虚为气阴不足，弦为风动，弱为血少。肝血亏虚，风阳内扰，肠道失润，故便难而弩挣汗出。前医误作肝气滞，投麻仁丸等，更伤津液。治以人参、苁蓉、当归、枸杞等益气养血润肠，佐楝实、白芍平肝熄风，方合病机。", ["虚", "弦", "弱"]], "13877": ["病机", "脉虚软而涩，根蒂素亏，经停乳少，血之不足；泛泛欲呕，肝乘于胃；率投滋腻，窒滞不行；略受风邪，无从解散，气机痹塞，九窍不和。虚软为气血亏，涩为血少气滞。故先开上宣中，继滋下焦，层次分明。", ["虚", "软", "涩"]], "13878": ["病机", "脉缓大，苔微黄，腿酸寝汗，溺赤脘疼，食减口干，乃劳力火升，内兼湿热。缓大为湿热壅盛，非虚损之候。任氏女脉软数而长，带下，亦湿火下注。软数主湿热，长为有余。两案皆以猪肚丸清湿火取效，证明脉不主虚，不可误补。", ["缓", "大", "软", "数"]], "13879": ["病机", "脉至弦梗，舌赤无津，杳不知饥，胁腹时胀，乃风阳内炽，津液耗伤。弦为肝旺，梗为气结，细为阴亏。香燥忌投，法宜濡润，恐阴涸。后脉梗虽和，极其弦细，是阴液未复，木火失涵，故加人参、龙眼肉，少佐黄连，滋水涵木而愈。", ["弦", "梗", "细"]], "13880": ["病机", "脉滑数，滑主痰，数主热，为暑热内伏、痰热交阻之象。原文谓“暑伏肺经，始为痰嗽”，温纳妄投致“胃枢塞滞，郁遏成疟”，暑热下迫大肠则痢。脉滑数正合暑热痰郁之病机，故口渴苔黄、溺似沸汤，治当清暑，源清则流洁。", ["滑", "数"]], "13881": ["病机", "脉滑而数，滑主痰，数主热，为燥火伏于肺胃之征。原文谓“燥火伏于肺胃”，故面赤能餐、汗多畏热、呕渴苔黄；恶露流通则血分无病，病在气分肺胃。脉滑数紧扣燥火痰热之机，法宜清肃上焦，虽产后亦不禁凉润。", ["滑", "数"]], "13882": ["病机", "脉虚弦缓大，虚为气弱，弦主木旺，缓大为中气不足、虚风内动。原文谓“固虚也，然非滋阴药所宜”，气短懒言、动即自汗，皆气虚阳浮之候；滋补填阴反兼便泄，更伤中阳。脉虚弦缓大正示气营两虚、虚风上扰，故用参耆桂苓龙牡以益气潜阳。", ["虚", "弦", "缓", "大"]], "13883": ["病机", "脉左弦数上溢，尺中滑大按之细弱，右手软滑。弦数上溢为肝阳上亢、郁热上冲，滑大为痰热内蕴，细弱软滑则阴血亏虚、痰湿内滞。原文见胁腹聚块上窜、唇白口糜、舌绛无津、暮热无眠，正合阴虚阳浮、痰热互结之病机，故补法无功。", ["弦", "数", "滑", "细"]], "13884": ["病机", "脉滑数而洪，滑主痰，数主热，洪为热盛气分。原文断为“冬温也”，面赤音低、大渴溺赤、鼻衄大流，皆肺胃热炽、迫血妄行之候；苔白不燥为“内有伏痰”，便泻如水为“肺热下大肠”。脉滑数洪正合冬温痰热壅肺之机，故以清解肺卫取效。", ["滑", "数", "洪"]], "13885": ["病机", "脉弦羍而虚滑，弦主肝郁气逆，虚滑为痰凝气滞。原文谓“素多怫郁，气滞痰凝”，用柴胡则肝气愈升，攻瘀则诛伐无过；气逆面青、牙关不开、胸次坚鞕如柈，皆痰气壅塞之候。脉弦缓不鼓亦示气郁痰阻、非纯实热，故以小陷胸合蠲饮化痰开结。", ["弦", "虚", "滑", "缓"]], "13886": ["病机", "右脉洪数，洪为阳明热盛，数主热，右脉候肺胃。原文见怀孕患嗽、鼻衄如喷、憎寒乍热、口渴头疼，乃寒外束而伏热蕴隆，肺胃热炽迫血上溢。脉洪数正合“伏热蕴隆”之机，故虽隆冬径投白虎汤合葱豉，解表清里而瘳。", ["洪", "数"]], "13887": ["病机", "脉虚数而弦，虚为真阴亏耗，数为燥热内伏，弦主痰郁气逆。原文谓“真阴素亏，痰多气郁”，初服温散则苔黑，投白虎则胸胁大疼，因枢机窒滞、气道未舒，阴液已伤非白虎所能任。脉虚数弦正示阴虚燥热、痰郁气滞之机，故以展气开痰、潜阳镇逆为治。", ["虚", "数", "弦"]], "13888": ["病机", "脉虚弦小数，虚为阴亏本质，弦为虚阳浮动之象，小数示阳扰不宁。患者多言不寐、面赤火升、汗出心摇，正是阴亏于下、虚阳上浮，将交春令肝木升发，故有鸢飞鱼跃之虞。脉证合参，病机为阴亏阳浮，非实火亢盛。", ["虚", "弦", "小", "数"]], "13889": ["预后", "两脉弦数，弦主肝郁风动，数主热，舌绛无津、汛断半年、破䐃脱肉，显系阴液枯涸、风火内炽。前医误作虚风，用参术桂附温补，致手足拘挛、日夜号痛、痰韧如石、皮肤燥裂，皆燥热伤阴之变。脉弦数而见形脱经断，故断为危候，不能过夏至。", ["弦", "数"]], "13890": ["病机", "右脉软滑而虚，为肺伤于燥、治节不行，津液被烁；左脉浮弦且数，乃温以辛甘，风阳内煽所致。患者痰嗽、胁跳、胸痒、汗出、便溏溲短，皆上下交虚、液亏风动之征。脉象示燥伤肺津、风阳内扰，非单纯痰嗽，故治先保液息风。", ["软", "滑", "虚", "弦"]], "13891": ["病机", "脉弦滑而数，弦主肝火，滑主痰，数主热。两腿疼肿、便溏不渴、溺热如沸，前医误作寒湿，用苍术、木瓜等温燥，其病日甚，筋掣欲厥。脉证合参，乃肝火挟伏痰为患，便泻为土受木乘，不渴因内有伏痰，故以清肝化痰取效。", ["弦", "滑", "数"]], "13892": ["病机", "脉弦细而滑，弦主郁，细主阴伤，滑主痰。坐卧不安、饥不能食、食则滞膈、善恐畏烦、面赤痰黄，乃七情怫郁、五火烁痰，误投补药致气机窒塞、升降失常。脉象示郁火挟痰，非虚证，故先清展气机，痰火去则眠食安。", ["弦", "细", "滑"]], "13893": ["病机", "左脉弦软，右虚大而滑。弦软为肝阴不足、虚风内动，虚大而滑为里气虽虚而伏痰内盛。患者神昏瘛疭、呓语溲红、时时呃逆、心下拒按、舌苔满黄，乃温邪内陷、气分未清、伏痰阻络。脉证示正虚邪陷、痰热内闭，故以扶正清心化痰并治。", ["弦", "软", "虚", "大"]], "13894": ["病机", "脉甚虚软，舌紫滑泽无苔，溲频数浓赤不禁，阴茎已缩，两手紫黯。此非真伤寒，乃心阳过扰、热伏厥阴，热邪内郁而阳气不达，故脉虚软、恶寒。虽平昔耽饮，设投燥剂则液涸，故以轻解透热、护阴为治，后伏热渐化。", ["虚", "软"]], "13895": ["病机", "两尺虚软，左寸关弦数，右兼浮滑。尺虚软为下焦阴亏，弦数为阴虚火炎，浮滑为痰火实于上焦。屡次堕胎、月事色淡、形瘦食少，前医大投温补，致五心如烙、面浮咳逆、痰壅碍眠。脉证示下虚上实、痰火壅盛，故治于虚处求实，清上滋下。", ["虚", "软", "弦", "数"]], "13896": ["病机", "脉弦软而数，弦主厥阴，软为热邪未至坚结，数则主热。结合发热呕吐、茎缩腹痛、苔黄腻，显系热邪内伏厥阴肝经，循经下扰则茎缩腹痛，犯胃则呕吐。孟英断为“热伏厥阴”，正合弦软数之脉。", ["弦", "软", "数"]], "13897": ["病机", "脉虚数而弦，虚数示营阴亏虚，弦主少阳邪客。娩后月余，营血本虚，邪乘虚入少阳，故间疟、头痛、善呕、乳少。孟英谓“营虚而邪客少阳”，脉象与症相符，治以和解兼养营。", ["虚", "数", "弦"]], "13898": ["病机", "脉虚软微数，虚软为营阴久亏，微数乃暑邪不甚重。虽患暑疟，但寒微热炽、汗多神惫，脉不洪滑，知邪轻而正虚。孟英谓“营阴久亏，不须重剂诛罚无辜”，故用清养轻剂。", ["虚", "软", "微", "数"]], "13899": ["病机", "脉滑数，右寸关更甚，滑主痰，数主热，右寸关候肺胃，痰热阻于上焦。舌淡白光滑似无苔，实有苔如膜，乃痰浊内闭。孟英断为“阴虚吸暑，兼以痰阻清阳”，初治失于开泄，故以轻清开上取效。", ["滑", "数"]], "13900": ["病机", "脉缓涩不调，缓非和缓，乃气机壅滞；涩为痰滞血行不畅。胸次坚而不柔、舌布干黄薄苔，皆痰滞未行、气机郁结之征。孟英斥遽投补剂之误，主以宣肺化痰，气行则脉自调。", ["缓", "涩"]], "13901": ["病机", "脉弦细软涩，重按如无，弦主肝郁，细软为虚，涩乃脉道不利。症见目张不阖、口开舌伸、筋瘛胸闷，孟英断为“情志郁结，怒木直升，痰亦随之，堵塞华盖”，非中暑虚脱，故宜宣肺行气。", ["弦", "细", "软", "涩"]], "13902": ["病机", "脉弦细软滑，弦细软为真阴亏于下，滑主痰热阻于上。耳鸣、食减痰多、舌苔灰黄厚腻三年，正合下虚上实之候。孟英谓“真阴亏于下，痰热阻于上”，治以滋阴化痰，标本兼顾。", ["弦", "细", "软", "滑"]], "13903": ["病机", "脉软滑而数，软为湿，滑为痰，数主暑热。盛暑患疟，热势烙手、无汗、神瞀、苔黄、便秘溺赤，乃暑湿挟痰交阻中焦，气机痹塞。孟英谓“暑湿挟痰𫐖轕于中，气机阻痹”，故以清宣开泄取效。", ["软", "滑", "数"]], "13904": ["病机", "脉滑数主痰热内蕴，弦疾乃肝郁化火、邪势鸱张。患者平素饮食不节，气滞多痰，时疟溺赤苔黄，脘闷不饥，显系痰热阻遏，疟邪未透。前医误投温补，致狂热尤甚，脉转弦疾而左尤坚搏，示邪热深入，肝火亢盛，故目不能张、畏闻声响，皆痰热上蒙清窍之征。", ["滑", "数", "弦", "疾"]], "13905": ["病机", "脉洪弦滑数，洪为暑热炽盛，弦主肝郁，滑数乃痰热内壅。症见壮热、舌紫肿苔厚腻黄、龈肿疼，卧则昏谵，坐起即清，正是湿热上熏、升降失常。前医误作斑疹、血室、虚脱，杂投温补滋腻，反助邪势。此脉此症，病属暑湿挟痰，肝肺胃同病，非虚脱也。", ["洪", "弦", "滑", "数"]], "13906": ["病机", "脉细而数，细为阴伤，数为热炽。患者清癯，疟后误用柴葛羌防，劫液助热，致壮热神疲、汗出不解、舌绛龈疼、齿缝血流，有下厥上竭之势。细数之脉，正示真阴耗损而邪热未清，肺未肃清，故宜轻剂清透，不可攻散滋培，以禀赋极弱，运化无权也。", ["细", "数"]], "13907": ["病机", "脉浮弦软数，尺中甚弱，浮弦为暑热扰于外，软数示真阴亏于内，尺弱乃肾阴素虚。年已花甲，久伤谋虑，吸受暑热，化疟未清，扰及中州，故吐泻交作、肢冷自汗、谵语。舌绛无液、稍有黄苔，吐酸甘苦辣、泻色酱热如火，皆伏热之据，非元虚也，温补则助热劫津。", ["浮", "弦", "软", "数"]], "13908": ["病机", "脉形滑数，滑主痰，数主热。年近古稀，新秋患感，前医热退即用滋养，致邪复热；又改厚朴姜枣，遂热壮神昏，舌心已黑，溲赤干呕，粥饮不入。滑数之脉，明示痰热内闭，非虚寒也。黑舌干呕，热灼津伤，故用清透痰热之剂，数帖霍然。", ["滑", "数"]], "13909": ["病机", "脉不浮而弦滑且数，按之愈甚，弦主暑热挟痰，滑数为痰热内盛。疟两旬，苔黄腻满布，大渴喜冷饮，溲赤臭痛，大解不行，皆暑热痰浊壅遏之征。前医温补杂投，致疟日甚、发日迟、补日峻、渴日增，脉证相参，确为暑热挟痰，非阳虚中寒，故清解取效。", ["弦", "滑", "数"]], "13910": ["病机", "脉弦洪而数，弦主肝火，洪数为暑热炽盛。疥疮虽外症，然形瘦臂疼，脉见弦洪数，显系肝经郁热、暑火内燔。妊妇患疥，误搽毒烈燥热之药，致壮热肤赤神昏、阴户疼肿、溲热如火、四肢拘挛，脉甚洪数，舌绛无苔，乃暑火证复为药毒助虐，故大剂清火解毒取效。", ["弦", "洪", "数"]], "13911": ["病机", "暑脉微弱，然兼数象，非虚也，乃暑热伤气、湿阻阳郁。高年泄泻发热、神思不清、自汗呕恶，脉微弱而数，正合暑湿内蕴。若误作脱而进参，则助热恋邪。又五弟妇脉弦滑而数，面赤不瞑，苔黄腻，胸下拒按，昏狂悲哭，乃痰热肝火为患，与暑湿异曲同工，皆实证非虚。", ["微", "弱", "弦", "滑"]], "13912": ["病机", "脉弦洪而数，弦主肝郁饮醇，洪数主暑热内炽。患者素善饮，积热于内，暑火外侵，又误服香窜燥烈之痧药，如火益热，致气冲咳嗽、血涌如泉。此脉示热盛动血，非单纯阴虚，故沈某遽补益剧。亟当清解客热，热退血止再议滋养。", ["弦", "洪", "数"]], "13913": ["预后", "脉虚弦而空软，虚弦为久病羸弱、肝木乘脾，空软乃胃气衰败、阴血亏耗之象。症见腹痛便泻、恶谷形消，土败木贼，故曰不可为。虽以参、芪、乌梅丸勉图，便坚食进，然脉之空软未复，预判春令木旺克土，终难起疴。", ["虚", "弦", "空", "软"]], "13914": ["病机", "脉弦数，弦为肝阳亢逆，数为热盛。娩后阴血骤虚，肝阳陡动，症见发狂、头痛睛红，胸腹舒、身不热，排除瘀血与实热。前医误作虚火温补，反助其狂。此脉示阴虚阳亢，故以三甲、二至、童溲等潜阳降火而愈。", ["弦", "数"]], "13915": ["病机", "脉弦涩，弦主肝郁气滞，涩主血行不畅。少腹坚胀、左胁聚气，溺赤便艰、口苦不饥，肢冷形瘦，皆肝郁化火、气血瘀滞之候。前医见面黄作暑湿攻补杂施，两月弗效。此脉明示非外因，乃肝郁耳，故用旋覆花汤合金铃子散、当归龙荟丸疏肝泻火而瘥。", ["弦", "涩"]], "13916": ["病机", "初起脉微弱为暑湿本象，今按之尚数，乃阴液已伤、暑热未清。症见痛痢不减、谷食不思、肌瘦如豺、口干舌绛、气短汗多，皆厥阴证胃液耗伤之候。脉未空数浮弦，说明阴液虽伤而胃气未绝，故亟予白头翁汤加养阴清热，若误温补酸收则危。", ["弱", "微", "数"]], "13917": ["病机", "脉象弦细无神，弦为肝郁，细为营阴亏虚，无神乃气血衰败之征。疮色黑陷、食减神疲、寒热时形、痛无停晷，皆营阴大亏、虚阳浮越之候。初无寒热红肿，非火毒可知；攻散劫津、温托壅气，致好肉剜成疮。此脉示虚损，故用引火下行、温洗及养血填精之剂。", ["弦", "细"]], "13918": ["病机", "脉洪且数，洪为暑热炽盛，数为热邪内迫。清癯阴亏之体，伏暑化疟，症见舌绛无苔、大渴多汗、寒微热甚、咳嗽兼呕。其兄脉亦洪数，体丰痰滞，但热无寒、汗多昏谵，曲糵素耽。此脉示伏暑痰热内蕴，故以清暑化痰为治，解赤粪而疟递轻。", ["洪", "数", "涩"]], "13919": ["病机", "脉则右大，右寸关候肺胃，大为热盛气壅之象。夏间嗽泻愈后，时发微热、寝汗如蒸、热甚于颈面、形瘦口干，皆肺热不清、阴液受灼之候。前医误作劳损，久服养阴，势必热锢深入而成损怯。此脉示肺热未清，故以芩、栀、桑叶等清透肺热，热退汗止。", ["大"]], "13920": ["病机", "脉来甚涩，涩主气血郁滞、热邪内伏。患者四肢发热、汗多形瘦、食减便溏，前医误补致热郁于内，气机不畅，故脉涩。涩而兼热象，说明热厥由误补壅遏，非虚寒之涩，故以芩、栀、连、柏清透郁热而愈。", ["涩"]], "13921": ["病机", "脉软脘胀，软为湿邪困阻、气机不舒之象。暑湿挟秽浊阻于募原，气机壅滞则脘胀，湿郁则脉软不任按。手紫面黄、便秘溺红、苔腻而渴，皆暑湿秽浊内蕴之征，故以菖、朴、橘、半芳化宣透，湿去则脉复。", ["软"]], "13922": ["预后", "左手弦洪涩数而上溢，右软滑大按之无神。弦洪数主木火亢盛，涩主郁滞，上溢为肝阳上僭；右软滑无神则胃气已败。高年滞下，七情郁结、木土相乘，又误投温补，酿成唇舌紫、痰血、咽膈阻塞之危候，脉证俱逆，故断药不可为。", ["弦", "洪", "涩", "数"]], "13923": ["病机", "脉弦数而驶，按胸下坚且痛，舌绛根苔黄滞。弦数主热，驶为热盛急迫，牢涩示府实坚结。战汗后瘀血下行，误投温补致汗收壮热、杳不知饥，热结胸府，阴伤而府犹实，故以陷胸合雪羹通降，下坚黑之矢而热缓。", ["弦", "数", "驶", "牢"]], "13924": ["预后", "脉微细欲绝而呼吸甚促，按心下坚且痛。微细为阴阳气血衰败，欲绝示胃气将竭；呼吸促为虚阳上浮。初治失于开泄，胸中痞结，津液尽从下脱，大泻黄水、肢痉音低、唇焦齿槁，攻补皆难，脉证相悖，故断疾不可为，翼日果殒。", ["微", "细"]], "13925": ["病机", "脉弦软，弦主饮邪内停、气机不畅，软为水饮浸渍、脉道不充。停饮则液不上布故口渴，内有停水故不喜饮；水凌火则寐即心掣，饮遏其流则得食痛加。舌上脱液虽属阴虚，亦由饮隔，故以芩、泽、橘、半、旋、蛤化饮，溲行得睡。", ["弦", "软"]], "13926": ["病机", "脉缓大而滑，缓为湿，大为热盛气壅，滑主痰涎内蕴。苔黄腻、脘下拒按，寒热大作、茎缩溲闭、气喘大汗，皆痰热湿浊壅阻气机之象，非虚寒内伤。故以菖、枳、旋、蒌、栀、豉、连、半涌吐痰涎，痰去则喘汗平、溲畅而愈。", ["缓", "大", "滑"]], "13927": ["病机", "脉软涩而不鼓指，右手尤甚，宛似虚寒，然舌紫苔黄腻口苦、眼鼻出火，乃真阴素亏而热伏于内。软涩不鼓为热郁气滞、脉道不利，非阳虚。故以栀、连、桑、菊、芩、斛清透伏热，热减则脉较和，溲赤便酱为伏热下行之征。", ["软", "涩"]], "13928": ["病机", "脉形滑数，滑主痰湿，数主热，结合发热、左胁疼、痰臭、苔黄舌绛、渴饮谵语、便秘溲赤，显系伏暑湿热酿痰，久积于左，热壅痰阻，故脉滑数。非内痈，乃湿热痰浊内蕴之证。", ["滑", "数"]], "13929": ["病机", "脉微弱而弦，微弱主中气虚弱，弦主寒湿内侵或饮邪。症见跗肿便溏、痰多食少、时欲呕吐、郑声，不渴无苔，小溲不赤，乃中虚寒湿为患，脾运失健，寒湿内盛，故脉微弱而弦。", ["微", "弱", "弦"]], "13930": ["病机", "脉虚软微数，左兼弦细，虚软为营分素亏，微数主伏热，弦细乃热阻隧络。症见少腹偏左作疼、发热自汗、眩冒谵语、呕渴不饥、耳聋烦躁，便溏溲热，舌本不赤略布黄苔，乃营亏伏热阻于隧络之病机。", ["虚", "软", "数", "细"]], "13931": ["病机", "初脉形涩滞，为伏暑晚发而本元极亏，涩主气机郁滞；继脉来软而且涩，软为虚，涩为滞；后脉转弦数，弦主热郁，数主热盛，乃浊热上熏。症见神昏、谵语、夜间热炽、腿凉头晕，皆伏暑化热、本元亏虚之病机。", ["涩", "软", "弦", "数"]], "13932": ["妇人", "原文未识脉名，仅言“脉欲离经”，为临产将娩之征。怀娠临月患疟，忧劳交加，伏暑化疟，脉欲离经提示气血将动、胎元欲产，故以栀、豉、苏、归、芩、连等安胎截疟，服两帖而产。", []], "13933": ["病机", "脉数而虚，数主热，虚主营亏；后脉尚数，热未清；脉数渐退，热渐减；终脉甚细软，细软为营阴亏虚。症见黄苔满布、腰疼、溲热便秘、嗽则欲呕，乃冬温营亏、肝阳烁液、痰阻枢机之病机。", ["数", "虚", "细", "软"]], "13934": ["病机", "脉迟弱，迟主寒，弱主虚，乃中虚痰湿内盛之象。症见喘逆、稍食甜物即发、苔黄垢而不渴、指冷腿酸，脾虚失运，痰湿内壅，故脉迟弱。投参、术、苍、枳等健脾燥湿化痰，痰吐气平而愈。", ["迟", "弱"]], "13935": ["病机", "脉洪滑右甚，左手兼弦，洪滑主痰热壅盛，右甚为痰热在肺胃，弦主内风。症见寒微热炽、昏谵瘛疭、目不识人、舌绛无液、苔黄燥、便秘，乃痰热深蟠、内风煽动之病机。后脉则右虚左数，为津虚痰滞。", ["洪", "滑", "弦", "数"]], "13936": ["病机", "脉来弦数，弦主肝郁，数主热，结合脘闷欲呕、汗多头重、苔色腻黄，说明余邪逗留兼挟肝郁，邪郁少阳阳明，痰热内扰，故见寒热复作、吐涎等症。", ["弦", "数"]], "13937": ["病机", "左脉弦数而洪，右滑数而溢，弦洪为肝阳亢盛，滑数为痰热内蕴，患者素体阴虚肝旺，腹有聚瘕，疟发苔黑口干，显系肝阳化火、痰热交阻之病机。", ["弦", "数", "洪", "滑"]], "13938": ["病机", "脉滑数而右大，按之皆虚，两尺尤甚，滑数主痰热，右大主邪实，按虚尺甚为下元虚损，故耳聋为精脱之征，病机属上焦痰实、下元亏虚，本虚标实。", ["滑", "数", "大", "虚"]], "13939": ["病机", "脉虚软微带弦滑，不甚鼓指，虚软为体气素亏，弦滑为痰阻清阳，气壅塞故脉更无力，证见苔黄腻、胸前拒按、谵语，病机为痰热内阻、正气不足。", ["虚", "软", "弦", "滑"]], "13940": ["病机", "脉状细软，细为阴亏，软为气弱，结合面赤耳聋、舌赤无液、便溏溲赤、龈肿巅疼，病机为肝肾素亏、心阳内亢，阴火潜燃，非外感实证。", ["细", "软"]], "13941": ["预后", "脉微欲脱，语难出声，舌光无苔，筋惕肉𥆧，微脉主阳气衰微，欲脱为危候，此因疟治误汗，气阴耗竭，虚风内动，故属预后不良之象。", ["微"]], "13942": ["病机", "初脉细数而涩，细数主阴虚热伏，涩主气郁湿滞，乃暑湿内伏、气郁不宣；后脉弦细而数，弦为肝郁，细数为阴伤热留，病机由暑湿郁遏转为肝热阴伤。", ["细", "数", "涩", "弦"]], "13943": ["病机", "脉弦劲而数，弦劲为肝火亢盛，数为热，结合口苦而渴、溲如沸、吐沫极酸，病机为肝经热盛、络脉瘀滞，热极似寒，非积寒之证。", ["弦", "劲", "数"]], "13944": ["病机", "前段脉甚滑、按之不绝，滑为血盛养胎之象，故断为孕而非寒呕，姜萸温燥反致血溢自汗。后段脉洪大按之虚软，洪大为气虚阳浮，虚软为脾肺不足，故娩后气逆碍眠、嗽汗便溏遗溺、口渴不饥，属虚阳上浮、脾失健运，治以沙参、黄耆、牡蛎等补敛并施而愈。", ["滑", "洪", "虚", "软"]], "13945": ["病机", "脉弦滑而数，弦为肝阳，滑为痰盛，数为热炽，合舌绛扪之甚燥、体丰呼吸不调、呃声不畅，断为肝阳内炽、痰阻枢机、液不上承，非津涸也。前医甘润愈投愈燥，正因痰热阻遏，津不上布；小陷胸加茹、薤、旋、菖等涤痰开结，一饮汗出热退，痰嗽流涎而解。", ["弦", "滑", "数"]], "13946": ["病机", "脉软而弦，软为气阴不足，弦为木旺乘土，合脘痛便溏、跗肿腰疼、频吐绿水、舌绛无液、口干少寐、形瘦神疲，断为木土相乘、阴液大耗。温补不效者，燥烈更伤阴液；故以参、连、归、斛、杜仲等培养中兼清肝木，忌燥烈，后加熟地舌渐生津而愈。", ["软", "弦"]], "13947": ["病机", "脉甚弦滑，弦为肝火，滑为痰盛，故断痰火之疴，戒温补以免瞽患；司马不从，渐至耳聋巅肿时咳，脉转搏劲不挠，乃痰火锢络成废。后案脉沉滑而数，沉滑主痰，数主热，体厚苔黄，故亟宜化痰清热，与类中虚治者迥别，示痰火实证不可妄补。", ["弦", "滑", "沉", "数"]], "13948": ["病机", "脉微弱为气阳不足，左手及右尺沉取弦数，为风阳内扰、湿热蕴结，合眩晕形消、舌深紫无苔不渴、纳食腹胀、溲少而赤、泻必肠鸣，断为中气固虚而兼风阳食火。故补不可佐滋腻滞中，亦不宜杂燥热煽风，取宣清升降补运兼施，服之胀消晕止。", ["微", "弱", "弦", "数"]], "13949": ["其他", "此段为医案编次说明，非论脉。言原案或脉证方药并叙，或叙证遗脉、叙脉遗证，方药注铢两者千百首中仅一二，编者欲人深思自得，故就原案笺释病情脉义、补其方药偶阙者。全段无脉象描述，故脉象要素为空，主旨属著述体例之其他类。", []], "13950": ["其他", "此段为全书切脉体例之总纲，提出一切脉以沉脉为要，凡沉脉与病情吻合者详加注说。原文只标沉脉，未及兼象，故仅取沉字。其意在强调沉取候脏气、辨病之所在，属诊法体例说明，非具体主病之论，故归其他。", ["沉"]], "13951": ["其他", "此段讲切沉脉的操作方法：病者正坐，两肘尽前置案上，医者重按久按，方能切得沉脉之情。原文两见沉脉，皆指脉位而言，非主病之象。其要在久按重按以候沉部脉气，属诊法操作规范，故脉象取沉，主旨归其他。", ["沉"]], "13952": ["病机", "右脉重按尤软，为气虚不能统摄之象。患者素患痰嗽，骤然吐血，孟英断为“气虚而血无统摄”，正因脉软无力，故用参耆术苓草山药等补气摄血。虽阴亏而忌阴药，非格阳而禁附桂，皆从脉软气虚着眼。", ["软"]], "13953": ["其他", "原文未直接描述脉象，仅言“中毒也”，以扒床拉席、口不能言、抓舌等症断为热毒内闭。绿豆清凉解毒，急火煎清汤澄冷灌之，取急证急治、清解热毒之意。脉象未及，故脉素缺如。", []], "13954": ["主病", "脉数重按有力、洪大滑数，为暑热内盛之象。赵子升夏病疟，孟英断为“暑热为患”，予白虎汤清解暑热。洪大滑数主阳明热盛，故用石膏知母；若脉洪大为阴虚，则温疟用白虎加桂枝，湿热疟用白虎加苍术，皆从脉辨治。", ["数", "洪", "大", "滑"]], "13955": ["病机", "原文未直接述脉，但孟英诊为“戴阳证”，必脉重按无力。真阳素虚，痰饮内动，卫阳不固，风邪外入，有根蒂欲拔之虞。面赤气逆烦躁，似热实寒，故以真武四逆回阳镇饮，攘外安内。脉象虽缺，病机从症可推。", []], "13956": ["病机", "脉微而弱，为阳气虚衰之象。钟耀辉年逾花甲，患肿起自肾囊，气逆便溏，溺清且长，孟英断为“土虚不制水也”。通利无功，滋阴亦谬，法宜补土胜湿，予大剂参术。脉微弱正合脾阳不振、水湿不化之机。", ["微", "弱"]], "13957": ["预后", "脉既数且乱，沉取极细，为阴分素亏、邪热内扰、精气欲脱之危候。汗出昏狂，精流欲脱，孟英谓“生机仅存一线”，亦斯人阴分素亏，不可尽谓附桂之罪。数乱主热扰，极细主阴亏，故以大剂滋阴清热、潜阳固脱之品灌之而安。", ["数", "乱", "细"]], "13958": ["病机", "脉沉而涩滞模糊，不分至数，为痰热阻遏气机之象。石符生感风湿失解，已从热化，加以温补，致气机窒塞，邪热无出路，烁液成痰，逆行而上。脉为气道，痰热阻气则升降不利，故脉沉涩模糊；肢凉畏冷乃气不流行、表虚所致。", ["沉", "涩"]], "13959": ["病机", "脉微而细，舌亮无胎，为气血两伤、阴亏尤甚之象。王某夏患感，多服表散，汗出过分，致气血两伤，肢骸失养，不能起坐。微阳弱，细阴弱，细尤过于微，合舌亮无胎，知阴亏为主，故用大剂参耆归术熟地等双补气血、滋养肝肾。", ["微", "细"]], "13960": ["病机", "脉似虚细而沉分弦滑，虚细为少阴不足之象，沉分弦滑乃阳明有余之征。饮食如常而肌肤消瘦、汛事紫淡不恒、两腓发热、面色青黄隐黑，皆内伤无形之热耗阴，血不充肌。脉沉取弦滑，说明热伏于里，非外感实邪，故宜甘寒养阴清热，不可直泻。", ["虚", "细", "沉", "弦"]], "13961": ["病机", "原文未直接描述脉象，仅言“脉数为阴虚、脉空数”为注文。产后昏谵汗厥、肌肤浮肿而恶露仍行，说明血分无病，病在气分痰饮。痰饮蒙蔽清窍则昏谵，气机不利则浮肿汗厥。脉数或空数提示阴虚而痰热内扰，故不可误投攻补，宜蠲饮化痰。", []], "13962": ["病机", "霍乱后目闭呃忒，医疑脱陷，然溺赤口干、脉情耎数，耎为阴虚，数为热邪，说明热伤肺胃津液，非阳虚欲脱。肝热逆冲则目闭，热伤肺气则呃忒。脉耎数反映阴虚兼热，故改予肃清肺胃之剂而安，不可温补回阳。", ["耎", "数"]], "13963": ["病机", "猝仆于地，脉弦滑而大。弦滑为痰食内蕴，大为气虚，痰气食相并上逆，蒙蔽清窍而猝仆。暴病无虚，脉大非虚脱，乃气虚推动无力致痰食停滞。故先开关探吐，继调气和中，痰食去则气机畅而愈。", ["弦", "滑", "大"]], "13964": ["病机", "古稀久泻，弦象独见右关，按之极弱，乃土虚木贼。右关主脾，弦为肝强，弱为脾虚，肝木乘脾，脾失健运则泻。前医温补升阳反助肝阳，辛通更泄脾气。脉象说明脾虚为本、肝强为标，治宜异功散健脾，佐乌梅木瓜芍药敛肝，使木不贼土。", ["弦", "弱"]], "13965": ["预后", "夏产数日，泄泻自汗呕吐不纳，脉虚微欲绝，证极可虞。虚微欲绝为阳气衰微、阴阳离决之兆，故曰“迟不及矣”，宜急补之。脉象说明阳虚欲脱，非一般产后三禁可拘，急予参芪术补气，龙牡石英黑豆潜阳固脱，四剂向安。", ["虚", "微"]], "13966": ["病机", "汛愆而饮食渐减，服通经药尤恶谷，脉缓滑。缓为阳虚气弱，滑为痰郁生热，痰气凝滞经隧，故经水愆期。病在气分，非血分瘀阻，故通经血药不效反伤胃气。脉象说明痰气交阻，法应豁痰流气，气畅则经自通。", ["缓", "滑"]], "13967": ["病机", "脉来涩数上溢，涩为津液已伤，数为热邪留著，溢乃热邪壅遏气机，上逆为呃忒口腻、频吐涎沫。冬温误表散则津伤热炽，误滋填则热锢，误温补则气窒，误攻下则阴劫。脉象说明津伤热壅、气机上逆，非表邪非积滞，故便秘潮热少腹烙而按不坚满。", ["涩", "数"]], "13968": ["病机", "脉弦细以数，弦为肝郁，细为阴血不足，数为阴虚内热。腰疽愈而复发五年，非外疡实邪，乃内损阴亏、虚火内伏，故脉见弦细数。孟英断为内损证，非外科所知，用大剂甘润滋填，正是针对阴虚之本，阴复则脉静病痊。", ["弦", "细", "数"]], "13969": ["病机", "首诊脉浮弦以滑，浮为风阳上扰，弦主肝风，滑为痰壅，故猝仆由风痰上逆、气火并升所致，治以息风降火、顺气蠲痰。后诊脉微弱而弦，微弱为阳虚气馁，弦为肝木未和，与前证相似而虚实迥异，故改用参术首乌等培补，示同病异治。", ["浮", "弦", "滑", "微"]], "13970": ["病机", "脉极沉，重按至骨则弦滑隐然，沉为热伏于里，弦滑为积热深锢、气机郁滞。症见恶寒、涎沫、不渴、便坚溲少、口气重，皆热伏深锢、阳气不达之假寒真热。孟英断为积热深锢，非大苦寒泻之不可，正合沉取弦滑之实象。", ["沉", "弦", "滑"]], "13971": ["病机", "脉沉而滑数，沉主里，滑数为痰热内蕴。疟经温补，暑湿失解，酿成痰饮盘踞三焦，气机阻塞，故恶寒喜热熨而反觉冷气上冲，乃真热假寒。脉情兼证并究，滑数沉实为里热之据，故予大剂苦寒，渐不畏寒，痰少谷增。", ["沉", "滑", "数"]], "13972": ["病机", "原文未识脉名，仅言一息如丝，乃阴血久夺、暑热鸱张之危候。大汗如雨则阴液暴伤，转筋由筋脉失养，故治法以救阴为急，用沙参枇叶龙牡木瓜等敛汗存阴、清暑舒筋。注文谓阴复则转筋止、脉息起，正点明阴血久夺为本、暑热为标。", []], "13973": ["病机", "原文未识脉名，仅述切脉时壮热烙指、汗出如雨带粉红色。素禀怯弱、汛停瘕聚、肌削，本属虚损；复感暑热，壮热汗出，是客邪炽盛。孟英先治客邪，用白虎加洋参元参，热退汗收后再调气养营，宿瘕亦消，体现急则治标、标本缓急之序。", []], "13974": ["病机", "注文谓脉必肝脉沉实数有力，沉主里，实为邪结，数为热，乃肝经郁热、气火内结之象。症似喘非喘、面赤眩晕、不寐，皆气机不舒而病不在气分之征。脉病而人可任苦寒大剂，故曰小恙，予连芩栀楝羚角龙荟丸泻肝，汛至色黑而愈。", ["沉", "实", "数"]], "13975": ["病机", "脉沉而有弦滑且数之象，沉为痰浊遏伏，弦滑为痰乘风上，数为温补助热。过投温补引动肝风，煽津为痰，痰乘风上则昏厥，奔流经络则抽搐，阳气逆上则鼻塞面浮。脉证合参，断为风痰上逆、热郁于里，故用甘寒息风化饮、凉苦泄热清肝。", ["沉", "弦", "滑", "数"]], "13976": ["病机", "脉细而滑数，细为阴分亏虚，滑数为暑湿客邪炽盛、伏热蕴隆。原文谓“客邪炽盛，伏热蕴隆，阴分甚亏，深虞津涸”，正合此脉。温散伤阴，故舌强紫赤、谵语神昏；湿热下注则肛前囊后溃脓。脉象揭示邪盛正虚、热灼营阴之机，故先予清营之剂。", ["细", "滑", "数"]], "13977": ["病机", "脉甚数，为阴亏内热之征，故曰“阴亏也，温补非宜”。灸火伤阴，又值溽暑，火气内攻，脉转滑数倍加。滑主痰，数主热，此热自内生，非外寒可温散。原文引仲景“微数之脉慎不可灸”之训，正以艾火大能伤阴，再投温散则阴愈亏而热愈炽。", ["数", "滑"]], "13978": ["病机", "脉细数而促，细为阴亏，数为热炽，促为热极风生、液将涸竭之象。原文直断“阴亏热炽，液将涸矣”，故见神昏谵妄、肢搐耳聋、舌黑唇焦、囊缩溺滴。此阳证阳脉，能任阴药，故用大剂滋阴清热。若脉耎弱则正不胜邪，故曰不治。", ["细", "数", "促"]], "13979": ["病机", "脉虚弦而小数，虚为素体阴津阳气皆伤，弦为内风动，小数为虚热。原文谓“患感时过投温散，阴津阳气皆伤”，后进补而滋腻妨中、刚烈动风，遂致肢冷欲呕、舌謇言涩、溺黄而频。脉虚弦小数正示虚中挟热、内风扰动之机，故用柔润潜阳、兼通中运。", ["虚", "弦", "数"]], "13980": ["病机", "脉滑而数，滑主痰热，数主火盛。原文谓“发散太过，火盛风炽，气血两燔”，故舌绛大渴、面赤音失。气分之邪由泻略泄其焰，营分之热由汛稍解其焚，脉滑数正是热邪充斥气血之征。若畏脱陷妄投止涩，则热无出路，故以清解为治。", ["滑", "数"]], "13981": ["病机", "右寸关滑数上溢，左手弦数。滑数为暑热壅肺、津液凝滞成涎沫；弦数为热郁肝胆。原文谓“暑热始终在肺，并不传经”，故耳聋口苦、胸次迷闷、频吐黏沫、啜饮阻塞。脉象示邪在肺经气分，清肃不行，故一剂白虎汤可愈，温散升提皆不中病。", ["滑", "数", "弦"]], "13982": ["病机", "脉数而芤，数为热邪炽盛，芤为阴血亏虚。原文谓“大渴则肺阳尚旺，病情全系热邪由气传营之象”，而“阴虚重于热实”。裸卧昏狂、舌黑大渴、溺赤便秘，皆热灼营阴之候。脉数而芤正示热实挟虚，故用犀角地黄汤加减，甘凉滋阴以救液。", ["数", "芤"]], "13983": ["病机", "原文未识脉名，然孟英诊断“阴亏，忌从疟治”，以疏散甚不相安，可知脉必非实。胁痛痰嗽、面黧形瘦，为虚中挟实、肺燥肝热之候。方主肃肺润燥、滋肾清肝，数服而痊，其病机在阴亏而肺失清肃、肝失濡养，故不可从疟作寒热实治。", []], "13984": ["病机", "原文未录具体脉名，孟英据“泻后腹中反觉舒畅”“春间尤甚”断为肝强脾弱、木土相凌。晨泄有年而温升补涩反剧，说明非脾肾虚寒，乃肝木偏旺、疏泄太过，克伐脾土，泻后肝郁稍得疏解故反舒畅；春气通肝，故春间尤甚。治以白术苡仁扶脾、黄连楝实芍药蒺藜泄肝，正合抑木扶土之法。", []], "13985": ["病机", "原文未载脉象，孟英诊为“气分偏虚，痰饮阻其清阳之旋运”。久患痰多、胸膈满闷、连年发痫，皆因气虚不能运化，痰饮中阻，清阳不升，旋运失职，故满闷而痫作。单治痰则气愈虚，故用六君去甘草加黄耆补气治本，桑枝蒌仁薤白菖蒲旋覆豁痰通阳治标，气旺痰消则胸次廓然。", []], "13986": ["病机", "原文未出脉象，孟英据“阴虚内热”及天令炎蒸断为血热恶露不行。娩后阴亏火旺，热灼血分，瘀阻胞宫，故恶露不下；此时若概投生化汤之温，则助热灼阴，骤则变证蜂起，缓则蓐损渐成。故以生地丹参丹皮凉血，桃仁山楂茺蔚泽兰琥珀活血，栀子豆卷清透郁热，使热清瘀行而效。", []], "13987": ["病机", "原文未录脉名，孟英切脉断为“元气随泻而泄”，高年霍乱转筋吐泻之后，暑邪虽减而元气大伤，故倦卧不能反侧、气少不能语言、不饮不食。此属虚实夹杂，余暑未清故热药在所禁，元气已泄故当补。方以丽参麦冬知母玉竹石斛白芍益气养阴，木瓜扁豆苡仁茯苓蒺藜和脾舒筋，补虚而不助暑。", []], "13988": ["病机", "脉微弱如无，为阳气衰微欲脱之象。霍乱转筋剧作，又误服青麟丸攻下，泄泻更伤元阳，故耳聋目陷、汗出肢冷、音哑肌削，皆阳亡阴竭、气血不能上承外达之候。孟英先浓煎高丽参接续微阳，继以参术苓芍附桂干姜温补脾肾、回阳固脱，重用附桂干姜鼓舞补药，一剂各证皆减，正合脉证。", ["微", "弱"]], "13989": ["病机", "脉芤而稍有歇止，孟英明言“芤者暑也，歇止者痰湿阻气机之流行也”。体丰年迈，暑湿之邪与素蓄痰浊相合，盘踞中焦，阻滞气机，故脉芤而歇止；清解不效、大便带血，是邪依附痰浊、气血受扰。必攻去其痰，使邪无所依，故用桃仁承气加礞石滚痰丸峻下黏痰污血，疟乃止。", ["芤"]], "13990": ["病机", "脉虚大而肌肤枯涩、口渴，孟英断为“气分之阴亏”。吐血之后，肺胃气阴两伤，气虚无以充脉故虚，阴亏阳浮故大；肌肤枯涩、口渴皆阴津不能濡润之征。此非阳虚，故温补既非；病在气分肺阴，故滋填肾阴亦谬。治以参耆二冬知母百合玉竹石斛桑叶枇叶，益气养阴、清润肺胃而愈。", ["虚", "大"]], "13991": ["病机", "脉弦而细、尺中甚数，为足少阴热疟之据。弦主疟、细主阴伤，尺中甚数则肾经热盛；疟作于子夜，口干嗜饮，皆少阴热灼阴津之象。甫两发即形消清瘦，是热邪耗阴甚速，故孟英戒不可玩视。方用元参生地知母丹皮地骨皮天冬龟板滋阴清热，茯苓石斛桑叶和中生津，专清少阴之热。", ["弦", "细", "数"]], "13992": ["病机", "脉伏胸痞，非阳气虚脱，乃滋腻阻塞气机，清阳不司旋运，痰饮闭滞隧络所致。湿邪久蕴化热，误投升补动肝阳，痰饮上逆，故见呃忒自汗、渴饮不食、颧赤便泄等邪实热浮之象。脉伏为邪闭，非脱象，故曰补药不可进，治以通降，使痰饮去而脉出。", ["伏"]], "13993": ["病机", "脉左细数为阴亏营热，右弦滑为气热痰实。阴亏之体，伏火之病，失于清降，扰及于营，故见肌热如烙、汛事非期而至、咽腐龈糜。细数主阴亏营分有热，弦滑主气分痰热壅实。先以犀角地黄汤清营调血，是急则治标、先血后气之权衡。", ["细", "数", "弦", "滑"]], "13994": ["病机", "本案未录脉象，然据“阴虚劳嗽”“冲气不纳则呕吐”及误投参术病益甚，可知非阳虚。劳者温之乃温养之谓，非温补。阴虚劳嗽，嗽久冲气不纳，故呕吐；治以甘寒中参温药，潜阳重镇，使冲气归宅。脉情虽未明言，然必非虚寒之象可据。", []], "13995": ["预后", "脉微无神，合自汗不收、肢背极冷、奄奄一息，为阳气欲脱之危候。禀赋素亏，误认表证而投柴葛香薷散之，更用枳朴槟榔泻之，重伤阳气，致阳脱于外。脉微无神乃阳气衰微、神气将散之象，故予救逆汤加参耆回阳固脱，服之渐安。", ["微"]], "13996": ["病机", "淋久不愈，延至溽暑，孟英以补中益气汤取效。原注谓“脾阳衰败，气不摄精，右脉必重按无力”，虽未明录脉象，然右脉重按无力为脾阳虚衰、中气下陷之征。脾阳不运，气不摄精，故淋久不止；补中益气升举脾阳，气复则淋自愈。", []], "13997": ["病机", "前案霍乱转筋，为湿热蕴伏，投连朴饮清化湿热、行食涤痰而瘳。后案久患痰嗽，孟英切脉曰“非伤风也”，原注谓阴虚肺燥，前医必作伤风温散，致伤上焦气分之阴。虽未录具体脉象，然脉非浮缓之伤风，当为虚细之象，故以甘润养阴取效。", []], "13998": ["病机", "脉来沉实而滑，为邪归胃腑、实热内结之征。患者感证误投柴葛温散，劫汗伤阴，热势更甚；孟英先以栀豉芩连清解升浮之热，俟邪归胃腑，脉见沉实滑，方用承气下之。沉主里，实主邪结，滑主热实，此治病分初中末之定法，下不厌迟。", ["沉", "实", "滑"]], "13999": ["病机", "本案未录脉象，孟英据“囊缩便秘，心摇摇不能把握”断为根蒂欲脱、阴虚阳浮。囊缩便秘为阴亏液涸，心摇摇不能把握为虚阳上浮、神不守舍。治以八味地黄汤去丹泽合生脉，加紫石英青铅龙牡胡桃楝实苁蓉，滋阴潜阳、纳气归元，使大解行而诸恙减。", []], "14000": ["病机", "脉弦滑有力，弦主肝阳上亢，滑主痰热内壅。高年孤阳炽于内，燥火薄于外，痰热胶结，故面浮喘嗽、痰黄带血、茎囊肿硬。脉证互参，证实为阴虚痰实，非温补所宜，故以白虎合泻白清泄痰火。", ["弦", "滑"]], "14001": ["病机", "原文未识脉名，然据“悲哀劳苦，阳气受伤，曲糵浸淫，乃从虫化”，知阳衰湿蕴，肌肤失养，化生虱虫。形消善痒、虱从肤出，皆阳气不布、湿浊外淫之象。治以补气加杉木桑枝，扶阳化湿，非杀虫套药可效。", []], "14002": ["病机", "脉弦滑而数，弦主肝热，滑主痰壅，数主火盛。暴病呕吐彻夜不止，气分实热，痰火内扰，胃气上逆。故以芩连栀楝大苦寒直折火势，佐贝母胆星化痰，旋覆赭石降逆。脉证合参，确为实热壅盛之候。", ["弦", "滑", "数"]], "14003": ["病机", "右关洪滑，洪为虚而滑为实，然“稍一动摇，血即上溢”，显系胃火炽盛、迫血妄行，实多虚少。自汗口渴，亦阳明热盛之征。故用白虎加西洋参大黄炭，清胃泻火，凉血止血，一剂霍然。", ["洪", "滑"]], "14004": ["病机", "脉滑数而左歇右促，更兼雀啄、解索，乍看极虚，实由湿热误补，漫无出路，充斥三焦，气机壅闭，痰饮凝滞。脉来屡变，皆痰阻气机之象。面黄头汗、胸痞拒按、便溺涩臭，俱为壅闭实证，非大虚也。", ["滑", "数", "促", "结"]], "14005": ["病机", "原文未识脉名，然据“厥阴为病”“咸苦泄热”“甘润滋阴”，知为热邪灼液、阴虚挟实。少腹酸坠、溲频数疼，热实兼阴虚；闻声惊悸，心肝阴耗。通渗则虚虚，故先泄热后滋阴，不犯通利。", []], "14006": ["病机", "脉沉弦而软滑，沉软主肝郁气结，弦滑主肝热挟痰。误补温运，郁热凝痰，故腹胀如痞、冲逆吐酸、肌肉渐消。苔黄腻、溲浑短，皆郁热痰凝之征。治以栀楝萸连清肝泄热，旋枳鸡金鳖甲化痰软坚。", ["沉", "弦", "软", "滑"]], "14007": ["病机", "左弦而数，右滑以驶，弦数主肝阳偏盛，滑驶主痰热内壅。阴虚木少水涵，肝阳上侮于胃，则脘痛呕逆；温补妄施，油添火上，肺胃津灼，痰凝气塞。见证多端，皆气失下降，非劳非妊，故以清淡肃清气道。", ["弦", "数", "滑", "驶"]], "14008": ["预后", "左尺坚搏，为真阴已伤之象。尺脉候肾，坚搏乃阴亏阳亢、脉失柔和，故孟英谓证可愈而难享年，非善象。久病生死察左尺盛衰，此脉示肾阴耗损，虽疽愈而根本已戕，故预后不佳。", ["坚", "搏"]], "14009": ["病机", "脉劲搏指，面赤不言，口涎自流，力大无制，乃禀赋过强、阳气偏盛之候。劲搏为阳亢无制，阴不配阳，故狂惑躁动。年越古稀，阴气先衰，火易燎原，热补更劫其阴，致涸竭之水难生，亢极之阳难和。", ["劲", "搏"]], "14010": ["病机", "脉软滑微数，软为阳虚，滑为痰实，数为阴虚挟热。新产血去，阴亏热内生，故发热；痰饮内盛，故谵妄昏瞀。渴喜热饮似虚寒，实为痰热内蕴。脉软滑微数正示阴亏痰热之机，非风寒瘀血，故温补攻通皆误。", ["软", "滑", "数", "微"]], "14011": ["病机", "脉数且涩，数主热，涩主阴伤血滞。素体阴虚，忧劳哀痛之余五志内燔，温邪外迫，径伤营分，故初热即舌赤而渴。脉数涩示热灼营阴、血行不畅，非善证，故急予清营凉卫，病势必转重。", ["数", "涩"]], "14012": ["主病", "耄年脉实，天畀独厚，证属阳结。脉实为邪热内结、腑气不通，故腹胀便秘。年逾八秩而脉实，非虚衰之候，乃阳热有余，法宜清火通腑，故用西洋参石膏知母等清火，送更衣丸通便而愈。", ["实"]], "14013": ["死脉", "左寸如钩，瞥瞥如羹上肥，是心之真脏脉见。钩为心脉，真脏脉现则真气散漫，不能收拾，故曰病不能夏。气逆血溢、腹胀囊肿虽似壅塞，然脉怪而散漫无根，与搏指不挠之邪壅不同，故主死。", ["钩"]], "14014": ["病机", "六脉缓滑，缓为脾脏挟湿，滑为挟热气不下行。气不下行则血上逆，故久患齿衄。年将及笄，天癸将至，脉缓滑示湿热血滞，非虚寒。治以凉血行瘀，使气下行，血不上逆，故一剂知，数日愈，寻即起汛。", ["缓", "滑"]], "14015": ["病机", "左脉浮弦数重按有力，弦为木旺，数为热，浮为阳浮。阴虚木燥，侮胃为泄，误饮火酒，怒木愈张，故转为滞下，左腹痞块，痢时绞痛。脉浮弦数有力示肝经郁热、木火亢盛，非寒也，故屏辛温，用苦寒泻热、咸寒育阴。", ["浮", "弦", "数"]], "14016": ["病机", "脉形豁大，为阴中之阳亦虚，肾气不能潜纳，虚火上炎，故面有红光；足冷为阳虚不能温煦。归脾汤中参耆性升，升提虚火，故吐血益甚。此脉主肾虚不纳、虚阳上浮之吐血，与面红、足冷相应，治以引火归原。", ["豁", "大"]], "14017": ["病机", "脉象弦滑以数，弦主痰饮，滑主痰湿，数主热，为痰饮盘踞胸中、外邪入而化热之象。右关脉必弦滑数重按有力，说明痰热结于胃腑。此脉主风温顺传胃腑、痰热内阻之证，与苔白滑、便秘、肢搐等症相应，痰饮一降则苔转黄。", ["弦", "滑", "数"]], "14018": ["病机", "左手弦而数，右部涩且弱，弦数主悒郁化火，涩弱主思虑伤脾、营血不足。病发心脾，脏阴亏虚，故见晡寒夜热、寝汗咽干、咳嗽胁疼、减餐经少、肌削神疲。此脉主脏燥、心脾两伤之病机，与情志郁结、阴血暗耗之症相应。", ["弦", "数", "涩", "弱"]], "14019": ["病机", "脉大而数，重按虚散，大为虚，数为阴虚挟热，重按虚散则阴中之阳尤虚。虚阳上浮，故两目发赤、牙龈肿痛、奔走骂人。此脉主阴虚阳浮、虚火上炎之狂躁，与面赤、龈肿、神志失常相应，治以滋阴潜阳、引火归原。", ["大", "数", "虚", "散"]], "14020": ["病机", "体瘦脉细数，尺中更乱，细数主阴虚内热，尺中乱为真阴下泄、根本动摇。发热前带下如崩，真液早泄，阴气先伤，阳气独发，故见舌绛咽干、耳聋谵语、咳吐黏痰。此脉主温病下虚、阴液枯竭之危候，与痉厥之变相应。", ["细", "数", "乱"]], "14021": ["病机", "脉滑痰多，苔黄舌绛，滑主痰湿内蕴，苔黄舌绛为热邪伤阴。形虽羸瘦而脉滑痰多，是体虚病实，痰热胶结为患，故右腰痛胀欲捶。此脉主痰热内阻之实证，与苔黄舌绛、痰多相应，治当攻去其痰，不可温补。", ["滑"]], "14022": ["预后", "六脉弦强无胃，弦强为邪气亢盛，无胃气则真脏脉见，胃气已败。热逾半月，胸腹胀痛拒按，便秘溺赤，舌黑口干，自汗烦躁，酷似结胸，乃误汗酿成。此脉主邪盛正衰、胃气将绝，预后不良，故越二日便行而殁。", ["弦", "强"]], "14023": ["病机", "脉数而洪，数为阴虚挟热，洪为阴虚阳浮，舌绛大渴，热已侵营而未离气分。产后四肢串痛，非风湿为病，乃温补祛风及生化汤、砂糖酒酿成营血耗伤、内风欲动。此脉主阴虚血耗、内热动风之病机，与舌绛大渴、肢痛呻吟相应。", ["数", "洪"]], "14024": ["病机", "脉弦无胃、脉不柔和，是肝郁化火、风阳内煽而胃气衰败之象。患者素多郁怒，气聚成瘕，久服温补劫阴伤液，津液涸竭，故脉失柔和而弦劲无胃；水液吐尽则哕逆空呕、便秘不行，舌痿难伸，正是孤阳无阴、胃阴枯竭之候，故断为女人孤阳之病。", ["弦"]], "14025": ["病机", "脉伏口渴，乃暑热内炽、气机壅遏不通所致。酷热患疟，误投平胃理中温燥之品，热邪闭郁气分，故热炽神昏、胸高气逆、溺赤便闭而脉反伏；口渴不食，正暑热伤津之征。脉伏非虚寒，乃热邪壅塞、阳气不达于脉，故主以白虎清透暑热。", ["伏"]], "14026": ["病机", "脉伏而重按沉实有力搏指，是痰浊壅阻气道、湿蕴热伏之象；痰去后脉现弦滑而数，则显暑热痰湿交蒸之实。脘闷苔腻欲呕、大渴喜热饮，皆痰湿内盛、暑热外侵使然。脉伏由痰阻气机，非阳气虚衰，故先以礞石滚痰丸开导，痰出则脉转弦滑数而呕止胸舒。", ["伏", "弦", "滑", "数"]], "14027": ["病机", "脉洪滑无伦，是暑热炽盛、气分热壅之象。疟作甚剧，目赤狂言、汗如雨下、舌深黄厚燥，皆暑热燔灼气分、热盛津伤之候；恣饮姜枣汤更助其热，故脉洪滑无伦。洪为热盛，滑主痰热内壅，脉证相合，故用白虎重剂清涤暑热。", ["洪", "滑"]], "14028": ["病机", "脉伏自汗，乃暑热为冷饮冰伏、大气不能转旋所致。啜冷石膏后心下痞闷、四肢渐冷过肘膝、二便不行，是寒凉冰伏胸中，阳气郁遏不达四末，故脉伏；自汗则暑热内蒸、气机失司。脉伏由冰伏气闭，非阳虚，故以六一散调紫雪丹辛香通闭、泻暑下行。", ["伏"]], "14029": ["病机", "脉沉细而数、尺为甚，是暑热深入足少阴、肝肾阴分亏耗之象。沉细为阴分不足，数为阴虚挟热；口渴、目不欲张、两腰收痛如锥刺、寒少热多、心慌，皆暑入少阴、肝肾阴伤之候。喻氏谓汗下温三法皆不可行，故以滋阴清暑为治。", ["沉", "细", "数"]], "14030": ["病机", "脉至梗涩、毫无微弱之形，是产后瘀血内停、阻遏气机之实证。腹胀泄泻、面浮足肿，宛似气虚，然舌色如常、小溲通畅，知病在血不在气；瘀停化热，气机失降，故脉梗涩而不微弱。渗湿温补反伤阴助热，故以丹参、泽兰、桃仁等活血化瘀取效。", ["涩"]], "14031": ["病机", "脉弦滑而重按有力搏指，是湿热积滞壅结肠腑之实象。滞下昼夜数十行、苔黄满布，为湿热蕴结、气血阻滞之下痢；弦主气滞，滑主湿浊痰热，重按有力说明邪实正不虚，故可重用芩连苦寒清湿热，佐楂朴行气导滞，送青麟丸通腑泄浊而愈。", ["弦", "滑"]], "14032": ["预后", "脉弱而见眩晕，更兼汗出息微，是阳气欲脱之兆。通因通用后痛泄无度、呕恶不纳，已伤中阳，而脉弱、息微并见，说明元气将脱，故孟英断为“元将脱矣”，急投大剂温补。脉弱在此非普通虚象，而是阳微欲绝之危候，与息微、汗出共判预后险恶。", ["弱"]], "14033": ["病机", "原文未识脉名，然述脘疼呕吐、畏寒不寐、四肢不仁、肌肉尽削、带下如溺等症。孟英断为“暑伏肺胃”，因屡投温补，熟地等阴柔腻滞挟制暑邪，致津气灼烁殆尽、脂液奔迫妄行、治节无权、阳明涸竭。此段重在阐明误补致暑伏肺胃、阴液耗伤之病机，非以脉象为主。", []], "14034": ["病机", "脉涩而兼沉弦以数，涩主血滞，沉弦主郁，数主伏热。患者因事抑郁，凛寒发热，前医作血虚治，投归芎丹参，致血为邪踞、更不流行，故左胁下及少腹梗塞不舒。孟英断为“阴虚挟郁，暑邪内伏”，脉涩沉弦数正示气郁血滞、伏暑内遏之机，故治宜清气为先。", ["涩", "沉", "弦", "数"]], "14035": ["病机", "脉沉而滑数梗梗，沉主里，滑数主实热，梗梗示结遏不畅。高年白痢，前医误作寒湿，屡投理中、附子，致腹胀且疼、不食不溺、哕逆发热。孟英断为“暑热未清”，补药早投，实热结遏不能宣达，故脉沉滑数而梗梗。此脉证实热内结，非虚寒，故用芩连杏朴等清宣。", ["沉", "滑", "数"]], "14036": ["病机", "脉弦细，沉取甚数，弦细为阴虚，沉数示热邪内锢。痢疾误作寒湿，广服温补燥热，致发热无溺、口渴不饥、腹疼胀、巅痛不眠、舌绛无津、肌肉尽削。孟英断为“暑热胶锢，阴气受烁”，脉弦细沉数正是阴虚而暑热深伏之象，故用育阴清热、合白头翁汤为治。", ["弦", "细", "数"]], "14037": ["病机", "脉细数而兼弦滑，细数为阴分挟虚，弦滑为气分挟痰热。萧某素患痰多，常服六君子汤，孟英断为“阴亏火盛，津液受灼而成痰”，非虚寒，故屏绝温补，须壮水之剂。后患喉痛，专科不效，孟英谓“阴虚于下，阳浮于上”，脉细数弦滑正示阴亏火旺、痰热内蕴之机。", ["细", "数", "弦", "滑"]], "14038": ["病机", "原文未识脉名，述孙位申患感耳聋，医泥少阳小柴胡之例，聋益甚。孟英断为“伏暑”，改投清肺之药而聋减。此段阐明耳聋治肺之理，因暑邪伏于肺胃，非少阳证，小柴胡中参草枣胶锢暑邪，故误治益甚。后误服葛粉，耳复聋，复投肃清肺胃药寻愈，示伏暑病机在肺胃气分。", []], "14039": ["预后", "脉极弦细而促，弦细为阴津已竭，促为热炽而脉数急，更兼舌绛大渴、小溲赤少、饮而不食月余，孟英断为“证实脉虚”，坚辞不治。此脉极弦细而促，非实热壅盛之促，乃阴液枯竭、虚阳躁动之候，与舌绛大渴、小溲赤少共示肺肾阴竭热炽，故预后不良。", ["弦", "细", "促"]], "14040": ["病机", "脉沉滑而数，沉主里，滑主痰，数主热，合为热痰结伏于里。原文谓“少腹结块，攻痛异常，大渴无溺”，又“昼夜百余行，五色并见”，乃温补酿成热痰滞下，非虚寒。脉沉滑数正应暑湿深受、温补助虐之机，故断为“药剂之误投”，非停滞可拟。", ["沉", "滑", "数"]], "14041": ["预后", "脉细硬如弦，毫无胃气，细为阴亏，硬弦为胃阴竭而肝木失养；右尺洪数，为肾阴竭而虚火动。原文“舌色光绛，大渴溺滴”，一派津液尽劫之象。温补劫阴，草木难生，故列于预后不良，示胃、肾、心、肺、肝阴俱竭之危。", ["细", "弦", "洪", "数"]], "14042": ["病机", "脉甚弦，重按则滑。弦为厥阴肝脉，滑为痰热内蕴。原文“三日一发，发则恶寒”，乃暑热伏于厥阴，肝挟热痰，邪正相争而作。弦滑并见，说明热暑伏厥阴而非虚寒，故温补“皆为戈戟”，主以左金、龙荟清肝泻热。", ["弦", "滑"]], "14043": ["病机", "脉微弱，为阳气虚衰之象。原文“呕吐自汗，肢冷神疲”，乃凉解伤中、阳虚内伤，非伏暑实证。微弱之脉与肢冷神疲相应，说明内伤虚寒，故用黄耆建中温补而安，断不可视同伏暑再投凉解。", ["微", "弱"]], "14044": ["预后", "脉形滑数，滑主痰热，数主热盛，为阳证阳脉。原文“舌虽黑而脉形滑数”“痰虽臭而气息调和”，说明热踞气血而胎未坏，阳证得阳脉尚可治。若阳证见阴脉则不治，故凭滑数之脉断其犹可挽回，主以气血两清。", ["滑", "数"]], "14045": ["病机", "脉隐隐然弦且滑，弦为肝强，滑为痰盛。原文“体丰”“泄泻脘痛”“齿痛”“极其畏热”，皆肝阳犯胃、痰热内蕴之征。脉弦滑与体丰痰盛相应，说明病在肝强痰盛而非虚寒，故治必先去其病而后补虚。", ["弦", "滑"]], "14046": ["病机", "脉滑苔厚，滑主痰，苔厚主实，合为热痰盘踞气分。原文“溺赤痰浓”，皆热痰之象，故知前医作虚寒治更剧。脉滑与痰浓溺赤相应，说明哮由热实痰阻而发，主以清化痰热，不可温补。", ["滑"]], "14047": ["病机", "本段未识脉名，全凭症候辨治。原文“口苦而渴”“泻出如火”“小溲不行”“痰黏且韧”，皆热证阳旺之象，故虽时值小寒、症似霍乱，实非寒证。痰黏且韧一语为辨证关键，说明热痰内蕴，主以清解，一剂知二剂已。", []], "14048": ["病机", "脉弦硬无情，乃胃阴已竭之象。患者过服温补，热药竭阴，胃中津液灼烁为痰，五脏失养，故见血溢、便泄、食少痰多、喘逆碍卧等症。弦硬为胃气败绝、真阴耗竭之候，非寒湿实证，童某误投温燥，更剧其势。", ["弦", "硬"]], "14049": ["病机", "脉形空耎促数，为营血暴脱、阴精亏虚之象。冬温失于清解，误服辛热，引邪深入，迫血妄行而崩。空耎主血脱，促数主热迫，舌绛苔黑、足冷息微，皆阴亏热炽、虚风内动之候。幸汛断十载，阴精基础尚存，故可治。", ["空", "耎", "促", "数"]], "14050": ["病机", "脉滑且数，滑主痰饮，数主阴虚挟热。素患痰嗽，温邪挟宿饮上逆，故头痛发热、面赤痰喘、谵语神昏；渴饮不饥、便溏溺少，乃热灼津伤、饮停不化。胸中冷气上冲，为痰饮阻遏、气机逆乱之征。法当清解，化痰透邪。", ["滑", "数"]], "14051": ["病机", "形瘦脉数，舌色乾红，为阴虚热胀之候。误服温补，阴愈耗而络愈痹，胀满由生。脉数主热，阴虚则内热，热灼津液，络脉不通，故腹胀不碍食，证非气分。极苦泄热、微辛通络，方中病机。", ["数"]], "14052": ["病机", "脉弦耎，苔黄腻，弦主饮、主痛，耎为湿阻，黄腻为湿热。素饮浓茶，酿湿生痰，饮邪上逆则呕吐，下阻则二便秘涩，宛似关格。医误为寒，投姜萸沉附，更煽风阳，饮藉风腾，但升不降。此饮证非阴枯阳结，治当苦寒泻风阳、辛温豁停饮。", ["弦", "耎"]], "14053": ["病机", "脉弦细以数，弦细为阴亏，数为内热，合为真阴大虚之证。腹胀脐脓，误予温补内托，劫阴助热，遂咳嗽不眠、腹中绞痛、痰色红绿、大便不行。舌绛大渴，津液枯涸。耆术归桂皆禁，治以甘露饮加西洋参等，滋阴润燥。", ["弦", "细", "数"]], "14054": ["病机", "脉左数右滑，皆极虚耎。左数主血分挟热，右滑主气分挟痰，虚耎为阴液素虚。冬温邪轻，因积劳久虚，肝阳内动，烁液成痰，逆升而厥，故昏沉如寐。治以犀角地黄清营、牛黄丸化痰热，清营兼清气，不可拘先气后营常法。", ["数", "滑", "耎"]], "14055": ["病机", "脉弦而数，弦主肝阳，数主热。冬暖泄气，天令不主闭藏，雷声大震，人身应之，肝阳乃动，迫血上溢而鼻衄如注。投元参、生地、犀角、牡蛎等凉血潜阳，既而胁痛流乳，仍属肝热，续予甘露饮加女贞、旱莲、三甲而瘳。", ["弦", "数"]], "14056": ["病机", "脉滑数而沉，滑主痰，数主热，沉主里，为痰热遏伏于里；面赤苔黄、手足冷过肘膝、当脐硬痛、小溲涩少，皆伏热内闭、阳气不达四末之象，故断为伏热为病，非虚寒。", ["滑", "数", "沉"]], "14057": ["病机", "右部微有弦滑，弦主痰饮，滑主痰热，右部候肺脾，故为痰热实证；虽脉不甚有力，但苔黄腻、咽喉阻塞、饮食碍进，皆痰热壅阻之征，非肾虚水泛，故以苇茎汤清化痰热而痊。", ["弦", "滑"]], "14058": ["病机", "脉滑数有力，滑主血盛，数主热，有力为气实，故为气实血热；漏血、吐血、纳食即吐，皆血热妄行、气逆上冲所致，证不属虚，补药反助病，故用清营药而血止。", ["滑", "数"]], "14059": ["病机", "脉数舌绛，数主热，绛为阴伤，故属阴虚挟热；便血本湿热，温补反伤阴液，致泄泻浮肿，脉数舌绛正是热伤阴液之征，故用苦甘寒清热养阴而愈。", ["数"]], "14060": ["病机", "脉弦数而滑，弦主肝，数主热，滑主痰，为阴亏肝阳侮胃、痰热内蕴；误投温补涩滞，气机不降，故寒热气逆、自汗不寐、口渴善呕，治以肃肺和肝胃而安。", ["弦", "数", "滑"]], "14061": ["病机", "脉右部沉滑，沉主里，滑主痰，右部候气分，故为痰热结伏气分；苔黄不渴、溲如苏木汁，皆伏热之征，虽似伤寒而实非，故先解客邪，继清痰热而瘥。", ["沉", "滑"]], "14062": ["病机", "脉有滑数之象，滑主湿热，数主火，花甲之年溺后出血水甚痛，虽溲长激似非火证，然滑数之脉明示湿热火毒下注，故用苦甘寒清利而痊。", ["滑", "数"]], "14063": ["病机", "脉弦数，弦主肝，数主热，赤痢延久，苔黄渴饮、腹胀而坠、日热夜甚，为热邪大伤气分之阴、肝经热盛，故用白头翁汤合金铃子散清肝凉血而愈。", ["弦", "数"]], "14064": ["病机", "脉伏恶寒、四肢厥逆，似阴厥，但渴饮溲赤，知为热邪内郁，阳郁不达。脉伏如故，热深厥深。后脉显滑数，为热邪外透，痰热内盛之象。故主热厥，非虚寒。", ["伏", "滑", "数"]], "14065": ["病机", "右关尺弦大而滑，弦为肝热，大为热盛，滑为痰热内壅。腹中绞痛、便血如注、面红喘逆，皆肝热挟痰、迫血妄行之候。脉证合参，主肝热挟虚之热痧。", ["弦", "大", "滑"]], "14066": ["病机", "脉洪大，按腹如烙，为热蒸气分，阴虚阳亢。痰嗽气逆误服温补，致痰中带血、气喘而厥、二便不通，皆热壅肺胃、阴液受灼之象。洪大为阴虚，主热盛伤阴。", ["洪", "大"]], "14067": ["病机", "脉虚细，为阴虚挟热，阴血不足，脉道不充。两膝筋络酸痛不红肿，苔黄腻，咽燥溺赤，皆阴虚热蕴之候。虚细主阴亏，热邪内伏，故治以滋阴清热。", ["虚", "细"]], "14068": ["病机", "脉沉弦，沉为热结在里，弦为肝热挟虚。因惊得病，不言不食、不寐不便，乃惊则气乱，痰热内闭，肝热挟痰上扰心神。沉弦主里热结聚，故用开窍涤痰。", ["沉", "弦"]], "14069": ["病机", "脉至滑数，滑为痰热，数为热盛。患感十余日，耳聋不语、昏不识人、苔黄腻、遗溺便秘，皆痰热蒙蔽心包、热结阳明之候。滑数主痰热内盛，故以白虎汤清泄。", ["滑", "数"]], "14070": ["病机", "脉耎汗多，热不甚壮，苔厚腻，呕恶烦躁，痰多腿酸，显是湿温。脉耎为湿邪困阻，气机不畅，非虚寒。湿蕴化热，不可从表治，更勿畏虚率补，主湿温病机。", ["软"]], "14071": ["病机", "脉数大渴，汗多苔黄，为阴虚挟热，热炽肺伤。发热泄泻日久，骨瘦如柴，音嘶气逆，皆热盛伤阴、肺胃津亏之象。脉数主热，阴虚挟热，故以竹叶石膏汤加减。", ["数"]], "14072": ["病机", "脉滑实为胃腑热结之征。原文谓“脉系胃实”，热邪下行结实于胃腑，燥矢结于手阳明大肠，故腹胀口干；胃热上蒸则身面渐黄，下注则腿痛异常。清解后表热已清，而里实未去，脉滑实正是下证之凭，故予茵陈大黄汤便行而愈。", ["滑", "实"]], "14073": ["病机", "脉弦劲为心肝阳邪逆升、气机不降之象。原文谓“脉弦劲二语，皆心肝阳邪逆升”，肝阳勃升则左目胞起瘰、痛及眉棱额角颠顶、脑后筋掣；风剂助纣为虐，其势孔亟。舌绛不饥亦阳升阴伤之征，故用固本合二至桑菊犀羚等息风降气。", ["弦", "劲"]], "14074": ["病机", "脉滑数苔黄而渴，为肺胃热实之征。原文谓“脉滑数苔黄而渴，为肺胃热实”，热实故浑身生疖如疔、痛楚难堪；舌紫为兼挟瘀血，故用白薇行瘀。脉数为阴虚挟热，故以花粉石斛顾阴。小溲或秘或频、大便努挣不下，皆热实阴伤之候。", ["滑", "数"]], "14075": ["病机", "脉洪滑且数，为热盛于阳明、挟血分瘀热之征。原文谓“脉洪滑且数”，故壮热狂烦、目赤谵语、脘闷腹胀拒按、畏明口渴、气逆痰多；汛适至而热入血分，故欲刎欲缢。洪滑数主实热，故用桃仁承气加犀角石膏等大破其血、极寒清热。", ["洪", "滑", "数"]], "14076": ["病机", "脉虚细中兼有弦滑，乃阴虚挟痰之征。原文谓“脉虚细为阴虚中挟阳虚，脉兼弦滑，为正虚中兼挟肝经痰热”，故腰疼腿木、胸闷气逆不能卧；温补助肝阳则喘汗欲脱、杳不思谷。舌绛而渴亦阴虚之候，故用沙参苁蓉石斛等养阴化痰。", ["虚", "细", "弦", "滑"]], "14077": ["病机", "脉细涩是阴虚中兼挟阳虚之征。原文谓“脉细涩是阴虚中兼挟阳虚”，高年阴亏，伏暑伤液，加以燥烈之药，津何以堪，故舌绛无津、肢冷自汗、杳不进谷、脘闷腹胀、小溲牵疼。细涩主阴液亏耗，故用沙参银花苁蓉白芍石斛等滋阴生津。", ["细", "涩"]], "14078": ["病机", "脉迟微为阳虚之征。原文谓“辨阳虚在脉迟微”，阳虚故滞下色白不黏、不饥不渴、腹微痛而不胀；迟微主阳气衰微，故进大剂真武汤加参以温阳。色白不黏、不渴，皆无热象，与迟微之脉相应，故断为阳虚而非热痢。", ["迟", "微"]], "14079": ["病机", "脉细数为阴虚挟热之征。原文谓“察脉细数”，滞下五色并见、神昏肢搐、大渴茎肿、腹痛后热，危险异常，皆热毒炽盛、阴液耗伤之候。细主阴伤，数主热盛，故用白头翁汤加犀角生地银花石斛等清热解毒、养阴凉血，三剂后热退神清。", ["细", "数"]], "14080": ["其他", "原文述“脉象六阴，按之如无”，为纯描述，未给具体脉名。此案高年阴液亏虚，虽脉象极虚，但孟英凭证不凭脉，见舌绛无津、音嘶痰嗽，断为脏热由腑而出，用甘凉清润获效。说明脉症有时不符，当舍脉从证，不可拘泥于脉。", []], "14081": ["病机", "脉耎为湿邪困阻、阳气不伸之象，结合苔腻，断为伏暑所化，非正疟。暑湿内蕴，脉道不畅故耎。治以清暑化湿，忌风寒温燥，方用知芩滑斛花粉清暑，橘半朴杏省头草化湿，药后病若失。", ["耎"]], "14082": ["病机", "脉细为阴血不足，痰咸为肾虚水泛。久患痰嗽碍卧，素不投补，孟英凭脉断为阴虚水泛，非补不可。用熟地等滋填，一饮而睡。说明脉细与痰咸并见，主肾阴虚水泛为痰，治当滋水制火，不可妄用参术助气。", ["细"]], "14083": ["病机", "右脉洪滑，为暑热内盛、痰热壅肺之象。妊妇患疟，目不能瞑、口渴自汗、便溏气短，显系伏暑为病。洪滑主热盛，非正疟之脉。孟英据此断为伏暑，忌小柴胡之温燥，投竹叶石膏汤清解，四剂疟止。", ["洪", "滑"]], "14084": ["病机", "右脉大，为热邪亢盛之象。患儿目患内障，夜热痰嗽，溺多，医作童损滋补，病日甚。孟英凭脉右大、口渴苔黄，断为伏热在肺，法当清解。盖余热未净，补早则热壅，故脉大主肺中伏热，治宜清透。", ["大"]], "14085": ["预后", "左部数，右手俨若鱼翔。鱼翔脉为真元将竭、脉气散乱之危象，数主热盛阴伤。痰嗽气促、自汗瘛疭、苔灰渴甚，热炽阴涸，脉证俱危。孟英勉力救治，先清后滋，渐得脉数转清，示危候可挽，然鱼翔终属险候。", ["数", "鱼翔"]], "14086": ["预后", "脉至细数，细为阴亏，数为热炽。发热腰腿痛如刀割，苔黑燥，溺赤便黑，热邪深入少阴，真阴耗损。孟英用甘凉濡润，热退痛已，但舌绛无津，终因女劳复致真阴涸竭，脉细数主阴竭热炽，预后不良。", ["细", "数"]], "14087": ["病机", "脉甚滑数，滑主痰，数主热。患者多疑善恐、寡言善笑、遗精，皆肝经痰热内扰之证。痰热蕴结肝经，脉道滑利而数。孟英用清肝化痰之剂送当归龙荟丸，四剂即能出署，说明滑数脉主肝经痰热。", ["滑", "数"]], "14088": ["病机", "脉沉数，沉主里，数主热，为热邪内伏之象。原文述溏泄后误投温补，致发热昏痉、咽喉黑腐，乃伏邪自寻出路，温补固留，内陷厥阴，肝肾阴竭。脉沉数正是热伏于里、阴伤液涸之征，与昏痉舌黑相应，故断为不可救药。", ["沉", "数"]], "14089": ["病机", "脉沉弱而弦，沉为痰热遏伏，弦为肝热，弱为脾阳伤败。脘痛漉漉有声、便秘溲赤、口渴苔黄，皆肝阳侮胃、痰热内阻之症。脉弱示脾阳已伤，故用参以顾护，防苦寒过剂。此脉象揭示痰热遏伏而脾阳不振，虚实夹杂之病机。", ["沉", "弱", "弦"]], "14090": ["病机", "脉微无神，倦卧奄奄，便秘溺赤，痰多口甘，苔黑腻，乃精气神三者交虚之证。脉微为阳气衰微、神气不振之象，非时行伏暑晚发之实邪。原文以温补大剂投之，正合脉微无神所主之虚寒病机，故得渐愈。", ["微"]], "14091": ["病机", "脉滑为痰热内蕴之征。陈媪牝疟月余，腹胀便秘，嗳多不饥，口淡，脉滑，显系痰热阻滞中焦，气机不畅。口淡虽为胃阳不旺，然脉滑主痰热，故孟英主以连朴橘贝杏茹等清化痰热、宣畅气机，数剂即瘳。", ["滑"]], "14092": ["病机", "脉象弦驶，弦为肝阳偏亢，驶为脉来急疾，主阳升气逆。夜坐阳升，饮酒助肝阳浮越，复因惊争气上逆，故见心跳、气逆如喘、肢麻手握、语言难出。脉弦驶正是肝阳化风、气逆上冲之病机反映，故以苏合香丸辛香开窍降逆。", ["弦", "驶"]], "14093": ["病机", "脉虽弦细而有力，弦细本似虚象，然有力则非纯虚，乃痰热内阻、气机壅滞之候。截疟后浮肿，误用温补，致呃忒不休、气冲碍卧，饮食不进。脉弦细有力揭示邪实内郁，故孟英以栝蒌薤白合小陷胸等清化痰热、降逆和胃，四剂而瘳。", ["弦", "细"]], "14094": ["病机", "脉弦缓，弦为肝热，缓为肝热壅痰阻气。娩子不育，汛事未行，呕吐发热，眩晕心𩠎，溏泄口渴溲痛，皆肝风煽升、痰热阻遏气机之象。脉弦缓非娠非损，乃血虚痰滞而感冬温，故以羚羊、竹茹、白薇等清肝化痰透邪。", ["弦", "缓"]], "14095": ["病机", "脉细弱而口干，细为阴血不足，弱为阳气亦衰，腰膝酸疼更示肾虚。血痢日久，自秋徂冬，阴血耗伤，兼挟阳虚。脉证合参，为阴虚中兼挟阳虚之候，故用鹿角霜、苁蓉、枸杞、熟地等温养精血，佐砂仁、石脂涩肠行瘀，十余剂而痊。", ["细", "弱"]], "14096": ["病机", "脉沉弦而数，沉主里，弦主肝，数主热，提示热邪深锢肝经。原文见周身麻木、四肢瘫痪、口苦而渴、痰冷如冰、气逆欲呕、溺热如火、间有发厥，皆热结肝经、肺气不行之象。痰冷如冰非真寒，乃热邪深锢、肺气不宣所致，故以雪羹旋赭栀楝等清肝泻热而效。", ["沉", "弦", "数"]], "14097": ["病机", "右脉弦大而强，弦主肝热，大主邪盛，右部候肺胃，提示冬温挟痰、误提而气不肃降。原文见目瞪不语、面赤气逆、昼夜需人抱坐、四日不著枕，皆痰热壅肺、气逆不降之候。脉弦大而强，正合邪热壅盛、肺失肃降之病机。", ["弦", "大"]], "14098": ["病机", "右脉弦细芤迟，弦为肝热，细为阴虚，芤迟为阳弱，提示暑邪内陷、误补致邪盛正虚。原文见滞下色酱、日数十行、口渴溲涩、面赤自汗，乃吸受暑邪误作虚治，邪愈盛而正反虚。脉象虚实夹杂，正合暑热内迫、气阴两伤之病机。", ["弦", "细", "芤", "迟"]], "14099": ["病机", "左脉细软为血分阴虚，右脉滑数为暑邪壅遏气分。原文见产后患赤痢延久、肌消膝软、见食欲呕，乃伏暑为病，幸未误药。左细软示阴血亏虚，右滑数示暑热壅遏气分，故方中泻暑清气之药较多，送驻车丸而愈。", ["细", "软", "滑", "数"]], "14100": ["病机", "右脉洪滑，左脉弦数，洪滑主阳明腑实热盛，弦数主肝经郁热、阴分不足。原文见右手足不遂、舌謇不语、面赤便秘，为阳明腑实之候。脉象与症相符，故以通腑泻热、清肝化痰为治，急下黑矢而舌謇顿减。", ["洪", "滑", "弦", "数"]], "14101": ["病机", "脉至细数无伦，细为阴伤，数为热盛，无伦示脉律不齐、邪热深陷。原文见昏谵痉厥、两手拘挛、宛如角弓反张、痰升自汗、渴饮苔黄，乃温补致热陷心包、肝风内动。脉细数无伦正合热灼阴伤、风火相煽之病机，故以犀羚等清心凉肝而脉较和。", ["细", "数"]], "14102": ["病机", "脉弦滑而微数，弦主肝热，滑主痰盛，数主热，提示痰热内闭、肝风鸱张。原文见昏痉谵语、六昼夜不交睫、旬日不沾米饮、舌缩苔垢，乃升散温补谬治致痰热蒙蔽心包。脉弦滑微数正合痰热内盛、风火相煽之病机，故以犀角、竹沥、紫雪丹清心豁痰开窍。", ["弦", "滑", "数"]], "14103": ["病机", "脉滑而洪主阳明热盛，左尺细数而芤、右尺洪大示女劳复、阴精亏耗而热炽。原文见鼻衄数升、苔黄大渴，为热盛迫血；后昏沉欲寐、发热自汗、舌绛溺涩，为女劳复。脉象由洪滑转细数芤，反映热盛伤阴、阴精耗损之病机。", ["滑", "洪", "细", "芤"]], "14104": ["病机", "脉沉而弦，沉为热邪锢闭于内，弦为肝热亢盛。患者右胁痛、音喑、气逆如奔、便溺不行，皆肝热挟痰上逆、闭阻气机所致。温运药反助热势，故病益甚。脉象揭示热闭于里，非寒湿为患，当以清肝化痰、降逆通络为治。", ["沉", "弦"]], "14105": ["预后", "脉促歇止，为阴脉，见于阳证（满舌黄苔、大渴引饮、便秘），乃阳证阴脉，正气伤残，不任苦寒峻下。患者醉饱后复感，痰食壅滞化热，脉象示心气衰败、脏气不续，故预后危殆，终至胀裂而死。", ["促", "结", "代"]], "14106": ["病机", "右手洪大滑数，洪大主热盛，滑数主痰热内壅。症见呃忒苔腻、便秘痰多、心下拒按，为痰热结于心下，气机不畅。脉象与症相符，故予小陷胸汤加味清热化痰、宽胸散结，数剂而安。", ["洪", "大", "滑", "数"]], "14107": ["病机", "脉弦数而滑，弦主肝郁，数主热，滑主痰。患者目疾日久，渐至腹中痞胀痛不可当、便秘形消，乃肝郁痰滞，误补致邪壅。脉象示肝经郁热挟痰，故予金铃子散合雪羹吞当归龙荟丸、礞石滚痰丸，清肝泻火、逐痰通腑。", ["弦", "数", "滑"]], "14108": ["病机", "右脉洪滑，洪主热盛，滑主痰。症见痰嗽气喘、苔白滑、小溲不赤，乃暑邪薄肺，挟素有之痰阻遏治节，气机不行，疹不能达。脉象示暑热痰壅于肺，故温散大忌，凉血亦非，予竹叶石膏汤合苇茎汤清暑化痰、宣肺透疹。", ["洪", "滑"]], "14109": ["病机", "脉弦伏而滑，弦主肝，伏主气机郁闭，滑主痰。患者因惊骇致气乱，挟痰逆升，眩晕便秘，时欲昏厥。脉象示痰气交阻、逆而上冲，胸腹无胀闷，旬余不更衣，正合“诸厥应下”之旨，故予降逆化痰、通下痰气。", ["弦", "伏", "滑"]], "14110": ["病机", "脉沉弦，沉主里，弦主肝、主痛。患者腰腿串痛、闻声筋掣，苔腻便秘，乃痰热内蕴、肝风窜络，广服温补致剧。脉象示痰热深伏肝经，故予雪羹羚楝胆星等清肝化痰、通络，吞礞石滚痰丸及当归龙荟丸泻热逐痰。", ["沉", "弦"]], "14111": ["病机", "脉甚滑数，滑主痰，数主热。患者体厚痰多，扬掷谵妄，舌绛面赤，渴饮便涩，乃暑热挟痰内闭心包，热盛动风。脉象示痰热壅盛，故予大剂白虎加犀角元参等清暑凉营、化痰开窍，送滚痰丸泻热逐痰，脉证渐和。", ["滑", "数"]], "14112": ["预后", "脉细数，细为阴血亏少，数为虚热内扰。产妇乳多善饭，形瘦减餐，舌光绛，乃血化乳溢，精华尽发于外，阴血耗竭，虚热内生。脉证合参，属急劳危候，故曰“无以药为”，即日断乳亦不及，预后不良。", ["细", "数"]], "14113": ["病机", "脉数无伦，数而失序，为热邪炽盛、阴液耗伤之象。暑疟本宜白虎，却误用温补燥散，助邪烁液，故汗渴不已、狂乱如故。脉数无伦正是邪热鸱张、津液枯竭之征，非阳虚欲脱，故宜大剂白虎加花粉、洋参等清热生津。", ["数"]], "14114": ["病机", "右脉滑数上溢，滑主痰，数主热，上溢为肺胃之气壅塞不降。滞下本属暑热，误投术朴夏葛等温燥升散，烁阴液，致咽疼口糜、呃忒噤口。脉证参之，非阳虚欲脱，实为阴伤热壅、肺胃气逆，故予大剂肃清，一剂知，二剂已。", ["滑", "数"]], "14115": ["病机", "脉至洪数不清，洪为热盛，数为邪热，不清示热邪弥漫、阴液受灼。疟痢并作，寒少热多，面垢苔黄，干呕口渴，溺赤汗出，皆实热壅盛之候。洪数之脉主阴虚挟热，故方中参用花粉以顾阴，清热化湿并进。", ["洪", "数"]], "14116": ["病机", "脉弦而软数，弦主肝风，软为阴亏，数主热。患者阴亏肝盛，误用表散温补，升逆枢滞，痰饮交结，风阳肆横，故目瞪神呆、气喘舌绛、肢搐而厥。弦软数脉正示阴亏于下、风阳上亢、痰热内扰之机，治以息风镇逆、清热蠲痰。", ["弦", "软", "数"]], "14117": ["病机", "脉见弦数软滑，弦为风阳，数为热，软为阴亏，滑主痰。秋感服温散药而日重，苔黑肢瘈，乃温燥助热，阴液受灼，风阳挟痰上扰。脉象示阴亏热炽、痰风内动之机，故急予清凉息风、化痰养阴，次日脉较和，渐向愈。", ["弦", "数", "软", "滑"]], "14118": ["病机", "脉甚数，数为热盛。溲赤苔黄，口渴燥呛，病由暑湿，体极阴亏，已从热化。脉甚数正是暑热内炽、阴液耗伤之征，虽便泄不可温燥，故先轻清肃解，继甘凉撤热，终以滋填潜摄收功。", ["数"]], "14119": ["病机", "按之豁然，即脉来豁大中空，主血虚气弱。半产后发热有时，广服滋阴不愈，脉证合参，乃血虚阳浮，非阴虚内热。故投当归补血汤补气生血而热退，继以小建中调补中焦，以脉豁然为血虚之据。", ["豁"]], "14120": ["其他", "原文未录脉象，仅述俞子患感兼腹痛胀，温散后二便不行、昏谵大渴、舌苔黑刺，孟英用犀翘楝薄栀连花粉元参大黄下之而便下神清。案末明言「此证孟英用下，必有脉情可据，断非仅以证论」，可知脉象虽佚，其凭脉断实、因实而下的思路贯穿始终，属脉证合参而以脉定治之例。", []], "14121": ["预后", "久患痰嗽，孟英主滋水舒肝，本阴亏兼郁。误投温补后咳嗽复作、渐至咽痛，冬初诊得「六脉皆数」。数脉主热，阴亏之体而见六脉皆数，是温补助热、阴液受灼，水令当藏而反见数阳之脉，故断「其不能春乎」，果验。此以脉数见于冬令测阴竭阳越之预后。", ["数"]], "14122": ["病机", "朱妇屡患半产，孕后病嗽。孟英察「右寸脉滑大搏指」，右寸属肺，滑为痰实，大为阴虚火旺，痰热壅肺故咳逆。肺气壅则震动胞系，胎因之不固。孟英据此断为病气侵胎而非元气弱，故屏温补、纯予清肺，治病即所以保胎。脉滑大搏指正是痰实阴虚、肺壅胎动之病机所在。", ["滑", "大"]], "14123": ["病机", "花甲之年喘嗽，坐不能卧旬日，进参汤喘稍定而易汗，似虚欲脱。孟英察脉「弦滑右甚」，弦为肝热挟虚，滑为痰热，右甚则痰热在肺。痰热壅肺、肝热上逆，故喘不得卧；参汤助热恋痰，切勿沾唇。凭脉设治，以蒌薤旋覆苏子花粉蛤壳青黛海䖳清化痰热，脉象揭示痰热而非虚脱。", ["弦", "滑"]], "14124": ["病机", "许妇腿痛多噫气，搓指抹眉噫即不已，向以为虚服补不愈。孟英诊「脉弦滑」，断为痰阻于络、气不得宣，弦滑乃肝风煽痰之象。其媳因悲发厥、汛愆，脉「弦数以滑」，数主热，弦滑为痰挟风阳，故为痰挟风阳而为厥。两案皆以弦滑数脉定痰热风阳内动之病机，非虚证可比。", ["弦", "滑", "数"]], "14125": ["病机", "吴永言久服姜食，患大溢血后时时火升，服芩连则烦渴益甚，用生地即闷滞。孟英「按其脉，沉取滑数」，沉为热伏于内，滑数为痰热，断为从前积热深伏。故以白虎汤加减清透气分，恣服渐吐胶痰而愈。沉取始得滑数，正是积热深伏、气失升降之凭据，非浮取所能察。", ["滑", "数", "沉"]], "14126": ["病机", "原文未载脉象，专论蔗之性味。赵子循啖蔗即鼻衄，孟英谓蔗甘凉而甘味太重、凉性甚微，津虚热不甚者相宜，湿热痰火内盛者服之则化热。子循之体「水虚而火旺」，蔗性不能敌，反从其气化热，如蔗经火炼成糖。虽无脉文，然水虚火旺之体、甘凉化热之理，与脉学所主阴虚火旺病机相通。", []], "14127": ["病机", "李华甫继室娠三月而崩，孟英按脉「弦洪而数」。弦为肝热，洪为热盛，数主热炽，三脉合见，断为血因热而崩、胎因崩而堕。故用大剂生地银花茅根柏叶青蒿白薇黄芩续断驴胶藕节凉血安胎。后专科误执暴崩宜补，温药助热，虚象日著、汗出昏运，正反证弦洪数脉所主热崩之确。", ["弦", "洪", "数"]], "14128": ["病机", "脉弦涩，弦为肝郁，涩为血瘀，合之乃肝郁凝瘀之象。原文谓\"察血紫黯\"，血紫黯正是瘀血之征，与弦涩脉相应。陡吐狂血而肢冷自汗，阴伤阳亦随之，脉弦涩示阴中之阳已不能鼓舞，残阴无几，故虽可愈而复发难瘳，终至不起。", ["弦", "涩"]], "14129": ["主病", "脉滑实，滑主痰，实主热结。患者年逾古稀，气逆烦躁不寐，便閟面赤，舌绛痰多，皆气分热实之候。脉滑实正合痰热内结、腑气不通之机，故以承气汤下之而霍然。此脉实为攻下之凭据，非虚证所宜。", ["滑", "实"]], "14130": ["病机", "脉沉而涩，沉主里，涩主气机窒痹。体冷自汗宛似虚脱，然二便不通、脘闷苔腻，知非真虚，乃痰热为补药所遏，一身气机窒痹不行，故脉沉涩。此涩非血少，乃痰热壅遏、气不流畅之象，故以开降之剂复杯即减。", ["沉", "涩"]], "14131": ["病机", "左脉弦细而虚，右尺寸皆数。弦细而虚为肾脏阴亏，数则为阴亏气不潜纳。久患痰嗽、食减形消、寝汗舌绛，皆阴亏之候。前医杂用耆术助气、二陈故纸附桂劫阴，愈补愈剧。此脉示阴亏气不潜纳，故用熟地苁蓉坎板等滋阴纳气而愈。", ["弦", "细", "虚", "数"]], "14132": ["病机", "脉伏而弦滑。伏非虚脱，乃肝阳贼肺、肺气不行所致；弦滑为肝风煽痰之象。患者连服温散，劫阴动风，倏然昏厥，自寅正至辰初不苏，正当风木司令之时。脉伏而弦滑，正合阴虚风动、痰随风升之机，故以息风救液、清热涤痰取效。", ["伏", "弦", "滑"]], "14133": ["病机", "脉沉弦且滑，沉主里，弦主郁，滑主痰，合为痰热𫐖轕之象；舌绛黄腻苔、口苦溲热，皆痰热之征。误补则气机壅塞，故日剧。娩后脉极滑数，滑数仍主痰热，知病根未刈，非产后血虚，故蠲痰清气法果应。此脉始终示痰热内蕴，不可妄补。", ["沉", "弦", "滑", "数"]], "14134": ["预后", "右寸脉促数不调，促数主热盛而气机不调。风温初感，误予温散，热虽渐退而脉促数不调，示温邪内陷、肺热壅盛，故断其恐有骤变。越二日鼾睡，促数尤甚，果至语言难出。此脉为风温误汗之危候，仲圣所言不欺，预后凶险。", ["促", "数"]], "14135": ["病机", "脉见芤数，芤主阴血亏虚，数主热炽。患者烟瘾甚大，吸受温邪，胁痛筋掣、气逆痰多、热壮神昏、茎缩自汗、舌绛无津，皆阴虚阳越、热炽液枯之险候。芤数脉正合阴亏于内、热炽于外之机，故以壮水息风、潜阳镇逆、益气充津之剂取效。", ["芤", "数"]], "14136": ["病机", "脉虚弦为根蒂虚兼怫郁，虚为气阴不足，弦为肝郁；后脉微为寒邪直中，微主阳衰，寒邪直中三阴，故见吐泻腹痛、肢冷音嘶。脉兼虚耎为暑湿伤中，虚耎示正气不足而湿滞。全案脉象反映正虚与邪实交替，虚弦主本虚标实，微脉主寒盛阳微。", ["虚", "弦", "微", "耎"]], "14137": ["预后", "脉甚细数为真阴欲匮，细为阴亏，数为热炽，阴亏热灼故舌绛无津、讝语。药后囊肿消而脉象依然，细数不减，示阴液难复，邪热深伏，故断其不起。脉无起色即病本未拔，虽暂效终归不治。", ["细", "数"]], "14138": ["病机", "脉洪滑弦数为温邪化热，内迫营血。洪为热盛，滑为痰湿，弦为肝风内动，数为热急。温散误表，热迫营血则汛行，肝风动则狂妄。脉象依然示热邪未清，故仍以清卫凉营取效。", ["洪", "滑", "弦", "数"]], "14139": ["病机", "脉洪数七至为热邪炽盛，洪主阳明热盛，数主热急，七至示热极。温燥误补，热邪内壅，故壮热神昏、洞泻如火、小溲不行。洪数脉应热盛，故用白头翁汤加石膏犀角等大剂凉解，脉证较减。", ["洪", "数"]], "14140": ["预后", "脉甚迟缓非脾阳虚，乃痰阻气机，缓为湿痰壅滞，迟为气机不利。后脉形滑驶如蛇，滑为痰，驶如蛇为真脏脉见，示胃气已败，故断其不起。前缓为痰阻可治，后滑驶为元气将绝。", ["缓", "滑"]], "14141": ["病机", "脉弦软而数为肝火挟痰，弦为肝阳，软为痰湿，数为火旺。温补助火，肝阳侮胃，故心辣如焚、善嗔畏热、饮食下咽即吐。弦软数示肝火痰热内蕴，故用清肝化痰降逆取效。", ["弦", "软", "数"]], "14142": ["预后", "脉甚弦滑为痰热内蕴，弦为肝风，滑为痰，舌光绛示阴伤。温补助痰热，肝风暗动，故发肿不饥。后脉数七至，数急为热极阴竭，眠食尽废，故不可救药。弦滑可治，数七至为死候。", ["弦", "滑", "数"]], "14143": ["病机", "脉洪实滑数为实热挟阴虚，洪为热盛，实为邪壅，滑为痰湿，数为热急。热毒上攻则目赤面肿，内扰则壮热神昏。洪实滑数示实热壅盛，故用大黄犀角等两下之，热清则愈。", ["洪", "实", "滑", "数"]], "14144": ["病机", "脉滑实而数，滑主痰，实主邪盛，数主热，合为痰热内盛之象。患者寒少热多、面目黄、苔腻大渴、腹胀溺赤，且嗜肥甘，显系膏粱挟暑湿热，病在气分。脉实数为邪热壅盛，滑为痰湿，故以承气加清热化痰之品泻实，二十余剂始愈。", ["滑", "实", "数"]], "14145": ["病机", "脉沉弦而细，沉主里，弦主肝风，细主阴亏。患者禀属阴亏，卒闻惊吓，气逆肢冷、自汗息微、身面青绿，乃素伤忧虑而风阳陡动，阴亏于下，阳扰于上。脉沉弦细正合阴亏风动之机，故用介类潜阳、滋养熄风而效。", ["沉", "弦", "细"]], "14146": ["病机", "脉滑且数，为痰热内盛；脉弦细数，为阴亏风动。陈书伯弟失音咽痛，脉滑数，口大渴，属热痰壅肺，故用大剂清肃而愈。其庶母喉糜头痛、心悸欲呕、壮热烦躁，脉弦细数，乃兼阴亏风动，故以犀羚清肝、滋阴潜阳而瘳。", ["滑", "数", "弦", "细"]], "14147": ["病机", "脉数而弦，数主热，弦主肝阳。患者形瘦、口渴音微溺涩，阴分极虚，肝阳炽盛，伏暑为痢。脉数弦正是阴虚阳亢、暑热内迫之象，故用白头翁汤加苦寒泻暑、顾阴潜阳，痢减音开，继以介类潜阳而痊。", ["数", "弦"]], "14148": ["病机", "脉迟缓，浮取甚微，非虚寒，乃暑湿内伏、燥矢在胃，气机不利，邪热升浮，故脉道不利而迟缓。患者便溏后热不退、静卧不食、目眵舌光红、口不渴、溲行、胸腹无苦、语懒音低，皆暑湿内伏、燥矢在胃之情状，下燥矢后脉证即减。", ["迟", "缓"]], "14149": ["病机", "脉虽沉伏难寻，而苔黄腻、口干溺赤，当从证舍脉，为湿热内闭、气机不通，故脉沉伏。钱妪脉弦滑，弦主肝热，滑主痰，为肝热煽痰贼胃，故用当归龙荟丸泻肝清痰而安。两案示脉不可执一，须脉证合参。", ["沉", "伏", "弦", "滑"]], "14150": ["病机", "脉细数，细主阴亏，数主热。朱妇小溲涩痛，渗利后反发热头痛、不饥口渴、夜不成眠，乃阴虚肝郁，化热生风，津液已烁。脉细数正合阴亏热炽之机，故用白薇、栀子、知母、花粉等清热养阴，忌再渗利。", ["细", "数"]], "14151": ["病机", "脉细而弦滑，细为阴亏，弦滑为痰热风阳内鼓。吴媳崩后脘痛发厥、自汗肢冷，口苦便涩，病不在血，乃素体多痰、风阳内动。后卒惊发狂，脉弦滑而数，数主热，弦滑主风痰，故息风阳、涤痰热而安。", ["弦", "滑", "数", "细"]], "14152": ["病机", "脉洪数，洪为热盛，数为热急，显系热实阴虚、肝风逆上之候。原文“胸腹痛极、昏厥咽糜、水饮碍下”皆风阳逆干肺胃、热灼津伤所致。洪数之脉主热实，与舌绛燥相合，说明温补酿热、阴液受灼，故用犀角、元参等清热存津息风。", ["洪", "数"]], "14153": ["病机", "脉弦而滑，弦为肝旺，滑为痰热；后脉弦数倍常，数主热盛。原文“舌绛口干”“善怒不眠、苦渴易饥”皆阳旺气血有余、肝热痰扰之象。高年久患淋漏，温补酿病，故脉弦滑数反映阴虚阳亢、痰热内蕴，治当清肺蠲痰柔肝充液。", ["弦", "滑", "数"]], "14154": ["病机", "脉甚弦耎，原文自注“脉弦为阴虚肝热，脉耎为阴中之阳虚”。弦主肝风内动，耎主阳虚不摄，故见“少腹宿瘕攻痛”“便泄而厥”。此脉说明阴虚肝热兼阳虚，风阳逆上而根蒂不固，故用龟板、石英潜镇，苁蓉、归身温养。", ["弦", "耎"]], "14155": ["病机", "脉弦滑，弦为肝风，滑为痰热。原文“胎前伏暑，乘新产血虚痰滞而发”，故见发热痉厥、谵语昏狂。弦滑之脉主风阳挟痰热内煽，恶露仍行示血虚未脱，治当息风阳以涤痰热，用犀羚、元参、竹叶等清透。", ["弦", "滑"]], "14156": ["病机", "初脉滑，为痰实；后脉极细数，细为阴虚，数为挟热。原文“目赤便秘，胸下痞塞如柈”，自注“阴虚痰实”“便秘胸痞皆胃实”。滑主痰，细数主阴亏热扰，说明痰饮为患误补致壅，故见眠食皆废、闻声惊惕，治宜清化痰热兼养阴。", ["滑", "细", "数"]], "14157": ["病机", "脉甚滑数，滑主痰湿，数主热盛。原文“温补所酿之疾”，秋痢失清，湿热逗留，孕后峻补致肺胃下行之令逆升，故“脘痛拒按、痰嗽不食、苦渴无溺、目赤障满”。滑数脉说明痰热壅盛、气机逆闭，治当清肃肺胃、化痰降逆。", ["滑", "数"]], "14158": ["病机", "脉弦细，原文自注“脉弦为肝热，脉细为阴虚中兼挟阳虚”。弦主肝热内郁，细主阴血不足，故见“腹痛不饥、水饮不沾、沉沉如寐”。误予参附姜术温补，致疼胀日加，脉弦细说明肝热阴虚兼阳运不健，治当清肝通降。", ["弦", "细"]], "14159": ["病机", "右寸沉滑，左脉细数而弦。沉滑主痰邪内闭肺络，细数弦主阴亏热扰。原文“痰嗽碍眠”“涕泪全无、目闭不饥、二便涩滞”，乃高年阴亏、温邪在肺为补药所锢。沉滑说明肺痹痰阻，细数弦示阴虚肝热，治宜开痹通胃、清化肺邪。", ["沉", "滑", "细", "数"]], "14160": ["病机", "脉弦缓而滑，弦主肝风，缓主湿，滑主痰，合之则肝风内动，痰湿伏而未化。症见颧赤苔黄、音微舌謇、便涩无痰，正是痰浊蒙蔽清窍、风阳上扰之象。孟英断为“痰中也，伏而未化”，故以犀羚息肝风，茹贝菖夏化痰浊，花粉知母清熱，桑枝丝瓜络通络，药后苔化音朗、痰吐便通，脉证相应。", ["弦", "缓", "滑"]], "14161": ["病机", "脉滑数，滑主痰，数主热，合之则痰热内蕴。患者向患痰嗽，屡发寒热，舌绛苔黄，渴饮溲赤，动则喘逆，夜不成眠，痰多畏冷，显系膏粱酿痰、温补助热，又吸暑邪，痰热互结，枢机不利。孟英谓“膏粱酿痰，温补助热，是为病根”，故以羚羊、豆豉、连翘等清透暑热，竹茹、贝母、旋覆等化痰降逆，热退痰化而安。", ["滑", "数"]], "14162": ["病机", "左手脉如无，右弦耎按之数。左脉如无，乃肝血大去、阴分久亏之征；右弦耎而数，弦为风阳陡动，耎为正气不足，数为热。高年阴亏，复因忿怒及服热药，致风阳暴升，血随气逆，故骤下黑血、大吐鲜红，汗出神昏、肢冷搐搦。孟英谓“肝血大去，风阳陡动”，治以救阴息风、凉血止血。", ["弦", "耎", "数"]], "14163": ["病机", "脉犹弦滑，弦主肝风，滑主痰热。患者素患喘嗽，本元久亏，春温误投温补，致痉厥神昏、耳聋谵语、面青舌绛、痰嗽不眠，显系温邪内陷，痰热蒙蔽，肝风鸱张。孟英断“证虽危险，生机未绝”，以犀羚、元参、石膏清热息风救阴，佐苁蓉、石英、鳖甲潜阳镇逆，贝母、竹沥通络蠲痰，脉证合参，故得转危为安。", ["弦", "滑"]], "14164": ["病机", "脉坚体厚，坚为阳实，体厚为形盛。阳热内实，肝风升腾，周身之气不降，故溺秘欲死。口渴苔黄，亦为热盛之征。孟英谓“脉坚则阳实，阳实则能任苦寒”，故径投知柏栀楝犀苑蒌茹之苦寒，送当归龙荟丸，直折肝经实火，内风靖而溺通。此脉坚为辨证眼目，示人实证可攻。", ["坚"]], "14165": ["病机", "右寸脉耎滑，耎主正虚，滑主痰实。右寸候肺，肺虚而痰贮于络，故嗽而卧难偏左。孟英断为“肺虚而痰贮于络”，以苇茎、丝瓜络、生蛤粉、贝母、冬瓜子清肺化痰通络，玉竹、枇叶、燕窝、梨肉润肺养阴，虚实兼顾，果愈。此脉耎滑并见，正虚痰实之机昭然。", ["耎", "滑"]], "14166": ["病机", "脉弦滑而数，弦为肝热，滑为痰盛，数为阴虚挟热。患者患疟，脘闷便秘，合目汗出，口渴不饥，乃温邪挟素盛之痰所化。或虑高年欲脱，孟英断“补药断不可投”，以知芩蒌杏翘贝旋茹连斛雪羹清化痰热、养阴透邪。合目汗出为阴虚阳浮，阴不复则阳不靖，故用石斛、雪羹滋阴潜阳，服果渐效。", ["弦", "滑", "数"]], "14167": ["病机", "脉弦洪而芤，弦为肝热，洪为热盛，芤为阴血亏虚。患者年逾花甲，陡患鼻衄不止，面黑黯而有红光，询知冬间广服助阳药，显系热亢阴虚之质。孟英谓“脉情为热实阴虚”，热迫血溢，风升而肝血随之，故以犀角、元参、茅根、女贞、旱莲、石斛等救液息风、凉血止血，投匕而安。", ["弦", "洪", "芤"]], "14168": ["病机", "脉弦洪豁大，左手为尤，乃真阴素亏、心阳外越、内风鸱张之象。弦为肝风，洪大为阳越，豁大示阴不敛阳。症见大渴大汗、能食妄言、面赤足冷、彻夜不瞑，皆阴虚阳浮、风火升腾之候，故主病机为阴亏阳越、内风动越。", ["弦", "洪", "大"]], "14169": ["病机", "脉甚弦洪滑数，弦主肝热，洪为阴虚挟热，滑数主痰热内壅。症见壮热、肢瘈面赤、呕吐苔黄、渴而溺清、昏厥、心下拒按、便秘汗多，显系痰热全在肺经气分，兼阴虚挟热，故脉象主痰热壅盛、肝风内动之病机。", ["弦", "洪", "滑", "数"]], "14170": ["病机", "左脉弦细而数，右耎滑。弦细数为血分阴虚、心火炽、肝风动；右耎滑为痰盛于中。症见烦躁不眠、狂妄瘛疭，乃阴虚火旺、肝风挟痰上扰。脉象揭示阴虚为本、风火痰为标之病机。", ["弦", "细", "数", "滑"]], "14171": ["病机", "脉细而弦，细为阴虚，弦为肝风。患者素患肝厥，仲夏患感，大便泄泻，渴饮痰多，不饥不寐。不饥不寐为热炽阳浮、肝风暗动之征。脉细弦正合阴虚肝风内动之病机，故主病机为肝风暗动、阴虚阳浮。", ["细", "弦"]], "14172": ["病机", "脉滑而弦，滑主痰，弦主阴虚挟热。症见间疟寒少热多、不饥大渴、善呕无汗，皆阳升不降、阳郁不达之象。脉滑挟痰，脉弦为阴虚挟热，故主病机为痰热内蕴、阴虚阳郁，肝胃不和。", ["滑", "弦"]], "14173": ["病机", "脉弦细而数，弦数为阴虚挟热，细为阴虚兼挟阳虚。症见腹胀减餐、牙衄腿痛、肌肉渐消，乃肝气虽滞而阴虚营热，肝阳侮胃、肝风消烁。脉象主阴虚营热、肝气郁滞之病机，非辛通温运所宜。", ["弦", "细", "数"]], "14174": ["病机", "脉芤而弦数，芤主阴血大亏，弦数为阴虚挟热。患者久患脚气，周身筋掣、龈痛齿麻、腰酸目眩、口干食少、夜不能眠，皆真阴大亏、筋骨失濡之候。因带下太甚，阴液漏泄，故脉芤弦数主阴虚液脱、虚风内动之病机。", ["芤", "弦", "数"]], "14175": ["病机", "左洪数，右弦滑。洪数为阴分虽虚而阳热偏亢，弦滑为肺胃痰热内壅。症见龈痛、身面浮肿、气逆不饥，乃痰热阻遏、肺胃失降。脉象主痰热壅盛于肺胃、兼阴分不足之病机，故先清痰热，继佐滋阴。", ["洪", "数", "弦", "滑"]], "14176": ["病机", "脉甚数主热盛，结合寒热、咽痛、大渴、脘闷舌绛，为阴虚风炽、热毒内燔之象。数脉为热邪鼓动，热盛则寒热咽痛，阴伤则大渴舌绛，故径投大剂犀羚元参丹皮桑栀银花花粉翘蒡以清热凉营、息风救液。", ["数"]], "14177": ["病机", "脉洪而数，洪为热盛，数为阴虚挟热。年近五旬天癸已绝，温补后病剧而崩，渴饮苔黄，是吸受暑邪、温补助热，暑邪挟肝阳由气侵营，迫血下漏。洪数脉正合阴虚热炽、血热妄行之机。", ["洪", "数"]], "14178": ["病机", "脉弦数左溢，弦为肝旺，数为热，左溢示肝阳勃升。忿怒而肝阳上逆，故腹痛欲厥、便閟不饥、口苦而渴。前医镇逆通补反剧，正因未识弦数左溢为肝阳化热、阴虚挟热之象，故以雪羹栀楝旋绛等息风肃肺、下左金丸而愈。", ["弦", "数"]], "14179": ["病机", "脉形细数，细为阴伤，数为热。间疟误用首乌鳖甲姜枣参桂温补，致狂躁妄言、面赤舌绛、溲涩便溏、渴饮汗多，是温补助热灼津，暑热内炽而阴液耗伤。细数脉正示暑证阴伤热盛，故以元参银花知芩茹贝等救液息风。", ["细", "数"]], "14180": ["病机", "右寸关弦滑而浮，为痰实于上；左关尺细耎无神，为阴虚于下。痰嗽喘逆、便閟不眠、微热不饥、口干畏热，皆阴虚于下、痰实于上、微兼客热之候。弦滑主痰，浮主上焦，细耎主下虚，故以清上滋下、浊药轻投为治。", ["弦", "滑", "浮", "细"]], "14181": ["病机", "脉象弦细耎数，弦为肝郁，细耎为肾虚，数为热。素属阴亏、情志抑郁，远行持重后咳逆胁痛、杳不知饥、卧难著枕，苔腻痰黏、便艰涩少，乃肾气不纳、肝气不舒、肺气不清、胃气不降。弦细耎数正合肾虚肝郁之机。", ["弦", "细", "耎", "数"]], "14182": ["病机", "脉涩口干，涩为营阴亏耗、血行不畅，口干为热灼津伤。怀妊患感，昏谵不语、善呕便秘、汗出不解，是营阴素亏、邪热内炽，热扰神明则昏谵，热结津伤则便秘口干。涩脉正示营阴不足而邪热内陷，故以元参石膏知芩等清热救阴。", ["涩"]], "14183": ["病机", "脉至洪滑，洪为热盛，滑为痰实。两目肿痛不能张，误投风药后昏痉欲厥，大渴便秘，是热盛痰壅、阳明热炽之候。洪滑脉主实热内盛，热灼津伤则大渴便秘，热扰神明则昏痉，故以白虎汤清泄阳明而霍然。", ["洪", "滑"]], "14184": ["主病", "脉滑而长，滑主痰热内盛，长主邪热炽张，疟发寒微热甚旬余，正合阳明气分热盛、痰热内蕴之机。前医虽用白虎汤名，然石膏少且煨、不去米，药力大减，故无效；孟英重用生石膏、知母、花粉，清阳明气热兼化痰，脉滑长为实热痰盛之应。", ["滑", "长"]], "14185": ["病机", "脉弦滑，弦为阴虚肝热、肝阳上扰，滑为痰热内蕴。眩晕脘痛、筋掣吐酸、渴饮不饥、咽中炙脔，皆肝阳侮胃、胃气不降、痰热阻络之候。温胃药反剧，因温燥助肝阳痰热。孟英以茹贝萸连旋赭栀楝清肝降逆化痰，正合弦滑所主之阴虚肝热、痰热内阻病机。", ["弦", "滑"]], "14186": ["病机", "脉滑数而溢，滑主痰热，数主热盛，溢为热势上涌、气逆不降。怀娠患感，温散劫津，致气冲不寐、欲痉厥、脘闷渴难受饮，乃肝胃热炽、痰热上逆、津液被劫之机。孟英以小陷胸加旋薤石膏知栀茹杏等清化痰热、降逆和胃，正对滑数而溢之痰热上溢病机。", ["滑", "数", "溢"]], "14187": ["病机", "脉来弦涩而数，右寸关弦耎以滑。弦数主热，涩主络脉瘀滞，滑主痰邪。误服温补，升降之令久窒，痰邪袭于隧络，故胁痛畏风、周身络胀、食少便难、日晡寒热。弦涩数示热郁络滞，右寸关弦滑示痰阻上焦，关格之势将成，故以凉润清通涤痰调升降为治。", ["弦", "涩", "数", "滑"]], "14188": ["病机", "脉浮弦洪滑，浮主暑邪外袭，洪滑主热盛痰壅，弦主肝风。年近六旬类中，遗溺痰升、昏瞀妄言、汗多面赤，乃吸受暑邪、连日服参汤温补助热，肝风煽痰逆升而厥。浮弦洪滑正合暑热挟痰、肝风上逆之机，故以羚角菖蒲连翘栀桑菊等苦甘寒息风救液、清热化痰。", ["浮", "弦", "洪", "滑"]], "14189": ["病机", "脉弦数，弦主肝阳，数主热盛。饱啖羊肉面条后腹痛，医误消导、叠投燥烈，致痛甚而渴、得饮大吐、二便不行，乃温药伤阴、肝阳逆上、阴津将涸之机。弦数正是肝热阴伤之应，故先以大剂雪羹频灌救阴，继以栀连楝斛茹芩知母等清肝养阴、降逆通腑。", ["弦", "数"]], "14190": ["病机", "脉至弦数，重按少神。弦数为热，重按少神示阴虚阳越、根本不足。年七十七患间疟，寒甚微而热必昏痉、舌不能伸、颧赤目垂、鼻冷额颏微汗、苔黄腻舌根纯红、口渴痰多，证属伏暑挟痰而阴虚阳越。弦数主热与肝阳，少神主虚，故先以苁蓉鳖甲楝斛茹贝燕窝藕养阴潜阳、清化痰热。", ["弦", "数"]], "14191": ["病机", "脉沉弦而缓，沉弦为肝热遏伏于里，缓非脾阳衰弱，乃痰浊阻气、脉道不利之象。外寒须复重衾、内热饮不解渴、温散即显咽痛，为痰热内伏、内风已动。沉弦示热郁于里，缓示痰浊阻气，故以犀羚元参丹皮白薇黑栀茹贝旋蒡清肝凉血、化痰透热，两帖而减。", ["沉", "弦", "缓"]], "14192": ["病机", "左脉弦数为阴虚挟肝热，右脉滑溢为风阳煽痰逆上。患者年近古稀，肢厥头肿、讝语遗溺，前医误作虚风温补而剧。弦数主肝热阴亏，滑溢主痰热内壅、风阳上逆，故病机为痰热内阻、风温外侵，治当息风阳、涤痰热。", ["弦", "数", "滑"]], "14193": ["病机", "脉皆细数，为真阴素亏、营液受灼之象。虽便溏不食，然脉证八句皆实热见证，细数非虚寒，故不必畏滋腻。经清滋治疗后脉渐和，示阴液渐复。脉来弦缓为病退之机，终获痊愈。", ["细", "数", "弦", "缓"]], "14194": ["病机", "脉弦滑右甚，弦主肝郁，滑主痰热，右甚则痰热偏盛于肺胃。患者三疟后胸中痞结如柈、苔黄苦渴、溲如热汤、带下如注，皆痰热内蕴、气分侵营之征。故先以陷胸合温胆豁痰清热，痰去则疟渐罢。", ["弦", "滑"]], "14195": ["病机", "脉虚弦豁大，虚为阴血不足，弦为肝逆，豁大为阳气浮越不敛。患者娩后恶露日久，复遭悲忧，干嗽吐血、头痛偏左、不饥不食不眠不便，乃阴虚肝逆、肺胃不降、阴中之阳亦虚。治以甘麦大枣合滋阴潜阳，服后脉渐敛、血止。", ["虚", "弦", "大"]], "14196": ["病机", "脉弦缓而滑，原文自注弦缓在浮分、滑在沉分，故为痰热窒塞肺胃之象。患者感后疹退而神气不爽、舌黑难伸、太息便秘、胸次拒按，皆痰热内结、腑气不通。脉证合参，故用凉膈散硝黄以下痰热，一帖苔退黄，再服下黑矢而神清。", ["弦", "缓", "滑"]], "14197": ["病机", "左脉弦洪而数为阴虚挟热、肝阳上浮，右脉滑而溢为痰挟风阳、肺气不降。面赤不眠、烦躁谵语、口甘渴腻、溲涩而痛、胸痞便闭，皆痰热阻痹、邪乃逗遛。治以陷胸温胆雪羹涤痰热，即所以息风阳，胸结渐开而谵语止。", ["弦", "洪", "数", "滑"]], "14198": ["病机", "左脉弦数为肝脏阴虚挟热，右脉虚耎为气分阳虚。患者梦遗久治不愈，耳出脓水、目泪难开、肩胁胸背酸疼、微有寒热、食减神疲，乃阴虚阳弱、肝热上扰。故以三才封髓加龙牡黄耆桑丹栀菊，双补气阴、潜镇肝阳。", ["弦", "数", "虚", "耎"]], "14199": ["病机", "脉甚弦涩，弦主肝郁，涩主血瘀。患者头震由肝经郁怒火升，溺閟腹胀、喘汗欲绝、口苦苔黄、舌色紫黯，汛虽不愆而内有瘀滞。弦涩与舌紫黯相合，确为瘀血内阻、气机不通，故以雪羹加金铃旋覆桃仁等化瘀通滞，仍吞龙荟丸清肝。", ["弦", "涩"]], "14200": ["病机", "脉弦滑洪数，不为指挠，为痰火壅盛之象。弦主肝风，滑主痰，洪数主火热。痰火内扰，蒙蔽心包，故见坐卧不安、如畏人捕、神躁妄闻。此脉证实为痰火内盛，与疑惧、躁妄等症相应。", ["弦", "滑", "洪", "数"]], "14201": ["病机", "脉迟涩，为病在血分，营血瘀滞；转为弦滑，乃痰热内蕴。迟涩非寒，乃热郁血分，故见筋掣不眠、喉舌皆赤。后脉来一息一歇，为暑湿内伏，挟痰阻肺，气壅不行，非虚脱之候。", ["迟", "涩", "弦", "滑"]], "14202": ["预后", "原文未明确脉象，但言“心脾之脉尚有根”，为可望之兆。体弱汛多，血虚肝风暗动，冷汗气逆，为肝阳逆厥。参耆屡进则肝风愈炽，故用介属重镇。脉有根则预后尚可，与危候相应。", []], "14203": ["病机", "舌绛脉数，为热毒内盛之征。数脉主热，舌绛为营分热盛。斑疹之候，断非受寒，乃热毒炽盛，迫及营血。火势甚炽，故一路清凉，自发起至落痂，毫不杂温升攻托之药。脉数与斑疹、便秘、渴饮等症相应。", ["数"]], "14204": ["病机", "右脉洪滑，为痰热内盛，故善饥善怒、骂詈如狂。脉弦而缓，非虚也，乃温补窒气，气机不畅。弦主肝，缓主湿，为痰气交阻。通络涤痰则瘥。脉证与神呆、狂躁、肢冷颤等相应。", ["洪", "滑", "弦", "缓"]], "14205": ["病机", "自汗脉涩，为肝风逆上，窒遏气机，营血不畅。涩脉主血瘀气滞，非虚脱。咽痛龈肿、牙关不开，皆风火壅盛。升散之药反助其势，故以犀羚射干等清肝熄风、解毒利咽。脉涩与绝谷濒危相应。", ["涩"]], "14206": ["病机", "脉弦数，为足厥阴暑疟。弦主肝，数主热，肝风炽逆，暑热内蕴。泛泛欲呕、口苦不饥、凛寒头痛、溲热如火，皆肝风暑热之现证。汛事愆期，为热扰血分。脉弦数与诸症相应。", ["弦", "数"]], "14207": ["病机", "脉滑实而数，为湿温化热，痰热内结。滑主痰湿，实主邪盛，数主热。壮热昏狂、大渴溲赤、稀水旁流，皆湿热壅盛之象。医但知湿甚，不知化热，投平胃散反助热。脉滑实数与危候相应。", ["滑", "实", "数"]], "14208": ["病机", "脉细数而体瘦，细为阴亏，数为热邪。患者平昔阴亏，热邪借风药披猖，营液得温燥而干涸，故见蓝斑、昏狂遗溺、大渴不已。此脉示阴亏热炽，非湿邪，误用温散则剧。", ["细", "数"]], "14209": ["病机", "脉甚滑数，滑主痰，数主热。苔色腻黄，乃平素多痰兼吸暑热。暑脉颇类乎虚，痰阻于肺呼吸不调又与气虚短促相似，故脉虽类虚而实为痰热壅遏，当先清暑热以顾元虚。", ["滑", "数"]], "14210": ["主病", "脉弦而滑，弦主湿热郁滞，滑主痰湿。溲涩苔黄，虽属高年，非虚证也。湿热下注则脱肛，脉弦滑为湿热内蕴之征，故以清其湿热而痊。", ["弦", "滑"]], "14211": ["病机", "脉颇平和，而滞下昼夜百余行，不饥不渴，欲呕腹痛上及心胸，是寒湿内阻，非时行暑湿痢。脉平和者，寒湿未化热，正气未大伤，故投姜桂萸朴温化而霍然。", ["和平"]], "14212": ["病机", "脉滑数，苔黄溲赤，脘闷善呕，为伏暑内蕴，痰热交阻。滑主痰，数主热，暑热伏于内，故畏冷不饥而脉滑数，投竹叶石膏汤清伏暑而痊。", ["滑", "数"]], "14213": ["病机", "脉皆滑，滑主痰热；继则脉弦而数，弦主内风，数主热。伏暑挟痰热蒙蔽包络则昏狂谵语，挟内风鸱张则头痛如劈、神识昏瞀，故以清暑化痰熄风为治。", ["滑", "弦", "数"]], "14214": ["病机", "脉弦滑而搏指，右手较甚，渴喜冷饮，小溲如沸，夜不成眠，全系痰热窒肺。久服滋阴是肺病治肾，故无效。弦滑搏指为痰热壅盛之实象，投苇茎汤合雪羹加清化而痊。", ["弦", "滑"]], "14215": ["病机", "脉弦滑，脘下聚气，疟久不痊，形消不食，医谓虚而投补更增自汗。弦滑主痰结内聚，非虚证也，故以小陷胸加竹茹旋枳开痰结，渐能纳谷，继以清养而病去肌充。", ["弦", "滑"]], "14216": ["病机", "原文仅言「按其脉尚不绝」，未及具体脉象，故脉素从缺。然「脉尚不绝」说明胃气未绝、生机尚存，与「面色灰黯、戴眼口开」之痰闭昏厥相应，属痰中闭窍而正气未脱。孟英以苦辛香开痰、牛黄至宝丹灌之，复杯而起，正取脉不绝为可治之凭，示痰闭非脱。", []], "14217": ["病机", "脉弦细而左寸右尺甚数、右寸关急搏不调，弦主肝郁、细为营津受烁，数急则内伏积热久锢深沉、温补煽动之象。原文谓「营津受烁，肉削痰多，升降愆常，火浮足冷」，脉与颈垂气促、舌黯面黧相合，故主内热锢结、痰火错杂之病机，非单纯外感。", ["弦", "细", "数", "急"]], "14218": ["病机", "脉左缓滑、右耎迟，缓滑为湿盛痰聚、耎迟则胃阳素弱。原文述「生冷伤乎胃阳，肝木乘虚」「湿盛为痰，温药相投……积温成热，反助风阳」，脉象正映痰饮踞中、肝升太过而胃降无权之机，久则气阻血瘀、元虚散漫，故主痰瘀互结、虚实错杂之病机。", ["缓", "滑", "耎", "迟"]], "14219": ["病机", "左脉如昨兼弦、右寸转缓滑，弦为风阳浮动、缓滑示痰浊渐化。原文谓「中脘气渐下降」「升降愆常，枢机窒涩，由乎风阳浮动，治节横斜，肺既不主肃清，一身之气皆滞」，脉由急搏转缓滑，正是气行浊降之征，故主肺气壅滞、风阳夹痰之病机渐松。", ["弦", "缓", "滑"]], "14220": ["病机", "脉稍和缓，较前急搏之象已减，为痰热渐涤、气机渐顺之应。原文「腿凉便滞，气少下趋，颧面时红，火炎上僭，两胁较热，络聚痰瘀」，叠授清宣后更衣色黑、噫罢呕止、纳谷颇增，脉缓正合浊降火敛之势，故主痰瘀渐化而余热未清之病机。", ["缓"]], "14221": ["病机", "脉渐柔和，承前数诊急搏弦滑之后，示痰火渐平、胃气来复。原文「各恙皆减，眠食渐安，火犹易升，头痛面赤，颈酸结核，胁热未蠲」，脉柔而症减，惟火升结核未净，故主痰热余邪未尽、正气渐复之病机，法转清养，去苦寒而加银花贝母黄菊。", ["柔"]], "14222": ["病机", "右寸脉洪大，洪为热盛、大为邪实，右寸候肺，故原文断为「春温也，乘其初犯，邪尚在肺」。发热面赤、渴而微汗，皆肺经热邪鸱张之症，脉洪大与症相应。宜令下行由腑而出，投知母花粉芩栀苇茎，便泻热水而脉静身凉，主肺热壅盛之病机。", ["洪", "大"]], "14223": ["病机", "脉弦耎微滑，弦主厥阴肝经、耎为阴虚不任、滑则痰气内滞。原文「乃阴虚而痰气滞于厥阴也」，环跳腿痛、转筋上冲、肢冷自汗，皆肝络痰气窜扰之症；畏热知饥、溲短便坚、舌红不渴，又见阴亏。脉症合参，主阴虚痰气滞于厥阴之病机。", ["弦", "耎", "滑"]], "14224": ["病机", "脉甚数，为温邪直入营分之征。春温初起即神气躁乱、惊惧不眠，乃热扰营阴，心神不宁。数脉主热，热盛入营，故脉数甚；营热内燔，故见躁乱惊惧。孟英断为温邪直入营分，用神犀丹佐紫雪清营透热，两剂而瘥，说明脉数在此提示病位在营，非表证汗解所宜。", ["数"]], "14225": ["病机", "脉沉弦而耎滑带数，沉主里，弦主饮，滑主痰，数主热。患者素患痰饮，误服温补，致痰热内壅，肺气不展，故发冷喘汗欲厥。脉沉弦为饮邪内伏，耎滑带数示痰热相搏。孟英谓病在肺，与少阴虚喘迥殊，切勿畏虚妄补，当以薤蒌枳杏旋等开肺涤痰，使痰有出路。", ["沉", "弦", "滑", "数"]], "14226": ["病机", "脉弦大而缓滑，弦大主实热壅盛，缓滑主痰湿内蕴。春温谵语发狂，连服清解大剂后反昏沉肢冷，似虚而实为热结胃腑，痰热蒙蔽。脉弦大缓滑与黄腻苔、秽气直喷相应，故孟英断为实热结于胃腑，投承气汤下胶黑矢而愈。此脉示邪实未去，不可因肢冷误作虚寒。", ["弦", "大", "缓", "滑"]], "14227": ["病机", "脉弦劲而数，弦劲为热伏厥阴、肝火亢盛之象，数为热盛。汛愆寒热，医误温补，致腹胀不饥、带淋便秘、溲涩而痛，乃热伏厥阴，肝火下迫，肺亦壅塞。脉弦劲数正是热伏厥阴之凭据，孟英用清肃开上之剂及当归龙荟丸，泻肝火而诸恙悉安。", ["弦", "劲", "数"]], "14228": ["病机", "脉来洪滑且数，洪为实热，滑为热痰，数为热盛。妊身八月患间疟，热炽昏沉，腰痛欲堕，苔黄腻垢浊，乃实热挟痰，兼有阴虚。脉洪滑数示热痰内盛，故孟英用芩知竹茹竹叶银花桑叶丝瓜络石斛石膏石菖蒲清热涤痰，一剂而痊。此脉主实热痰浊，非虚寒可比。", ["洪", "滑", "数"]], "14229": ["病机", "脉弦滑，弦主痰饮，滑主痰热；脉滑数，滑为痰，数为热。朱父年逾七旬患间疟，脘闷苔黄，脉弦滑，为痰热内蕴；李妻素患痰嗽，近兼晡热不饥，脉滑数，乃痰火内伏，温热外侵。两案脉象均示痰热为患，故孟英投清热涤痰药而愈。脉弦滑数在此主痰火内伏，非虚损之候。", ["弦", "滑", "数"]], "14230": ["病机", "脉耎数，耎为湿温之湿象，数为热象。劳伤之后发热身黄，孟英察脉耎数，断为湿温重证，故初起即黄。湿温湿热交蒸，故脉耎数；湿热扰营，则谵语昏聋、抽痉遗溺。此脉示湿热内蕴，非单纯劳伤，故亟予清解，佐牛黄丸紫雪丹泄卫清营而瘳。", ["耎", "数"]], "14231": ["病机", "脉洪数无伦，右尺更甚，洪数为实热炽盛，无伦示热势乖张，右尺候肾，更甚则热灼下焦阴分。高年患感，误燥误补，致气逆神昏、汗多舌缩，乃实热兼挟阴虚。脉洪数无伦正是热盛阴伤之征，故孟英用大剂犀角石膏芩连柏知母花粉等清热救阴，三日后脉证渐和。", ["洪", "数"]], "14232": ["病机", "脉缓为挟湿，滑溢为痰热不降。患者形瘦阴亏，而痰湿阻痹中焦，故脘膈闷极、苔腻不渴；脉缓滑上溢，说明湿痰内蕴、热邪不降，枢机不利。虽间日疟寒少热多，但非单纯表邪，不可提表助逆，亦不可凉润碍枢，治当化湿痰、通降气机。", ["缓", "滑"]], "14233": ["病机", "脉虚弦耎数，舌光赤无苔，为阴液亏虚、肝阳上逆之象。冲脉系于肝，冲经上逆则嗽，阳升无液则头疼口燥。脉耎为阴中之阳亦虚，故非外感，乃内伤虚损。治以苁蓉、石英、龟板等育阴潜阳，使冲逆平而嗽减餐加。", ["虚", "弦", "耎", "数"]], "14234": ["病机", "原文未识脉名，仅言“按其脉肤甚热”。肤热为湿热时邪外蒸之征，非疝病。睾丸肿痛偏右，乃湿热伤气、下注厥阴。医误用茴香、芦杷、乌药等辛温疝药，反助热痛剧。治以清解湿热，便行热退，说明脉肤热主湿热壅盛，当从时邪论治。", []], "14235": ["预后", "左寸数疾，余皆耎大，舌尖独黑，苔腻黄。左寸候心，数疾为离火内亢；耎大乃坎水不制，虚阳外浮。平昔曲运心机，阴亏火炽，兼湿温之感，势必自焚。脉象舌色昭示根本已败，故虽证原不重，仍断为不治，果数日而殒。", ["数", "疾", "耎", "大"]], "14236": ["病机", "脉形歇代，然弦搏有根，非无根之散。歇代主脉气不续，弦搏有根则胃气尚存，故虽高年湿温旬余，仍属实证。呃忒连朝、二便窒涩、苔腻而灰，为痰湿热阻腑气，气化不行。治以清宣展布，使痰热去而脉复。", ["歇", "代", "弦"]], "14237": ["病机", "脉弦细而耎，为阴虚劳倦、湿温毒重之证。弦为肝热，细耎为阴液不足。清解中须寓存阴，若徒用渗利，脉更细弱，神益昏惫，乃阴液愈竭。急救阴液，复脉汤去姜桂麻仁，易西洋参，加知母花粉，使神苏脉起，说明弦细耎弱主阴亏热伏。", ["弦", "细", "耎", "弱"]], "14238": ["病机", "脉弦细而涩，舌光紫满布白糜，骨瘦如柴，少腹拒按，溲閟。弦为肝热，细涩为阴血枯涸、脉络瘀滞。湿热久羁，误用辛温渗利，阴液耗伤，腑气不通。虽属下证，形证危殆，法难直授，先外罨通溲，内以育阴润降，使小溲行而气平。", ["弦", "细", "涩"]], "14239": ["病机", "脉弦滑且数，苔滑腻微黄，渴喜冷饮，便秘溲热。弦滑为肝热煽痰，数为兼挟阴虚。伏痰内盛，肝逆上升，兼吸受暑热，故气冲欲厥、脘痛莫当。自服辛温，愈助肝阳。治以清肝化痰、降逆和胃，使吐止痛减、热退而愈。", ["弦", "滑", "数"]], "14240": ["病机", "脉弦细虚数，弦为风阳浮动，细虚为营阴素亏，数为酷热外烁。娩后三日发热汗多，苔黄眩悸，乃阴虚阳越，痉厥之萌。脉象揭示营阴亏虚、风阳内动之病机，故治以滋阴潜阳、清热熄风。", ["弦", "细", "虚", "数"]], "14241": ["主病", "脉滑数，滑主痰热内蕴，数主热毒炽盛。便秘两月而脉滑数，为热毒壅结肠胃之实证，故面赤龈胀、银针拔出如煤黑。脉滑数兼便秘，确为可下之征，故用犀角石膏硝黄等清解化毒。", ["滑", "数"]], "14242": ["病机", "脉浮弦数，浮为阳越，弦为肝阳勃升，数为热。心悸肢冷如冰而舌尖赤无苔，乃阴虚阳越、煎厥根萌。脉象示肝阳上浮、阴不敛阳之机，故治以滋阴潜镇、引阳下行。", ["浮", "弦", "数"]], "14243": ["病机", "左脉弦急，右脉洪滑数，弦急为木火上浮，洪滑数为酷暑外烁、津液大耗兼伏痰。产后发热谵语嗽痰，恶露仍行，脉象示阴虚阳浮、痰热内蕴之病机，故亟予营卫两清。", ["弦", "急", "洪", "滑"]], "14244": ["病机", "脉缓大而右关较甚，缓大为劳倦伤阳之象，右关主脾胃，较甚说明湿热蕴积中焦。嗽痰带血而能安谷，脉象示阳气不足为本、湿热蕴积为标，故治以清化湿热兼扶脾阳。", ["缓", "大"]], "14245": ["病机", "脉见细弱之形，细弱为阴血亏虚、阳气不振。滞下腹痛微呕，肌无华泽，汛断舌紫黯无津，乃素质阴亏、情怀悒郁、二阳默炽、五液潜消。脉象示正虚邪恋，故不可套用攻下。", ["细", "弱"]], "14246": ["妇人", "脉甚滑疾，滑疾为妊娠之征，虽虚微耎数而滑象仍形，说明虚损之中犹有胎孕之滑脉。前医作虚损治，徒补其虚而不治所以虚，脉象揭示妊娠与虚损并存，故用药须顾及胎元。", ["滑", "疾", "虚", "微"]], "14247": ["病机", "脉弦数，弦为肝郁，数为热，乃阴虚挟热之象；便血三十余年，形瘦腰疼，嗽痰气逆，舌黄溺赤，脉象示肝经郁热、肺失肃降，非温补所宜。后脉虚弦豁大，为阴血亏虚、阳气浮越之变。", ["弦", "数", "虚", "豁大"]], "14248": ["病机", "脉弦滑而洪，弦主痰饮，滑主痰湿，洪为阳明热盛。体丰多汗、苔黄便血、呕渴妄言，显系伏痰内盛，暑热扰于阳明，痰热交蒸，故脉象洪滑而弦。此脉主痰热内蕴、暑邪炽盛之病机，与呕渴、妄言、不寐等症相应。", ["弦", "滑", "洪"]], "14249": ["病机", "脉弦数而促，弦主热痰，数主热盛，促为热壅气机。苔黑口干，寒战妄言，是素有热痰、暑邪内伏。后兼浮脉，为风温袭表，温散劫津，热得风而更炽。此脉主痰热内伏、风温外袭之病机，与寒热、妄言、口渴无溺相应。", ["弦", "数", "促", "浮"]], "14250": ["病机", "脉滑数，滑主痰湿，数主热盛。舌绛便艰、口臭溲少，乃湿热痰火内蕴。疡医温托温补，致湿热痰火一齐关住，不得外泄，故寒热频作、肌肉渐削。此脉主湿热痰火壅遏之病机，与咽糜龈腐、睛赤音嘶等症相应。", ["滑", "数"]], "14251": ["病机", "脉来沉实而数，沉主里，实主邪实，数主热。舌苔紫黯，恶露虽行而寒热头疼，乃瘀血内阻为患。瘀血停滞，郁而化热，故脉沉实而数。此脉主瘀血内结之病机，与腹痛、下瘀血块等症相应。", ["沉", "实", "数"]], "14252": ["病机", "脉弦缓，弦主气机郁滞，缓主痰湿。苔黄腻，气逆肢寒，神疲欲寐，乃胎之初孕，阻气凝痰，窒碍枢机。痰阻气滞，枢机不利，故脉弦缓。此脉主痰阻气滞之病机，与气逆、肢寒、耳聋舌謇等症相应。", ["弦", "缓"]], "14253": ["病机", "原文未识脉名，但言“虚促虽形，未必即为虚谛”。肺为痰壅，气不流行，故脉见虚促。年甫三旬，病起于暴，苔腻痰浓，足冷面红，无非痰阻枢机，有升无降。此脉主痰壅气逆之病机，与气喘、足冷面红、不饥不寐等症相应。", []], "14254": ["病机", "两脉上溢，左兼弦细。弦细为真阴久虚，风阳上僭，冲脉之气上逆。干嗽无停、口渴无苔，乃阴亏阳亢，冲嗽不已，厥脱堪虞。此脉主阴虚阳浮、冲气上逆之病机，与干嗽、目不交睫、厥脱等症相应。", ["弦", "细"]], "14255": ["病机", "左弦疾而促，右滑数而溢。弦疾促为肝阳鼓舞直升，滑数溢为痰热壅肺。苔色满布，痰嗽气逆，额汗颧红，系冬温挟痰阻肺，治节不伸，肝阳上逆。此脉主痰热阻肺、肝阳上亢之病机，与痰嗽、躁扰、颧红等症相应。", ["弦", "疾", "促", "滑"]], "14256": ["病机", "脉耎滑而数，耎为湿滞，滑主痰饮，数则为热，合之苔腻滞，显系平昔善饮、湿热内蕴之征。奔走过劳，邪乃下注，致肛翻患痔、小溲不行。脉不虚不迟，故非真火无权，亦非清阳下陷，乃膀胱气阻、湿热下注之实证，与年高强忍肛坠之势相应。", ["耎", "滑", "数"]], "14257": ["病机", "左脉弦劲而数，右滑大不调，弦劲为肝胆风阳上僭，数为热，滑大为肺胃痰热有余。苔黄腻、口渴溺多，皆痰热内盛之象；面浮跗肿、喘嗽易嗔，则风阳挟痰上扰。脉证合参，病机在肺胃痰热与肝胆风阳，故畏虚妄补，必以清化痰热、潜降风阳为治。", ["弦", "劲", "数", "滑"]], "14258": ["病机", "左弦而微数，右耎滑兼弦，左强右弱，升降不调。弦为肝木过升，微数为阴亏有热，耎滑为湿浊内蟠、土失提防。久患痰嗽、动则气逆、夜不能寐，乃肝升太过、肺降不及；纳减呕腐吞酸，则中运为滋腻所碍。脉象揭示水常泛溢、土失提防之机，非单纯清阳下陷或真阴不足。", ["弦", "微", "数", "耎"]], "14259": ["预后", "脉细数而弦，右则按之如无，细为阴亏，数为热灼，弦为温毒深蟠、肝风内动。舌缩底绛、苔黑如漆、口开茎萎，皆阴液尽烁之候。右脉按之如无，则脾胃生气已绝，甘露琼浆不能复其已竭之津，故预后不良。此脉象说明温毒深入、阴液耗竭，属死候。", ["细", "数", "弦"]], "14260": ["病机", "脉甚弦耎，弦为肝脉，耎则示脾败肝旺。体属久虚，误进肾气汤月余，滋腻碍中，附桂助肝，遂致呕恶便溏、不饥无溺。苔腻舌红，乃中虚健运失职、湿浊内蕴。脉弦耎正是土衰木横之象，故治以培中泄木、行水蠲痰，而非温补下焦。", ["弦", "耎"]], "14261": ["病机", "脉弦而数，弦为肝郁，数为热，合之能食便行、气上冲、腹时痛胀，及病起汛后、继多白带，显系瘀停化热、煽动肝阳。昼明了夜妄言，酷似热入血室。脉弦数说明瘀血化热、肝阳上扰，故径从瘀血治，瘀行则神情爽慧。", ["弦", "数"]], "14262": ["病机", "范廉居脉形虚大，舌紫无苔，为上焦热恋、下部阴亏，虚大为阴不敛阳。其室脉至虚弦、按之涩弱，乃营亏气弱、肝胃不和。渠女脉来弦滑数实，苔黄大渴、二便皆閟，系腑实热结。三案脉象各异，分别示阴亏热恋、虚弦涩弱、腑实壅盛之病机。", ["虚", "大", "弦", "滑"]], "14263": ["病机", "左关弦、寸滑如珠、尺细而干，弦为肝阳，滑为痰，细干为真阴亏。水不涵木，风阳内炽，搏液成痰，故脉见弦滑细。误服温补后脉已虚促不调，虚为气耗，促为阳越，乃阴虚阳越之危候。脉象由弦滑细转为虚促，示病机由痰热内扰转为阴阳离决。", ["弦", "滑", "细", "虚"]], "14264": ["病机", "脉右甚滑大，右主肺胃，滑为痰热，大为热盛，此产后血去，肝阳上亢，贼胃生热，热壅阳明，故脉右滑大。头痛甚剧乃阳明热壅、肝阳上扰之征，予清阳明法得大解而瘥，正合脉证。", ["滑", "大"]], "14265": ["病机", "脉弦细以涩，两尺如无，弦主暑湿内伏、气机阻塞，细涩为阴伤血少，尺部如无乃肾气不通。暑湿阻塞气机，宣降无权，乱而上逆，故见霍乱转筋、音哑厥逆、口渴即吐，脉象反映邪阻正伤之机。", ["弦", "细", "涩"]], "14266": ["病机", "脉细欲伏，细为暑湿内蕴、气机不畅，伏为邪阻阳气不达。苔白而厚，凛寒厥逆，烦闷躁扰，口不甚渴，乃暑湿内蕴未化，阳气被遏，故脉细欲伏。非寒证，乃暑湿蒙蔽，脉象反映邪伏阳郁之机。", ["细", "伏"]], "14267": ["病机", "脉左弦强而右滑大，左弦强为肝火素盛，右滑大为胃热壅盛。舌绛目赤，大渴饮冷，霍乱转筋，乃肝胃之火素盛，热复侵荣，故脉象弦强滑大。转筋由血热，脉证相符，清肝胃之火而愈。", ["弦", "强", "滑", "大"]], "14268": ["病机", "脉虽虚软，并无脱象，虚软为暑湿伤气、正气不足，然舌赤而干、利下臭恶，乃气分伏暑，业扰及荣。脉虚软非脱，乃邪扰正虚，虑其络闭神昏，故不可再投热剂，脉象反映暑热内伏、气阴两伤之机。", ["虚", "软"]], "14269": ["病机", "脉伏无溺，伏为热邪伤肺、肺气不行，非气液两竭之比。口渴汗多，腹痛苔黄，目陷形消，肢冷音飒，乃热邪内闭，气机不通，故脉伏无溺。汗多阴津未竭，正旺邪亦旺，脉伏反映热闭气机之病机。", ["伏"]], "14270": ["病机", "脉滑数右甚，滑为痰实，数为热盛，右甚主肺胃。口竭苔黄，胸下坚硬而痛，吐泻虽多食尚恋膈，乃肺胃痰实兼挟阴虚，非寒证也。脉滑数右甚反映痰热壅阻肺胃之病机，故揭去回阳膏而清化痰热。", ["滑", "数"]], "14271": ["病机", "脉伏无溺，伏为冬寒内伏、气机郁遏不宣，寒邪化热，究与暑湿较异。手面皆黑，目陷睛窜，厥逆音嘶，舌紫苔腻，大渴汗淋，神情瞀乱，危象毕呈，脉伏反映寒邪化热、气机闭遏之病机，刺络出血以泄郁热。", ["伏"]], "14272": ["主病", "原文述温病转为霍乱，见“腹不痛而肢冷脉伏”，脉伏为邪热内闭、气血壅滞，阳气不达四末所致，非虚寒之象。兼口渴苔黄、小水不行、神情烦躁，皆热郁气分、邪无外泄之征。脉伏与肢冷并见，正是“热深厥深”之机，故主温病霍乱之热闭证。", ["伏"]], "14273": ["病机", "原文论伏邪欲发、客邪外入，两邪交讧致“气道立时闭塞，血脉因而瘀滞”，故见“四肢厥冷，手面皆黑”与“肢冷脉伏”。脉伏乃邪闭血凝、气不流行之象，非气血枯槁。文中明言“热深厥深之理”，指出昧者误以脉伏肢冷为寒为脱，反投热药，使邪愈闭。此脉主热邪内闭、气血瘀滞之病机。", ["伏"]], "14274": ["主病", "原文列飞龙夺命丹主治“痧胀疗痛，霍乱转筋，厥冷脉伏神昏危急之证”，脉伏与厥冷、神昏并见，为秽恶温暑诸邪闭阻气机、蒙蔽清窍所致。脉伏反映邪闭深重、气血不能外达，故属危急之候。此脉主痧胀霍乱之邪闭神昏证，与眩晕痞胀、瞀乱昏狂等症相应。", ["伏"]], "14275": ["预后", "原文载患者余毒蕴隆、失于清解，症见咽痛碍食、颐肿舌糜、牙关紧、痰嗽胁疼、溺赤管痛、便溏色酱，而“脉已弦紧数疾”。弦紧主邪结，数疾主热盛，四象并见，示余毒炽盛、邪热鸱张，故断为“莫可措手”，属预后不良之脉。此脉与余毒蕴隆诸症相应，主邪盛正衰之危候。", ["弦", "紧", "数", "疾"]], "14276": ["误治", "原文述下利转筋，医见肢冷即投温补，致呃忒、病危。孟英诊得“左弦滑，右弱不应指”，左弦滑主痰热内结，右弱不应指因痰食壅阻、阳气不布，非虚寒。苔黄厚腻浊、小水不行、脐上拒按，皆实邪内闭之征。前医误以肢冷右脉软弱为虚寒，温补致剧，故本段主旨为误治，脉象示痰热内闭之实。", ["弦", "滑", "弱"]], "14277": ["病机", "原文述秋夜陡患霍乱，腹痛异常，“诊其脉，细数而弦”，肢冷畏寒、口不渴而泻、吐极苦、舌色甚赤、小便全无。细数主伏暑内热伤阴，弦主腹痛、气机郁滞，肢冷畏寒乃新凉外束、阳郁不达。脉症合参，为“新凉外束，伏暑内发”之病机，细数弦脉正合暑热内伏、寒邪外束之象。", ["细", "数", "弦"]], "14278": ["误治", "原文述霍乱转筋，初进桂附药后“指渐冷，脉渐伏”，更用牡蛎龟板阿胶而势剧。孟英辨为伏暑挟食，见苔黄大渴、小便全无、泻出极热、心下拒按。脉渐伏由燥补涩腻致邪热内闭、阳气不达，非虚寒。前医误治，反使邪无宣泄。此脉主伏暑内闭、热深厥深之病机，与苔黄大渴、心下拒按相应。", ["伏"]], "14279": ["病机", "原文述霍乱自汗、肢冷脉无，人谓寒证欲用热药。孟英察苔白厚边绛、渴甚头大痛，断为暑热内伏、寒凉致病。脉无因暑热内闭、阳气不达，非虚寒脱证。服五苓加黄连等后脉稍出，证明邪闭得开、阳气渐通。此段脉象虽未明指，然“脉无”与肢冷自汗并见，主暑热内伏、气机闭阻之病机。", []], "14280": ["病机", "脉弦滑搏数，弦主肝郁气逆，滑主痰，数主热，搏则邪势亢盛。患者年高阴亏，便如羊矢，今陡患呃忒，苔黄厚腻、口苦溺赤，显系痰热内阻、气机上逆所致。虽衰年虚体，然脉象与苔黄口苦溺赤相合，说明呃逆由痰热壅遏、胃气不降而发，非虚寒之呃，故主大剂凉润清化痰热。", ["弦", "滑", "数"]], "14281": ["病机", "脉极弦细，弦为肝阳亢逆，细为阴血不足。霍乱转筋、厥逆目窜、膈闷无溺、苔黄苦渴，乃伏暑挟素盛肝阳为病，误进桂附姜术温补，致气逆欲死。脉弦细反映肝阳化火、阴液受灼，气机壅塞，故以昌阳泻心汤清暑泻肝、降逆和胃，外贴涌泉引火下行。", ["弦", "细"]], "14282": ["病机", "初诊脉未全伏，伏而未显，示邪热内闭、气机壅遏；次日脉弦滑，弦主肝热，滑主痰湿。孕妇便泻，误投姜附桂朴，致四肢麻冷、气塞神昏、溺闭汗淋、大渴呕吐，乃暑热内陷、肝胃热盛、痰湿中阻。脉弦滑与苔黄渴呕相应，说明邪热未清、痰湿尚滞，故以白头翁汤加味清暑化湿。", ["弦", "滑"]], "14283": ["病机", "脉弦数，弦主肝热，数主热盛。霍乱服姜桂数剂泻不止，大渴而脉弦数，虽素吸鸦片阴分素亏，然脉数与渴饮相合，说明热药过剂、暑热内迫、阴津受灼。幸便泻分消药力，未致津液早枯。脉弦数反映肝胃热炽、阴伤液耗，故以白头翁汤合封髓丹苦寒泻热、甘凉救阴。", ["弦", "数"]], "14284": ["病机", "脉微弱而数，微弱为暑热伤气、脉道不充，数为热。高年陡患呕泻、身热腹痛、神思不清，脉微弱而数，正合“暑脉自虚”之论，说明暑热内扰、气阴两伤，非虚寒欲脱。若误作高年畏脱而用辛散痧药，必耗津液。脉虚数与身热呕泻并见，故主暑热挟湿，治以芩连滑斛清暑化湿、护阴和胃。", ["微", "弱", "数"]], "14285": ["病机", "脉弦数左甚，弦主肝阳，数主热，左甚则肝热偏亢。霍乱转筋后渐生呃忒，苔焦而渴、龈衄脘闷、便溏色酱、小便短赤，皆伏暑未清、气机阻塞之象。脉弦数左甚与苔焦龈衄相应，说明暑热内炽、肝阳上逆、气机失肃，当脐尚贴回阳膏更助其热，故预后不良。", ["弦", "数"]], "14286": ["病机", "脉来沉细，沉主里，细主湿滞脉道，身不发热，俨似虚寒，然苔色黄腻、小溲全无，乃湿热内蕴、阳气郁遏之象。洞泻如注、汗出如洗、恹恹一息，是湿浊困阻、气化不行，脉沉细正合湿遏热伏、脉道不利。故断为湿热病，以桂苓甘露饮加厚朴清利湿热、宣通气机。", ["沉", "细"]], "14287": ["病机", "脉伏，为热邪内闭、气机壅遏，脉道不通。赤膊恶热、五内如焚、目陷音嘶、苔黄大渴、啜饮即吐、肢厥，皆热盛于里、格阴于外之象。脉伏与苔黄大渴并见，说明热邪深伏、逆冲之火上炎，非虚寒厥逆，故取冷雪水徐灌以折热，继以石膏黄连知母泻其逆冲之火。", ["伏"]], "14288": ["病机", "霍乱吐蛔而口干脉细，细为阴血不足、暑热内伏之象。暑邪伏于厥阴，犯扰中焦，故吐蛔；热灼津伤，故口干而脉细。脉细在此非虚寒，乃暑热耗阴、厥阴受病之征，故用连梅茹楝清暑泄肝、苡斛苏芩和中生津而愈。", ["细"]], "14289": ["病机", "年逾六旬而脉甚滑数，滑主湿痰内盛，数主热邪亢炽。原文谓“赋质偏阳，湿热内盛”，故口渴苔黄、便溺皆热、畏热著夹衣。滑数之脉正合湿热蕴蒸之病机，幸未误进温补，予大剂清化而渐愈，脉象与证候相印。", ["滑", "数"]], "14290": ["预后", "此段列霍乱数案以辨预后。脉微欲绝者，阳气衰微欲脱，虽证不甚剧亦决不治；脉伏而形脉两脱、大汗如淋者，正气溃散，勉投参药竟不能救。原文“凭脉不凭证”“阳越之象”，说明脉微、伏、散皆主正气败绝、阴阳离决之危候。", ["微", "伏", "散"]], "14291": ["病机", "脉甚弦驶，弦主肝火，驶为数急之象，示火热内炽而急迫。原文断为“肝火内炽，暑热外侵”，故溺血如注、头疼如劈、自汗息微。弦驶之脉正应肝火暑热交炽、风阳僭极之病机，故用犀角、龙荟丸清肝泻火而吐泻止、溺血减。", ["弦", "驶"]], "14292": ["病机", "脉弦耎而数，弦主厥阴肝热，数为热盛，耎示热中兼有柔缓之象而非实坚。原文谓“清厥阴蕴热，非痧也”，茎缩腹痛、发热呕吐、苔黄腻，皆厥阴蕴热之候。弦耎而数正合肝经郁热之病机，故用楝茹连斛栀柏清泄而愈。", ["弦", "耎", "数"]], "14293": ["病机", "初诊脉细而弦，细为阴伤，弦主肝郁，霍乱转筋、目陷音嘶乃吐泻伤津、肝风内动之象。服后脉耎而弦，耎示邪减而正未复，弦仍主肝郁，原文谓“素多肝郁也”。终至脉和胀减，示郁热渐平、气机调和，脉象变化与病情进退相应。", ["细", "弦", "耎"]], "14294": ["病机", "脉微弦，微为元气素弱，弦主内风与肝火。原文谓“本元素弱，谋虑萦思，心火上炎，内风随以上僭”，故肢麻昏运、面红睛赤、音低神惫。微弦之脉正合本虚标实、心火肝风上僭之病机，非痧闭实证，故以人参龙蛎菖连等补镇清降而瘥。", ["微", "弦"]], "14295": ["病机", "六脉迟耎，迟主阳气不足，耎为软弱无力，示中气亏虚；左脉仍弦，弦主肝郁。原文断为“真中气不足，溲便为之变也”，故便艰而先硬后溏、汗出神惫、呕吐酸辣。迟耎之脉正合中虚开阖无权之病机，故不宜润下升提，以参术橘半旋芍培中而更衣得通。", ["迟", "耎", "弦"]], "14296": ["病机", "脉微苔白，腹大痛而欲重按，显系中虚有素，因热受寒，寒邪直中，阳气式微，故脉微肢冷自汗；腹痛喜按，虚寒内盛。治以理中汤加桂枝白芍，温中散寒，舍时从证，复杯而愈。", ["微"]], "14297": ["预后", "脉七至而细促不耐按，数而细促，按之无力，乃中气卒然溃散之兆。虽略无病，然脉病人不病，胃气已败，形削汗多，脉渐脱，音渐嘶，终至不救，预后极恶。", ["细", "促", "数"]], "14298": ["主病", "脉伏为霍乱转筋急证之主脉，肢冷腹痛，口渴烦躁，目陷，乃暑湿秽浊内闭，阳气不达，气血壅滞，故脉伏不见，治以蚕矢汤清利湿热，宣通阳气。", ["伏"]], "14299": ["主病", "脉伏溺无，肢厥汗多，转筋吐下，口渴腹痛，面黑目陷，为温暑痧邪深入营分，热毒内闭，气机壅塞，血脉不通，势极危殆，治以解毒活血汤清营解毒，活血透邪。", ["伏"]], "14300": ["兼症", "霍乱后余邪未清，身热口渴，余热内蕴，身冷脉沉，汤药不下而发呃，乃热邪内郁，气机不畅，脉沉主里，非虚寒也，治以驾轻汤清透余邪，和胃降逆。", ["沉"]], "14301": ["病机", "脉沉弦而软滑，沉弦主肝郁，软滑主痰湿，苔黄腻，溲浑短，乃肝郁气结，郁久生热，温补凝痰，痰热内阻，气机不畅，故腹胀如痞，冲逆吐酸，治以清肝解郁，化痰消痞。", ["沉", "弦", "软", "滑"]], "14302": ["病机", "左弦而数，右滑以驶，弦数主肝郁化火，滑驶主痰热内壅，症见头疼眩晕，气逆呕吐，痰多不寐，经事不行，乃误投温补，痰热上扰，肝胃不和，治以清化痰热，调肝和胃。", ["弦", "数", "滑"]], "14303": ["病机", "未识脉名，然症见发热恶寒，肢振自汗，少腹气上冲胸，头疼口渴，乃卫虚风袭，络脉久伤，肝风内动，津液素亏，汗出耗津，肝失所养而上冲，肺胃失养而口渴，治以建中加龙牡等，柔肝熄风，调和营卫。", []], "14304": ["预后", "左尺坚搏，为真阴已伤之象。尺脉候肾，坚搏乃阴亏阳亢、脉失柔和，故断其证虽可愈而寿难永。原文谓“真阴已伤，非善象也”，即从脉象判断根本已损，虽疮疽渐安，然阴精耗伤，脉见坚搏，预后不良，后果然卒于京。", ["坚", "搏"]], "14305": ["病机", "脉劲搏指，为阳气偏盛、阴不制阳之象。患者年高而欲纳妾，病狂惑，面赤不言，口涎自流，力大无制，皆阳盛火炎之征。原文谓“禀赋过强，阳气偏盛”，脉劲搏指正合此机，非虚寒可比，故前医热补愈剧。", ["劲", "搏"]], "14306": ["病机", "脉软滑微数，为阴亏内热、痰饮内盛之象。新产血去，阴亏生热，故脉数而软；痰饮内盛，故脉滑。原文谓“素体阴亏，热自内生”，又谓“痰饮内盛，津液未致涸竭”，脉软滑微数正合阴亏痰热之机，故以蠲饮六神汤加减而瘳。", ["软", "滑", "数", "涩"]], "14307": ["病机", "耄年脉实，为天畀独厚、阳结便秘之象。原文谓“耄年脉实，天畀独厚，证属阳结，法宜清火”，脉实主邪实有余，非虚衰之候，故用清火通腑之剂而愈。若误投温补，则胀满愈甚，不可救药。", ["实"]], "14308": ["死脉", "左寸如钩，为心之真藏脉见，主真气散漫。原文谓“脉来瞥瞥如羹上肥，而左寸如钩，是心之真藏见矣”，又谓“此为真气之散漫”，与邪气壅塞之“证实脉亦实”不同，散漫不能收拾，故断其病不能夏，季春果殁。", ["实", "钩"]], "14309": ["妇人", "六脉缓滑，为气血充盈、天癸将至之象。室女久患齿衄，医多误治，孟英诊得缓滑之脉，知非虚损，乃经水将行、气血壅盛所致。原文谓“天癸将至耳”，故用活血通经之剂，一剂知，数日愈，寻即起汛。", ["缓", "滑"]], "14310": ["病机", "脉形豁大，为虚火上炎、阴不敛阳之象。吐血而面有红光，足冷，脉豁大，乃肾阳虚衰、虚阳上浮之证。原文谓“面有红光，脉形豁大”，又探足冷果然，故用六味地黄汤送肉桂引火归原，复杯而愈。前医归脾升补，故吐益甚。", ["豁", "大"]], "14311": ["病机", "脉弦滑以数，为风温挟痰热内蕴之象。脘痛发热咽痛，目闭鼻塞耳聋肢搐，苔白滑，大解未行，脉弦滑数，主痰热内阻、风温顺传胃府。原文谓“病是风温，然不逆传膻中，而顺传胃府”，脉象与证相符，故断证可无恐。", ["弦", "滑", "数"]], "14312": ["病机", "左手弦数，右部涩弱，弦数主悒郁化火，涩弱为思虑伤脾、营血不足。症见晡寒夜热、寝汗咽干、咳嗽胁疼，乃心脾郁结、阴血暗耗之象。脉证合参，病发心脾，非外感实邪，故以甘麦大枣汤加藕怡情养血而脉证大减。", ["弦", "数", "涩", "弱"]], "14313": ["病机", "脉大而数，重按虚散，大数似实热，然重按虚散为阴亏阳浮、虚火上炎之真象。症见目赤、龈肿、狂妄骂詈，乃下虚上实、龙雷之火上奔。故用熟地、肉桂、磁石、龙齿引火归元，重镇安神，投匕即安。", ["大", "数", "虚", "散"]], "14314": ["预后", "体瘦脉细数，尺中更乱，细数主阴虚阳亢，尺乱为真液下夺、根本已摇。温病见气逆无寐、咳痰舌绛、耳聋谵语，又带下如崩，阴气先伤，阳气独发。脉象示下虚已极，故断为痉厥之变不旋踵，预后险恶。", ["细", "数", "乱"]], "14315": ["病机", "形虽羸瘦而脉滑痰多，苔黄舌绛，滑脉主痰湿内蕴，合苔黄舌绛为痰热胶结。体虚病实，温补非宜，徒补则助痰。故先以雪羹加竹茹、楝实等送控涎丸攻逐胶痰，痰去而后调补获痊。", ["滑"]], "14316": ["死脉", "六脉弦强无胃，弦强为真脏脉见，无胃即失柔和冲和之气。症见胸腹胀痛拒按、便秘溺赤、舌黑口干、自汗烦躁，乃湿热误汗内陷，盘踞胃府，结胸危候。脉无胃气，故断越二日便行而殁。", ["弦", "强"]], "14317": ["病机", "脉数而洪，舌绛大渴，数洪为阳热亢盛、营血耗伤。产后四肢串痛，非风湿，乃温补祛风及生化汤、砂糖酒酿成内风欲动。体丰血旺，阴足可恃，故投大剂凉润壮水，一剂知，恢复尚易。", ["数", "洪"]], "14318": ["病机", "脉弦无胃、不柔和，弦为肝脉，无胃则失冲和，主肝阳化风、津液涸竭。素多郁怒，气聚为瘕，攻痛呕吐，前服温补逍遥理中，劫阴伤液，风阳内煽，水自沸腾。脉不柔和，示肝阴耗极，非人间之药所能疗。", ["弦"]], "14319": ["病机", "脉伏口渴，伏脉非必虚寒，暑热内闭、阳郁不达亦可见伏。症见热炽神昏、胸高气逆、苔黄溺赤、不食不便，乃暑湿内蕴、热深厥深。前医拘司天投平胃理中，反助暑热。故以白虎汤加清热解毒，旬日疟断。", ["伏"]], "14320": ["病机", "初诊脉伏，乃痰浊壅阻气道，气机不通，故虽蕴湿内盛、暑热外侵而脉象隐伏不见，脘闷苔腻欲呕亦痰湿上逆之征。服礞石滚痰丸后痰出甚多，气机得通，脉转弦滑而数，弦主痰饮、滑主痰湿、数主暑热，说明痰去而暑热湿邪之本象显露，故呕止胸舒、苔转黄燥，脉证相应。", ["伏", "弦", "滑", "数"]], "14321": ["病机", "脉洪滑无伦，洪为暑热燔炽、气分热盛，滑主痰热内壅，无伦形容其搏指有力而失和缓之常。结合目赤狂言、汗如雨下、舌深黄厚燥，显系暑热炽盛、内扰神明之候。更因恣饮姜枣汤三日，辛温助热，故脉象洪滑异常，孟英令食西瓜、用白虎加石膏清解暑热，热退则脉证俱安。", ["洪", "滑"]], "14322": ["病机", "酷热啜冷石花，冷饮冰伏胸中，大气不能转旋，阳气不达四末，故四肢渐冷、上过肘膝而脉伏自汗。此脉伏非阳虚欲脱，乃暑热为冷饮所遏、气机闭塞之实证，故二便不行。孟英以六一散调紫雪丹辛香通冰伏之气，次日脉见胸舒、溺行肢热，正说明脉伏由气机冰伏而致，非虚脱之候。", ["伏"]], "14323": ["病机", "脉沉细而数，尺部为甚，沉主病在里，细为阴伤，数主热，尺甚说明暑热深入足少阴肾经。暑热灼伤肾阴，故口渴、两腰收痛如锥刺、心慌不能把握、目不欲张；寒少热多亦邪在阴分之征。此暑入足少阴之证，汗下温三法皆不可行，与一般疟疾表散温补之法迥异。", ["沉", "细", "数"]], "14324": ["病机", "产后腹胀泄泻、面浮足肿，医以渗湿温补月余不效，貌似气虚。然脉至梗涩，毫无微弱之形，梗涩主瘀血阻滞、气血运行不畅，非虚损之脉。瘀血内阻，水湿不化，故腹胀泄泻、面浮足肿。孟英以丹参、泽兰、桃仁、五灵脂等行瘀利水，数服即瘥，证明病本在瘀而非气虚。", ["涩"]], "14325": ["误治", "本案未识脉名，孟英据阴虚之质、暑热胶锢断为误投补药。暑热证须邪到血分方可议用生地，初病即进熟地等滋腻之品，致暑热胶固难解，如油入面、如漆投胶，终至舌黑卷短而卒。文中以小米舍人、吴忻山二案反复申明：不察外来暑热、徒恃滋补滞腻，反致误人性命，属典型误治之戒。", []], "14326": ["主病", "滞下昼夜数十行，脉弦滑，苔黄满布。弦主气机壅滞、滑主湿热积滞，弦滑并见说明湿热蕴结肠道、气血阻滞之痢疾实证。苔黄满布亦湿热内盛之征。孟英重用芩、连清热燥湿，佐楂、朴行气导滞，送服青麟丸，投匕而痊，脉证与方药相应，证实为湿热滞下之实证实脉。", ["弦", "滑"]], "14327": ["预后", "滞下经通因通用后痛泄无度、呕恶不纳、汗出息微，脉弱眩晕。脉弱为正虚之象，合汗出息微、眩晕，说明元气将脱、正气衰败，非伏暑之痢实证。孟英辨此独非伏暑证，急投大剂温补，脉候渐安，一月后康复。脉弱在此为元气欲脱之危候，提示预后险重、须急救固脱。", ["弱"]], "14328": ["病机", "原文未明言脉象，但述脘疼呕吐、畏寒不寐、四肢不仁、肌肉尽削、带下如溺等症，孟英断为“暑伏肺胃”，因温补药中熟地等阴柔腻滞挟制，致“津气灼烁而殆尽，脂液奔迫以妄行，治节无权，阳明涸竭”，故现卫外不固、四肢不仁、九窍不利，脉象虽缺，病机为暑热内伏、津气两伤。", []], "14329": ["病机", "原文未载脉象，然述五龄儿发热数日，误服柴葛解肌汤后“肢搐而厥，目张不语”，孟英谓“病是暑邪，治以风药，热得风而焰烈，津受烁以风腾，乃风药引起肝风”，此即暑热炽盛、引动肝风、津液受烁之机，故见搐厥目张，治以犀角地黄汤加羚羊、石膏等清暑凉肝。", []], "14330": ["病机", "脉涩而兼沉弦以数，涩主血滞，沉弦主郁，数主热，合之乃“阴虚挟郁，暑邪内伏”。郁则气机不宣，伏邪无从走泄，误投血药引邪深入，血为邪踞，故左胁下及少腹梗塞不舒；舌无苔、口不渴、便溺如常，说明热未外露，治宜先清气透邪，气得宣布则热象必露。", ["涩", "沉", "弦", "数"]], "14331": ["病机", "脉沉而滑数梗梗，沉主里，滑数主暑热痰滞，梗梗为邪阻气机之象。患者年逾花甲，体丰善泻，白痢误投理中、附子，致“暑热未清”而腹胀且疼、不食不溺、哕逆发热，脉证合参，显系暑热挟滞内蕴，补药早投反壅塞气机，故以芩、连、朴、滑等清暑化滞。", ["沉", "滑", "数"]], "14332": ["病机", "脉弦细，沉取甚数，弦细为阴伤脉道不充，数为热，沉取甚数说明热伏于里。痢疾误作寒湿，广服温补燥热，致“暑热胶锢，阴气受烁”，故发热无溺、口渴不饥、腹疼胀、巅痛不眠、舌绛无津、肌肉尽削，脉证合参显为暑热内炽、阴液耗伤，故以育阴清暑合白头翁汤为治。", ["弦", "细", "数"]], "14333": ["病机", "脉细数而兼弦滑，细数主阴亏火盛，弦滑主痰饮内蕴。萧某素患痰多，常服六君子汤，孟英断为“阴亏火盛，津液受灼而成痰”，非虚寒痰湿，故须壮水之剂。后患咽痛，乃“阴虚于下，阳浮于上”，喉腭白腐为吸烟毒气薰蒸，脉象始终反映阴虚火旺、痰热胶结之病机。", ["细", "数", "弦", "滑"]], "14334": ["预后", "脉极弦细而促，舌绛大渴，小溲赤少，饮而不食月余，孟英谓“证实脉虚，坚辞不治”。弦细为阴伤脉道拘急，促为热盛而脉数中一止，极弦细而促示真阴耗竭、邪热鸱张，脉虚则胃气已败，正虚邪实，故断为不治。此段主旨在于凭脉判断预后凶险。", ["弦", "细", "促", "虚"]], "14335": ["病机", "脉至沉滑而数，沉主里，滑数主暑热挟滞。病痢而少腹结块攻痛、大渴无溺、昼夜百余行、五色并见，孟英谓“此必温补所酿”，因舍病顾虚，早投参、术、姜、萸、附、桂等守补燥烈，致“邪浊蟠踞”，滞下更甚。脉沉滑数正是暑热内蕴、邪滞搏结之征，非虚寒可比。", ["沉", "滑", "数"]], "14336": ["预后", "脉细硬如弦，毫无胃气，是胃气衰败、真脏脉现之象；右尺洪数，为肾阴亏耗、暑热内炽。舌光绛、大渴溺滴，皆津液尽劫之征。此暑疟误温，邪热愈炽，阴液速亡，故断为不治。", ["细", "硬", "弦", "洪"]], "14337": ["病机", "脉甚弦，重按则滑，弦主厥阴，滑主痰热。头痛三日一发、恶寒，乃暑热伏于厥阴，循经上扰。前医议姜附温补，反助邪热。孟英以左金、龙荟清肝泻火，热除则痛止。", ["弦", "滑"]], "14338": ["病机", "脉微弱，为阳气虚衰、中气内伤之象。发热数日，误投凉解，致呕吐自汗、肢冷神疲，此内伤虚寒，非伏暑也。故用黄芪建中温中补虚，加龙、姜、苓、橘以安中，投剂即安。", ["微", "弱"]], "14339": ["妇人", "脉形滑数，滑主痰热，数主热盛。怀妊四月，寒热如疟，误发散安胎，致舌黑神昏、大渴便泄，乃伏暑失清，热陷营血。然脉滑数、气息调和，是胎未坏，故重用气血两清而胎安。", ["滑", "数"]], "14340": ["病机", "体丰脉不甚显，而隐隐然弦且滑，弦为肝强，滑为痰盛。久泻脘痛、齿痛、汛事不调、畏热，皆肝强痰盛、郁而化热之征。前医妄补，反锢其痰。孟英辨为实证，非虚寒也。", ["弦", "滑"]], "14341": ["病机", "脉滑苔厚，溺赤痰浓，滑主痰热，厚苔主里实。哮发于冬，前医作虚寒治更剧，实由痰热壅肺。故用知母、花粉、杏、贝、苓、滑石等清化痰热，热清痰消则哮安。", ["滑"]], "14342": ["病机", "脉弦硬无情，弦主肝木，硬为胃气将绝、真阴耗竭之象。壮年霉疮过服寒凉伤阳，继又温补无度，致热药竭阴，津液灼烁为痰，木火内焚，溲绿如胆汁，乃水源欲绝、东方色露之危候。", ["弦", "硬"]], "14343": ["误治", "脉形空软促数，空软为营血暴脱、阴液亏虚，促数为热盛邪陷。冬温失于清解，误服归、柴、姜、术、朴等温燥，致崩血一阵。苔黑舌绛、足冷息微，皆热药劫阴、营血下脱之误治危证。", ["空", "软", "促", "数"]], "14344": ["病机", "脉滑且数，滑主痰饮内盛，数主热邪亢盛。患者素患痰嗽，今病温邪挟宿饮上逆，故脉见滑数。滑为痰浊壅盛之象，数为温邪内炽之征，与面赤痰喘、谵语神昏、渴饮不饥等症相应，说明痰热互结、邪扰心神。孟英断为温邪挟饮，法当清解，正是从滑数脉中悟出热与痰搏之病机。", ["滑", "数"]], "14345": ["病机", "脉数而形瘦，舌色乾红，为阴虚热胀之候。数脉主热，然此热非实热，乃阴液亏耗、虚热内生所致。温补之药愈耗其阴，故脉愈数、肌愈削，干呛气急，与女子风消息贲相类。孟英以极苦泄热、微辛通络法治之，正是针对阴虚络痹、热郁胀满之病机，非气分实胀可比。", ["数"]], "14346": ["病机", "脉弦软，苔黄腻，为饮证之脉。弦主饮邪内停，软示非实热坚结。患者嗜浓茶，茶性寒凉而味变甘浊，酿湿生饮，阻遏气机，故脘痛呕吐、二便秘涩。医误作寒治，姜萸沉附更煽风阳，饮藉风腾，但升不降，宛似关格。孟英以连、楝、栀、芩清降，旋覆、竹茹等涤饮，正是针对饮郁化热、风阳上逆之病机。", ["弦", "软"]], "14347": ["病机", "脉弦细以数，舌绛大渴，为真阴大虚之证。弦细主阴血亏少，数主虚热内扰。患者骤患腹胀，脐间出脓，外科误与温补内托，耗竭真阴，故脉见弦细数。孟英谓耆、术、归、桂皆为禁剂，以甘露饮加西洋参、花粉等清润之品，正是针对阴虚液燥、虚热内炽之病机，非实热壅滞可比。", ["弦", "细", "数"]], "14348": ["病机", "脉左数右滑，皆极虚软。左数主肝阳内动，右滑主痰浊内盛，虚软则示积劳久虚之体。患者虽感冬温，邪尚轻微，因劳倦耗阴，肝阳化风，烁液成痰，逆升而厥，俨似温邪内陷。孟英断为肝阳内动、痰热上扰之候，故用犀角靖内风、牛黄化痰热，正是从数滑虚软中识得本虚标实之病机。", ["数", "滑", "虚", "软"]], "14349": ["病机", "脉弦而数，弦主肝阳亢盛，数主热邪内迫。冬暖雷震，肝阳应之而动，血随气上溢，故鼻衄如注。孟英谓不可因体肥头汗畏虚脱而进温补，投以元参、生地、犀角、牡蛎等凉血潜阳之品，正是针对肝阳化火、迫血妄行之病机。弦数脉在此为肝热亢盛、血热上溢之明征。", ["弦", "数"]], "14350": ["病机", "脉滑数而沉，滑主湿热壅滞，数主热邪亢盛，沉主病在里。患者赤痢、面赤苔黄、手足冷过肘膝、当脐硬痛、小溲涩少，为伏热内蕴、湿热积滞肠道之候。脉沉说明热伏于里，非表热可比；滑数则示湿热搏结。孟英断为伏热为病，用大剂芩、连、栀、楝等清泄里热，正是从沉滑数脉中识得热伏于里、湿热壅滞之病机。", ["滑", "数", "沉"]], "14351": ["病机", "脉虽不甚有力，右部微有弦滑，苔色黄腻。弦滑主痰饮内停，右部候肺，说明痰热壅肺。患者咳嗽、痰冷、咽喉阻塞、饮食碍进，医作肾虚水泛治而无效。孟英谓虚寒乃本体，痰咳乃新受外邪，积补生热，故苔黄腻。以苇茎汤加雪羹等清热化痰，正是针对痰热壅肺、兼有药误之病机，非纯虚寒可比。", ["弦", "滑"]], "14352": ["病机", "脉滑数有力，滑主痰湿，数主热，有力为实，故断为气实血热。患者怀娠漏血，前医误补，反助病势，血热妄行，上溢为吐血，下溢为漏血。脉证相符，非虚证，故补药无效。胎无血荫而不长，但不堕者，气分坚实耳。", ["滑", "数", "有", "力"]], "14353": ["病机", "脉数舌绛，数主热，绛为热入营血之象。本案便血本属湿热，医投温补，血虽止而湿热未去，反伤阴液，致泄泻浮肿。脉数舌绛提示热邪未清、阴液已伤，故以清热利湿、养阴之剂而愈。", ["数"]], "14354": ["病机", "脉弦数而滑，弦主肝，数主热，滑主痰。产后阴亏，肝阳偏亢，侮胃乘脾，加以温补涩滞，气机不降，故见寒热气逆、自汗不寐、口渴善呕、杳不纳谷。脉象反映肝阳有余、痰热内阻之病机，治以肃肺和肝胃。", ["弦", "数", "滑"]], "14355": ["病机", "右部沉滑，沉主里，滑主痰。症见恶寒头痛发热似伤寒，而心下疼胀、苔黄不渴、溲如苏木汁，为痰热内蕴。先以葱豉解表，后清痰热，吐胶痰而纳复。脉沉滑提示痰热在里，非单纯表证。", ["沉", "滑"]], "14356": ["病机", "脉有滑数之象，滑主湿痰，数主热。溺后出血水甚痛，虽溲长激似非火证，然脉滑数说明湿热下注、灼伤血络。故以清热利湿、凉血止血之剂取效。脉象为辨证关键，不可仅凭自觉症状断为非火。", ["滑", "数"]], "14357": ["病机", "脉弦数，弦主肝，数主热。赤痢延久，苔黄渴饮、腹胀而坠、五热夜甚，为湿热蕴结、肝经郁热之象。脉弦数反映热邪内盛、肝气不舒，故用白头翁汤合金铃子散清肝凉血、行气止痛而愈。", ["弦", "数"]], "14358": ["病机", "脉伏恶寒，似阴厥，然口渴溲赤，真情已露。脉伏为热邪内郁、阳郁不达之假象，非虚寒。至第七日泻红水、溺管痛、呕恶烦躁，脉显滑数，说明热邪下行、痰热内盛。脉伏之证须结合症候辨真假，不可泥于肢冷脉伏即断为寒。", ["伏", "滑", "数"]], "14359": ["病机", "右关尺弦大而滑，弦滑主痰，大主热。腹中绞痛、泻血如注、面油红、喘逆不寐，为痰热内蕴、迫血妄行。左脉颇和，病在右关尺，提示痰热结于中下焦。脉象明确痰热为患，故以清热化痰、凉血止血之剂取效。", ["弦", "大", "滑"]], "14360": ["病机", "脉洪大，按腹如烙，为热结在肺，邪热炽盛之象。患者久患痰嗽气逆，夏初恶寒，热结在肺，误服理中汤致痰中带血、气喘而厥、二便不通、冷汗腹胀，皆因热邪内壅，肺气不降，腑气不通。洪大脉主热盛，与腹如烙相应，说明热结于里，非虚寒之证。", ["洪", "大"]], "14361": ["病机", "脉虚细，苔黄腻，咽燥溺赤，两膝后筋络酸疼而不红肿，卧则痛不可当，为阴虚于下，火炎于上，血不养筋。虚细脉主阴血不足，筋脉失养，故酸痛彻夜；虚火夹湿热上炎，故苔黄腻、咽燥溺赤。治以煎剂清上，丸药培下，标本兼顾。", ["虚", "细"]], "14362": ["病机", "脉沉弦，因惊而致不语不食、不寐不便，别无他苦，为惊则气乱，痰气内阻，神机不运。沉弦主气郁痰凝，惊则气逆，痰随气升，蒙蔽清窍，故不言不食；气机不畅，故不寐不便。治以化痰开窍、调气宁神，使气顺痰消，则神复而言。", ["沉", "弦"]], "14363": ["病机", "脉至滑数，舌不能伸，苔黄腻，遗溺便秘，目不交睫，胸腹按之不柔，为温邪入心，热痰内闭，神昏不语。滑数脉主痰热内盛，热极神外越，故客未入室而先知。下证已备，热结阳明，故便秘溺遗。治以白虎汤加减清心化痰，投剂即谵语滔滔，乃热势外达之象。", ["滑", "数"]], "14364": ["病机", "脉软汗多，热不甚壮，苔色厚腻，呕恶烦躁，痰多腿酸，显是湿温。软脉因热为湿所持，湿蕴化热，故脉不洪数而软；汗多乃湿郁热蒸，非虚脱之汗。湿温不可从表治，更勿畏虚率补，误投参、归、熟地则增湿益热，病日以剧，终至不救。", ["软"]], "14365": ["病机", "脉数大渴，汗多苔黄，发热泄泻，骨瘦如豺，音嘶气逆，为热盛于阳明，肺移热于大肠。数大脉主热盛，大渴汗多乃热灼津伤；泄泻日久，形瘦音嘶，气逆，是热邪未清而气阴已耗。治以竹叶石膏汤加减，清热生津，十余剂向愈，后大解反坚燥，继与滋养而康。", ["数", "大"]], "14366": ["病机", "脉滑实，腹胀口干，身面渐黄，腿痛异常，为湿热内蕴，腑气不通。滑实脉主实热积滞，湿热郁蒸，故发黄；热结于里，故腹胀口干；湿热下注，故腿痛。医以清解未效，孟英用茵陈大黄汤通腑泄热，两剂便行而各恙霍然，说明病机在阳明实热。", ["滑", "实"]], "14367": ["病机", "脉弦劲，舌绛不饥，左目胞起瘰，痛及眉棱、额角、巅顶，脑后筋掣难忍，为肝阳化风，火升痰壅，络脉拘急。弦劲脉主肝风内动，风火循经上扰，故痛连巅顶脑后；舌绛不饥，为热灼阴伤。医投风剂反剧，治以固本合二至、犀、羚、牡蛎等，育阴潜阳，息风通络。", ["弦", "劲"]], "14368": ["病机", "脉滑数而舌紫苔黄渴，滑主痰湿食积，数主热盛，合见为湿热壅盛、痰火内郁之象。酷热之秋生疖如疔、溲秘或频、便努挣不下，皆湿热下注、腑气不通所致；卧不能收摄乃热扰心神。脉滑数正是实热痰湿之征，故用白虎汤加清热生津之品而痊，非虚证可温补。", ["滑", "数"]], "14369": ["病机", "脉洪滑且数，洪为热盛气分，滑主痰热内壅，数主邪热炽盛。汛至而壮热狂烦、谵语欲刎，乃热入血室、瘀热互结；脘闷腹胀拒按、苔黄尖绛、畏明口渴，皆阳明实热与血分瘀热并见。脉洪滑数正合大实大热之候，故用桃仁承气汤加犀角石膏等大破其血、大清其热，继以脉滑苔黄腹胀再投小承气。", ["洪", "滑", "数"]], "14370": ["病机", "脉虚细中兼有弦滑，虚细为阴血亏虚之本，弦滑乃痰饮内停、肝气横逆之标，合为阴虚挟痰之候。素患脘痛晕厥、腰疼腿木、胸闷气逆不能卧，皆阴亏肝旺、痰饮上逆所致；温补后喘汗欲脱、杳不思谷，更伤其阴。脉象虚实并见，故治以滋阴调肝、祛饮利痰，两不相碍。", ["虚", "细", "弦", "滑"]], "14371": ["病机", "脉细涩而舌绛无津，细主阴血不足，涩主津亏血少、脉道不利。高年阴亏，伏暑伤液，又经枳朴槟楂燥烈攻伐，胃汁更伤，故肢冷自汗、杳不进谷、脘闷腹痛、溲牵疼。细涩正是阴液枯涸、气血不充之征，非实滞可攻，故用滋阴养液兼调肝气而痛闷渐去、汗止肢温。", ["细", "涩"]], "14372": ["病机", "脉迟微，迟主阳虚阴盛、脏腑虚寒，微主阳气衰微。滞下色白不黏、不饥不渴、腹微痛而不胀，皆脾肾阳虚、寒湿内停之象，与热痢色赤黏秽者迥异。脉迟微正合虚寒之本，故进大剂真武汤加参温阳健脾而愈，示人滞下亦有虚寒当温之一途。", ["迟", "微"]], "14373": ["病机", "脉细数，细主阴血亏虚，数主热邪内炽。五色痢并见、神昏肢搐、大渴茎肿、腹痛夜热，乃热毒深入营血、阴液耗伤之危候；前医误升提温补致肢冷自汗、液脱肛坠，亦属药误。细数之脉示热盛而阴伤，故用白头翁汤加犀角生地银花等清热解毒、凉血养阴，热退神清而愈。", ["细", "数"]], "14374": ["病机", "脉象六阴、按之如无，乃高年阴液枯竭、脉道不充之候，非阳虚当温。音嘶痰嗽、舌绛无津，继转滞下色酱、脐旁坚硬按之趯趯，皆藏热由府而出、阴亏热结之象。脉之如无正示阴液难充，故始终以甘凉清润为法，忌温燥，服犀角地黄知母银花苁蓉等而痢止、舌润而愈。", []], "14375": ["病机", "脉软而苔腻，软主正气不足、湿邪困阻，腻苔主湿浊内蕴。此疟乃伏邪所化，非正疟寒热往来之属，湿浊阻于膜原，故脉软不弦不紧。既为伏邪湿化，则风寒药、姜枣汤皆不可犯，恐助湿生热。故用知芩橘半滑朴杏斛等清化湿浊、宣畅气机，一剂而病若失。", ["软"]], "14376": ["病机", "脉细为阴血不足之象，痰咸乃肾虚水泛之征。久患痰嗽碍卧，脉细痰咸并见，说明阴虚水泛、虚火上炎，故非温补参术所宜，当用熟地大剂滋填肾阴，使水归壑而痰嗽自平。原文'阴虚水泛，非此不为功'正点明此脉此痰所主之病机。", ["细"]], "14377": ["兼症", "右脉洪滑主里热痰盛，虽舌黑而胎固无恙，说明热在气分而未伤胎元。病由伏暑，育阴滋腻则邪恋，小柴胡中人参、半夏、姜、枣温燥，反助暑热，故咽疼舌黑、心头绞痛。脉形细数又示阴分渐伤，故治当清暑透邪，不可拘泥伤寒和剂之法。", ["洪", "滑", "细", "数"]], "14378": ["病机", "右脉大主肺胃热盛，口渴苔黄为伏热在肺之征。病起瘄后余热未净，误投滋补数月，腻滞留邪，故脉右大而病日甚。热伏既久，非清解不为功，故用滑石、知母、花粉等清透肺胃，服后遍身发斑，正是伏热外达之象，脉大为实热之据。", ["大"]], "14379": ["病机", "脉虚促欲绝，虚为正气不支，促为热盛阴伤、脉道急促。患感误作虚治，补及旬日，邪热内陷营分，故舌卷痉厥、腰以下不能动。此非虚脱，乃营热炽盛、阴液将竭之危候，故先灌紫雪、犀角地黄汤清营凉血，厥止而黑苔渐退，脉虚促正是热灼营阴之反映。", ["虚", "促"]], "14380": ["预后", "左部数主热盛，右手俨若鱼翔，乃脉来浮泛无根、如鱼游水之死候，痰嗽气促、自汗瘛疭、苔灰渴甚，皆热炽阴伤、气液将竭之象。孟英谓'据脉莫能下手'，正因鱼翔之脉示胃气将败，预后凶险，故竭力以竹叶石膏汤清透气热，冀挽回于万一。", ["数", "鱼翔"]], "14381": ["病机", "脉至细数，细为阴亏，数为热盛，合腰腿痛如刀割、苔黑燥、溺赤便黑，显系温邪深入少阴、真阴内损、热灼营血之候。故用西洋参、麦冬、生地、犀角等甘凉濡润、清营救阴。后舌绛倍加、水饮难下，正是真阴涸竭之征，脉细数实为热伤少阴之明证。", ["细", "数"]], "14382": ["病机", "脉甚滑数，滑主痰盛，数主热炽，与多疑善恐、寡言善笑、时或遗精诸症相合，说明痰火内扰、心神不宁。原文'脉与证合'点明滑数之脉正应痰火之证，故从痰火论治，用元参、黄连、竹黄、栀子等清化痰火，送服当归龙荟丸泻肝火，四帖即效。", ["滑", "数"]], "14383": ["误治", "脉沉数，沉主里，数主热，溏泄而脉沉数，说明伏邪内蕴、热迫大肠，泄泻正是伏邪自寻出路。医者不察，误投温补健脾，泻虽暂减而热得补而不行，遂致发热昏痉、咽喉黑腐，内陷厥阴。原文'病起泄泻，何必为寒'正斥温补之误，脉沉数实为伏热之据。", ["沉", "数"]], "14384": ["病机", "脉沉弱而弦，沉弱为久病胃阳伤、痰饮内停之象，弦主肝气挟痰饮上逆。患者脘痛、按之漉漉有声、便秘溲赤、口渴苔黄、杳不知饥、绝粒、药入即吐，皆肝气犯胃、痰饮上逆、胃失和降之候。脉证合参，病机为肝气挟痰饮上逆，胃阳久伤。", ["沉", "弱", "弦"]], "14385": ["病机", "脉微无神，为精气神三者交虚之候。患者牝疟二旬，倦卧奄奄、便秘、溺赤不饥、痰多口甘、苔黑腻蒙茸，皆元阳衰微、精血亏耗、痰浊内阻之象。脉微无神正合虚寒本质，非伏暑实邪，故以温补大剂扶阳填精，使寒后始热、苔退痰少。", ["微"]], "14386": ["病机", "脉滑主痰湿内蕴。陈媪牝疟月余，腹胀便秘、嗳多不饥、口淡，皆痰湿阻滞中焦、气机升降失司之候。脉滑与口淡、不饥相应，说明痰湿内盛而非虚寒，故以连、朴、橘、贝等化痰行气之品取效，与前案虚实相反。", ["滑"]], "14387": ["病机", "脉象弦驶，弦主肝阳上亢，驶为数急之象，示肝阳浮越、气逆上冲。患者夜坐阳升，饮酒益浮肝阳，惊则气逆，故心跳欲吐、气逆如喘、肢麻手握、语言难出。脉弦驶正合肝阳化风、痰气闭结之机，故以苏合香丸辛香通气而愈。", ["弦", "驶"]], "14388": ["误治", "脉弦细本似虚象，但弦细而有力，说明虽细而有根，非纯虚之候。前医误认体虚，径用温补，致呃忒不休、气冲碍卧、饮食不进，乃温补助热、气逆上冲之变。孟英凭“有力”断为误补，以栝蒌、薤白、小陷胸等清降痰热而瘳，示脉须辨有力无力。", ["弦", "细"]], "14389": ["病机", "脉弦缓，弦主痰滞，缓为湿象，非妊娠之滑数，亦非虚损之细弱。患者产后一载经未行，腹不胀，脉弦缓，结合呕吐发热、眩晕心嘈、溏泄、口渴溲痛，乃血虚痰滞而感冬温。脉弦缓正示痰湿内滞、血虚未复，故以清透冬温、化痰调血之剂取效。", ["弦", "缓"]], "14390": ["病机", "脉细弱主气血阴阳俱虚。患者血痢半年，阴血耗伤，下元亏虚，故口干、腰膝酸疼。脉细弱与腰膝酸疼并见，说明久痢伤及肝肾精血，非湿热余邪未尽。故以鹿角霜、苁蓉、枸杞、杜仲等温养肝肾、填补精血，佐熟地、血余、石脂固涩，十余剂而痊。", ["细", "弱"]], "14391": ["病机", "脉沉弦而数，沉主里，弦主肝郁，数主热。患者周身麻木、四肢瘫痪、口苦而渴、痰冷如冰、气逆欲呕、汛愆腹胀、溺热如火、间有发厥，皆肝经郁热、痰火内闭、气机逆乱之候。脉沉弦数正合热郁于里、肝风挟痰上扰之机，故以清肝泻火、化痰降逆取效。", ["沉", "弦", "数"]], "14392": ["病机", "脉右部弦大而强，弦主气逆痰滞，大主邪盛。本案冬温挟痰，误用温散，致气不肃降，故见目瞪不语、面赤气逆、昼夜需人抱坐。脉弦大而强反映痰热壅盛、气机逆乱，与‘误提而气不肃降’相应，非虚证。", ["弦", "大"]], "14393": ["病机", "右脉弦细芤迟，弦主暑邪内郁，细芤迟示阴血不足、脉道空虚。年高体弱，吸受暑邪误作虚治，邪愈盛而正反虚，故脉虚证实。口渴溲涩、面赤自汗为暑热内迫，脉象与‘邪盛正虚’病机紧扣。", ["弦", "细", "芤", "迟"]], "14394": ["预后", "脉至细数无伦，细为阴血亏耗，数为热邪亢盛，无伦示脉律不齐、阴将竭矣。证交三十八日，昏谵痉厥、两手拘挛如角弓反张，皆肝无血养、阴竭风动之候。脉象提示阴液将竭、邪热鸱张，故势极危殆。", ["细", "数"]], "14395": ["病机", "脉弦滑而微数，弦主肝风，滑主痰热，数主热盛。患感误治逾月，昏痉谵语、六昼夜不交睫，舌缩苔垢，乃痰热内闭、肝风鸱张。脉象与‘误药酿成大证’相应，尖虽卷色犹红润、二便不秘，尚存一线生机。", ["弦", "滑", "数"]], "14396": ["主病", "脉滑而洪，滑主痰湿内蕴，洪主阳明热盛。鼻衄数升、苔黄大渴，显系阳明气分热炽、迫血妄行。脉洪滑与白虎汤证相应，投之即安。后左尺细数而芤、右尺洪大，为女劳复，阴虚火旺之象。", ["滑", "洪"]], "14397": ["病机", "脉弦滑而微数，弦主肝火，滑主痰浊，数主热。时虽春暮天气酷热，劳则火升，挟素有之痰上扰清窍，故目偏左视、扬手妄言。苔黄脘闷亦痰火内蕴之征。脉象与‘火升挟痰’病机相合，故用清火豁痰而愈。", ["弦", "滑", "数"]], "14398": ["病机", "脉沉而弦，沉主病在里，弦主气滞饮停。右胁痛、音瘖、仰卧不能反侧、气逆如奔、便溺不行，皆痰饮内结、肝肺气机壅塞所致。误用温运益甚，脉沉弦正是饮邪深伏、气机不畅之明证，故以旋覆赭石等降气涤饮而效。", ["沉", "弦"]], "14399": ["预后", "脉促歇止，促主阳盛热结，歇止示脏气衰败、脉道不利。醉饱后胀闷便闭，仍饮酒食肉，致热结阳明、痰火上冲，满舌黄苔秽腻。脉促歇止而体丰肉颤，证属邪实正虚，预后极危，故不与药，果至胀裂而死。", ["促", "结"]], "14400": ["主病", "脉右手洪大滑数，洪大主热盛，滑数主痰热内壅。症见呃忒苔腻、便秘痰多、心下拒按，显系痰热结胸之候。右手脉候肺胃，洪大滑数反映热痰壅阻中上二焦，故与小陷胸汤加味清热涤痰而安。", ["洪", "大", "滑", "数"]], "14401": ["病机", "脉弦数而滑，弦主肝郁，数主热，滑主痰。症见目疾、腹中痞胀痛不可当、便秘形消，乃肝郁痰滞误补致殆。弦数滑脉正合肝郁化火、痰热内结之病机，故用金铃子散合雪羹及滚痰丸等清肝涤痰。", ["弦", "数", "滑"]], "14402": ["误治", "本段未识脉名，述麻疹误用温散致气喘痰升、喘汗濒危。前医见瘄点不绽，连进柽柳等温散，更用麻黄定喘，反耗气伤津，致痰热闭肺。孟英投白虎加西洋参、竹叶而愈，示疹证宜清肺透邪，温散为大忌。", []], "14403": ["病机", "右脉洪滑而口渴，洪主热盛，滑主痰。症见瘄未齐而痰嗽气喘、苔白滑、溲不赤，乃暑邪薄肺，挟素有之痰阻其治节，气机不行而疹不能达。脉证相符，故用竹叶石膏汤合苇茎清肺化痰，忌温散凉血。", ["洪", "滑"]], "14404": ["病机", "脉弦伏而滑，弦主肝郁气逆，伏主气机郁闭，滑主痰。症见不知饥、眩晕便秘、时欲昏厥，胸腹无胀闷，旬余不更衣，乃惊则气乱，挟痰逆升，正合“诸厥应下”之旨。故用旋赭栀连等降气涤痰。", ["弦", "伏", "滑"]], "14405": ["病机", "脉沉弦，沉主里，弦主肝郁、主痛。症见腰腿串痛、闻响声即筋掣、苔腻便秘，乃广服温补致积痰蕴热、胶固不开，肝郁化火生风。沉弦脉反映痰热内结、肝气郁滞，故用雪羹、羚楝、胆星等清肝涤痰通络。", ["沉", "弦"]], "14406": ["病机", "脉甚滑数，滑主痰，数主热。症见体厚痰多、扬掷谵妄、舌绛面赤、渴饮便涩，乃暑热挟痰内闭心包，阳明热盛。滑数脉正合痰热壅盛之机，故用大剂白虎加犀角、元参、滚痰丸等清心涤痰，脉证渐和。", ["滑", "数"]], "14407": ["预后", "脉细数，细主阴血亏虚，数主虚热。症见产后乳多善饭而形遽瘦、减餐、舌光绛，乃乳溢过中，精血耗竭，虚劳之候。脉细数示阴血枯涸、虚热内扰，故断为急劳，药不可为，预后不良。", ["细", "数"]], "14408": ["病机", "脉数无伦，是温散补燥诸药助邪烁液、津液耗伤而热邪亢盛之象。暑疟本宜白虎清热，前医误用温补，致邪热愈炽、阴液愈亏，故汗渴不已、狂乱如故。脉数而失伦次，正示热盛津伤、邪未解而正已耗，故虽宜白虎，却不可监以桂枝助热耗津。", ["数"]], "14409": ["病机", "右脉滑数上溢，右主肺胃，滑为痰，数为热。此由升散温燥之剂烁其阴液，肺胃之气窒塞不能下行，痰热上逆，故见咽疼口糜、呃忒噤口、体厚痰多、身热面赤。脉证相参，非阳虚欲脱，实为阴伤痰热壅塞之候，故用大剂肃清而效。", ["滑", "数"]], "14410": ["病机", "脉至洪数不清，洪为热盛，数为热急，不清者热邪挟湿浊壅遏之象。疟痢并作、寒少热多、滞下五色、面垢苔黄、干呕口渴、溺赤汗出，皆暑湿热邪充斥三焦、气血两燔之候。洪数不清正合大剂芩连滑朴石膏知母清解湿热之治。", ["洪", "数"]], "14411": ["病机", "脉弦而软数，弦为肝盛风动，软为阴亏，数为热。患者本阴亏肝盛之质，误提表助其升逆、温补滞其枢机，致痰饮𫐖轕、风阳肆横，故目瞪神呆、气喘舌绛、肢搐而厥。弦软数正示阴亏于下、风阳痰热扰于上，故以息风镇逆、清热蠲痰取效。", ["弦", "软", "数"]], "14412": ["病机", "脉弦数软滑，弦数为热盛风动，软为阴亏，滑为痰。秋感服温散药而日重，苔黑肢瘛，是温散助热、阴液受灼、痰热内扰、风阳欲动之候。脉较和则示药后热势渐退、阴液渐复，故一路清凉渐以向愈，可见弦数软滑主痰热阴亏风动之机。", ["弦", "数", "软", "滑"]], "14413": ["病机", "脉甚数，数为热。虽久雨坐水号、人以为寒湿，然溲赤苔黄、口干燥呛，显系暑湿之邪从热化，体极阴亏故化热尤速。脉甚数正示热邪内盛，不可因便泄而犯温燥，故先轻清肃解，继甘凉撤热，终以滋填潜摄收功，误治则败。", ["数"]], "14414": ["病机", "原文未识脉名，仅言按之豁然，即脉来浮大中空、按之豁然而空，为血虚阳浮之象。半产后发热有时，久服滋阴不愈，正因阴血亏虚而阳气浮越，非纯阴虚。故投当归补血汤阳和之品而热退，继以小建中愈之，示脉豁然主血虚阳浮，不可执滋阴一法。", []], "14415": ["预后", "六脉皆数，数为热，见于冬令水旺之时，是阴亏火旺、真阴不能潜藏之象。久患痰嗽本属阴亏兼郁，误投温补致咳嗽复作、咽痛，阴液愈耗而虚火愈炎。冬见数脉，违时令之藏，故断其不能春，果验，示脉数失时主预后不良。", ["数"]], "14416": ["病机", "右寸脉滑大搏指，滑主痰，大主热盛，右寸候肺，提示肺中痰热壅盛。患者病嗽，前医误用温补，致肺气愈壅，咳逆愈盛，震动胞系而胎堕。孟英屏温补、纯清肺，治其病以保胎，正合“治病所以保胎”之旨。", ["滑", "大"]], "14417": ["病机", "脉弦滑右甚，弦主饮、滑主痰，右甚则痰饮偏盛于肺。喘嗽坐不能卧，进参汤反助痰壅，故切勿沾唇。孟英以栝蒌薤白旋覆等开降痰饮，投匕即减。石媪脉虚弦细滑，则兼虚象，故重加熟地，示病同体异之治。", ["弦", "滑"]], "14418": ["病机", "脉弦滑，弦主气郁，滑主痰，乃痰阻于络、气不得宣，故腿痛而噫气不已。其媳脉弦数以滑，数主热，滑主痰，弦主风阳，为痰挟风阳而为厥。两案皆以脉弦滑为痰郁之据，故用蠲痰息风、舒郁清营获效。", ["弦", "滑", "数"]], "14419": ["病机", "沉取滑数，沉主里，滑主痰，数主热，是积热深伏于内。患者久服姜食，致大溢血后火升不愈，服芩连则烦渴益甚，以苦化燥；用生地则闷滞，以甘缓中。孟英断为从前积热深伏，故用白虎加味恣服，渐吐胶痰而愈。", ["沉", "滑", "数"]], "14420": ["病机", "脉弦洪而数，弦主肝，洪主热盛，数主热，乃血因热而崩，胎因崩而堕。孟英用大剂凉血止血而安。后专科执暴崩宜补，用温药致虚象日著、汗出昏晕，孟英斥其“执死书以治活病”，明血热未因胎堕而化寒。", ["弦", "洪", "数"]], "14421": ["病机", "脉弦涩，弦主肝郁，涩主血瘀，察血紫黯，乃肝郁凝瘀所致陡吐狂血。证虽可愈，然不能惩忿，逾二年复吐竟不起。孟英用丹参、丹皮、茺蔚等化瘀解郁，复杯果愈，示弦涩为瘀滞之脉。", ["弦", "涩"]], "14422": ["病机", "脉滑实，滑主痰，实主邪盛，且便秘面赤、舌绛痰多，乃痰热内结、腑气不通之实证。年逾古稀而脉证俱实，孟英以承气汤下之霍然，示攻邪当凭脉证，不可拘于年高。", ["滑", "实"]], "14423": ["病机", "脉沉而涩，沉主里，涩主气机窒痹，体冷自汗宛似虚脱，惟二便不通、脘闷苔腻，乃痰热为补药所遏，一身气机窒痹不行。孟英以蒌薤旋赭等开降，复杯即减，示沉涩非虚，乃遏塞之象。", ["沉", "涩"]], "14424": ["病机", "左脉弦细而虚，右尺寸皆数，为阴亏气不潜纳之候。弦细而虚示阴血不足、脉道不充，虚而兼弦为虚阳不潜；右寸关数则气火偏旺。久患痰嗽、食减形消、夜不能眠、寝汗舌绛，皆阴亏阳浮、气不归元之象。前医误用耆、术助气，二陈、故纸、附、桂劫阴，故愈补愈剧。", ["弦", "细", "虚", "数"]], "14425": ["病机", "脉伏而弦滑，伏为邪热内闭、阳郁不达，弦滑主痰热内盛。患感连服温散，热邪不得外解，反灼液成痰，痰热蒙蔽心包，故旬日后倏然昏厥、自寅至辰不苏。脉伏非虚寒，乃热深厥深、痰热胶结之征，故用大剂犀羚、至宝丹清心开窍、涤痰泄热而安。", ["伏", "弦", "滑"]], "14426": ["病机", "脉沉弦且滑，沉为病在里，弦滑主痰热内蕴；舌绛黄腻苔、口苦溲热，皆痰热之征。心悸眩晕、汗出肢冷息微似虚，实由痰热壅遏、气机不通、阳不外达所致，误补则气机壅塞，故日剧。后脉极滑数，示病根未刈，痰热尚炽，故以蠲痰清气法应。", ["沉", "弦", "滑", "数"]], "14427": ["预后", "右寸脉促数不调，促数主热盛而气机急促不匀，右寸属肺，为风温之邪郁于肺卫、误用温散劫津之象。微感误表，热虽渐退而脉促数不调，孟英断为风温误汗、恐有骤变；越二日鼾睡，促数尤甚，终至语言难出而逝，示温病误汗、高年阴液枯竭之危候。", ["促", "数"]], "14428": ["病机", "脉见芤数，芤为中空、阴血亏耗，数为热邪炽盛。烟瘾之人津液素亏，复吸温邪，热炽液枯，故舌绛无津、壮热神昏、茎缩自汗，有阴虚阳越、热炽液枯之险。芤数并见，示阴竭于内而阳热鸱张，故用壮水息风、潜阳镇逆、益气充津、蠲痰清热标本并治。", ["芤", "数"]], "14429": ["病机", "脉仍虚弦，略加软数。虚弦为根蒂虚而兼怫郁，软数则暑热内侵、滞下伤阴之象。年逾七旬遭惨痛，咳嗽气逆痰咸、夜多漩溺，本属肾虚不纳；夏间吸暑患痢，脉虚弦加软数，示虚体兼暑热，故前方增滑石去暑、吞香连丸治痢而瘳。", ["虚", "弦", "软", "数"]], "14430": ["预后", "脉甚细数，细为阴血亏少，数为阳热亢盛，舌绛无津、间有讝语，乃真阴欲匮、阴竭阳亢之候。体厚善饮而气逆，误从虚治，渐至一身尽肿，外候虽轻，脉象依然不改，故孟英坚辞不肯承手，寻果不起。细数之脉示阴液难复、阳热独亢，不拘何病均忌。", ["细", "数"]], "14431": ["病机", "脉至洪滑弦数，洪为热盛，滑主痰，弦数主肝胆火炽、热迫营血。患感误投温散，遍身麻瘄，汛事适来，医反进小柴胡汤升散温燥，遂狂妄莫制，目赤苔黄、大渴不寐。洪滑弦数示温邪化热、气血两燔，故用大剂清卫凉营、犀角地黄之类而安。", ["洪", "滑", "弦", "数"]], "14432": ["病机", "脉洪数七至，洪为热盛，数为邪热内迫，七至则热极。原文见“热壮神昏，汗出不止”“洞泻如火，小溲不行”，乃温邪误用温燥，热毒炽盛，充斥三焦，故脉洪数急疾。此脉主实热壅盛，与壮热、神昏、洞泻、溺闭相应，非虚寒泄泻。", ["洪", "数"]], "14433": ["预后", "初诊“脉甚迟缓”，虽苔黄便秘多言，热痰内阻而脉反迟，是邪深壅遏之象；后“脉形滑驶如蛇”，滑为痰热，驶如蛇则脉无胃气、动荡失序，故断其不起。此脉由迟缓转滑驶，示痰火鸱张而真元已败，主病进之危候。", ["缓", "滑"]], "14434": ["病机", "脉弦软而数，弦为肝火，软为营阴受灼，数为热炽。原文“肝火宜清”而误温补，致形瘦浮肿、胁背刺痛、心辣如焚、食入即吐，皆肝火挟痰上逆、伏热内郁之症。此脉主肝经郁火、阴伤痰阻，与诸热象相应。", ["弦", "软", "数"]], "14435": ["预后", "初诊“脉甚弦滑”，弦主痰饮，滑主痰热，舌光绛为热灼阴伤；久服温补，痰热愈壅。再诊“脉数七至”，数而急疾，为热毒亢盛、胃气已竭，故眠食尽废，断为不可救药。此脉由弦滑转数七至，主痰热化火、阴液耗竭之死候。", ["弦", "滑", "数"]], "14436": ["主病", "脉洪实滑数，洪为热盛，实为邪壅，滑为痰热，数为火炽。原文“目赤”“满面红肿，壮热神昏，舌绛大渴，腹微胀”，显系热毒挟痰上攻、腑气不通。此脉主实热痰火内结，与壮热、神昏、腹胀相应，故用两下而愈。", ["洪", "实", "滑", "数"]], "14437": ["病机", "脉弦滑，弦主肝郁，滑主痰湿。原文服透土长寿丹后“齿痛目赤，诸恙蜂起”，又“下部畏冷”，乃热毒内蕴、湿热下流，阳气不达。此脉主湿热痰火郁遏，与齿痛、目赤、腿冷并见，故用石膏、当归龙荟丸清泄。", ["弦", "滑"]], "14438": ["主病", "脉滑实而数，滑为痰湿，实为邪壅，数为热盛。原文“寒少热多，面目甚黄，苔腻大渴，腹胀溺赤，纳谷”，乃膏粱厚味挟暑湿热，壅阻中焦。此脉主湿热痰滞内实，与黄疸、腹胀、溺赤相应，故用承气加减清下。", ["滑", "实", "数"]], "14439": ["病机", "脉沉弦而细，沉为病在里，弦为肝风，细为阴血不足。原文“卒闻惊吓”“气逆肢冷，自汗息微，身面青绿”，乃素伤忧虑、阴亏血少，风阳陡动，气机逆乱。此脉主阴虚阳亢、肝风内动，与肢冷息微、面青相应，故用镇逆养阴。", ["沉", "弦", "细"]], "14440": ["病机", "脉滑且数，为痰热内盛之象，故见失音咽痛、口大渴，治以清肃而愈；其庶母脉弦细数，弦主肝风，细数主阴亏，故曰“兼阴亏风动”，症见头偏左痛、心悸欲呕、壮热烦躁，与肝阳化风、阴液不足相应。", ["滑", "数", "弦", "细"]], "14441": ["病机", "脉数而弦，数主热，弦主肝，形瘦口渴音微溺涩，乃“阴分极虚，肝阳炽盛，伏暑为痢”，故腹痛异常；治以白头翁汤加味清暑热、凉肝阴，与寒痢迥异，正因脉数弦示伏暑化热伤阴之机。", ["数", "弦"]], "14442": ["病机", "脉迟缓，浮取甚微，似属虚寒，然目眵舌光红、口不渴、静卧懒言，实为“暑湿内伏，而有燥矢在胃，机关为之不利”，湿胜热伏故脉不数；待下燥矢后脉证依然，继以凉润而痊，可见脉迟缓非阳虚，乃湿遏热伏之征。", ["迟", "缓", "微"]], "14443": ["病机", "脉虽沉伏难寻，而苔黄腻、口干溺赤，痛脉多沉，此非元虚欲脱，乃热郁气滞、邪闭于里，故腹痛自汗肢冷息微；从证不从脉，与连、朴、楝、栀等清通而康，示沉伏脉主实邪内闭，不可误补。", ["沉", "伏"]], "14444": ["病机", "脉细数，细主阴亏，数主热，症见小溲涩痛、发热头疼、不饥口渴、夜不成眠，乃“阴虚肝郁，化热生风，津液已烁”，渗利更伤其阴，故以滋阴清热、柔肝息风而愈，脉细数正示阴亏热炽之机。", ["细", "数"]], "14445": ["病机", "脉细而弦滑，口苦便涩，乃“素体多痰，风阳内鼓”，虽崩后而病不在血；后发狂，脉弦滑而数，弦主风阳，滑数主痰热，故以息风阳、涤痰热取效，脉象始终示风痰内动之病机。", ["弦", "滑", "数", "细"]], "14446": ["病机", "脉洪数，舌绛燥，洪为热盛，数为热炽，症见胸腹痛极、昏厥咽糜、水饮碍下，乃温补致热毒壅盛、灼伤津液；胎下已朽，咽腹之疾随愈，续用甘凉清热存津，脉洪数正示热毒充斥之病机。", ["洪", "数"]], "14447": ["病机", "脉弦而滑，舌绛口干，弦主肝阳，滑主痰，乃阳旺痰盛之体，久患淋漏、风斑，因广服温补酿病；后寒热如疟、善怒不眠、苦渴易饥，脉弦数倍常，弦数主肝火炽盛，故以清肺蠲痰、柔肝充液渐安，脉象示肝阳痰热为患。", ["弦", "滑", "数"]], "14448": ["病机", "脉甚弦软，弦主肝郁气滞，软主正虚。患者年五十余，初患目赤发热，误温散致泄厥，进补剂后少腹宿瘕攻痛，舌绛而渴，显系肝郁化火、阴液亏耗，兼有宿瘕。脉弦软反映肝气横逆而正气已伤，故用苁蓉、当归、龟板等柔肝养阴，佐以清泄。", ["弦", "软"]], "14449": ["病机", "脉弦滑，弦主肝热动风，滑主痰滞。新产次日便泻发热痉厥、谵语昏狂，恶露仍行，乃胎前伏暑乘新产血虚痰滞而发。脉弦滑正是暑热挟痰、内风鸱张之象，故用大剂犀、羚、元参等清营凉血、豁痰熄风，遍身得赤疹而痉止神清。", ["弦", "滑"]], "14450": ["病机", "初诊脉滑，作痰治；今冬复病误补，脉极细数，阴已伤矣。滑主痰饮，细数主阴亏火旺。痰饮为患，乍补每若相安，久补则阴伤火炽，故见目赤便秘、胸下痞塞如柈、闻声惊惕、寒颤自汗、肢冷如冰。脉极细数揭示痰火内郁而阴液耗损，非虚脱之证。", ["滑", "细", "数"]], "14451": ["病机", "脉甚滑数，滑主痰湿，数主热。患者秋患痢后溏泄未愈，怀娠后峻补，致温补酿痰助热，肺胃下行之令逆升，故两目赤障、气逆碍眠、脘疼拒按、痰嗽不食、苦渴无溺。脉滑数正是痰热壅盛之征，非虚证，故用清化痰热之剂。", ["滑", "数"]], "14452": ["病机", "脉弦细，弦主气滞，细主阴伤。腹痛不饥，误服参、术、姜、附温补，致疼胀日加、水饮不沾、沉沉如寐，苔色黄腻。脉弦细反映肝郁气滞而阴液已伤，湿热内蕴，故用枳、朴、萸、连、栀、楝等清肝理气化湿，二剂便行脉起而愈。", ["弦", "细"]], "14453": ["病机", "右寸沉滑，左手细数而弦。沉滑主痰壅肺气，细数弦主阴亏火旺。高年阴亏，温邪在肺，未经清化，率为补药所锢，致涕泪全无、耳闭不饥、二便涩滞、干嗽无痰、气逆自汗。脉象揭示痰热痹阻肺络而阴液耗伤，故宜开痹通胃，清化痰热。", ["沉", "滑", "细", "数"]], "14454": ["病机", "脉弦缓而滑，弦主肝风，缓主湿，滑主痰。年近古稀，左半不遂，颧赤苔黄，音微舌蹇，便涩无痰，此痰中也，伏而未化。脉弦缓而滑正是风痰内伏、肝阳化风之象，故用犀、羚、茹、贝、菖、夏等清肝熄风、化痰开窍，服后苔化音清，痰渐吐而愈。", ["弦", "缓", "滑"]], "14455": ["病机", "脉滑数，滑主痰，数主热。向患痰嗽，秋仲寒热如疟，舌绛苔黄，渴饮溲赤，动则喘逆，夜不成眠，痰多畏冷。此膏粱酿痰，温补助热，夏吸暑邪，互相𫐖轕。脉滑数正是痰热内蕴、暑邪留恋之征，故用羚羊、豆豉、连翘等清暑化痰，五剂热退。", ["滑", "数"]], "14456": ["病机", "左脉如无，是阴血大亏、血脉空虚；右弦软按之数，为气分热盛而兼痰湿。高年阴亏，肝血暴去，风阳陡动，故汗出神昏、肢冷搐搦、躁乱妄言。脉象示阴亏于下、热扰于上，非脱证，故参汤不可灌，当清热凉血、救阴息风。", ["弦", "软", "数"]], "14457": ["预后", "证见痉厥神昏、谵语痰喘，本属危候，然脉犹弦滑，弦主风阳，滑主痰热，脉象未至散乱无根，说明邪虽盛而正气尚能抗邪，生机未绝。故孟英断为可治，以清热息风、潜阳镇逆获效。若脉转虚散，则预后不良。", ["弦", "滑"]], "14458": ["病机", "脉坚体厚，坚脉主实，体厚示形气不衰，结合口渴苔黄、溺秘欲死，为湿热火毒壅结下焦、膀胱气化不行之实证。脉坚与苔黄口渴相应，故用知、柏、栀、楝清利湿热，佐当归龙荟丸泻火通便，实邪去则溺通。", ["坚"]], "14459": ["病机", "右寸候肺，脉软滑，软为虚，滑为痰，故曰肺虚而痰贮于络。卧难偏左，乃痰阻肺络、气机不利所致。脉象与咳嗽、偏卧难相应，治以苇茎、丝瓜络、贝母、蛤粉等清肺化痰通络，药证相符而愈。", ["软", "滑"]], "14460": ["病机", "脉弦滑而数，弦主少阳疟邪，滑主痰盛，数主热，合之则为温邪挟痰化热之象。脘闷便秘、口渴不饥、合目汗出，皆痰热内蕴、邪阻气机之症。高年虽虚，脉象属实，故补药断不可投，当以清化痰热为治。", ["弦", "滑", "数"]], "14461": ["病机", "脉弦洪而芤，洪为热盛，芤为中空阴伤，弦主肝阳亢逆。年逾花甲，冬服助阳药，热亢阴虚，迫血妄行，故鼻衄不止，面黑黯而红光亦虚阳上浮之征。脉象与热亢阴虚相应，治以大剂清热滋阴凉血而安。", ["弦", "洪", "芤"]], "14462": ["病机", "脉至弦洪豁大，左手为尤，左脉属心肝肾，弦洪豁大示心阳外越、内风鸱张，真阴亏于下而阳浮于上。大渴大汗、面赤足冷、妄言不瞑，皆阳越风动之候。脉象与证相符，故用龙牡、犀珠、龟鳖潜阳息风，佐滋阴之品。", ["弦", "洪", "大"]], "14463": ["病机", "脉甚弦洪滑数，弦主风，洪主热盛，滑主痰，数主热，合为痰热内盛、风火相煽之象。痘后清凉未辍而壮热肢瘈、呕吐苔黄、便秘汗多，乃新感温邪挟痰热内结。脉证相应，故用小陷胸加石膏、知母等清热化痰而安。", ["弦", "洪", "滑", "数"]], "14464": ["病机", "左脉弦细而数，弦为肝风，细为阴虚，数为心火；右软滑主痰盛于中。合观乃阴虚之体，心火炽、肝风动而痰盛于中，故见烦躁不眠、狂妄瘛疭。温药误投更助火动风，孟英先息风清火化痰，正合此脉机。", ["弦", "细", "数", "滑"]], "14465": ["病机", "脉细而弦，细为阴血不足，弦为肝木偏旺。素患肝厥，仲夏患感，内风虽未陡动，而便泄、渴饮痰多、不饥不寐，正是肝木乘脾、阴亏痰扰之象。白头翁汤加三甲、石斛、茯苓、竹茹，清肝潜阳兼养阴化痰，切中细弦之机。", ["细", "弦"]], "14466": ["病机", "脉滑而弦，滑主痰热内盛，弦主少阳不和。间疟寒少热多、不饥大渴、善呕无汗，乃痰热壅于阳明少阳，枢机不利。孟英投白虎汤加花粉、柴胡，清阳明之热、和解少阳，正合滑弦所主之痰热与枢机不利。", ["滑", "弦"]], "14467": ["病机", "脉弦细而数，弦为肝气郁滞，细为阴血亏虚，数为营分有热。腹胀减餐、牙宣腿痛、肌肉渐消，皆肝郁阴虚营热之候，非辛通温运所宜。故以乌梅、黄连、楝、芍等酸苦泄热柔肝，继以甘润滋填，终得汛准脉和。", ["弦", "细", "数"]], "14468": ["病机", "脉芤而弦数，芤主阴血大亏，弦数为肝阳偏亢、虚热内扰。久患脚气，筋掣上巅、龈痛指麻、腰酸目眩、口干食少、夜不成眠，皆真阴亏而筋骨失濡。带下太甚，阴液漏泄，故治病澄源以洁流，滋填潜阳而愈。", ["芤", "弦", "数"]], "14469": ["病机", "左洪数，右弦滑。洪数为肺胃痰热炽盛，弦滑为痰浊内壅。龈疼日久，身面浮肿、气逆不饥，乃阴分虽虚而痰热先盛。孟英先清肺胃痰热，投白虎加沙参、花粉、冬瓜皮等，肿消后再佐滋阴而龈疼止，先标后本之法。", ["洪", "数", "弦", "滑"]], "14470": ["病机", "两尺皆浮，左寸关弦。尺浮为肾失闭藏，寸关弦为肝木太过、独行疏泄。半产后营分不摄、淋漓数月，正合此脉。眉批言填补肾阴即涵养肝木，加黄柏苦坚、螵蛸涩固，故渐愈；然病久初痊即孕，涵蓄无权，终至胎堕。", ["浮", "弦"]], "14471": ["病机", "脉甚数，数为热盛。陡发寒热、咽痛大渴、脘闷舌绛，皆热邪充斥气营之象。孟英径投大剂犀、羚、元参、丹皮、桑、栀、银花、花粉、翘、蒡，清营凉血解毒。服后遍身发赤疹而热退知饥，是热从疹透、邪有出路之征。", ["数"]], "14472": ["病机", "脉洪而数，洪为热盛，数为邪热内迫，非虚寒之象。患者年近五旬、天癸已绝，前医误作肾虚、中虚，投温补而血下漏，愈补愈甚。此脉说明吸受暑邪，暑热炽盛，迫血妄行，故见渴饮苔黄、崩漏。温补助邪，故病剧。洪数之脉正合暑热内盛之机，与犀角、元参等清暑凉血之治相应。", ["洪", "数"]], "14473": ["病机", "脉弦数左溢，弦为肝气偏旺，数为热，左溢示肝阳勃升、气血上逆。患者体弱，医误与镇逆通补，势日甚。此脉说明因忿怒而肝阳暴升，故腹痛欲厥、便秘不饥、口苦而渴。弦数左溢正是肝阳上亢、郁热内盛之征，与雪羹、栀、楝、旋覆等清肝降逆之治相应。", ["弦", "数"]], "14474": ["病机", "脉形细数，细为阴伤，数为热盛，合面赤舌绛、溲涩便溏、渴饮汗多，是暑热内炽、阴液受灼之象。前医误用首乌、鳖甲、参、桂温补，致狂躁妄言，邪热愈炽。此脉说明暑证热盛而阴伤，非虚寒可补，与元参、银花、知母、芩、茹等清暑养阴之治相应。", ["细", "数"]], "14475": ["病机", "右寸关弦滑而浮，弦滑主痰实，浮示微兼客热；左关尺细软无神，主阴虚于下。合痰嗽喘逆、便秘不眠、微热口干，是阴虚于下、痰实于上、微兼客热之候。攻补皆难偏任，故以清化痰热之剂配熟地泡汤煎服，浊药轻投，清上滋下，正合此脉所主之病机。", ["弦", "滑", "浮", "细"]], "14476": ["病机", "脉象弦细软数，弦为肝郁，细软为阴亏，数为郁热。患者素属阴亏、情志抑郁，因远行持重而咳逆胁痛、杳不知饥、卧难著枕，苔腻痰黏、便难溲少。此脉说明肾气不纳、肝气不舒、肺气不清、胃气不降，虚实夹杂。故以沙参、枇杷叶、旋、贝清降，龟板、鳖甲、青铅纳肾，熟地汤煎服滋填。", ["弦", "细", "软", "数"]], "14477": ["病机", "脉涩口干，涩为营阴亏少、血行不畅，口干为热灼津伤。患者怀妊患感，昏谵不眠、善呕便秘、汗出不解，是营阴素亏而邪热内炽，热扰心神则昏谵，热灼津液则便秘口干。涩脉正示营阴不足、邪热内郁，与元参、石膏、知、芩、银花等清热养阴之治相应。", ["涩"]], "14478": ["病机", "脉至洪滑，洪为热盛，滑为实热壅盛，合两目肿痛不能略张、大渴便秘，是阳明热炽、邪热上攻之象。前医误投风药，致昏痉欲厥，乃风药助热升散。此脉说明热盛于里，非外风所致，故与白虎汤清泄阳明，二剂霍然，正合洪滑主实热之机。", ["洪", "滑"]], "14479": ["病机", "脉滑而长，滑主痰热内盛，长为气分热盛、邪势有余。患者患疟寒微热甚、旬余不愈，是阳明气分热盛之疟。前医虽用白虎汤，然石膏少且煨、兼不去米，力薄无效。此脉说明热盛于气分，当重用石膏、去米加花粉竹茹，大清气热，服之寻愈，正合滑长主实热之机。", ["滑", "长"]], "14480": ["病机", "脉弦滑，弦主肝郁，滑主痰饮。患者眩晕脘痛、筋掣吐酸、渴饮不饥、咽中炙脔，皆肝郁化火、痰热内阻之象。前医温胃反剧，更证非寒湿。孟英以和肝开郁清痰取效，脉象紧扣痰热郁结之病机。", ["弦", "滑"]], "14481": ["病机", "脉滑数而溢，滑主痰，数主热，溢为热势上涌。娠妇感邪，温散助热，致气冲不寐、痉厥脘闷、渴难受饮，痰热壅盛，上扰神明。孟英以小陷胸加清热涤痰之品，大剂投之，正合脉证。", ["滑", "数"]], "14482": ["病机", "脉弦滑上溢，弦主肝逆，滑主热痰，上溢为血随气逆。齿衄五日不止，去血已多，经事愆期，显系倒经。孟英用犀角、泽兰、牛膝、桃仁等凉血降逆，引血下行，脉证相合，故安。", ["弦", "滑"]], "14483": ["病机", "脉来弦涩而数，右寸关弦软以滑。弦涩主气滞血瘀，数主郁热，滑为痰邪。升降之令久窒，痰邪袭于隧络，关格将成。胁痛、络胀、食少便难、寒热，皆痰瘀阻络、气机不通之候。", ["弦", "涩", "数", "滑"]], "14484": ["病机", "脉浮弦洪滑，浮为热邪在表，弦主肝风，洪滑为痰热壅盛。类中昏瞀、遗溺痰升、汗多面赤，乃吸受热邪，复服参汤助热，风火痰热上扰。孟英清热息风化痰，脉证相应，故效。", ["浮", "弦", "洪", "滑"]], "14485": ["病机", "脉弦数，弦主痛主肝，数主热。腹痛因饱食羊肉面条，消导燥热杂投，痛甚渴吐，二便不行，显系肝胃热结、气机壅滞。孟英以海䖳、凫茈清热通降，佐栀、连、楝、龙荟丸泻热，脉证合参，故愈。", ["弦", "数"]], "14486": ["病机", "脉至弦数，重按少神。弦数为热，少神为阴虚。间疟寒微热甚，昏痉舌强，颧赤鼻冷，苔黄口渴痰多，证属伏暑挟痰，阴虚阳越。孟英先育阴潜阳，继清痰热，脉证相参，故获愈。", ["弦", "数"]], "14487": ["病机", "脉沉弦而缓，沉主里，弦主郁，缓主湿。外寒内热，饮不解渴，便溺皆行，温散即咽疼，显系痰热内伏，阳郁不达。孟英以犀、羚、元参、丹皮等清透痰热，脉证相合，故两帖而减。", ["沉", "弦", "缓"]], "14488": ["病机", "脉弦数右滑溢，弦主肝风，数主热，滑溢为痰热壅盛。患者年近古稀，肢厥头肿、讝语遗溺，前医误作虚风温补致剧。此脉说明痰热内阻、风温外侵，热痰蒙蔽清窍则讝语，风热上壅则头肿，非虚证可比，故以清化痰热、疏风透邪取效。", ["弦", "数", "滑"]], "14489": ["病机", "脉皆细数，细为阴亏，数为热烁。感证误投桂朴姜柴温燥，致痰血频咯、神瞀耳聋、苔黑溲少，真阴素亏而营液受烁。虽便溏不食，脉细数揭示阴虚为本，不可畏滋腻，故用西洋参、生地、二冬、龟板等甘凉濡润，五剂后脉渐和，阴复热退而愈。", ["细", "数"]], "14490": ["病机", "脉来弦缓，弦主肝郁，缓主痰湿。饱食后大吐而厥，厥回腹痛异常、口苦渴、二便不行，乃痰滞内阻而热伏厥阴，肝气无从疏泄。弦缓正合痰滞热伏、肝失疏泄之机，故投雪羹、栀、楝、元胡、萸、连等清肝化痰、疏泄厥阴，一剂痛减，再服便行。", ["弦", "缓"]], "14491": ["病机", "脉弦滑右甚，弦主肝郁痰结，滑主痰热，右甚则病在肺胃。三疟误用温散热补，致胸中痞结如柈、苔黄苦渴、溲如热汤、带下如注，显系痰热互结、阻于胸脘。脉弦滑右甚正应痰热壅结之机，故用小陷胸合温胆加薤白，吐胶痰后痞消，改甘凉而疟罢。", ["弦", "滑"]], "14492": ["病机", "切脉虚弦豁大，虚为阴血亏耗，弦为肝郁，豁大为气散不敛。娩后恶露日久，复遭悲恸，干嗽吐血、头痛偏左、不饥不眠，乃悲哀伤中、阴亏肝旺、气不收敛。虚弦豁大正示脏阴亏损而肝气浮越，故用甘麦大枣加熟地、首乌、鳖甲等养阴柔肝，服后脉渐敛而血止。", ["虚", "弦", "大"]], "14493": ["病机", "脉弦缓而滑，弦主肝，缓主湿滞，滑主痰热。患感发疹，热退而神气不爽、舌黑难伸、太息便秘、胸次拒按，乃痰热内结、腑气不通，热邪逗留胸膈。弦缓而滑正合痰滞热结之机，故投凉膈散加知母、花粉、枳实、竹茹，一帖苔退黄，再服下黑矢而神清向愈。", ["弦", "缓", "滑"]], "14494": ["病机", "左弦洪而数，右滑而溢，弦洪数主肝阳上浮化火，滑溢主痰热壅盛。面赤不眠、烦躁谵语、口甘渴腻、溲涩而疼、胸次痞结、大解未行，正是肝阳上浮、肺气不降、痰热阻痹，邪乃逗留。脉象与症相符，故用小陷胸合温胆、雪羹加旋薤开结，继以当归龙荟丸、通幽汤下黑矢而痊。", ["弦", "洪", "数", "滑"]], "14495": ["病机", "脉左弦数，右虚软。左弦数主肝火内扰，右虚软主脾肾气阴不足。梦遗久治不愈，耳出脓水、目泪难开、肩胁胸背酸疼、微寒热、食减神疲，乃阴虚火旺、肝经湿热上扰而脾肾亏虚。弦数示火，虚软示虚，故用三才封髓加龙牡黄耆桑丹栀菊，补虚清火并行，旬日而瘳。", ["弦", "数", "虚", "软"]], "14496": ["病机", "初诊脉弦滑，弦主肝郁，滑主痰火，故断为肝经郁怒火升，投当归龙荟丸而瘥。后病屡发，脉转弦涩，涩主瘀滞，合口苦苔黄、舌色紫黯、溺秘腹胀，知内有瘀滞，虽汛愆而脉证相符，故以雪羹加活血通利之品，下黑血而愈。", ["弦", "滑", "涩"]], "14497": ["病机", "脉弦滑洪数，不为指挠，弦主肝胆，滑主痰，洪数主火热，合神躁妄闻、如畏人捕，显系痰火壅盛、扰乱神明。故用石膏、黄连、礞石滚痰丸等清火逐痰，下其痰火后脉证渐平，继以清包络肝胆之有余而调神志。", ["弦", "滑", "洪", "数"]], "14498": ["病机", "诊脉迟涩，迟涩非寒，乃血热内蕴、营行不利之象，合喉舌皆赤、筋掣不眠，故用大剂清营而瘥。后太夫人脉来一息一歇，似脱而非脱，苔黄腻不渴、胸闷、嗅食极臭，断为暑湿内伏，脉歇正因湿阻气机，非虚脱可比。", ["迟", "涩", "弦", "滑"]], "14499": ["预后", "原文未识脉名，仅言「心脾之脉尚有根」，以脉有根为可望之凭。体弱汛多、便溏冷汗气逆，屡进参耆而危，是下虚误补其上。脉尚有根，说明心脾元气未绝，故用龙牡龟鳖等潜镇固摄，一剂转机，渐以向愈。", []], "14500": ["病机", "舌绛脉数，数主热盛，绛主热入营血，合头疼恶冷、呕吐肢冷，此热深厥深，断为斑疹之候而非受寒。故一意清透，点形圆绽，果未出痘。脉数贯穿火势甚炽，故始终清凉，不杂温升攻托，浆浓痂黑、便秘渴饮皆热盛之征。", ["数"]], "14501": ["病机", "右脉洪滑，洪主阳明热盛，滑主痰，合神呆目瞪、言语失伦、善饥善怒骂詈如狂，断为痰火蒙蔽心包，故用犀角、石膏、礞石滚痰丸而愈。其祖脉弦而缓，弦主络脉不和，缓非虚象，故曰非虚，与通络方吞指迷茯苓丸而瘥。", ["洪", "滑", "弦", "缓"]], "14502": ["误治", "咽痛本宜清降，疡科连与升散，致龈肿、牙关不开、舌不出齿、自汗脉涩。涩主阴血耗伤、脉络不利，绝谷濒危，显系升散劫阴、热毒壅结之误治变证。故洗去敷药，改以犀羚元参等清降解毒，数日而痊，眉批明言宜降反升之害。", ["涩"]], "14503": ["主病", "脉弦数，弦主厥阴，数主暑热，合搐搦间日而作、泛泛欲呕、口苦不饥、凛寒头痛、汛愆、溲热如火，断为厥阴暑疟。疟邪伏于厥阴，暑热内炽，故脉弦数，治以大剂犀羚栀菊等清暑泄热、凉肝息风，数日而愈。", ["弦", "数"]], "14504": ["病机", "脉滑实而数，滑主痰湿，实主邪盛，数主热。此乃湿温化热，邪壅气分，故见壮热昏狂、大渴溲赤、稀水旁流。前医但知湿甚，投平胃散温燥，反助热势。脉实数为里热炽盛之征，滑为湿浊未化，湿热交蒸，故以石膏、大黄下之而愈。", ["滑", "实", "数"]], "14505": ["病机", "脉细数而体瘦，细为阴亏，数为热炽。患者平昔阴亏，热邪藉风药而披猖，营液得温燥而干涸，故斑色绀、危险万分。细数脉示营液已伤，热毒内陷营分，非实热壅盛之比，故用大剂清营解毒、养阴透斑之品。", ["细", "数"]], "14506": ["病机", "脉甚滑数，滑主痰，数主暑热。苔色腻黄，乃平素多痰，兼吸暑热，痰热蒙蔽心包，故昏谵。化疟后脉较平，示邪有外出之机。暑脉颇类乎虚，痰阻于肺呼吸不调又与气虚短促相似，然脉滑数实为痰热内蕴，故坚持清解，不可妄补。", ["滑", "数"]], "14507": ["病机", "脉弦而滑，弦主肝郁气滞，滑主湿热痰浊。溲涩苔黄，显系湿热下注，气机不畅，致脱肛。虽属高年，脉不虚而弦滑，非虚证也，故清其湿热而痊。若误作气虚下陷而用升提温补，必助湿热，反致迁延。", ["弦", "滑"]], "14508": ["病机", "脉颇平和，非热盛之象。滞下昼夜百余行，不饥不渴而欲呕，腹痛上及心胸，乃寒湿内阻，气机凝滞。脉平和示无实热，与暑湿痢之脉数疾者大异，故断为寒湿，投姜、桂、萸、朴温化而愈。脉象平和在此为辨证关键，不可因滞下而妄清。", ["和平"]], "14509": ["病机", "脉滑数，滑主痰湿，数主热。畏冷不饥，苔黄溲赤，脘闷善呕，乃伏暑内蕴，痰热交阻，疟邪未透。脉滑数示里热痰盛，非寒疟之脉弦紧，故用竹叶石膏汤清伏暑而痊。若误认畏冷为寒，投温散则助热伤津。", ["滑", "数"]], "14510": ["病机", "脉皆滑，滑主痰；继则脉弦而数，弦主风，数主热。前证壮热耳聋、谵语昏狂、见人欲咬，乃伏暑挟痰，蒙蔽心包，故以犀角等加菖蒲、胆星、竹沥、牛黄驱风痰。后证发热善呕、头疼如劈、口苦耳聋、神识昏瞀，脉弦数，为伏暑挟内风鸱张，故用清暑熄风之品。", ["滑", "弦", "数"]], "14511": ["病机", "脉弦滑而搏指，右手较甚，弦主肝火，滑主痰热，搏指为邪实壅盛。久患吐血，渴喜冷饮，米谷碍于下咽，小溲如沸，夜不成眠，乃痰热壅肺，肝火犯胃，灼伤血络。久服滋阴无效，因滋腻碍痰。故用苇茎汤合雪羹加清化痰热、降火止血之品，大剂投之而痊。", ["弦", "滑"]], "14512": ["病机", "脉弦滑，弦主痰饮气结，滑主痰湿内盛。疟久不痊，形消不食，医误补而自汗增，孟英诊得脘下聚气，脉弦滑，知为痰结中焦，气机不畅，故投小陷胸加竹茹、旋覆、枳实以开痰结，渐能纳谷。此脉证实为痰热互结之病机，非虚证也。", ["弦", "滑"]], "14513": ["病机", "患者昏厥，一息奄奄，面色灰黯，戴眼口开，似属危候，然按其脉尚不绝，知正气未绝，痰热蒙蔽清窍，气机暂闭。故用菖蒲、胆星、竹茹、旋覆等豁痰开窍，和入童溺、牛黄至宝丹清心透邪，复杯而起。脉尚不绝为辨证关键，说明非真元败绝，乃痰热内闭之病机。", []], "14514": ["病机", "脉弦细，左寸与右尺甚数，右寸关急搏不调。弦细为阴伤气郁，数急为内热炽盛。患者平昔善饮，积热内伏，温补杂投，煽动风阳，致痰多气逆、肌肉消瘦、耳鸣腰痛、火升梦戈、凛寒善怒。颈垂气促、舌黯无苔、面黛不渴，皆热灼津伤、痰瘀阻络之象，病机为内伏积热、风阳上扰、痰瘀互结。", ["弦", "细", "数", "急"]], "14515": ["病机", "本案据来信述病状立案，未直接诊脉，故脉象要素缺如。证延二十余年，始因生冷伤胃阳，肝木乘虚，胁疼挛掣，湿盛为痰，温药积热，反助风阳，消烁胃津，渐形瘦削。痰饮据为窠囊，气阻血瘀，病机为肝升太过、胃降无权、痰瘀互结、本虚标实。", []], "14516": ["病机", "脉左缓滑，右软迟。缓滑主痰湿内蕴，软迟主阳气不足、痰饮阻滞。证逾二十年，右胁聚气，有升无降，饮阻不宣，呕逆减餐，二便非攻不畅，吐苦吞酸，苔黄舌绛，渴喜冷饮。脉证合参，显属痰饮内伏、气机升降失常、标实本虚之病机，故曰流善幻显属于痰。", ["缓", "滑", "软", "迟"]], "14517": ["病机", "再诊左脉如昨兼弦，右寸亦转缓滑。弦为风阳内动，缓滑为痰湿渐化。中脘气渐下降，二便欲解不行，乃升降愆常、枢机窒涩，由风阳浮动、治节横斜、肺失肃清，一身之气皆滞。脉象示痰湿稍减而风阳未靖，气机未畅，故以轻可去实，先廓上游为治。", ["弦", "缓", "滑"]], "14518": ["病机", "三诊脉来较静，小溲渐行，虽未更衣，已能安谷。脉静为邪退正安之象，小溲行则浊得下降，纳谷则胃气渐复。前诊痰湿壅阻、气机窒涩，今脉静溲行，知清通导浊之法已效，病机向愈，故仍导以清通，因势利导。", []], "14519": ["病机", "四诊脉稍和缓，叠授清宣后更衣色黑，噫气渐罢，酸水不呕，纳谷颇增，皆邪退之征。然腿凉便滞，气少下趋，颧面时红，火炎上僭，两胁较热，络聚痰瘀，是上焦风阳未靖，下焦气机未畅，痰瘀留络。脉稍和缓示胃气渐和，病机向安，法仍缓导以刈根株。", ["缓", "和"]], "14520": ["预后", "原文述“各恙皆减，眠食渐安”，而“脉渐柔和”，是邪退正复、胃气渐和之象。脉由病时之弦急转为柔和，说明肝火渐平，痰热渐化，故虽“火犹易升，头疼面赤，颊酸结核，胁热未蠲”，然脉已不劲，预后向安，故“且参清养”以善后。", ["柔", "和"]], "14521": ["病机", "春温初犯，邪尚在肺，右寸脉洪大，为温邪壅肺、气分热盛之征。洪大者，热势鸱张，肺失清肃，故发热面赤、渴而微汗。孟英谓“宜令其下行，由腑而出”，以知母、花粉、黄芩等清降肺热，使热从大便而解，果泻热水而脉静身凉。", ["洪", "大"]], "14522": ["病机", "脉弦软微滑，弦主厥阴，软为阴虚不敛，滑属痰气。患者素体阴虚，环跳穴痛、转筋上冲、痛自乳起下注于髀，皆厥阴经脉为痰气所滞。脉不任按之弦硬而见软滑，正合“阴虚而痰气滞于厥阴”之病机，故以养阴化痰、柔肝通络为治。", ["弦", "软", "滑"]], "14523": ["病机", "春温初起即神气躁乱、惊惧不眠，两脉甚数，数主热盛，且脉至急迫，是温邪不从气分透解，直入营分，内扰心神。孟英断为“温邪直入营分”，故用神犀丹佐紫雪清营凉血、开窍安神，两剂而瘥，非汗解所宜。", ["数"]], "14524": ["病机", "脉沉弦而软滑带数，沉主里，弦主饮癖，软滑为痰湿内蕴，数则郁而化热。患者素患痰饮，误服温补，致痰伏愈多，壅塞清阳升降之路，故发冷喘汗欲厥。脉沉弦软滑，正合“痰饮内伏、肺气不展”之机，与少阴水泛之脉沉微迥别。", ["沉", "弦", "软", "滑"]], "14525": ["病机", "春温谵语发狂，连服清解大剂反昏沉肢冷，脉弦大而缓滑，苔黄腻秽气喷人，是凉药冰伏其邪，热与秽浊互结阳明，脉道虽大而缓滑，非虚寒之比。弦大主热壅，缓滑主痰湿秽浊，故投承气汤加清化，下胶黑矢而愈，此“凉药无涤秽之功”之明证。", ["弦", "大", "缓", "滑"]], "14526": ["病机", "间疟数发后热炽昏沉，脉来洪滑且数，苔黄腻垢浊，洪数为阳明热盛，滑主痰湿，妊身八月而腰疼欲堕，是温疟热邪内炽、痰热壅遏，有动胎之势。孟英以黄芩、知母、石膏等清热涤痰，热退则胎安，一剂而痊。", ["洪", "滑", "数"]], "14527": ["病机", "年逾七旬患间疟，脉弦滑，脘闷苔黄，弦主少阳疟邪，滑主痰热内蕴，脉不虚而实，故孟英曰“无恐也”。投清热涤痰药数剂霍然，可见高年未必皆虚，凭脉辨证，邪去则正安，不可拘于年迈而妄补。", ["弦", "滑"]], "14528": ["病机", "脉滑数，滑主痰，数主热，乃痰火内伏，温热外侵之象。患者年逾花甲，素患痰嗽，痰火内蕴，复感温热，故见晡热不饥、头疼不食。脉滑数正合痰火内伏之机，投石膏药清解后热退知饥，宿恙亦愈，说明脉象与病机相应。", ["滑", "数"]], "14529": ["病机", "脉软数，软主湿，数主热，乃湿温重证。湿温初起即见身黄发热，湿热郁蒸所致。脉软数提示湿热内蕴，故亟与清解。后因辍药，湿热之邪扰营，出现谵语昏聋、抽痉遗溺，脉象当有变化，但初诊脉软数已定湿温之基。", ["软", "数"]], "14530": ["病机", "脉洪数无伦，右尺更甚，洪数为热盛之象，右尺候肾，热邪深入下焦，气逆神昏、汗多舌缩，皆热盛阴伤之危候。前医误用燥补，致热势鸱张。脉洪数无伦反映热邪充斥，故用大剂清热救阴，后脉证渐和，示邪退正复。", ["洪", "数"]], "14531": ["病机", "脉缓滑而上溢，缓主湿，滑主痰，上溢示痰湿阻痹，气机升逆。患者形瘦阴亏，患间日疟，寒少热多，脘膈闷极，苔腻不渴，皆痰湿内阻之征。脉缓滑上溢说明痰湿壅盛，枢机不利，故治以运枢机、化痰湿，忌提表凉润。", ["缓", "滑"]], "14532": ["病机", "脉虚弦软数，虚软为阴亏，弦数为阳升无液，冲气上逆。患者胎前患嗽，娩后不痊，头疼口燥，舌光赤无苔，乃阴液亏虚，阳无所附，冲气上逆之嗽，非外感也。脉虚弦软数正合阴亏阳升之机，故用滋填潜降而愈。", ["虚", "弦", "软", "数"]], "14533": ["病机", "原文未识脉名，仅言“按其脉肤甚热”，肤热为湿热时邪外蒸之象。患者陡患偏坠，医误作疝治，用温散，遂痛不可忍。孟英断为湿热时邪，睾丸肿痛偏右，脉肤热正是湿热蕴结之征，故以清解取效，忌温燥。", []], "14534": ["预后", "脉左寸数疾，余皆软大，左寸候心，数疾为离火内亢，软大为湿温之象。患者年逾花甲，患湿温，苔腻黄，舌尖独黑，脉象舌色示平昔曲运心机，坎水不制，势必自焚，兼湿温之感，预后不良，果数日而殒。", ["数", "疾", "软", "大"]], "14535": ["预后", "脉形歇代，但脉虽歇而弦搏有根，歇代为脉气不续，然弦搏有根示胃气尚存，得乎天者厚，虽高年犹为实象。患者湿温旬余，呃忒连朝，二便窒涩，苔腻而灰，府气未宣，痰湿热阻，清宣展布尚可图，后渐露下虚之象，转予培补而安。", ["歇", "代", "弦"]], "14536": ["病机", "脉弦细而软，为阴虚劳倦、湿温毒重之象。弦主肝郁，细软示阴液亏虚，湿温毒邪内蕴。后脉更细弱，乃阴液愈耗、正气渐衰，故神昏惫、溲涩疼。此脉主阴虚湿温，与肤赤苔黄、便溏溲痛相应，治当清解存阴。", ["弦", "细", "软", "弱"]], "14537": ["病机", "脉弦细而涩，舌光紫白糜，乃热入营阴、津液枯涸之候。弦为肝郁，细涩示阴血亏耗、脉络瘀滞。骨瘦如豺、少腹拒按、势将喘逆，皆阴伤热结、正虚邪实之象，故虽当下而法难直授。", ["弦", "细", "涩"]], "14538": ["病机", "脉弦滑且数，苔滑腻微黄，乃伏痰内盛、肝逆上升，兼吸受暑热。弦主肝逆，滑数为痰热内蕴。气冲欲厥、脘痛呕吐、便秘溲热，皆痰热肝逆之症，故以黄连、竹茹、旋覆等清化痰热、降逆平肝。", ["弦", "滑", "数"]], "14539": ["病机", "脉弦细虚数，乃营阴素亏、酷热外烁、风阳浮动，痉厥之萌。弦为风阳，细虚为营阴亏，数主热。发热汗多、苔黄眩悸，皆阴虚阳浮之候，故治以滋潜镇摄，防其痉厥。", ["弦", "细", "虚", "数"]], "14540": ["病机", "脉滑数，面赤龈胀，便秘不通，乃毒热内蕴、腑气壅实。滑主痰湿，数主热，滑数并见为毒热炽盛。服外洋丸药后毒热未解，反致便秘龈胀，故以犀角、石膏、硝黄等清解攻下。", ["滑", "数"]], "14541": ["病机", "脉浮弦而数，舌尖赤无苔，乃阴虚阳越、煎厥根萌。浮为阳浮于外，弦为肝风内动，数主热。心悸肢冷如冰，是阳越于上、阴竭于下之危候，故以元参、二至、三甲等滋阴潜阳。", ["浮", "弦", "数"]], "14542": ["病机", "脉左弦急，右洪滑数，苔黄大渴，谵语嗽痰，乃阴虚血去过多、木火上浮、酷暑外烁、津液大耗兼伏痰。弦急为肝火，洪滑数为痰热。恶露仍行、唇齿干燥，皆阴伤热炽之候，故营卫两清。", ["弦", "急", "洪", "滑"]], "14543": ["妇人", "脉虽虚微软数，而断为娠象，乃因气逆不能眠，医皆畏却。虚微软数为气血不足之脉，然妊娠初期脉亦可现滑疾，此案以脉滑疾为娠象，用药顾及胎元，后竟产孙，说明脉诊辨妊之重要。", ["虚", "微", "软", "数"]], "14544": ["病机", "脉弦数，弦主肝郁，数主热，结合舌苔黄、溺短赤，说明肝经湿热下注，灼伤血络，故便血。前医误作虚寒温补，反助湿热。本案实为痔血，非虚寒便血，故用肃肺祛痰、清肝凉血之剂而愈。", ["弦", "数"]], "14545": ["病机", "脉虚弦豁大，虚为营液大脱，弦为风阳上冒，豁大乃阴虚阳浮之象。产后晕汗、目不能开、心若悬旌，正是阴血骤亏、风阳上扰之候。虽无恶露，胸腹舒，非瘀血为患，故不可破血，治当滋阴镇逆。", ["虚", "弦", "豁", "大"]], "14546": ["病机", "脉弦滑而洪，弦主肝，滑主痰，洪主热盛。体丰多汗、苔黄便血、呕渴妄言、彻夜不瞑，乃伏痰内盛，暑扰阳明，痰热蒙蔽心神。故用大剂清暑化痰、凉血解毒之品，三帖证平。", ["弦", "滑", "洪"]], "14547": ["病机", "脉弦数而促，弦主热郁，数主热盛，促为热盛气急。苔黑口干，寒战壮热妄言，是素有热痰，暑邪内伏，热痰交阻。后感冒风邪，脉兼浮，证属风温，温散反炽，故宜清化。", ["弦", "数", "促"]], "14548": ["病机", "脉弦滑左甚，弦主肝郁，滑主痰湿，左甚属肝经。平昔阴虚肝滞，痛胀少餐，暮热形消，咽疼喉癣，九年不孕，今经闭而脉弦滑左甚，乃肝郁痰凝，气血尚充，故断其有孕，果得一子。", ["弦", "滑"]], "14549": ["病机", "脉滑数，滑主痰湿，数主热，舌绛便艰、口臭溲少，蕴隆虫虫，乃湿热痰火内蕴。疡医温托温补，致湿热痰火一齐关住，病势愈剧，咽糜龈腐、睛赤音嘶，皆热毒上攻之候。", ["滑", "数"]], "14550": ["病机", "脉来沉实而数，沉主里，实主邪实，数主热。舌色紫黯，堕胎后恶露虽行，寒热头疼自汗，冷自心中出，乃瘀血内阻，郁而化热，非类疟虚寒。故用活血化瘀之剂，瘀去则热自退。", ["沉", "实", "数"]], "14551": ["病机", "脉弦缓，弦主气郁，缓主湿，苔黄腻，乃胎之初孕，阻气凝痰，窒碍枢机。气逆肢寒、神疲欲寐、耳聋舌蹇，皆痰湿蒙蔽清阳所致，非元气虚脱。故治当宣豁痰湿，投匕即效。", ["弦", "缓"]], "14552": ["病机", "原文述“脉无常候”“虚促虽形，未必即为虚谛”，强调脉象模糊无定，非真虚。病机为痰壅肺气，气不流行，有升无降，故见气喘、苔腻痰浓、足冷面红、自汗等。痰阻枢机，脉道不畅，故脉无定候；虚促之象由痰壅气逆所致，非虚证。", []], "14553": ["病机", "脉两上溢，左兼弦细。真阴久虚，风阳上僭，冲嗽不已，厥脱堪虞。弦细为阴亏阳亢之象，上溢示风阳升腾无制。阴不潜阳，肝风上逆，故干嗽无停、目不交睫；脉弦细主真阴亏虚，风阳上僭，有厥脱之危。", ["弦", "细"]], "14554": ["病机", "脉左弦疾而促，右滑数而溢。冬温挟痰阻肺，治节不伸，肝阳鼓舞直升。弦疾促为肝阳亢盛、痰火内扰之象；右滑数而溢主痰热壅肺。痰热阻肺，肝阳上逆，故痰嗽气逆、额汗颧红、神情躁扰。", ["弦", "疾", "促", "滑"]], "14555": ["病机", "脉软滑而数，苔色腻滞。平昔善饮，湿热内蕴，奔走过劳，邪乃下注，膀胱气阻，溲涩不通。软滑主湿，数主热，湿热内蕴下注，非真火无权，亦非清阳下陷。脉软滑数说明湿热壅阻下焦，气化不利，故肛翻患痔、小溲不行。", ["软", "滑", "数"]], "14556": ["病机", "脉左弦劲而数，右滑大不调。胃肺之痰热有余，肝胆之风阳上僭。弦劲数主肝阳亢盛化风，滑大主痰热壅盛。痰热蕴肺，肝风上逆，故疟复间作、面浮跗肿、喘嗽易嗔。脉象示痰热风阳交炽，非大虚之候。", ["弦", "劲", "数", "滑"]], "14557": ["病机", "脉左弦而微数，右软滑兼弦。水常泛滥，土失堤防，肝木过升，肺金少降。左弦微数主肝阳偏亢，右软滑兼弦主脾虚湿蕴。久投滋腻，湿浊内蟠，中运受阻，升降不调，故痰嗽气逆、纳减呕腐。", ["弦", "数", "软", "滑"]], "14558": ["病机", "脉细数而弦，左脉弦细而数。冬温伏热，阴伤火旺。细数主阴虚内热，弦主肝阳偏亢。热灼营阴，故舌缩底绛、苔黑如；阴亏火旺，故脉细数而弦。此非中虚寒湿，乃温邪深入营血之候。", ["细", "数", "弦"]], "14559": ["病机", "脉甚弦软，苔腻舌红。中虚而健运失职，误投滋腻，更滞枢机，附、桂之刚，徒增肝横。弦软主土虚木乘，肝脾不调。中虚湿阻，肝木偏横，故呕恶便溏、不饥无溺。脉弦软说明中虚湿滞，肝木乘脾，非肾气不纳。", ["弦", "软"]], "14560": ["病机", "脉弦而数，弦主肝郁气滞、瘀血内阻，数主热。患者病起汛后、继多白带，瘀血留滞血室，郁而化热，故脉弦数；昼明了夜妄言，酷似热入血室。能食便行说明病不在肠胃，气上冲、腹时痛胀为瘀阻气逆之征，故径从瘀血论治而效。", ["弦", "数"]], "14561": ["病机", "脉形虚大，虚为气阴不足，大为热恋未净、阴亏不敛；舌紫无苔、呃忒自汗，为上焦热恋、下部阴亏。其室脉至虚弦、按之涩弱，虚弦为营血亏虚、肝失柔养，涩弱为气滞血少，故见苔腻口酸、耳鸣不寐、脘痛头摇，治以养营调气、和胃柔肝。", ["虚", "大", "弦", "滑"]], "14562": ["病机", "左关弦、寸滑如珠、尺细而干，弦为风阳内炽、木失水涵，滑为搏液成痰，细而干为真阴素亏。体丰色白、平昔多痰，舌绛苔干、睛赤，皆阴亏火旺、痰热内扰之象，故忌温燥而宜轻清。误服党参、枸杞、当归等温补，遂致火升气逆、言语支离。", ["弦", "滑", "细"]], "14563": ["其他", "此段论临证医案之源流与价值，非辨脉之文，故无脉象可录。原文谓医案\"犹名法家之有例案\"，对病书方、因题立义，性命得失系焉；强调溯其脉证，方能见病者情形与医者学识心思，属医案体例之论，不涉具体病机。", []], "14564": ["病机", "脉象滑数，滑主痰湿，数主热，合为痰热内蕴之征。风温袭肺，肺失宣降，故咳嗽气急、头痛发热；舌苔干白、额上汗出、面色暗晦，为正虚邪实、热蒸津伤之象。滑数之脉示痰热壅肺，正虚不能胜邪，故虑其喘脱。", ["滑", "数"]], "14565": ["预后", "脉数稍减，是热势略退之兆，然身热未退、咳嗽气升复作，苔仍干白、面色晦滞不开，说明邪不外达而正气先虚。证届七日为一候关节之机，脉数虽减而未静，故只能望其安稳无变，再图转机，属预后判断之文。", ["数"]], "14566": ["病机", "脉形弦数，弦主少阳枢机不利、邪郁不达，数主热。舌白尖红、胸中烦闷，邪留少阳阳明，外症如疟、里则协热便泄，正是少阳阳明合病、热邪不肯宣达之象，故拟大柴胡法和解兼通下，脉弦数即其凭据。", ["弦", "数"]], "14567": ["预后", "左脉空大，空为脉道失充、阴血亏竭，大为虚阳外浮不敛；右脉模糊，为正气溃散、脉道不清。年逾古稀染温邪而内陷，便泄气粗、神蒙如寐、舌焦干短，皆正虚邪陷、阴液将涸之危候，故势防痉厥，属预后不良之判。", ["空", "大"]], "14568": ["病机", "左脉大右脉小，非邪盛之象，乃元气虚弱之征。温邪十二日斑疹遍透而神识仍糊，大便屡行齿垢未脱，舌尖红中心焦，阴津灼伤。脉神委顿，说明正气已衰，无力托邪。故从元气推求，虑液涸动风致痉厥、胃虚气逆致呃忒，当务存津液、济甘凉。", ["大", "小"]], "14569": ["病机", "原文未出具体脉名，仅言「脉神委顿」。脾肾阳气素虚，阳邪一化阴湿即来，脉神委顿正是阳气不振、正不胜邪之象。故当早防波变，古方大豆卷、麻黄汤类发汗之品与此虚证总不相宜，恐更伤阳气。", []], "14570": ["病机", "脉沉小，舌白腻，身无热口不渴，少腹硬满如盘按之不痛，此非热结乃寒凝。温邪甫退而中寒复起，肾阳不足，膀胱气化无权，水气凝而为瘕。脉沉主里、小主阳虚，正合肾阳不振、水寒内结之机，须防犯胃冲心呃厥。", ["沉", "小"]], "14571": ["病机", "脉形糊数，糊为阴液枯涸、脉道不充，数为邪火内炽。温邪十一日神昏齿燥舌焦干，斑疹透而未足色不鲜泽，乃阳明邪火炽盛、少阴阴液消亡。数而模糊说明正虚邪实、津液将竭，势有痉厥之险，故拟生津救液佐芳香宣窍。", ["数"]], "14572": ["病机", "脉伏如无，肤冷汗出，而斑色红紫、脘腹拒按、舌红干燥目赤唇焦，此非阳虚之伏，乃邪热内闭、阳气不达于外。热结旁流、阴津外泄，故脉伏与肤冷并见，颇有内闭外脱之虑，勉进黄龙汤法以攻下存阴。", ["伏"]], "14573": ["病机", "肤冷汗出脉伏，渊按明言非虚象乃闭象，从斑色红紫上看出。热邪深闭于里，阳气不能外达，故脉伏而肤冷；斑色红紫为热毒内蕴之征。此脉伏属热闭而非阳脱，故参须温补可斟酌，不可误作虚脱论治。", ["伏"]], "14574": ["病机", "脉洪大而汗出，目赤耳聋舌白烦渴，乃气分热邪炽盛之象。洪大为阳明热盛、正气尚能抗邪，热迫津泄故汗出。当辛凉彻气分之热邪，甘凉救肺胃之津液，使热清而津复，防其入营耗阴。", ["洪", "大"]], "14575": ["病机", "脉形洪滑，舌苔灰白，目张不语而神慧，与汤则咽身能转侧，说明非邪闭心包。洪为阳盛，滑主痰，乃肝阳夹痰火阻塞清明之府。神慧能咽可转侧，正见邪未内陷心包，故勿再芳香开达，开则引邪内陷。", ["洪", "滑"]], "14576": ["病机", "三诊目张不语、多汗而脉大，是阳热亢盛、阴液耗伤之象。脉大为阳盛之征，汗多则阴津外泄，阳无所附，故断为阳盛阴虚。目张不语属神昏之渐，脉大而兼多汗，正虚邪实，最防阳气暴脱而成厥脱，故急急救阴以图万一。", ["大"]], "14577": ["预后", "四诊目能合、口能言，汗多稍收，脉大稍敛，较前之脉大无敛为缓，故云似有一线生机。然舌蹇言涩、两臂动强，是阴亏风动之兆，脉大虽敛而风阳未息，恐其发痉。存阴熄风法正针对阴虚风动，脉象由大渐敛示邪热稍退而正未复。", ["大"]], "14578": ["病机", "寸关脉细滑数，细为阴亏，滑数为湿蕴生痰、热蒸灼液。因畏虚多进谷食，邪留恋不化，郁于心胃，湿蕴生痰化热，故烦躁、恶心、错语，舌边乾红、心苔黄腻。脉细滑数正是将燥未燥、将陷未陷之象，阴亏之体虑其内陷，故拟导赤泻心、生津化浊。", ["细", "滑", "数"]], "14579": ["主病", "脉洪口渴，口臭喷人，目赤神糊，斑疹透而未足，显系阳明胃火极盛、热毒外发之候。洪脉为阳明热盛之征，热灼营血则斑疹虽见而透未足，胃火冲逆故口臭口渴。急急化斑，以白虎清阳明、犀地清营解毒，再复存阴，正合脉洪胃火之治。", ["洪"]], "14580": ["病机", "左脉细小、右脉洪大，左候少阴、右候阳明，细小为阴津大伤，洪大为燥火未退，故断为少阴不足、阳明有余。黑苔剥落、舌质深红，皆阴伤火旺之征。际此阴伤火旺，治当一面存阴、一面泻火，玉女煎最合，守过三候冀其阴复。", ["细", "洪", "大"]], "14581": ["病机", "渊按单举右脉洪大，右主阳明，洪大为热盛之象，故断为阳明热结夹滞显然。洪大之脉见于右部，说明热邪结于阳明胃肠，兼有积滞内停，与前述阴伤火旺之右脉洪大相呼应，示燥火未退而热结已成。", ["洪", "大"]], "14582": ["病机", "此段未识脉名，然耳聋无闻、舌干难掉，显系阴津大伤、不能上承清窍濡润舌本所致。阴津耗竭则耳失所养而聋，舌失所润而难掉，故用复脉法以复其阴液。脉象虽未明载，从症可推阴亏之机，与前后诸诊阴伤火旺一脉相承。", []], "14583": ["病机", "脉象软而小数，软为湿邪偏盛、正气不足，小为阴分受耗，数为热邪内蒸。证逾旬日，温邪挟湿，病在气营之交，苔白腻边红、疹透不爽、寐则谵语，皆湿遏热伏、营卫同病之象。脉软小数为湿蕴热蒸、气营两伤之征，故清营泄卫、理气化浊恰如其分。", ["软", "小", "数"]], "14584": ["病机", "脉软数而舌白腻，神蒙嗜卧却呼之清、语言了了，说明非邪陷心包，乃湿热弥漫上焦、肺气失宣。软为湿象，数为热象，湿热相合则脉软数；肺气不布则神蒙嗜卧，胃浊未化则呃逆未除，故从肺胃立法。", ["软", "数"]], "14585": ["预后", "前诊脉弦硬，今转小而涩数，是温邪袭肺、痰火逆上之际，阴津暗伤、元气渐馁之象。弦硬为邪正相搏，小涩数为津亏气弱，故原文虑其喘汗厥脱。脉由实转虚而病未退，正不胜邪，预后堪忧。", ["弦", "硬", "小", "涩"]], "14586": ["死脉", "原文未识脉名，然述时证脉先大后小、先强后弱，热不退而病反增者必死。大强为邪正相争，小弱为正气衰馁，正衰而邪不退，病日进而正日亏，故断为死证，立方用药无甚深意，属死脉范畴。", []], "14587": ["病机", "诒按阐发前条：初病脉硬大，是邪正相搏、正气尚能敌邪；转为弱小，则正气馁矣。病象不退反增，乃正气不能敌邪，病日进而正日亏。此以脉之硬大转弱小辨邪正消长，说明脉变反映正气盛衰，故主死候。", ["硬", "大", "弱", "小"]], "14588": ["病机", "舌干绛、齿燥唇焦、痰气喘粗而脉细数，细为阴津亏耗，数为邪热内蒸。无形邪热熏膻中，有形痰浊阻肺胃，津枯液燥、正气内亏，故脉细数。正虚邪实，恐有厥脱之变，治当化痰涤热治标、扶正生津救本。", ["细", "数"]], "14589": ["病机", "头汗淋沥、痰喘不止、面青晦、舌红干涸、齿板唇焦，脉形洪大。洪大为阳明邪火有余，火载气上逆、肺失肃降而为喘；面青、津涸则少阴阴津不足。上实下虚，证势危险，深虑厥脱，故救少阴之津、清阳明之火。", ["洪", "大"]], "14590": ["治法", "原注仅言此玉女煎合生脉散，盖温病以救阴为急。脉散为气阴耗散、津液不敛之象，故用生脉散敛气生津，玉女煎清胃救阴。脉散提示阴伤气耗，治当急救阴液，属治法范畴，非单纯主病。", ["散"]], "14591": ["病机", "渊按脉形洪大，合头汗、面青，上实下虚大著。洪大为阳明邪火有余、气火上逆，面青头汗为下虚不纳。故于补下纳气中清热救津，人参、石膏、粳米救肺清热亦所以救肾，说明洪大脉主上实下虚之病机。", ["洪", "大"]], "14592": ["病机", "脉大稍软，较前略缓，然气促烦躁、舌红干涸、齿垢唇焦，显系津液未回、虚阳未息、上逆之气未降。脉大主虚阳浮越，软为正气渐馁，故虽逾险岭而未涉坦途。心腹透㾦为邪欲外达之象，仍当救少阴、清阳明，以冀津回阳潜。", ["大", "软"]], "14593": ["病机", "脉形洪大中空，乃津枯液燥、气化不行之候。洪大为热盛，中空为津亏不敛，故神昏如醉、舌淡红无苔、呓语呢喃。芳开虽暂快，终非根本，必甘寒润燥生津，俾气化津回，方保吉兆。", ["洪", "大", "空"]], "14594": ["误治", "葶苈治痰喘属实者，若身不热而脉微者忌之。脉微为阳气衰微，非实喘可比，误用苦寒峻泻，必更伤正气。此条明辨虚实，示人痰喘脉微者不可妄投葶苈，属误治之戒。", ["微"]], "14595": ["预后", "战而得汗，脉静身凉，邪已解矣，此战汗后佳兆。然舌黄未去，胃中余浊未清，尚宜和化。脉静为邪退正安之象，身凉为表里通达，惟余浊未净，故不可骤补，当以和胃化浊收功。", []], "14596": ["治法", "原注凡战汗后脉静身凉，用方大法不外乎此，总以和胃气、化湿热为主。脉静身凉示邪已外解，然湿热余浊易滞中焦，故治法重在和胃化湿，不可过用寒凉或温补，以平为期。", []], "14597": ["病机", "脉数而洪，舌燥齿干，心荡气促，阳明之火方炽，少阴之阴已涸。数主热，洪主火盛，腹硬痛、便三日不通，气火尽浮于上。阴津大涸，虽似宜通降，然不得不先养其津，姑拟一方备商。", ["数", "洪"]], "14598": ["妇人", "温邪上受，化火上炎，喉痛色赤，全由邪火炽张。斑痧之后，犀角地黄甘寒清解。今观脉色，神情爽朗，立夏病减即退，胎不动即安，大便才通为转机。此妇人妊娠温病，治当清解安胎并重。", []], "14599": ["妇人", "温邪燔亢之余，余热未净，肺胃阴津受戕。胎当七八月，肺与大肠司养，肺受火淫，燥热移于大肠，遂移热胞络。胞脉系肾而络胞胎，热上迫肺，故音哑、咳嗽而喉复痛。此胎中阴火，当养阴顺气，忌阴火上冲。", []], "14600": ["病机", "原文未出脉名，专论伏温传变与音哑之由。谓伏温由少阴出太阴，故退而复来、轻而再重；疹属肺、斑属胃，温邪从两经外达。又辨胞络为胞门子户，系肾，少阴脉贯肾上入喉，热邪上干喉中故音哑、甚则喉痛，明其病机在少阴热邪上攻，非胎热所致。", []], "14601": ["预后", "阴虚之体感温邪反复，交九日神识时迷、满舌碎腐，而脉象渐沉。沉为邪陷于里、正气不能外达之象，温病见沉脉多示邪深正馁，故防其昏厥。原文以“脉象渐沉”与神迷、舌腐并见，提示病势内陷，预后当慎，非寻常里实之沉。", ["沉"]], "14602": ["预后", "发汗太过、津液内夺之后，生津达邪，疹点已化，热未退而脉象稍和。脉和示胃气渐复、邪有外达之机，故原文许为“佳兆”。虽苔煤、神糊有时清，大势无变，仍守前方加味。此以脉象转和判断津回邪透、病情向安，属预后之论。", ["和"]], "14603": ["主病", "久患便血，阴气先伤于下，复感温邪挟积，肺胃气阻，上喘下泄、发热口渴、舌绛如朱、额汗不止、遍体无汗，而脉小数疾。小数疾为阴血虚而邪火内伏，阴不守则额汗，液虚则身无汗，脾陷肾逆则喘泄并作，故断为厥脱险象环生。", ["小", "数", "疾"]], "14604": ["病机", "此释上证脉理：阴血耗于下、脾气伤于中，感温邪而喘泄并见，泄为脾陷、喘为肾逆，两藏不守则厥脱易易。头汗为阴不守而阳越，身无汗为阴液虚而气不能化；舌绛如朱为胃阴亏、心火炽；脉小数疾正是阴血虚而邪火伏。故戒升发、禁发汗，急顾中气阴液。", ["小", "数", "疾"]], "14605": ["病机", "此案辨阴阳虚实疑似：音低神倦似虚，而便泄臭水、中脘按痛为实；肢冷脉细似阴，而小便热痛为阳。脉细虽似阴寒，合小便热痛则知非纯虚寒。舌白谵语为痰蒙火郁，日暮烦躁为阴虚阳盛。原文主张怪证多属痰，虚中夹实当先治实，脉细须与症合参。", ["细"]], "14606": ["主病", "二诊头胀身疼、热炽脉数，舌苔浊厚灰黄。数脉主热，热炽于里则脉数；头胀身疼为邪郁肌表，苔浊厚灰黄为邪积交蕴、浊滞不化。脉数与热炽、浊苔相应，说明邪积交阻而未能透达，故原文断“有日重之势”，示病进。", ["数"]], "14607": ["主病", "温邪吸自口鼻，阻于膜原，蒸痰聚浊，弥漫三焦，热势早轻、过午则甚，舌灰黄、渴不多饮、心胸烦躁，脉濡而数。濡主湿、数主热，濡数并见正合湿温之湿遏热伏；邪蕴膜原不达，故方四日而势防生变，仍以前方加减。", ["濡", "数"]], "14608": ["病机", "左脉小数急，数急为邪热内郁，小为正气不足；右脉模糊，右主气分，模糊乃正气不能鼓动邪气外达。原文谓“正虚不能敌邪，邪不宣达”，虽有胸中烦躁痞痛、频转屎气似可下，然脉象示正虚邪陷，故恐内陷生变，不可径下。", ["小", "数", "急"]], "14609": ["预后", "下后燥屎浊秽已去，胸腹痞痛解，而舌反焦黑、脉反数疾，数疾为邪热炽盛、劫烁津液之象。证交七日一候之期，正邪交争关节，脉数疾不退示邪热未衰，虑其“过卫入营，内陷神昏”，故当甘寒养津兼开泄三焦以透邪。", ["数", "疾"]], "14610": ["病机", "左脉促数，促为阳盛热结、数主热炽，左脉候营，营中热盛鼓动血脉故促数；右脉模糊，肺胃气分不宣。原文“营中之热炽盛，斑疹似透不透”，热郁营分不能外达，故深虑内闭神昏，急与清营透卫以开达。", ["促", "数"]], "14611": ["病机", "斑疹稠密不疏，烦躁气粗，右脉涩滞。涩滞为气机郁阻、热邪壅遏营血，气营之热交炽，血行不畅故脉涩。原文谓“气营之热交炽，深有昏呃之虑”，斑疹虽为邪之出路，然稠密而脉涩，示热毒壅盛难透，故虑昏呃。", ["涩", "滞"]], "14612": ["其他", "原文仅言“右脉稍起，当脐动气略宁”，未载具体脉名，属诊后记录。右脉稍起示气分渐复，当脐动气略宁为下焦冲逆稍平，仍遵昨法续治，属病情向愈之观察，故列其他。", []], "14613": ["病机", "脉象虚实并见，虚为阴亏正弱，实为痰浊内蒙。原文“阴亏火旺，语言错乱，痰浊内蒙，汗不解，舌苔霉黑”，正虚与邪实夹杂，故脉虚实互见。阴亏火旺、痰浊蒙蔽心包，深虑发痉呃厥，治当存阴清热化痰泄浊。", ["虚", "实"]], "14614": ["病机", "脉数无力，数为热邪未退，无力为正气已虚。原文“神识虽清，热势不退，齿垢未脱，动气又作”，正虚邪恋，气不敛冲故动气复作。数而无力示邪热留恋而正不胜邪，尚虑变端，故以扶正达邪为要。", ["数", "无", "力"]], "14615": ["病机", "脉数混混而不清，数为热，混混不清为湿浊蕴蒸、热渐化燥，气机不畅。原文“湿蕴化热，热渐化燥”，斑疹并见、神识模糊、气粗短促、目赤耳聋，阴精下亏风阳上亢，虑内陷昏痉，故拟生津达邪兼芳香逐秽。", ["数"]], "14616": ["病机", "脉沉小而数疾，沉主邪郁于里，小为湿阻气机，数疾因热郁不达。原文谓“湿蕴化热，余湿犹滞，气火熏蒸，蒙蔽清窍”，故脉见沉小，非虚而属邪郁不达；数疾为热郁欲透之象。此脉主湿温邪在太阴阳明，湿胜于热，热为湿遏，故斑疹虽透而神识时糊，日晡烦躁。", ["沉", "小", "数", "疾"]], "14617": ["病机", "脉数较大于昨，数为热盛烦心，大为病进之征。原文引“数则烦心，大为病进”，谓非阴转为阳，乃湿热郁蒸，热势转盛。舌苔白厚罩灰、面红目赤为阳盛，头昏耳聋为阴虚，小溲窒塞为气化不及。脉数大示邪热内迫，正虚不能托邪，故当生津彻热、利窍化湿。", ["数", "大"]], "14618": ["病机", "原文未识脉名，仅言“脉时躁时静”，躁则邪热内陷扰神，静则神倦若寐，为湿热郁蒸、蒙蔽心包之象。虽便不通而腹鸣不满，肠胃不实，粪必溏，未可骤攻。尖苔白罩微霉，邪在营气之交，故神识沉迷、起坐如狂。此脉象示邪内陷，当透热转气、芳香宣窍。", []], "14619": ["病机", "下后舌黑稍退而脉反洪大，洪大为阳明火旺之象。下后阴伤，邪热未净，反入阳明，燔灼之火盛，故脉洪大、神识仍昏。原文谓“阳明火旺也”，治当清阳明燔灼之火、救少阴涸竭之阴。此脉主热盛于内，正伤邪炽，与舌黑、神昏相应。", ["洪", "大"]], "14620": ["病机", "右脉洪大数疾，左亦弦数。洪大数疾为阳明实热内盛，燥屎内结，故便坚黑；左弦数为肝木乘土，脘痛经来。渴喜热饮乃湿与热合，热处湿中，饮热汤则湿开。脉与唇焦齿板合观，主湿温挟食、肝胃同病，非蓄血，亦非真寒。", ["洪", "大", "数", "疾"]], "14621": ["预后", "战汗后少顷复热，汗出而脉躁疾，原文列为“一忌”。躁疾者，邪热不退而正气已伤，脉不静反躁，示正不胜邪，热邪内陷。适值经来，恐热入血室，故用豆豉、黑栀宣泄表里，延胡、郁金、香附通血中气滞，防其滋变。此脉主预后不良，当急治。", ["躁", "疾"]], "14622": ["预后", "便下黑栗，脘痛大减，舌霉唇焦退，邪减之征。然脉由数大变为虚小无力，心中觉空，是邪减正虚之象。数大本为邪热盛，今转虚小，示正气耗伤，无力抗邪，防神糊痉厥等变。原文谓“延过两候乃吉”，脉虚小为转危之兆，当扶正为要。", ["数", "大", "虚", "小"]], "14623": ["预后", "大解后热平，脉转弱小，若伏邪已净，则脉静身凉，各候俱平，祗须清养。若伏邪再炽，脉随病变，或仍数大。若热盛而脉虚小，是邪盛正虚之重候，不得以九日两候为凭。脉弱小为邪退正复之象，虚小为邪盛正虚之危，当随证治之。", ["弱", "小", "虚", "数"]], "14624": ["病机", "脉仍数，示湿温旬日，邪热未清，郁于气分。舌白腻、头汗多、身热不解、咳嗽不扬、小溲不爽，皆湿温蕴蒸三焦、气机不宣之象。数脉主热，湿遏热伏，故热势缠绵；湿阻上焦则咳，阻下焦则溲涩。治当分泄三焦，使湿去热孤。", ["数"]], "14625": ["预后", "脉形不显，乃温邪挟积化燥，战汗不透，正气无力鼓邪外出，脉道不充之故。大热虽减而里热仍炽，舌霉边白，高年阴液已亏，正虚邪陷，恐内陷心包。脉不应证，为预后险恶之兆，故曰「恐其内陷」。", []], "14626": ["病机", "脉形软数，软主湿盛，数主热蒸，湿温交蒸之象。舌灰白腻、渴不多饮、咳逆痰稠、便溏神糊，皆邪居手足太阴、气机不达、三焦窍络皆阻之征。肺主一身之气，气机不达则喘，喘甚不休则有厥脱之危，故所虑在气急。", ["软", "数"]], "14627": ["病机", "脉象不达，乃暑邪内闭，肺气闭塞，气机不能外达于脉道。恶寒发热、口不能言、先有咳嗽，皆肺气壅闭、暑热内郁之象。肺主气，气闭则脉道不利，故脉不显。治拟开而达之，宣通肺气，使暑邪外透。", []], "14628": ["病机", "脉数细而沉，数主热，细主阴伤，沉主邪闭于里。暑邪归心，闭阻心包，故神昏；舌干黄、唇齿燥、耳聋便泄，皆津枯热炽、三焦皆病之征。邪闭心胞如火如焚，脉沉细则正虚邪陷，病危甚，故曰险候。", ["数", "细", "沉"]], "14629": ["预后", "脉细如丝，乃伏暑挟积伤脾，中气不运，水饮留伏，气血生化乏源，脉道不充。身热腹满便泄、手足搐搦、眼吊口噤、角弓反张，皆脾伤木横、热胜风动之痉。乱进丹丸汤水，中气愈困，脉细如丝，正气衰微，终为险候。", ["细"]], "14630": ["病机", "脉弦带数，弦主疟邪郁于少阳，数主热盛。暑湿内伏，凉风外袭，湿遏热伏，化火为疟，先寒后热，日轻夜重。心胸烦躁、中脘痞塞、呕吐泄泻，皆热甚于中、蒸熏水谷之湿。今疟退而脉仍弦数，舌白腻、溲不爽，病机偏重于里，法从里治。", ["弦", "数"]], "14631": ["预后", "脉沉糊，沉主邪陷于里，糊为正气溃散、脉道不清之象。年过花甲，病中劳顿，伏邪挟积，正虚邪陷，故神昧、舌强、身热不扬、手足寒冷、气短作呃、便泄溏臭。脉沉糊而症见厥脱之兆，深虑正气不支，厥脱立至。", ["沉"]], "14632": ["预后", "伏暑化燥劫津动风，舌黑唇焦、鼻煤齿燥、神昏指牵引，皆阴津消涸、邪火燎原之象。两脉促疾，促为阳盛热迫，疾主火炽阴伤，脉与症合，示邪火未衰而津液难复。虽便通病减，然脉仍促疾，说明险象未除，故断恐其复剧，属预后不良之判。", ["促", "疾"]], "14633": ["病机", "伏暑两解后得汗便安，复热神糊目上视几厥脱，热时舌乾红、退则黄腻，是湿遏热炽、将燥未燥、将陷未陷。脉沉不起，阳证而见阴脉，热邪内郁不能外达，正气有陷伏之势，故曰相反可虞。治借桂通阳、苓通阴、草果祛太阴寒、知母清阳明燥热，正针对湿遏阳郁之机。", ["沉"]], "14634": ["病机", "阴虚之体伏暑湿热，邪不易达。耳鸣眩悸、苔浊胸痞、微寒微热，脉形弦数，弦主肝胆气郁、湿阻络脉，数主热郁于内。虚不甚、邪不多，故不可大补亦不可重剂攻邪，但求脉情无变则可保无虞，说明此脉反映邪正相持、湿热郁蒸之病机。", ["弦", "数"]], "14635": ["病机", "伏暑三候神糊呃逆、肢痉痰多、音低，脉大而虚。大为邪气壅盛、虚为正气不足，脉症合观，明是中虚浊恋、液涸痰蒙。身痒烦躁因从未得汗，汗出不彻久虚所致，夺气音低更证中气之败。故治法惟有和中宣化，听胃气自布，示正虚邪恋、攻补两难之病机。", ["大", "虚"]], "14636": ["病机", "暑湿伏于太阴，中焦阳气不化，故神蒙若寐、身热不扬、肢冷脉濡。濡主湿盛阳微，湿浊困阻则阳气不舒，手指牵引、舌根牵强为风痰阻络。舌苔灰白厚掯、口泛甜味极甚，皆中宫浊湿之征。脉濡正合湿浊内蕴、阳不舒化之机，故仿缩脾饮醒中化湿浊。", ["濡"]], "14637": ["病机", "高年元气素亏，新邪乘虚引动伏邪晚发。脉小数而虚，小为阴津不足，数为邪热内扰，虚则元气已亏。干咳欲呕、舌边光红、根苔白掯、热甚无汗，皆津枯邪恋之象。脉虚数示正虚邪留，故虑其化燥神昏，属津枯邪恋、正不胜邪之病机。", ["小", "数", "虚"]], "14638": ["病机", "伏邪湿热内蕴，三焦气机不达，故午后发热、胸闷头胀、尿少无汗、舌苔白腻。脉象软细，软主湿困、细主气机郁滞血行不畅，说明湿热阻遏、气化不利而非大实大热。故拟开上、疏中、渗下，仿河间分消三焦法，正合此湿郁气滞之病机。", ["软", "细"]], "14639": ["病机", "伏邪挟积阻塞中宫，疟发日轻日重，重则神蒙烦躁、起卧如狂，是食积蒸痰、邪热化火、痰火上蒙胞络。脉沉实而舌苔黄，沉主病在里，实主邪积内结，说明邪积聚于阳明腑实。故法当通下，仿大柴胡例，脉症相合，示里实可下之病机。", ["沉", "实"]], "14640": ["治法", "原文仅言“脉舌与证合参”，未出具体脉象，故脉象要素为空。其主旨在于强调脉诊须与舌象、症状互参，方能准确辨证。此处据脉舌证合参，断为大柴胡汤证，故以和解少阳、通下里实为治法，体现脉证合参以定治则的临床思路。", []], "14641": ["病机", "脉细主虚，结合腹胀、舌白，说明病机由阳明转属太阴。少阴疟邪挟痰浊上走心胞则昏狂，下乘脾土则腹撑；今脉细、腹胀、舌白，为脾阳不振、寒湿内阻之象，故法当辛温通阳、转运中气，随机应变以急者为先。", ["细"]], "14642": ["病机", "脉缓大主脾阳渐通而邪未尽。前投姜附、达原等辛温通阳，喉中痰声平、腹胀松，今脉缓大、神气安和，示脾脏阳气虽通，但寒热痰涎未化，腹中微胀、痰多黏腻，故仍宗前法轻减其制，以化余邪。", ["缓", "大"]], "14643": ["病机", "脉数急主温热时邪，燥火湿热郁于肺胃。原文论烂喉丹痧由地气郁发、燥金司令、热胜金燥所致，邪干肺胃则咽喉痛肿腐，脉数急正是热邪亢盛、燥火内迫之象，故治以辛凉散邪、甘寒化毒。", ["数", "急"]], "14644": ["病机", "脉数大无力、右脉涩滞不调，主正虚邪恋、复夹食滞。痧邪留恋，早食温粥致食复，热邪未净而胃气未清，故身热口干、咽腐肤肿、颐毒脓稀；数大无力为气阴两伤，右涩滞为食滞壅阻，攻补两难。", ["数", "大", "涩"]], "14645": ["病机", "脉不见浮弦洪数，反软数模糊，主邪郁不达。烂喉丹痧误作喉蛾，清泻太过，邪不外达而内郁，故右腭肿痛、恶寒；软数模糊为正气受遏、邪热内陷之征，深防内陷，急宜解肌透达兼清化。", ["软", "数"]], "14646": ["病机", "左脉较昨稍大，右脉仍然不利，主肺胃邪热欲达不达。早进寒凉致倒行逆施，丹痧欲透不透，喉肿益甚，痰火上盛；左脉稍大为邪有外达之势，右脉不利为肺胃气机壅滞，故仍拟透解兼清化。", ["大"]], "14647": ["病机", "脉缓滑不数，主热退而痰湿内盛。体肥多湿，湿得热蒸痰，痰阻肺胃，胃气失降，故痰多干呕、咽喉仍痛；缓滑为痰湿之象，不数示邪热已退，故治以降气化痰为主，清解次之。", ["缓", "滑", "数"]], "14648": ["病机", "原文引《脉经》寸左右弹主阳跷为病、《内经》阳跷脉满令人不寐，推为阳盛阴亏、卫气不交于阴，故寒热止而复来属营卫不和。阳跷行卫分、阴跷行营分，肺主卫、心主营，脾胃为营卫之源，故以半夏秫米汤和脾胃调营卫交通阴阳，非专治奇经；又嫌其燥，因舌边碎痛阴伤。", []], "14649": ["病机", "脉弦而肝胃尤甚，是木胜克土之象。高年元气素弱，伏暑后三疟，胃气一虚则恶谷厌纳、痰多呕恶、心跳少寐、便闭溺赤丛生。虽便两旬不通，脉弦属肝旺胃虚，未可通腑，故以培养中气、启胃化痰为扼要，调和营卫退寒热佐之。", ["弦"]], "14650": ["治法", "本条为按语，总结前数方皆治虚疟、久疟之法，重在运脾气、补脾阴、和营卫、温督脉。虽未出脉象，其病机为久疟正虚、脾营不足、督脉失温，故治法从脾胃营卫与奇经督脉并调，属虚疟久疟的治法归纳。", []], "14651": ["预后", "脉濡小，濡主湿恋、小主元气渐伤。营久患疮疥湿热浸淫，复感暑湿为疟缠绵成三疟，湿邪仍恋而正气已损，故虑其加腹满，宜早图之，并须安逸忌口。脉症合参示湿未化而元渐虚，预后须防腹满之变。", ["濡", "小"]], "14652": ["病机", "左脉细弦为肝肾亏，右脉软弱为脾胃虚，三疟后气血两亏。细弦属阴血不足而肝失柔养，软弱属中气虚弱，左右分候肝肾脾胃，故治法补肝肾、调脾胃、养气血，并须安逸少劳，脉象直接指示虚损所在。", ["细", "弦", "软", "弱"]], "14653": ["预后", "疟脉自弦，弦大者为阳，邪有外达之势。今疟来热势稍轻而短，是邪有退机，仍从前法施治。脉弦为疟邪踞少阳之常象，弦大示阳分邪盛而易达，热轻热短与脉相应，故判断病势向退，属预后转佳之候。", ["弦"]], "14654": ["病机", "三疟久延营卫两伤，复因产后下焦八脉空虚，疟邪阻于血络聚于肝募而成疟母，腹中结块偏左。脉空虚正合营卫气血俱损、奇经不足之机，久病瘦人夏至阴阳剥复之际最怕阴伤，故和阳生阴、从产后立法，佐搜络以杜疟邪之根。", ["空虚"]], "14655": ["病机", "脉弦数为痰饮内蕴、食积化热之象。素有痰饮咳嗽，复感凉风外薄、食积内停，寒热似疟、额角痛、胸脘痞胀、大便不通，是有表复有里。弦主饮主痛，数主热主积，故拟疏里解表，表里双解以除痰食外邪。", ["弦", "数"]], "14656": ["病机", "脉弦数，弦主肝旺气滞，数主热，示阳明腑有积热而燥屎未全结；两手掌心独热为热郁于里，大便五日不通为腑气壅滞，舌苔薄白不黄则燥结未深，故曰燥屎尚未全结，治宜缓通其腑，不可峻下。", ["弦", "数"]], "14657": ["预后", "高年下痢日夜百余次，脉细为正气已衰，加之舌苔白掯、身热恶心、饮食不纳、痢下五色，皆痢疾忌款；脉细与噤口五色并见，示脾胃败而正不胜邪，故初起虽可用败毒散，仍须人参扶正和胃，预后堪虑。", ["细"]], "14658": ["病机", "左脉沉小为邪陷厥阴、阴分受困，右脉弦大为阳明积热内恋而木来乘土；下痢色紫后重、舌黄晡热皆积热之征，木乘土则下痢后重，高年体虚神怯，脉沉小示正虚，故防其厥脱。", ["沉", "小", "弦", "大"]], "14659": ["病机", "红痢日久，脾气虚、营气耗，脉迟缓而涩，迟缓主脾阳失运，涩主营血耗伤；舌薄白底绛、渴不贪饮、口恶甜味，皆脾阳失运而湿动于中之象，误服红曲、滑石致痢复剧，故主湿伤脾阳之病机。", ["迟", "缓", "涩"]], "14660": ["病机", "从脉象迟涩看出中阳不足而营血滞涩，故理中汤温运中阳、驻车丸分导湿热为合；红曲、滑石性偏渗利寒凉，与迟涩所主之虚寒湿滞适与相反，故用之痢复剧，此段以脉证逆治明病机。", ["迟", "涩"]], "14661": ["病机", "久吸洋烟，脉沉而细，沉主里、细主虚，示阳气不足而寒邪内侵；微寒微热、头略胀痛为寒邪在表，昼不痢而痢在夜、色赤者，乃寒伤营分，非湿热下痢，故当和营散寒、温通阳气，勿与常痢同治。", ["沉", "细"]], "14662": ["病机", "脉细肢寒，细为阳虚血少，肢寒为阳气不达四末；昼不痢而痢在夜，夜属阴，脾阳不能统摄营阴，故营阴下泄而为痢，此段以脉细肢寒与痢在夜互证，明脾阳失统之病机。", ["细"]], "14663": ["病机", "右脉细弦为木侮土，左脉细弱为肾水亏，水不涵木则肝气横逆；下痢赤白由木胜土衰、湿热不化，病本在肝气而及脾肾，故华先生补中升阳参育阴从本求治，再参温化以顾脾肾阳气。", ["细", "弦", "弱"]], "14664": ["病机", "两脉虚濡，为脾胃元气大弱之象，濡主湿、虚主不足，故元气虚而湿滞。然原文强调下痢古称滞下，起于湿热居乡，早补早敛往往受累，故虽见虚濡，此时仍以苦辛宣通腑滞为法，扶正之剂留待久痢。脉虚濡在此示元气弱而湿热未清，不可骤补。", ["虚", "濡"]], "14665": ["病机", "陆氏《脉经》云代则气衰、细则气少，多指阳气为言。今下痢而得代细之脉，脾胃之阳微特著；更兼形衰畏冷、小便清长，皆阳虚之征。下痢赤者属血分，腹中痛者为有积，故立方从通补兼施设想，寻其罅而通之补之。", ["代", "细"]], "14666": ["病机", "脉弦硬，为伏暑湿热蕴于肠胃及厥阴之象。厥阴之表便是少阳，故先热痢后兼疟，乃厥阴少阳表里同病；疟后便溏为少阳木邪侮土，泻止疟痢仍作则胃气强旺、土不受邪，病还厥少两经。小便少因阴气亏而渗愈少，当滋化源，清厥阴之热兼益肾阴、运脾之湿。", ["弦", "硬"]], "14667": ["病机", "复诊痢减而腹仍痛，脉弦兼寒热，值经来之时，为血虚木郁、肝胃未和之候。弦主肝木，木郁则疏泄失职，血虚则肝失所养，故寒热并见。治拟养血疏肝，使肝胃调和，则腹痛寒热可解。", ["弦"]], "14668": ["病机", "脉细肢寒，为太阴阳气已弱之征；小便艰难，则膀胱气化又钝。红痢匝月、腹痛后重，先曾发疟三次，属中虚表邪传里。细脉主阳气不足，肢寒为阳虚外候，故拟开其中焦、化其湿热，兼升阳解表，表里双解。", ["细"]], "14669": ["病机", "脉弦紧而不数，面色青而不渴，为寒积之征。弦紧主寒主痛，不数则非热；便痢白腻如水晶鱼脑色、小便不利、少腹偏右板窒，诸医疑肠痈，然肠痈有寒有热，此证属寒积，故宜温通，与《金匮》薏苡附子败酱散寒者之意相合。", ["弦", "紧"]], "14670": ["病机", "脉沉细，沉主里、细主虚，为里寒之象。泄痢白腻而腹不痛，白腻属寒湿，腹不痛则非实积，故断为寒也，宜温之。沉细在此示阳气不足、寒湿内盛，温法所以散寒化湿。", ["沉", "细"]], "14671": ["病机", "脉紧肢寒，并不发热，兼素有寒疝、苔白不渴，皆寒象为多。紧主寒主痛，肢寒为阳虚，不发热则非热痢。河间论痢属热者多，景岳论痢属寒者不少，此证腹不甚痛但肛酸且胀，寒象偏著，故宗景岳温治之法。", ["紧"]], "14672": ["病机", "脉弦主痛、主积，迟则为寒。休息痢近五年，腹中块垒时痛，痢下兼干粪，苔灰白，皆寒积痼冷在肠胃之征。弦为积块内结、气机不畅，迟为阳虚寒凝，故断为虚而有寒积，非纯虚可补，当先取去积冷再调，与《本事方》痼冷在肠胃之说相合。", ["弦", "迟"]], "14673": ["病机", "休息下痢半载，色红而黏，脉弦。弦为风木之象，久羁肠脏营分，风邪郁而化热伤血，故下黏红；近日畏风身热，是外感新风引动伏邪。脉弦既示风邪未出，又示营分郁滞，故法取补中升阳兼凉血，使内伏之风与外感之邪并解。", ["弦"]], "14674": ["病机", "脉沉细涩，沉属里、细属阴亏、涩属精血不充，合为阴阳并弱。便泄半载脾肾两亏，阳痿精伤、面白无华、足跗浮肿、纳食暖气，皆脾肾虚而湿注气逆之候。刚热劫阴、滋腻妨胃，故宜双补阴阳，于补土中兼顾肾藏，紧扣沉细涩所主之虚损病机。", ["沉", "细", "涩"]], "14675": ["病机", "脉沉细数，沉细为虚，数为阴分有热。复诊后腹鸣气坠属脾虚气陷，舌心光红、脉沉细数则为肾藏阴伤、虚热内生。前之双补略效而阴伤未复，故仍用补中升阳，升举脾陷兼顾肾阴，脉数非实热，乃阴虚之征，不可苦寒直折。", ["沉", "细", "数"]], "14676": ["病机", "两脉弦硬不柔，即胃之牢脉，弦硬为胃气不柔、阴血亏而气失和降。肛门外疡溃后大便作泻月余，下部畏冷似寒，然脉不沉迟而弦硬，知非真寒，证属阴虚而气陷。故温中扶土、升阳化湿，以柔养胃气，不可因畏冷纯投刚热。", ["弦", "硬", "牢"]], "14677": ["预后", "吐泻转筋，肢冷脉伏，汗出音低，目陷鼻冷，口不渴身不热，一派阳亡欲脱之象。脉伏为阳气不能鼓动血脉，非邪闭，乃正气溃败、阴阳离决之危候，故断为险重，属霍乱亡阳之预后不良，急宜回阳固脱。", ["伏"]], "14678": ["病机", "霍乱虽平而汤水呛吐、小便不利、四肢仍冷、冷汗仍出，两手脉微细。微为阳衰，细为阴弱，脉微细示吐利之后阴阳两伤、阳气未复，故肢冷汗出；呛吐为清浊升降未和。拟五苓通利阴阳佐清上，正对脉微细所主之阴阳俱虚、气化不利。", ["微", "细"]], "14679": ["预后", "脉形乍大乍小，为阴阳乖乱、正气无主之象；面暗不泽、苔黄而湿、腹满足肿、小便黄赤，色证合参，是湿遏热伏、阴气阻遏于中，属女劳黑疸。疸而变腹满，脾肾已败，脉之乍大乍小正示胃气将绝，故云在法难医，预后不良。", ["大", "小"]], "14680": ["预后", "疟止复作、腹满平而又发，示病根未除；目黄溺少面黑，脉细为湿郁血分、脾虚不运之征。细脉主正虚湿滞，疸而腹满者脾土已困，故难治，防延黑疸，姑与分消以缓其势。", ["细"]], "14681": ["病机", "面黧黑、腹满足肿，脉沉而细，沉为病在里，细为阳气衰少。脾肾之阳不化，水湿阻滞于中，故见肿满；阳不化气则水停，证势甚重，治以通阳燥湿，使阳复则湿化。", ["沉", "细"]], "14682": ["病机", "脉象洪大，右肢偏废，便闭后小便不利、少腹胀满，洪大为阳气亢盛、气血壅实之象。虽望八之年而脉不衰，故病类中，非纯虚，乃气火内郁、升降失司，与河间主火、丹溪主痰之说相参。", ["洪", "大"]], "14683": ["预后", "脉大稍敛，一息四至，不失和缓之形，是有胃气。类中内风掀动，脉大为风阳亢盛，稍敛且缓则胃气尚存，风阳有渐平之机，故预后较佳，与纯弦劲无胃气者不同。", ["大", "缓"]], "14684": ["病机", "左脉稍平，知肝心之火渐退；右尺尚旺，乃肾膀之火未清。初因中气不足、膀胱失化，今心火妄动、相火随炽，脉象左右差异反映火邪偏盛部位，故仍以清心导赤泻肝立法。", ["平"]], "14685": ["预后", "脉稍柔，风阳有渐熄之机；语言稍贯，机窍有渐灵之意。心血衰少故心跳，操劳起病，当静养使水升火降、心肾相交。脉柔为风阳渐平之兆，佐化痰和胃以和其中，则诸恙可霍然。", []], "14686": ["病机", "两手关脉皆见一粒厥厥动摇之象，动脉主惊、主痛、主气乱。关候脾胃，脾虚木胜，内风动跃，故左半肢体麻木不仁、头眩面麻，属偏枯之候，虑延仆中，当早图之。", ["动"]], "14687": ["预后", "两关脉厥厥动摇之象大减，内风有暗熄之机；左手屈伸稍安，左足麻木未愈。动脉减则风阳渐平，然未全愈，故拟补肾生肝以治本，使水涵木而风自熄。", ["动"]], "14688": ["病机", "原文谓年老精血枯而络脉空，肝气乘虚入络，湿热又从而为患。脉空即络脉空虚之象，精血亏耗不能充盈脉道，故按之空豁。肝之部在少腹胁肋，肾之府在腰，精血既枯则肝木失养，乘虚窜络而痛，湿热乘隙蕴结，故以补养精血、疏肝通络、兼化湿热为治，脉空正示本虚标实之机。", ["空"]], "14689": ["兼症", "此段为复诊，未载脉象。原文述胁肋之痛稍减，惟小溲短少，夜半以后脘腹觉胀，断为浊气不化。前法补养精血、疏通脉络已见小效，而新添溺少夜胀，乃阳气不运、浊阴凝滞之兼症，故前方加通阳泄浊之品。所重在症候转归与方药调整，非以脉断病，故脉象要素从缺。", []], "14690": ["病机", "脉双弦者，两手皆弦，弦为饮为痛，寒饮内踞胃中，木气失和而克土，故脘痛吐酸。得食则痛缓，知其中气本虚，非实邪壅塞。原文以双弦定寒饮在胃，以木克土释吐酸，以食缓辨中虚，三者合参，病机为虚寒夹饮、肝木犯胃，故主小建中汤加味和中泄木祛寒。", ["弦"]], "14691": ["预后", "脘痛而肢冷脉伏，头汗淋漓，原文断曰防厥。脉伏者阳气内闭不能外达，肢冷为阳不布于四末，头汗淋漓则虚阳有上越之势，阴阳不相顺接，厥脱之变迫在眉睫。此段重在警示危候，脉伏与肢冷头汗并见，示阳气欲脱而非寻常寒凝，故列于预后以戒医者早图。", ["伏"]], "14692": ["病机", "脉细而弦，细为虚为寒，弦为肝为痛。原文谓肝木挟下焦水寒之气乘于脾胃，脘痛攻肋、呕吐酸水，正是木挟寒水侮土之象。细示中气不足，弦示肝气横逆，寒水在下焦，肝木挟之上犯，故拟温中御寒、扶土抑木，脉细弦合参，虚寒与肝逆并见。", ["细", "弦"]], "14693": ["病机", "右脉细，左脉弦，原文以为肝气横逆、中气久虚之证。左弦应肝逆，故胸脘阻塞攻冲；右细应中虚，故营卫不和而寒热，大便溏、饮食少亦中虚之征。病将一载，虚实夹杂，以四君子合逍遥加左金，扶土抑木并行。左右分诊，细弦对举，正示肝强脾弱之病机。", ["细", "弦"]], "14694": ["病机", "此段未载脉象。原文述久患肝风眩晕，疟后周身筋脉跳跃，甚则发厥，断为血虚不能涵木、筋脉失养、虚风走络、痰涎凝聚。疟久伤阴耗血，木失水涵则风动，筋脉失濡则跳跃，风痰蒙扰则发厥，故拟养血熄风、化痰通络。全凭症候推求病机，脉象要素从缺。", []], "14695": ["病机", "左手脉沉弦而涩数不调，原文断为血虚而肝风暗动：沉弦属肝，涩为血少，数而不调则风动之征。右关独缓滑，缓滑主胃有湿痰。尺寸俱弱，金水两虚。合耳聋、肩膊酸难举、痰多、口干腻诸症，乃血虚风动、痰湿中阻、肺肾两亏之错综病机，脉象分部各有所主。", ["沉", "弦", "涩", "数"]], "14696": ["病机", "原文以“脉左弱为血虚，右弱为气虚”分候气血，左弱则血不荣，右弱则气不充，气血两虚则上不养头目而眩，下不濡筋脉而麻木，甚则心乱神昏。此肝风挟痰所致，本虚标实，故法当清上补下。", ["弱"]], "14697": ["病机", "原文未出脉名，以“血不养筋，筋脉牵掣”为辨，昼安暮发、不能安卧，明言病在阴经。血虚不能濡养筋脉，入夜阴气用事而血更不充，故筋急牵掣，治宜养血以和经脉。", []], "14698": ["治法", "原文未及脉象，诒按称“此养阴柔肝之正法”，与复脉、定风、阿胶鸡黄等法用意相合。所论重在治法，以养阴柔肝为要，使阴血得充则肝风自息，非以脉断病。", []], "14699": ["病机", "脉象弦大而滑，弦为肝风，大为中气已虚，滑主痰湿。少腹块平、小便反不禁，是精血不足；右手麻木、痰多气升，乃内风走络、脾湿生痰。故脉弦大滑相应于风、虚、痰交杂之机。", ["弦", "大", "滑"]], "14700": ["病机", "左关独弦滑，左关候肝，弦为风阳，滑为痰火。风阳挟痰上扰阳明，故头额偏左连及腮齿皆痛。脉象与症相符，主肝风痰火为患，治拟熄风阳、清痰火。", ["弦", "滑"]], "14701": ["预后", "病久正虚，阴阳两弱，坎离不交，复因舟行跋涉，热闷鼓动风阳，扰乱神明，卒然神糊不语、烦躁不安。诊脉促乱，促为阳盛而乱为气机乖戾，饮食不进，正虚邪扰，预后堪忧，故姑拟熄风和阳、安神定志以冀转机。", ["促", "乱"]], "14702": ["病机", "病后络脉空虚，相火内风走窜入络，故心中嘈热、胸前跳跃、背脊灼热，症在经络脊脉之中。脉空虚正合络虚，非清不足以熄火，非镇不足以定风，然络虚不填则风火复入，故清火、熄风、填窍三法相须为用。", ["空", "虚"]], "14703": ["病机", "右脉弦滑搏结，左但弦小。弦为肝火，滑为痰壅，搏结主痰火交争；左弦小乃肾水不足，不能涵木。肝火冲肺则吐血，乘脾胃为痰遏则痫厥，故右脉弦滑。法当壮水涵木，佐化痰镇逆。", ["弦", "滑", "小"]], "14704": ["病机", "脉浮弦而大，按少力，为肝肾阴亏于下，风阳上升，兼挟痰浊。浮弦大主风阳上扰，按少力示下虚，故曰升多降少，上盛下虚。症见呕、头眩心嘈，久延虑仆中，法当养阴潜阳化痰。", ["浮", "弦", "大"]], "14705": ["病机", "原文未识脉名，然述病原风阳走络，攻注疼痛，由肝郁得之；口中甜腻，胃有湿浊。病机为肝郁化风，风阳窜络，兼胃湿浊。络病不能速愈，须耐心安守。", []], "14706": ["病机", "两脉模糊，难以捉摸，乃惊动肝阳，神魂扰乱，血随气逆，属薄厥。脉模糊因气逆血乱，神失主宰。两足常冷，阳升于上，急以介类潜阳，重镇怯。", []], "14707": ["病机", "春脉当弦而反微，是肝虚也。弦为肝脉，微为虚象，肝虚魂不藏，夜不得寐；昼日当寤反寐，胃虚也。胃虚阳气失明，故昼寐。治补肝藏魂，益胃补气。", ["弦", "微"]], "14708": ["预后", "两脉弦搏不柔，两目正圆直视，舌光红如柿皮，舌边碎缺如虫蚀，时躁时狂时清时静，皆病之忌。弦搏不柔为心肝郁火变幻，木火升则神不守舍，所见绿衣红裤二童子乃神魂出舍，预后险恶。", ["弦", "搏"]], "14709": ["病机", "脉浮小弱，舌心红苔白，语言错乱，哭笑不常，似属心风。浮小弱为风入心经，蕴热蒸痰所致。风邪入心，热蒸痰蒙，故神乱。用《本事方》独活汤。", ["浮", "小", "弱"]], "14710": ["病机", "脉细数，懒言倦卧，精气神三者皆虚。舌苔白腻，有痰有饮。静则气怠若虚，动则气上自乱，是虚而有痰兼火。火伏痰不升则静，火动痰升则躁，痰火起伏。治以十味温胆加减。", ["细", "数"]], "14711": ["病机", "脉不显，因阴遏于外，阳伏于内，阴如迷雾，阳若日光，阳为阴遏故沉沉默默而蒙昧。有时阳光见𬀪则脉稍起，阴霾四合则昏昏如寐。病源头眩心悸，苔白多痰，痰饮郁中，法必通阳，进苓桂术甘汤加味。", []], "14712": ["病机", "右关候脾胃，脉独滑动如豆，是痰浊聚于中焦之象。滑主痰湿，动主搏击不定，痰浊内阻则中脘皮肉觉厚；痰走经络，则手足筋脉时或动惕。原文以“痰浊在中焦”“痰走经络”点明病机，故治法攻补兼施，既化其痰，又顾其虚。", ["滑", "动"]], "14713": ["病机", "脉虚弦滑，虚为土弱金虚，弦为木旺风动，滑为痰饮内停。原文谓“金土水不足而风痰有余”，金虚不能制木生水，土弱不能御木侮、生金化痰，故见足软难行、口流涎沫、舌左无苔等风痰瘫痪之象。脉虚弦滑正合虚中夹实、本虚标实之机。", ["虚", "弦", "滑"]], "14714": ["病机", "脉小弦滑沉，弦主少阳，滑主痰，沉主里，小为邪郁。因疟多饮烧酒，酒助火生痰，痰火内扰神明，故如醉如狂、语言妄乱。原文断为“少阳、阳明同病，而连及厥阴”，邪并阳明弥漫心包，故发狂又昏昏默默。脉象正示痰火郁于里而枢机不利。", ["小", "弦", "滑", "沉"]], "14715": ["预后", "二诊内热稍和，脉数亦减，是邪热渐退之兆。然腹中偏左作痛，年已二九经事未通，原文断为“血虚肝郁显然”，虑延干血劳损。脉数虽减而未静，示阴血未复、郁热尚存，故预后须防劳损之变，非单纯热退即安。", ["数"]], "14716": ["病机", "外皮不热而脉微数急，原文断为“里有热也”，且属阴虚里热，非关表邪。微为虚，数急为热，阴虚内热故脉数急而微。无头痛恶寒，故愈散其邪愈虚其表而增咳嗽；无胸痞恶心，故非湿热。脉象紧扣阴虚里热之机，治当和中兼理脾肺。", ["微", "数", "急"]], "14717": ["病机", "复诊诸恙俱减而脉数未静，原文谓“究属元气真阴亏损”。数脉本主热，此热由虚生，故补肺脾后仍数，示亏损未复。前补在肺脾，今参肾药兼养其阴，以观动静。脉数未静正是真阴未充、虚热未敛之征，不可徒作实热论。", ["数"]], "14718": ["病机", "脉沉搏数，沉主里，搏为邪正相争有力，数主热。原文谓“营阴大亏，虚火内亢”，故骨热不已、鼻血时流、周身骨痛、口燥渴饮。虚火内亢而脉沉搏数，是阴亏于内、火搏于里之象。劳损根深，入夏防剧，拟滋少阴、清阳明，正对阴虚火亢之机。", ["沉", "搏", "数"]], "14719": ["病机", "脉虚形弱，虚为营阴内亏，弱为气血不足。原文谓“心脾营阴内亏，肝胆风火上逆”，故内热头眩、项间结核。脉虚形弱示正虚为本，风火上逆为标。病由内生，治以养营，然不易速效。脉象紧扣营阴亏虚、形气不足之病机。", ["虚"]], "14720": ["病机", "脉弦数者，肝胆郁热之候也。弦为肝脉，数主热，肝胆相表里，郁热内炽，戕伐生生之气，肺金失清肃，脾胃失转输，故咳嗽发热，热势交寅卯而盛，相火日炽，阴津日涸，燎原之势不至涸竭不止。", ["弦", "数"]], "14721": ["预后", "脉形软数，软为气虚，数为阴虚内热。肺脾两虚则咳嗽气塞，心营亏损则骨蒸夜热，面白无华。劳损根深，脉象软数示气阴两亏，虚热内扰，至夏至阳盛之时，虚火易动，故防剧。", ["软", "数"]], "14722": ["病机", "脉软数为气虚，骨蒸心跳为血虚。软脉主气弱，数脉主虚热，气弱则脾肺两虚，血虚则心营亏损，故咳嗽头眩、面色痿黄，皆脾肺两虚、气血不足之候。", ["软", "数"]], "14723": ["病机", "左脉数疾，为心肝阳亢之象。数疾主热盛，左脉候心肝，肝火戕胃则食减，心火烁金则热增，胃阴失降，虚阳外浮，故谷食反减、夜热增重，夏令阳盛，防其剧变。", ["数", "疾"]], "14724": ["预后", "咳嗽内热俱减，惟脉之细数不退，仍为可虑。细为阴亏，数为虚热，症减而脉未和，示阴亏虚火内伏未清，根蒂未固，故虽症缓，仍当虑其反复。", ["细", "数"]], "14725": ["病机", "此阴亏而虚火上炎之证。方以理中合生脉法，温中清上，土厚则火敛，金旺则水生，使中焦得温，上焦虚火自敛，肺金得润，肾水自生，阴阳调和，虚火归元。", []], "14726": ["病机", "脉数内热，乃虚火内炽之象。脾胃不足，肝木亢逆，清浊升降失司，攻消克伐更伤元气，纳减津枯，虚火戕及肺胃，故火升颧赤、脉数内热，渐成劳损，当扶土升清降浊，佐泻火清金。", ["数"]], "14727": ["病机", "脉数内热，咳嗽脘胁仍痛，乃阴虚肝郁成热，肺失清肃。数脉主热，阴虚则内热生，肝郁化火刑金，故咳嗽胁痛，热灼肺络，仍防吐血。", ["数"]], "14728": ["病机", "疟后盗汗，阴津大伤，久咳痰血，行动气喘，食少无力，脉虚细数。虚为气阴不足，细为阴血亏耗，数为虚热内扰。阴伤于下，气浮于上，故咳喘内热多汗并见，劳损根深，正合虚劳之候。", ["虚", "细", "数"]], "14729": ["病机", "盗汗气喘咳嗽，脉细。细为精气两虚，肺肾俱损，气不归元则喘，卫外不固则汗，肺失濡养则咳。景岳谓大虚之证微补尚难见效，故舍补摄肺肾别无他法，脉细正示虚损之本质。", ["细"]], "14730": ["病机", "吐痰带血后干咳，渐至发热消瘦，行动气升，脉细数。细为肾气亏于下，数为阴亏生内热。劳碌感邪延绵，下亏上损，虑成劳损。形容消瘦、气升，皆阴不敛阳、虚火上浮之象。", ["细", "数"]], "14731": ["预后", "久咳血痰，复肛门结疡，肺遗热于大肠。脉数音哑，数为热盛，音哑为金破不鸣，劳损之根已深。时当夏令火旺金衰，故虑气逆血沸。脉数与音哑并见，示肺热阴伤，预后堪忧。", ["数"]], "14732": ["病机", "脉沉取数，沉为病在里，数为热，故阴内亏而热在里，劳损之候。咳吐白痰、心腹时痛、得矢气则宽，病兼肝郁。咳已三年初无身热，病从痰饮始，故宜从痰饮气郁例治，脉沉数正合里虚夹郁之机。", ["沉", "数"]], "14733": ["病机", "久咳痰稠，上午发热，面青黄。左脉细数，右脉软弱。细数为阴亏虚热，软弱为气分不足。病属上损，幸大便不溏，未过中及下。脉见两象，示气阴两伤而病位尚浅，故加谨调养以待夏至。", ["细", "数", "软", "弱"]], "14734": ["病机", "复诊咳嗽脉细数，热由上午延及下午，阴气渐伤。细为阴亏，数为虚热。大便间或带血，脾气虚也。阴伤及气，虚热日深，故从景岳理阴煎例，扶过夏至一阴来复，冀无增变。", ["细", "数"]], "14735": ["治法", "脉散为气阴耗散、肺肾不摄之象。用四君子汤合生脉散益气敛阴，加生地、山药、白芍、扁豆、川贝、阿胶、红枣，培土生金、滋阴养血。脉散示正气涣散，故以补摄为治，非单主一病，乃据脉施治之法。", ["散"]], "14736": ["病机", "脉细为阴津亏耗、脉道不充，数为虚热内扰。原文述漏疡日久阴津暗渗，又加咳嗽气耗、劳神，致咳甚气升、便溏内热、音哑喉痛，皆阴亏火动、精气神三伤之象。细数并见，正合劳损虚热之机，故断为已成劳损。", ["细", "数"]], "14737": ["病机", "左脉空大，空为脉道不实、阴精亏乏，大为虚阳外张。原文以左脉空大属肾水亏，兼倦怠无力为脾气弱，食少则阴虚生内热，证属内伤。脉空大正是肾阴不足、虚热内生之征，与脾弱食少相应，故主内伤虚损。", ["空", "大"]], "14738": ["治法", "此段为按语，就左脉空大议补中益气与六味补肾之立法。左脉空大示肾阴亏虚、脉道不充而虚张，升、柴升散之品易耗阴升阳，故宜斟酌。脉象在此用于权衡用药，非单纯主病，故归治法，紧扣空大与升柴宜慎之论。", ["空", "大"]], "14739": ["病机", "脉软无力为气虚不能鼓动脉道，故属气虚。原文并述便溏食少属脾虚、干咳无痰属肺虚、时觉口苦属心热移脾，诸症合参，以气虚脾弱为本，兼有心热之标。脉软无力正应气虚之机，故立十补一清之法，补虚为主兼清心热。", ["软"]], "14740": ["病机", "脉缓无力，缓而无力为脾气虚弱、鼓动乏力的表现。原文述病将半载寒热奄缠，补营疏郁后心悸腹胀仍然，更见便溏足肿，显系脾气虚弱、运化失职、水湿下注。脉缓无力与便溏足肿相应，故当补脾，进归脾加减。", ["缓"]], "14741": ["病机", "脉细数弱，细弱为气血亏虚、脉道不充，数为虚热之象。原文谓骨格瘦小先天元气不足，夏秋寒热至今不已，脉细数弱断为气血两亏；头不痛而身疼、口沃清水，又属胃气虚寒。脉证合参，主气血两亏兼胃寒，故商温补仿东垣法。", ["细", "数", "弱"]], "14742": ["病机", "脉沉主里，数主热，沉数并见为里热郁结。原文述手足冷、胸闷食少属脾胃衰弱，大便干燥为肠中津液枯竭。脉沉数而手足冷，是阳气郁遏于内、津枯生燥之象，故法当温中土、润大肠，仿菟丝子丸加减，温润并行。", ["沉", "数"]], "14743": ["病机", "脉沉带数，沉为病在里、气血郁滞，数为火郁内扰。原文谓血止咳不已而脉沉带数，其根未去；以气逆则血逆、经络不和、血不宁静，故必降气而后血不升，充阴而后火退。脉沉数正示气逆火郁、血不归经之病机，根蒂未除。", ["沉", "数"]], "14744": ["病机", "脉数而血涌，然胃气大虚，胸中痞塞、大便带溏，故为虚痞虚数。咳血三月忽冲溢，唇白面青，断非实火，乃虚火迫血妄行。实火宜清降，虚火宜补和，此脉数非实热，主胃虚气不摄血之病机。", ["数"]], "14745": ["病机", "复诊脉数退而血少止，反恶寒汗出，乃血脱气无所依，气虚不固外卫。脉数退示虚火渐平，但气随血脱，最怕喘呃暴脱。胸痞已宽，稍能容纳，仿血脱益气，阳生阴长，主气虚欲脱之病机。", ["数"]], "14746": ["其他", "诒按仅言后方均是复脉加减，未及脉象与病机，属对前案方药之按语，非论脉主病。故脉象要素无，主旨归其他，不涉具体病机分析。", []], "14747": ["病机", "先天不足，虚痰溃敛，春阳升发，喉痒咳嗽，大吐血鲜红，脉细促，心嘈若饥。细为阴亏，促为火急，一团虚火炎炎莫御，迫血妄行。虽宜清降，亦当预顾真阴，否则血脱阴伤而晕，主阴虚火旺之病机。", ["细", "促"]], "14748": ["预后", "阴虚内热，咳嗽痰红，脉数无神。数而无力无神，乃真阴亏虚、虚火内扰之象，非实热。渐延劳损，示病势日深，预后堪忧。脉数无神为阴损及阳、精气渐衰之征，主劳损将成之预后。", ["数"]], "14749": ["预后", "咳嗽四年，曾失血，今音哑，脉形细弱。细弱为真阴元气皆亏，劳损根深，药难见效。幸胃气尚可、大便未溏，姑拟甘润养阴，希图苟安。脉细弱主精气两亏，劳损深重，预后不良。", ["细", "弱"]], "14750": ["治法", "再诊咳止而失血音哑，津液枯槁，劳损成矣。脉形细弱，精气两亏。宗《内经》调以甘药、《金匮》黄耆建中汤，急建中气，俾饮食增而津液旺，精血渐充。脉细弱主精气亏虚，治当甘药建中。", ["细", "弱"]], "14751": ["病机", "寒饮咳嗽化火动血，血证屡发，咳嗽不已，脉弦形瘦。弦为饮邪未去，形瘦为阴血已亏。静则咳甚属阴，饮由阴生；动则气升属阳，火动使然。阴虚痰饮显然，主饮邪未去、阴血已亏之病机。", ["弦"]], "14752": ["病机", "脉虚数为阴虚火亢之象，两尺愈虚则肾阴独亏尤为明显。心肝火旺故脉数，脾胃受戕、痰湿内生故脉虚；血随气逆则咳嗽黄痰带血，掌中觉热为阴虚内热之征。全段以脉虚数两尺愈虚点出肾虚为本、心肝火为标，故治法养肾阴以清心肝之火、肃肺胃之气。", ["虚", "数"]], "14753": ["病机", "脉数而左寸独锐，左寸候心，锐为火炎搏指之象，故断为心经有火。心火亢盛、迫血妄行，则吐血不止。此段以脉数左寸独锐定位病在心经，火性急迫故脉锐，血随火升故吐血，法宜清养，清心火而养阴血，使火降血宁。", ["数"]], "14754": ["预后", "脉沉细涩，沉为在里，细为阴亏，涩为血少津枯，合之咳嗽吐血、寒热朝轻晡甚、头汗不休，显系真阴大亏、虚阳上亢、肺金受烁、脾胃伤戕。津液日耗、元气日损，虚极成劳，故断为难为力矣。脉沉细涩正是精血枯涸、脉道不充之征，故姑拟生脉六君子汤保肺清金、调元益气以图缓。", ["沉", "细", "涩"]], "14755": ["治法", "此段为原注，纯述治法方义，无脉象描述。生脉散保肺清金，六君子去术嫌其燥、加扁豆培养脾阴，取土旺生金之意。不用养阴退热之药，恐滋腻碍肠、寒凉妨胃。强调久病以胃气为本，有胃则生，故治法重在保肺清金、培养脾阴以顾胃气，与上段脉沉细涩虚劳之治相呼应。", []], "14756": ["治法", "咳嗽内伤经络而吐血甚多，然脉不数、身不热、口不渴，说明并无火亢热盛之象，故切戒见血投凉。脉不数正提示病由内伤气虚、中焦不摄，血失统摄而外溢。法当益胃，拟理中加味，温运中阳以复统血之权。此段以脉不数辨其非热，是凭脉定治、反对见血凉血的关键。", ["数"]], "14757": ["病机", "吐血鼻血牙血发斑、斑中出血，为阳明之火极炽、迫血外溢；腹满濡软则少阴气不运。病已三月血有间断，是有瘀血在腹中。食少身热脉数，数主热亦主阴虚，故断其阴已虚。脉数与阳明火炽、阴分已亏相应，故拟养阴化瘀、清胃和中，既清阳明之火，又顾少阴之虚与腹中瘀血。", ["数"]], "14758": ["治法", "痰饮久咳，咳伤肺络而失血，然脉不数、舌苔白，说明无火热血燥之象，故不必过清。脉不数与苔白互证，提示病在气分痰湿而非热迫血溢。治但顺气化痰，气顺则血自归经，痰化则咳嗽可止。此段以脉不数排除热证，主以调气化痰，体现凭脉辨寒热、不妄用清凉之旨。", ["数"]], "14759": ["病机", "血证屡发历春夏秋，诊脉虚弱，形容清瘦，年方十七而精未充早泄，阴失守而火升。脉虚弱为正虚不足、气血俱亏之象，与形容清瘦相合，说明阴精亏耗、虚火内动。精未充而早泄则根本先伤，故虑异日难名之疾应褚氏之言。治宜滋水降火，兼须自保养，以固其本。", ["虚", "弱"]], "14760": ["病机", "原文未出脉名，然述“阴虚有火，外则寒邪深袭”，又引“阳维为病苦寒热，阴维为病苦心痛”，明指阴阳营卫偏虚、寒热错杂之病机。失血咳嗽兼三疟数月，疟来心口酸痛、胸腹空豁，皆营卫不调、阴阳两虚之候，故拟建中合生脉、复脉，双补肺肾之阴以调营卫。", []], "14761": ["病机", "脉细而迟，细为阴血不足，迟为阳气不运，合胸痛嗳气、舌苔白腻，知非单纯虚象。原文断为“胃中有瘀血，挟痰浊为患”，瘀阻气机则胸痛，痰浊中阻则嗳气苔腻，脉细迟正示气血不畅、痰瘀内结之机。", ["细", "迟"]], "14762": ["病机", "脉大气虚，大而无力为气虚不敛、清阳不升之象。便血肠燥，根在气虚下陷、肠失濡润。原文谓“补气则清阳自升，清肠则便血自止”，正以脉大示气虚为本，故治法补气升阳兼润肠，非单纯止血。", ["大"]], "14763": ["病机", "脉象细数，细为营阴亏耗，数为虚热内扰，故原文断“营阴大伤”。面黄少神、腹中鸣响，则脾气大困、脾阳不运。肠痔脱肛便血日久，苦寒止血更碍脾阳，故拟黑地黄丸法，滋阴而不伤脾，紧扣细数之脉与脾困之症。", ["细", "数"]], "14764": ["病机", "脉沉而细，沉主里、细主虚，面黧腹肿并见，知非表邪。原文断“脾肾之阳不化，水湿阻滞于中”，阳虚不能化气行水，水湿内停则肿，脉沉细正应阳气衰微、水湿壅阻之机，故姑予渗湿通阳，并防加剧。", ["沉", "细"]], "14765": ["病机", "脉浮主表，一身悉肿、咽痛发热、咳，乃风湿相搏于表，肺气失宣，水气溢于肌肤。原文“拟越婢法”，正是以脉浮为邪在表之据，取宣肺清热、发越水气之义，使表解则肿消。", ["浮"]], "14766": ["预后", "肿胀已退而脉较前稍大，汗出至膝，原文谓“阳气有流通之象，阴湿有消化之机”，是脉由沉细转大、阳气渐复之佳兆。然仍须温理中州、调养百日，以防反复，故本段重在判断预后转归，非单纯言病机。", ["大"]], "14767": ["病机", "脉沉主里，小便不利、面目肢体大腹阴囊悉肿，原文断“病属里水”，水湿内停、气化不行使然。鼻中流血、喉间略痛，则肺家有郁热。脉沉正示水病在里，故拟越婢汤宣肺清热、发越水气，兼解肺郁之热。", ["沉"]], "14768": ["病机", "左脉浮洪为风邪袭表、阳为湿遏而化热之象，右脉软数为湿与热合、营卫不和。原文谓\"阳被湿遏，不得宣越，湿与热合，交蒸互郁\"，更感风邪凑肺，故一身面目四肢悉肿、咳喘气急，成风水之证；寒热如疟、多汗则营卫不和、表虚不固，脉与症合，示正虚邪盛之势。", ["浮", "洪", "软", "数"]], "14769": ["病机", "脉细如丝为气血衰少、正虚之象，重按至骨乃见弦，是肝木乘脾、克伐中州。原文谓痞块由大疟日久、水饮痰涎与气相搏而成，久则癖散成臌，腹日加大、口干、小便短少，皆湿热不运、木旺克土之征，故脉细而沉取弦，主脾虚肝乘、水湿壅聚之臌胀。", ["细", "弦"]], "14770": ["病机", "脉沉主里，滑主积滞痰湿，数主热，合为暑湿伏邪挟积、阻滞肠胃之征。原文谓\"大腹骤满，腹中时痛，痛则大便黏腻，色红如痢，小水短少\"，皆中州不运、积滞化热、湿热下迫之候，脉沉滑数正应积滞内实，故拟大橘皮汤送木香槟榔丸以通利积滞。", ["沉", "滑", "数"]], "14771": ["病机", "脉沉主里、主水气内停。原文谓\"气与水相搏，大腹骤满，小便不利，大便欲泄不泄\"，气机壅滞、水湿不化，故脉见沉。沉为在里之征，示病位不在表而在气分水府，法当疏气逐水，使气行则水行，小便通而胀满自消。", ["沉"]], "14772": ["预后", "脉形细数为元气大亏、虚热内扰之象。原文谓脾虚胀满、面浮足肿、小便不利，脾阳不运则水湿泛溢，脉细示气血不足，数示虚阳浮动。细数并见，正虚已甚，故虑其喘急之变，示病势有转危之虞，属预后警示之论。", ["细", "数"]], "14773": ["病机", "脉细为气血衰少，形瘦腹胀如鼓而脉细，是木旺乘脾、脾土衰败之候。原文谓\"木旺乘脾，腹胀如鼓，形瘦脉细，证属单胀\"，肝木克伐，脾失健运，气水壅聚成胀，而形瘦脉细示正气已虚，故法当温通，温运脾阳以化气行水。", ["细"]], "14774": ["病机", "两尺脉滑，尺部候下焦，滑主湿热积滞。原文谓\"湿热积滞在于下焦，小便不利，大腹胀满\"，下焦气化不利则水湿不行，中焦气因之不通用，故大腹胀满。脉滑应湿热积滞之实，病位在下焦，与小便不利、腹胀之症相应。", ["滑"]], "14775": ["预后", "脉来虚细为阳虚气弱、水湿不化之象。原文谓痢后阳虚，腹满面浮足肿、色青黄，痢后脾阳受损，运化失职，水湿泛溢肌肤。虚细之脉示元气未复，正虚而水湿壅盛，故虑延臌胀重症，属预后不良之警示。", ["虚", "细"]], "14776": ["病机", "脉象细弦，细为阴血不足，弦为肝郁气滞。原文述肝郁木横克土，湿热不化，先淋浊后腹胀胁痛，此脉象反映木郁不达、肝脾不和之病机。弦主痛、主郁，细主虚，故见左肋隐痛、身微热，虑延鼓胀，提示气郁湿阻，久则胀满。", ["细", "弦"]], "14777": ["病机", "脉沉细涩，沉主里，细主虚，涩主血行不畅。原文述经停十月，腹微满，脐上心下块长数寸，属伏梁，因恚怒气郁痰凝所致。此脉象示气郁血滞、痰凝成积，病在里而正气已伤，故治宜开郁正元，理气行血，寓消于补。", ["沉", "细", "涩"]], "14778": ["病机", "脉沉紧而细，沉主里，紧主寒主痛，细主虚。原文述休息痢后气攻胸脘板痛，聚而成块偏右，为脾之积，面色晦滞。此脉象反映阳气郁伏、浊阴凝聚，寒凝气滞成积，故当温通以散阴寒。", ["沉", "紧", "细"]], "14779": ["病机", "脉象沉弦而紧，沉主里，弦主气郁，紧主寒凝。复诊大便已通，脘腹之块未化，面色晦滞已明，阳光一𬀪，阴凝渐通。此脉象仍示寒凝气滞、阴邪未散，但已有松动之象，故仍以温通为治。", ["沉", "弦", "紧"]], "14780": ["病机", "脉沉弦小，沉主里，弦主肝邪，小主正气不足。原文述气从少腹上冲咽嗌，心中跳，胁中痛，此奔豚气挟肝邪。寒热虽止而气仍上逆，脉象示肝气郁逆、冲脉不降，故宗《金匮》法以平冲降逆。", ["沉", "弦", "小"]], "14781": ["病机", "右关滑动主痰积中焦，左关弦搏主肝木气旺，尺寸俱微缓示气血两亏。原文述泄痢一载，痰积湿热肝气互结，左肋梗硬。此脉象反映本虚标实，痰热郁结而元气已弱，故攻补两难，唯择性味不猛者通化。", ["滑", "动", "微", "缓"]], "14782": ["病机", "脉迟细，迟主寒，细主虚。原文述脘中有块，纳食撑胀，腹中漉漉作声，嗳腐吞酸，大便坚结，此脾胃有寒积。迟细之脉示中阳不足、寒积内停，故当以温药下之，仿温脾法以散寒消积。", ["迟", "细"]], "14783": ["病机", "脉沉弦细，沉细为虚为寒，沉弦为气为郁。原文述结癖累累久踞腹中，年逾六旬，元气下虚，中气已弱，肝气肆横，腹渐胀满。此脉象反映正虚寒凝、气郁成积，病关情志，非湿热积滞，故攻消难施，拟商通补。", ["沉", "弦", "细"]], "14784": ["病机", "原文未出脉名，以“血虚木横”立论：肝血虚则木失柔养而横逆，故两胁气撑胀痛、腹中有块；血虚心神失养则心荡，营卫不和则寒热。病根日久损及奇经，冲脉为病逆气里急，任脉为病女瘕，阳维苦寒热，阴维苦心痛，诸症与奇经病机相合，故谓调之不易。", []], "14785": ["病机", "此段为诒按，无脉象。主旨辨奇经病之由来：十二经气血有余则溢入奇经，有病者必日久病深由正经侵入。故虽见奇经症候，用药仍当以正经为主，不可为近贤专主奇经之说所蒙。所论为病机传变与治法归属，非主一脉。", []], "14786": ["病机", "脉微细为阴象，阳虚阴盛之征。少腹有块上攻及脘，自脘至嗌气塞，发作大痛欲厥、头汗如雨，皆浊阴上干清阳、阴气凝结所致。然舌黄腻浊苔、便泄臭秽，又兼湿热；块痛得按稍减，中气亦虚。脉微细与阴凝相应，而湿热虚象并见，故方法难周。", ["微", "细"]], "14787": ["预后", "复诊脉仍微细，温通后病势虽减而脉象未复，说明阴寒凝结未解。下焦浊阴上干清阳，少腹胸胁有块攻撑作痛，痛甚发厥；泄仍臭秽、恶谷厌纳，中气大亏，当脐硬痛，恐属脏结。脉微细示阳气衰微，攻补两难，故诚为棘手，属预后堪忧之候。", ["微", "细"]], "14788": ["病机", "渊按无脉象，就水寒血气凝聚冲脉之分立论：水寒之气与血气相结，凝于冲脉所过之处，乃成块痛等症。果系实证，则温散水寒、通利血气之方必效。此段辨冲脉病之属寒实者，明其病机在寒凝气结，非虚损可比。", []], "14789": ["病机", "原文未出脉名，述少腹有块、痛则经来如注、气升如喘。冲脉久伤则血海失约，经来如注；冲气上逆则气升如喘；肝木肆横则少腹块痛。病机在冲脉损伤、肝木横逆，气血失于制约，故见经行暴下与气逆并作。", []], "14790": ["病机", "脉小紧数，小为阴血不足，紧数主郁热内迫。痛久气血瘀凝，曾吐血乃阳明胃络郁热蒸迫而上；血止后痛仍作、发于午后，舌红无苔，是血去阴伤而气分郁热仍阻肝胃之络，不能透达。脉小紧数正合阴伤郁热之机，故宜理气疏郁、辛通而不耗液。", ["小", "紧", "数"]], "14791": ["病机", "脉细主阳气不足、痰饮内阻。胸痹痰饮、脘痛甚则呕酸，乃胃阳不布，阴寒痰浊上逆所致。脉细与胃阳不振相应，阳不运则饮停，饮停则胸痹脘痛。故先以通阳为治，阳复则饮化而痛止，此脉细示虚寒饮阻之病机。", ["细"]], "14792": ["病机", "脉细少神，细为气血不足，少神示脾胃气衰。脘胁痛虽除而脾胃大惫，面浮足肿乃土衰水泛，水湿内停。脉症合参，虑其腹满，急宜温补中阳以消水湿，属阳虚水泛之病机。", ["细"]], "14793": ["病机", "脉微形瘦，微为阳气衰微，形瘦为营阴不足。阳维病则阳气弱而腹痛便溏，阴维病则营阴虚而心痛舌红。阴阳并损，损及奇经，故脉微形瘦，当以甘温补益。", ["微"]], "14794": ["病机", "脉细主气血不足，阳虚则肢体面目俱浮、便溏。舌红无苔为阴伤，口不干渴乃君火外露。此阳虚阴伤，虚阳上浮，治当引火归元，脉细正是阴阳两虚之征。", ["细"]], "14795": ["病机", "脉迟弦，迟为阳虚寒凝，弦为肝气不舒。过服消积破气，中气伤戕，肝胃不和，阳虚寒聚于中，故脘间窒痛、得食则安、不能嗳气转矢气。拟通阳泄木法。", ["迟", "弦"]], "14796": ["病机", "脉涩数，涩为血瘀，数为火热。热走清道则鼻衄，热逼膻中则心痛，小便赤。此血因火逆，火随血结，瘀热互结，故脉涩数，仿热厥心痛合瘀血心痛例，清之导之。", ["涩", "数"]], "14797": ["病机", "脉沉弦，沉主里主寒，弦主痛主积。腹痛下午胀，脉沉弦，属虚寒挟积。前用温下痛减，今以温中化积，脉沉弦正是寒积内结之象。", ["沉", "弦"]], "14798": ["病机", "脉小弦滑，小为虚，弦为寒为痛，滑为宿积。腹痛三年，寒在中焦，然脉小弦滑必有宿积。每交午月痛甚，兼湿热，故脉浮小而沉大，按之有力，阴中伏阳。当利少阴之枢，温厥阴之气，运太阴之滞。", ["小", "弦", "滑", "浮"]], "14799": ["病机", "脉浮小沉大，浮小为虚，沉大为积伏下焦。痛则气聚于下，故脉见沉大。渊按既知宿积，当再进温下，三年之病谅非久虚。此论积伏下焦，脉沉大主积，似是而非之辨。", ["浮", "小", "沉", "大"]], "14800": ["病机", "左脉弦，原文明言“木克土也”，肝木乘脾，故腹痛。仲景以腹痛脉弦主小建中汤，正是培土抑木；痛得食稍安属中虚，漉漉有声兼水饮，故建中加椒目以去水饮。弦为肝脉，见于腹痛，示肝邪犯中焦，非单纯虚寒。", ["弦"]], "14801": ["病机", "左脉独弦滑，原文断为“肝邪乘胃”。弦主肝木，滑主痰饮，肝邪挟饮上逆，故痛势上攻胃脘、连及心下。前用建中而痛势上攻，说明中虚未复而肝胃不和加剧，故改拟疏肝，弦滑并见正是肝旺饮停之征。", ["弦", "滑"]], "14802": ["病机", "脉迟主寒，原文“中虚阳弱，寒积内停”点明病机。喜食甜味、痛在当脐连腰、常懔懔恶寒，皆中阳不足、寒积内停之候。便通而痛未止，说明积未全去而阳未复，故拟通阳破沉寒、益火消阴翳，迟脉正是阳虚寒凝之据。", ["迟"]], "14803": ["病机", "脉弦迟，原文引《脉经》“迟则为寒”，又引仲景“口不渴而脉双弦者，饮也”。弦主饮癖，迟主寒，寒饮内停于中，故脐以上连胃脘胀痛。弦迟并见，说明寒饮结聚、阳气不运，与口不渴之症相应，故主寒饮。", ["弦", "迟"]], "14804": ["病机", "脉弦大而迟，原文断为“胃中阳气不足，而有寒饮”。迟为阳虚，弦大为寒饮内盛、气机壅塞之象。当脐腹痛、痛则气塞胸中、嗳气不得语，正是寒饮阻遏胃阳、气逆不降之候，故以温药通阳化饮为治。", ["弦", "大", "迟"]], "14805": ["病机", "脉沉弦而紧，沉主里，弦主痛主饮，紧主寒主结。原文谓“素有肝胃气痛，兼挟寒积”，脘腹胀满、痛及于腰、舌苔白腻、渴不欲饮、大便似利不利，皆寒积内结之候。沉弦紧并见，示寒结深痼，恐成脏结，故用温脾法温通破结。", ["沉", "弦", "紧"]], "14806": ["预后", "两投温下而便仍不通，胸腹高突、汤水辄吐、肢渐冷、脉渐细、鼻煽额汗，原文断为“厥脱可忧”。脉细为阳气衰微、脉道不充，与肢冷、额汗并见，是阳脱之兆。又辨结胸、脏结以寒热为别，归咎太阴脾脏受戕、清阳失运，故用枳实理中挽回。", ["细"]], "14807": ["预后", "脉形弦硬，原文谓“春令见此，是即但弦无胃”。春脉当微弦而和缓，今弦硬无胃气，是木火亢逆、胃汁肠液干枯之象。纳食哽痛、大便坚燥，正与弦硬之脉相应，示真阴耗损、胃气将败，故断为“治之不易”，属预后不良之候。", ["弦", "硬"]], "14808": ["病机", "左脉沉数不利，沉主气郁，数主火，不利为血少不泽，故断为肝气郁而血少；右关及寸滑搏，滑主痰，搏主火，为痰火壅盛。肺胃气失降，肝木之火上逆，蒸津为痰，阻塞气道，故咽喉胸膈阻碍、纳食呕噎。脉象与五志化火、阳亢阴不上承之病机相应。", ["沉", "数", "滑"]], "14809": ["病机", "脉细如丝，为阴气凝聚、阳气汩没之象。气郁胸膈则饮食不纳，气滞腹中则臌胀，形肉顿瘦，皆由阳气衰微、阴寒内结所致。细脉主气血虚少，更兼阴凝阳陷，故以培土、通阳、化气为治，脉象直接反映阳气不振、阴寒内盛之病机。", ["细"]], "14810": ["主病", "脉滑大，滑主痰，大主热，食入哽噎不下、舌腻，显系痰浊壅盛、化火阻膈之痰膈证。大肠燥火凝结，更助痰火之势。脉象与痰火内盛、气机不通之病机相应，故拟清痰火、佐宣通为治。", ["滑", "大"]], "14811": ["病机", "胃脉浮按则紧，沉按则弦。紧主寒，弦主木旺，弦为木侮土，紧为寒邪在中，木乘土位，胃气上逆，故食下饱胀、作酸呕吐而成反胃。脉象直接揭示肝木犯胃、寒滞中焦之病机，与反胃症候相应。", ["浮", "紧", "弦"]], "14812": ["预后", "脉细肢寒，细为阳气衰少，肢寒为阳微不达四末，故曰阳微已甚。先曾呕血，胃中空虚，寒饮停留，阳气不通，水谷不化，食入呕吐酸水，证成翻胃。脉症合参，虑延脾败难治，脉象提示阳气衰微、脾胃将败之预后不良。", ["细"]], "14813": ["病机", "两手脉沉，沉主气郁。胃中素有酒湿，因恼怒引动肝胆之火，与胃痰相搏，致心跳少寐、食入则呕。脉沉反映气机郁滞、痰火内阻之病机，故用温胆加味以化痰清火、理气解郁，脉象与气郁痰火之证相应。", ["沉"]], "14814": ["病机", "脉沉细，沉为阴盛，细为阳衰，故曰重阴之象。三阴三阳俱结，太阴无阳明之阳，少阴无太阳之阳，厥阴无少阳之阳，阴独盛于内，阳气不通，阴气凝涩，膀胱不化而水成，故反胃兼浮肿。脉象直接反映阴阳俱结、阴寒内盛之病机。", ["沉", "细"]], "14815": ["病机", "右脉沉滑，沉主气滞，滑主痰；左脉细弱，细弱为血虚。吐血后瘀血挟痰浊阻于肺胃之络，下焦相火随冲脉上逆，鼓动其痰而呃逆。脉象与瘀血痰浊阻络、相火上逆之病机相应，故呃气自少腹上冲，舌白腻亦痰湿之征。", ["沉", "滑", "细", "弱"]], "14816": ["病机", "脉沉细数而涩，沉细为阴血不足，数为郁热内蒸，涩则血行不畅、气机郁滞。原文谓“血虚气郁，经事之不来宜也”，正合此脉。五志郁极从火化，故饥而善食、小溲澄脚如脓，为三消之渐；胸痛吐酸水，乃肝郁化火生虫之征。脉象揭示血虚为本、郁热为标，虚实夹杂。", ["沉", "细", "数", "涩"]], "14817": ["病机", "药后便溏易出，是苦泄暂效，然“脉仍数涩”，数主郁热，涩主血虚，说明郁热未清、脏阴日消。原文言“究属血虚而有郁热”，故见舌红而碎、口渴消饮、月事不至，血日干而火日炽；头眩目花带下，皆阴虚阳亢之征。脉数涩不去，示病根深固，清郁热与补脏阴须并行。", ["数", "涩"]], "14818": ["主病", "左寸关搏数，左寸候心、左关候肝，搏数乃火势极炽之象。原文直断“心肝之火极炽”，火灼下焦则口干、小溲频数而浑浊，成下消证；久有脚气，湿热蕴于下焦。脉数在此既主心肝实火，又示湿热内蕴，故治拟清心肝之火、化肾与膀胱之湿，脉症相合。", ["数"]], "14819": ["病机", "肛漏阴津先损于下，嗜酒湿热盛于中，劳碌感寒与胸中痰湿相合，遂成痰饮咳嗽、呕吐清水。原文点明“内热脉数，阴津已亏”，数脉主热，热灼阴津，故欲蠲痰饮恐温燥劫阴，欲除内热恐清凉增咳，治疗两难。脉数揭示阴虚内热与痰饮并存之病机，宜和胃降气。", ["数"]], "14820": ["病机", "咳呕清水为痰饮，而“脉细数，内热，为阴虚之候”，细主阴血不足，数主内热，故知阴虚为本。原文指出治痰饮宜温、治阴虚宜滋，药适相背。肝肾子母之脏，补母益子；胃土为肺金之母，又当和胃化痰。脉细数正是阴虚内热之凭据，故拟滋燥兼行，仿东垣法而不碍。", ["细", "数"]], "14821": ["病机", "脉沉弦者，沉主里、弦主饮，原文径言“饮也”。饮邪内停，浊阴之气上攻阳位，故头眩心悸，病发则呕吐酸水、满背气攻作痛，得嗳则痛松。脉沉弦恰合饮停气逆之机，故治“当以温药和之”，以温化饮邪、通降浊阴，脉象与症候相互印证。", ["沉", "弦"]], "14822": ["预后", "痰饮久留，咳喘痰多黏腻，脾肾两亏，脾虚痰不化而食减，肾虚阳衰水泛，致腹满足肿面浮成溢饮。原文虽引《金匮》小青龙发汗之法，然“脉细阳衰，便难液涸，肾气久虚”，细脉示阳气阴液俱衰，不堪发泄耗阴伤阳，故改拟附子都气丸裁去熟地。脉细在此判断攻邪之禁，关乎预后转归。", ["细"]], "14823": ["病机", "风邪久恋肺中，寒饮停留胃脘，风能化热，咳久伤阴，积饮生痰，胃阳失布。肺伤则肾亏，胃虚则脾弱，脾弱故便泄，肾亏故“左尺脉弦而大”。左尺候肾，弦大为肾虚饮泛、阳气不藏之象。原文虽曾吐血而时呕清水，断为寒饮无疑，脉弦大正合肾亏饮停之病机，故从饮门例治。", ["弦", "大"]], "14824": ["病机", "脉双弦者，一手两脉皆弦，弦为饮邪内伏、木旺克土之象。原文谓痰饮伏留心下，得食则安，是中虚而饮停；形肉瘦削、口不渴、头眩心悸，皆饮遏清阳、阴血不充之征。双弦既示饮邪恋膈，又见脾胃气弱、肝肾阴亏，故从肺脾肾三经立法，外饮治脾肺、内饮治肾，层层深入。", ["弦"]], "14825": ["病机", "脉细为元气不足、寒饮内阻之象。原文言手足太阴二经有寒饮积滞，阻遏清阳，故头常眩运、当脐痛而口不渴；清阳不能通达，郁极则欲达，故一月之中必发寒热数次。病将四月，元气渐虚而饮仍不化，细脉正示正虚饮恋，先以小青龙蠲饮通阳，再议补虚。", ["细"]], "14826": ["病机", "脉沉取之数，沉主里、数主热，合之则阴内亏而热在里。原文谓病延日久，劳损之候，咳唾白痰、脘腹时痛、得矢气稍宽，病由肝郁而成；咳已三年而初无身热，是根在痰饮。沉数并见，说明郁热伏于阴分、痰饮气郁交阻，故从痰饮气郁例治，求其根而不徒清热。", ["沉", "数"]], "14827": ["治法", "本条仅列六味地黄丸合生脉散加青铅，脉散为气阴耗散、肺肾不摄之象。六味滋肾填阴，生脉散敛肺益气，加青铅重镇摄纳，正合散脉所主之虚浮无根。虽原文未详症候，然以方测脉，知为咳嗽日久、气阴两伤、摄纳无权之候，故用补敛镇摄之法，使散者收之。", ["散"]], "14828": ["病机", "脉涩而数，涩主血少气滞、痰湿阻络，数主热。原文谓伏暑挟湿，湿能生热，咳嗽痰稠、曾经吐血，血止而咳仍，舌苔灰白而渴，是湿热痰浊恋于肺胃。涩示血行不畅、痰阻脉道，数示郁热未清；病将匝月，元气大伤，谷食少进，故治在化痰降气和中，兼顾脾胃。", ["涩", "数"]], "14829": ["病机", "左脉细微，左候肝肾，细微为阴阳俱虚、摄纳无力之象。原文谓咳嗽痰喘浅在肺胃、深属肝肾，今气短有出多纳少之意，是本虚已著；虽舌苔黄浊不化，亦当以摄纳为要。额上汗冷、胃泛不纳，正是虚阳上浮、将成虚脱之兆，故舍标治本，急予摄纳固脱。", ["微", "细"]], "14830": ["预后", "本条为末药服法及预后判断，未识脉名。原文以好肉桂、上沉香、坎炁研末调服，意在温肾纳气、引火归元。所谓若得额汗收敛、左脉稍起，犹有生机可理；若不应手，难为力矣，是以额汗与左脉能否复起为虚实脱绝之验，脉起则元气尚可挽回，脉不起则摄纳无权，预后不良。", []], "14831": ["病机", "脉形细数，细为阴虚血少，数为虚热内扰。原文谓下焦阴虚、中焦痰盛、上焦肺弱，肺弱故身常恶寒，阴虚故脉数，喘哮频发则由痰盛。细数并见，说明阴亏于下而痰踞于中，虚热与痰浊相兼，病分三层，故治有三法，层层护卫，法法兼到，非一端可尽。", ["细", "数"]], "14832": ["病机", "脉迟为寒，舌白为痰，此喘之标在肺、本在肾，寒痰内伏，肺气不降，肾阳不足，故以金水六君煎加味温肾化痰。脉迟主脏寒，与舌白痰证相应，说明病机为寒痰阻肺、肾不纳气。", ["迟"]], "14833": ["病机", "脉形细数，细为阴津大亏，数为火旺，值炎暑水衰火旺，金受其灼，故气喘交午愈甚、掌心热、咳嗽痰黄，渐延损症。脉细数主阴虚火旺，与汗多、头汗未敛、饮食减少相应，说明肺阴耗伤、虚火内炽。", ["细", "数"]], "14834": ["病机", "脉象弦滑，滑主痰饮，弦主气逆，痰饮属阴，夜重于昼，故喘息不安。中气不足，湿化为痰，气逆不降，脉弦滑与痰饮内停、气机壅逆相应，说明病机为痰饮阻肺、中气亏虚。", ["弦", "滑"]], "14835": ["病机", "右脉虚细，左脉促疾，阴气大亏，阳气偏亢，显成劳瘵之形。虚细为阴伤，促疾为阳亢，火入金乡则咳喘汗多，木乘土位则便溏不食，脉与舌红燥裂、溺痛频数相应，说明水亏木横、火烁肺金。", ["虚", "细", "促", "疾"]], "14836": ["治法", "原注脉散，此六味汤合生脉散等四方并一，用生地补肾阴，麦冬、沙参补肺阴，五味敛汗，芍药、甘草土中泻木，通草、竹叶合导赤散治窍痛。脉散主气阴耗散，故以酸敛补阴、泻火缓痛为法，服后喘止泻止，说明脉散与气阴两伤相应。", ["散"]], "14837": ["预后", "复诊脉数未退，阴虚未复，咳嗽不止，肺气日虚，夏暑将临，病尚未稳。脉数主阴虚火旺，数未退则阴未复，与咳嗽不止、肺气日虚相应，说明病机仍属阴虚肺弱，预后需小心安养。", ["数"]], "14838": ["病机", "七旬有六，面色红润，脉形坚搏，外似有余，里实不足。坚搏为真阴亏虚、虚阳外露之象，屡患咳嗽，娇脏暗伤，风温劫胃津、灼肺阴，脉与舌苔薄白底有裂纹、饮食略减相应，说明本虚标实，不可辛散。", ["坚", "搏"]], "14839": ["病机", "右脉弦滑，左弦小数，弦主肝郁，滑主痰，数为热，小为阴伤。肝经郁勃之热，肺家胶黏之痰，痰为火郁而臭，非肺痈可比。脉弦滑数小与咳嗽喉痒、痰或稀或浓腥臭相应，说明病机为肝火犯肺、痰热内郁。", ["弦", "滑", "数", "小"]], "14840": ["预后", "咳嗽面白为肺金受伤，脉数而洪属虚火，火旺克金，脉象与面色相克，故言'脉克色而火胜金'。夏至一阴生，火令极盛而阴始复，若剥而不复，则火灼金销，预后堪虑。此段以脉数洪断虚火灼肺，重在预后转归。", ["数", "洪"]], "14841": ["治法", "原文仅言'脉散'，散脉主气耗不收，肺气耗散则咳。故用生脉散合六君子汤加紫菀，生脉敛散，六君健脾益气，紫菀润肺止咳。此段以脉散为据，立益气敛肺、健脾化痰之法，属治法范畴。", ["散"]], "14842": ["病机", "原文未出脉名，纯述病机。暑风从背俞内薄于肺，湿热从胃脉上注于肺，外内合邪并于胸中，气不得通则上逆作咳。舌苔薄白、口腻不渴，属饮家。此段论咳嗽病机为外邪与湿热合于肺胃，气逆而咳。", []], "14843": ["病机", "邪恋肺虚，脉形空大，空大者虚而无力，主肺气亏虚。前用降气化痰、保肺涤饮无效，得汗则身体轻快，知留邪未尽。故补虚兼化邪，用钱氏法。此段以脉空大断肺虚留邪之病机。", ["空", "大"]], "14844": ["病机", "脉虚软而似数，虚软为气虚，似数非真数，乃虚阳躁动。'邪之所凑，其气必虚'，虚处受邪则病实，咳嗽虽由外感，实因气虚。故既不可纯作风寒，亦未必是虚损，用玉竹饮子。此段以脉虚软似数辨气虚受邪之病机。", ["虚", "软", "数"]], "14845": ["预后", "嗜酒多湿，湿蕴生痰，体质阴虚，烦劳伤气，咳嗽带血、行动气升。诊脉虚小，虚小为气阴两亏，恐正不胜邪而加喘急，故以金水六君煎加味。此段以脉虚小断气阴亏虚，虑其喘急，重在预后。", ["虚", "小"]], "14846": ["病机", "伤风咳嗽本多浮脉，今反沉紧而涩，沉紧为邪伏，涩为血滞，是邪伏深固、肺气郁而不达。左肋一点疼痛不移，防发肺疽；声哑为竭力正虚。拟芎枳散合泻白法，清金兼挑血分之风。此段以脉沉紧涩辨邪伏血郁之病机。", ["沉", "紧", "涩"]], "14847": ["病机", "左尺极细，寸关微而似数，右三部俱弦滑。尺细主肾阴亏，寸关微数主虚阳，右弦滑主湿热相火。下有遗精、肛门痒出水，上则头眩耳鸣、苔粉白，乃肾阴下亏、湿热相火下淫上混，蒙闭清窍。此段以脉合症辨阴虚火旺、湿热蒙窍之病机。", ["细", "微", "数", "弦"]], "14848": ["病机", "原文未识脉名，但述精浊连年不断、血块淋漓，乃肝肾大虚、八脉失固，兼湿热混乱不清。舌苔白腻示湿浊内蕴。病机为虚不摄精、湿热下注，故见精浊血块；法当脾肾双补、固摄下焦，针对虚而兼湿之机。", []], "14849": ["病机", "脉之虚主肝肾八脉亏虚，因湿浊混淆、精血频下所致。虚脉示正气不足，然湿热未清，相火不宁，徒补则壅滞。原文强调“不先清湿热以宁相火”，说明虚中夹实，病机为虚不固摄兼湿热扰精，故先清源后塞流。", ["虚"]], "14850": ["病机", "脉细肢寒，细主阴血不足，肢寒为阳不布达。原文谓“肾阳与胃阳不布”，因水窍为败精瘀浊阻塞，湿热不泄，浊气上攻致嗳气、腹中不和、二便不爽。病机为阳虚湿浊内阻，下焦气化失司，故法宜通阳渗湿、益肾化浊。", ["细"]], "14851": ["病机", "脉细固属阴虚，若下垂尺泽，为相火下淫。尺泽候肾，细而垂尺示肾阴亏虚、相火妄动，迫精血下流，故精血下流、小溲频数、溺窍疼痛、大便干结。病机为肾阴不足、相火偏亢，法补养肾阴兼清相火。", ["细"]], "14852": ["病机", "脉左小右大，左小为肾水亏虚，右大为心阳内亢。原文谓“肾水下亏不能上承于心，心阳内亢而反下趋于肾”，坎离不交，故下为淋浊尿血、宗筋绊痛，上为眩晕咳嗽、心中震跃。病机为心肾不交、阴虚阳亢，属内伤虚证。", ["小", "大"]], "14853": ["病机", "右脉空大，两尺皆虚。空大示心阴耗损、君不制相，相火妄动，故强阳常举、精浊时流；尺虚为肾气不固，见肛门气坠、大便溏薄。心中嘈辣、干嗽无痰亦阴亏火旺之象。病机为心阴亏虚、相火妄动、肾气不固。", ["空", "大", "虚"]], "14854": ["病机", "左脉虚细，右脉洪大。左候肾阴，虚细为阴亏；右候相火，洪大为火胜。原文谓“阴亏而相火胜也”，肾虚精关不固，湿热混于坎宫，精从溺后而出。病机为肾阴亏虚、相火偏胜兼湿热下注，法补肾阴、化湿热。", ["虚", "细", "洪", "大"]], "14855": ["病机", "脉弦紧主痛、主寒。先腹痛数日，继小便不利、少腹胀满如鼓，屡用通利益甚，舌苔白腻、便泄黏腻，身无寒热。此中阳不足，水湿泛溢，膀胱气化无权，弦紧示寒湿内盛、气机凝滞。法当温土御水寒、通阳化湿浊。", ["弦", "紧"]], "14856": ["病机", "脉细主气血不足、阳气衰微，肢寒为寒凝下焦、阳气不达四末之征。原文言\"寒气客于下焦，瘀凝停于小腹\"，膀胱阳气失化而癃闭，产后八日小溲不通，腹中觉冷，正合脉细肢寒之象。寒瘀阻塞胞门，阳气不能温通，故虑气逆上攻发厥，法当温通化瘀利水。", ["细"]], "14857": ["病机", "脉细为津液亏耗、脉道不充，数为燥火内灼之象。原文谓\"肺热叶焦，津液不能灌输于经脉\"而成痿躄，形肉消削、咳嗽痰臭、舌红无苔，皆津液消耗、燥火内灼所致。肺为水源，百脉朝宗，肺热则百脉失润，故脉细而数，主痿躄之病机在肺胃津伤。", ["细", "数"]], "14858": ["病机", "脉形濡主湿邪内蕴、气血为湿所困。原文言暑雨潮湿，湿从下受入于经络，两足腿股酸楚不能屈伸，此脚气之候。适值经行，湿热自气伤营，故少腹窒塞、小便涩痛、舌苔白底绛、身微寒热。濡脉正应湿滞，虑气逆冲胸之变，拟防己饮加减以化湿热。", ["濡"]], "14859": ["病机", "脉之凝涩主气血郁滞、络脉不通。原文述经后少腹痛连腰股、肛门气坠、大便不通、小便赤涩热痛，皆肝经郁热、络脉凝涩之征。涩脉示血行不畅，郁热阻滞肝经，故拟宣肝经郁热、通络脉凝涩为治，脉涩与症候相合。", ["涩"]], "14860": ["病机", "此段未识脉名，纯论病机。原文谓经未尽而行房过度，经血乘虚入络，冲任八脉受伤。行房耗损肾气，经期血室正开，乘虚内陷，伤及冲任，故成瘀滞之患。虽无脉象可凭，然病机在冲任损伤、血络瘀阻，与经行不尽、房劳伤肾相应。", []], "14861": ["病机", "脉沉涩主阳气陷下、营血瘀滞。原文言经来半月不止、紫血块、少腹疼痛、气坠阴门、下午恶寒，正是阳陷入阴、营虚失守之候。沉为阳陷，涩为血滞，紫块与痛皆瘀象，气坠阴门为气虚下陷。故法以升阳收摄其阴，脉症相合。", ["沉", "涩"]], "14862": ["病机", "脉小而迟缓主阳气不足、脾胃虚寒。原文谓营分有热则经至淋漓，卫分有寒则脉小而迟缓，脾为营之本、胃为卫之源。经至而舌苔反布、胸无痞闷，是胃阳虚无力化浊。小迟缓三象皆阳虚之征，故拟醒胃阳以摄脾阴，脉象正示中阳不振之病机。", ["小", "迟", "缓"]], "14863": ["病机", "脉细迟缓主中气不足、气血两衰。原文言经行过多，血气两衰，肝肾失固；舌白多痰为胃有浊，咽干色红为阴虚火浮。细为血少，迟缓为气虚阳弱，正合\"中气不足\"之论。脉象与血气两衰、胃浊阴虚之兼症相应，故议金水六君煎、生脉四君子合参。", ["细", "迟", "缓"]], "14864": ["病机", "右脉更觉细微，为脾气虚衰不振之象；左脉稍觉有力，得归、地滋养之功。脾虚不能统血，冲任不固，故经漏不止；心脾不足，则心跳食少；腹中微痛，气虚且滞。脉细微主虚，与脾虚证候相应，故治仿黑归脾法，补脾以固冲任。", ["细", "微"]], "14865": ["病机", "脉小迟缓，小主虚，迟主寒，缓为不足。此脉不属热象，乃脾肾阳虚、不能固摄其血之候，故漏下未必属热。阳虚失于温煦，血不归经，故当温固兼施。若见血即以为热，则误矣。脉小迟缓正是虚寒之凭据。", ["小", "迟", "缓"]], "14866": ["病机", "脉促数，促为阳盛而阴不能和，数为热。寒热无序，下有淋带，上则心跳，少腹痛，便坚，面色痿黄，皆血瘀化热、气血壅滞之候。瘀血内阻，新血不归，故见淋带；瘀热上扰，则心跳。脉促数主瘀热内结，虑延劳损。", ["促", "数"]], "14867": ["病机", "脉象细数，细为阴血不足，数为有热。崩后淋带不断，少腹板痛，身发寒热，乃血瘀未尽，复兼肝气夹寒，脾胃大虚。瘀滞则痛，虚则脉细，寒热错杂则数。法当通补，通瘀补虚并行，以脉细数知阴伤而热未清。", ["细", "数"]], "14868": ["预后", "脉弦硬无情，脉愈数，乃阴虚阳亢、元气极虚不能固摄之候。年近六旬天癸反频来，为脱营下竭，血从外脱；下竭必上厥，故面赤火升发热。血属阴，阴虚则阳亢，故脉弦硬无情；数则阴愈虚。夏令阳亢无制，恐水涸龙飞，预后不良。", ["弦", "硬", "数"]], "14869": ["病机", "原文未及脉象，以乳汁化生之理言病机。乳房属胃，乳汁血所化；无子而乳胀出汁，非血有余，乃血不循道下归冲脉为月水，反随肝气上入乳房。血犹水，气犹风，血随气行，如风激水作波澜。治当顺气下行，非堵截涩源。", []], "14870": ["病机", "脉轻按虚微，为元气之虚；重按细数，属营阴之损；左尺细弱，肾水亏也。因目疾过服苦寒，戕伐生生之气，胃寒则阳郁生湿，肝寒则阴凝结瘕。经来热甚，舌布白苔，湿浊熏蒸。少腹块痛聚散无常，瘕属无形之气。脉虚微细数，主元气阴营俱损。", ["虚", "微", "细", "数"]], "14871": ["病机", "脉数不和，舌仍光赤，乃阴津未充、虚阳未敛之象。内热日久经停，投养阴调血通经得热退经行，然脉数不和，知阴津未复，虚阳尚浮。数脉主热，此热为虚阳外扰，非实火，故宜小心安养，待阴充阳敛则脉和。", ["数"]], "14872": ["预后", "原文言「脉数已和」，是数脉已趋缓和，说明前此热扰脉道之数象渐退；又「舌色光红已退」，热势得减，营阴渐复。然「尚觉微热」，余邪未尽，故仍守前法增损调治。脉数转和提示邪热渐解、病情向愈，而非病机新变。", ["数"]], "14873": ["病机", "脉沉而数，沉主里、数主热，合「热伏营血之中」，明示热邪深伏营分而非在表。忧愁抑郁耗损心脾之营，肝木僭逆，气塞内热夜甚、经事两月不来，皆营血郁热、木郁不舒之候。故用柴胡四物汤和营血以舒木郁，脉象正点出病位在里、病性属热。", ["沉", "数"]], "14874": ["病机", "原文未识出脉名，故脉象要素为空。年近五十，经事频来且多，乃「冲脉不司收摄」之故。冲为血海，主蓄溢，摄纳失职则经水频多，久则有崩决之虞。此段以年岁与经候推求冲脉失摄之病机，主在防崩，故曰补之摄之，非凭脉立论。", []], "14875": ["病机", "脉象虚微，虚为不足、微为阳衰，合「气血大亏」。两次血崩后赤带连绵半载，冲任不固，气血耗伤，故头眩、心跳、腰酸、足软并见。近腹痛食减，脾运亦弱，恐再致崩决。脉虚微正应气血两亏、奇经失养之机，故拟方固摄奇经。", ["虚", "微"]], "14876": ["病机", "脉虚数，虚为气血不足，数为虚热扰动。产后血舍空虚，八脉先伤于下，悲哀伤肺，咳嗽震动冲脉上逆，故气逆痰多、背寒内热。频进疏风清热再伤脾胃，致便溏食减，病成蓐劳。脉虚数正合冲脉气逆、脾胃两伤、虚热内扰之病机，故治以通补奇经、扶脾理肺。", ["虚", "数"]], "14877": ["病机", "左脉细数，细为营阴不足、数为虚热，故曰「营阴亏也」；右脉细软，软主气虚，故曰「脾气虚也」。产后劳碌，气血伤而不复，身常内热、心荡若嘈，皆营虚脾弱、虚热内生之候。两脉分候左右，正点出营亏与脾虚并见之病机，久延虑成劳损。", ["细", "数", "软"]], "14878": ["病机", "脉弦搏，弦主肝、搏为劲急有力，故断「肝阳有上亢之象」。小产后恶露即止，瘀血结块，胞络上系心胞，血凝动火、火炽生风，故心神妄乱、言语如癫。脉弦搏示肝阳亢盛、瘀热化风，防其吐血。治以化瘀为先，清火化痰为佐，脉象正应此病机。", ["弦", "搏"]], "14879": ["预后", "脉洪而荒，洪为阳盛气浮，荒则脉形散乱无根，合「虚阳外越」。产后痉厥不醒、恶露稀少、面赤身温，乃肝风炽张、营虚气耗，虚阳浮越于外，冷汗遂出。脉洪而荒正是阴竭阳浮、胃气将败之象，故虑其厥而不返，属危重之预后判断。", ["洪"]], "14880": ["其他", "原文未识别出脉名，仅以“脉荒者，乱也”释脉荒为乱，并疑为杜撰。其病机为虚风挟痰上逆，故治以化痰降火、冲入童便。脉象描述模糊，无法提取具体脉素，主旨属对脉象术语的考辨，非论病机或主病。", []], "14881": ["病机", "脉大稍软，较前之脉大而减，示邪势稍退而正虚未复。面赤稍退、恶露稍多，为瘀浊得下；然厥仍不醒、舌灰黄、沃涎沫、不食，乃营虚气滞、胃虚浊泛，清阳不升，浊阴不降。脉大软为气虚湿浊内蕴之象，故须温通化浊以冀阳回厥醒。", ["大", "软"]], "14882": ["病机", "脉沉而寒热，沉主里，寒热为邪正相争。产后淋雨，水寒之气从毛窍入骨节，内舍于肾，外达太阳阳明，故腰疼头痛、遍体机关不利。邪留胃肾则纳少恶心、寐少恐惧；头痛甚汗出为太阳表虚。脉沉说明寒邪内侵，病位在里。", ["沉"]], "14883": ["病机", "脉数舌红，数主热，舌红为阴伤。疟痢三年，脾胃元气大伤，腹满足肿、小溲短少，为脾虚不运、湿浊内停。前投升阳益胃热势略减，今脉数舌红示阴液亦损，虚热内扰。童稚阴亏，病延日久，故拟补益脾阴兼化浊，防夏令增剧。", ["数"]], "14884": ["病机", "诒按指出小儿虚证以脾胃为主，然脉数舌红，数主热、舌红主阴伤，说明阴液亦损。脾胃虚弱日久，化源不足，虚热内生，故脉数；阴液亏耗，故舌红。治疗当于补脾之中稍参养阴，以顾护阴液，不可纯用温燥。", ["数"]], "14885": ["病机", "左脉弦洪，右部细小。弦洪为肝阳上亢、火势极盛之象，故脑疽坚肿未消、脓水不多、腐肉未化；右细小示气虚下陷，大便艰结、小溲频数。高年气阴不充，肝阳无制，脓水腐肉无朝生暮长之功，势将渐蹈陷机，故治宜镇肝抑火兼补托化脓。", ["弦", "洪", "细", "小"]], "14886": ["病机", "左脉弦洪不减，酉戌之交烦躁不安，为心火太旺、肝阳未镇。脓水较多终未能畅，根盘稍和究未化，示火势仍盛，乘气虚有内陷之虞。受补能寐，说明正气尚可扶。弦洪脉持续，主火盛未衰，故拟清心化热与补托相辅，防其内陷。", ["弦", "洪"]], "14887": ["病机", "脉左部略平，较前弦洪减，示肝阳稍戢；然发际坚肿火色未退，脾胃不思饮食，日中至黄昏痛势最甚，为阴火上乘、邪火愈炽。昨用补托脓水甚多，正气得扶毒便外出。脉略平而火未清，故当运调胃气、参镇火之品，备正防变。", ["平"]], "14888": ["病机", "左脉洪数较前日平和，说明脓水淋漓、毒从外泄，小溲通畅、火从下降，面赤火升得平、痛势亦减。洪数为火热亢盛之象，今较平则升降各司其职、气盛上下咸宜，属补托之助见效，故为佳兆，但仍宜增不宜减。", ["洪", "数"]], "14889": ["病机", "脉情亦和，与神气清朗、胃气亦开相应，示补气顾阴之剂得效。然丑寅之际似梦非梦、语言错误，乃心营内虚、相火上乘，脉和而症见神志不宁，说明整体脉气虽和，阴分仍虚，故主张阳分补气、阴分养阴，因时服药。", ["和"]], "14890": ["病机", "原文未识脉名，统观脉证：外则痛止火退、脓多腐未脱，内则舌苔灰浊、胃气不开，烦闷、腹痛干呕而呛、时觉模糊。此脏腑不和、湿热乘虚而入，病后虽宜补，然湿热蒸郁、弱体易累，故暂去参耆，从胃腑立法，六腑以通为补。", []], "14891": ["病机", "原文未识脉名，今晨诊脉左三部较和于昨、右关亦旺，与烦闷顿除、脘中空爽、口味大和相应，示从胃立法应手。久病调补脾胃则升降自调、生长之机自复；惟下午精神怯、神情恍惚，乃真阴大伤、夏至阴气大剥，因时而动，故仍从胃立法而兼柔润顾阴。", []], "14892": ["病机", "右关和缓有神，故饮食知味、梦寐亦安；左脉之弦亦和于昨，弦为肝象，今转和缓，是波平浪静、休养生息之候。脉象由弦转和，说明肝气渐平、脾胃渐复，此时宜慎劳动、节饮食，培植脾胃以扶初生之阴。", ["弦", "缓"]], "14893": ["病机", "原文未识脉名，惟言脉亦不调。腐脱眠食安，病已向愈；然未申之交升降失调，脘闷自汗、不能偃卧、脉不调，舌苔浊厚带灰，是胃中湿浊分明。高年气弱、当湿令大行，午后阳中之阴为阳劫而阴益弱，浊气当权反劫正气，即世俗所谓痧胀。", []], "14894": ["病机", "脉静神怡，与随补随通、湿去正复后安适相应。前从湿热一边著手，补中寓通，合东垣之法，夏秋尤宜。脉静示邪退正安，阴生之节已在目前，故补气调胃、和平其制，无事求奇，正合病后调补之道。", ["静"]], "14895": ["病机", "左脉带弦、右部略软，弦主肝脾不和、气机郁滞，软示胃气偏弱。便溏数次为脾气不升，精神稍倦、腹中隐痛，必冷积留于肠间。幸纳食尚多、胃气尚和，然高年大病之后不宜多降，故用参苓白术散加味，升健脾运兼化冷积。", ["弦", "软"]], "14896": ["病机", "左脉弦象稍减，说明肝木郁结之势已缓，而右脉有神，胃气尚存。前段言诸气𪱥郁皆属于肺、诸腹胀满皆属于脾，今便溏腹痛虽属脾虚，必有积滞，温消后症减而弦象亦减，正合脾病及肝、木郁渐舒之机，故论治仍从脾胃著手，去温消之品以善后。", ["弦"]], "14897": ["病机", "原文以脉散等言其阴火不敛、精不蕴藏。太太八旬操持耗阴，阴不足则孤阳少所维系，睡后奔走无定、目见奇异，皆阴不敛阳、精不内守之象。脉散正是阴亏阳浮、根本失摄之征，故虽云不足宜补，而舌苔浊厚胸痞，补阴又有不易，须权宜施治。", ["散"]], "14898": ["预后", "脑疽三候，根盘板滞、脓水清稀、神识时糊，脉虚细数。虚细为正气大亏，数则毒热未清而正不胜邪，故断为正虚不能化毒、毒反陷入于里。脓清神糊与虚细数脉相应，预后堪虑，姑用扶正托毒以望转机，属险候之辨。", ["虚", "细", "数"]], "14899": ["病机", "右脉软弱，主胃气残惫。脑疽三候余，顶塌根散、脓少木肿，皆气虚不能引血化腐托毒外出之象。右脉候脾胃，软弱则元气不承，脓腐难期，深恐阳变为阴。原文强调外疡须赖元气承载，黄耆托毒正为此设，脉软弱即其凭据。", ["软", "弱"]], "14900": ["病机", "对口疽旬日，误用补托致火毒弥漫中宫，痞闷呕恶。脉滑数、舌白腻，皆湿热壅遏之象。滑主湿痰壅盛，数主热郁于里，与营气不从、逆于肉里之痈肿病机相合。实而补之反助邪威，故用苦辛宣达，冀表里宣通以免邪陷神昏。", ["滑", "数"]], "14901": ["病机", "玉枕疽逾三候，脓泄不畅、腐肉未脱、大便溏薄，脉形迟细。迟细为元气虚寒、气血不足之征，正虚则不能托脓外透、腐肉难脱，便溏亦脾阳不运之象。脉症合参，属虚寒托毒无力，故法以补托，冀脓透腐脱。", ["迟", "细"]], "14902": ["病机", "二诊玉枕疽及四候，根稍突、脓稍透，而脉仍迟细，原文直断元气亏。迟细主阳气衰微、营血不足，脓虽稍透而脉不复，说明根本未复，托毒之力仍弱。故温补法理无违，以迟细为虚寒之凭，温补即所以助元气、促脓腐。", ["迟", "细"]], "14903": ["病机", "本段未识脉名，以症测机。先痛后肿，自气分伤及营分，咳逆头胀，余邪尚留隧道而未全入络。肺主一身气化，气机利则关节利，气机痹则脉络俱痹，故治病大纲在从事气机。虽无脉象可凭，而气分先病、营分继伤之机已明，治当宣畅气机。", []], "14904": ["病机", "脉来弦数右大，弦主风温，数主热，右大示邪入胃中。风温兼夹痰食，已入胃中，化热伤津，故舌苔微黄。脉数右大说明热势渐盛，有化燥神昏之虞，与肿势愈甚、恶寒已除相应，提示表邪已解而里热转盛。", ["弦", "数"]], "14905": ["病机", "脉沉按之而实，沉主里，实主邪结。温邪外郁化火而内结，故见头面滋水淋漓、五日不大便、脘痞苔黄。脉沉实说明邪热与燥屎内结于阳明，当乘势逐之，与原文「温邪外郁化火而内结」相应。", ["沉", "实"]], "14906": ["病机", "脉迟细，迟主寒，细主阴亏。阴亏络空，寒邪袭入，盘踞不出，故颊车坚肿、牙关紧合不开。脉迟细说明正虚寒凝，久则难驱化，治当温通散寒中搜其锢结之邪，与「阴亏络空，寒邪袭入」相应。", ["迟", "细"]], "14907": ["病机", "脉象郁涩，涩主气滞血瘀。肝胆郁火凝结成痰，腮颊硬肿、牙关不开，此骨槽痰也。脉郁涩说明气失利畅，痰火郁结难化，故药力不易见效，宜自怡悦为要，与「气失利畅」相应。", ["涩"]], "14908": ["病机", "脉形虚数，虚主血虚，数主热。牙龈肿而不坚、腐而不溃，日晡微热，此血虚肝郁，木火上升，略兼外感。脉虚数说明营血不足而虚热内生，表邪已退，今拟养营熄风潜阳为治，与「血虚肝郁，木火上升」相应。", ["虚", "数"]], "14909": ["病机", "诊脉弦数，弦主肝胆风阳，数主热。素禀阴亏火亢，风阳上扰，近感风温引动肝胆之阳，挟痰入络，阻袭少阳阳明，故牙关坚急不开、左颊结块焮肿。脉弦数说明厥阳、痰浊、风温三者杂合为病，与怀孕八月胎气宜安相应。", ["弦", "数"]], "14910": ["病机", "脉细弦，细主正虚，弦主寒痛。牙咬痈色白而脉细弦，身微寒热，此寒痰阻于关窍，略感风邪所致。脉细弦说明寒痰凝滞、风邪外袭，治以辛温解散，与「寒痰阻于关窍」相应。", ["细", "弦"]], "14911": ["病机", "脉极细，细主阴亏。少阴肾水不足，阳明胃火有余，牙宣出血，晡时微寒壮热，而其脉极细，此素体之阴亏也。脉极细说明阴血亏虚不能充脉，当凭此论治，用景岳玉女煎，与「素体之阴亏」相应。", ["细"]], "14912": ["病机", "原文指出“脉细”可能为“素禀如是”，非必阴虚所致。脉细主气血不足或脉道不充，但此案强调须“见证确可据”方可“舍脉从证”，说明脉细在此非独主阴虚，提示病机需结合症候判断，不可仅凭脉断病。", ["细"]], "14913": ["病机", "脉虚主气血不足，结合“头眩，心嘈”，为肝虚风阳上逆之候。耳中深底生痈而脓从腭鼻出，痛在耳中，脉虚提示正气不足，肝血亏虚，风阳上扰，故从肝虚风阳上逆论治。", ["虚"]], "14914": ["预后", "脉数不扬，数主热，不扬为邪郁不达。喉疳腐烂而“眉心不开”，乃肺气内闭，热毒郁结。脉数不扬反映邪热内蕴而气机不畅，深虑喘厥之变，示病势危重，预后不良。", ["数"]], "14915": ["病机", "脉息太细，原文断为“素禀六阴，真阳不足”。喉痹由少阴君火合少阳相火上逆，病由内生。脉细主真阳不足，故用养阴降火化痰时须慎用清药，恐“阴未足而阳先伤”，提示病机为本虚标实。", ["细"]], "14916": ["病机", "脉不甚虚，饮食尚可，说明正气未大伤。痰疬由气郁而起，肝胆三焦之火循经上走，结成痰核。脉不甚虚提示病机以痰火郁结为主，正虚不著，故收功虽难，尚可专从痰火论治。", ["虚"]], "14917": ["病机", "脉实能纳，说明胃气尚强，正气未衰。此病与失营证相类，脉实提示痰火内结而正能抗邪，故用药专从痰火著想，攻邪有据。脉实在此主邪实而正不虚，为可攻之征。", ["实"]], "14918": ["治法", "原文未识脉名，专论治法。方以六味滋肾、生脉保肺，合柴、芍清肝，立方周到。又拟去温肝之萸肉，加清胆之芩、茹，体现从肾、肺、肝、胆调治，侧重清肝利胆化痰，属治法讨论。", []], "14919": ["病机", "原文未识脉名，论瘰疬病机。女子以肝为先天，肝血亏则木火易炽，木火炽则津液燥结，阻于经脉而成瘰疬。瘰者累累如贯珠，疬者历久不易愈。逍遥散加减主之，示病机为肝血亏虚、木火燥结。", []], "14920": ["病机", "脉数食少，乃脾胃气虚，虚热内生之象。薛营虚肝郁，颈结痰核，溃者未敛，坚者不消，又见呕恶，皆因脾胃虚弱，运化失职，痰湿凝聚。脉数非实热，乃气虚发热，故慎勿漫进苦寒消痰之药，当以益气养营为主，冀呕止热减。", ["数"]], "14921": ["病机", "严冲脉隶于肝肾，女子以肝为先天。及笄之年，癸水未通，颈项虚痰累累，骨蒸晨汗，血枯肝郁，劳瘵之根萌也。逍遥散养血润之、培土生之，佐柴胡升春生之气，令木气敷荣，即木郁达之之义。必得天癸通行，病根斯拔。", []], "14922": ["病机", "脉形小弱带数，小弱为虚，数为火亢。两目内眦肉胀红丝，水亏火亢；左耳上结核坚硬色不变，症属虚痰。虚火炼液成痰，痰凝络脉，故用壮水制阳，兼以咸降，使水足火降，痰自消。", ["小", "弱", "数"]], "14923": ["预后", "脉空虚，色白不泽，素患瘰疬梦遗，下虚已久。今腹胀如鼓，上气喘逆，兀坐不能睡卧，此水泛土溃以凌金，下虚上实之候。水愈深火愈衰，欲利水先温火，欲归气必摄阴。然病深气竭，药难奏效，预后棘手。", ["虚", "空"]], "14924": ["病机", "营行脉中，卫行脉外。体肥湿胜之人，卫恒虚冷，营多盛热。疡发背脊，内脓已结，外腐未透，营火极炽，卫弱失于敷布，不能引血化腐载毒外出，渐显内陷之机。非温不能助卫阳，非清不能解营热，血实宜决之，气虚宜掣引之。", []], "14925": ["预后", "疡发极大，脓去过多，精神惫败，脉数无神，脾胃困顿，其势甚险。脉数无神乃正气衰败、虚阳外浮之象，脓去过多则气血耗伤，脾胃困顿则化源不足，正虚毒陷，故亟宜扶正托毒，犹恐鞭长莫及。", ["数"]], "14926": ["病机", "曲运烦冗，心阳暗亢，气血怫逆，乃生大疽。诸痛痒疮，皆属心火，火毒有虚实之分。羌防升散、黄耆固气，适足以增炎固火，火毒不得外泄，反陷入营，致烦躁，脉来太旺，非高年所宜。脓稀根硬，烦渴干哕，虑有火陷之险。", []], "14927": ["主病", "肾俞漫肿色白，脉虚微热，此肾俞发也。属三阴亏损，湿热入络，气血凝滞而生。脉虚微为三阴不足，微热为湿热内蕴，正虚邪滞，故最为奄缠。姑与消散法，以图缓效。", ["虚", "微", "热"]], "14928": ["预后", "脉弱无神，是精血衰微、络脉空虚之征。溃脓三月虽暂愈，然每交节令必发寒热，面色萎黄，脓水淋沥，暗损其津，正虚不能托邪。脉弱无神说明元气难复，外证虽似向愈而内损已深，故曰功尚难恃，预后堪忧，拟补益真元以治内。", ["弱"]], "14929": ["病机", "两脉洪大转数，为湿火入络、热邪鸱张之象。洪大主热盛气分，转数则热势更急，故见手外腕及足跗指肿痛而红。脉洪大数说明络中热壅，火性急迫，与局部红肿热痛相应，故拟清络热方法，清其入络之湿火。", ["洪", "大", "数"]], "14930": ["病机", "脉左弦数，右濡弱，左弦数应肝火横逆，右濡弱应土虚。肝有邪流于两胁，故乳房结核、缺盆阻结；肝邪侵胃侮肺，故潮热、气逆、咳嗽痰多、胸痹纳少。脉象示肝旺脾弱、木火刑金，热久津伤，故柔肝顾阴为先，不当纯用消肿。", ["弦", "数", "濡", "弱"]], "14931": ["病机", "原文仅言脉不和，未列具体脉象。营枯无以养络，络脉不和而成木硬，乳房结核名乳癖，兼遍体肢麻掣痛。脉不和反映营血亏虚、络脉失养，木郁化结。故非养营无以生血，非泄木无以化结，并须开怀胸襟以助药力。", []], "14932": ["病机", "脉拘急，是阴血亏、肝气郁、筋脉失荣之征。木来乘土，乳房结核；血不荣筋，故筋脉拘急。脉拘急说明筋脉失养而挛缩，症虽外疡实从内生，非攻消可解，法当养血荣筋，使血充筋柔则拘急自缓。", ["急"]], "14933": ["病机", "脉弦滑数，弦主风木，滑主痰，数主火。风温久恋，化火蒸痰，灼金耗液，故咳嗽月余、痰腥带血、气升呛逆。脉弦滑数正合风温痰火壅肺之机，证属肺痈，非轻候，示热痰壅盛而肺络已伤。", ["弦", "滑", "数"]], "14934": ["预后", "脉形弦硬，为木火亢逆、肺气失降之象。咳逆痰腥带血，面色暗晦，说明肺痈未愈而肝木上逆乘金。弦硬之脉示邪势劲急，故防加喘急，预后须慎。此段重在提示脉象转硬、面晦为病情进展之兆。", ["弦", "硬"]], "14935": ["预后", "咳唾臭脓而脉数，肺痈已见脓后热不退，是虚火之数。不欲食、时寒时热，示火克金而土虚不能生金，是谓重虚。脉数在此非实热，乃虚火浮越，故曰恐难治，预后不良，强调脓后脉数不退、胃气衰败之危。", ["数"]], "14936": ["病机", "脉数而虚，数为热象，虚为阴亏，合之则阴虚内热。咳吐臭痰三月，久咳伤肺，阴液耗损，故脉虚；虚热内扰，故脉数。面白无华、饮食渐减，乃肺病及脾，母病及子，脾土失运。肺失所恃，正虚邪恋，肺叶焦痿，故防成肺痿。脉症合参，主肺阴亏虚、脾肺两伤之病机。", ["数", "虚"]], "14937": ["预后", "脉数而虚，与前诊同，然面色由白转青晦，纳谷由减至大减，是木火乘金、金伤及土之象。数脉为火，虚脉为正伤，肝木之火上刑肺金，肺病及脾，脏气克贼，土败木贼。脉象未改而症候日进，正虚邪盛，故断为恐延不治，属预后不良之候。", ["数", "虚"]], "14938": ["预后", "脉洪数无神，洪数为热盛，无神为正气衰败，阴液大伤。舌绛、咳痰秽浊腥臭，热毒壅肺。引仲景“脉数大而虚为肺痿”，数大为热，虚为阴亏，肺阴耗竭则成痿。痈为实热可攻，痿为虚损难复，故曰痈犹可、痿则难治，脉无神示胃气将绝，主预后险恶。", ["洪", "数", "虚"]], "14939": ["病机", "脉来弱而数，弱为阴不足，数为阳有余，即阴虚阳亢、正虚邪恋之象。虚体著邪，留恋不化，肺失清肃则咳逆痰黏，胃津不足则纳少，邪热入络则季胁肿痛。瘦人阴亏，液涸可虑。日暮寒热、痛势加剧，为邪热酿脓之征。脉症合参，主气阴两虚、邪热逗留入络之病机。", ["弱", "数"]], "14940": ["主病", "脉数主热，怒则肝气上逆，血菀于上，章门结块硬痛，寒热并作，小便短少，皆肝经郁热、气血壅滞之象。章门为肝之募穴，结块硬痛属肝痈。数脉为热毒内蕴，热盛肉腐，故防其内溃咳吐脓血而剧。脉数在此主肝痈热毒壅盛之病机。", ["数"]], "14941": ["病机", "脉附骨极细而锐，细为阴血不足，锐为瘀热内结，附骨示病位深沉。右肋章门酸疼略肿，食少便溏，面浮足肿，腰脊酸痛，乃脾虚湿盛、湿热瘀伤之候。脾主运化，湿热瘀阻脾络，日久正虚胃弱，故症属脾痈。脉细而锐，正虚与瘀热并见，恐不克支持。", ["细"]], "14942": ["治法", "脉虚形瘦，虚为正气不足，形瘦为阴血亏耗。胃脘生痈，初起寒热，延今四十余日，晨必泄泻无度，是中气大虚、脾失健运，不胜攻消之任。脉虚示正虚为主，故与内托法扶正托毒。倘仍作泻，则脾土败绝，难以挽回。此段以脉虚定治法，主内托扶正。", ["虚"]], "14943": ["病机", "脉来左虚弱，右弦数。左脉候血，虚弱为病后气虚不复、阴血不足；右脉候气，弦数为湿热壅滞。湿热踞于胃脘之络，胸高坚突不移，此肚角痈也。厌谷纳少，为脾土受困。脉症合参，主湿热壅滞、气虚不复之病机，故用扶土和中、扶正却邪之治。", ["弱", "弦", "数"]], "14944": ["病机", "原文未载脉象，以脘下结肿、按之痛不可仰为据，断为痰气交凝、阻塞脉络。痰气互结则络脉不通，不通则痛而拒按；结聚日久，气血壅遏，有化腐成痈脓之虑。故治法以和中化痰为主，兼攻逐络中瘀滞，使痰化气行、瘀去络通，则肿痛可消而痈脓可免。", []], "14945": ["病机", "脉形郁数，郁者气机不畅，数者邪热内蒸。伏暑之邪挟肝郁，气痹血阻，故脘左板痛、寒热不时。暑热郁于内则脉数，肝气郁结则脉形不舒；气血痹阻于脘左，结聚不散，势有肚角痈之虑。治以和解宣络，使暑透郁开、气血流通。", ["数"]], "14946": ["主病", "脉数身热，数主热盛，热盛则肉腐，故断为内痈已成。当脐肿硬名曰脐痈，热毒壅聚脐部，脓成而身热脉数，是邪正相争之象。若不从脐中溃出，恐热毒内走大肠，变为盘肠之险；芽孩脏腑娇嫩，犯此非轻，故特申其危。", ["数"]], "14947": ["预后", "脉细食少，细为气血不足，食少则化源匮乏。肠内痈脓将足而正气已伤，脓成而正虚，无力托毒外溃，故脉细食少。治以托里，意在补益气血、扶正托毒，冀其脓从外溃为妙；若正不胜邪，脓毒内陷，则预后堪忧，此段重在审脉以判转归。", ["细"]], "14948": ["病机", "脉数寒热，数主热，寒热为邪正交争。湿热阻于肝络，右少腹高突成痈，绵延匝月而脓脚已成，是湿热壅遏、营血瘀滞化腐。脉数示热毒尚炽，寒热示邪正交争；舌苔灰腻，湿热内蕴之征。故法当攻营逐络以消痈，兼和解以透达。", ["数"]], "14949": ["病机", "弦数之脉，弦主痛、主郁，数主热。疡脓不尽，饮食不节则寒热复作，弦数之脉与灰腻之苔减而复来，说明余毒未清、中宫壅滞，热与湿浊复聚。脉证相应，皆由脾胃不和、脓毒留恋所致，故仍以和解中宫为治，冀热退谷增则正复邪却。", ["弦", "数"]], "14950": ["预后", "脉细汗多，细为阴血不足，汗多为气随液泄。阳邪入于阴经，欲结外疡，而年逾六旬、精神疲惫，正虚不能托邪。舌干掯、小便赤痛示阴伤火亢，大便溏泄示脾弱；脉细汗多则气血两亏，恐不克支持而生晕厥，症势险重，故备商以图万全。", ["细"]], "14951": ["病机", "脉细而便泄，细为阴血亏少，泄为脾阳不振，皆阴象，与横痃疽属阴、由五脏而生相应。疽色不红、肿不高、痛著于骨如针刺，是阴寒凝滞、深着筋骨。然舌焦红干涸、小溲赤痛，又属津亏火亢，阴中夹阳、寒热两歧，高年犯此，攻补两难，故称棘手。", ["细"]], "14952": ["病机", "脉细主气血两虚、阴津大亏。原文谓脉细、便溏、多汗皆属虚寒之象，舌干苔掯为阴津大亏，饮食少纳为脾胃极弱，故细脉在此反映高年气血虚衰、脾胃虚弱、阴津耗损之本虚病机；而小溲茎中痛、尿色浑浊则属湿热内瘀之标，脉细不足以显湿热，提示正虚为主、兼挟湿浊。", ["细"]], "14953": ["病机", "脉缓而小，缓主湿、小主气血不足。原文谓湿毒流注，湿得热而蔓延，循经窜络，病在阳明，口苦带腻，脉缓而小，断为湿胜于热、热伏湿中。缓脉应湿邪偏盛，小脉示正气不充、湿阻络脉，故脉不洪数而缓小，正合湿重于热、热为湿遏之病机。", ["缓", "小"]], "14954": ["病机", "脉细主气血不足、寒凝络脉。原文述寒邪入络，腿股酸痛漫肿，色白脉细，口不渴。色白、不渴为寒象，脉细示寒邪客于络脉、气血运行不畅而正虚，故当温散之，拟阳和汤法温阳散寒通络。细脉在此说明寒凝络脉、气血不充之病机。", ["细"]], "14955": ["病机", "脉洪主热盛、湿热相火亢盛。原文膝肿大、皮色不红、骨中如火灼之痛、脉洪、口腻、身热，断为湿热相火乘虚注于溪谷，症属鹤膝风痹。洪脉应火热内盛，与骨中灼痛、身热相应，说明湿热相火深注筋骨之病机，故称殊非小疾、极难速效。", ["洪"]], "14956": ["病机", "本段未识脉名，纯以症候论病机。原文谓疡脓后气血必虚，奔走烈日汗出招风，风与热毒舍于皮肤脉络，秋凉外束热郁皮中，遍体搔痒，面黑而浮、少腹略满，奇痒时唇舌俱麻，为外风引动内风。经云面肿曰风，风行必燥，木胜克土，现为风癞，久防腹满，说明风热郁络、肝木克脾之病机。", []], "14957": ["病机", "本段未识脉名，以症论病机。原文述对口发于督脉，顶虽未起而根脚不散，乃半阴半阳之症，所虑年高气血已枯，不可不兼护托。说明疮疡虽未成脓，然根脚散漫属正虚毒滞、半阴半阳，年高气血枯竭则托毒无力，故治当护托兼顾，病机在气血已枯、毒滞难化。", []], "14958": ["病机", "脉数主热、主气血伤。原文痈生于耳，流脓多而气血伤，脉数，牙关不开。流脓多则气血耗伤，脉数示热毒未清、正伤而邪热犹存，牙关不开为热毒壅阻经络。数脉在此说明痈疡热毒内盛、气血已伤之病机，故用柴胡四物加减养血兼清少阳。", ["数"]], "14959": ["病机", "脉至细数无力，细主阴血不足，数主热，无力主虚。原文耳窍流脓数月，痛不减而脉细数无力，说明病久脓流耗伤肝肾之阴，阴虚生内热，兼少阳之火未清，故脉细数而无力。用归芍六味加减滋肝肾之阴兼清少阳之火，正合阴虚火旺、正虚邪恋之病机。", ["细", "数", "虚"]], "14960": ["病机", "原文未载脉象，从“不肿不痛”“无翳无肿无胬肉无红筋”排除外风与火邪，断为“肾水有亏，肝血不足”，视不明至夜尤甚正是阴血亏虚不能上荣于目之征；眼包宽纵又关脾气不运、络脉有亏，故病机属脾肾两亏、肝血不足，法当培补脾肾兼以养血，缓图固本。", []], "14961": ["病机", "脉见弦数，弦为肝脉、主肝郁阴亏，数为阳热亢盛之象。两目失明、右目风轮翳起、左目内障瞳神，皆肝开窍于目，肝阴亏虚不能涵木，则阳亢于上，虚火循经上扰目窍，故原文直断“肝阴亏而阳亢”，弦数正是阴亏阳亢并见之脉。", ["弦", "数"]], "14962": ["病机", "脉数主热，风轮起翳、气轮赤脉贯睛、泪多，为风热之邪闭结目络，气血壅滞而成。数脉示热邪内盛，风热相搏上攻于目，故原文谓“因风热闭结”；热势鸱张恐损及瞳神，则调治不易，脉数与赤脉贯睛、泪多之症相应。", ["数"]], "14963": ["病机", "右关候脾胃，脉至右关沉有力，沉主里、有力为实，示阳明里热实邪内结。黄膜上冲、热逼膏伤、视物不见，皆阳明余火不清、火性上升害目所致；曾患乳痈亦阳明热毒之征。阳明多气多血，实火宜清降，故曰“宜于清降”，脉症相合。", ["沉", "有力"]], "14964": ["病机", "原文未识脉名，然“左脉全无”是关键：左候血，脉全无示肝血亏极、血脉空虚；而左眼骤加肿痛、黑珠浑浊、泪出如糊，又属外邪壅盛。虚体而兼实邪，故断为“虚体实邪之恙”，养血之中佐辛温疏散，正合虚人夹邪之治。", []], "14965": ["病机", "右寸关候肺与脾胃，脉至右寸关较大，大脉主邪气盛实。气轮赤而风轮起翳，气轮属肺、风轮属肝，故断为“肝肺两经之邪”；寸关脉大示邪在表分、正气尚能抗邪，故曰“可清可散”，脉之较大与肝肺实邪相应。", ["大"]], "14966": ["病机", "左关候肝、左尺候肾，脉至左关尺较数，数主热。口舌糜烂、门齿下根为甚，齿属肾、龈属胃，而左关尺数示肝火偏旺、肾阴不足，虚火上炎熏灼口舌，故法宜清肝火、养肾阴，兼以凉解，脉数与口舌糜烂之症相合。", ["数"]], "14967": ["病机", "复诊口疳未增未减，而左脉数而有力，数主热、有力为实，示邪热仍盛而非虚火。更益头痛，乃又受风热之故，风热上扰清窍则头痛，热壅口舌则疳不愈。脉由前之“较数”转为数而有力，说明风热之邪增重，故当以清散风热为治。", ["数", "有力"]], "14968": ["病机", "六脉软弱，示正气虚衰、肾元亏败。牙疳碎烂色紫暗无神、舌滑带黑、下门齿脱落，皆肾经虚火上浮、骨中湿毒内蕴之象。脉软弱与虚症相符，故断为虚症之极重险者，治宜桂附导火归原，因外感时令而暂用六味壮水制阳。", ["软", "弱"]], "14969": ["预后", "复诊烂处色紫而泽稍明润，脉亦稍为有神，说明前投壮水制阳、兼却骨中湿毒已见效机。脉由无神转有神，是正气渐复、胃气未绝之兆，故预后较前为佳，然色仍紫暗，湿毒未净，尚需续治。", []], "14970": ["病机", "脉至得数，数为热为火，风火上炽，故牙龈碎烂。脉数与风火之症相应，火性急迫故脉数，治拟清疏以散风火。", ["数"]], "14971": ["病机", "脉至右大于左，右主气属阳明，左主血属肝肾。右大于左，示阳明湿化为火偏盛，而肝肾之阴不足。上下门牙龈脚碎烂色带紫暗，正合阴虚火旺、湿毒熏蒸之病机。", ["大"]], "14972": ["病机", "脉至沉弦，沉为气滞，弦为肝脉。症见牙龈腐烂形似翻花、左胁肋胀痛，起于抑郁，肝气郁滞、气血不畅所致，非时邪客感。故治宜怡情悦性、药饵不伤气血，切忌攻伐苦寒。", ["沉", "弦"]], "14973": ["病机", "六脉细弱，细为血少，弱为气虚，示正气不足。牙痈有脓而余肿不消，乃正虚无力托毒外出，故治以扶正为主，稍益清解，不可纯用攻伐。", ["细", "弱"]], "14974": ["病机", "脉至滑数，滑主痰湿，数主火热，左三部更甚，左属肝胆，火炽甚矣。木舌肿连咽喉，乃三焦火毒上攻，故急宜清三焦之火，用栀子金银花汤，明晨轻减方可得生。", ["滑", "数"]], "14975": ["病机", "脉虽细弱无力，似属虚象，然症见舌连左半咽喉肿痛，乃上焦风热挟痰，故当从症不从脉。细弱无力示正气不足，用药宜轻，重则犯及中下二焦，此示临证须脉症合参。", ["细", "弱"]], "14976": ["病机", "脉至弦数，弦主痛主郁，数主热盛，合示热毒壅聚、气血壅滞。舌痈而脉弦数，是火毒结于舌本、内脓已成之征，热盛肉腐成脓，故断为危险，急急清解以泄热毒，防其内陷。", ["弦", "数"]], "14977": ["病机", "左寸关浮数，浮主邪在表在上，数主热，寸关候上焦心肺，示燥火之邪郁于上焦。咽痛连牙龈、大便不解，是燥火内结、上攻清窍，故宜清降兼疏；辛温升提更助燥火，故明言忌之。", ["浮", "数"]], "14978": ["病机", "脉至细弱无神，细弱主气血不足，无神示正气虚馁。咽喉溃烂而脉不数不实，是气血亏虚、不能托毒生肌，非实火所致。故宜活血养血以扶生生之气，若投寒凉则更伤气血，溃烂难愈。", ["细", "弱"]], "14979": ["病机", "脉带浮数，浮主风邪在表，数主热，合为风热袭于上焦。风热上攻则咽痛头疼，脉症相应，故宜清散，使风热从表而解，不可妄用温燥或苦寒直折。", ["浮", "数"]], "14980": ["病机", "原文未识脉名，仅言色脉合参并无火象。咽喉碎烂而色脉不见火征，说明非实热壅盛，乃虚火上浮或气血失养所致。故清滋苦寒之药决不可投，恐更伤中气、遏抑生机，当从虚论治。", []], "14981": ["病机", "脉至弱而细，弱主气虚，细主血少，合示气血两虚。咽喉上腭溃烂而脉不实不数，是气血不足、疮面失养，非实火。故宜调养气血兼甘凉解毒，勿服苦寒以免伤生生之气。", ["弱", "细"]], "14982": ["病机", "色脉和参，脉和示无大邪大虚，并非重恙。咽如茅刺因勤于女红、肺气窒塞所致，属气机不畅而非实火虚火。故一切偏寒偏热之药勿投，恐扰其平和之气，调畅肺气自可向愈。", ["和"]], "14983": ["病机", "右寸关带数，右寸候肺、右关候脾胃，数主热。素有肝气，久服温燥治痛治呕之药，劫伤肺液，虚热内生，故咽如炙脔而右寸关带数。宜清金保肺缓缓图治，苦寒亦不相宜，恐更伤肺液。", ["数"]], "14984": ["病机", "脉至浮数有力，浮主邪在表，数主热，有力为实，合示风热之邪外袭、正气尚充，故断为风热有余。咽喉左半腐烂乃风热上攻、腐灼肌膜所致，脉证相符，故可清可散，以疏风清热为治。", ["浮", "数"]], "14985": ["病机", "脉至似有若无，是气滞络瘀、脉道不畅；左关隐隐带弦带数，左关候肝，弦为肝郁，数为阳亢，故断肝郁气滞、厥阳亢。络瘀气滞则脉不流利，咽喉右半络脉红紫、食下硬痛，正合“一阴一阳结为喉痹”之旨。", ["弦", "数"]], "14986": ["病机", "原文未识脉名，仅言“色、脉已亏”，是色泽与脉象皆见虚象。咽喉碎烂甚于右半，虽有实邪而日久正伤，非近感风火可比。只用疏解则耗散已亏之正，故必兼清补，示久病虚实夹杂、正虚邪恋之病机。", []], "14987": ["病机", "脉至浮弦带滑，浮为邪在表，弦主痛、主肝，滑为痰湿，合示外邪夹痰。咽痛色如秋海棠叶背红丝绊满、肩背怯寒，是邪郁肌表；平素阴亏，房欲后受邪，正虚邪凑，故宜清上实下，兼顾下元。", ["浮", "弦", "滑"]], "14988": ["病机", "脉至带数，数为热，咽痛甚于左半，左属心肝，故断心阳肝火上亢。火性上炎，灼于咽喉则痛，脉数正是火热内盛之征，与心阳肝火亢逆之病机相应。", ["数"]], "14989": ["病机", "脉至浮大，浮主表邪，大为热盛邪实。去冬喉痈得脓后肿痛不除，是余邪未清；近因感冒呛咳见红，脉浮大，示风热复袭、热伤血络。故先清散，续商调理，并虑其转为喉痈、喉风。", ["浮", "大"]], "14990": ["病机", "脉浮而不甚流利，浮为邪在表，不甚流利是热郁于里、气血不畅。咽喉漫肿无形、痛甚于左，乃风寒束缚于外，热郁于里不得透达，遂成喉风。故拟散之中兼清，外解风寒、内清郁热。", ["浮"]], "14991": ["病机", "脉至右寸浮数，右寸候肺，浮主风邪在表，数主热，合示风热上感于肺。咽喉碎烂甚于右，是风热循肺经上攻、腐灼咽喉所致，究属风热上感，故先为清散，以疏风清热为治。", ["浮", "数"]], "14992": ["病机", "脉浮为风寒在表，迟为寒邪凝滞，气血被遏。原文“牙关紧急，腮颐作胀”乃风寒袭少阳、阳明经络，经气不利所致。浮迟并见，说明邪在表而寒性收引，故治宜清散，切忌寒遏，以免冰伏邪气。", ["浮", "迟"]], "14993": ["病机", "右关候脾胃，脉数主热。原文“面颊浮肿”为少阳阳明风热之邪壅盛，循经上攻。右关较数，说明风热之邪已入阳明，胃热偏旺，故治宜清之散之，使风热从表里分消。", ["数"]], "14994": ["病机", "左脉弦主肝郁，滑主痰凝。原文“颧疽色紫木硬无情，得脓不化”乃肝郁气滞、积久痰凝，结于局部。弦滑并见，说明气郁与痰浊交阻，非实火可比，故药忌苦寒，须怡悦情怀缓缓图治。", ["弦", "滑"]], "14995": ["病机", "原文“脉来少神”为纯描述，未出具体脉名。面无华色、脉少神，显系气血亏虚。颐颔结核、牙龈碎烂，乃虚火上浮或气血不荣所致，不可作寻常外症肆用寒凉攻伐，以免更伤生生之气。", []], "14996": ["病机", "右脉洪滑而大，洪主热盛，滑主痰，大主邪实。原文“此为痰火有余”，痰火循经上扰，故见鼻衄、颈侧之疬。洪滑大并见，说明痰火壅盛于阳明，属实热有余之象。", ["洪", "滑", "大"]], "14997": ["病机", "脉滑数而有力，甚于右关，右关候脾胃。滑主痰，数主热，有力为实。原文“颏下疬生累累”，乃痰火有余之象，结于颈颏。滑数有力说明痰火实邪壅盛，非虚证可比。", ["滑", "数"]], "14998": ["病机", "左三部浮弦带数，浮为虚阳外浮，弦主肝郁，数主热。原文“产后而起，面色萎黄，热甚于夜”，显系肝肾阴亏，肝阳上亢，痰随火升，凝炼成颈痰。因虚致实，故法当育阴制阳，兼咸软坚，不可清散攻消。", ["浮", "弦", "数"]], "14999": ["病机", "脉来艰涩，涩主气滞血瘀、痰凝阻络。原文“木郁不舒，颈左结核，按之棉软”，乃肝气郁滞，痰浊凝聚而成。涩脉说明气机不畅，痰凝络阻，故宗木喜条达法，疏肝解郁以化痰。", ["涩"]]});